# ── Forex-Factory News-Kalender (öffentlicher Wochen-Feed, gecacht) ──
# FF hat keine offizielle API, aber einen öffentlichen JSON-Feed pro Woche.
# Wir proxien + cachen serverseitig (30 min), damit der Browser weder CORS noch
# Rate-Limit trifft. Nur USD-Events werden durchgereicht.
_news_cache = {"ts": 0, "data": None, "ttl": 30 * 60, "fehl_bis": 0.0}
_news_lock = threading.Lock()
NEWS_TTL = 30 * 60
NEWS_TTL_OHNE_NAECHSTE = 5 * 60      # nur nextweek fehlt: liefern + cachen, aber bald neu versuchen
NEWS_PAUSE_NACH_FEHLER_S = 120      # thisweek gescheitert: so lange nicht neu bei FF fragen (sonst holt jeder Tab-Aufruf neue 429)
NEWS_ALARM_NACH_S = 2 * 3600         # thisweek so lange am Stück gescheitert → einmal 🟠 (nur bei aktivem Funded-CFD-Planer)
FF_URLS = [
    "https://nfs.faireconomy.media/ff_calendar_thisweek.json",
    "https://nfs.faireconomy.media/ff_calendar_nextweek.json",
]
_news_regel = {"at": 0.0, "an": True, "aktiv": False}
_news_fehl = {"seit": 0.0, "gemeldet": False}


def news_antwort(ok_diese, ok_naechste, events, alt, now):
    """REIN RECHNEND (testbar): NEWS-REGEL FUNDED CFD (30.10.2026, S8 8427eda9 — Funded-CFD-Starts sperren rund um rote USD-News, leerer
    Kalender = fail-closed im Tab). Vorher cachte ein Abruf, bei dem beide FF-URLs ≠ 200 lieferten (429), {"events": []} 30 min als frisch.
    → (payload, http_status, cache) mit cache = (payload, ttl_s) zum Schreiben oder None (nicht schreiben).
    thisweek nicht ok: alter Cache → der, mit unvollstaendig true (fetched unverändert, nicht überschreiben); sonst 502 ohne Cache.
    nur nextweek nicht ok: liefern + cachen mit kurzer TTL, unvollstaendig false. Beide ok: wie immer, unvollstaendig false."""
    if not ok_diese:
        if alt is not None:
            return dict(alt, unvollstaendig=True), 200, None
        return {"error": "News-Kalender (diese Woche) nicht lesbar", "events": [], "unvollstaendig": True}, 502, None
    payload = {"events": list(events or []), "fetched": now, "unvollstaendig": False}
    return payload, 200, (payload, NEWS_TTL if ok_naechste else NEWS_TTL_OHNE_NAECHSTE)


def _news_regel_lesen():
    """funded_cfd_plan_regeln.news_regel (60 s gemerkt) → (an, planer_aktiv). Lesefehler / Spalte fehlt = an (Regel bleibt an)."""
    if time.time() - _news_regel["at"] < 60:
        return _news_regel["an"], _news_regel["aktiv"]
    an, aktiv = True, _news_regel["aktiv"]
    try:
        z = (sb_select("funded_cfd_plan_regeln", {"select": "aktiv,news_regel", "id": "eq.1"}) or [{}])[0]
        an, aktiv = z.get("news_regel") is not False, bool(z.get("aktiv"))
    except Exception:
        pass
    _news_regel.update(at=time.time(), an=an, aktiv=aktiv)
    return an, aktiv


def _news_fehl_merken(ok_diese, now, planer_aktiv):
    """🟠 einmal, wenn thisweek > NEWS_ALARM_NACH_S am Stück scheitert und der Funded-CFD-Planer aktiv ist (ein Ort statt je PC-Tab)."""
    if ok_diese:
        _news_fehl.update(seit=0.0, gemeldet=False)
        return
    if not _news_fehl["seit"]:
        _news_fehl["seit"] = now
    if planer_aktiv and not _news_fehl["gemeldet"] and now - _news_fehl["seit"] > NEWS_ALARM_NACH_S:
        _news_fehl["gemeldet"] = True
        try:
            alarm_senden(2, "news_kalender_fehlt", "News-Kalender fehlt — Funded-CFD-Starts gesperrt",
                         f"Forex-Factory diese Woche seit {int((now - _news_fehl['seit']) // 60)} min nicht lesbar — die News-Regel sperrt "
                         "Funded-CFD-Starts (fail-closed), bis der Kalender wieder da ist.")
        except Exception as e:
            print(f"[news] ⚠️ Alarm: {type(e).__name__}: {e}", flush=True)


@app.route("/news/calendar", methods=["GET", "OPTIONS"])
def news_calendar():
    if request.method == "OPTIONS":
        return "", 200
    now = time.time()
    regel_an, planer_aktiv = _news_regel_lesen()
    with _news_lock:
        if _news_cache["data"] is not None and (now - _news_cache["ts"]) < (_news_cache.get("ttl") or NEWS_TTL):
            return jsonify(dict(_news_cache["data"], news_regel=regel_an))
        alt = _news_cache["data"]
        if now < (_news_cache.get("fehl_bis") or 0):
            p, st, _c = news_antwort(False, False, [], alt, now)
            return jsonify(dict(p, news_regel=regel_an)), st
    events, ok = [], []
    for url in FF_URLS:
        gut = False
        try:
            r = requests.get(url, timeout=12, headers={"User-Agent": "Mozilla/5.0 (Prophos)"})
            daten = r.json() if r.status_code == 200 else None
            if isinstance(daten, list):
                gut = True
                for ev in daten:
                    if not isinstance(ev, dict) or str(ev.get("country") or "").upper() != "USD":
                        continue
                    events.append({
                        "id": ev.get("id") or (str(ev.get("title")) + str(ev.get("date"))),
                        "title": ev.get("title"),
                        "country": ev.get("country"),
                        "date": ev.get("date"),
                        "impact": ev.get("impact"),
                        "forecast": ev.get("forecast"),
                        "previous": ev.get("previous"),
                    })
        except Exception as e:
            print(f"[news] ⚠️ {url.rsplit('/', 1)[-1]}: {type(e).__name__}: {str(e)[:120]}", flush=True)
        ok.append(gut)
    _news_fehl_merken(ok[0], now, planer_aktiv)
    payload, status, cache = news_antwort(ok[0], ok[1] if len(ok) > 1 else True, events, alt, now)
    with _news_lock:
        if cache:
            _news_cache.update(data=cache[0], ts=now, ttl=cache[1], fehl_bis=0.0)
        elif not ok[0]:
            _news_cache["fehl_bis"] = now + NEWS_PAUSE_NACH_FEHLER_S
    return jsonify(dict(payload, news_regel=regel_an)), status

# ── Futures-Kurse NQ / MNQ (30.08.2026, Finns Wunsch „NQ-Live-Stand ablesen") ──
# Quelle ist der oeffentliche Yahoo-Chart-Endpoint: kein Schluessel, kein Konto,
# CME-Futures unter NQ=F / MNQ=F. Warum ueberhaupt ein Proxy: Yahoo schickt
# keine CORS-Header, ein direkter fetch aus dem Browser scheitert also — und
# ueber app.py greift derselbe Weg auch vom Handy, ohne dass ein PC laufen muss.
#
# EHRLICHKEIT ZUR VERZOEGERUNG: Yahoo liefert CME-Futures fuer Gratis-Nutzer
# verzoegert (~10 min). Deshalb wandert 'tick_zeit' ungefiltert mit nach vorn
# und die Oberflaeche zeigt das Alter an — ein Kurs ohne sichtbares Alter waere
# genau die Sorte Zahl, die man fuer live haelt, bis es teuer wird. Fuer einen
# Ueberblick reicht das; wer daran spaeter Ausfuehrung haengen will, braucht
# eine echte Live-Quelle (naheliegend: der Orbit-Reader liest TradingViews
# Watchlist mit Finns eigenem CME-Abo).
_markt_cache = {"ts": 0, "data": None}
_markt_lock = threading.Lock()
MARKT_TTL = 10            # Sekunden — Finn will es so frisch wie moeglich; an
                          # Yahoos ~10 min Verzoegerung aendert das nichts, es
                          # holt den verzoegerten Stand nur oefter nach.
MARKT_PUNKTE = 600        # 5-Minuten-Kerzen: ~50 Handelsstunden. Feiner als die
                          # frueheren 15-Minuten-Kerzen, weil daraus jetzt auch
                          # der grosse Chart gezeichnet wird — die Sparkline auf
                          # der Karte nimmt sich davon clientseitig das Ende.
MARKT_SYMBOLE = [
    {"key": "NQ",  "yahoo": "NQ=F",  "name": "E-mini Nasdaq-100",       "punktwert": 20},
    {"key": "MNQ", "yahoo": "MNQ=F", "name": "Micro E-mini Nasdaq-100", "punktwert": 2},
]


def _markt_hole(sym):
    """Einen Kontrakt bei Yahoo holen. Wirft bei Problemen — der Aufrufer
    entscheidet, ob er alten Stand liefert."""
    r = requests.get(
        f"https://query1.finance.yahoo.com/v8/finance/chart/{sym['yahoo']}",
        params={"range": "5d", "interval": "5m"},
        headers={"User-Agent": "Mozilla/5.0 (Prophos)"}, timeout=12)
    r.raise_for_status()
    res = ((r.json() or {}).get("chart") or {}).get("result") or []
    if not res:
        raise ValueError(f"Yahoo ohne Ergebnis fuer {sym['yahoo']}")
    m = res[0].get("meta") or {}
    ts = res[0].get("timestamp") or []
    q = ((res[0].get("indicators") or {}).get("quote") or [{}])[0]
    closes = q.get("close") or []
    # Luecken (None) fallen raus — Yahoo liefert sie fuer Zeiten ohne Handel.
    # Zeit und Kurs muessen dabei PAARWEISE wegfallen, sonst verschiebt sich
    # die Zeitachse still gegen die Kurse.
    punkte = [(t, c) for t, c in zip(ts, closes) if c is not None]
    punkte = punkte[-MARKT_PUNKTE:]
    preis = m.get("regularMarketPrice")
    vortag = m.get("chartPreviousClose") or m.get("previousClose")
    diff = (preis - vortag) if (preis is not None and vortag) else None
    return {
        "key": sym["key"], "yahoo": sym["yahoo"], "name": sym["name"],
        "punktwert": sym["punktwert"],
        "kurzname": m.get("shortName"), "waehrung": m.get("currency"),
        "boerse": m.get("exchangeName"),
        "preis": preis, "vortag": vortag, "diff": diff,
        "diff_pct": (diff / vortag * 100) if (diff is not None and vortag) else None,
        "tick_zeit": m.get("regularMarketTime"),
        "zeiten": [p[0] for p in punkte],
        "kurse": [round(p[1], 2) for p in punkte],
    }


@app.route("/markt/futures", methods=["GET", "OPTIONS"])
def markt_futures():
    if request.method == "OPTIONS":
        return "", 200
    now = time.time()
    with _markt_lock:
        if _markt_cache["data"] is not None and (now - _markt_cache["ts"]) < MARKT_TTL:
            return jsonify(_markt_cache["data"])
    maerkte, fehler = [], []
    for sym in MARKT_SYMBOLE:
        try:
            maerkte.append(_markt_hole(sym))
        except Exception as e:
            fehler.append(f"{sym['key']}: {type(e).__name__}")
    if not maerkte:
        # Nichts Neues bekommen: lieber den alten Stand mit seinem Alter zeigen
        # als eine leere Oberflaeche — dieselbe Regel wie beim News-Kalender,
        # und dieselbe wie ueberall im Stack: stale ist eine Aussage, leer nicht.
        with _markt_lock:
            if _markt_cache["data"] is not None:
                alt = dict(_markt_cache["data"])
                alt["stale"] = True
                alt["fehler"] = fehler
                return jsonify(alt)
        return jsonify({"maerkte": [], "fehler": fehler, "fetched": now}), 502
    payload = {"maerkte": maerkte, "fetched": now, "stale": False,
               "fehler": fehler, "quelle": "Yahoo Finance (verzoegert)"}
    with _markt_lock:
        _markt_cache["data"] = payload
        _markt_cache["ts"] = now
    return jsonify(payload)

