def flatten_php_form(data, parent_key=""):
    """Konvertiert nested dict/list zu PHP-Bracket-Form für x-www-form-urlencoded.

    Beispiel: {'settings': [{'id_slave': '29524'}]}
    →        [('settings[0][id_slave]', '29524')]

    Wird von Duplikium V4 verlangt für Endpoints die Arrays nehmen (z.B. setSettings.php).
    Flache Dicts ohne Nesting bleiben unverändert (Backwards-Compat zu getAccounts etc.).
    """
    items = []
    if isinstance(data, dict):
        for k, v in data.items():
            new_key = f"{parent_key}[{k}]" if parent_key else str(k)
            if isinstance(v, (dict, list)):
                items.extend(flatten_php_form(v, new_key))
            elif v is None:
                items.append((new_key, ""))
            elif isinstance(v, bool):
                items.append((new_key, "1" if v else "0"))
            else:
                items.append((new_key, str(v)))
    elif isinstance(data, list):
        for i, v in enumerate(data):
            new_key = f"{parent_key}[{i}]"
            if isinstance(v, (dict, list)):
                items.extend(flatten_php_form(v, new_key))
            elif v is None:
                items.append((new_key, ""))
            elif isinstance(v, bool):
                items.append((new_key, "1" if v else "0"))
            else:
                items.append((new_key, str(v)))
    return items

@app.after_request
def cors(r):
    r.headers["Access-Control-Allow-Origin"] = "*"
    # sb-token gehört dazu, sonst blockt der Browser den Admin-Endpoint schon im
    # Preflight ("Failed to fetch", 15.08.2026 live aufgetreten).
    r.headers["Access-Control-Allow-Headers"] = "Content-Type, Authorization, ma-token, ma-account, dup-token, dup-user, sb-token"
    # PATCH/DELETE seit 31.08.2026: der Kaufplan aendert und loescht Zeilen, und
    # ohne die Methoden hier scheitert schon der Preflight — der Browser meldet
    # nur "Failed to fetch", was wie ein Netzfehler aussieht und keiner ist.
    # Exakt dieselbe Falle wie beim sb-token-Header eine Zeile drueber.
    r.headers["Access-Control-Allow-Methods"] = "GET, POST, PATCH, DELETE, OPTIONS"
    return r

@app.route("/")
def index():
    # Optional (nur für lokale PC-Installationen): Frontend LIVE von einer URL holen,
    # damit prophos.html auf den PCs nie veraltet — Updates laufen dann weiter normal
    # über GitHub/Cloudflare, ohne dass auf jedem PC etwas nachgezogen werden muss.
    # Aktivierung per Env-Var PROPHOS_FRONTEND (setzt start-local-backend.bat).
    # Ohne die Var bleibt das Verhalten unverändert (Railway ist damit nicht betroffen).
    # Bei jedem Fehler/Timeout: Fallback auf die lokale Datei, damit der PC offline
    # weiterarbeiten kann.
    # SCHUTZ (07.10.2026, Finn: „dass man die Software, das Frontend und das Backend nicht kopieren kann"): auf Railway liefert
    # „/" die Oberfläche NICHT mehr aus — sie lag dort für jeden ohne Login offen. Railway ist nur API; die Seite gibt es über
    # pages.dev (dort davor Cloudflare Access) bzw. auf den PCs über localhost:5000.
    if (os.environ.get("RAILWAY_ENVIRONMENT") or os.environ.get("RAILWAY_GIT_COMMIT_SHA") or "").strip():
        return Response('<!doctype html><meta charset="utf-8"><title>Prophos</title>'
                        '<p style="font-family:system-ui">Prophos: <a href="https://prophos.pages.dev/prophos">prophos.pages.dev</a></p>',
                        mimetype="text/html")
    remote = (os.environ.get("PROPHOS_FRONTEND") or "").strip()
    if remote:
        # Seit 07.10.2026 zuerst mit dem PC-Schlüssel von Railway (pages.dev steht hinter Cloudflare Access, ein Server-Abruf
        # ohne Anmeldung bekäme dort nur die Login-Seite); pages.dev und die lokale Datei bleiben Rückfall.
        r0 = _code_holen("/code/datei/prophos.html", timeout=15)
        if r0 is not None and len(r0.content) > 50000 and b"OS_TAB_BUILD" in r0.content:
            return Response(r0.content, mimetype="text/html")
        try:
            r = requests.get(remote, timeout=10)
            if r.ok and len(r.content) > 50000 and b"OS_TAB_BUILD" in r.content:
                return Response(r.content, mimetype="text/html")
            print(f"[frontend] Remote lieferte HTTP {r.status_code} / {len(r.content)} Bytes — nutze lokale Datei")
        except Exception as e:
            print(f"[frontend] Remote-Fetch fehlgeschlagen ({type(e).__name__}) — nutze lokale Datei")
    # Serve prophos.html if present, otherwise fall back to old index.html
    if os.path.exists("prophos.html"):
        return send_from_directory(".", "prophos.html")
    return send_from_directory(".", "index.html")

# ── Frontend-Version für den Build-Wächter (25.09.2026, Koordination: PC-Tabs liefen tagelang auf altem Stand — Mikes
# pc-l5o8bv auf .544, aktuell .595). Der Wächter in prophos.html holt /mt5-copier/VERSION von der eigenen Origin; auf
# localhost:5000 gab es die Route nicht (404), also blieb er still und der offene Tab alt (der Selbst-Update-Watcher
# aktualisiert nur Backend/Copier). Quelle wie beim Frontend-Proxy oben: im Lokal-Modus (PROPHOS_FRONTEND) dieselbe
# Remote-Origin, damit Version und ausgeliefertes HTML zusammenpassen; sonst (Railway) die Datei im Repo. 30 s gecacht,
# CORS kommt aus dem gemeinsamen after_request. ──
_frontend_ver = {"at": 0.0, "wert": None}
_FRONTEND_VER_RE = re.compile(r"^\d{4}-\d{2}-\d{2}\.\d+$")

@app.route("/mt5-copier/VERSION", methods=["GET"])
def frontend_version():
    now = time.time()
    if _frontend_ver["wert"] and now - _frontend_ver["at"] < 30:
        wert = _frontend_ver["wert"]
    else:
        wert = None
        remote = (os.environ.get("PROPHOS_FRONTEND") or "").strip()
        if remote:
            r0 = _code_holen("/code/stand")      # 07.10.2026: zuerst Railway (pages.dev hinter Cloudflare Access)
            try:
                v0 = str(((r0.json() or {}).get("version") if r0 is not None else "") or "").strip()
                if _FRONTEND_VER_RE.match(v0):
                    wert = v0
            except Exception:
                pass
        if remote and not wert:
            try:
                m = re.match(r"^(https?://[^/]+)", remote)
                if m:
                    r = requests.get(m.group(1) + "/mt5-copier/VERSION", timeout=6, headers={"Cache-Control": "no-cache"})
                    t = (r.text or "").strip()
                    if r.ok and _FRONTEND_VER_RE.match(t):
                        wert = t
            except Exception as e:
                print(f"[frontend] VERSION remote fehlgeschlagen ({type(e).__name__}) — nutze lokale Datei")
        if not wert:
            try:
                with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "mt5-copier", "VERSION"), "r", encoding="utf-8") as f:
                    t = f.read().strip()
                wert = t if _FRONTEND_VER_RE.match(t) else None
            except Exception:
                wert = None
        if wert:
            _frontend_ver.update(at=now, wert=wert)
    if not wert:
        return Response("", status=404, mimetype="text/plain")
    resp = Response(wert, mimetype="text/plain")
    resp.headers["Cache-Control"] = "no-store"
    return resp

# ── TopstepX Proxy ──
@app.route("/api/<path:path>", methods=["GET","POST","OPTIONS"])
def tsx_proxy(path):
    if request.method == "OPTIONS": return "", 200
    h = {"Content-Type": "application/json"}
    t = request.headers.get("Authorization", "")
    if t: h["Authorization"] = t
    try:
        r = requests.request(request.method, f"{TSX_BASE}/api/{path}",
            json=request.get_json(silent=True), headers=h, timeout=10)
        return Response(r.content, status=r.status_code, content_type="application/json")
    except Exception as e:
        return jsonify({"error": str(e), "success": False}), 500

# ── MetaApi Proxy ──
@app.route("/ma/<path:path>", methods=["GET","POST","OPTIONS"])
def ma_proxy(path):
    if request.method == "OPTIONS": return "", 200
    if path == "positions" and request.method == "GET":
        # 08.10.2026 (Prüfer: ~90 GET /ma/positions je 5 min, ein Drittel 500/504 nach 5–15 s — der Proxy wartet bis 15 s auf
        # MetaApi und belegt den einen Worker). Abruf kam nur noch aus der alten Live-Trades-Ansicht (Frontend seit .1367 entfernt),
        # alte Tabs/lokale Stände fragen weiter → sofort leer antworten, ohne MetaApi. /ma/account + history-deals (Handknöpfe) bleiben.
        return jsonify([])
    token      = request.headers.get("ma-token", "")
    account_id = request.headers.get("ma-account", "")
    h = {"Content-Type": "application/json", "auth-token": token}
    if account_id and path == "account":
        url = f"{MA_BASE}/users/current/accounts/{account_id}/account-information"
    elif account_id:
        url = f"{MA_BASE}/users/current/accounts/{account_id}/{path}"
    else:
        url = f"{MA_BASE}/users/current/{path}"
    try:
        r = requests.request(request.method, url,
            json=request.get_json(silent=True), headers=h, timeout=15, verify=False)
        return Response(r.content, status=r.status_code, content_type="application/json")
    except Exception as e:
        return jsonify({"error": str(e)}), 500

# ── MT5-Copier Panel-Proxy (Etappe 3, 15.08.2026) ──
# prophos.html erreicht darueber die Panel-API des eigenen Hedge-Copier-Stacks
# auf DIESEM PC (127.0.0.1:8770, siehe mt5-copier/panel.py). Bewusst nur
# localhost: der Copier ist eine Pro-PC-Angelegenheit — auf Railway existiert
# kein Panel, dort antwortet die Route sauber mit 502 und das Frontend zeigt
# "nur am lokalen PC verfuegbar". Die Duplikium-Logik bleibt komplett
# unberuehrt; das hier ist die parallele Schnittstelle zum eigenen Copier.
COPIER_PANEL = "http://127.0.0.1:8770"

# UPDATE-SCHUTZ (29.10.2026, Befund „Deploy-Welle": fünf Abrisse in zwei Stunden — jeder 1–2 min nach einem Push mit app.py; der lokale
# Selbst-Neustart (_local_version_watcher) beendete diesen Prozess per os._exit mitten in einem /copier-Aufruf, der Bot lief im Panel
# weiter und klickte, nur die Antwort war weg → „Ergebnis UNKLAR"). Jeder Proxy-Aufruf zählt hier mit; der Watcher startet nur bei 0 und
# wenn das Panel „frei" meldet. Kurz vor dem Beenden schließt er den Proxy (zu): neue Aufrufe bekommen sofort 503 „nichts gesendet" statt
# mitten im Lauf abzureißen.
_PROXY = {"n": 0, "zu": False}
_PROXY_LOCK = threading.Lock()


@app.route("/copier/<path:path>", methods=["GET","POST","OPTIONS"])
def copier_proxy(path):
    if request.method == "OPTIONS": return "", 200
    # SICHERHEIT (Review 15.08.2026): Das Panel schuetzt sich selbst nur, solange
    # es direkt angesprochen wird — es bindet an 127.0.0.1 und prueft Host+Origin.
    # Dieser Proxy darf diese Grenze NICHT aufweichen. Zwei Riegel:
    #  1) Nur lokale Aufrufer. app.py lauscht auf 0.0.0.0 (Railway/LAN), aber der
    #     Copier ist eine reine Loopback-Sache. Ein LAN-Geraet (fremde remote_addr)
    #     darf hier nichts schalten — sonst koennte es Accounts auf 'live' setzen.
    #  2) Browser-Origin durchreichen, damit die Origin-Pruefung des Panels wieder
    #     greift (schuetzt gegen Drive-by-POSTs fremder Seiten trotz CORS '*').
    if request.remote_addr not in ("127.0.0.1", "::1", "::ffff:127.0.0.1"):
        return jsonify({"ok": False, "copier_offline": True,
                        "error": "Copier ist nur lokal auf dem PC selbst erreichbar."}), 403
    with _PROXY_LOCK:
        if _PROXY["zu"]:
            # _nichtGesendet: beweisbar nichts weitergereicht — der Tab wertet es wie „lokales Backend weg" (kein UNKLAR, später erneut)
            return jsonify({"ok": False, "copier_offline": True, "_httpFail": True, "code": "backend_neustart", "retry_ok": True, "_nichtGesendet": True,
                            "error": "Prophos-Backend startet gerade neu (Update) — nichts gesendet, gleich erneut."}), 503
        _PROXY["n"] += 1
    try:
        return _copier_proxy_lauf(path)
    finally:
        with _PROXY_LOCK:
            _PROXY["n"] -= 1


def _copier_proxy_lauf(path):
    h = {"Content-Type": "application/json"}
    origin = request.headers.get("Origin")
    if origin: h["Origin"] = origin
    # HEDGE-ZU-7S (02.11.2026, Plan e67ec7b9: Close 7,17 s zwischen Tab und Panel, Glied unbekannt): nur Messung, das Panel gibt den Stempel zurück
    if path == "hedge-solo":
        h["X-Prophos-Proxy-Ms"] = str(round(time.time() * 1000))
    try:
        # master-order braucht mehr Luft als der Rest (Review-Blocker 15.08.2026):
        # ein zu frueher Proxy-Abbruch haette dem Frontend 'keine Order' gemeldet,
        # waehrend die Order Sekunden spaeter doch platziert wird (Doppel-Order-
        # Pfad). Seit 287644d darf der Bot bis 300s laufen (SL/TP-Band-Scan) —
        # die 60s hier waren am alten 45s-Stand kalibriert und rissen die Kette
        # wieder auf (Offene Punkte 215/221); mit Remote-Signalen (28.08.2026)
        # sitzt dann niemand am PC, der es merkt. Der aeussere Timeout ist die
        # Obergrenze der Wahrheit: 310s = Bot-Maximum + Puffer. master-close
        # (28.08.2026, Remote-Close) faehrt denselben Band-Scan — gleiche Luft.
        # tv-order (30.08.2026, Orbit-Puls Schritt 2) gehoert in dieselbe
        # Klasse: der Bot darf 180s laufen (vier Warte-Etappen im Browser plus
        # 25s Bestaetigungsfenster), ein frueher Proxy-Abbruch waere hier
        # derselbe Doppel-Order-Pfad wie bei master-order.
        # tv-konto (21.09.2026, Futures-Puls Neuaufbau Schritt 2): startet bei
        # Bedarf TradingView und wartet, bis der Broker wieder verbunden ist —
        # das Panel gibt dem Bot 260 s (seit 2b: ab-/anmelden). Hier wird nichts gesendet, ein frueher
        # Abbruch waere also kein Doppel-Order-Pfad, aber eine falsche Absage.
        # tv-lesen / tv-close (24.09.2026, Orbit-V2-Rundgang und -Schließen): der Bot schaltet
        # Konten um und wartet auf frische Reader-Stände — Panel-Timeout bis 165 s+. Mit 25 s
        # brach der Proxy ab, während der Bot weiterklickte (PC-Agent-Befund).
        # hedge-solo (24.09.2026, Winning-Day-Gegenhedge): das Panel wartet bis 14 s auf die
        # Quittung des Copiers — 25 s waeren knapp, ein Proxy-Abbruch saehe wie „nicht gesendet" aus.
        # tsx-konto / tsx-lesen / tsx-inventar / tsx-close (30.09.2026, Topstep-Paket Etappe S): das Panel gibt dem Bot 170 s
        # (tsx-konto) bzw. 150 s — mit den 25 s von bisher brach der Proxy ab, während der Bot unter TV_ORDER_LOCK
        # weiterklickte (order_signale 99e6087a, 27.09. ReadTimeout). Das Frontend meldete „nichts gesendet", ein
        # erneuter Start hätte ein zweites Mal platziert: derselbe Doppel-Order-Pfad wie master-order.
        _tmo = (310 if path in ("master-order", "master-close", "tv-order", "tv-lesen", "tv-close",
                                "tsx-konto", "tsx-lesen", "tsx-inventar", "tsx-close", "tv-konten-liste")   # tv-konten-liste (29.10.2026): Panel bis 260 s
                else 270 if path == "tv-konto" else 40 if path == "hedge-solo" else 100 if path == "tv-neuladen" else 160 if path == "tv-tm-update"
                else 50 if path == "vorflug" else 25)   # 29.10.2026: Panel bis 90 / 150 s
        # vorflug (F-A, 11.11.2026, Slave 1 FS3 / Slave 4 98c62e41): das Panel liest bis 40 s (Lese-Deckel, nur MetaTrader5-API) — mit 25 s kam ein 502, der Tab
        # wiederholte im nächsten Takt. 50 s = Lese-Deckel + Luft (≥ 45 s, Master). Nur lesend, kein Doppel-Order-Pfad
        r = requests.request(
            request.method, f"{COPIER_PANEL}/api/{path}",
            params=request.args,
            json=request.get_json(silent=True) if request.method == "POST" else None,
            headers=h, timeout=_tmo)
        return Response(r.content, status=r.status_code, content_type="application/json")
    except Exception as e:
        return jsonify({"ok": False, "copier_offline": True,
                        "error": f"Copier-Panel auf diesem PC nicht erreichbar ({type(e).__name__})"}), 502

# ── Stack-Neustart per Knopf (15.08.2026, Finns Wunsch) ──
# Das Hand-Ritual — CMD-Fenster zu, taskkill python, start-alles.bat — als EIN
# Klick im MT5-Tab. Killt bewusst auch DIESES Backend; die .bat startet alles
# frisch, laufende Instanzen schuetzen sich selbst (Copier-Status-Sperre,
# Panel/Backend-Port-Probe). Nur Lokal-Modus + nur Loopback (gleiche Riegel
# wie der Copier-Proxy — ein LAN-Geraet darf den Stack nicht neu starten).
#
# 31.08.2026 (Finn: "bau mal einen Button, der alle offenen CMD schliesst — ich
# muss die immer von Hand schliessen"): der Kill war bis heute eine WHITELIST
# von fuenf Fenstertiteln. Die trifft genau die Fenster, die start-alles.bat
# selbst mit "start <Titel> cmd /c ..." oeffnet — und sonst keines. Alles
# andere ueberlebt und stapelt sich: das Fenster von start-alles.bat SELBST
# (autostart-einrichten.bat startet es mit LEEREM Titel, es laeuft also unter
# dem Standardtitel), jedes von Hand doppelgeklickte .bat, und jede Huelle,
# deren Titel sich seit dem Start geaendert hat. Auf Finns Screenshot standen
# sieben Konsolen; nach "Alles neu starten" blieben die titellosen stehen.
# Eine Whitelist kann das prinzipiell nicht loesen — sie kennt nur, was sie
# selbst geoeffnet hat. Deshalb jetzt umgekehrt: ALLE cmd.exe, egal woher.
# Das ist Finns Ansage ("alle sieben Fenster, egal welche") und auf diesen PCs
# auch richtig: was dort in einer Konsole laeuft, gehoert zum Stack und wird
# im selben Zug neu gestartet.
# Der Helfer ist deshalb ein POWERSHELL-Skript und kein .bat mehr: ein .bat
# laeuft selbst in einer cmd.exe und wuerde sich beim Blanko-Kill als Erstes
# selbst beenden — start-alles.bat wuerde nie erreicht. powershell.exe ist vom
# cmd-Kill nicht betroffen und ueberlebt ihn. Die Datei liegt bewusst im
# Klartext in %TEMP% (kein -EncodedCommand), damit auf dem PC nachlesbar
# bleibt, was der Knopf getan hat.
@app.route("/local/restart-stack", methods=["POST", "OPTIONS"])
def local_restart_stack():
    if request.method == "OPTIONS":
        return "", 200
    if request.remote_addr not in ("127.0.0.1", "::1", "::ffff:127.0.0.1"):
        return jsonify({"ok": False, "msg": "Nur lokal auf dem PC selbst erlaubt."}), 403
    if os.name != "nt" or not (os.environ.get("PROPHOS_FRONTEND") or "").strip():
        return jsonify({"ok": False, "msg": "Nur im Lokal-Modus (PROPHOS_FRONTEND) verfuegbar."}), 403
    bat = (os.environ.get("PROPHOS_STACK_BAT") or r"C:\mt5-copier\start-alles.bat").strip()
    if not os.path.exists(bat):
        return jsonify({"ok": False, "msg": f"start-alles.bat nicht gefunden: {bat}"})
    if "'" in bat:
        # Ein einfaches Anfuehrungszeichen wuerde das PS-Literal unten aufbrechen.
        return jsonify({"ok": False, "msg": "Pfad mit ' wird nicht unterstuetzt: " + bat})
    import subprocess
    import tempfile
    url = ("https://raw.githubusercontent.com/finntraidingview-cmd/Prophos/"
           "main/mt5-copier/start-alles.bat")
    helper = os.path.join(tempfile.gettempdir(), "prophos-restart-stack.ps1")
    skript = f"""# Von Prophos erzeugt — Knopf "Alles schliessen & neu starten".
$ErrorActionPreference = 'SilentlyContinue'
$ProgressPreference = 'SilentlyContinue'
# Antwort ans Frontend rausgehen lassen, bevor das Backend stirbt.
Start-Sleep -Seconds 2
# 1) ALLE Konsolenfenster — und zwar ZUERST: start-copier.bat & Co. sind
#    Neustart-Schleifen, ein zuerst beendetes python.exe waere in 10 s zurueck.
Get-Process cmd | Stop-Process -Force
# 2) Danach die Prozesse selbst. Trifft absichtlich auch dieses Backend.
Get-Process python, pythonw | Stop-Process -Force
Start-Sleep -Seconds 2
# 3) start-alles.bat haelt alles ausser sich selbst aktuell — eine LAUFENDE
#    Batchdatei darf man nicht ueberschreiben, sie kann es also nicht selbst
#    tun. Hier geht es: der Kill oben hat gerade alles beendet, die Datei ist
#    garantiert nicht offen. Best effort — schlaegt der Download fehl oder
#    kommt er zu kurz an, bleibt schlicht der alte Stand.
$bat = '{bat}'
# Seit 07.10.2026 (Repo privat): zuerst Railway mit dem PC-Schlüssel (code_token.txt neben der .bat), sonst GitHub.
$tok = ''
try {{ $tok = (Get-Content (Join-Path (Split-Path -Parent $bat) 'code_token.txt') -TotalCount 1 -ErrorAction Stop).Trim() }} catch {{ }}
$ok = $false
if ($tok) {{ try {{ Invoke-WebRequest 'https://web-production-bec81.up.railway.app/code/datei/mt5-copier/start-alles.bat' -Headers @{{'X-Code-Token'=$tok}} -OutFile "$bat.newh" -TimeoutSec 20 -UseBasicParsing; $ok = $true }} catch {{ }} }}
if (-not $ok) {{ try {{ Invoke-RestMethod '{url}' -OutFile "$bat.newh" -TimeoutSec 20 }} catch {{ }} }}
if (Test-Path "$bat.newh") {{
  if ((Get-Item "$bat.newh").Length -ge 700) {{ Move-Item -Force "$bat.newh" $bat }}
  else {{ Remove-Item -Force "$bat.newh" }}
}}
# 4) Frisch hochfahren.
Start-Process -FilePath $bat -WorkingDirectory (Split-Path -Parent $bat)
"""
    # utf-8-SIG (mit BOM): Windows PowerShell 5.1 liest eine .ps1 OHNE BOM als
    # ANSI und verstuemmelt dabei die Umlaute/Gedankenstriche in den Kommentaren.
    # Harmlos waere das nur, solange nichts davon je aus einem Kommentar rutscht
    # — der BOM macht die Frage gegenstandslos.
    with open(helper, "w", encoding="utf-8-sig") as f:
        f.write(skript)
    DETACHED_PROCESS = 0x00000008
    CREATE_NEW_PROCESS_GROUP = 0x00000200
    subprocess.Popen(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass",
                      "-WindowStyle", "Hidden", "-File", helper],
                     creationflags=DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP,
                     close_fds=True, cwd=os.path.dirname(bat))
    print("[stack] Neustart angestossen — ALLE Konsolen werden geschlossen, "
          "dieses Backend wird mitgekillt.", flush=True)
    return jsonify({"ok": True, "msg": "Alle Konsolen werden geschlossen, Stack startet neu."})

# ── Duplikium Connect (Basic Auth → Token) ──
@app.route("/duplikum/connect", methods=["POST","OPTIONS"])
def duplikum_connect():
    """
    Body: {"email": "...", "password": "..."}
    Macht Basic-Auth-POST gegen getToken.php und gibt Token zurück.
    Token + Creds werden in-memory gecached für Auto-Refresh.
    """
    if request.method == "OPTIONS": return "", 200
    data = request.get_json(silent=True) or {}
    email    = (data.get("email") or "").strip()
    password = data.get("password") or ""
    if not email or not password:
        return jsonify({"ok": False, "error": "email und password sind nötig"}), 400

    try:
        r = requests.post(
            f"{DUP_BASE}/access/getToken.php",
            auth=(email, password),
            timeout=15
        )
        # Duplikium gibt entweder JSON {token: "..."} oder den Token direkt als Plain-Text zurück.
        # Wir behandeln beide Fälle defensiv.
        token = None
        try:
            d = r.json()
            if isinstance(d, dict):
                token = d.get("token") or d.get("access_token") or (d.get("data") or {}).get("token")
            elif isinstance(d, str):
                token = d
        except Exception:
            # Plain-Text-Response
            txt = (r.text or "").strip().strip('"')
            if txt and len(txt) < 2000 and " " not in txt:
                token = txt

        if not r.ok or not token:
            return jsonify({
                "ok": False,
                "status": r.status_code,
                "error": "Login fehlgeschlagen — prüfe E-Mail/Passwort und ob 'Enable access' im Trade-Copier-Dashboard aktiviert ist.",
                "raw": (r.text or "")[:300]
            }), 401

        # Cache (Memory only)
        duplikum_sessions[email] = {
            "token": token,
            "password": password,
            "last_refresh": time.time()
        }
        return jsonify({"ok": True, "token": token, "email": email})

    except requests.exceptions.RequestException as e:
        return jsonify({"ok": False, "error": f"Netzwerkfehler: {e}"}), 502
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500

def refresh_duplikum_token(email):
    """Holt einen neuen Token. Nutzt gecachte Creds ODER dauerhafte Env-Creds
    (überlebt Restarts/Worker-Wechsel). Returns neuer Token oder None."""
    s = duplikum_sessions.get(email)
    password = (s or {}).get("password")
    # Fallback: dauerhafte Env-Creds, falls der In-Memory-Cache leer ist
    # (z.B. nach Railway-Restart oder in einem anderen Gunicorn-Worker).
    if not password and email and DUP_EMAIL and email.lower() == DUP_EMAIL.lower():
        password = DUP_PASSWORD
    if not password:
        return None
    try:
        r = requests.post(
            f"{DUP_BASE}/access/getToken.php",
            auth=(email, password),
            timeout=15
        )
        token = None
        try:
            d = r.json()
            if isinstance(d, dict):
                token = d.get("token") or d.get("access_token") or (d.get("data") or {}).get("token")
            elif isinstance(d, str):
                token = d
        except Exception:
            txt = (r.text or "").strip().strip('"')
            if txt and len(txt) < 2000 and " " not in txt:
                token = txt
        if r.ok and token:
            # Session (neu) aufbauen, damit Folge-Refreshes wieder aus dem Cache gehen
            duplikum_sessions[email] = {
                "token": token,
                "password": password,
                "last_refresh": time.time()
            }
            print(f"[duplikum] 🔄 Token refreshed für {email}")
            return token
    except Exception as e:
        print(f"[duplikum] ⚠️ Refresh error: {e}")
    return None

# ── Duplikium Session-Handout (25.08.2026) ──
# Flotte + Live-Lots im Frontend brauchen den Duplikium-Token, der aber nur im
