def alarm_prio_aus_titel(titel):
    """REIN RECHNEND (testbar): Stufe 1–3 einer bestehenden Meldung nach ihrem Titel."""
    t = str(titel or "")
    for teil, p in ALARM_PRIO_TITEL:
        if teil in t:
            return p
    return 3


def _alarm_empfaenger():
    """{uid: min_prio} der aktiven Master-IDs, 120 s gecacht. Tabelle fehlt/nicht lesbar → {} (Alarme aus, Pushes an IDs laufen weiter)."""
    if _alarm["empf"] is not None and time.time() - _alarm["empf_at"] < ALARM_CACHE_S:
        return _alarm["empf"]
    try:
        rows = sb_select("alarm_empfaenger", {"select": "user_id,min_prio", "aktiv": "eq.true"}) or []
        _alarm["empf"] = {str(r["user_id"]): int(r.get("min_prio") or 2) for r in rows}
    except Exception as e:
        print(f"[alarm] ⚠️ Empfänger nicht lesbar: {type(e).__name__}: {e}", flush=True)
        _alarm["empf"] = _alarm["empf"] or {}
    _alarm["empf_at"] = time.time()
    return _alarm["empf"]


def _alarm_fremd_verwaltet(uid):
    """True = ID gehört zu einer Gruppe mit Verwalter (Emin) oder IST ein Verwalter — deren Meldungen gehen nicht an die Master-IDs."""
    if time.time() > _push_verwalter_cache["bis"]:
        _push_verwalter_cache.update(karte=gp_verwalter_karte(), bis=time.time() + 300)
    karte = _push_verwalter_cache["karte"]
    return str(uid) in karte or str(uid) in set(karte.values())


def alarm_senden(prio, art, titel, text, uid=None, plan_id=None, schluessel=None, url=None, tag=None, renotify=False, daten=None,
                 ausser=(), zeichen=None, push_prio=None):
    """Eine Meldung an alle Master-IDs mit min_prio ≥ prio + eine Zeile alarm_log. ausser = Empfänger, die sie schon haben. UA1 (06.11.2026):
    zeichen ersetzt das Prio-Zeichen im Titel, push_prio die Stufe für Push (Ton/Stehenbleiben) und alarm_log — „✅ erledigt" erreicht so mit
    prio 1 dieselben Empfänger wie das 🔴, kommt aber leise wie ⚪ und steht im Verlauf nicht als 🔴. Ohne beides wie bisher. Wirft nie."""
    zu = n = 0
    stufe = None
    try:
        prio = max(1, min(3, int(prio or 3)))
        stufe = max(1, min(3, int(push_prio))) if push_prio else prio
        titel_m = ((ALARM_ZEICHEN[prio] if zeichen is None else str(zeichen)) + str(titel or "Prophos"))[:80]
        for ziel, schwelle in _alarm_empfaenger().items():
            if ziel in ausser or prio > schwelle:
                continue
            a, b = push_an_user(ziel, titel_m, text, url=url or ALARM_LINK, tag=tag or f"alarm-{art}-{plan_id or ''}"[:60],
                                renotify=renotify or stufe == 1, prio=stufe, _weiter=False)
            zu, n = zu + a, n + b
    except Exception as e:
        print(f"[alarm] ⚠️ senden {art}: {type(e).__name__}: {e}", flush=True)
    try:
        _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/alarm_log",
                    json={"prio": stufe or prio, "art": str(art)[:40], "titel": str(titel or "")[:120], "text": str(text or "")[:400],
                          "uid": uid if uid and re.fullmatch(r"[0-9a-f-]{36}", str(uid)) else None, "plan_id": plan_id,
                          "schluessel": schluessel, "daten": daten or {}, "zugestellt": zu, "geraete": n},
                    headers=_sb_headers("return=minimal"), timeout=10)
    except Exception as e:
        print(f"[alarm] ⚠️ alarm_log: {type(e).__name__}: {e}", flush=True)
    _st = stufe or prio
    _alarm["letzt"] = (_alarm["letzt"] + [{"at": _wt_now_iso(), "prio": _st, "art": art, "titel": titel, "zugestellt": zu}])[-30:]
    print(f"[alarm] {(zeichen if zeichen is not None else ALARM_ZEICHEN.get(_st, '')) or '⚪ '}{titel} — {str(text or '')[:160]} ({zu}/{n} Geräte)", flush=True)
    return zu, n


def _alarm_weiter(uid, titel, text, url, tag, renotify):
    """Weg (a): eine Meldung an eine ID zusätzlich an die Master-IDs (eingestuft nach Titel). Nie an die ID selbst, nie Verwalter-Gruppen."""
    try:
        if str(tag or "") in ALARM_OHNE_TAGS or not _alarm_empfaenger() or _alarm_fremd_verwaltet(uid):
            return
        namen, _aus = _ap_namen()
        wer = namen.get(str(uid), "")
        if wer and wer not in titel and wer not in text:
            text = f"{wer}: {text}"
        alarm_senden(alarm_prio_aus_titel(titel), "push", titel, text, uid=str(uid), url=url, tag=tag, renotify=renotify,
                     ausser={str(uid)})
    except Exception as e:
        print(f"[alarm] ⚠️ weiter: {type(e).__name__}: {e}", flush=True)


def _alarm_ts(v):
    try:
        t = datetime.fromisoformat(str(v).replace("Z", "+00:00"))
        return t if t.tzinfo else t.replace(tzinfo=timezone.utc)
    except Exception:
        return None


PULS_BILD_PFAD_RE = re.compile(r"pc-[a-z0-9]{4,12}/\d{4}-\d{2}-\d{2}/\d{8}-\d{6}-[0-9a-f]{6}")   # wie PULS_FEHLERBILD_PRAEFIX_RE (weiter unten)


def tsx_brackets_fehlen(route, tv):
    """REIN RECHNEND (29.10.2026, NOVA-ENDE-NUR-MIT-BEWEIS — wie tsxBracketsFehlen in prophos.html): fehlen an diesem tsv2-Plan laut
    Start-Ergebnis Brackets? tv.brackets_fehlen {risk, tp, bild?} (Bot-Rücklesung S5 9286f5f9 bzw. vom PC-Tab aus der vollen Warnung; alte
    Bots true), sonst die Bot-Warnung. tv.brackets_ok_at (Puls oder Hand-Knopf) = nachgewiesen.
    -> {"risk": bool, "tp": bool[, "dialog": Titel aus tv.bracket_dialog][, "bild": Fehlerfoto-Pfad]} | None"""
    if str(route or "") != "tsv2" or not isinstance(tv, dict) or tv.get("brackets_ok_at"):
        return None
    f = _tsx_brackets_kern(tv)
    if not f:
        return None
    bf = tv.get("brackets_fehlen")
    bild = (bf.get("bild") if isinstance(bf, dict) else None) or tv.get("bracket_dialog_bild")
    if bild and PULS_BILD_PFAD_RE.fullmatch(str(bild)):
        f["bild"] = str(bild)
    if tv.get("bracket_dialog"):
        f["dialog"] = re.sub(r"\s+", " ", str(tv.get("bracket_dialog")))[:60]
    return f


def _tsx_brackets_kern(tv):
    bf = tv.get("brackets_fehlen")
    if bf is True:
        return {"risk": True, "tp": True}
    if isinstance(bf, dict) and (bf.get("risk") or bf.get("tp")):
        return {"risk": bool(bf.get("risk")), "tp": bool(bf.get("tp"))}
    # FAIL-CLOSED (Prüfung 29.10.2026, wie tsxWarnungBrackets): jeder Teil der Warnung zählt als „fehlt“ (auch „Reiter Positions … nicht
    # gefunden“, „Order abgelehnt“), außer „Risk/To Make steht auf … der Plan hat keinen SL/TP“ (Bracket steht)
    w = re.sub(r"^\s*Brackets in TopstepX prüfen:\s*", "", str(tv.get("warnung") or ""), flags=re.I)
    teile = [x.strip() for x in re.split(r";\s*", w) if x.strip()]
    teile = [x for x in teile if not re.match(r"^(Risk|To Make) steht auf .*der Plan hat keinen (SL|TP)$", x, re.I)]
    if not teile:
        return None
    risk = any(re.match(r"^Risk\b[^;]*nicht gesetzt", x, re.I) for x in teile)
    tp = any(re.match(r"^To Make\b[^;]*nicht gesetzt", x, re.I) for x in teile)
    if (risk or tp) and all(re.search(r"nicht gesetzt", x, re.I) for x in teile):
        return {"risk": risk, "tp": tp}
    return {"risk": True, "tp": True}


def alarm_ereignisse(plaene, namen, jetzt, seit_iso):
    """REIN RECHNEND (testbar): Plan-Zeilen (id,user_id,status,route,orbit_v3,hedge_eur,master_name,master_firm,started_at,updated_at,
    hedge,final_at + Felder für gp_push_ereignisse) → [(schluessel, prio, art, titel, text, uid, plan_id[, url])].
    Zustände (Hedge/Master auseinander) zählen ab Dauer, Übergänge (Start, Start-Fehler, Radar-Schluss) nur nach seit_iso."""
    out = []
    for key, titel, text in gp_push_ereignisse(plaene, namen, seit_iso):
        if key.endswith("|start"):
            continue                                 # „Trade läuft" meldet schon push_trade_wache (⚪, über _alarm_weiter)
        art = "richtungsschutz" if key.endswith("|ss") else "nicht_gestartet"
        out.append((key, 2, art, titel.replace("⚠ ", "").replace("⛔ ", ""), text, None, key.split("|", 1)[0]))
    for p in plaene or ():
        pid, uid, st = str(p.get("id")), str(p.get("user_id")), p.get("status")
        h = p.get("hedge") if isinstance(p.get("hedge"), dict) else {}
        hst = h.get("status")
        wer = namen.get(uid, uid[:8])
        konto = f"{p.get('master_firm') or ''} {p.get('master_name') or ''}".strip()
        start = _alarm_ts(p.get("started_at"))
        mit_hedge = (_wd_num(p.get("hedge_eur")) or 0) > 0 or p.get("orbit_v3") is True
        lots = f"{h.get('lots')} Lot {h.get('symbol') or ''}".strip() if h.get("lots") else "Fusion-Hedge"
        if st in ("review", "completed") and hst in HEDGE_LEBT:
            ende = _alarm_ts(p.get("final_at")) or _alarm_ts(p.get("updated_at"))
            s = (jetzt - ende).total_seconds() if ende else None
            if s is not None and s >= ALARM_HEDGE_OFFEN_S:
                out.append((f"{pid}|hedge_offen|{min(int(s // ALARM_ERINNERN_S), 3)}", 1, "hedge_offen", "Hedge offen, Master zu",
                            f"{wer} · {konto}: Master ist seit {int(s // 60)} min {int(s % 60)} s zu, {lots} noch offen — im Fusion-Terminal "
                            f"schließen." + (f" Close-Fehler: {str(h.get('close_fehler'))[:80]}" if h.get("close_fehler") else ""),
                            uid, pid))
        elif st == "open" and mit_hedge and p.get("route") in ("tvv2", "tsv2") and start:
            s = (jetzt - start).total_seconds()
            zu_at = _alarm_ts(h.get("closed_at"))
            if hst not in HEDGE_LEBT and hst != "geschlossen" and s >= ALARM_OHNE_HEDGE_S:
                out.append((f"{pid}|ohne_hedge|{min(int(s // ALARM_ERINNERN_S), 3)}", 1, "ohne_hedge", "Master läuft ohne Hedge",
                            f"{wer} · {konto}: Trade läuft seit {int(s // 60)} min, kein offener Fusion-Hedge"
                            + (f" ({hst}: {str(h.get('msg') or h.get('fehler') or '')[:80]})" if hst else "") + " — Hedge von Hand öffnen oder Master schließen.",
                            uid, pid))
            elif hst == "geschlossen" and zu_at and (jetzt - zu_at).total_seconds() >= ALARM_HEDGE_ZU_MASTER_S:
                s2 = (jetzt - zu_at).total_seconds()
                out.append((f"{pid}|ohne_hedge_zu|{min(int(s2 // ALARM_ERINNERN_S), 3)}", 1, "ohne_hedge", "Master läuft ohne Hedge",
                            f"{wer} · {konto}: Hedge ist seit {int(s2 // 60)} min zu ({h.get('grund') or '?'}), Master laut Prophos noch offen — "
                            f"in TradingView prüfen, ggf. abhaken.", uid, pid))
            elif hst in HEDGE_LEBT and h.get("close_fehler"):
                out.append((f"{pid}|close_fehler", 1, "hedge_close_fehler", "Hedge-Close scheitert",
                            f"{wer} · {konto}: {lots} — {str(h.get('close_fehler'))[:120]}", uid, pid))
        # HEDGE-SCHNELLER (02.11.2026, hedgeToastSchluss im PC-Tab): Exit-Fill-Meldung schloss Fusion, die Tabelle zeigt nach 8 s weiter eine Position → 🔴 einmal je Plan
        tw = h.get("toast_wache") if isinstance(h.get("toast_wache"), dict) else {}
        if tw.get("urteil") == "offen" and str(tw.get("at") or "") > seit_iso:
            out.append((f"{pid}|toast_offen", 1, "hedge_toast_offen", "Hedge zu, Master offen",
                        f"{wer} · {konto}: Fill-Meldung {tw.get('menge')} @ {tw.get('preis')} hat Fusion geschlossen, die Tabelle zeigt nach 8 s noch eine "
                        f"Position — in TradingView prüfen, sonst Hedge auf der Karte von Hand öffnen.", uid, pid))
        # HEDGE ZU SPÄT (30.10.2026, hedgeSpaetVermerken im PC-Tab): Order älter als 90 s, der Tab öffnet nicht mehr von selbst → 🔴 einmal je Plan;
        # läuft der Master weiter, erinnert ohne_hedge oben im Takt
        if hst == "uebersprungen" and h.get("grund_code") == "zu_spaet" and str(h.get("at") or "") > seit_iso:
            out.append((f"{pid}|hedge_zu_spaet", 1, "hedge_zu_spaet", "Hedge fehlt, von Hand prüfen",
                        f"{wer} · {konto}: Order ist {h.get('alter_s') or '?'} s alt, Prophos öffnet den Fusion-Hedge nicht mehr von selbst "
                        f"(Grenze 90 s) — im Fusion-Terminal prüfen, ob schon ein Hand-Hedge liegt, sonst auf der Karte „Hedge öffnen“.", uid, pid))
        # GEGENRICHTUNG GESTARTET (30.10.2026, RIEGEL-LOCK, sql/2026-10-30_riegel_lock.sql): ein Start ohne Claim (Hand-Start) lief, obwohl
        # dieselbe ID × Firma in Gegenrichtung läuft — der DB-Trigger trade_plans_gegenrichtung_start hält es an der Zeile fest → 🔴 einmal je Plan
        rv = p.get("rv") if isinstance(p.get("rv"), dict) else {}
        if rv.get("at") and str(rv.get("at")) > seit_iso:
            out.append((f"{pid}|richtung_verstoss", 1, "gegenrichtung_gestartet", "Gegenrichtung gestartet",
                        f"{wer} · {konto}: {str(rv.get('richtung') or '').upper()} gestartet, obwohl {str(rv.get('grund') or 'dieselbe ID × Firma in Gegenrichtung läuft')[:180]}"
                        f"{' (Prüfung unklar)' if rv.get('unklar') else ''} — sofort prüfen, ggf. einen der beiden schließen.", uid, pid))
        # FINALER TRADEIFY GEHALTEN (29.10.2026): der DB-Trigger hat den Start verschoben (start_sperre art final_halten) → ⚪ einmal je Plan
        ss = p.get("ss") if isinstance(p.get("ss"), dict) else {}
        # HEDGE-TRADE OHNE FREIGABE (29.10.2026, trade_plans_a0_hedge_freigabe): ⚪ einmal je Plan
        if st == "planned" and ss.get("art") == "hedge_freigabe" and str(ss.get("at") or "") > seit_iso:
            if ss.get("wo") == "wd":   # APEX-WD BESTÄTIGEN (02.11.2026): Farmer-Winning-Day wartet im Funded-Planer → Winning Days
                out.append((f"{pid}|hedge_freigabe", 3, "hedge_freigabe", ("Recoverer" if wd_ist_recoverer_plan(dict(p, winning_day=True)) else "Apex-WD") + " wartet auf Bestätigung",
                            f"{wer} · {konto}: wartet auf deine Bestätigung (Admin → Funded-Planer → Winning Days → „Zu bestätigen“) — "
                            f"startet erst danach.", uid, pid))
            else:
                out.append((f"{pid}|hedge_freigabe", 3, "hedge_freigabe", "Hedge-Trade wartet auf Bestätigung",
                            f"{wer} · {konto}: wartet auf deine Bestätigung im Challenge-Planer (Admin → Challenge-Planer → „Zu bestätigen“ "
                            f"bzw. „Hedge-Freigabe offen“) — startet erst danach.", uid, pid))
        # ECHO OHNE HEDGE ABGELAUFEN (02.11.2026, trade_plans_a1_echo_hedge): nach 8 h gibt der Riegel auf, der Plan startet nicht mehr → ⚪ einmal je Plan
        if st == "planned" and ss.get("art") == "echo_hedge" and ss.get("status") == "aufgegeben" and str(ss.get("at") or "") > seit_iso:
            wann = "Startfenster zu Ende" if ss.get("ablauf") == "fenster" else "nach 8 h"
            out.append((f"{pid}|echo_hedge_ablauf", 3, "echo_hedge_ablauf", "Echo-Trade abgelaufen",
                        f"{wer} · {konto}: nicht gestartet ({wann}), {str(ss.get('text') or 'Echo-Hedge nicht rechenbar')[:160]} — Plan läuft ab, neu planen.", uid, pid))
        # APEX OHNE HEDGE GEHALTEN (30.10.2026, trade_plans_a1_apex_hedge): ⚪ einmal je Plan — nur, wenn ah_tick den Grund nicht schon selbst
        # gemeldet hat (_ah_ohne, apex_hedge.gemeldet), z. B. weil Railway den Plan noch nicht gesehen hat
        ahm = p.get("ahm") if isinstance(p.get("ahm"), dict) else {}
        if st == "planned" and ss.get("art") == "apex_hedge" and str(ss.get("at") or "") > seit_iso and not ahm.get("gemeldet"):
            nx = _alarm_ts(ss.get("naechster"))
            nx_txt = nx.astimezone(_ap_tz("Asia/Dubai")).strftime("%H:%M") if nx else "?"
            out.append((f"{pid}|apex_hedge", 3, "apex_hedge_ohne", f"{MODELL_NAME['orbit_prio2']} wartet auf Hedge",
                        f"{wer} · {konto}: {str(ss.get('text') or (MODELL_NAME['orbit_prio2'] + ' wartet auf Gegenhedge'))[:160]} — startet nie ohne Hedge, "
                        f"nächster Versuch {nx_txt} Dubai.", uid, pid))
        tfh = p.get("tfh") if isinstance(p.get("tfh"), dict) else {}
        if st == "planned" and ss.get("art") == "final_halten" and str(ss.get("at") or "") > seit_iso and not tfh.get("gemeldet"):
            nx = _alarm_ts(ss.get("naechster"))
            nx_txt = nx.astimezone(_ap_tz("Asia/Dubai")).strftime("%d.%m. %H:%M") if nx else "?"
            out.append((f"{pid}|final_halten", 3, "tradeify_final_halten", "Finaler Tradeify-Trade gehalten",
                        f"{wer} · {konto}: finaler Trade (TP {_wd_num(p.get('master_tp')) or '?'} $) startet nicht, bis die Gegenhedge-Logik steht — "
                        f"bleibt geplant, nächster Versuch {nx_txt} Dubai.", uid, pid))
        # NOVA OHNE SL/TP (29.10.2026): Start-Ergebnis meldet fehlende Brackets → 🔴 sofort (nächster Takt), Erinnerung alle 15 min, bis Puls/
        # Hand sie nachweist (tv.brackets_ok_at) oder der Plan nicht mehr läuft. Prophos beendet solche Pläne nie per Kurs-Schätzung.
        bf = tsx_brackets_fehlen(p.get("route"), {"brackets_fehlen": p.get("tv_bf"), "warnung": p.get("tv_w"), "brackets_ok_at": p.get("tv_ok"),
                                                   "bracket_dialog": p.get("tv_bd"), "bracket_dialog_bild": p.get("tv_bdb")})
        if st == "open" and bf:
            s = max((jetzt - start).total_seconds(), 0) if start else 0
            ri = str(p.get("richtung") or "").upper()
            kt = _wd_num(p.get("master_contracts"))
            menge = f"{ri + ' ' if ri in ('BUY', 'SELL') else ''}{('%g' % kt) if kt is not None else '?'}"
            ein = _wd_num(p.get("tv_ein"))
            preis = f"{ein:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".") if ein else "?"
            fehlt = " und ".join(x for x, ja in (("SL (Risk)", bf["risk"]), ("TP (To Make)", bf["tp"])) if ja)
            dlg = f" (Dialog „{bf['dialog']}“)" if bf.get("dialog") else ""
            # Fehlerfoto (S5): der Push öffnet Prophos mit …#fehlerbild=<pfad> → Radar + Bild (pulsFehlerbildZeigen, Admin-Bildroute)
            # höchstens 2 Meldungen je Plan (Triage 30.10.2026: Marc …0038 9× in 3 h) — erste sofort, eine Erinnerung nach 15 min
            out.append((f"{pid}|ohne_sltp|{min(int(s // ALARM_ERINNERN_S), 1)}", 1, "nova_ohne_sltp", f"{MODELL_NAME['nova']} ohne SL/TP",
                        f"{wer} · {konto}: {menge} @ {preis} — {fehlt} nicht gesetzt{dlg} — in TopstepX setzen." + (" Foto: antippen." if bf.get("bild") else ""),
                        uid, pid) + ((f"https://prophos.pages.dev/prophos#fehlerbild={bf['bild']}",) if bf.get("bild") else ()))
        # WIEDER OFFEN (29.10.2026): die Endlesung sah die Position nach dem Ende noch offen, der PC-Tab hat den Plan zurück auf open gesetzt
        # (final → final_verworfen). Einmal je Rückholung (Schlüssel mit Zeitpunkt), nur als Übergang nach seit_iso.
        fv = p.get("fv") if isinstance(p.get("fv"), dict) else {}
        fv_at = _alarm_ts(fv.get("verworfen_at"))
        if st == "open" and fv_at and fv_at > (_alarm_ts(seit_iso) or jetzt):
            out.append((f"{pid}|wieder_offen|{fv.get('verworfen_at')}", 1, "plan_wieder_offen", "Position noch offen — Plan wieder läuft",
                        f"{wer} · {konto}: Prophos hatte den Trade beendet ({str(fv.get('grund') or fv.get('quelle') or '?')[:30]}), die "
                        f"Endlesung sieht die Position noch offen — Plan wieder unter Läuft. In {'TopstepX' if p.get('route') == 'tsv2' else 'TradingView'} "
                        f"prüfen und schließen.", uid, pid))
        # ABGLEICH (AB1, 10.11.2026): Ergebnis des PC-Tab-Abgleichs Master ↔ Hedge — nur als Übergang nach seit_iso
        ab = p.get("ab") if isinstance(p.get("ab"), dict) else {}
        ab_st, ab_at = ab.get("status"), str(ab.get("at") or "")
        if ab_st and ab_st in ALARM_ABGLEICH and ab_at > seit_iso:
            prio_ab, titel_ab = ALARM_ABGLEICH[ab_st]
            out.append((f"{pid}|abgleich|{ab_st}|{ab_at[:13]}", prio_ab, f"abgleich_{ab_st}", titel_ab,
                        f"{wer} · {konto}: {str(ab.get('msg') or ab_st)[:240]}", uid, pid))
        if hst == "geschlossen" and h.get("grund") in ALARM_RADAR_GRUENDE and str(h.get("closed_at") or "") > seit_iso:
            # Text nur, wenn er stimmt (Auswertung 30.10.2026: bei 2 von 3 Radar-Alarmen hatte das Userscript das Ende gesehen, der Beweis lehnte ab)
            rkn = h.get("reader_kurz_nein") if isinstance(h.get("reader_kurz_nein"), dict) else None
            warum = (f"das Userscript sah das Master-Ende, Schluss abgelehnt: {str(rkn.get('grund') or '?')[:80]}" if rkn
                     else "das Userscript hat das Master-Ende nicht zuerst gesehen (Puls im falschen Konto / Tab zu?)")
            out.append((f"{pid}|radar", 2, "radar_schloss", "Radar hat geschlossen",
                        f"{wer} · {konto}: Radar hat den Hedge {ALARM_RADAR_GRUENDE[h.get('grund')]} geschlossen — {warum}.", uid, pid))
        # BALANCE NUR NOCH NACHKONTROLLE (30.10.2026, Finn „Idee 1"; „4 Punkte ist ja gar nichts, lieber 10, 15, 20 Punkte"): gekürztes Konto, Hedge zu, obwohl der Balance-Beweis
        # durchfiel oder fehlte (hedge.reader_kurz.ok false, prophos.html kurzEndeBeweis). Ausstieg > 20 Pkt neben dem Kurs-Fenster → 🔴, könnte ein Hand-Wechsel aufs Nachbarkonto sein;
        # ≤ 20 Pkt → still; nicht rechenbar (Balance fehlt, 5 von 9 am 30.10.) → nur 🟠. Einmal je Plan
        rk = h.get("reader_kurz") if isinstance(h.get("reader_kurz"), dict) else None
        # Master DOCH noch offen (Gegenprüfung 30.10.2026): Plan mit Hedge holt die Endlesung nie zurück (tvV2NochOffenRegel), Puls sieht die Position aber zweimal offen → 🔴, einmal je Plan
        if hst == "geschlossen" and rk and rk.get("ok") is False and st == "review" and (_wd_num(p.get("puls_offen_n")) or 0) >= 2:
            out.append((f"{pid}|kurz_master_offen", 1, "kurz_master_offen", "Hedge zu, Master noch offen",
                        f"{wer} · {konto}: Hedge ist zu (Balance-Nachkontrolle nicht bestanden), Puls sieht die Master-Position noch offen — sofort von Hand prüfen und schließen.", uid, pid))
        if hst == "geschlossen" and rk and rk.get("ok") is False and str(h.get("closed_at") or "") > seit_iso:
            ex, lo, hi = _wd_num(rk.get("exit")), _wd_num(rk.get("lo")), _wd_num(rk.get("hi"))
            if ex is None or lo is None or hi is None:
                out.append((f"{pid}|kurz_balance", 2, "kurz_balance_fehlt", "Hedge zu, Balance nicht geprüft",
                            f"{wer} · {konto}: Hedge geschlossen, die Balance-Nachkontrolle ging nicht: {str(rk.get('grund') or '?')[:80]}.", uid, pid))
            elif max(lo - ex, ex - hi) > 20.0:
                out.append((f"{pid}|kurz_balance", 1, "kurz_balance_nein", "Hedge zu, Balance passt nicht",
                            f"{wer} · {konto}: Hedge geschlossen, Balance passt nicht zum Ausstieg: {ex:.2f} liegt {max(lo - ex, ex - hi):.1f} Pkt neben dem Kurs-Fenster {lo:.2f}–{hi:.2f}"
                            f"{' (Balance ' + str(rk.get('b1')) + ')' if rk.get('b1') is not None else ''} — von Hand prüfen, ob der Master noch läuft.", uid, pid))
    return out


def alarm_im_log_filter(keys):
    """REIN RECHNEND (testbar): PostgREST-Filter schluessel=in.("…","…") — Schlüssel in Anführungszeichen (sie tragen „|"), ohne Anführungszeichen und Backslash."""
    ks = sorted({str(k) for k in keys or () if k and '"' not in str(k) and "\\" not in str(k)})
    return "in.(" + ",".join(f'"{k}"' for k in ks) + ")" if ks else None


def alarm_im_log(keys, seit_s):
    """Welche dieser Schlüssel stehen in den letzten seit_s Sekunden schon im alarm_log? → set; Lesefehler → None (der Aufrufer sendet dann
    wie bisher — lieber doppelt als eine 🔴 verschluckt). Triage 30.10.2026: die Merker _alarm["gemeldet"] / _SKRIPT_WACHT lagen nur im
    Speicher, jeder Railway-Neustart meldete dasselbe erneut (userscript_alt 4 Wellen am 29.10., Nova ohne SL/TP 9× für einen Plan)."""
    filt = alarm_im_log_filter(keys)
    if not filt:
        return set()
    try:
        ab = datetime.fromtimestamp(time.time() - seit_s, timezone.utc).isoformat()
        rows = _sb_all("alarm_log", {"select": "schluessel", "schluessel": filt, "at": f"gte.{ab}"}) or []
        return {str(r.get("schluessel")) for r in rows if r.get("schluessel")}
    except Exception as e:
        print(f"[alarm] ⚠️ alarm_log nicht lesbar ({type(e).__name__}) — Entprellung nur im Speicher", flush=True)
        return None


def alarm_tick():
    """Weg (b), Railway-Takt (ap_loop): einmal je Minute die Pläne der HT-IDs lesen und melden, was alarm_ereignisse findet."""
    if time.time() - _alarm["at"] < ALARM_TAKT_S or not _alarm_empfaenger():
        return
    _alarm["at"] = time.time()
    jetzt = datetime.now(timezone.utc)
