    w0 = _wd_num(d.get("wartete_s"))
    wartete = int(min(max(w0, 0), 86400)) if (w0 is not None and w0 == w0 and abs(w0) != float("inf")) else 0
    wer_txt = f"{namen.get(uid, uid[:8])}" + (f" · {pc}" if pc else "")
