def wd_sl_fest_fuer_plan(spanne, plan, acc, liq_regeln, fruehere, rnd=None):
    """REIN RECHNEND (testbar, FT2 + Prüfer MUSS 1/SOLLTE 1): fester SL eines WD-Plans — FAIL-CLOSED. Jede Unsicherheit → sperre (kein Plan bzw. kein Start):
    Konto nicht gelesen, liq_regeln fehlen, Balance seit dem letzten Trade nicht nachgelesen, ein früherer Trade DESSELBEN CME-Tags ohne Start-Balance (dann ist
    der Tagesstart unbekannt und das Daily Loss nicht sicher messbar), Puffer unbekannt oder zu klein (wd_sl_fest). sperre_art 'daten' (nächster Takt versucht es
    wieder) | 'puffer' (heute nichts mehr). Sonst wie wd_sl_fuer_plan: Puffer aus hf_wd_master_verlust (Tagesstart → Tagesgrenze)."""
    lo, hi = float(spanne[0]), float(spanne[1])

    def zu(grund, art="daten"):
        return {"ohne": True, "sperre": True, "sperre_art": art, "stufe": None, "pct": None, "usd": None, "puffer": None, "balance": None, "liq_balance": None,
                "regel": "sl_fest", "spanne": [lo, hi], "grund": f"fester SL {lo:.0f}–{hi:.0f} $: {grund} — kein Plan (Daily Loss = Hard Breach)"}
    if fruehere is None:
        # FT2c (Prüfer S2 zu KK1b): _wd_sl_kontext/_wd_fruehere_trades(streng) liefern bei unlesbaren früheren Trades None — das ist NICHT „keine früheren Trades“
        # (sonst Tagesstart = Balance jetzt → womöglich falscher Puffer). Art „daten“ → POST übersprungen mit WD_GRUND_SL_DATEN, nächster Lauf versucht es wieder
        return zu(WD_SL_GRUND_FRUEHER)
    if not acc:
        return zu("Konto-Daten nicht lesbar")
    if not liq_regeln:
        return zu("liq_regeln nicht geladen")
    bal, bal_grund = wd_sl_balance(acc, fruehere)
    if bal is None:
        return zu(bal_grund or "keine Balance")
    st = str((plan or {}).get("started_at") or (plan or {}).get("start_um") or "")
    tag = _cme_handelstag(st) if st else None
    aid = str(acc.get("id") or "")
    if tag and any(str(f.get("master_account_id") or "") == aid and f.get("started_at") and str(f["started_at"]) < st and _cme_handelstag(f["started_at"]) == tag
                   and _wd_num(f.get("bal_start")) is None for f in fruehere or ()):
        return zu("früherer Trade heute ohne Start-Balance — Tagesstart unbekannt")
    acc2 = dict(acc, tv_balance=bal)
    mv = hf_wd_master_verlust(liq_regeln, acc2, dict(plan or {}, konto_typ="winning_days", winning_day=True), None, fruehere)
    puffer = _wd_num(mv.get("usd"))
    liq = round(bal - puffer, 2) if puffer is not None else None
    w = wd_sl_fest([lo, hi], puffer, bal, liq, rnd=rnd, grund=mv.get("grund"))
    if w.get("sperre"):
        w["sperre_art"] = "daten" if puffer is None else "puffer"
    return w


def wd_sl_fest(spanne, puffer, balance=None, liq_balance=None, rnd=None, grund=None):
    """REIN RECHNEND (testbar, FT2): fester SL einer Firma → mt5_baseline.wd_sl. $ gleichverteilt in spanne [von, bis] (ganze $), gekappt auf
    Puffer − WD_SL_FEST_LIQ_PUFFER. Puffer unbekannt/≤ 0 oder gekappter SL < WD_SL_FEST_MIN_USD → {ohne: True, sperre: True, grund} (kein Plan)."""
    rnd = rnd or random
    lo, hi = float(spanne[0]), float(spanne[1])
    p = _wd_num(puffer)
    out = {"ohne": True, "stufe": None, "pct": None, "usd": None, "puffer": (round(p, 2) if p is not None else None), "balance": _wd_num(balance),
           "liq_balance": _wd_num(liq_balance), "regel": "sl_fest", "spanne": [lo, hi]}
    if p is None or p <= 0:
        return dict(out, sperre=True, grund=f"fester SL {lo:.0f}–{hi:.0f} $: Puffer bis zur Tagesgrenze unbekannt ({grund or 'kein gültiger Puffer'}) — kein Plan")
    usd = int(lo + rnd.random() * (hi - lo) + 0.5)
    usd = min(max(usd, int(lo)), int(hi))
    deckel = int(p - WD_SL_FEST_LIQ_PUFFER)
    gekappt = usd > deckel
    if gekappt:
        usd = deckel
    if usd < WD_SL_FEST_MIN_USD:
        return dict(out, sperre=True, grund=f"fester SL {lo:.0f}–{hi:.0f} $: nur {p:,.0f} $ bis zur Tagesgrenze — kein Plan (Daily Loss = Hard Breach)".replace(",", "."))
    return dict(out, ohne=False, usd=usd, gekappt=gekappt,
                grund=(f"auf {usd} $ gekappt (Puffer {p:,.0f} $ − {WD_SL_FEST_LIQ_PUFFER:.0f} $)".replace(",", ".") if gekappt else None))


def wd_sl_wuerfeln(regel, puffer, balance=None, liq_balance=None, rnd=None, grund=None):
    """REIN RECHNEND (testbar, Zufallsquelle rnd mit .random() injizierbar): → mt5_baseline.wd_sl | None (regel None = Würfel aus, nichts schreiben).
    Erst die Stufe nach Anteil, dann — nur bei einer SL-Stufe mit gültigem Puffer (> 0) — pct in [von, bis] zufällig (1 Nachkommastelle),
    usd = Puffer × pct auf ganze $ (kaufmännisch). Ohne SL: ohne=True, pct/usd None, grund nennt warum (gewürfelt / Puffer ungültig, grund vom Aufrufer)."""
    if not regel:
        return None
    rnd = rnd or random
    p = _wd_num(puffer)
    out = {"ohne": True, "stufe": None, "pct": None, "usd": None, "puffer": (round(p, 2) if p is not None else None),
           "balance": _wd_num(balance), "liq_balance": _wd_num(liq_balance), "regel": "sl_wuerfel"}
    stufen = regel.get("stufen") or []
    w, kum, idx = rnd.random() * 100.0, 0.0, None
    for i, s in enumerate(stufen):
        kum += s["anteil"]
        if w < kum:
            idx = i
            break
    if idx is None:                                   # Rundungsrest am oberen Ende: letzte Stufe mit Anteil > 0
        idx = max((i for i, s in enumerate(stufen) if s["anteil"] > 0), default=None)
    if idx is None:
        out["grund"] = "keine Stufe mit Anteil > 0"
        return out
    s, out["stufe"] = stufen[idx], idx
    if s.get("von") is None:
        out["grund"] = "gewürfelt: ohne SL"
        return out
    if p is None or p <= 0:
        out["grund"] = grund or "kein gültiger Puffer (Balance − Liq ≤ 0 oder unbekannt)"
        return out
    pct = round(s["von"] + rnd.random() * (s["bis"] - s["von"]), 1)
    pct = min(max(pct, s["von"]), s["bis"])
    usd = int(p * pct / 100.0 + 0.5)
    if usd < 1:
        out["grund"] = f"SL {pct} % von {p:.2f} $ unter 1 $"
        return out
    out.update(ohne=False, pct=pct, usd=usd)
    return out


def wd_sl_balance(acc, fruehere, null_basiert=False):
    """REIN RECHNEND (testbar): Balance vor dem neuen WD-Trade → (wert | None, grund). Prüfer WS1a 09.11.2026: tv_balance gilt nur, wenn sie NACH dem Ende des
    letzten Trades dieses Kontos gelesen wurde (wie hedgeLiqLevel im Tab); sonst die End-Balance dieses Trades (final.balance_end), fehlt die → unbekannt
    (Plan um 02:00 nach einem Verlusttag, Nachlesung steht aus — der Puffer wäre um dessen P&L verschoben). fruehere = _wd_fruehere_trades."""
    a = acc or {}
    tvb, tv_at = _wd_num(a.get("tv_balance")), str(a.get("tv_balance_at") or "")
    aid = str(a.get("id") or "")
    letzt = max((f for f in fruehere or () if str(f.get("master_account_id") or "") == aid and f.get("ended_at")),
                key=lambda f: str(f["ended_at"]), default=None)
    if letzt is not None and (not tv_at or tv_at <= str(letzt["ended_at"])):
        be = _wd_num(letzt.get("bal_end"))
        if be is not None and (be > 0 or null_basiert):   # TX2: Topstep Express zählt 0-basiert, dort sind 0 und negativ echte Stände
            return be, None
        return None, "Balance seit dem letzten Trade nicht nachgelesen — Puffer unbekannt"
    if tvb is None or (tvb <= 0 and not null_basiert):
        return None, "keine Balance am Konto"
    if null_basiert and not tv_at:
        return None, "keine gelesene Balance am Konto"   # 0-basiert: ohne Lesezeit könnte 0 auch „nie gelesen“ heißen
    return tvb, None


TX2_MLL_VOR = 100.0    # wie der WD-Hedge (hedgeLiqLevel tsv2: Liquidation = MLL + 100 $)


def wd_sl_express_mll(acc, fruehere, bal=None):
    """REIN RECHNEND (testbar, TX2 10.11.2026, Master: „Topstep Express in den WD-Zufalls-SL aufnehmen“): MLL eines Topstep-Express-Kontos (XFA, TopstepX zeigt
    es 0-basiert) aus BELEGTEN Werten → (mll, quelle) | (None, grund). Wie ap_kette_mll_belegt, nur 0-basiert:
      (1) jüngste TopstepX-Lesung tv.mll_start dieses Kontos (Puls liest sie bei jedem Start mit; nur 0-basierte Werte < 1.000 — absolute fallen raus),
      (2) „MLL lieber zu hoch“: JEDE bekannte Schluss-Balance (bal_end) − Max DD liegt nie über der echten MLL (die zieht am Tagesschluss vom Hochpunkt nach) →
          MLL = max(Lesung, max(bal_end) − Max DD), höchstens 0 (die XFA-MLL hört am Startwert 0 auf — belegt: alle Express-WD-Konten lesen 0).
          Gegenprüfung TX2 10.11.2026: zuerst zählten nur abgeschlossene CME-Tage NACH der Lesung — die Planung um 02:00 Dubai (22:00 UTC, noch CME-Tag D) für
          Starts an D+1 sah den Tagesschluss von D nicht; bei großen Würfel-Stufen lag der SL dann hinter der echten MLL. Auch der laufende Tag und Trades vor
          der Lesung zählen jetzt mit (zu hoch ist sicher, nur der Puffer wird kleiner); nachgezogen wird nur nach oben.
          bal = die für den Puffer benutzte Balance (Prüfer TX2, Empfehlung a): zählt wie ein Schluss NACH der Lesung — ein Gewinn- oder Hand-Trade ohne
          bal_end, der den Stand hob, zieht die MLL damit trotzdem nach.
    Ohne Lesung → unbekannt (kein Raten über Größe/Hochpunkt); Schluss-Balance nach der Lesung, aber Max DD fehlt → unbekannt."""
    a = acc or {}
    aid = str(a.get("id") or "")
    dd = _wd_num(a.get("max_drawdown"))

    def _t(x):
        try:
            t = datetime.fromisoformat(str(x).replace("Z", "+00:00").replace(" ", "T"))
            return t if t.tzinfo else t.replace(tzinfo=timezone.utc)
        except Exception:
            return None
    lesung, lesung_at, schluss = None, None, []
    for f in fruehere or ():
        if str(f.get("master_account_id") or "") != aid:
            continue
        m, st = _wd_num(f.get("mll_start")), _t(f.get("started_at"))
        if m is not None and m < 1000 and st and (lesung_at is None or st > lesung_at):
            lesung, lesung_at = float(m), st
        be = _wd_num(f.get("bal_end"))
        if be is not None:
            schluss.append((_t(f.get("ended_at")), be))
    if lesung is None:
        return None, "Topstep Express — noch keine MLL-Lesung aus TopstepX (Puls liest sie beim ersten Start mit)"
    if _wd_num(bal) is not None:
        schluss.append((None, float(_wd_num(bal))))   # ohne Zeit = jetzt, also nach der Lesung
    quelle = f"TopstepX-MLL {lesung:,.0f} $ (Lesung {lesung_at.strftime('%d.%m. %H:%M')} UTC)".replace(",", ".")
    if schluss:
        if dd is None or dd <= 0:
            # ohne Max DD nicht nachziehbar: nach der Lesung (oder ohne Zeit) geschlossen → unbekannt; nur ältere Schlüsse → steckten schon in der Lesung
            if any(en is None or en > lesung_at for (en, _be) in schluss):
                return None, "Topstep Express — Max DD am Konto fehlt, MLL nach der Lesung nicht nachziehbar"
        else:
            neu = min(0.0, max(be for (_en, be) in schluss) - float(dd))
            if neu > lesung:
                return round(neu, 2), f"MLL {neu:,.0f} $ = höchste Schluss-Balance − Max DD, über der {quelle}".replace(",", ".")
    return round(min(lesung, 0.0), 2), quelle


WD_SL_GRUND_FRUEHER = "frühere Trades nicht lesbar — Puffer unbekannt"
WD_SL_FRUEHER_WARTE_S = (1.0, 3.0)          # KK1b: Pause vor dem einen Wiederholungsversuch (_wd_sl_kontext)
WD_SL_FRUEHER_NAECHSTER = " — nächster Lauf"  # Zusatz am Übersprungen-Grund im POST /admin/wd-plaene


def wd_sl_fuer_plan(regel, plan, acc, liq_regeln, fruehere, rnd=None):
    """REIN RECHNEND (testbar): wd_sl eines neuen WD-Plans → dict | None (Würfel aus). Puffer = hf_wd_master_verlust (Balance tv_balance − Liq wie Radar
    und WD-Hedge, Daily Loss ab Tagesstart bei Apex). Topstep Express (TX2, 10.11.2026): Liq = MLL aus TopstepX (wd_sl_express_mll) + 100 $ wie der WD-Hedge,
    Balance 0-basiert wie TopstepX (wd_sl_balance) — fehlt eins davon → ohne SL mit Grund."""
    if not regel:
        return None
    if not acc:
        return wd_sl_wuerfeln(regel, None, rnd=rnd, grund="Konto-Daten nicht lesbar — Puffer unbekannt")
    if fruehere is None:
        # KK1: frühere Trades nicht lesbar (_wd_sl_kontext) — ohne sie fehlen Tagesstart-Balance/MLL-Start; wie „Konto-Daten nicht lesbar“: lieber kein SL
        return wd_sl_wuerfeln(regel, None, _wd_num(acc.get("tv_balance")), rnd=rnd, grund=WD_SL_GRUND_FRUEHER)
    if ist_topstep_express(acc):
        # Prüfer TX2 (Empfehlung a, 10.11.2026): die Puffer-Balance zählt mit ins MLL-Nachziehen (Gewinn-/Hand-Trade ohne bal_end hob den Stand) —
        # sonst hinge die Sicherheit nur an der Stufen-Obergrenze (DB-änderbar). Reihenfolge der Gründe wie bisher: erst MLL-Lesung, dann Balance.
        bal, bal_grund = wd_sl_balance(acc, fruehere, null_basiert=True)
        mll, mll_text = wd_sl_express_mll(acc, fruehere, bal)
        if mll is None:
            return wd_sl_wuerfeln(regel, None, _wd_num(acc.get("tv_balance")), rnd=rnd, grund=mll_text)
        if bal is None:
            return wd_sl_wuerfeln(regel, None, rnd=rnd, grund=bal_grund)
        liq = round(mll + TX2_MLL_VOR, 2)
        w = wd_sl_wuerfeln(regel, round(bal - liq, 2), bal, liq, rnd=rnd,
                           grund=f"Topstep Express — Balance {bal:,.2f} $ an/unter MLL + 100 ({liq:,.2f} $)".replace(",", "X").replace(".", ",").replace("X", "."))
        if isinstance(w, dict):
            w["liq_quelle"] = mll_text
        return w
    # Prüfer WS1a: ohne geladene liq_regeln fiele die Rechnung auf Größe + 100 zurück — bei Apex läge der SL dann hinter dem Daily Loss
    if not liq_regeln:
        return wd_sl_wuerfeln(regel, None, _wd_num(acc.get("tv_balance")), rnd=rnd, grund="liq_regeln nicht geladen — Puffer unbekannt")
    bal, bal_grund = wd_sl_balance(acc, fruehere)
    if bal is None:
        return wd_sl_wuerfeln(regel, None, rnd=rnd, grund=bal_grund)
    acc = dict(acc, tv_balance=bal)
    mv = hf_wd_master_verlust(liq_regeln, acc, dict(plan or {}, konto_typ="winning_days", winning_day=True), None, fruehere)
    bal, puffer = _wd_num(acc.get("tv_balance")), _wd_num(mv.get("usd"))
    liq = round(bal - puffer, 2) if (bal is not None and puffer is not None) else None
    return wd_sl_dll_pflicht(wd_sl_wuerfeln(regel, puffer, bal, liq, rnd=rnd, grund=mv.get("grund")), mv)


WD_GRUND_DLL_OHNE_SL = "Tageslimit-Firma: kein WD-Plan ohne SL"   # DL2b: Übersprungen-Grund (Präfix) im POST /admin/wd-plaene


def wd_sl_dll_firma(regeln, acc):
    """REIN RECHNEND (testbar, DL2b 11.11.2026, Master/Finn: Firmen MIT Tageslimit — Lucid 2.700, FTMO Futures 1.000 — bekommen nie einen WD-Plan ohne SL; Firmen
    ohne (Tradeify: „nie ein Daily Loss Limit“, Apex mit Stufen-Regel) bleiben wie heute). → True | False | None (unbekannt: Konto oder Regeln fehlen).
    True: Konto dll_usd > 0, sonst liq_regeln-Zeile der Kontoart winning_days mit art 'tagesstart', hat die WD-Zeile kein Tageslimit (boden), die Funded-Zeile
    derselben Firma/Größe mit 'tagesstart' (wie hedgeLiqDll im Tab). dll_usd 0 → False. 'stufen' (Apex) zählt hier bewusst nicht."""
    if not acc:
        return None
    kd = _wd_num(acc.get("dll_usd"))
    if kd is not None:
        return kd > 0
    if not regeln:
        return None
    firma, gr = acc.get("firm"), _wd_konto_groesse(acc)
    r = liq_regel_waehlen(regeln, firma, "winning_days", gr)[0]
    art = (r or {}).get("art")
    if art in ("tagesstart", "stufen"):
        return liq_dll_schutz(r)        # DL2-Schalter: tagesstart an, stufen (Apex) nur mit dll_schutz true
    if art in (None, "boden"):
        rf = liq_regel_waehlen(regeln, firma, "funded", gr)[0]
        return (rf or {}).get("art") in ("tagesstart", "stufen") and liq_dll_schutz(rf)
    return False


WD_SL_DLL_PUFFER = 100.0    # DL2: so weit vor dem Tageslimit sitzt der Pflicht-SL (Gebühren/Schlupf; Tradeify zählt die Kommission mit)


def wd_sl_dll_pflicht(w, mv):
    """REIN RECHNEND (testbar, DL2 11.11.2026, Master: „WD ohne SL … trotzdem ein SL knapp vor dem DLL“; Fall …0887: WD ohne SL, Tradeify schloss den Master am Daily
    Loss): hat der Würfel „ohne SL“ ergeben und ist der Puffer ein Tageslimit (mv.art daily_loss, Soft Breach — die Firma schließt den Master), bekommt der Plan
    einen SL = Puffer − WD_SL_DLL_PUFFER. Darunter WD_SL_FEST_MIN_USD → bleibt ohne (der Fusion-Hedge schließt am DLL-Level). Sonst unverändert."""
    if not isinstance(w, dict) or not w.get("ohne") or w.get("sperre") or (mv or {}).get("art") != "daily_loss" or (mv or {}).get("dll_schutz") is not True:
        return w   # DL2-Schalter: ohne dll_schutz (Apex 'stufen' ohne Freigabe) wie vor DL2
    p = _wd_num((mv or {}).get("usd"))
    if p is None:
        return w
    usd = int(p - WD_SL_DLL_PUFFER)
    if usd < WD_SL_FEST_MIN_USD:
        return dict(w, grund=f"{w.get('grund') or 'ohne SL'} — Daily Loss nur {p:,.0f} $ entfernt, kein Pflicht-SL".replace(",", "."))
    return dict(w, ohne=False, usd=usd, pflicht_dll=True,
                grund=f"ohne SL gewürfelt — Daily Loss: SL {usd} $ = {p:,.0f} $ bis zum Tageslimit − {WD_SL_DLL_PUFFER:.0f} $".replace(",", "."))


def _wd_sl_wuerfel_lesen():
    """wd_farmer_regeln.sl_wuerfel (id 1) → (regel | None, quelle). Spalte fehlt (SQL nicht eingespielt) oder Lesefehler → (None, 'aus') = wie bisher kein SL."""
    try:
        rows = sb_select("wd_farmer_regeln", {"select": "sl_wuerfel", "id": "eq.1"}) or []
    except Exception as e:
        if "sl_wuerfel" not in str(getattr(getattr(e, "response", None), "text", "") or e):
            print(f"[wd-sl-wuerfel] ⚠️ nicht lesbar ({type(e).__name__}: {str(e)[:120]}) — Würfel aus", flush=True)
        return None, "aus"
    return wd_sl_wuerfel_regel(rows[0].get("sl_wuerfel") if rows else None)


def _wd_sl_konten_select(params):
    """accounts für den WD-SL mit DL2-Konto-Limit dll_usd (11.11.2026); fehlt die Spalte noch (sql/2026-11-11_dl2_konto_dll.sql nicht eingespielt) → ohne sie wie bisher."""
    try:
        return sb_select("accounts", dict(params, select=params["select"] + ",dll_usd"))
    except Exception as e:
        if "dll_usd" not in str(getattr(getattr(e, "response", None), "text", "") or e):
            raise
        return sb_select("accounts", params)


def _wd_sl_kontext(mids, mit_fest=False):
    """Einmal je POST /admin/wd-plaene: (regel, konten {id: acc}, liq_regeln, fruehere). Würfel aus → (None, {}, [], []). Fehlen die Konto-Daten,
    bleibt die Regel an und jeder Plan bekommt ohne=True mit Grund (lieber kein SL als einer ohne belegten Puffer). mit_fest (FT2): feste SL je Firma
    eingerichtet → Konten/Liq/Trades auch bei ausgeschaltetem Würfel laden (der feste SL sperrt ohne Daten, statt still ohne SL zu planen)."""
    regel, _q = _wd_sl_wuerfel_lesen()
    if (not regel and not mit_fest) or not mids:
        return regel, {}, [], []
    konten = {}
    try:
        for i in range(0, len(mids), 80):
            for a in _wd_sl_konten_select({"select": "id,name,firm,account_type,starting_balance,external_id,max_drawdown,max_daily_drawdown,"
                                                      "tv_balance,tv_balance_at", "id": "in.(" + ",".join(mids[i:i + 80]) + ")"}) or []:
                konten[str(a.get("id"))] = a
    except Exception as e:
        print(f"[wd-sl-wuerfel] ⚠️ Konten nicht lesbar ({type(e).__name__}) — diese Pläne ohne SL", flush=True)
        return regel, {}, [], []
    fruehere = None
    for versuch in range(2):
        try:
            fruehere = _wd_fruehere_trades(mids, streng=True)
            break
        except Exception:
            # KK1b (S2-Stopp, 11.11.2026): ein kurzer Aussetzer um 01:30 soll nicht alle WDs kosten — EINMAL nach 1–3 s (gestreut, Puls-Jitter-Regel) neu lesen
            if versuch == 0:
                time.sleep(random.uniform(*WD_SL_FRUEHER_WARTE_S))
    # weiter nicht lesbar → None: POST /admin/wd-plaene legt gewürfelte Pläne dann NICHT an (DL2-Linie: kein WD-Plan ohne belegten SL-Puffer)
    return regel, konten, _liq_regeln_laden(), fruehere


