def _wd_sl_ohne(grund):
    return {"ohne": True, "stufe": None, "pct": None, "usd": None, "puffer": None, "balance": None, "liq_balance": None, "regel": "sl_wuerfel", "grund": grund}


def wd_sl_nach_kandidat(p, jetzt):
    """REIN RECHNEND (testbar): darf SL1 diesen Plan nachwürfeln? Farmer-Plan, geplant, nie geclaimt/gestartet/gesendet, wd_sl noch der Tab-Rückfall,
    keine frische Sperr-Marke sl_lauf_at eines laufenden Hand-/Fern-Starts, Start mindestens WD_SL_NACH_VORLAUF_S entfernt."""
    p = p or {}
    bl = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    ws = bl.get("wd_sl") if isinstance(bl.get("wd_sl"), dict) else {}
    if p.get("status") != "planned" or not str(p.get("notes") or "").startswith("Winning-Day-Farmer") or ws.get("grund") != WD_SL_RUECKFALL_GRUND:
        return False
    if p.get("start_um_gestartet_at") or p.get("started_at") or p.get("orbit_gesendet_at"):
        return False
    lauf = _ap_ts(bl.get("sl_lauf_at"))
    if lauf and (jetzt - lauf).total_seconds() < WD_SL_NACH_SPERRE_S:
        return False                                 # ein Hand-/Fern-Start läuft gerade (Sperr-Marke des Tabs)
    st = _ap_ts(p.get("start_um"))
    return bool(st and (st - jetzt).total_seconds() >= WD_SL_NACH_VORLAUF_S)


def wd_sl_nach_rechnen(regel, p, acc, liq_regeln, fruehere, rnd=None, jetzt_iso=None):
    """REIN RECHNEND (testbar): neues wd_sl (+ master_sl | None) für einen Rückfall-Plan — genau wie POST /admin/wd-plaene: Recoverer/Ausgleich ohne Würfel,
    sonst wd_sl_fuer_plan; Rechenfehler → ohne SL mit Grund. Markiert die Herkunft (quelle 'nachgewuerfelt', at). Der Grund ist danach nie mehr der Rückfall."""
    p = p or {}
    bl = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    if wd_ist_recoverer_plan(p):
        ws = _wd_sl_ohne("Recoverer — kein Würfel")
    elif bl.get("wd_ausgleich") is True:
        ws = _wd_sl_ohne("Ausgleich — kein Würfel")
    else:
        try:
            ws = wd_sl_fuer_plan(regel, p, acc, liq_regeln, fruehere, rnd=rnd)
        except Exception as e:
            ws = _wd_sl_ohne(f"Rechenfehler ({type(e).__name__})")
    if not ws:
        return None, None
    ws = dict(ws, quelle="nachgewuerfelt", nach_at=jetzt_iso)
    if ws.get("grund") == WD_SL_RUECKFALL_GRUND:
        ws["grund"] = "nachgewürfelt: ohne SL"
    usd = ws.get("usd") if (not ws.get("ohne") and ws.get("usd")) else None
    return ws, usd


def wd_sl_nach_tick(jetzt=None, rnd=None):
    """SL1-Takt: Rückfall-Pläne der Tabs nachwürfeln → {geaendert: [...], gewuerfelt, ohne, uebersprungen} | {aus: True}."""
    jetzt = jetzt or datetime.now(timezone.utc)
    regel, _q = _wd_sl_wuerfel_lesen()
    fest = _wd_sl_fest_lesen() if "_wd_sl_fest_lesen" in globals() else {}   # FT2: feste SL je Firma auch bei Würfel aus; get: ältere Selftest-Lader
    if not regel and not fest:
        return {"aus": True}
    rows = sb_select("trade_plans", {"select": "*", "status": "eq.planned", "mt5_baseline->wd_sl->>grund": f"eq.{WD_SL_RUECKFALL_GRUND}",
                                     "start_um_gestartet_at": "is.null", "started_at": "is.null",
                                     "start_um": "gte." + (jetzt + timedelta(seconds=WD_SL_NACH_VORLAUF_S)).isoformat(), "limit": "200"}) or []
    rows = [p for p in rows if wd_sl_nach_kandidat(p, jetzt)]
    out = {"geaendert": [], "gewuerfelt": 0, "ohne": 0, "uebersprungen": []}
    if not rows:
        return out
    mids = sorted({str(p.get("master_account_id") or "") for p in rows} - {""})
    konten = {}
    try:
        for i in range(0, len(mids), 80):
            for a in _wd_sl_konten_select({"select": "id,name,firm,account_type,starting_balance,external_id,max_drawdown,max_daily_drawdown,"
                                                      "tv_balance,tv_balance_at", "id": "in.(" + ",".join(mids[i:i + 80]) + ")"}) or []:
                konten[str(a.get("id"))] = a
        liq = _liq_regeln_laden()
        frueher = _wd_fruehere_trades(mids, streng=True)    # KK1: Lesefehler → dieser Takt schreibt nichts (except unten)
    except Exception as e:
        out["fehler"] = f"Konto-/Liq-Daten oder frühere Trades nicht lesbar ({type(e).__name__}) — nächster Takt"
        return out
    if not liq:
        out["fehler"] = "liq_regeln nicht geladen — nächster Takt"
        return out
    jetzt_iso = jetzt.isoformat().replace("+00:00", "Z")
    for p in rows:
        pid = str(p["id"])
        acc = konten.get(str(p.get("master_account_id") or ""))
        if acc is None:
            out["uebersprungen"].append({"id": pid, "grund": "Konto nicht gelesen"})
            continue
        _fest = wd_sl_fest_schluessel(fest, acc) if fest else None
        if _fest:
            # FT2 (Prüfer MUSS 3): fester SL fail-closed. Daten unklar → nichts schreiben (nächster Takt); Puffer zu klein → Grund schreiben, master_sl bleibt leer —
            # der DB-Riegel trade_plans_wd_sl_pflicht lässt den Plan dann nicht starten
            try:
                ws = wd_sl_fest_fuer_plan(_fest["usd"], p, acc, liq, frueher, rnd=rnd)
            except Exception as e:
                out["uebersprungen"].append({"id": pid, "grund": f"fester SL: {type(e).__name__} — nächster Takt"})
                continue
            if ws.get("sperre") and ws.get("sperre_art") != "puffer":
                out["uebersprungen"].append({"id": pid, "grund": ws.get("grund")})
                continue
            ws = dict(ws, quelle="nachgewuerfelt", nach_at=jetzt_iso)
            usd = None if ws.get("sperre") else ws.get("usd")
            if ws.get("sperre"):
                # Prüfer 2 SOLLTE 2: Puffer heute zu klein → den Plan VERBRAUCHEN (Claim-Art 'verbrauch' wie „verpasst“) statt ihn ungestartet stehen zu lassen —
                # er hielte sonst die Kette der ID (suKetteFrei) den ganzen Tag auf; der DB-Riegel lässt Verbrauchs-Claims durch
                ws = dict(ws, verbraucht_at=jetzt_iso)
        elif not regel:
            continue
        else:
            ws, usd = wd_sl_nach_rechnen(regel, p, acc, liq, frueher, rnd=rnd, jetzt_iso=jetzt_iso)
        if not ws:
            continue
        bl = dict(p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}, wd_sl=ws)
        upd = {"mt5_baseline": bl}
        if usd:
            upd["master_sl"] = usd
        if ws.get("verbraucht_at"):
            upd.update(start_um_gestartet_at=ws["verbraucht_at"], start_claim_art="verbrauch")   # FT2: fester SL passt heute nicht → nie starten
        filt = {"id": f"eq.{pid}", "status": "eq.planned", "start_um_gestartet_at": "is.null", "started_at": "is.null", "orbit_gesendet_at": "is.null",
                "mt5_baseline->wd_sl->>grund": f"eq.{WD_SL_RUECKFALL_GRUND}"}
        if p.get("updated_at"):
            filt["updated_at"] = f"eq.{p['updated_at']}"
        else:
            out["uebersprungen"].append({"id": pid, "grund": "updated_at fehlt — kein sicherer Guard"})
            continue
        try:
            z = sb_update("trade_plans", filt, upd)
        except Exception as e:
            out["uebersprungen"].append({"id": pid, "grund": f"{type(e).__name__}: {str(e)[:100]}"})
            continue
        if not z:
            out["uebersprungen"].append({"id": pid, "grund": "inzwischen geändert/geclaimt — nächster Takt"})
            continue
        out["geaendert"].append({"id": pid, "konto": p.get("master_name"), "usd": usd, "pct": ws.get("pct"), "grund": ws.get("grund")})
        out["gewuerfelt" if usd else "ohne"] += 1
        print(f"[wd-sl-nach] {pid[:8]} {p.get('master_name')}: " + (f"SL {usd} $ ({ws.get('pct')} % von {ws.get('puffer')} $)" if usd
                                                                     else f"ohne SL — {ws.get('grund')}"), flush=True)
    return out


def _wd_sl_nach_takt():
    """aus ap_loop: gestreut alle WD_SL_NACH_TAKT_S (Jitter-Regel), Fehler nur loggen."""
    if time.time() < _wd_sl_nach["naechster"]:
        return
    _wd_sl_nach["naechster"] = time.time() + random.uniform(*WD_SL_NACH_TAKT_S)
    try:
        _wd_sl_nach["letztes"] = wd_sl_nach_tick()
        _wd_sl_nach["fehler"] = ""
    except Exception as e:
        _wd_sl_nach["fehler"] = f"{type(e).__name__}: {e}"
        print(f"[wd-sl-nach] ⚠️ {type(e).__name__}: {e}", flush=True)


# ── Farmer auf V2 (24.09.2026, Vollumstieg auf Kapitel „Ohne Hedge") ─────────
# Finn: „riesen Umstieg — geh alles durch, Backend, jedes Einzelne". Seit dem
# 24.09.2026 gibt es keinen Gegen-Hedge mehr, Duplikum fliegt komplett raus. Die
# Regel für den Farmer stammt aus Finns Ansage vom 22.09.2026 („Ich will nie
# wieder Winning Days manuell fahren müssen": ab 02:00 Dubai alle Fundeds ID für
# ID, Richtung je ID, TP aus der Firmen-Spanne) — davon bleibt alles, NUR der
# Weg ändert sich: statt Orbit (tvplus, Puls platziert + Duplikum kopiert auf den
# Slave) fährt der Farmer jetzt Orbit V2 (tvv2: Puls in TradingView, Rundgang
# liest Today's P&L) bzw. bei einer MT5-Firma Echo V2 (mt5v2: Puls im MT5-Master-
# Terminal). Das Frontend (tpVorplanPlanRow) schickt die Zeilen noch mit
# route='tvplus' + Duplikum-Slave/Multiplier — hier wird das VOR dem Insert
# umgeschrieben, damit nie wieder ein Farmer-Plan auf einem Hedge-Weg landet,
# egal welcher Frontend-Stand die Zeile baut. Slave/Multiplier werden auf null
# gesetzt (kein Slave = nichts zu hedgen), master_symbol wie das Frontend
# (MNQ + Frontmonat), falls es fehlt.
WD_V2_NULL_FELDER = ("slave_account_id", "slave_name", "slave_firm", "slave_risk", "multiplier")
WD_V2_ROUTEN = ("tvv2", "mt5v2", "tsv2")   # tsv2 seit .1488 (13.10.2026): Topstep-Winning-Days über Puls in TopstepX


def _wd_futures_frontcode(jetzt=None):
    """Frontmonat-Code der CME-Index-Futures (H/M/U/Z + Jahresziffer), exakt wie
    tpFuturesFrontcode im Frontend: Roll am Donnerstag vor dem 3. Freitag des
    Quartalsmonats (= 3. Freitag − 8 Tage); liegt der Roll-Tag noch VOR dem
    Stichtag, ist der nächste Quartalsmonat dran. Gerechnet in UTC-Kalendertagen.
    → z.B. 'Z6' am 24.09.2026, 'U6' am 09.09.2026."""
    d = jetzt or datetime.now(timezone.utc)
    MON = {3: "H", 6: "M", 9: "U", 12: "Z"}
    d_ord = datetime(d.year, d.month, d.day).toordinal()
    for i in range(13):
        roh = (d.month - 1) + i
        jahr, monat = d.year + roh // 12, (roh % 12) + 1
        if monat not in MON:
            continue
        erster = datetime(jahr, monat, 1)
        bis_freitag = (4 - erster.weekday()) % 7          # weekday(): Mo=0 … Fr=4
        dritter_freitag = erster.toordinal() + bis_freitag + 14
        roll = dritter_freitag - 8
        if roll > d_ord:
            return MON[monat] + str(jahr % 10)
    return ""


def _wd_v2_route(firm):
    """Weg je Konto: Topstep → Topstep V2 (tsv2), sonstige Futures-Firma → Orbit V2 (tvv2), alles andere → Echo V2 (mt5v2).
    Topstep seit .1488 (Finn 13.10.2026, Winning Days Farm für Topstep): Topstep hängt seit 24.09.2026 nicht mehr an TradingView —
    ein tvv2-Plan wäre zur Startzeit rot. Puls platziert in TopstepX, TP/SL als Dollar der ganzen Position in „To Make" / „Risk"."""
    f = (firm or "").strip().lower()
    if "topstep" in f:
        return "tsv2"
    if _ist_tradeify_cfd(f):
        return "mt5v2"   # Tradeify CFD (23.10.2026): MT5/Echo V2, nie TradingView — „tradeify" in WD_FUTURES_FIRMEN meint Futures
    return "tvv2" if any(k in f for k in WD_FUTURES_FIRMEN) else "mt5v2"


def _wd_plan_v2(body, firm=None, jetzt=None):
    """Farmer-Zeile auf V2 drehen (in place + zurück): route, Slave-Felder null,
    master_symbol bei Bedarf (MNQ + Frontmonat, wie das Frontend ohne NQ-Modus).
    Ein schon V2-gesetzter Weg bleibt, wie er ist (Frontend entscheidet MNQ/NQ)."""
    route = str(body.get("route") or "")
    if route not in WD_V2_ROUTEN:
        body["route"] = _wd_v2_route(firm if firm is not None else body.get("master_firm"))
    # Winning Days Farm mit Fusion-Gegenhedge (26.09.2026, Finn: „die Winning Days werden gewürfelt wie im Admin … und unter
    # Winning Days mit der Logik ausgeführt, die wir entwickelt haben"): trägt die Zeile hedge_eur > 0, bleiben Multiplikator
    # und Risiko Slave stehen — genau wie beim Handweg im Popup. Der Copier rechnet die Fusion-Lots aus Kontrakte × multiplier
    # (hedgeSoloOeffnenKern); ohne ihn fiele er auf die nie live gefahrene eur/tp_punkte-Rechnung zurück.
    hedge = False
    try:
        hedge = body["route"] in ("tvv2", "tsv2") and float(body.get("hedge_eur") or 0) > 0   # tsv2 seit .1493: Winning Day auf Topstep mit Fusion-Hedge
    except (TypeError, ValueError):
        hedge = False
    for k in WD_V2_NULL_FELDER:
        if hedge and k in ("slave_risk", "multiplier"):
            continue
        body[k] = None
    if body["route"] == "mt5v2":
        # Review-Finding 24.09.2026 (W12): das Frontend schickt MNQ+Frontcode für JEDE Zeile —
        # bei einer MT5-Firma bliebe „MNQZ6" als MT5-Symbol stehen. Leer = Firmen-Standard.
        body["master_symbol"] = None
    elif not str(body.get("master_symbol") or "").strip() and body["route"] in ("tvv2", "tsv2"):
        body["master_symbol"] = "MNQ" + _wd_futures_frontcode(jetzt)   # tsv2: TopstepX-Contract MNQ/NQ + Frontmonat (.1488)
    return body


def _wd_login():
    """Eingeloggt reicht (wie /admin/overview). → (user_id, None) oder (None, (resp, status))."""
    if not SUPABASE_SERVICE_KEY:
        return None, (jsonify({"error": "Server nicht konfiguriert (SUPABASE_SERVICE_KEY fehlt)"}), 503)
    token = (request.headers.get("sb-token") or "").strip()
    if not token:
        return None, (jsonify({"error": "Nicht angemeldet"}), 401)
    try:
        r = _auth_user_anfrage(token)
        u = r.json() or {}
        if r.status_code != 200 or not u.get("id"):
            return None, (jsonify({"error": "Nicht angemeldet"}), 401)
        # Nur eigene Daten (27.09.2026): gilt für diese eine Anfrage. Ist admin_zugang nicht
        # lesbar, greift das except unten (502) — nie still alles ausliefern.
        # admin_zugang 60 s gemerkt (01.10.2026, SUPABASE-DIÄT B) — Fehler werfen weiter ins except (502)
        # Admin-Gruppen (08.10.2026): Einschränkung als MENGE (Verwalter = seine Gruppe, Mitglied = nur er); ohne Einschränkung
        # Finns ?gruppe=-Lesefilter (nur GET). admin_gruppe 60 s gemerkt; fehlt die Tabelle noch, gibt es keine Gruppen.
        sicht, verwalter = admin_sicht_lesen(str(u["id"]))
        # UNT0-Fix (S5-Prüfung 05.11.2026, Finn: Übersicht 5–6 s): Login-ID + Mail dieser Anfrage merken — _wd_login_ich liest sie hier statt einer
        # zweiten /auth/v1/user-Anfrage je Übersicht
        g.login_uid, g.login_mail = str(u["id"]), str(u.get("email") or "").strip().lower()
        # ANZEIGE ≠ AUSFÜHRUNG (Master 08.10.2026, Nachbesserung A): die Gruppe gilt nur in der Admin-Ansicht (?ansicht=admin bzw.
        # sicht=admin, das schicken allein die Admin-Reiter). Jede andere Anfrage desselben Logins — der PC-Tab des Verwalters (Start,
        # Endlesung, Hedge, Abhaken, Radar, Farmer-Automatik …) — sieht und ändert wie bis .1380 nur die eigene ID.
        if verwalter and not _admin_ansicht():
            sicht, verwalter = frozenset({str(u["id"])}), False
        if sicht is not None:
            g.admin_nur_uid = str(u["id"])
            g.admin_sicht = sicht
            g.admin_verwalter = verwalter
        else:
            f = _admin_filter_aus_anfrage()
            if f is not None:
                g.admin_filter = f
        return str(u["id"]), None
    except Exception:
        return None, (jsonify({"error": "Anmeldung nicht prüfbar"}), 502)


def _wd_personen(radar=False):
    """user_id → Anzeigename (user_metadata.name, sonst E-Mail-Kürzel) und die
    Menge der ausgeblendeten Personen (ADMIN_EXCLUDE_EMAILS) — wie in der Übersicht.
    radar=True (Finn 02.11.2026, Julian aus Emins Gruppe stand im HT-Radar unter Bestanden): Finns Gruppen-Chip des Admin-Reiters zählt nicht, nur die
    Einschränkung des Logins — wie /admin/live-trades für Läuft/Erledigt, das den Chip nie mitschickt."""
    disp, excluded = {}, set()
    r = _auth_liste_anfrage()
    for u in (r.json() or {}).get("users", []):
        uid = str(u.get("id"))
        mail = str(u.get("email") or "")
        meta_name = str((u.get("user_metadata") or {}).get("name") or "").strip()
        disp[uid] = meta_name or (mail.split("@")[0] if "@" in mail else (mail or uid[:8]))
        if mail.strip().lower() in ADMIN_EXCLUDE_EMAILS:
            excluded.add(uid)
    nur = _admin_nur_uid()
    sicht = _admin_eingeschraenkt() if radar else _admin_sicht()
    if nur:   # nur eigene Daten (27.09.2026) — seit 08.10.2026 die eigene Gruppe (Verwalter): alle anderen raus
        excluded = set(disp) - set(sicht or {nur})
    elif sicht is not None:   # Finns ?gruppe=-Filter (08.10.2026): HT zusätzlich zur Ausblendung, Verwalter-Gruppe genau die Gruppe (C)
        excluded = (set(excluded) | (set(disp) - set(sicht))) if _admin_filter_ist_ht() else (set(disp) - set(sicht))
    else:   # Standard-Sicht HT (09.10.2026): Gruppen MIT Verwalter raus wie in _admin_basis
        # radar: _admin_standard_aus wäre bei gesetztem Chip leer, darum die Verwalter-Gruppen direkt
        excluded = set(excluded) | (_admin_verwalter_gruppen_ids(admin_gruppen_daten()) if radar else _admin_standard_aus())
    return disp, excluded


