@app.errorhandler(SupabaseGesperrt)
def _sb_gesperrt_antwort(e):
    """Routen ohne eigenes except: 503 mit Retry-After statt 500 (die Anfrage ging gar nicht an Supabase)."""
    return (jsonify({"ok": False, "error": "Datenbank gerade gestört — gleich noch einmal", "db_bremse": True}), 503,
            {"Retry-After": str(max(SB_BREMSE_HALB_S, int(getattr(e, "rest_s", 0) or 0)))})


# ════════════════════════════════════════════════════════════════════════════
# KOMPASS-SAMMLER — Pascals Nasdaq-Forecasts dauerhaft in die DB (23.09.2026)
#
# Finn: „bau eine Seite in Prophos unter Admin, wo ich die Daten immer live
# bekomme + alles in die DB packen immer". Pascals Research-Agent „Kompass"
# postet mehrmals täglich Forecasts zum Nasdaq-100 (LONG/SHORT, Konfidenz 1–5)
# in einen Cloudflare-Worker. Die Seite lifeplanner-eps.pages.dev/signal.html
# ist dafür NICHT brauchbar: sie baut das JSON erst im Browser zusammen, ein
# HTTP-GET bekommt nur die leere Hülle. Der Worker selbst liefert die ganze
# Liste (id, context, date, time, title, body) — aber nur den laufenden Stand,
# nichts davon ist bei uns dauerhaft. Dieser Sammler holt die Liste alle
# KOMPASS_INTERVAL Sekunden und upsertet sie in kompass_forecasts (Pascals id
# ist der Schlüssel; erfasst_at bleibt beim Update stehen, weil es nicht im
# Body steht). Läuft nur mit Service-Key, also auf Railway — der Admin-Tab
# trägt beim Laden zusätzlich selbst nach (Browser-Upsert), falls Railway hängt.
KOMPASS_URL = (os.environ.get("KOMPASS_URL")
               or "https://kompass-api.pascal-hermann-22.workers.dev?category=k%3Aideas")
# Jede Minute (Finn 23.09.2026 03:0x: „immer live, nie holen drücken müssen"). Der Feed ist klein
# (~130 Zeilen) und der Worker bei Cloudflare — geschrieben wird nur, was neu oder geändert ist.
KOMPASS_INTERVAL = int(os.environ.get("KOMPASS_INTERVAL") or 60)
_kompass_info = {"started": False, "last_run": 0, "last_ok": 0, "runs": 0, "feed": 0,
                 "neu": 0, "last_error": "", "url": KOMPASS_URL}
_kompass_lock = threading.Lock()
_kompass_started = False
_kompass_memo = {}   # id -> Hash(titel+text+datum+zeit) des letzten Schreibens — spart den Upsert unveränderter Zeilen

# Reihenfolge wichtig: „New York Session Forecast (Update vor Trigger)" enthält
# auch „new york" — der speziellere Treffer muss zuerst geprüft werden.
KOMPASS_SESSIONS = [
    ("update vor trigger", "ny_update"),
    ("asia", "asia"),
    ("pre-london", "prelondon"),
    ("london", "london"),
    ("new york", "ny"),
    ("hourly", "hourly"),
]


def kompass_session(ctx):
    c = (ctx or "").lower()
    for key, name in KOMPASS_SESSIONS:
        if key in c:
            return name
    return "sonst"


def kompass_parse(item):
    """Ein Worker-Eintrag → eine Zeile für kompass_forecasts (None = kein Forecast,
    z. B. Pascals Test-Einträge ohne LONG/SHORT-Titel)."""
    if not isinstance(item, dict) or not item.get("id"):
        return None
    # Titel-Formate im Feed (Stand 23.09.2026): seit ~Ende August „LONG - Konfidenz 3/5", davor
    # „LONG - 60%" (Prozent statt Konfidenz) und vereinzelt Freitext wie „[6H-UPDATE] LONG (fade-Risiko) …".
    # Richtung = erstes LONG/SHORT im Titel; Konfidenz nur, wenn „Konfidenz N/5" drinsteht.
    titel = str(item.get("title") or "")
    mb = re.search(r"\b(LONG|SHORT)\b", titel, re.I)
    mk = re.search(r"Konfidenz\s*(\d)\s*/\s*5", titel, re.I)
    bias = mb.group(1).upper() if mb else None
    konf = int(mk.group(1)) if mk else None
    if konf is not None and not (1 <= konf <= 5):
        konf = None
    datum = str(item.get("date") or "")[:10]
    if not re.match(r"^\d{4}-\d{2}-\d{2}$", datum):
        datum = None
    zeit = str(item.get("time") or "").strip()[:5] or None
    # Posting-Zeit: Pascals id ist ein Epoch-Zeitstempel (idea-1790114840 = 22.09.2026 22:07:20 UTC) —
    # genauer als date/time, die er von Hand setzt (23.09. 01:07 stand mit date 22.09. drin).
    mt = re.match(r"^idea-(\d{10})$", str(item["id"]))
    t0 = datetime.fromtimestamp(int(mt.group(1)), tz=timezone.utc).isoformat() if mt else None
    return {
        "id": str(item["id"])[:80],
        "t0": t0,
        "session": kompass_session(item.get("context")),
        "kontext": (item.get("context") or None),
        "datum": datum,
        "zeit": zeit,
        "bias": bias,
        "konfidenz": konf,
        "titel": (item.get("title") or None),
        "text": (item.get("body") or item.get("text") or None),
        "roh": item,
        "aktualisiert_at": datetime.now(timezone.utc).isoformat(),
    }


def kompass_collect():
    """Feed holen, in die DB upserten. Gibt (feed_count, neu) zurück, wirft bei Fehlern."""
    with _kompass_lock:
        r = requests.get(KOMPASS_URL, timeout=20, headers={"Accept": "application/json"})
        r.raise_for_status()
        items = r.json()
        if not isinstance(items, list):
            raise ValueError("Worker liefert keine Liste")
        rows = [z for z in (kompass_parse(i) for i in items) if z]
        if not _kompass_memo and rows:
            # Erster Lauf nach dem Start: was schon in der DB steht, gilt als bekannt —
            # geschrieben wird es trotzdem einmal (Titel/Text könnten sich geändert haben).
            for s in _sb_all("kompass_forecasts", {"select": "id"}):
                _kompass_memo.setdefault(str(s.get("id")), "")
        def sig(z):
            return hashlib.sha1(json.dumps([z["titel"], z["text"], z["datum"], z["zeit"], z["kontext"]],
                                           ensure_ascii=False).encode("utf-8")).hexdigest()
        neu = [z for z in rows if z["id"] not in _kompass_memo]
        schreiben = [z for z in rows if _kompass_memo.get(z["id"]) != sig(z)]
        for i in range(0, len(schreiben), 200):
            sb_upsert("kompass_forecasts", schreiben[i:i + 200])
        for z in schreiben:
            _kompass_memo[z["id"]] = sig(z)
        _kompass_info.update({"feed": len(rows), "neu": len(neu), "last_ok": time.time()})
        if neu:
            print(f"[kompass] {len(neu)} neue Forecasts gesichert (Feed {len(rows)})", flush=True)
        return len(rows), len(neu)


# ── Auswertung (23.09.2026, Finn: „pack die Daten mal in Prophos, is der Bot von meinem Bruder, will
#    sehen wie gut der is"): je Forecast die Kursbewegung 1/2/4/8 h nach der Posting-Zeit, aus den
#    NQ-Futures-Kerzen (Yahoo, 5 min, 60 Tage — derselbe Weg wie /markt/futures). Ergebnis in
#    kompass_forecasts.auswertung; „fertig" sobald alle Horizonte da sind. Kerzen höchstens alle 4 min neu.
KOMPASS_HORIZONTE = (1, 2, 4, 8)
_kompass_kerzen = {"at": 0, "T": [], "K": []}   # T = Epoch je Kerze, K = (open, high, low, close)

# Session-Fenster (23.09.2026, Finn: „mach auch Statistiken, wie gut es ist"): zusätzlich zu den
# festen Stunden-Horizonten das Fenster, für das der Forecast eigentlich gedacht ist —
# NY Open→Close, London Open→Close, Pre-London die vier Stunden vor London, Asia = Tokio-Handel.
# Für NY außerdem der Gap (Open gegen den Vortagesschluss 16:00 NY) — das ist die Frage, für die
# Pascals eigener Backtest 80 % ausweist. Stündlich hat kein Fenster (dort zählt +1 h).
try:
    from zoneinfo import ZoneInfo as _ZI
except Exception:   # pragma: no cover — sehr alte Python-Version
    _ZI = None
KOMPASS_FENSTER = {
    "ny":        ("America/New_York", (9, 30), (16, 0), 0),
    "ny_update": ("America/New_York", (9, 30), (16, 0), 0),
    "london":    ("Europe/London",    (8, 0),  (16, 30), 0),
    "prelondon": ("Europe/London",    (4, 0),  (8, 0),  0),
    "asia":      ("Asia/Tokyo",       (9, 0),  (15, 0), 0),
}


def kompass_fenster(session, t0):
    """→ (von, bis, vortag_close) als Epoch für das Session-Fenster des Tages, in dem t0 (Ortszeit) liegt.
    vortag_close = 16:00 NY des letzten Werktags davor (nur NY). None, wenn keine Session."""
    f = KOMPASS_FENSTER.get(session)
    if not f or not _ZI:
        return None
    tz = _ZI(f[0])
    d = datetime.fromtimestamp(t0, tz)
    von = d.replace(hour=f[1][0], minute=f[1][1], second=0, microsecond=0)
    bis = d.replace(hour=f[2][0], minute=f[2][1], second=0, microsecond=0)
    # Posting nach Fensterende (z. B. Asia-Forecast 17:30 NY = 06:30 Tokio → Fenster liegt noch vor uns: passt;
    # ein NY-Forecast um 18:00 NY dagegen meint den nächsten Tag)
    if t0 > bis.timestamp():
        d2 = d + __import__("datetime").timedelta(days=1)
        von = d2.replace(hour=f[1][0], minute=f[1][1], second=0, microsecond=0)
        bis = d2.replace(hour=f[2][0], minute=f[2][1], second=0, microsecond=0)
    vortag = None
    if session in ("ny", "ny_update"):
        v = von - __import__("datetime").timedelta(days=1)
        while v.weekday() >= 5:
            v -= __import__("datetime").timedelta(days=1)
        vortag = v.replace(hour=16, minute=0, second=0, microsecond=0).timestamp()
    return int(von.timestamp()), int(bis.timestamp()), (int(vortag) if vortag else None)


def _kompass_bedarf(session):
    b = [f"h{h}" for h in KOMPASS_HORIZONTE]
    if session in KOMPASS_FENSTER:
        b.append("sess")
    if session in ("ny", "ny_update"):
        b.append("gap")
    return b


def kompass_kerzen():
    if _kompass_kerzen["T"] and time.time() - _kompass_kerzen["at"] < 240:
        return
    r = requests.get("https://query1.finance.yahoo.com/v8/finance/chart/NQ%3DF",
                     params={"range": "60d", "interval": "5m"},
                     headers={"User-Agent": "Mozilla/5.0 (Prophos)"}, timeout=20)
    r.raise_for_status()
    res = ((r.json() or {}).get("chart") or {}).get("result") or []
    if not res:
        raise ValueError("Yahoo ohne Kerzen für NQ=F")
    ts = res[0].get("timestamp") or []
    q = ((res[0].get("indicators") or {}).get("quote") or [{}])[0]
    T, K = [], []
    for t, o, h, l, c in zip(ts, q.get("open") or [], q.get("high") or [], q.get("low") or [], q.get("close") or []):
        if c is None:
            continue
        T.append(int(t)); K.append((o if o is not None else c, h if h is not None else c, l if l is not None else c, c))
    if len(T) < 100:
        raise ValueError(f"Yahoo liefert nur {len(T)} Kerzen")
    _kompass_kerzen.update({"at": time.time(), "T": T, "K": K})


def _kompass_px(t):
    """Schlusskurs der letzten Kerze bis t (None bei Lücke > 1 h, z. B. Wochenende)."""
    T = _kompass_kerzen["T"]
    i = bisect.bisect_right(T, t) - 1
    if i < 0 or t - T[i] > 3600:
        return None, None
    return _kompass_kerzen["K"][i][3], i


def kompass_auswerten():
    """Alle Forecasts mit Richtung und Posting-Zeit, die noch nicht fertig sind, nachrechnen."""
    rows = _sb_all("kompass_forecasts", {"select": "id,bias,t0,session,auswertung", "bias": "not.is.null", "t0": "not.is.null"})
    # Offen = irgendein Bedarf fehlt (Stunden-Horizonte, Session-Fenster, Gap) und nicht als unrechenbar markiert
    offen = [z for z in rows if not ((z.get("auswertung") or {}).get("grund"))
             and any(k not in (z.get("auswertung") or {}) for k in _kompass_bedarf(z.get("session")))]
    if not offen:
        return 0
    kompass_kerzen()
    T, K = _kompass_kerzen["T"], _kompass_kerzen["K"]
    jetzt = time.time()
    n = 0
    for z in offen:
        try:
            t0 = int(datetime.fromisoformat(str(z["t0"]).replace("Z", "+00:00")).timestamp())
        except Exception:
            continue
        aus = dict(z.get("auswertung") or {})
        long = z["bias"] == "LONG"
        p0, i0 = _kompass_px(t0)
        if p0 is None:
            # Vor dem Kerzenfenster (Yahoo: 60 Tage für 5 min) oder in einer Handelspause — nicht rechenbar
            if t0 < T[0]:
                aus.update({"fertig": True, "grund": "keine Kerzen (älter als 60 Tage)", "berechnet_at": datetime.now(timezone.utc).isoformat()})
                sb_update("kompass_forecasts", {"id": f"eq.{z['id']}"}, {"auswertung": aus})
                n += 1
            continue
        aus["p0"] = p0
        geaendert = False
        for h in KOMPASS_HORIZONTE:
            key = f"h{h}"
            if key in aus:
                continue
            t1 = t0 + h * 3600
            if t1 > T[-1] or t1 > jetzt:
                continue   # Stunde noch nicht vorbei bzw. Yahoo noch nicht so weit (Verzögerung)
            p1, i1 = _kompass_px(t1)
            if p1 is None:
                continue
            hi = max(k[1] for k in K[i0:i1 + 1]); lo = min(k[2] for k in K[i0:i1 + 1])
            dp = (p1 - p0) / p0 * 100
            aus[key] = {
                "p": p1, "dp": round(dp, 4), "hit": (dp > 0) if long else (dp < 0),
                "mfe": round(((hi - p0) if long else (p0 - lo)) / p0 * 100, 4),
                "mae": round(((p0 - lo) if long else (hi - p0)) / p0 * 100, 4),
            }
            geaendert = True
        # Session-Fenster + Gap (nur wenn das Fenster vorbei ist; fehlende Kerzen → 'na', damit es nicht ewig offen bleibt)
        fen = kompass_fenster(z.get("session"), t0)
        if fen:
            von, bis, vortag = fen
            if "sess" not in aus and bis <= jetzt and bis <= T[-1]:
                pv, iv = _kompass_px(von); pb, ib = _kompass_px(bis)
                if pv is not None and pb is not None and iv is not None:
                    dp = (pb - pv) / pv * 100
                    hi = max(k[1] for k in K[iv:ib + 1]); lo = min(k[2] for k in K[iv:ib + 1])
                    aus["sess"] = {"von": von, "bis": bis, "p_von": pv, "p_bis": pb, "dp": round(dp, 4),
                                   "hit": (dp > 0) if long else (dp < 0),
                                   "mfe": round(((hi - pv) if long else (pv - lo)) / pv * 100, 4),
                                   "mae": round(((pv - lo) if long else (hi - pv)) / pv * 100, 4)}
                elif bis + 7200 <= jetzt:
                    aus["sess"] = {"na": True}
                geaendert = True
            if vortag and "gap" not in aus and von <= jetzt and von <= T[-1]:
                pvt, _i = _kompass_px(vortag); po, _j = _kompass_px(von)
                if pvt is not None and po is not None:
                    dp = (po - pvt) / pvt * 100
                    aus["gap"] = {"vortag": vortag, "open": von, "p_vortag": pvt, "p_open": po, "dp": round(dp, 4),
                                  "hit": (dp > 0) if long else (dp < 0)}
                elif von + 7200 <= jetzt:
                    aus["gap"] = {"na": True}
                geaendert = True
        if all(k in aus for k in _kompass_bedarf(z.get("session"))):
            if not aus.get("fertig"):
                aus["fertig"] = True; geaendert = True
        if geaendert:
            aus["berechnet_at"] = datetime.now(timezone.utc).isoformat()
            sb_update("kompass_forecasts", {"id": f"eq.{z['id']}"}, {"auswertung": aus})
            n += 1
    if n:
        print(f"[kompass] Auswertung: {n} Forecasts nachgerechnet", flush=True)
    return n


def kompass_loop():
    print(f"[kompass] 🧭 Sammler läuft (alle {KOMPASS_INTERVAL}s, {KOMPASS_URL})", flush=True)
    db_n = 0   # DB-Fehler in Folge (01.10.2026, AUSFALL-BREMSE)
    while True:
        started = time.time()
        db_fehler = False
        try:
            kompass_collect()
            _kompass_info["last_error"] = ""
        except Exception as e:
            _kompass_info["last_error"] = f"{type(e).__name__}: {e}"
            db_fehler = db_fehler or _ist_db_fehler(e)
            print(f"[kompass] ⚠️ {e}", flush=True)
        try:
            _kompass_info["ausgewertet"] = kompass_auswerten()
            _kompass_info["auswertung_error"] = ""
        except Exception as e:
            _kompass_info["auswertung_error"] = f"{type(e).__name__}: {e}"
            db_fehler = db_fehler or _ist_db_fehler(e)
            print(f"[kompass] ⚠️ Auswertung: {e}", flush=True)
        _kompass_info["last_run"] = time.time()
        _kompass_info["runs"] += 1
        db_n = db_n + 1 if db_fehler else 0   # nur DB-Fehler verlängern (Worker-Fehler behalten den Takt)
        _schleife_schlafen(schleifen_pause(max(15.0, KOMPASS_INTERVAL - (time.time() - started)), db_n, sb_bremse_rest_s(), 300),
                           db_pause=db_n > 0)


def start_kompass():
    global _kompass_started
    if _kompass_started:
        return
    if not SUPABASE_SERVICE_KEY:
        print("[kompass] ℹ️ Kein SUPABASE_SERVICE_KEY — Sammler inaktiv (Admin-Tab trägt selbst nach).", flush=True)
        return
    _kompass_started = True
    _kompass_info["started"] = True
    threading.Thread(target=kompass_loop, daemon=True).start()


@app.route("/admin/kompass", methods=["GET", "OPTIONS"])
def admin_kompass():
    """Stand des Sammlers; ?refresh=1 holt den Feed sofort (Knopf „Jetzt holen" im Admin-Tab)."""
    if request.method == "OPTIONS":
        return "", 200
    me, err = _wd_login()
    if err:
        return err
    out = dict(_kompass_info)
    if (request.args.get("refresh") or "") in ("1", "true"):
        try:
            feed, neu = kompass_collect()
            out.update({"feed": feed, "neu": neu, "refreshed": True, "last_error": ""})
        except Exception as e:
            out.update({"refreshed": False, "last_error": f"{type(e).__name__}: {e}"})
    out["now"] = time.time()
    return jsonify(out)


