# 18:28–18:35 Dubai kein WEITERER Big Trade starten, wenn schon einer läuft — „nicht aktiv sein, sondern starten"). Dieselbe Entscheidung wie
# prophos_big_trade_halten / trade_plans_big_trade (sql/2026-11-03_zwei_orbit_firma_marktoeffnung.sql): Firma über beide Fenster und auch bei
# big_max_je_id = 2; Markteröffnung in New-York-Zeit (wandert mit der US-Zeitumstellung), nur wenn im Fenster schon einer läuft.
PULS_HEIM_CODE_FIRMA = "firma_laeuft"
PULS_HEIM_CODE_MARKT = "markt_oeffnung"
PULS_HEIM_ZWEIT_CODES = (PULS_HEIM_CODE_ZWEIT, PULS_HEIM_CODE_FIRMA, PULS_HEIM_CODE_MARKT)
PULS_HEIM_MARKT_NY = ((9, 28), (9, 35))


def puls_heim_fenster(route):
    """REIN RECHNEND (testbar): Fenster einer Aktion/eines Plans wie prophos_big_trade_fenster — 'tsx' (tsv2), 'tv' (tvv2, polar, tvplus),
    None = Echo (mt5/mt5v2/dup: kein TradingView-Kontowechsel, wartet nie). Leer/unbekannt → 'alle' (wie bisher)."""
    r = str(route or "").strip().lower()
    if not r:
        return "alle"
    if r in PULS_HEIM_ECHO_ROUTEN:
        return None
    return "tsx" if r == "tsv2" else "tv"


def puls_heim_im_fenster(plaene, fenster):
    """REIN RECHNEND (testbar): nur die Pläne im Fenster der Aktion ('alle' = keine Auswahl)."""
    if fenster == "alle":
        return list(plaene or ())
    return [p for p in plaene or () if puls_heim_fenster(p.get("route")) == fenster]


def puls_heim_ist_big(p):
    """REIN RECHNEND (testbar): Big Trade wie prophos_big_trade(route, hedge_eur, orbit_v3, prophos_wd_wie(...)) — tvv2/tsv2 mit Hedge-Weg
    oder polar, kein Winning Day, keine Apex-Challenge auf dem WD-Weg."""
    p = p or {}
    if p.get("winning_day") is True or str(p.get("konto_typ") or "") == "winning_days" or plan_ist_apex_hedge(p):
        return False
    r = str(p.get("route") or "")
    if r == "polar":
        return True
    return r in ("tvv2", "tsv2") and ((_wd_num(p.get("hedge_eur")) or 0) > 0 or p.get("orbit_v3") is True)


def puls_heim_zweit_regel(regel):
    """REIN RECHNEND (testbar): (big_max_je_id, zweit_usd) aus puls_heim_regel — Standard (1, 2.500). Ungültiges → Standard (1 = heute)."""
    r = regel if isinstance(regel, dict) else {}
    try:
        mx = int(r.get("big_max_je_id")) if r.get("big_max_je_id") is not None else 1
    except (TypeError, ValueError):
        mx = 1
    z = _wd_num(r.get("zweit_usd"))
    return max(1, mx), (float(z) if z is not None and z >= 0 else PULS_HEIM_ZWEIT_USD)


def puls_heim_markt_oeffnung(jetzt=None):
    """REIN RECHNEND (testbar, 03.11.2026): liegt jetzt (aware datetime, Standard: jetzt) in 09:28–09:35 New York? → Fensterende (UTC) | None.
    Wie prophos_big_trade_markt_oeffnung."""
    from zoneinfo import ZoneInfo
    ny = (jetzt or datetime.now(timezone.utc)).astimezone(ZoneInfo("America/New_York"))
    (vh, vm), (bh, bm) = PULS_HEIM_MARKT_NY
    if not ((vh, vm) <= (ny.hour, ny.minute) < (bh, bm)):
        return None
    return ny.replace(hour=bh, minute=bm, second=0, microsecond=0).astimezone(timezone.utc)


def puls_heim_zweit_urteil(andere, max_je_id, zweit_usd, firma=None, markt_bis=None):
    """REIN RECHNEND (testbar): darf ein weiterer Big Trade derselben ID im selben Fenster starten? andere = [{name, art, nah, rest_tp_usd,
    rest_liq_usd, gesendet}] der schon laufenden (nah wie puls_heim_nah mit Schwellen (zweit_usd, zweit_usd); gesendet = Order gerade raus,
    noch nicht offen). firma = [{name, firma}] laufende Big Trades derselben ID bei derselben Firma (beide Fenster); markt_bis = Ende der
    Markteröffnung (puls_heim_markt_oeffnung) oder None. Reihenfolge wie prophos_big_trade_halten: nichts im Fenster → nur Firma; sonst voll →
    Firma → Markteröffnung → Abstand. → {frei, code?, grund?, rest_tp_usd?, rest_liq_usd?, firma?, bis?}."""
    andere, firma = list(andere or ()), list(firma or ())
    def firma_sperre():
        f = firma[0]
        return {"frei": False, "code": PULS_HEIM_CODE_FIRMA, "firma": f.get("firma"),
                "grund": f"Big Trade „{f.get('name') or '?'}“ läuft schon bei {f.get('firma') or '?'} — je Firma nur einer gleichzeitig"}
    if not andere:
        return firma_sperre() if firma else {"frei": True}
    if len(andere) >= int(max_je_id):
        a = andere[0]
        return {"frei": False, "code": PULS_HEIM_CODE_ZWEIT,
                "grund": (f"Big Trade „{a.get('name') or '?'}“{(' (' + a['art'] + ')') if a.get('art') else ''} läuft schon in diesem Fenster — höchstens {int(max_je_id)} gleichzeitig"
                          if int(max_je_id) <= 1 else f"schon {len(andere)} Big Trades in diesem Fenster — höchstens {int(max_je_id)}")}
    if firma:
        return firma_sperre()
    if markt_bis is not None:
        from zoneinfo import ZoneInfo
        return {"frei": False, "code": PULS_HEIM_CODE_MARKT, "bis": markt_bis.isoformat(),
                "grund": f"Markteröffnung 09:28–09:35 New York (bis {markt_bis.astimezone(ZoneInfo('Asia/Dubai')).strftime('%H:%M')} Dubai): "
                         f"kein weiterer Big Trade, solange „{andere[0].get('name') or '?'}“ läuft"}
    for a in andere:
        if a.get("gesendet"):
            return {"frei": False, "code": PULS_HEIM_CODE_ZWEIT, "grund": f"Big Trade {a.get('name')} wurde gerade gesendet — erst wenn er offen ist"}
        if a.get("nah") is None:
            return {"frei": False, "code": PULS_HEIM_CODE_UNKLAR,
                    "grund": f"Big Trade {a.get('name')} ({a.get('art')}) nicht prüfbar: {a.get('grund') or 'kein Kurs/Level'} — zweiter Start wartet"}
        if a.get("nah"):
            return {"frei": False, "code": PULS_HEIM_CODE_ZWEIT, "rest_tp_usd": a.get("rest_tp_usd"), "rest_liq_usd": a.get("rest_liq_usd"),
                    "grund": f"1. Trade {a.get('name')} ({a.get('art')}) ist {a.get('grund')} — zweiter Start wartet (Spanne {format(float(zweit_usd), ',.0f').replace(',', '.')} $)"}
    return {"frei": True}


PULS_HEIM_FELDER = ("id,user_id,master_account_id,master_name,master_firm,route,notes,status,richtung,master_contracts,master_symbol,"
                    "master_symbol_root,master_tp,master_sl,master_pl,hedge_eur,hedge_faktor,start_um,started_at,ended_at,completed_at,"
                    "planned_for,created_at,mt5_baseline,konto_typ,orbit_v3,winning_day,blown,orbit_gesendet_at,start_um_gestartet_at")


def _puls_heim_naehe(plaene, schwellen_je):
    """[(plan, n, info, name, art)] — Nähe je Plan wie puls_heim_pruefen (Live-Trades-Zeile, frischer Kurs). schwellen_je(acc, plan)."""
    ids = sorted({str(p.get("master_account_id")) for p in plaene if p.get("master_account_id")})
    accs = {str(a["id"]): a for a in (sb_select("accounts", {"select": "id,name,firm,account_type,starting_balance,external_id,max_drawdown,max_daily_drawdown,tv_balance,tv_balance_at",
                                                                 "id": f"in.({','.join(ids)})"}) or [])} if ids else {}
    fruehere = _wd_fruehere_trades(ids, streng=True)   # KK1 (Prüfer SOLLTE): Lesefehler → die Aufrufer fangen ihn (Zweit-Prüfung: nicht frei)
    liq_regeln, liq_verlauf, liq_kw = _liq_regeln_laden(), _liq_verlauf_laden(ids), _liq_kw_laden()
    kurse = _kurs_jetzt()
    out = []
    for p in plaene:
        acc = accs.get(str(p.get("master_account_id") or ""))
        z = _lt_zeile(p, acc, {}, {}, wd_vorher_waehlen(p, fruehere), regeln=liq_regeln, fruehere=fruehere, verlauf=liq_verlauf,
                      kw_firmen=ap_unt_firmen(p.get("user_id"), liq_kw, streng=False) if liq_kw is not None else None)   # UNT3
        kurs = puls_heim_kurs_frisch(kurse, z.get("symbol_root"))
        n = puls_heim_nah(z, kurs, schwellen_je(acc, p))
        name = f"{(acc or {}).get('firm') or p.get('master_firm') or 'Big Trade'} …{str((acc or {}).get('external_id') or '')[-4:]}"
        art = f"{str(z.get('richtung') or '').upper()} {int(z['kt']) if _wd_num(z.get('kt')) else '?'} {z.get('symbol_root') or 'NQ'}"
        info = {"plan": str(p.get("id")), "konto": name, "art": art, "kurs": kurs, "tp_level": n["tp_level"], "liq_level": n["liq_level"],
                "rest_tp_usd": n["rest_tp_usd"], "rest_liq_usd": n["rest_liq_usd"]}
        out.append((p, n, info, name, art))
    return out


def puls_heim_zweit_pruefen(plan):
    """Darf dieser (geplante) Big Trade jetzt starten? → {frei, code?, grund?, big_trade?, max_je_id, zweit_usd}. Kein Big Trade / nicht
    geplant → frei. Andere Big Trades DERSELBEN ID im selben Fenster: open (Nähe mit zweit_usd) oder gerade gesendet/geclaimt (wie
    prophos_big_trade_laeuft). Fehler → nicht frei (big_trade_unklar)."""
    p = plan or {}
    if str(p.get("status") or "") != "planned" or not puls_heim_ist_big(p):
        return {"frei": True}
    if p.get("orbit_gesendet_at") or p.get("started_at"):
        return {"frei": True}            # wie prophos_big_trade_halten: Order schon gesendet — Nachklick/Neustart nie sperren (Prüfung S4)
    regel = _puls_heim_regel()
    mx, zu = puls_heim_zweit_regel(regel)
    try:
        f = puls_heim_fenster(p.get("route"))
        rows = _sb_all("trade_plans", {"select": PULS_HEIM_FELDER, "user_id": f"eq.{p.get('user_id')}", "status": "in.(open,planned)",
                                       "route": "in.(tvv2,tsv2,polar)"}) or []
        jetzt = datetime.now(timezone.utc)
        def frisch(iso, minuten):
            try:
                return bool(iso) and (jetzt - datetime.fromisoformat(str(iso).replace("Z", "+00:00"))).total_seconds() < minuten * 60
            except ValueError:
                return False
        lauf = [r for r in rows if str(r.get("id")) != str(p.get("id")) and puls_heim_ist_big(r)
                and (r.get("status") == "open" or frisch(r.get("orbit_gesendet_at"), 10)
                     or (frisch(r.get("start_um_gestartet_at"), 2) and not r.get("started_at")))]
        andere = puls_heim_im_fenster(lauf, f)
        # JE FIRMA NUR EINER (03.11.2026): über beide Fenster, Firma wie prophos_firma_key (_firm_norm); die eigene Firma aus der DB-Zeile
        selbst = next((r for r in rows if str(r.get("id")) == str(p.get("id"))), None) or p
        fk = _firm_norm(selbst.get("master_firm"))
        firma = [{"name": r.get("master_name") or "?", "firma": fk} for r in lauf if _firm_norm(r.get("master_firm")) == fk]
        if not andere and not firma:
            return {"frei": True, "max_je_id": mx, "zweit_usd": zu}
        bis = puls_heim_markt_oeffnung(jetzt) if andere else None
        offen = [r for r in andere if r.get("status") == "open"]
        naehe = {str(x[0].get("id")): x for x in _puls_heim_naehe(offen, lambda _a, _p: (zu, zu))} \
            if (offen and len(andere) < mx and not firma and bis is None) else {}
        liste = []
        for r in andere:
            x = naehe.get(str(r.get("id")))
            if x:
                liste.append({"name": x[3], "art": x[4], "nah": x[1]["nah"], "grund": x[1]["grund"], "rest_tp_usd": x[1]["rest_tp_usd"],
                              "rest_liq_usd": x[1]["rest_liq_usd"], "info": x[2]})
            else:
                liste.append({"name": r.get("master_name") or r.get("master_firm") or "?", "art": str(r.get("richtung") or "").upper(),
                              "gesendet": r.get("status") != "open", "nah": None})
        u = puls_heim_zweit_urteil(liste, mx, zu, firma, bis)
        if not u.get("frei"):
            erst = next((a.get("info") for a in liste if a.get("info")), None)
            if erst:
                u["big_trade"] = erst
        elif liste:   # Z6 (03.11.2026): weiterer Big Trade frei → Abstand der laufenden beim Start merken (Handy-Meldung „Zweiter Big Trade gestartet“)
            u["zweit_andere"] = [dict(a.get("info") or {}, konto=(a.get("info") or {}).get("konto") or a.get("name"), art=a.get("art")) for a in liste]
        return dict(u, max_je_id=mx, zweit_usd=zu)
    except Exception as e:
        print(f"[puls-heim] ⚠️ Zweit-Prüfung {str(p.get('id'))[:8]}: {type(e).__name__}: {str(e)[:160]}", flush=True)
        return {"frei": False, "code": PULS_HEIM_CODE_UNKLAR, "max_je_id": mx, "zweit_usd": zu,
                "grund": f"Zweit-Prüfung gerade nicht möglich ({type(e).__name__}) — Start wartet"}


# ══ ZWEI ORBIT AUFS HANDY (03.11.2026, Auftrag Z6; Finn will „Zwei Orbit“ auf 2 stellen, „von Anfang an eine Handy-Nachricht über Prophos, sobald so ein
# Szenario passiert, damit er es sich ansehen kann“). Drei 🟠-Meldungen an die Master-IDs (alarm_senden, alarm_log, Entprellung über schluessel):
#  (1) „Zweiter Big Trade gestartet“ — eine ID hat im selben Fenster ≥ 2 Big Trades offen (alarm_tick, je jüngstem Plan einmal). Abstand der laufenden zu TP/Liq
#      beim Start: der Klick-Riegel (/richtung/frei, frei mit zweit_andere) merkt ihn je Plan im Speicher; nach einem Railway-Neustart der Wert von jetzt.
#  (2) „Zweiter Big Trade wartet“ — einmal je Plan: Klick-Riegel sperrt mit zweit_wartet/firma_laeuft/markt_oeffnung (sofort, Thread) oder die DB setzt
#      start_sperre art zweit/firma/markt (alarm_tick).
#  (3) „Puls hat das Konto gewechselt (Priorität)“ — der PC-Tab hängt an /alarm/heimweg das Feld prio {von, nach, a_von, a_nach} (bigTradePlan → heimNaechster);
#      einmal je Wechsel (alarm_heimweg).
# Big Trade = puls_heim_ist_big (prophos_big_trade: Apex-Challenge und Winning Day zählen nicht). ══
ZWEIT_FENSTER_NAME = {"tv": "TradingView", "tsx": "TopstepX"}
ZWEIT_MERK_S = 2 * 3600
ZWEIT_PULS_KONTO_MAX_S = 120
ZWEIT_LOG_S = 3 * 86400          # Entprellung im alarm_log länger als der 24-h-Speicher (ein Paar > 24 h offen meldet nicht neu)
ZWEIT_PRIO_AT_S = 900            # at vom Tab nur ± 15 min um die Serverzeit, sonst Serverzeit (Schlüssel je Minute)
_ZWEIT_START_MERK = {}   # plan_id → {at, andere: [{plan, konto, art, rest_tp_usd, rest_liq_usd}]}
_ZWEIT_LOCK = threading.Lock()


def zweit_konto_name(p):
    """REIN RECHNEND (testbar): „Tradeify …4758“ — Firma + letzte 4 der Kennung aus master_name („150k FTDFYSLX150742744758 → Funded“)."""
    p = p or {}
    m = re.search(r"[A-Z]{2,}[A-Z0-9_-]*\d{4,}", str(p.get("master_name") or "").upper())
    firma = str(p.get("master_firm") or "").strip()
    return f"{firma} …{m.group(0)[-4:]}".strip() if m else (str(p.get("master_name") or "").strip() or firma or "?")


def zweit_art(p):
    """REIN RECHNEND (testbar): „BUY 3 NQ“ aus richtung, master_contracts, master_symbol_root."""
    p = p or {}
    kt = _wd_num(p.get("master_contracts"))
    return f"{str(p.get('richtung') or '').upper()} {int(kt) if kt and float(kt).is_integer() else (kt or '?')} {p.get('master_symbol_root') or 'NQ'}".strip()


def _zweit_usd(x):
    v = _wd_num(x)
    return None if v is None else format(int(round(float(v))), ",").replace(",", ".") + " $"


def _zweit_hhmm(iso):
    from zoneinfo import ZoneInfo
    t = _alarm_ts(iso)
    return t.astimezone(ZoneInfo("Asia/Dubai")).strftime("%H:%M") if t else "?"


def zweit_gruppen(plaene):
    """REIN RECHNEND (testbar): offene Big Trades je (user_id, Fenster) mit mindestens zwei → [(uid, fenster, [plan…] nach started_at aufsteigend)]."""
    je = {}
    for p in plaene or ():
        if str(p.get("status") or "") != "open" or not puls_heim_ist_big(p):
            continue
        f = puls_heim_fenster(p.get("route"))
        if f in ("tv", "tsx"):
            je.setdefault((str(p.get("user_id")), f), []).append(p)
    return [(u, f, sorted(l, key=lambda x: str(x.get("started_at") or ""))) for (u, f), l in sorted(je.items()) if len(l) >= 2]


def zweit_puls_wo(konto_text, plaene):
    """REIN RECHNEND (testbar): in welchem dieser Konten steht der Puls-Chrome? Reader-Kontotext (Balance klebt evtl. an der Kennung) → Kontoname | Rohtext | None."""
    k = (re.split(r"[^A-Z0-9]+", str(konto_text or "").strip().upper()) or [""])[0]
    if not k:
        return None
    for p in plaene or ():
        m = re.search(r"[A-Z]{2,}[A-Z0-9_-]*\d{4,}", str(p.get("master_name") or "").upper())
        if m and (k == m.group(0) or (k.startswith(m.group(0)) and re.fullmatch(r"\d{1,3}", k[len(m.group(0)):]))):
            return zweit_konto_name(p)
    return k


def zweit_gestartet_ereignis(uid, fenster, gruppe, namen, merk, jetzt_naehe, puls_wo):
    """REIN RECHNEND (testbar): Meldung (1) für eine Gruppe aus zweit_gruppen → (schluessel, prio, art, titel, text, uid, plan_id, daten). B = der jüngste.
    merk = _ZWEIT_START_MERK-Eintrag von B oder None; jetzt_naehe = {plan_id: {rest_tp_usd, rest_liq_usd}} als Rückfall (Wert von jetzt)."""
    b, andere = gruppe[-1], gruppe[:-1]
    wer = namen.get(str(uid), str(uid)[:8])
    beim = {str(x.get("plan") or ""): x for x in ((merk or {}).get("andere") or []) if x.get("plan")}
    teile, daten_a = [], []
    for a in andere:
        name = zweit_konto_name(a)
        x = beim.get(str(a.get("id")))
        quelle = "beim Start von B" if x else "jetzt"
        x = x or (jetzt_naehe or {}).get(str(a.get("id"))) or {}
        tp, liq = _zweit_usd(x.get("rest_tp_usd")), _zweit_usd(x.get("rest_liq_usd"))
        abst = f"{tp or '?'} vor TP / {liq or '?'} vor Liq ({quelle})" if (tp or liq) else "Abstand nicht lesbar"
        teile.append(f"A: {name} {zweit_art(a)} (seit {_zweit_hhmm(a.get('started_at'))}) — {abst}")
        daten_a.append({"plan": str(a.get("id")), "konto": name, "rest_tp_usd": x.get("rest_tp_usd"), "rest_liq_usd": x.get("rest_liq_usd"), "quelle": quelle})
    text = (f"{wer} · {ZWEIT_FENSTER_NAME.get(fenster, fenster)}: {len(gruppe)} Big Trades laufen. " + " · ".join(teile)
            + f" · B: {zweit_konto_name(b)} {zweit_art(b)} (gestartet {_zweit_hhmm(b.get('started_at'))}) · Puls steht in {puls_wo or 'unbekannt (Reader-Konto nicht frisch)'}")
    return (f"{b.get('id')}|zweit_gestartet", 2, "zweit_gestartet", "Zweiter Big Trade gestartet", text, str(uid), str(b.get("id")),
            {"fenster": fenster, "andere": daten_a, "puls": puls_wo})


ZWEIT_WARTET_ARTEN = {"zweit": PULS_HEIM_CODE_ZWEIT, "firma": PULS_HEIM_CODE_FIRMA, "markt": PULS_HEIM_CODE_MARKT}
ZWEIT_WARTET_WORT = {PULS_HEIM_CODE_ZWEIT: "zu nah / schon voll", PULS_HEIM_CODE_FIRMA: "gleiche Firma", PULS_HEIM_CODE_MARKT: "Markteröffnung"}


def zweit_wartet_ereignis(p, code, grund, namen):
    """REIN RECHNEND (testbar): Meldung (2), einmal je Plan → (schluessel, prio, art, titel, text, uid, plan_id, daten)."""
    uid = str((p or {}).get("user_id"))
    wer = namen.get(uid, uid[:8])
    text = f"{wer} · {zweit_konto_name(p)} {zweit_art(p)}: wartet — {ZWEIT_WARTET_WORT.get(code, code)}: {str(grund or '').strip() or '?'}"
    return (f"{p.get('id')}|zweit_wartet", 2, "zweit_wartet", "Zweiter Big Trade wartet", text[:400], uid, str(p.get("id")), {"code": code})


def zweit_prio_ereignis(uid, von, nach, a_von, a_nach, namen, at_ms):
    """REIN RECHNEND (testbar): Meldung (3), einmal je Wechsel (Schlüssel mit von, nach und Minute des Wechsels)."""
    wer = namen.get(str(uid), str(uid)[:8])
    pkt = lambda v: f"{_wd_num(v):.0f} Pkt" if _wd_num(v) is not None else "? Pkt"   # noqa: E731
    text = (f"{wer}: Puls von {zweit_konto_name(von)} ({pkt(a_von)} bis TP/Liq) ins Konto {zweit_konto_name(nach)} ({pkt(a_nach)}) — näher an TP/Liq, "
            f"Userscript liest jetzt dort")
    minute = int((at_ms or 0) // 60000)
    return (f"{nach.get('id')}|prio_wechsel|{str(von.get('id'))[:8]}|{minute}", 2, "prio_wechsel", "Puls hat das Konto gewechselt (Priorität)", text,
            str(uid), str(nach.get("id")), {"von": str(von.get("id")), "a_von": _wd_num(a_von), "a_nach": _wd_num(a_nach)})


def zweit_start_merken(pid, andere):
    """Klick-Riegel /richtung/frei frei mit weiteren laufenden Big Trades: deren Abstand je Plan merken (Speicher, 2 h)."""
    with _ZWEIT_LOCK:
        jetzt = time.time()
        for k in [k for k, v in _ZWEIT_START_MERK.items() if jetzt - v.get("at", 0) > ZWEIT_MERK_S]:
            _ZWEIT_START_MERK.pop(k, None)
        _ZWEIT_START_MERK[str(pid)] = {"at": jetzt, "andere": [{k: x.get(k) for k in ("plan", "konto", "art", "rest_tp_usd", "rest_liq_usd")} for x in andere or ()]}


def _zweit_senden(ev):
    """Ereignis einmal senden: Speicher-Merker (_alarm['gemeldet']) + alarm_log der letzten 24 h. Wirft nie."""
    key = ev[0]
    with _ZWEIT_LOCK:
        if key in _alarm["gemeldet"]:
            return False
        _alarm["gemeldet"][key] = time.time()
    schon = alarm_im_log([key], ZWEIT_LOG_S)
    if schon and key in schon:
        return False
    alarm_senden(ev[1], ev[2], ev[3], ev[4], uid=ev[5], plan_id=ev[6], schluessel=key, tag=f"alarm-{ev[2]}-{ev[6][:8]}", daten=ev[7])
    return True


def zweit_wartet_melden(plan_id, code, grund):
    """Klick-Riegel sperrt einen weiteren Big Trade → Meldung (2) im Hintergrund (der Riegel antwortet ohne Wartezeit). Nur HT-IDs."""
    def lauf():
        try:
            if not _alarm_empfaenger() or f"{plan_id}|zweit_wartet" in _alarm["gemeldet"]:
                return
            p = (sb_select("trade_plans", {"select": "id,user_id,master_name,master_firm,richtung,master_contracts,master_symbol_root", "id": f"eq.{plan_id}"}) or [None])[0]
            namen, aus = _ap_namen()
            if p and str(p.get("user_id")) not in aus and not _alarm_fremd_verwaltet(p.get("user_id")):
                _zweit_senden(zweit_wartet_ereignis(p, code, grund, namen))
        except Exception as e:
            print(f"[alarm] ⚠️ Zweit wartet {str(plan_id)[:8]}: {type(e).__name__}: {e}", flush=True)
    threading.Thread(target=lauf, daemon=True).start()


def zweit_alarm_tick(aus, jetzt):
    """alarm_tick (1×/min): Meldungen (1) und (2) aus den offenen/geplanten Big Trades der HT-IDs."""
    rows = _sb_all("trade_plans", {"select": PULS_HEIM_FELDER + ",ah_status:mt5_baseline->apex_hedge->>status", "status": "eq.open", "route": "in.(tvv2,tsv2,polar)"}) or []
    rows = [r for r in rows if str(r.get("user_id")) not in aus and not _alarm_fremd_verwaltet(r.get("user_id"))]
    namen, _a = _ap_namen()
    for uid, fenster, gruppe in zweit_gruppen(rows):
        b = gruppe[-1]
        key = f"{b.get('id')}|zweit_gestartet"
        if key in _alarm["gemeldet"]:
            continue
        with _ZWEIT_LOCK:
            merk = _ZWEIT_START_MERK.get(str(b.get("id")))
        jetzt_naehe = {}
        if not merk:
            try:
                jetzt_naehe = {str(x[0].get("id")): x[2] for x in _puls_heim_naehe(gruppe[:-1], lambda _a2, _p: (PULS_HEIM_ZWEIT_USD, PULS_HEIM_ZWEIT_USD))}
            except Exception as e:
                print(f"[alarm] ⚠️ Zweit-Abstand {str(b.get('id'))[:8]}: {type(e).__name__}: {e}", flush=True)
        puls = None
        pc = ((b.get("mt5_baseline") or {}).get("hedge") or {}).get("pc") if isinstance(b.get("mt5_baseline"), dict) else None
        if fenster == "tsx":
            puls = "TopstepX (eigenes Fenster, kein Reader-Konto)"
        elif pc:
            try:
                ep = (sb_select("echoplus_live", {"select": "konto,updated_at", "pc_name": f"eq.{pc}", "limit": "1"}) or [None])[0]
                t = _alarm_ts((ep or {}).get("updated_at"))
                if ep and t and (jetzt - t).total_seconds() <= ZWEIT_PULS_KONTO_MAX_S:
                    puls = zweit_puls_wo(ep.get("konto"), gruppe)
            except Exception as e:
                print(f"[alarm] ⚠️ Puls-Konto {pc}: {type(e).__name__}: {e}", flush=True)
        _zweit_senden(zweit_gestartet_ereignis(uid, fenster, gruppe, namen, merk, jetzt_naehe, puls))
    # (2) aus der DB-Sperre (prophos_big_trade_halten / Claim-Trigger); „voll“ (art zweit) nur, wenn der Schalter auf ≥ 2 steht
    mx = puls_heim_zweit_regel(_puls_heim_regel())[0]
    geplant = _sb_all("trade_plans", {"select": "id,user_id,status,master_name,master_firm,richtung,master_contracts,master_symbol_root,ss:mt5_baseline->start_sperre",
                                      "status": "eq.planned", "route": "in.(tvv2,tsv2,polar)", "mt5_baseline->start_sperre->>art": "in.(zweit,firma,markt)",
                                      "updated_at": f"gte.{(jetzt - timedelta(hours=3)).isoformat()}"}) or []
    for p in geplant:
        if str(p.get("user_id")) in aus or _alarm_fremd_verwaltet(p.get("user_id")) or f"{p.get('id')}|zweit_wartet" in _alarm["gemeldet"]:
            continue
        ss = p.get("ss") if isinstance(p.get("ss"), dict) else {}
        code = ZWEIT_WARTET_ARTEN.get(str(ss.get("art") or ""))
        if code and (code != PULS_HEIM_CODE_ZWEIT or mx >= 2):
            _zweit_senden(zweit_wartet_ereignis(p, code, ss.get("text"), namen))


def puls_heim_pruefen(pc, ausser=None, route=None):
    """Darf der Puls auf diesem PC das Konto wechseln? → {frei, code?, grund?, big_trade?}. Riegel aus (Tabelle fehlt, aktiv false, kein PC,
    kein Big Trade hier) → frei. Big Trade nah oder nicht prüfbar → nicht frei. Fehler beim Rechnen → nicht frei (fail-closed), Grund im Text.
    route (30.10.2026, NUR TV WARTET): Route der anfragenden Aktion — Echo (mt5/mt5v2) immer frei, tvv2 sieht nur das TV-Fenster, tsv2 nur
    TopstepX; ohne Route alle Fenster wie bisher."""
    regel = _puls_heim_regel()
    if not isinstance(regel, dict) or regel.get("aktiv") is False or not pc:
        return {"frei": True}
    fenster = puls_heim_fenster(route)
    if fenster is None:
        return {"frei": True}            # Echo: kein TradingView-Kontowechsel, das Auge liest weiter (Befund S6)
    try:
        rows = _sb_all("trade_plans", {"select": PULS_HEIM_FELDER, "status": "eq.open", "route": "in.(tvv2,tsv2)",
                                       "mt5_baseline->hedge->>pc": f"eq.{pc}"})
        rows = puls_heim_im_fenster(rows, fenster)
        big = puls_heim_big_trades(rows, pc, ausser)
        wd_schw = puls_heim_wd_schwellen(regel)
        wds = puls_heim_wd_trades(rows, pc, ausser) if wd_schw else []
        apex_schw = puls_heim_apex_schwellen(regel)
        apexe = puls_heim_apex_trades(rows, pc, ausser) if apex_schw else []
        if not big and not wds and not apexe:
            return {"frei": True}
        ids = sorted({str(p.get("master_account_id")) for p in big + apexe + wds if p.get("master_account_id")})
        accs = {str(a["id"]): a for a in (sb_select("accounts", {"select": "id,name,firm,account_type,starting_balance,external_id,max_drawdown,max_daily_drawdown,tv_balance,tv_balance_at",
                                                                     "id": f"in.({','.join(ids)})"}) or [])} if ids else {}
        fruehere = _wd_fruehere_trades(ids, streng=True)   # KK1: Lesefehler → except unten = nicht frei (fail-closed wie jeder Rechenfehler hier)
        liq_regeln, liq_verlauf, liq_kw = _liq_regeln_laden(), _liq_verlauf_laden(ids), _liq_kw_laden()
        kurse = _kurs_jetzt()
        for p in big:
            acc = accs.get(str(p.get("master_account_id") or ""))
            z = _lt_zeile(p, acc, {}, {}, wd_vorher_waehlen(p, fruehere), regeln=liq_regeln, fruehere=fruehere, verlauf=liq_verlauf,
                          kw_firmen=ap_unt_firmen(p.get("user_id"), liq_kw, streng=False) if liq_kw is not None else None)   # UNT3
            kurs = puls_heim_kurs_frisch(kurse, z.get("symbol_root"))
            n = puls_heim_nah(z, kurs, puls_heim_schwellen(regel, (acc or {}).get("firm") or p.get("master_firm")))
            name = f"{(acc or {}).get('firm') or p.get('master_firm') or 'Big Trade'} …{str((acc or {}).get('external_id') or '')[-4:]}"
            art = f"{str(z.get('richtung') or '').upper()} {int(z['kt']) if _wd_num(z.get('kt')) else '?'} {z.get('symbol_root') or 'NQ'}"
            info = {"plan": str(p.get("id")), "konto": name, "art": art, "kurs": kurs, "tp_level": n["tp_level"], "liq_level": n["liq_level"],
                    "rest_tp_usd": n["rest_tp_usd"], "rest_liq_usd": n["rest_liq_usd"]}
            if n["nah"] is None:
                return {"frei": False, "code": PULS_HEIM_CODE_UNKLAR, "big_trade": info,
                        "grund": f"Big Trade {name} ({art}) nicht prüfbar: {n['grund']} — Puls bleibt im Konto, nichts gesendet"}
            if n["nah"]:
                return {"frei": False, "code": PULS_HEIM_CODE_NAH, "big_trade": info,
                        "grund": f"Big Trade {name} ({art}) ist {n['grund']} — Puls bleibt im Konto, nichts gesendet"}
        # Apex-Challenge (02.11.2026) vor den Winning Days; beide: eigene 100-$-Grenze, nicht prüfbar = frei (s. oben)
        for p, schw, art_name, art_info in ([(x, apex_schw, "Apex-Challenge", {"apex_hedge": True}) for x in apexe]   # SCHLÜSSEL, kein Anzeigename (S3 05.11.2026, Rückbau MK1b): der Tab liest den Grund-Anfang (sfIstWdSperre/sfIstApexSperre → 2–4 min statt 15 min, „Apex-Challenge nah“) — nie umbenennen ohne den Tab
                                            + [(x, wd_schw, MODELL_NAME["winning_day"], {"winning_day": True}) for x in wds]):
            acc = accs.get(str(p.get("master_account_id") or ""))
            z = _lt_zeile(p, acc, {}, {}, wd_vorher_waehlen(p, fruehere), regeln=liq_regeln, fruehere=fruehere, verlauf=liq_verlauf,
                          kw_firmen=ap_unt_firmen(p.get("user_id"), liq_kw, streng=False) if liq_kw is not None else None)   # UNT3
            kurs = puls_heim_kurs_frisch(kurse, z.get("symbol_root"))
            n = puls_heim_nah(z, kurs, schw)
            # Liq-Level unbekannt → puls_heim_nah sagt „nicht prüfbar“, obwohl der TP-Rest feststeht: dann zählt der TP allein (Prüfer 22.10.2026)
            tp_nah = n["nah"] is None and n["rest_tp_usd"] is not None and n["rest_tp_usd"] <= schw[0]
            if not (n["nah"] or tp_nah):
                continue
            if tp_nah:
                n["grund"] = f"{_ap_de(max(0.0, n['rest_tp_usd']), 0)} $ vor dem TP (Grenze {_ap_de(schw[0], 0)} $)"
            name = f"{(acc or {}).get('firm') or p.get('master_firm') or art_name} …{str((acc or {}).get('external_id') or '')[-4:]}"
            art = f"{str(z.get('richtung') or '').upper()} {int(z['kt']) if _wd_num(z.get('kt')) else '?'} {z.get('symbol_root') or 'MNQ'}"
            info = {"plan": str(p.get("id")), "konto": name, "art": art, "kurs": kurs, "tp_level": n["tp_level"], "liq_level": n["liq_level"],
                    "rest_tp_usd": n["rest_tp_usd"], "rest_liq_usd": n["rest_liq_usd"], **art_info}
            return {"frei": False, "code": PULS_HEIM_CODE_NAH, "big_trade": info,
                    "grund": f"{art_name} {name} ({art}) ist {n['grund']} — Puls bleibt im Konto, nichts gesendet"}
        return {"frei": True}
    except Exception as e:
        print(f"[puls-heim] ⚠️ Prüfung PC {pc}: {type(e).__name__}: {str(e)[:160]}", flush=True)
        return {"frei": False, "code": PULS_HEIM_CODE_UNKLAR, "grund": f"Big-Trade-Prüfung gerade nicht möglich ({type(e).__name__}) — Puls bleibt im Konto, nichts gesendet"}


@app.route("/admin/puls-heim", methods=["GET", "OPTIONS"])
def admin_puls_heim():
    """GET /admin/puls-heim?pc=pc-xxxxxx → {ok, frei, code?, grund?, big_trade?} — derselbe Riegel „Puls bleibt zu Hause" (puls_heim_pruefen)
    für den PC-Tab (19.10.2026, Finn „wie du denkst": auch Balance-Lesungen ↻ und Rundgang wechseln das Konto im Puls-Chrome und reißen
    dem Reader die Lese-Lücke — der Tab fragt hier VOR jeder Lesung eines fremden Kontos, solange auf dem PC ein Big Trade läuft).
    Auth wie /admin/live-trades (eingeloggt reicht, Header sb-token); die Rechnung läuft mit service role, weil fremde Pläne auf dem PC
    per RLS unsichtbar wären. Kein Big Trade auf dem PC → frei, ohne weitere Reads."""
    if request.method == "OPTIONS":
        return "", 200
    _me, err = _wd_login()
    if err:
        return err
    pc = str(request.args.get("pc") or "").strip()[:40]
    if not re.fullmatch(r"pc-[a-z0-9]{4,12}", pc):
        return jsonify({"ok": False, "msg": "pc fehlt (pc-xxxxxx)"}), 400
    # route (30.10.2026, NUR TV WARTET): tvv2 = TradingView-Lesung, tsv2 = TopstepX-Lesung, mt5/mt5v2 = Echo (frei); ohne = alle Fenster
    route = str(request.args.get("route") or "").strip().lower()[:10] or None
    out = jsonify(dict({"ok": True}, **puls_heim_pruefen(pc, route=route)))
    out.headers["Cache-Control"] = "no-store"
    return out


@app.route("/admin/zweit-frei", methods=["GET", "OPTIONS"])
def admin_zweit_frei():
    """GET /admin/zweit-frei?plan=<uuid> → {ok, frei, code?, grund?, big_trade?, max_je_id, zweit_usd} — ZWEI ORBIT (30.10.2026, Stück 1):
    darf dieser geplante Big Trade jetzt starten (puls_heim_zweit_pruefen)? Für den Sofort-Start-Wächter im PC-Tab (S7, alle 20–40 s
    gewürfelt). Auth wie /admin/puls-heim (eingeloggt); nur eigene Pläne bzw. Pläne der eigenen Sicht. Fehler → frei false."""
    if request.method == "OPTIONS":
        return "", 200
    me, err = _wd_login()
    if err:
        return err
    pid = str(request.args.get("plan") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f-]{36}", pid):
        return jsonify({"ok": False, "msg": "plan fehlt"}), 400
    try:
        plan = (sb_select("trade_plans", {"select": "id,user_id,status,route,hedge_eur,orbit_v3,winning_day,konto_typ,orbit_gesendet_at,started_at,"
                                                    "apex_hedge:mt5_baseline->apex_hedge", "id": f"eq.{pid}"}) or [None])[0]
    except Exception as e:
        return jsonify({"ok": True, "frei": False, "code": PULS_HEIM_CODE_UNKLAR, "grund": f"Plan nicht lesbar ({type(e).__name__})"}), 200
    if not plan:
        return jsonify({"ok": False, "msg": "Plan nicht gefunden"}), 404
    if str(plan.get("user_id")) != str(me):
        try:
            sicht, _v = admin_sicht_lesen(str(me))
        except Exception:
            return jsonify({"ok": False, "msg": "Anmeldung nicht prüfbar"}), 502
        _m, aerr = _admin_auth()
        if not ((aerr is None and sicht is None) or (sicht is not None and str(plan.get("user_id")) in {str(u) for u in sicht})):
            return jsonify({"ok": False, "msg": "nur eigene Pläne"}), 403
    if isinstance(plan.get("apex_hedge"), dict):
        plan["ah_status"] = plan["apex_hedge"].get("status")
    out = jsonify(dict({"ok": True}, **puls_heim_zweit_pruefen(plan)))
    out.headers["Cache-Control"] = "no-store"
    return out


def polar_slave_riegel_urteil(lauf, wer_uid, richtung, konto):
    """REIN RECHNEND (testbar): POLAR-SLAVE-RIEGEL (30.10.2026, Bauplan S8) — prüft die Anfrage des Slave-PCs gegen den Polar-Lauf, bevor die
    DB gefragt wird. → (None, status, antwort) wenn abgelehnt, sonst ((user, firma, richtung, plan_id, account_id), None, None).
    lauf = polar_lauf-Zeile {plan_id, slave_user_id, slave {auftrag {account_id, richtung, …}}}, konto = accounts-Zeile {id, user_id, firm}."""
    if not isinstance(lauf, dict):
        return None, 400, {"ok": False, "msg": "Polar-Lauf unbekannt"}
    su = str(lauf.get("slave_user_id") or "")
    if not su or su != str(wer_uid or ""):
        return None, 403, {"ok": False, "msg": "Polar-Lauf gehört nicht zu dieser ID (Slave)"}
    sl = lauf.get("slave") if isinstance(lauf.get("slave"), dict) else {}
    auf = sl.get("auftrag") if isinstance(sl.get("auftrag"), dict) else {}
    aid = str(auf.get("account_id") or "")
    if not aid or not isinstance(konto, dict) or str(konto.get("id")) != aid or str(konto.get("user_id") or "") != su:
        return None, 400, {"ok": False, "msg": "Slave-Konto des Laufs nicht lesbar oder passt nicht zur Slave-ID"}
    if richtung not in ("buy", "sell"):
        return None, 400, {"ok": False, "msg": "richtung fehlt"}
    if str(auf.get("richtung") or "").lower() != richtung:
        return None, 200, {"ok": True, "frei": False, "code": "gegenrichtung", "grund": "Richtung passt nicht zum Polar-Lauf — nichts gesendet"}
    return (su, konto.get("firm") or auf.get("firm") or "", richtung, str(lauf.get("plan_id") or "") or None, aid), None, None


def _richtung_frei_polar_slave(d, wer):
    """/richtung/frei im KONTO-MODUS für den Polar-Slave-PC (30.10.2026, Bauplan S8): Body {polar_lauf, seite: slave, richtung}. Der
    Polar-Plan gehört der MASTER-ID — geprüft wird hier Slave-ID × Slave-Firma (CFD) mit prophos_gegenrichtung_frei_konto, dieselbe
    Regel wie polar_app _richtung_konto beim /polar/start. Keine Heim-/Zweit-Prüfung (Slave = MT5, wie master-order). Fehler → 503/400,
    das Panel klickt dann nicht (fail-closed)."""
    lid = str(d.get("polar_lauf") or "").strip().lower()
    r = str(d.get("richtung") or "").strip().lower()
    if str(d.get("seite") or "") != "slave" or not re.fullmatch(r"[0-9a-f-]{36}", lid):
        return jsonify({"ok": False, "msg": "polar_lauf/seite fehlt"}), 400
    try:
        lauf = (sb_select("polar_lauf", {"select": "id,plan_id,slave_user_id,slave", "id": f"eq.{lid}", "limit": "1"}) or [None])[0]
        aid = str((((lauf or {}).get("slave") or {}).get("auftrag") or {}).get("account_id") or "") if isinstance(lauf, dict) else ""
        konto = (sb_select("accounts", {"select": "id,user_id,firm", "id": f"eq.{aid}", "limit": "1"}) or [None])[0] if re.fullmatch(r"[0-9a-f-]{36}", aid) else None
    except Exception as e:
        return jsonify({"ok": False, "msg": f"DB nicht erreichbar: {str(e)[:120]}"}), 503
    arg, status, antwort = polar_slave_riegel_urteil(lauf, wer[0], r, konto)
    if arg is None:
        if status != 200:
            print(f"[polar-slave] ⛔ {lid[:8]} PC {wer[1]}: {antwort.get('msg')}", flush=True)
        out = jsonify(dict(antwort, uid=wer[0], pc=wer[1]) if status == 200 else antwort)
        out.headers["Cache-Control"] = "no-store"
        return out, status
    su, firma, richt, pid, aid = arg
    try:
        resp = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/rpc/prophos_gegenrichtung_frei_konto", headers=_sb_headers(), timeout=(5, 15),
                           json={"p_user": su, "p_firma": firma, "p_richtung": richt, "p_ausser_plan": pid, "p_ausser_konto": aid})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"DB nicht erreichbar: {str(e)[:120]}"}), 503
    if resp.status_code != 200:
        return jsonify({"ok": False, "msg": f"DB-Antwort {resp.status_code}: {(resp.text or '')[:160]}"}), 503
    try:
        erg = resp.json()
    except ValueError:
        return jsonify({"ok": False, "msg": "DB-Antwort kein JSON"}), 503
    if not isinstance(erg, dict) or "frei" not in erg:
        return jsonify({"ok": False, "msg": "DB-Antwort unerwartet"}), 503
    frei = erg.get("frei") is True
    out = jsonify({"ok": True, "frei": frei, "code": None if frei else "gegenrichtung", "grund": erg.get("grund"), "firma": erg.get("firma") or firma,
                   "plan": erg.get("plan"), "uid": wer[0], "pc": wer[1], "polar_lauf": lid, "seite": "slave"})
    out.headers["Cache-Control"] = "no-store"
    if not frei:
        print(f"[polar-slave] ⛔ {lid[:8]} PC {wer[1]}: {erg.get('grund')}", flush=True)
    return out


@app.route("/richtung/frei", methods=["POST"])
def richtung_frei():
    """HARTE LINIE FÜR DEN PULS-KLICK (13.10.2026, Finn nach Mikes Topstep-Short + zwei geplanten Longs: „wenn aus irgendeinem Grund
    der Wächter ausfällt … dass da nie was passieren kann"): das Panel am PC fragt VOR jedem scharfen Klick hier nach — läuft bei
    derselben ID × Firma auf einem anderen Konto ein Trade in Gegenrichtung? Antwort aus der DB-Funktion prophos_gegenrichtung_frei
    (sql/2026-10-13_gegenrichtung_hart.sql, service role — RLS zeigt dem PC fremde Zeilen nicht). Ohne „ok+frei" klickt das Panel
    nicht (fail-closed). Nur Railway, Header X-Code-Token (derselbe Schlüssel wie /code/stand), Body {plan_id, richtung}.
    REVIEW GELESEN = FREI (Finn 19.10.2026 23:55 Dubai, sql/2026-10-19_gegenrichtung_review_gelesen.sql): ein beendeter Plan in review sperrt
    nur, solange seine Endlesung fehlt (prophos_plan_gelesen) — gelesen heißt frei, ohne Abhaken. Die Regel steckt in der DB-Funktion, hier
    ändert sich nichts: Antwort weiter fail-closed, kein „frei" ohne DB-Antwort."""
    if not _code_stand_sha():
        return jsonify({"ok": False, "msg": "nur auf Railway"}), 404
    wer = _code_zugang()
    if not wer:
        return jsonify({"ok": False, "msg": "kein gültiger Schlüssel"}), 403
    d = request.get_json(silent=True) or {}
    if d.get("polar_lauf") is not None or str(d.get("seite") or "") == "slave":
        return _richtung_frei_polar_slave(d, wer)
    pid = str(d.get("plan_id") or "").strip().lower()
    r = str(d.get("richtung") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f-]{36}", pid) or r not in ("buy", "sell"):
        return jsonify({"ok": False, "msg": "plan_id/richtung fehlt"}), 400
    try:
        resp = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/rpc/prophos_gegenrichtung_frei", headers=_sb_headers(),
                           timeout=(5, 15), json={"p_plan": pid, "p_richtung": r})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"DB nicht erreichbar: {str(e)[:120]}"}), 503
    if resp.status_code != 200:
        return jsonify({"ok": False, "msg": f"DB-Antwort {resp.status_code}: {(resp.text or '')[:160]}"}), 503
    try:
        erg = resp.json()
    except ValueError:
        return jsonify({"ok": False, "msg": "DB-Antwort kein JSON"}), 503
    if not isinstance(erg, dict):
        return jsonify({"ok": False, "msg": "DB-Antwort unerwartet"}), 503
    antwort = {"ok": True, "frei": erg.get("frei") is True, "code": None if erg.get("frei") is True else "gegenrichtung", "grund": erg.get("grund"),
               "firma": erg.get("firma"), "plan": erg.get("plan"), "uid": wer[0], "pc": wer[1]}
    if antwort["frei"]:
        # NUR TV WARTET + ZWEI ORBIT (30.10.2026): Route/Art des Plans für die Heim-Prüfung (Fenster) und die Zweit-Prüfung. Nicht lesbar →
        # Heim-Prüfung über alle Fenster (wie bisher) und Zweit-Prüfung nicht frei (fail-closed)
        try:
            plan = (sb_select("trade_plans", {"select": "id,user_id,status,route,hedge_eur,orbit_v3,winning_day,konto_typ,orbit_gesendet_at,started_at,"
                                                        "apex_hedge:mt5_baseline->apex_hedge", "id": f"eq.{pid}"}) or [None])[0]
            if isinstance(plan, dict) and isinstance(plan.get("apex_hedge"), dict):
                plan["ah_status"] = plan["apex_hedge"].get("status")
        except Exception as e:
            print(f"[puls-heim] ⚠️ Plan {pid[:8]} nicht lesbar: {type(e).__name__}: {str(e)[:120]}", flush=True)
            plan = False
        # PULS BLEIBT ZU HAUSE (19.10.2026): Big Trade dieses PCs nah am TP/an der Liq → Puls verlässt das Konto nicht (puls_heim_pruefen)
        heim = puls_heim_pruefen(wer[1], pid, (plan or {}).get("route") if plan else None)
        if heim.get("frei"):
            heim = (puls_heim_zweit_pruefen(plan) if plan else {"frei": True}) if plan is not False else \
                {"frei": False, "code": PULS_HEIM_CODE_UNKLAR, "grund": "Plan nicht lesbar — Zweit-Prüfung nicht möglich, nichts gesendet"}
        if heim.get("frei") and heim.get("zweit_andere"):
            zweit_start_merken(pid, heim["zweit_andere"])   # Z6: Abstand der laufenden beim Start (Handy-Meldung „Zweiter Big Trade gestartet“)
        if not heim.get("frei"):
            # zweit_wartet geht als big_trade_nah raus (Panel + PC-Tab kennen nur die Heim-Codes: Plan bleibt Geplant, kein Start-Fehler-Rot);
            # die Unterscheidung holt der Sofort-Start-Wächter des Tabs über GET /admin/zweit-frei (S7), zweit: true für neuere Panels
            # 03.11.2026 (Z5): firma_laeuft / markt_oeffnung genauso; der echte Code steht in zweit_code (für die Texte im Tab), bis = Fensterende
            zw = heim.get("code") in PULS_HEIM_ZWEIT_CODES
            code = PULS_HEIM_CODE_NAH if zw else heim.get("code")
            antwort.update(frei=False, code=code, grund=heim.get("grund"), big_trade=heim.get("big_trade"),
                           zweit=zw, zweit_code=heim.get("code") if zw else None, bis=heim.get("bis"))
            if zw and (heim.get("code") != PULS_HEIM_CODE_ZWEIT or int(heim.get("max_je_id") or 1) >= 2):
                zweit_wartet_melden(pid, heim.get("code"), heim.get("grund"))   # Z6: einmal je Plan aufs Handy (Hintergrund); „voll“ bei Schalter 1 = heute, kein Alarm
            print(f"[puls-heim] ⛔ PC {wer[1]} Plan {pid[:8]}: {heim.get('grund')}", flush=True)
    out = jsonify(antwort)
    out.headers["Cache-Control"] = "no-store"
    return out


# ══ MAIL-REITER (16.10.2026, Finn: „Jedes Gmail ist ausschließlich für Prophos, ALLE Mails sollen rein. So simpel wie möglich … Jede ID
# bekommt nur ihre eigenen Mails"). Ein Google-Apps-Script im Gmail-Konto der ID schickt alle 5 min neue Mails (Erst-Lauf: 90 Tage in
# Portionen) hierher. Der Schlüssel im Header X-Mail-Schluessel wird gehasht und in mail_schluessel gesucht — die ID kommt NIE aus dem Body.
# Gespeichert wird mit service role in mails (sql/2026-10-16_mail_reiter.sql); lesen tut das Frontend per RLS nur die eigenen Zeilen.
# Bestehende Mails werden nie überschrieben (ignore-duplicates): „gelesen" in Prophos bleibt, ein doppelter Import schadet nicht.
# Größen hart gedeckelt, HTML wird hier nur als Text abgelegt und im Browser ausschließlich im sandbox-iframe ohne Skripte gezeigt. ══
MAIL_MAX_STAPEL = 50
MAIL_MAX_TEXT = 50_000
MAIL_MAX_HTML = 200_000
MAIL_MAX_BODY = 14 * 1024 * 1024          # 50 × (200 KB HTML + 50 KB Text) + JSON-Hülle
MAIL_ID_RE = re.compile(r"[A-Za-z0-9_-]{1,64}")


def mail_zeile(roh, uid):
    """REIN RECHNEND (testbar): eine Mail aus dem Script → Zeile für public.mails oder None (ungültig). Alle Felder gekürzt, nur
    erlaubte Schlüssel, Datum als ISO (UTC), Anhänge nur Name/Größe/Typ."""
    if not isinstance(roh, dict):
        return None
    mid = str(roh.get("id") or "").strip()
    if not MAIL_ID_RE.fullmatch(mid):
        return None

    def s(k, n):
        v = roh.get(k)
        return None if v is None else str(v)[:n]
    datum = None
    try:
        d = datetime.fromisoformat(str(roh.get("datum") or "").replace("Z", "+00:00"))
        datum = (d if d.tzinfo else d.replace(tzinfo=timezone.utc)).astimezone(timezone.utc).isoformat()
    except ValueError:
        datum = None
    anh = []
    for a in (roh.get("anhaenge") if isinstance(roh.get("anhaenge"), list) else [])[:30]:
        if not isinstance(a, dict):
            continue
        try:
            gr = max(0, int(a.get("groesse") or 0))
        except (TypeError, ValueError):
            gr = 0
        anh.append({"name": str(a.get("name") or "")[:200], "groesse": gr, "typ": str(a.get("typ") or "")[:100]})
    labels = [str(x)[:60] for x in (roh.get("labels") if isinstance(roh.get("labels"), list) else [])[:30] if x is not None]
    tid = str(roh.get("thread") or "").strip()
    return {"user_id": uid, "gmail_msg_id": mid, "thread_id": tid if MAIL_ID_RE.fullmatch(tid) else None,
            "von": s("von", 500), "an": s("an", 2000), "betreff": s("betreff", 500), "datum": datum,
            "snippet": s("snippet", 500), "text": s("text", MAIL_MAX_TEXT), "html": s("html", MAIL_MAX_HTML),
            "anhaenge": anh, "gelesen": bool(roh.get("gelesen")), "labels": labels}


def _mail_user_zum_schluessel(token):
    """Klartext-Schlüssel → user_id über den SHA-256 in mail_schluessel (service role), None wenn unbekannt."""
    t = str(token or "").strip()
    if not re.fullmatch(r"[0-9a-f]{64}", t):
        return None
    h = hashlib.sha256(t.encode("ascii")).hexdigest()
    # bewusst ohne Cache: nach „Neu verbinden" ist der alte Schlüssel sofort ungültig (Master 16.10.2026); ein Lookup je 5-min-Lauf und ID
    rows = sb_select("mail_schluessel", {"select": "user_id", "token_sha256": f"eq.{h}", "limit": "1"}) or []
    return str(rows[0].get("user_id") or "") or None if rows else None


@app.route("/mail/eingang", methods=["POST"])
def mail_eingang():
    """POST /mail/eingang, Header X-Mail-Schluessel, Body {mails: [...≤ 50], stand: {fertig, gesendet}} → {ok, angenommen}.
    403 = Schlüssel unbekannt (neu verbunden → das alte Script hört damit auf)."""
    if request.content_length is None:          # ohne Längenangabe (chunked) griffe der Deckel nicht (Prüfung Slave 2)
        return jsonify({"ok": False, "msg": "Content-Length fehlt"}), 411
    if request.content_length > MAIL_MAX_BODY:
        return jsonify({"ok": False, "msg": "zu groß"}), 413
    try:
        uid = _mail_user_zum_schluessel(request.headers.get("X-Mail-Schluessel"))
    except Exception as e:
        return jsonify({"ok": False, "msg": f"DB nicht erreichbar: {str(e)[:120]}"}), 503
    if not uid:
        return jsonify({"ok": False, "msg": "Schlüssel unbekannt — in Prophos unter Mail neu verbinden"}), 403
    d = request.get_json(silent=True) or {}
    roh = d.get("mails") if isinstance(d.get("mails"), list) else []
    if len(roh) > MAIL_MAX_STAPEL:
        return jsonify({"ok": False, "msg": f"höchstens {MAIL_MAX_STAPEL} Mails je Aufruf"}), 400
    zeilen, gesehen = [], set()
    for m in roh:
        z = mail_zeile(m, uid)
        if z and z["gmail_msg_id"] not in gesehen:
            gesehen.add(z["gmail_msg_id"])
            zeilen.append(z)
    try:
        if zeilen:
            r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/mails", params={"on_conflict": "user_id,gmail_msg_id"}, json=zeilen,
                            headers=_sb_headers("resolution=ignore-duplicates,return=minimal"), timeout=(5, 60))
            _sb_pruefen(r)
        st = d.get("stand") if isinstance(d.get("stand"), dict) else {}
        upd = {"zuletzt_at": datetime.now(timezone.utc).isoformat(),
               "import_stand": {"fertig": bool(st.get("fertig")), "gesendet": int(st.get("gesendet") or 0) if str(st.get("gesendet") or "0").isdigit() else 0}}
        neueste = max((z["datum"] for z in zeilen if z.get("datum")), default=None)
        if neueste:
            alt = (sb_select("mail_schluessel", {"select": "zuletzt_mail_at", "user_id": f"eq.{uid}"}) or [{}])[0].get("zuletzt_mail_at")
            if not alt or str(neueste) > str(alt).replace(" ", "T"):
                upd["zuletzt_mail_at"] = neueste
        sb_update("mail_schluessel", {"user_id": f"eq.{uid}"}, upd)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Speichern fehlgeschlagen: {str(e)[:160]}"}), 503
    # Payout-Matcher (29.10.2026): Stand der Payout-Anfragen aus den Mails des Stapels — nach dem Speichern, wirft nie, hält den Import nicht auf
    if zeilen:
        payout_mail_verarbeiten(zeilen)
        tv_konten_mail_auftraege(zeilen, uid)   # Kauf-Mail einer TradingView-Firma → Auftrag „Konto-Liste lesen" (29.10.2026, wirft nie)
    return jsonify({"ok": True, "angenommen": len(zeilen)})


# ══ PAYOUT-MATCHER (29.10.2026, Finn ~02:00: „Jedes Mal, wenn ich ein Payout anfrage, bekomme ich E-Mails (angefragt, approved, geschickt).
# Die Payouts sollen unter Admin automatisch im Feld ‚Liegt bei‘ den Stand bekommen, mit Meldung an mich. Abhaken bleibt manuell.“)
# Einziger Verarbeitungspunkt = /mail/eingang beim Ankommen (Apps-Script je ID → public.mails, keine account_id an der Mail). Je Firma und
# Stufe ein Muster auf Betreff (+ Absender), Kontonummer/Betrag aus dem Text. Zuordnung: pending_payouts status=pending derselben user_id ×
# Firma — mit Kontonummer exakt (accounts.external_id bzw. Nummer im account_name), sonst nur, wenn GENAU EINE offene Anfrage passt. Schreibt
# nur liegt_bei („<Stufe> · <Datum> · <Betreff kurz>“, eine höhere Stufe überschreibt eine niedrigere, nie umgekehrt — dadurch idempotent, falls
# das Script dieselbe Mail nochmal schickt) und meldet „gesendet“ ⚪ an die Master-IDs (alarm_senden). Nichts wird abgehakt (status bleibt
# pending), Hand-Texte in liegt_bei bleiben als „vorher: …“ erhalten. Rein rechnend testbar: payout_mail_stufe, payout_pending_zuordnen;
# Dry-Run über echte Mails ohne Schreiben: payout_matcher_dryrun / GET /admin/payout-mail-dryrun. Wirft nie nach außen. ══
PAYOUT_STUFEN = {"angefragt": 1, "geprüft": 2, "gesendet": 3}
# Betrag im Text: „$1,710.98“, „$4500.00“, „$822.626“, „$786.5“ — erster Treffer nach dem Schlüsselwort, sonst erster $-Betrag
_PAYOUT_BETRAG_RE = re.compile(r"\$\s?([0-9][0-9,]*(?:\.[0-9]+)?)")
# Muster-Tabelle: (firma, stufe, Absender-Regex, Betreff-Regex, Konto-Regex auf Betreff+Text | None, Beispielbetreff)
# Kontonummern: Tradeify FTDFYSLX150393423058 („Account(s) Approved …“), Topstep EXPRESS-V2-679005-57119155 („Your payout for * EXPRESS-…*“),
# FundedNext 14192655 (im Betreff „… disbursed! - 14192655“). Apex/5ers/FundingPips nennen kein Konto → nur über „genau eine offene Anfrage“.
PAYOUT_MAIL_MUSTER = (
    # Tradeify — Betreff „Your payout request has been received“ → „🎉 Your payout has been approved“ → Rise „Payment Received: $X from Tradeify Holdings, Corp“
    ("tradeify", "angefragt", r"tradeify", r"payout request has been received", None, "Your payout request has been received"),
    ("tradeify", "geprüft", r"tradeify", r"payout has been approved", r"Account\(s\)\s+Approved\s*:?\s*((?:[A-Z]{4,}\d{6,})(?:\s*,\s*[A-Z]{4,}\d{6,})*)", "🎉 Your payout has been approved"),
    # Forge-Level-Up (675/1.350 $) und „first payout“ sind laut Finn (29.10.2026 01:10) echte Payouts — nur HTML, kein Konto/Betrag im Text;
    # ohne Anfrage in Prophos landen sie über die Betragsprüfung in der ohne_anfrage-Liste des Dry-Runs (nachtragen)
    ("tradeify", "geprüft", r"tradeify", r"Forge Level Up payout is approved", None, "Your Forge Level Up payout is approved"),
    ("tradeify", "geprüft", r"tradeify", r"first payout is confirmed", None, "🎉 Congratulations! Your first payout is confirmed"),
    ("tradeify", "gesendet", r"rise", r"Payment Received:.*from Tradeify", None, "Payment Received: $675.00 from Tradeify Holdings, Corp"),
    # Topstep — „Your payout is being processed 💰“ (Konto + Betrag) → „Your payout has been approved! 🎉“ (nur Betrag; „funds are on the way“)
    ("topstep", "angefragt", r"topstep", r"payout is being processed", r"payout for\s*\*?\s*([A-Z]+(?:-[A-Z0-9]+){2,})", "Your payout is being processed 💰"),
    ("topstep", "geprüft", r"topstep", r"payout has been approved", None, "Your payout has been approved! 🎉"),
    # Apex — nur „PA Payout Approved“ („$2500 approved on Oct 26, Funds within 3–4 business days“, kein Konto)
    ("apex", "geprüft", r"apex", r"PA Payout Approved", r"((?:PA-?)?APEX-[0-9]{5,}-[0-9]{1,3})", "PA Payout Approved"),
    # 5ers — „Your 5ers Payout Request Confirmation“ → „You got paid | reference id“ → Rise „Payment Received … from Five Percent Online Ltd“
    ("5ers", "angefragt", r"5ers", r"Payout Request Confirmation", None, "Your 5ers Payout Request Confirmation"),
    ("5ers", "gesendet", r"5ers", r"You got paid", None, "You got paid | Your payout reference id: xAYk2uGv"),
    ("5ers", "gesendet", r"rise", r"Payment Received:.*from Five Percent", None, "Payment Received: $1,157.23 from Five Percent Online Ltd"),
    # FundedNext — „Your Performance Reward Request OTP“ → „Performance Reward Request Accepted“ → „… Reward has been disbursed! - <Kontonr>“
    ("fundednext", "angefragt", r"fundednext", r"Performance Reward Request OTP", None, "Your Performance Reward Request OTP"),
    ("fundednext", "geprüft", r"fundednext", r"Performance Reward Request Accepted", None, "Performance Reward Request Accepted"),
    ("fundednext", "gesendet", r"fundednext", r"Performance Reward has been disbursed", r"disbursed!?\s*-\s*(\d{6,})", "Congratulations! Your Performance Reward has been disbursed! - 14192655"),
    # FundingPips — „Reward Requested“ → „Reward Processing Initiated“ (Betrag „Amount $822.626“); Geld-Mail gibt es nicht
    ("fundingpips", "angefragt", r"fundingpips", r"^\s*Reward Requested\s*$", None, "Reward Requested"),
    ("fundingpips", "geprüft", r"fundingpips", r"Reward Processing Initiated", None, "Reward Processing Initiated"),
)
# FTMO, Lucid, Blue Guardian: keine Payout-Mails (Befund S6 29.10.2026) — kein Muster.
_PAYOUT_MUSTER_RE = [(f, st, re.compile(von, re.I), re.compile(bet, re.I), re.compile(kon, re.I) if kon else None, bsp)
                     for f, st, von, bet, kon, bsp in PAYOUT_MAIL_MUSTER]


def payout_firma_key(name):
    """REIN RECHNEND: Firmenname aus pending_payouts.account_firm/Absender → Schlüssel der Muster-Tabelle oder None.
    „Tradeify CFD“ zählt als tradeify (gleicher Absender), „FundedNext Futures“ als fundednext, „The5%ers“ als 5ers."""
    s = re.sub(r"[^a-z0-9]", "", str(name or "").lower())
    if "tradeify" in s:
        return "tradeify"
    if "topstep" in s:
        return "topstep"
    if "apex" in s:
        return "apex"
    if "5ers" in s or "fivepercent" in s or "the5" in s:
        return "5ers"
    if "fundednext" in s or "fundingnext" in s:
        return "fundednext"
    if "fundingpips" in s:
        return "fundingpips"
    return None


def _payout_text_flach(mail):
    """Text einer Mail ohne Tags/Links/Schmuckzeichen, auf eine Zeile — Betreff zuerst (Kontonummer steht bei FundedNext nur dort)."""
    roh = str(mail.get("text") or "") or str(mail.get("snippet") or "")
    if not roh.strip() and mail.get("html"):
        roh = str(mail.get("html") or "")
    roh = re.sub(r"<[^>]*>|https?://\S+", " ", roh)
    return re.sub(r"[\s‌͏ ]+", " ", f"{mail.get('betreff') or ''} \n {roh}")[:20000]


def payout_mail_stufe(mail):
    """REIN RECHNEND (testbar): Mail-Zeile (von, betreff, text/snippet/html) → (firma, stufe, kontonr|None, betrag|None, konten) oder None,
    wenn es keine Payout-Mail ist. Erster passender Eintrag der Muster-Tabelle gewinnt (Betreff + Absender). konten = alle Nummern der Mail
    (Tradeify „Account(s) Approved A, B“ nennt mehrere, Prüfer 29.10.2026), kontonr = die erste."""
    von, betreff = str(mail.get("von") or ""), str(mail.get("betreff") or "")
    for firma, stufe, von_re, bet_re, kon_re, _bsp in _PAYOUT_MUSTER_RE:
        if not von_re.search(von) or not bet_re.search(betreff):
            continue
        flach = _payout_text_flach(mail)
        konten = []
        if kon_re:
            m = kon_re.search(flach)
            konten = [k for k in re.split(r"[\s,]+", m.group(1).strip()) if k] if m else []
        konto = konten[0] if konten else None
        betrag = None
        m = _PAYOUT_BETRAG_RE.search(flach)
        if m:
            try:
                betrag = round(float(m.group(1).replace(",", "")), 2)
            except ValueError:
                betrag = None
        return firma, stufe, konto, betrag, konten
    return None


def _payout_konto_norm(s):
    """Kennung vergleichbar machen: Apex „PA-APEX-685010-01“ → „PAAPEX6850100000001“, „APEX-641699-21“ → „APEX6416990000021“ (so legt Finn
    external_id an; Muster aus S6 59865726, 29.10.2026); sonst nur Groß + ohne Trennzeichen."""
    k = str(s or "").strip().upper()
    m = re.fullmatch(r"(PA-?)?APEX-?([0-9]{5,6})-([0-9]{1,3})", k)
    if m:
        return ("PAAPEX" if m.group(1) else "APEX") + m.group(2) + m.group(3).zfill(7)
    return re.sub(r"[^A-Z0-9]", "", k)


def _payout_betrag_plausibel(betrag, amount, currency=None, fx=None):
    """REIN RECHNEND: Mail-Betrag ($) passt ±15 % zum Anfrage-Betrag — brutto oder netto (Tradeify/Topstep zahlen 90 % des genehmigten Betrags
    aus), bei EUR-Anfragen zusätzlich über den Kurs (fx = EUR je USD, wie _wd_fx) — Finn trägt mal $, mal € ein (Prüfung 29.10.2026:
    Tradeify 4.500 $ → 4.040 „EUR“, Topstep 1.715 $ → 1.354 €). 15 % statt 10 % (Master 29.10.2026): 5ers zieht ~11 % Gebühr ab
    (602,79 $ Mail gegen 680 $ Anfrage); fremde Payouts liegen > 70 % daneben."""
    try:
        b, a = float(betrag), float(amount)
    except (TypeError, ValueError):
        return False
    if not (b > 0 and a > 0):
        return False
    werte = [b, b * 0.9]
    if str(currency or "EUR").upper() != "USD" and fx and 0.5 < float(fx) < 1.5:
        werte += [b * float(fx), b * 0.9 * float(fx)]
    return any(abs(x - a) <= 0.15 * a for x in werte)


def payout_pending_zuordnen(firma, konto, kandidaten, betrag=None, fx=None):
    """REIN RECHNEND (testbar): offene Anfragen [{id, account_firm, account_name, external_id, requested_at, amount}] derselben ID → (Treffer|None, grund).
    Mit Kontonummer: exakt gegen external_id oder enthalten im account_name (normiert); passen mehrere Anfragen desselben Kontos, gilt die
    jüngste (requested_at) — dieselbe Nummer taucht alle paar Wochen wieder auf. Ohne Nummer: GENAU EINE Anfrage der Firma, sonst die einzige,
    deren Betrag ±15 % zum Mail-Betrag passt (S3-Stresstest 29.10.2026: zwei Payouts derselben ID × Firma liegen oft nebeneinander)."""
    gleiche = [p for p in kandidaten if payout_firma_key(p.get("account_firm")) == firma]
    if not gleiche:
        return None, "keine offene Anfrage dieser Firma"
    if konto:
        kn = _payout_konto_norm(konto)
        exakt = [p for p in gleiche if kn and (_payout_konto_norm(p.get("external_id")) == kn or kn in _payout_konto_norm(p.get("account_name")))]
        if len(exakt) == 1:
            return exakt[0], "Kontonummer"
        if len(exakt) > 1:
            juengst = max(str(p.get("requested_at") or "") for p in exakt)
            neueste = [p for p in exakt if str(p.get("requested_at") or "") == juengst]
            if len(neueste) == 1:
                return neueste[0], f"Kontonummer, jüngste von {len(exakt)} Anfragen"
            return None, f"Kontonummer passt auf {len(exakt)} offene Anfragen vom selben Tag"
        # Nennt die Mail ein Konto, das zu keiner offenen Anfrage passt, ist es ein ANDERES Konto — nie auf „die einzige“ ausweichen
        # (Live-Simulation 29.10.2026: Mail für …033794 wäre sonst der Anfrage …060459 zugeordnet worden)
        return None, f"Kontonummer passt zu keiner der {len(gleiche)} offenen Anfragen"
    if len(gleiche) == 1:
        # Prüfer 29.10.2026: auch die einzige Anfrage nur, wenn der Betrag passt (±15 %) — sonst ist es ein Payout ohne Anfrage in Prophos
        if not betrag or _payout_betrag_plausibel(betrag, gleiche[0].get("amount"), gleiche[0].get("currency"), fx):
            return gleiche[0], "einzige offene Anfrage der Firma" + (" (Betrag passt)" if betrag else "")
        return None, f"keine passende Anfrage: Betrag {betrag} passt nicht zur einzigen offenen ({gleiche[0].get('amount')} {gleiche[0].get('currency') or ''})"
    if betrag:
        plausibel = [p for p in gleiche if _payout_betrag_plausibel(betrag, p.get("amount"), p.get("currency"), fx)]
        if len(plausibel) == 1:
            return plausibel[0], f"Betrag ±15 % (eine von {len(gleiche)} offenen Anfragen)"
        return None, f"{len(gleiche)} offene Anfragen der Firma, Mail nennt kein Konto, Betrag passt auf {len(plausibel)}"
    return None, f"{len(gleiche)} offene Anfragen der Firma, Mail nennt kein Konto"


def _payout_liegt_bei_stufe(txt):
    """Stufe aus einem liegt_bei-Text, den der Matcher geschrieben hat („geprüft · 28.10. 21:04 · …“) → Rang 0–3."""
    t = str(txt or "").strip().lower()
    for st, rang in PAYOUT_STUFEN.items():
        if t.startswith(st):
            return rang
    return 0


def _payout_ts(iso):
    """ISO-Zeit aus mail_zeile (isoformat) oder PostgREST („2026-10-28 20:25:23+00“, Bruchteile) → aware datetime (UTC), None bei Müll."""
    t = str(iso or "").strip().replace("Z", "+00:00")
    t = re.sub(r"([+-]\d{2})$", r"\1:00", t)
    t = re.sub(r"\.(\d{1,6})\d*", lambda m: "." + m.group(1).ljust(6, "0"), t)
    try:
        d = datetime.fromisoformat(t)
    except (TypeError, ValueError):
        return None
    return d if d.tzinfo else d.replace(tzinfo=timezone.utc)


def _payout_datum_txt(iso):
    try:
        d = _payout_ts(iso)
        if d is None:
            return "?"
        try:
            from zoneinfo import ZoneInfo
            d = d.astimezone(ZoneInfo("Europe/Berlin"))
        except Exception:
            pass
        return d.strftime("%d.%m. %H:%M")
    except (TypeError, ValueError):
        return "?"


def payout_liegt_bei_text(stufe, datum_iso, betreff, alt):
    """REIN RECHNEND: neuer liegt_bei-Text; ein Hand-Text (nicht vom Matcher) bleibt als „vorher: …“ erhalten."""
    kurz = re.sub(r"\s+", " ", str(betreff or "")).strip()[:60]
    neu = f"{stufe} · {_payout_datum_txt(datum_iso)} · {kurz}"
    alt = str(alt or "").strip()
    if " · vorher: " in alt:                                   # Hand-Text aus einer früheren Stufe weiter mitführen (Prüfung 29.10.2026)
        neu += " · vorher: " + alt.split(" · vorher: ", 1)[1][:60]
    elif alt and not _payout_liegt_bei_stufe(alt) and not alt.lower().startswith("unklar"):
        neu += f" · vorher: {alt[:60]}"
    return neu[:240]


def _payout_mail_passt_zeitlich(mail_datum, requested_at):
    """Mail gehört zeitlich zur Anfrage: frühestens 1 Tag vor requested_at (Datum ohne Uhrzeit, Berlin vs. UTC) und höchstens 14 Tage danach
    (S3-Stresstest 29.10.2026; Tradeify zahlt in 1–2 Tagen, 5ers bis 4, Apex 3–10 Werktage; länger offene Anfragen bleiben Handarbeit)."""
    md = _payout_ts(mail_datum)
    try:
        ra = datetime.strptime(str(requested_at)[:10], "%Y-%m-%d").replace(tzinfo=timezone.utc)
    except (TypeError, ValueError):
        return False
    if md is None:
        return False
    return ra - timedelta(days=1) <= md <= ra + timedelta(days=14)


PAYOUT_RECEIVED_TAGE = 3   # schon abgehakte Anfragen bleiben so lange Kandidatin (nur liegt_bei, kein Alarm) — S3-Stresstest 29.10.2026: FundedNext-Mails kommen am Folgetag


def _payout_kandidaten(uid, nur_pending=True):
    """Anfragen einer ID (+ external_id des Kontos) → Liste für payout_pending_zuordnen. nur_pending: offene plus die in den letzten
    PAYOUT_RECEIVED_TAGE (+2 Puffer) abgehakten (status received) — die Abgleich-Funktion filtert je Mail-Datum nach."""
    params = {"select": "id,user_id,account_id,account_name,account_firm,amount,currency,liegt_bei,requested_at,received_at,status", "user_id": f"eq.{uid}"}
    if nur_pending:
        seit = (datetime.now(timezone.utc) - timedelta(days=PAYOUT_RECEIVED_TAGE + 2)).strftime("%Y-%m-%d")
        params["or"] = f"(status.eq.pending,and(status.eq.received,received_at.gte.{seit}))"
    rows = sb_select("pending_payouts", params) or []
    ids = sorted({str(r.get("account_id")) for r in rows if r.get("account_id")})
    ext = {}
    for i in range(0, len(ids), 80):
        for a in sb_select("accounts", {"select": "id,external_id", "id": f"in.({','.join(ids[i:i + 80])})"}) or []:
            ext[str(a.get("id"))] = a.get("external_id") or ""
    for r in rows:
        r["external_id"] = ext.get(str(r.get("account_id")), "")
    return rows


def _payout_received_frisch(p, mail_datum):
    """Abgehakte Anfrage zählt nur, wenn sie höchstens PAYOUT_RECEIVED_TAGE vor der Mail abgehakt wurde."""
    md = _payout_ts(mail_datum)
    try:
        ra = datetime.strptime(str(p.get("received_at"))[:10], "%Y-%m-%d").replace(tzinfo=timezone.utc)
    except (TypeError, ValueError):
        return False
    return md is not None and md - timedelta(days=PAYOUT_RECEIVED_TAGE) <= ra


def payout_mail_verarbeiten(zeilen):
    """Nach dem Insert in /mail/eingang: jede Payout-Mail des Stapels einer offenen Anfrage zuordnen und liegt_bei setzen; „gesendet“ meldet
    ⚪ an die Master-IDs. Wirft nie; Ergebnis nur im Log. Idempotent: gleiche/niedrigere Stufe schreibt nichts (auch kein zweiter Alarm)."""
    try:
        treffer = [(z, payout_mail_stufe(z)) for z in (zeilen or []) if z]
        treffer = [(z, t) for z, t in treffer if t]
        if not treffer:
            return
        je_uid, fx = {}, None
        try:
            fx = _wd_fx()
        except Exception:
            fx = None
        for z, (firma, stufe, konto0, betrag, konten) in sorted(treffer, key=lambda x: PAYOUT_STUFEN[x[1][1]]):   # niedrige Stufe zuerst → Reihenfolge wie der Posteingang
          for konto in (konten or [None]):   # Tradeify nennt in einer Mail mehrere Konten → je Konto eine Zuordnung
            uid = str(z.get("user_id") or "")
            if uid not in je_uid:
                je_uid[uid] = _payout_kandidaten(uid, nur_pending=True)
            zeitlich = [p for p in je_uid[uid] if _payout_mail_passt_zeitlich(z.get("datum"), p.get("requested_at"))]
            kand = [p for p in zeitlich if p.get("status") == "pending"]
            p, grund = payout_pending_zuordnen(firma, konto, kand, betrag if len(konten) <= 1 else None, fx)
            if not p:
                # Zweiter Blick (S3 29.10.2026): kürzlich abgehakte Anfragen — nur Stand nachtragen, keine Meldung, keine „unklar“-Notiz
                kand_r = [p for p in zeitlich if p.get("status") == "received" and _payout_received_frisch(p, z.get("datum"))]
                if kand_r:
                    p2, grund2 = payout_pending_zuordnen(firma, konto, kand + kand_r, betrag if len(konten) <= 1 else None, fx)
                    if p2 and p2.get("status") == "received":
                        p, grund = p2, grund2 + " (schon abgehakt — nur Stand)"
            # Rise meldet JEDE Zahlung der Firma (auch Forge-Programm, 675 $ an viele IDs): ohne Kontonummer gilt „gesendet“ nur für eine Anfrage,
            # die schon „geprüft“ ist — sonst Notiz statt Stufe (29.10.2026, Dry-Run: Forge-Zahlungen am 16.10. hätten 4 Anfragen „gesendet“ gesetzt)
            if p and stufe == "gesendet" and not konto and re.search(r"rise", str(z.get("von") or ""), re.I) and _payout_liegt_bei_stufe(p.get("liegt_bei")) < PAYOUT_STUFEN["geprüft"]:
                p, grund = None, "Rise-Zahlung ohne Kontonummer, Anfrage noch nicht „geprüft“"
            if not p:
                # Mehrdeutig: an den Kandidaten ohne Stand eine Notiz, damit Finn im Admin sieht, dass eine Mail da ist — nie eine Stufe überschreiben;
                # nennt die Mail ein fremdes Konto, gehört sie keiner der Anfragen → keine Notiz (Prüfung 29.10.2026)
                offen = [] if grund.startswith("Kontonummer passt zu keiner") else [q for q in kand if payout_firma_key(q.get("account_firm")) == firma and not str(q.get("liegt_bei") or "").strip()]
                for q in offen:
                    notiz = f"unklar · {_payout_datum_txt(z.get('datum'))} · Mail ohne eindeutige Zuordnung: {str(z.get('betreff') or '')[:70]}"[:240]
                    try:
                        sb_update("pending_payouts", {"id": f"eq.{q['id']}", "status": "eq.pending"}, {"liegt_bei": notiz, "updated_at": datetime.now(timezone.utc).isoformat()})
                        q["liegt_bei"] = notiz
                    except Exception as e:
                        print(f"[payout-mail] ⚠️ Notiz {q.get('id')}: {type(e).__name__}: {e}", flush=True)
                print(f"[payout-mail] {firma} {stufe} {konto or ''} {betrag or ''} — keine Zuordnung ({grund}): {str(z.get('betreff') or '')[:80]}", flush=True)
                continue
            if _payout_liegt_bei_stufe(p.get("liegt_bei")) >= PAYOUT_STUFEN[stufe]:
                continue   # schon so weit (oder weiter) — nichts schreiben, kein zweiter Alarm
            neu = payout_liegt_bei_text(stufe, z.get("datum"), z.get("betreff"), p.get("liegt_bei"))
            try:
                ok = sb_update("pending_payouts", {"id": f"eq.{p['id']}", "status": f"eq.{p.get('status') or 'pending'}"}, {"liegt_bei": neu, "updated_at": datetime.now(timezone.utc).isoformat()})
            except Exception as e:
                print(f"[payout-mail] ⚠️ liegt_bei {p.get('id')}: {type(e).__name__}: {e}", flush=True)
                continue
            if not ok:
                continue   # Status hat sich inzwischen geändert — nichts
            p["liegt_bei"] = neu
            print(f"[payout-mail] {firma} {stufe} → {p.get('account_firm')} {p.get('account_name')} ({grund})", flush=True)
            if stufe == "gesendet" and p.get("status") == "pending" and not _alarm_fremd_verwaltet(uid):
                namen, _aus = _ap_namen()
                wer = namen.get(uid, uid[:8])
                konto_txt = konto or str(p.get("account_name") or "")[:40]
                betrag_txt = f" {betrag:,.2f} $".replace(",", "X").replace(".", ",").replace("X", ".") if betrag else ""
                alarm_senden(3, "payout_gesendet", f"Payout {p.get('account_firm') or firma}{betrag_txt} gesendet",
                             f"{wer}: Payout {p.get('account_firm') or firma} {konto_txt}{betrag_txt} gesendet — Geld sollte da sein. Im Admin unter Payouts abhaken.",
                             uid=uid, schluessel=f"payout|{p.get('id')}|gesendet", daten={"pending_id": str(p.get("id")), "firma": firma, "betrag": betrag, "konto": konto})
    except Exception as e:
        print(f"[payout-mail] ⚠️ verarbeiten: {type(e).__name__}: {e}", flush=True)


def payout_matcher_dryrun(tage=30):
    """Nur rechnen, nichts schreiben: alle Mails der letzten `tage` Tage von Payout-Absendern durch die Muster, Zuordnung gegen Anfragen ALLER
    Stände (pending/received) derselben ID im Zeitfenster der Anfrage (so sieht man, was historisch getroffen hätte). → {tage, mails, payout_mails,
    eindeutig, unklar, je_firma, ohne_anfrage: [Payout-Mails ohne Anfrage in Prophos — zum Nachtragen], treffer: [{…}]}."""
    seit = (datetime.now(timezone.utc) - timedelta(days=max(1, int(tage or 30)))).isoformat()
    mails = _sb_all("mails", {"select": "id,user_id,von,betreff,datum,snippet,text", "datum": f"gte.{seit}",
                              "or": "(von.ilike.*tradeify*,von.ilike.*topstep*,von.ilike.*apex*,von.ilike.*5ers*,von.ilike.*fundednext*,von.ilike.*fundingpips*,von.ilike.*riseworks*)",
                              "order": "datum.asc,id.asc"})   # fester Tiebreaker fürs Blättern in _sb_all
    je_uid, out, je_firma, ohne_anfrage = {}, [], {}, []
    try:
        fx = _wd_fx()
    except Exception:
        fx = None
    n_payout = n_ok = n_unklar = 0
    for z in mails:
        t = payout_mail_stufe(z)
        if not t:
            continue
        firma, stufe, konto0, betrag, konten = t
        n_payout += 1
        uid = str(z.get("user_id") or "")
        if uid not in je_uid:
            je_uid[uid] = _payout_kandidaten(uid, nur_pending=False)
        kand = [p for p in je_uid[uid] if _payout_mail_passt_zeitlich(z.get("datum"), p.get("requested_at"))]
        p, grund, konto = None, "", konto0
        for konto in (konten or [None]):   # mehrere Konten in einer Mail: erster Treffer zählt für die Statistik
            p, grund = payout_pending_zuordnen(firma, konto, kand, betrag if len(konten) <= 1 else None, fx)
            if p:
                break
        if p:
            n_ok += 1
        else:
            n_unklar += 1
            if grund.startswith(("keine offene Anfrage", "keine passende Anfrage")):   # Payout-Mail ohne Anfrage in Prophos → zum Nachtragen (kein Alarm, kein Write)
                ohne_anfrage.append({"firma": firma, "user_id": uid, "stufe": stufe, "betrag": betrag, "datum": z.get("datum"), "betreff": str(z.get("betreff") or "")[:90]})
        f = je_firma.setdefault(firma, {"mails": 0, "eindeutig": 0, "unklar": 0})
        f["mails"] += 1
        f["eindeutig" if p else "unklar"] += 1
        out.append({"mail_id": str(z.get("id") or ""), "datum": z.get("datum"), "user_id": uid, "firma": firma, "stufe": stufe, "konto": konto,
                    "betrag": betrag, "betreff": str(z.get("betreff") or "")[:90], "treffer": str(p.get("id")) if p else None,
                    "treffer_konto": (f"{p.get('account_firm')} {p.get('account_name')}"[:80] if p else None),
                    "treffer_status": (p.get("status") if p else None), "grund": grund,
                    "liegt_bei_neu": (payout_liegt_bei_text(stufe, z.get("datum"), z.get("betreff"), p.get("liegt_bei")) if p else None)})
    return {"tage": int(tage or 30), "mails": len(mails), "payout_mails": n_payout, "eindeutig": n_ok, "unklar": n_unklar, "je_firma": je_firma,
            "ohne_anfrage": ohne_anfrage, "treffer": out}


@app.route("/admin/payout-mail-dryrun", methods=["GET", "OPTIONS"])
def admin_payout_mail_dryrun():
    """GET ?tage=30 → payout_matcher_dryrun (nur rechnen, nichts schreiben). Gate wie die Rechnungen (_admin_auth, ADMIN_EMAILS):
    die Treffer nennen Betreffzeilen und Konten aller IDs."""
    if request.method == "OPTIONS":
        return "", 200
    _, err = _admin_auth()
    if err:
        return err
    try:
        tage = max(1, min(60, int(request.args.get("tage") or 30)))   # 60 Tage ≈ 17 MB Mail-Text — darüber reißt der gunicorn-Timeout
    except ValueError:
        tage = 30
    try:
        return jsonify(payout_matcher_dryrun(tage))
    except Exception as e:
        print(f"[payout-mail] ⚠️ dryrun: {type(e).__name__}: {e}", flush=True)
        return jsonify({"error": f"Dry-Run fehlgeschlagen ({type(e).__name__}: {str(e)[:120]})"}), 502


# ══ ADMIN → MAIL (21.10.2026, Finn 05:15 Dubai: „Unter Admin noch einmal Gmail hinzufügen, wo ich alle Gmail-Accounts jeder einzelnen ID im
# Überblick habe — ganz normales, simples Overview, nach jeder ID filtern oder alles, damit ich einmal am Tag von dort alle Gmails durchgehen
# kann"). Quelle ist die vorhandene: public.mails + mail_schluessel (Mail-Reiter oben, Script je ID → /mail/eingang) — keine neue Anbindung.
# Das Frontend liest mails per RLS nur für die eigene ID, deshalb hier ein Admin-Weg mit Service-Key. Gate: _admin_auth (ADMIN_EMAILS, wie die
# Rechnungen) — strenger als die Übersicht, weil Mails Login-Codes und Auszahlungs-Bestätigungen enthalten; ein normaler ID-Login sieht hier
# nie fremde Mails. IDs wie die Standard-Sicht Hermann Technologies (_wd_personen: ADMIN_EXCLUDE + Gruppen mit Verwalter raus — Emins Gruppe
# bleibt draußen). Nur lesen und „gelesen" setzen; kein Takt, das Frontend lädt beim Öffnen des Reiters und auf ↻. ══
ADMIN_MAIL_LIMIT = 200
ADMIN_MAIL_LIMIT_MAX = 500
ADMIN_MAIL_UID_RE = re.compile(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}")
ADMIN_MAIL_LISTE_FELDER = "id,user_id,von,betreff,datum,snippet,gelesen,anhaenge"
ADMIN_MAIL_VOLL_FELDER = "id,user_id,von,an,betreff,datum,text,html,anhaenge,gelesen,labels"


def admin_mail_params(args):
    """REIN RECHNEND (testbar): Query → (user_id | None, limit, vor | None) oder raise ValueError(Text). user_id nur als UUID, limit 1…500
    (Standard 200), vor = ISO-Zeitpunkt zum Weiterblättern (nur Mails mit datum davor)."""
    a = args or {}
    uid = str(a.get("user_id") or "").strip().lower()
    if uid and not ADMIN_MAIL_UID_RE.fullmatch(uid):
        raise ValueError("user_id ungültig")
    try:
        limit = int(str(a.get("limit") or ADMIN_MAIL_LIMIT).strip())
    except ValueError:
        raise ValueError("limit ungültig")
    limit = max(1, min(ADMIN_MAIL_LIMIT_MAX, limit))
    vor = str(a.get("vor") or "").strip()
    if vor:
        try:
            d = datetime.fromisoformat(vor.replace("Z", "+00:00"))
        except ValueError:
            raise ValueError("vor ungültig")
        vor = (d if d.tzinfo else d.replace(tzinfo=timezone.utc)).astimezone(timezone.utc).isoformat()
    return uid or None, limit, vor or None


def admin_mail_zaehler(content_range):
    """REIN RECHNEND (testbar): PostgREST Content-Range („0-24/808", „*/0") → Gesamtzahl, sonst None."""
    m = re.search(r"/(\d+)\s*$", str(content_range or ""))
    return int(m.group(1)) if m else None


def admin_mail_ids(disp, excluded, schluessel, ungelesen):
    """REIN RECHNEND (testbar): Chip-Liste → [{user_id, name, verbunden, zuletzt_at, zuletzt_mail_at, ungelesen}], sichtbare IDs = disp ohne
    excluded. verbunden = das Script hat sich mit dem aktuellen Schlüssel gemeldet (zuletzt_at, wie der Mail-Reiter). Reihenfolge: verbundene
    zuerst, dann nach Name. ungelesen nur für verbundene (None = nicht zählbar)."""
    ex = {str(x) for x in (excluded or ())}
    sk = {str(r.get("user_id")): r for r in (schluessel or ()) if isinstance(r, dict) and r.get("user_id")}
    out = []
    for uid, name in (disp or {}).items():
        uid = str(uid)
        if uid in ex:
            continue
        k = sk.get(uid) or {}
        verb = bool(k.get("zuletzt_at"))
        out.append({"user_id": uid, "name": str(name or uid[:8]), "verbunden": verb, "zuletzt_at": k.get("zuletzt_at"),
                    "zuletzt_mail_at": k.get("zuletzt_mail_at"), "ungelesen": (ungelesen or {}).get(uid) if verb else None})
    out.sort(key=lambda x: (not x["verbunden"], x["name"].lower()))
    return out


def _admin_mail_sicht():
    """(disp, sichtbare user_ids) der Standard-Sicht Hermann Technologies — wirft bei nicht lesbarer Auth-/Gruppen-Liste (Aufrufer 502)."""
    disp, excluded = _wd_personen()
    return disp, {u for u in disp if u not in excluded}


def _admin_mail_ungelesen(uid):
    """Ungelesen-Zahl einer ID (HEAD + count=exact, keine Zeilen) — None, wenn nicht lesbar."""
    try:
        r = _sb_anfrage("HEAD", f"{SUPABASE_URL}/rest/v1/mails", params={"select": "id", "user_id": f"eq.{uid}", "gelesen": "eq.false"},
                        headers=_sb_headers("count=exact"), timeout=(5, 20))
        _sb_pruefen(r)
        return admin_mail_zaehler(r.headers.get("Content-Range"))
    except Exception:
        return None


# MAIL-LESER (21.10.2026, Finn ~04:00 Dubai im Reiter Admin → Mail, Build .1670: „Ich bin ja Finn + Admin … Kann ich alle Mails nicht
# sehen?" — Liste leer, oben „✗ Nur für Admins"). Ursache: das Gate war allein _admin_auth (Railway-Variable ADMIN_EMAILS); Finns Tages-
# Login „Finn + Pascal" steht dort nicht → jedes GET /admin/mail 403 (Railway-HTTP-Logs ab 20.10. 21:49 UTC), obwohl 3.833 Mails von 7 IDs
# in public.mails liegen. Ihn in ADMIN_EMAILS aufzunehmen hieße zugleich Rechnungen, Ausgleichen, Bot-Schalter — und in der Liq-Ansicht
# kippte „Kunde" für diese ID (lq_kunde_flags, keine liq_personen-Zeile). Deshalb eine eigene, enge Freigabe NUR fürs Mail-Lesen: Tabelle
# admin_mail_leser (sql/2026-10-21_admin_mail_leser.sql, nur Service-Key, keine E-Mail im Repo wie admin_zugang). Zusätzlich darf der
# Login im Admin nicht eingeschränkt sein (admin_sicht_lesen → None) — ein Verwalter oder Gruppen-Mitglied sieht hier nie Mails.
_admin_mail_leser_cache = {"bis": 0.0, "uids": None}


def admin_mail_leser_uids():
    """user_ids aus admin_mail_leser (frozenset), 60 s gemerkt. Tabelle fehlt (SQL nicht eingespielt) → leer. Andere Lesefehler werfen
    (Aufrufer 502) — nie still freigeben."""
    jetzt = time.time()
    with _kurz_cache_lock:
        if _admin_mail_leser_cache["uids"] is not None and _admin_mail_leser_cache["bis"] > jetzt:
            return _admin_mail_leser_cache["uids"]
    try:
        rows = sb_select("admin_mail_leser", {"select": "user_id"}) or []
    except requests.exceptions.HTTPError as e:
        if not admin_gruppen_tabelle_fehlt(e):
            raise
        rows = []
    uids = frozenset(str(z.get("user_id")) for z in rows if isinstance(z, dict) and z.get("user_id"))
    with _kurz_cache_lock:
        _admin_mail_leser_cache.update(bis=jetzt + AUTH_LISTE_CACHE_S, uids=uids)
    return uids


def _admin_mail_auth():
    """Gate von /admin/mail*: ADMIN_EMAILS (_admin_auth) ODER eingetragener Mail-Leser, der im Admin nicht eingeschränkt ist.
    → None (frei) oder (response, status)."""
    _, err = _admin_auth()
    if err is None or err[1] != 403:
        return err
    uid = str(request.environ.get("prophos.admin_uid") or "")   # setzt _admin_auth vor dem 403
    try:
        frei = bool(uid) and uid in admin_mail_leser_uids() and admin_sicht_lesen(uid)[0] is None
    except Exception:
        return jsonify({"ok": False, "msg": "Anmeldung nicht prüfbar"}), 502
    if not frei:
        return jsonify({"ok": False, "msg": "Nur für Admins — dieser Login ist nicht für Admin → Mail freigegeben"}), 403
    return None


@app.route("/admin/mail", methods=["GET", "PATCH", "OPTIONS"])
def admin_mail():
    """GET /admin/mail[?user_id=&limit=&vor=] → {ok, ids:[…], mails:[{id, user_id, von, betreff, datum, snippet, gelesen, anhaenge}], mehr}
    (neueste oben, alle sichtbaren IDs oder genau eine). PATCH {id} → eine Mail gelesen; PATCH {user_id, alle: true} → alle Mails dieser ID
    gelesen. → {ok, n}. Nur ADMIN_EMAILS oder Mail-Leser (_admin_mail_auth)."""
    if request.method == "OPTIONS":
        return "", 200
    err = _admin_mail_auth()
    if err:
        return err
    try:
        disp, sicht = _admin_mail_sicht()
    except Exception as e:
        return jsonify({"ok": False, "msg": f"IDs nicht lesbar: {str(e)[:120]}"}), 502
    if request.method == "PATCH":
        b = request.get_json(silent=True) or {}
        try:
            if b.get("id") is not None:
                mid = int(b.get("id"))
                rows = sb_select("mails", {"select": "id,user_id", "id": f"eq.{mid}", "limit": "1"}) or []
                if not rows or str(rows[0].get("user_id")) not in sicht:
                    return jsonify({"ok": False, "msg": "Mail nicht gefunden"}), 404
                n = len(sb_update("mails", {"id": f"eq.{mid}", "gelesen": "eq.false"}, {"gelesen": True}) or [])
                return jsonify({"ok": True, "n": n})
            uid = str(b.get("user_id") or "").strip().lower()
            if b.get("alle") is True and ADMIN_MAIL_UID_RE.fullmatch(uid) and uid in sicht:
                r = _sb_anfrage("PATCH", f"{SUPABASE_URL}/rest/v1/mails", params={"user_id": f"eq.{uid}", "gelesen": "eq.false"},
                                json={"gelesen": True}, headers=_sb_headers("return=minimal,count=exact"), timeout=(5, 60))
                _sb_pruefen(r)
                return jsonify({"ok": True, "n": admin_mail_zaehler(r.headers.get("Content-Range")) or 0})
        except (TypeError, ValueError):
            return jsonify({"ok": False, "msg": "id ungültig"}), 400
        except Exception as e:
            return jsonify({"ok": False, "msg": f"Speichern fehlgeschlagen: {str(e)[:120]}"}), 503
        return jsonify({"ok": False, "msg": "id oder {user_id, alle: true} nötig"}), 400
    try:
        uid, limit, vor = admin_mail_params(request.args)
    except ValueError as e:
        return jsonify({"ok": False, "msg": str(e)}), 400
    if uid and uid not in sicht:
        return jsonify({"ok": False, "msg": "ID nicht in dieser Sicht"}), 404
    try:
        schluessel = sb_select("mail_schluessel", {"select": "user_id,zuletzt_at,zuletzt_mail_at"}) or []
        verb = sorted(u for u in sicht if any(str(k.get("user_id")) == u and k.get("zuletzt_at") for k in schluessel))
        ungelesen = {}
        if verb:
            with concurrent.futures.ThreadPoolExecutor(max_workers=min(8, len(verb))) as pool:
                for u, n in zip(verb, pool.map(_admin_mail_ungelesen, verb)):
                    ungelesen[u] = n
        ziel = [uid] if uid else sorted(sicht)
        mails = []
        if ziel:
            p = {"select": ADMIN_MAIL_LISTE_FELDER, "user_id": f"in.({','.join(ziel)})", "order": "datum.desc.nullslast,id.desc",
                 "limit": str(limit + 1)}
            if vor:
                p["datum"] = f"lt.{vor}"
            mails = sb_select("mails", p) or []
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Mails nicht lesbar: {str(e)[:120]}"}), 503
    return jsonify({"ok": True, "ids": admin_mail_ids(disp, set(disp) - sicht, schluessel, ungelesen), "mails": mails[:limit],
                    "mehr": len(mails) > limit})


KONTO_MAIL_BETREFF_RE = re.compile(r"[A-Za-z0-9 .:'’!?\-]{3,80}")   # Betreff-Suchwörter aus dem Frontend — ohne Komma/Klammern (PostgREST-or-Syntax, Prüfer 29.10.2026)
KONTO_MAIL_TEXT_MAX = 3000


# HT-PAYOUTS ALS CSV (29.10.2026, Finn: „Einnahmen = alle HT-Payouts aus Prophos“ für das Google Sheet „HT Buchhaltung 2026“, das die Liste per
# IMPORTDATA selbst lädt — ohne Teilen, ohne Dienstkonto). Schutz: Token aus der Railway-Variable HT_PAYOUTS_CSV_TOKEN (fehlt sie oder ist sie
# kürzer als HT_PAYOUTS_CSV_TOKEN_MIN → immer 404, nie offen), Vergleich mit hmac.compare_digest, falscher/fehlender Token → 404 (die Route
# gibt sich nicht zu erkennen). Inhalt: nur transactions kind=payout der Gruppe Hermann Technologies — ausgeblendet wie in Admin → Payouts
# „Payouts erhalten“: ADMIN_EXCLUDE und alle IDs von Gruppen MIT Verwalter (id_gruppen, nicht hart codiert). Spalten nur Datum · Betrag ·
# Währung · ID · Zweck · Transaktions-ID, keine Logins/Mails (ID-Name nur aus user_metadata.name, sonst die ersten 8 Zeichen der user_id).
# Betrag mit Dezimalkomma, ohne Tausenderpunkt — liest Google in de- und en-Tabellen gleich (das Sheet rechnet Text und Zahl). Der Token
# wird nie geloggt; Fehler nur mit Typ. Prüfer 29.10.2026: Textfelder kommen von den Kunden (Kontoname, Firma, Name) — beginnt eins mit
# = + - @ Tab CR, kommt ein ' davor (sonst liefe z. B. „=IMPORTXML(…)“ im Sheet als Formel); nur Payouts ab HT_PAYOUTS_AB (Finns Zeitraum);
# ohne lesbare Verwalter-Gruppe (id_gruppen fehlt/leer) → 502, nie die Emin-Gruppe ungefiltert.
HT_PAYOUTS_CSV_TOKEN_MIN = 32
HT_PAYOUTS_AB = "2026-05-30"


def ht_payouts_token_ok(ist, soll):
    """REIN RECHNEND: True nur bei gesetztem, ausreichend langem Soll-Token und exakt gleichem Ist-Token (zeitkonstant verglichen)."""
    soll = str(soll or "").strip()
    if len(soll) < HT_PAYOUTS_CSV_TOKEN_MIN:
        return False
    return hmac.compare_digest(str(ist or "").encode("utf-8"), soll.encode("utf-8"))


def ht_payouts_csv_sicher(s):
    """REIN RECHNEND: Text für eine CSV-Zelle, die ein Tabellenprogramm nie als Formel liest (führendes = + - @ Tab CR → ' davor)."""
    s = str(s or "")
    return "'" + s if s[:1] in ("=", "+", "-", "@", "\t", "\r") else s


def ht_payouts_ausblenden(users, exclude_mails, gruppen_daten):
    """REIN RECHNEND: (disp, aus) — disp = user_id → Anzeigename (nur user_metadata.name, sonst user_id[:8], nie die Mail), aus = ADMIN_EXCLUDE
    + alle IDs der Gruppen MIT Verwalter (Emin-Gruppe …). Wirft bei leerer Nutzerliste: ohne Auth-API ist nicht trennbar, was HT ist."""
    if not users:
        raise RuntimeError("Nutzerliste leer — HT nicht sicher trennbar")
    verwalter = _admin_verwalter_gruppen_ids(gruppen_daten)
    if not verwalter:
        raise RuntimeError("keine Gruppe mit Verwalter lesbar — HT nicht sicher trennbar")
    disp, aus = {}, set()
    for u in users:
        uid = str(u.get("id") or "")
        if not uid:
            continue
        name = str((u.get("user_metadata") or {}).get("name") or "").strip()
        disp[uid] = name or uid[:8]
        if str(u.get("email") or "").strip().lower() in exclude_mails:
            aus.add(uid)
    return disp, aus | verwalter


def ht_payouts_csv(txs, disp, aus):
    """REIN RECHNEND: CSV-Text (Kopf + Zeilen, nach Datum) aus transactions kind=payout; Zeilen ausgeblendeter IDs und vor HT_PAYOUTS_AB
    fallen raus, Textfelder über ht_payouts_csv_sicher."""
    import csv as _csv
    import io as _io
    zeilen = []
    for t in txs or ():
        uid = str(t.get("user_id") or "")
        datum = str(t.get("occurred_at") or "")[:10]
        if not uid or uid in aus or datum < HT_PAYOUTS_AB:
            continue
        try:
            betrag = abs(float(t.get("amount") or 0))
        except (TypeError, ValueError):
            continue
        zweck = " · ".join(x for x in (str(t.get("account_firm") or "").strip(), str(t.get("account_name") or "").strip()) if x)
        zeilen.append([datum, f"{betrag:.2f}".replace(".", ","), ht_payouts_csv_sicher(str(t.get("currency") or "EUR").upper()),
                       ht_payouts_csv_sicher(disp.get(uid) or uid[:8]), ht_payouts_csv_sicher(zweck), ht_payouts_csv_sicher(t.get("id"))])
    zeilen.sort(key=lambda z: (z[0], z[5]))
    buf = _io.StringIO()
    w = _csv.writer(buf, lineterminator="\n")
    w.writerow(["Datum", "Betrag", "Währung", "ID", "Zweck", "Transaktions-ID"])
    w.writerows(zeilen)
    return buf.getvalue()


@app.route("/ht/payouts.csv", methods=["GET"])
def ht_payouts_csv_route():
    """GET /ht/payouts.csv?token=… → text/csv der HT-Payouts (siehe Block oben). 404 ohne gültigen Token, 502 bei Lesefehler."""
    if not ht_payouts_token_ok(request.args.get("token"), os.environ.get("HT_PAYOUTS_CSV_TOKEN")):
        return Response("Not Found", status=404, mimetype="text/plain")
    try:
        users = (_auth_liste_anfrage().json() or {}).get("users", [])
        disp, aus = ht_payouts_ausblenden(users, ADMIN_EXCLUDE_EMAILS, admin_gruppen_daten())
        txs = _sb_all("transactions", {"select": "id,user_id,account_name,account_firm,amount,currency,occurred_at", "kind": "eq.payout"}) or []
        text = ht_payouts_csv(txs, disp, aus)
    except Exception as e:
        print(f"[ht-payouts-csv] ⚠️ nicht lesbar ({type(e).__name__})", flush=True)   # bewusst ohne URL/Token
        return Response("Fehler", status=502, mimetype="text/plain")
    r = Response(text, mimetype="text/csv")
    r.headers["Content-Type"] = "text/csv; charset=utf-8"
    r.headers["Cache-Control"] = "no-store"
    return r


# ADMIN → KONTO FÜR EINE ANDERE ID ANLEGEN (29.10.2026, Finn 07:15: „Ja — im Admin soll man alle bestätigen können.“). Admin → Alle Accounts zeigt
# TV-Konten aller IDs als „zu bestätigen“; bis hierhin konnte nur die eingeloggte ID ihre eigenen anlegen (accounts schreibt der Browser-Client per
# RLS nur für sich). POST /admin/konto-anlegen legt das Konto mit dem Service-Key für den BESITZER der Zeile an — die eigene ID geht weiter über
# saveAccount. Gate wie Kapital/Admin → Mail: uneingeschränkt nur ADMIN_EMAILS oder admin_mail_leser (Finn + Pascal, Pascal); Verwalter (Emin) nur
# mit ?ansicht=admin und nur für IDs seiner Gruppe; jeder andere Login → 403. Body = Whitelist (admin_konto_zeile): genau die Felder, die das
# Account-Modal beim Anlegen schreibt — nie Zugangsdaten, nie MetaApi, nie live, wd_farm immer aus. Doppel-Schutz wie kontoDoppelFinden im
# Frontend (External ID normiert inkl. Apex-Form, archivierte zählen mit, Kontoname enthält die Nummer ab 8 Zeichen) → 409 mit Kontoname.
# Danach tv_konten.angelegt_account_id (Tabelle fehlt → nur das Markieren entfällt) und wie saveAccount die Kauf-Transaktion bei Kaufpreis.
ADMIN_KONTO_TYPEN = frozenset({"challenge", "phase1", "phase2", "funded", "funded_cfd", "winning_days"})   # live nie über diesen Weg
ADMIN_KONTO_ZIELE = frozenset({"trading_days", "winning_days"})
ADMIN_KONTO_APEX_RE = re.compile(r"^(PA-)?APEX-(\d+)-(\d+)$")


def admin_konto_ext_norm(v):
    """REIN RECHNEND: External ID normiert wie extIdNorm im Frontend — Großbuchstaben, Apex PA-APEX-685010-01 → PAAPEX6850100000001,
    alles außer A–Z/0–9 raus."""
    t = str(v or "").strip().upper()
    m = ADMIN_KONTO_APEX_RE.match(t)
    if m:
        t = f"{'PAAPEX' if m.group(1) else 'APEX'}{m.group(2)}{m.group(3).rjust(7, '0')}"
    return re.sub(r"[^A-Z0-9]", "", t)


def admin_konto_doppel(ext, konten):
    """REIN RECHNEND: erstes Konto der Liste mit derselben External ID (normiert) oder dessen Name die Nummer enthält (ab 8 Zeichen) — sonst None.
    Wie kontoDoppelFinden; die Liste enthält archivierte Konten mit (das Archiv ist nur ein Merker)."""
    k = admin_konto_ext_norm(ext)
    if not k:
        return None
    for a in konten or ():
        if admin_konto_ext_norm(a.get("external_id")) == k or (len(k) >= 8 and k in admin_konto_ext_norm(a.get("name"))):
            return a
    return None


def admin_konto_zeile(b):
    """REIN RECHNEND: (zeile, None) oder (None, Fehlertext) aus dem Request-Body — nur Whitelist-Felder, Typen geprüft; user_id setzt die Route."""
    def text(k, n):
        return str(b.get(k) or "").strip()[:n]

    def zahl(k):
        v = b.get(k)
        if v in (None, ""):
            return None
        if isinstance(v, bool):
            raise ValueError(k)
        try:
            f = float(v)
        except (TypeError, ValueError, OverflowError):
            raise ValueError(k)
        if f != f or f <= 0 or f > 1e9:
            raise ValueError(k)
        return f

    def ganz(k, lo, hi, leer=None):
        # nur echte Ganzzahl oder Ziffern-Text — kein bool, kein 5.9 → 5, kein Infinity (Gegenprüfung 29.10.2026)
        v = b.get(k)
        if v in (None, ""):
            return leer
        if isinstance(v, int) and not isinstance(v, bool):
            n = v
        elif isinstance(v, str) and re.fullmatch(r"\d{1,4}", v.strip()):
            n = int(v.strip())
        else:
            raise ValueError(k)
        if not lo <= n <= hi:
            raise ValueError(k)
        return n

    def datum(k):
        v = str(b.get(k) or "").strip()
        if not v:
            return None
        try:
            datetime.strptime(v[:10], "%Y-%m-%d")
        except ValueError:
            raise ValueError(k)
        if len(v) != 10:
            raise ValueError(k)
        return v

    b = b if isinstance(b, dict) else {}
    name, firm, ext, typ = text("name", 120), text("firm", 60), text("external_id", 64), text("account_type", 20)
    if not name or not firm:
        return None, "Name und Firma sind Pflicht"
    if not ext:
        return None, "External ID ist Pflicht"
    if typ not in ADMIN_KONTO_TYPEN:
        return None, "Typ nicht erlaubt"
    try:
        zeile = {"name": name, "firm": firm, "account_type": typ, "external_id": ext,
                 "purchase_cost": zahl("purchase_cost"), "max_drawdown": zahl("max_drawdown"), "max_risiko_trade": zahl("max_risiko_trade"),
                 "auto_planer": b.get("auto_planer") is not False, "wd_farm": False}
        cons = zahl("consistency_pct")   # nur wenn im Modal gewählt (Standard = leer = DB-Standard); „Andere Zahl" darf Komma haben
        if cons is not None and cons > 100:
            raise ValueError("consistency_pct")
        if cons is not None:
            zeile["consistency_pct"] = cons
        if typ == "funded_cfd":   # Payout-Block des Modals: nur Funded CFD
            zeile["payout_ready_at"] = datum("payout_ready_at")
            zeile["waiting_payout_since"] = datetime.now(timezone.utc).isoformat() if b.get("waiting_payout") is True else None
        ziel = b.get("goal_kind") or None
        if ziel is not None and ziel not in ADMIN_KONTO_ZIELE:
            raise ValueError("goal_kind")
        if ziel:
            zeile.update(goal_kind=ziel, goal_target=ganz("goal_target", 1, 100, 5), goal_min_profit=zahl("goal_min_profit"),
                         goal_done_offset=ganz("goal_done_offset", 0, 100), goal_since=datum("goal_since"), goal_manual=ziel == "winning_days")
    except (TypeError, ValueError) as e:
        return None, f"Feld ungültig: {e}"
    return zeile, None


def _admin_konto_gate():
    """→ (erlaubt, None) oder (None, (Antwort, Status)); erlaubt = None (alle IDs) oder Menge der user_ids (Verwalter mit ?ansicht=admin).
    Eng wie kapital_app._gate: eingeschränkte Logins nur als Verwalter, sonst ADMIN_EMAILS oder admin_mail_leser."""
    uid, err = _wd_login()
    if err:
        return None, err
    g.admin_konto_uid = str(uid)   # fürs Log: wer hat angelegt
    nein = (jsonify({"ok": False, "msg": "Nur für Admins oder den Verwalter der Gruppe"}), 403)
    sicht = getattr(g, "admin_sicht", None)
    if sicht is not None:
        if getattr(g, "admin_verwalter", False) and not isinstance(sicht, str) and sicht:
            return frozenset(str(x) for x in sicht), None
        return None, nein
    _mail, err = _admin_auth()
    if err is None:
        return None, None
    if err[1] != 403:
        return None, err
    try:
        if str(uid) in admin_mail_leser_uids():
            return None, None
    except Exception:
        return None, (jsonify({"ok": False, "msg": "Anmeldung nicht prüfbar"}), 502)
    return None, nein


@app.route("/admin/konto-anlegen", methods=["POST", "OPTIONS"])
def admin_konto_anlegen():
    """POST /admin/konto-anlegen {user_id, name, firm, account_type, external_id, …, tv_name?} → {ok, account, markiert} | 409 {ok:false, msg,
    konto:{id,name}} (gibt es schon) | 400/403/404/502. Siehe Block oben."""
    if request.method == "OPTIONS":
        return "", 200
    erlaubt, err = _admin_konto_gate()
    if err:
        return err
    b = request.get_json(silent=True) or {}
    ziel = str(b.get("user_id") or "").strip().lower()
    if not ADMIN_MAIL_UID_RE.fullmatch(ziel):
        return jsonify({"ok": False, "msg": "user_id fehlt oder ungültig"}), 400
    if erlaubt is not None and ziel not in erlaubt:
        return jsonify({"ok": False, "msg": "ID nicht in deiner Gruppe"}), 403
    zeile, fehler = admin_konto_zeile(b)
    if fehler:
        return jsonify({"ok": False, "msg": fehler}), 400
    try:
        if not any(str(u.get("id")) == ziel for u in (_auth_liste_anfrage().json() or {}).get("users", [])):
            return jsonify({"ok": False, "msg": "ID nicht gefunden"}), 404
        doppel = admin_konto_doppel(zeile["external_id"], sb_select("accounts", {"select": "id,name,external_id", "user_id": f"eq.{ziel}"}) or [])
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht prüfbar: {type(e).__name__}"}), 502
    if doppel:
        return jsonify({"ok": False, "msg": f"Gibt es schon: {doppel.get('name') or zeile['external_id']} — nicht doppelt angelegt",
                        "konto": {"id": doppel.get("id"), "name": doppel.get("name")}}), 409
    # DD1 (06.11.2026): ohne Max DD aus dem Modal → Schablone Firma × Typ × Größe, sonst Firmen-Kernwert; Lesefehler → Feld bleibt leer wie bisher
    try:
        if not _wd_num(zeile.get("max_drawdown")):
            _m = re.search(r"(\d{2,3})\s*k\b", str(zeile.get("name") or ""), re.I)
            _vl = konto_vorlage_finden(sb_select("bulk_vorlagen", {"select": "*", "aktiv": "eq.true"}) or [], zeile.get("firm"), zeile.get("account_type"),
                                       float(_m.group(1)) * 1000) if _m else None   # ohne Größe keine Schablone (sonst die erste beliebiger Größe)
            konto_dd_ergaenzen(zeile, _vl, *_konto_dd_regeln(ziel, zeile.get("account_type")))
    except Exception as e:
        print(f"[admin-konto] ⚠️ Max DD nicht ergänzt: {type(e).__name__}: {e}", flush=True)
    hinweis = []
    try:
        try:
            neu = sb_insert("accounts", dict(zeile, user_id=ziel))
        except requests.exceptions.HTTPError as e:
            # Spalte consistency_pct fehlt (SQL nicht eingespielt) → ohne Feld nochmal, wie accConsFehlt im Frontend
            if "consistency_pct" not in zeile or "consistency_pct" not in str(getattr(getattr(e, "response", None), "text", "") or ""):
                raise
            zeile.pop("consistency_pct")
            hinweis.append("Consistency nicht gespeichert (Spalte fehlt)")
            neu = sb_insert("accounts", dict(zeile, user_id=ziel))
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht angelegt: {str(e)[:160]}"}), 502
    acc_id = (neu or {}).get("id")
    print(f"[admin-konto] {getattr(g, 'admin_konto_uid', '')} legt für {ziel} an: "
          f"{zeile['name']} ({acc_id})", flush=True)
    if zeile.get("purchase_cost"):   # wie saveAccount: Auto-Transaktion für den Kaufpreis (EUR, negativ)
        try:
            sb_insert("transactions", {"user_id": ziel, "account_id": acc_id, "account_name": zeile["name"], "account_firm": zeile["firm"],
                                       "kind": "account_purchase", "amount": -abs(zeile["purchase_cost"]), "currency": "EUR",
                                       "occurred_at": datetime.now(timezone.utc).date().isoformat(), "notes": "Account-Kauf (auto)",
                                       "auto_generated": True})
        except Exception as e:
            hinweis.append(f"Kauf-Transaktion nicht gebucht ({type(e).__name__})")
    markiert = False
    tv_name = str(b.get("tv_name") or "").strip()[:120]
    if tv_name and acc_id and admin_konto_ext_norm(tv_name) != admin_konto_ext_norm(zeile["external_id"]):
        # External ID im Modal geändert (Tippfehler korrigiert): die TV-Zeile gehört zu einer anderen Nummer — nicht als angelegt markieren
        hinweis.append("TV-Zeile nicht markiert (External ID weicht ab)")
    elif tv_name and acc_id:
        try:
            markiert = bool(sb_update("tv_konten", {"user_id": f"eq.{ziel}", "name": f"eq.{tv_name}", "angelegt_account_id": "is.null"},
                                      {"angelegt_account_id": acc_id}))
        except requests.exceptions.HTTPError as e:
            if not admin_gruppen_tabelle_fehlt(e):
                hinweis.append("TV-Zeile nicht markiert")
        except Exception:
            hinweis.append("TV-Zeile nicht markiert")
    return jsonify({"ok": True, "account": neu, "markiert": markiert, "hinweis": " · ".join(hinweis)})


