KONTO_RESET_CFD_TYPEN = frozenset({"phase1", "phase2", "funded_cfd"})


def konto_reset_typ(alt_typ):
    """REIN RECHNEND (testbar): Typ der neuen Zeile nach einem Reset — CFD-Phasen → phase1, sonst challenge."""
    return "phase1" if str(alt_typ or "") in KONTO_RESET_CFD_TYPEN else "challenge"
KONTO_PHASE_NAME = {"challenge": "Challenge", "phase1": "Phase 1", "phase2": "Phase 2", "funded": "Funded", "funded_cfd": "Funded",
                    "winning_days": "Winning Days"}


def konto_reset_zeile(alt, neu_ext, vorlage=None):
    """REIN RECHNEND (testbar): neue Konto-Zeile nach einem Reset aus der alten (accounts-Zeile) → dict ohne user_id. Einstellungen der alten
    Zeile, External ID neu, Startbalance = Größe, Balance 0, nie WD-Farm/Duplikum/Zugangsdaten, Ziel-Zählung frisch; Kaufpreis aus der Vorlage
    (bulk_vorlagen), sonst der alten Zeile. Name nach der Namensregel „<Größe> <External ID> → <Phase>"."""
    z = {k: alt.get(k) for k in KONTO_RESET_KOPIE if alt.get(k) is not None}
    z["account_type"] = konto_reset_typ(alt.get("account_type"))
    if vorlage and _wd_num(vorlage.get("purchase_cost")):
        z["purchase_cost"] = _wd_num(vorlage["purchase_cost"])
    if vorlage and _wd_num(vorlage.get("consistency_pct")):
        z["consistency_pct"] = _wd_num(vorlage["consistency_pct"])
    gr = _wd_num(alt.get("account_size")) or _wd_num(alt.get("starting_balance")) or _wd_num((vorlage or {}).get("account_size"))
    if gr:
        z["account_size"] = gr
        z["starting_balance"] = gr
    gr_txt = (f"{gr / 1000:g}k " if gr else "")
    z.update(external_id=str(neu_ext).strip(), balance=0, wd_farm=False, duplikum_linked=False, goal_manual=z.get("goal_kind") == "winning_days",
             name=f"{gr_txt}{str(neu_ext).strip()} → {KONTO_PHASE_NAME.get(z.get('account_type'), 'Challenge')}")
    z.setdefault("account_type", "challenge")
    z.setdefault("currency", "USD")
    return z


def konto_vorlage_finden(vorlagen, firm, typ, groesse):
    """REIN RECHNEND (testbar): aktive Schablone gleicher Firma × Typ × Größe (account_size/starting_balance) → dict oder None."""
    for v in vorlagen or ():
        if v.get("aktiv") is False or str(v.get("firm") or "").strip().lower() != str(firm or "").strip().lower() or v.get("account_type") != typ:
            continue
        if groesse and _wd_num(v.get("account_size") or v.get("starting_balance")) != _wd_num(groesse):
            continue
        return v
    return None


def _konto_verworfen_lesen(uids):
    """{user_id: [EXT normiert, …]} aus user_settings 'konto_verworfen'. Wirft."""
    out = {}
    for r in _sb_all("user_settings", {"select": "user_id,value", "key": f"eq.{KONTO_VERWORFEN_KEY}", "user_id": f"in.({','.join(uids)})"}) or []:
        v = r.get("value") if isinstance(r.get("value"), dict) else {}
        out[str(r.get("user_id"))] = sorted(v)
    return out


def _konto_ziel_uid(b):
    """Ziel-ID einer Bestätigen-/Verwerfen-Aktion → (ziel, None) | (None, Antwort). Eigene ID (sb-token) immer; eine andere nur mit dem Gate
    von /admin/konto-anlegen (ADMIN_EMAILS/admin_mail_leser, Verwalter nur seine Gruppe)."""
    uid, _mail, err = _login_uid_mail()
    if err:
        return None, err
    ziel = str((b or {}).get("user_id") or uid).strip().lower()
    if not ADMIN_MAIL_UID_RE.fullmatch(ziel):
        return None, (jsonify({"ok": False, "msg": "user_id ungültig"}), 400)
    if ziel == str(uid):
        return ziel, None
    erlaubt, err = _admin_konto_gate()
    if err:
        return None, err
    if erlaubt is not None and ziel not in erlaubt:
        return None, (jsonify({"ok": False, "msg": "ID nicht in deiner Gruppe"}), 403)
    return ziel, None


@app.route("/konto-mails/mein", methods=["GET", "OPTIONS"])
def konto_mails_mein():
    """GET /konto-mails/mein?betreff=<a>|<b>…[&tage=14] (eingeloggt, eigene ID) → {ok, mails:[…wie /admin/konto-mails], verworfen:[EXT…]}."""
    if request.method == "OPTIONS":
        return "", 200
    uid, _mail, err = _login_uid_mail()
    if err:
        return err
    woerter = [w.strip() for w in str(request.args.get("betreff") or "").split("|") if w.strip()]
    woerter = [w for w in woerter if KONTO_MAIL_BETREFF_RE.fullmatch(w)][:12]
    if not woerter:
        return jsonify({"ok": False, "msg": "betreff fehlt (Suchwörter mit | getrennt)"}), 400
    try:
        tage = max(1, min(60, int(str(request.args.get("tage") or KONTO_ZU_BESTAETIGEN_TAGE))))
    except ValueError:
        return jsonify({"ok": False, "msg": "tage ungültig"}), 400
    try:
        mails = _konto_mails_laden([uid], woerter, tage)
        verworfen = _konto_verworfen_lesen([uid]).get(uid, [])
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Mails nicht lesbar: {str(e)[:120]}"}), 503
    return jsonify({"ok": True, "mails": mails, "verworfen": verworfen, "tage": tage})


@app.route("/konto-verwerfen", methods=["POST", "OPTIONS"])
def konto_verwerfen():
    """POST {ext[, user_id][, tv_name]} → {ok}: Zeile „zu bestätigen" ausblenden (nichts gelöscht). Eigene ID oder Admin-Gate."""
    if request.method == "OPTIONS":
        return "", 200
    b = request.get_json(silent=True) or {}
    ziel, err = _konto_ziel_uid(b)
    if err:
        return err
    ext = admin_konto_ext_norm(b.get("ext"))
    if not 6 <= len(ext) <= 64:
        return jsonify({"ok": False, "msg": "ext ungültig"}), 400
    jetzt = datetime.now(timezone.utc).isoformat()
    try:
        z = sb_select("user_settings", {"select": "value", "user_id": f"eq.{ziel}", "key": f"eq.{KONTO_VERWORFEN_KEY}", "limit": "1"}) or []
        v = dict((z[0].get("value") if z and isinstance(z[0].get("value"), dict) else {}))
        v[ext] = jetzt
        if len(v) > KONTO_VERWORFEN_MAX:
            v = dict(sorted(v.items(), key=lambda kv: str(kv[1]))[-KONTO_VERWORFEN_MAX:])
        _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/user_settings", params={"on_conflict": "user_id,key"},
                    json={"user_id": ziel, "key": KONTO_VERWORFEN_KEY, "value": v, "updated_at": jetzt},
                    headers=_sb_headers("resolution=merge-duplicates,return=minimal"), timeout=12).raise_for_status()
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
    tv = tv_konto_normal(b.get("tv_name"))
    if TV_KONTEN_NAME_RE.fullmatch(tv):           # dieselbe Zeile steht auch im TV-Dropdown → dort ebenfalls ignoriert (Tabelle fehlt → egal)
        try:
            sb_update("tv_konten", {"user_id": f"eq.{ziel}", "name": f"eq.{tv}", "ignoriert_at": "is.null"}, {"ignoriert_at": jetzt})
        except Exception:
            pass
    return jsonify({"ok": True})


# RÜCKGÄNGIG NACH EIN-KLICK-ANLEGEN (30.10.2026, Master nach S2-Hinweis: „Tradeify vs. Tradeify CFD wurde schon öfter verwechselt"): der Toast
# „Angelegt: <Name> · <Firma> · <Typ> (für <ID>) · Rückgängig" (~15 s) ruft POST /konto-rueckgaengig {account_id, alt_id?}. Rückgängig =
# das NEUE Konto archivieren (Grund 'rueckgaengig'), NIE löschen; bei einem Reset kommt die alte Zeile aus dem Archiv zurück (alt_id, gleicher
# Besitzer). Nur für Konten, die höchstens KONTO_RUECK_S alt sind. Recht: Besitzer selbst, sonst das Gate von /admin/konto-anlegen. Die
# Kauf-Buchung bleibt stehen (nichts wird gelöscht); geplante Pläne eines archivierten Kontos fallen ohnehin aus Planer und Delta.
KONTO_RUECK_S = 30 * 60


def konto_rueckgaengig_pruefen(neu, alt, jetzt):
    """REIN RECHNEND (testbar): darf das Anlegen rückgängig gemacht werden? neu/alt = accounts-Zeilen {id, user_id, created_at} (alt optional).
    → None oder Fehlertext."""
    if not neu or not neu.get("id"):
        return "Konto nicht gefunden"
    try:
        t = datetime.fromisoformat(str(neu.get("created_at") or "").replace("Z", "+00:00"))
    except ValueError:
        return "Anlegezeit unbekannt"
    if t.tzinfo is None:
        t = t.replace(tzinfo=timezone.utc)
    if (jetzt - t).total_seconds() > KONTO_RUECK_S:
        return f"zu alt für Rückgängig (älter als {KONTO_RUECK_S // 60} min) — unter Accounts archivieren"
    if alt is not None:
        if not alt.get("id") or str(alt.get("id")) == str(neu.get("id")):
            return "alte Zeile ungültig"
        if str(alt.get("user_id")) != str(neu.get("user_id")):
            return "alte Zeile gehört einer anderen ID"
    return None


@app.route("/konto-rueckgaengig", methods=["POST", "OPTIONS"])
def konto_rueckgaengig():
    if request.method == "OPTIONS":
        return "", 200
    b = request.get_json(silent=True) or {}
    kid, alt_id = str(b.get("account_id") or "").strip().lower(), str(b.get("alt_id") or "").strip().lower()
    if not re.match(r"^[0-9a-f-]{36}$", kid) or (alt_id and not re.match(r"^[0-9a-f-]{36}$", alt_id)):
        return jsonify({"ok": False, "msg": "account_id/alt_id ungültig"}), 400
    uid, _mail, err = _login_uid_mail()
    if err:
        return err
    try:
        zeilen = sb_select("accounts", {"select": "id,user_id,name,created_at", "id": f"in.({','.join([kid] + ([alt_id] if alt_id else []))})"}) or []
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht prüfbar: {type(e).__name__}"}), 502
    neu = next((z for z in zeilen if str(z.get("id")) == kid), None)
    alt = next((z for z in zeilen if str(z.get("id")) == alt_id), None) if alt_id else None
    if alt_id and alt is None:
        return jsonify({"ok": False, "msg": "alte Zeile nicht gefunden"}), 404
    fehler = konto_rueckgaengig_pruefen(neu, alt, datetime.now(timezone.utc))
    if fehler:
        return jsonify({"ok": False, "msg": fehler}), 404 if fehler == "Konto nicht gefunden" else 409
    besitzer = str(neu.get("user_id"))
    if besitzer != str(uid):
        erlaubt, err = _admin_konto_gate()
        if err:
            return err
        if erlaubt is not None and besitzer not in erlaubt:
            return jsonify({"ok": False, "msg": "ID nicht in deiner Gruppe"}), 403
    jetzt_iso = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    try:
        _konto_archiv_eintragen(besitzer, kid, "rueckgaengig", jetzt_iso, neu.get("name"))
        _ap_archiv_merk["wert"] = None
        alt_zurueck = _archiv_eintrag_entfernen(alt_id) if alt else 0
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht rückgängig: {type(e).__name__}: {str(e)[:120]}"}), 502
    print(f"[konto-rueckgaengig] {str(uid)[:8]}: {neu.get('name')} archiviert (Rückgängig){(', alte Zeile ' + str(alt.get('name') or '') + ' wieder aktiv') if alt else ''}", flush=True)
    return jsonify({"ok": True, "archiviert": kid, "alt_wieder_aktiv": bool(alt_zurueck) if alt else None})


@app.route("/konto-reset-bestaetigen", methods=["POST", "OPTIONS"])
def konto_reset_bestaetigen():
    """POST {neu, alt[, user_id][, tv_name]} → {ok, account, archiviert, hinweis} | 404 (alte Zeile fehlt → als Kauf anlegen) | 409 (neue
    External ID gibt es schon). Eigene ID oder Admin-Gate. Siehe Block oben."""
    if request.method == "OPTIONS":
        return "", 200
    b = request.get_json(silent=True) or {}
    ziel, err = _konto_ziel_uid(b)
    if err:
        return err
    neu_ext, alt_ext = str(b.get("neu") or "").strip(), str(b.get("alt") or "").strip()
    if not 6 <= len(admin_konto_ext_norm(neu_ext)) <= 64 or not 6 <= len(admin_konto_ext_norm(alt_ext)) <= 64 \
            or admin_konto_ext_norm(neu_ext) == admin_konto_ext_norm(alt_ext):
        return jsonify({"ok": False, "msg": "neu/alt ungültig"}), 400
    try:
        konten = sb_select("accounts", {"select": "*", "user_id": f"eq.{ziel}"}) or []
        archiv = _ap_archiviert()
        vorlagen = sb_select("bulk_vorlagen", {"select": "*", "aktiv": "eq.true"}) or []
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht prüfbar: {type(e).__name__}"}), 502
    doppel = admin_konto_doppel(neu_ext, konten)
    if doppel:
        return jsonify({"ok": False, "msg": f"Gibt es schon: {doppel.get('name') or neu_ext} — nicht doppelt angelegt",
                        "konto": {"id": doppel.get("id"), "name": doppel.get("name")}}), 409
    k_alt = admin_konto_ext_norm(alt_ext)
    # mehrere Zeilen mit derselben Nummer (Fehl-Zeile von Hand archiviert, Gegenprüfung 29.10.2026): die aktive zuerst, sonst die jüngste
    kandidaten = sorted((a for a in konten if admin_konto_ext_norm(a.get("external_id")) == k_alt),
                        key=lambda a: (str(a.get("id")) not in archiv, str(a.get("created_at") or "")), reverse=True)
    alt = kandidaten[0] if kandidaten else None
    if not alt:
        return jsonify({"ok": False, "msg": f"Alte Zeile {alt_ext} gibt es bei dieser ID nicht — als Kauf anlegen"}), 404
    if (alt.get("account_type") or "challenge") not in ADMIN_KONTO_TYPEN:
        return jsonify({"ok": False, "msg": f"Alte Zeile ist {alt.get('account_type')} — Reset nur für Prop-Firm-Konten"}), 400
    # Größe der alten Zeile, sonst aus ihrem Namen (DD1-Gegenprüfung 06.11.2026: 725 von 1.605 Konten ohne account_size/starting_balance — ohne Größe nahm
    # konto_vorlage_finden die erste Schablone der Firma, ein „100k" wurde zum „150k" mit dessen Max DD)
    _m_alt = re.search(r"(\d{2,3})\s*k\b", str(alt.get("name") or ""), re.I)
    _gr_alt = alt.get("account_size") or alt.get("starting_balance") or (float(_m_alt.group(1)) * 1000 if _m_alt else None)
    vorlage = konto_vorlage_finden(vorlagen, alt.get("firm"), konto_reset_typ(alt.get("account_type")), _gr_alt)
    zeile = konto_reset_zeile(alt, neu_ext, vorlage)
    # DD1 (06.11.2026): alte Zeile ohne Max DD → Schablone, sonst Firmen-Kernwert (vorher erbte der Reset die Lücke); Lesefehler → Feld bleibt leer.
    # Ohne bekannte Größe gar nicht (die Zeile trüge sonst die Größe einer beliebigen Schablone), Flex am alten Namen zählt
    try:
        if _gr_alt:
            konto_dd_ergaenzen(zeile, vorlage, *_konto_dd_regeln(ziel, zeile.get("account_type")), namen=(alt.get("name"),))
    except Exception as e:
        print(f"[konto-reset] ⚠️ Max DD nicht ergänzt: {type(e).__name__}: {e}", flush=True)
    hinweis = []
    try:
        try:
            neu = sb_insert("accounts", dict(zeile, user_id=ziel))
        except requests.exceptions.HTTPError as e:
            if "consistency_pct" not in zeile or "consistency_pct" not in str(getattr(getattr(e, "response", None), "text", "") or ""):
                raise
            zeile.pop("consistency_pct")
            hinweis.append("Consistency nicht übernommen (Spalte fehlt)")
            neu = sb_insert("accounts", dict(zeile, user_id=ziel))
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht angelegt: {str(e)[:160]}"}), 502
    acc_id = (neu or {}).get("id")
    jetzt = datetime.now(timezone.utc).isoformat()
    print(f"[konto-reset] {ziel[:8]}: {alt.get('name')} → {zeile['name']} ({acc_id})", flush=True)
    if zeile.get("purchase_cost"):   # wie saveAccount / /admin/konto-anlegen: Kauf-Transaktion (EUR, negativ) — Reset = Kauf
        try:
            sb_insert("transactions", {"user_id": ziel, "account_id": acc_id, "account_name": zeile["name"], "account_firm": zeile.get("firm"),
                                       "kind": "account_purchase", "amount": -abs(float(zeile["purchase_cost"])), "currency": "EUR",
                                       "occurred_at": datetime.now(timezone.utc).date().isoformat(), "notes": f"Reset von {alt_ext} (auto)",
                                       "auto_generated": True})
        except Exception as e:
            hinweis.append(f"Kauf-Transaktion nicht gebucht ({type(e).__name__})")
    archiviert = False
    if str(alt.get("id")) not in archiv:
        try:
            archiviert = _konto_archiv_eintragen(ziel, str(alt["id"]), "blown", jetzt, name=alt.get("name"))
        except Exception as e:
            hinweis.append(f"alte Zeile nicht archiviert ({type(e).__name__}) — von Hand als blown archivieren")
    plaene_weg = []
    if archiviert or str(alt.get("id")) in archiv:
        # wie archiveAccount()/archivPlaeneEntfernen im Frontend (Master 29.10.2026): geplante, nie gestartete Pläne der alten Zeile sofort
        # weg — sonst will Puls bis zum nächsten Archiv-Sweep auf einem Konto starten, das es nicht mehr gibt. Laufende/Review bleiben.
        try:
            plaene_weg = _ap_plaene_entfernen(ap_archiv_sweep_ziele(
                sb_select("trade_plans", {"select": AP_SWEEP_FELDER, "master_account_id": f"eq.{alt['id']}", "status": "eq.planned",
                                          "started_at": "is.null"}) or [], {str(alt["id"])}))
        except Exception as e:
            hinweis.append(f"geplante Trades der alten Zeile nicht entfernt ({type(e).__name__}) — der Archiv-Sweep holt es nach")
        if alt.get("rest_planer_at"):   # wie archiveAccount(): „Rest zurück im Planer" weg
            try:
                sb_update("accounts", {"id": f"eq.{alt['id']}"}, {"rest_planer_at": None})
            except Exception:
                pass
    tv = tv_konto_normal(b.get("tv_name"))
    if acc_id and TV_KONTEN_NAME_RE.fullmatch(tv) and admin_konto_ext_norm(tv) == admin_konto_ext_norm(neu_ext):
        try:
            sb_update("tv_konten", {"user_id": f"eq.{ziel}", "name": f"eq.{tv}", "angelegt_account_id": "is.null"}, {"angelegt_account_id": acc_id})
        except Exception:
            pass
    return jsonify({"ok": True, "account": neu, "archiviert": archiviert, "alt": {"id": alt.get("id"), "name": alt.get("name")},
                    "plaene_entfernt": len(plaene_weg), "typ": zeile.get("account_type"), "consistency_pct": zeile.get("consistency_pct"),
                    "schablone": (vorlage or {}).get("name"), "hinweis": " · ".join(hinweis)})


@app.route("/admin/mail/<int:mid>", methods=["GET", "OPTIONS"])
def admin_mail_eine(mid):
    """GET /admin/mail/<id> → {ok, mail:{id, user_id, von, an, betreff, datum, text, html, anhaenge, gelesen, labels}} — eine Mail zum Lesen
    (das Frontend darf fremde Zeilen per RLS nicht lesen). Setzt NICHT gelesen (das macht PATCH, wie der Mail-Reiter nach dem Öffnen).
    Gate wie /admin/mail (_admin_mail_auth)."""
    if request.method == "OPTIONS":
        return "", 200
    err = _admin_mail_auth()
    if err:
        return err
    try:
        _disp, sicht = _admin_mail_sicht()
        rows = sb_select("mails", {"select": ADMIN_MAIL_VOLL_FELDER, "id": f"eq.{int(mid)}", "limit": "1"}) or []
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Mail nicht lesbar: {str(e)[:120]}"}), 503
    if not rows or str(rows[0].get("user_id")) not in sicht:
        return jsonify({"ok": False, "msg": "Mail nicht gefunden"}), 404
    return jsonify({"ok": True, "mail": rows[0]})


@app.route("/code/datei/<path:pfad>", methods=["GET"])
def code_datei(pfad):
    """Eine Repo-Datei aus genau dem deployten Stand. ?sha=… muss (falls angegeben) dieser Stand sein, sonst 409 mit dem
    aktuellen — der PC fragt dann neu. Header X-Code-Token."""
    sha = _code_stand_sha()
    if not sha:
        return jsonify({"ok": False, "msg": "nur auf Railway"}), 404
    if not _code_zugang():
        return jsonify({"ok": False, "msg": "kein gültiger Schlüssel"}), 403
    if not code_pfad_ok(pfad):
        return jsonify({"ok": False, "msg": "Pfad nicht erlaubt"}), 400
    will = (request.args.get("sha") or "").strip().lower()
    if will and will != sha:
        return jsonify({"ok": False, "msg": "anderer Stand", "sha": sha}), 409
    ziel = os.path.join(_CODE_WURZEL, *pfad.split("/"))
    if not os.path.isfile(ziel):
        return jsonify({"ok": False, "msg": "nicht gefunden"}), 404
    with open(ziel, "rb") as f:
        daten = f.read()
    resp = Response(daten, status=200, mimetype="application/octet-stream")
    resp.headers["Cache-Control"] = "no-store"
    resp.headers["X-Code-Sha"] = sha
    return resp


# TAB SELBST NEU LADEN (Finn 16.10.2026: „Wenn man den Tab neu laden muss, mach das als Bot — wie beim Balancelesen. Nie mehr Hand-F5."
# Anlass Chris · pc-c19p2l: Tab hing mit „Popup offen" auf .1565, Copier/Bot schon .1582, F5 von Hand nötig — auch Tabs mit altem Code
# müssen wieder nachziehen). Das Panel am PC (per Code-Sync immer aktuell) fragt hier je Minute, wie sein Tab steht, und lädt ihn
# selbst neu (Strg+F5 im Prophos-Fenster). Hier nur Lesen: Tab-Stand aus mt5_live + Riegel des Servers für diesen PC. ?panel= ist die
# letzte Entscheidung des Panels — geloggt bei Änderung (Spur im Railway-Log).
_tab_stand_spur = {}
_tab_nl_stand = {}   # pc → {grund, grund_at, ergebnis, ergebnis_at}: dieselbe Spur für /admin/pc-stand (02.11.2026); nach einem Railway-Neustart spätestens in 1 min wieder da


def tab_nl_merken(merk, pc, spur, ergebnis, ergebnis_at, jetzt):
    """REIN RECHNEND auf merk (testbar): Neulade-Grund und letztes Ergebnis des Panels je PC. Leere Spur = Tab aktuell, Grund weg; das letzte Ergebnis bleibt stehen.
    ergebnis_at = Zeit des Panels in s, unlesbar → jetzt beim ersten Sehen."""
    z = merk.setdefault(pc, {"grund": "", "grund_at": None, "ergebnis": "", "ergebnis_at": None})
    if spur != z["grund"]:
        z.update(grund=spur, grund_at=jetzt)
    if ergebnis and ergebnis != z["ergebnis"]:
        try:
            at = float(ergebnis_at)
        except (TypeError, ValueError):
            at = 0.0
        z.update(ergebnis=ergebnis, ergebnis_at=at if at > 0 else jetzt)
    return z


def tab_stand_riegel(signale_laeuft, plaene, pc, jetzt):
    """REIN RECHNEND (testbar): Server-Grund, der ein Neuladen des Tabs auf diesem PC jetzt verbietet, sonst ''. signale_laeuft =
    order_signale status laeuft mit pc = dieser PC; plaene = trade_plans der IDs dieses PCs (status, start_um, start_um_gestartet_at,
    auto_plan, auto_bestaetigt_at, hedge_status, hedge_pc)."""
    if signale_laeuft:
        return f"Puls/Signal läuft auf diesem PC ({len(signale_laeuft)})"
    for p in plaene or ():
        st = str(p.get("status") or "")
        if st == "open" and p.get("hedge_status") in ("oeffnet", "schliesst") and (not p.get("hedge_pc") or p.get("hedge_pc") == pc):
            return "Hedge öffnet/schließt"
        if st != "planned":
            continue
        gest = _ap_ts(p.get("start_um_gestartet_at"))
        if gest is not None and (jetzt - gest).total_seconds() < 360:
            return "Start geclaimt (< 6 min)"
        su = _ap_ts(p.get("start_um"))
        if gest is None and su is not None and -180 <= (su - jetzt).total_seconds() <= 300 and (not p.get("auto_plan") or p.get("auto_bestaetigt_at")):
            return "Start in ≤ 5 min"
    return ""


# ══ FERN-AUFTRAG „PROPHOS IM PULS-CHROME ÖFFNEN" (30.10.2026, Finn, während Pascal sich an allen HT-PCs im Puls-Chrome einloggt: „Mach
# diesen Tab nochmal überall auf." — bei Chris war das Prophos-Fenster im Puls-Chrome nicht offen). Admin setzt je PC (oder für alle HT-PCs)
# einen einmaligen Auftrag (Speicher, ein Worker, verfällt nach TAB_AUFTRAG_GUELTIG_S); das Panel liest ihn beim minütlichen Tab-Stand-
# Abruf, öffnet Prophos im Puls-Chrome im eigenen Fenster bzw. holt den vorhandenen Tab nach vorn (mit allen Riegeln) und quittiert über
# POST /pc/tab-auftrag-quittung (geöffnet / nach vorn / verschoben mit Grund / Fehler). Nur HT-PCs, kein Login, kein Klick in TradingView. ══
TAB_AUFTRAG_GUELTIG_S = 10 * 60
_tab_auftrag = {}   # pc → {"id", "at", "von", "quittung": {"at", "ergebnis", "grund"} | None}


def tab_auftrag_offen(a, jetzt_ts):
    """REIN RECHNEND (testbar): offener Auftrag für das Panel → {"id", "at"} oder None (keiner, verfallen oder schon erledigt)."""
    if not isinstance(a, dict) or not a.get("id") or jetzt_ts - float(a.get("at") or 0) >= TAB_AUFTRAG_GUELTIG_S:
        return None
    if str(((a.get("quittung") or {}).get("ergebnis")) or "") in ("geoeffnet", "vorn"):
        return None
    return {"id": a["id"], "at": a["at"]}


def tab_auftrag_ht_pcs(rows, aus, fremd):
    """REIN RECHNEND (testbar): mt5_live-Zeilen → sortierte PC-Kennungen der HT-IDs (ohne ausgeblendete und fremd verwaltete IDs)."""
    return sorted({str(r.get("pc_name")) for r in rows or [] if re.fullmatch(r"pc-[a-z0-9]{4,12}", str(r.get("pc_name") or ""))
                   and str(r.get("user_id") or "") and str(r.get("user_id")) not in aus and not fremd(str(r.get("user_id")))})


@app.route("/admin/pc-tab-auftrag", methods=["GET", "POST", "OPTIONS"])
def admin_pc_tab_auftrag():
    """GET → {ok, auftraege: {pc: {...}}, gueltig_s}. POST {pc} oder {alle: true} → Auftrag „Prophos im Puls-Chrome öffnen" je HT-PC. Voller Admin."""
    if request.method == "OPTIONS":
        return "", 200
    uid, err = _admin_voll()
    if err:
        return err
    jetzt = time.time()
    if request.method == "GET":
        return jsonify({"ok": True, "gueltig_s": TAB_AUFTRAG_GUELTIG_S, "auftraege": {pc: dict(a, offen=tab_auftrag_offen(a, jetzt) is not None,
                        alter_s=int(jetzt - float(a.get("at") or 0))) for pc, a in _tab_auftrag.items() if jetzt - float(a.get("at") or 0) < 6 * 3600}})
    d = request.get_json(silent=True) or {}
    try:
        rows = sb_select("mt5_live", {"select": "pc_name,user_id:status->>user_id",
                                      "updated_at": f"gte.{datetime.fromtimestamp(jetzt - 7 * 86400, timezone.utc).isoformat()}"}) or []
    except Exception as e:
        return jsonify({"ok": False, "error": f"PC-Liste nicht lesbar: {type(e).__name__}"}), 502
    _namen, aus = _ap_namen()
    ht = tab_auftrag_ht_pcs(rows, aus, _alarm_fremd_verwaltet)
    if d.get("alle") is True:
        ziele = ht
    else:
        pc = str(d.get("pc") or "").strip().lower()
        if pc not in ht:
            return jsonify({"ok": False, "error": "kein HT-PC (oder seit 7 Tagen ohne Prophos-Tab)"}), 403
        ziele = [pc]
    for pc in ziele:
        _tab_auftrag[pc] = {"id": uuid.uuid4().hex[:12], "at": jetzt, "von": uid, "quittung": None}
    print(f"[tab-auftrag] Prophos im Puls-Chrome öffnen → {', '.join(ziele) or '—'}", flush=True)
    return jsonify({"ok": True, "pcs": ziele, "gueltig_s": TAB_AUFTRAG_GUELTIG_S})


@app.route("/pc/tab-auftrag-quittung", methods=["POST"])
def pc_tab_auftrag_quittung():
    """Quittung des Panels (X-Code-Token, PC aus dem Schlüssel): {id, ergebnis: geoeffnet|vorn|verschoben|fehler, grund}."""
    wer = _code_zugang()
    if not wer:
        return jsonify({"ok": False, "error": "kein gültiger Schlüssel"}), 403
    pc = str(wer[1] or "")[:20]
    d = request.get_json(silent=True) or {}
    a = _tab_auftrag.get(pc)
    if not a or str(d.get("id") or "") != a.get("id"):
        return jsonify({"ok": True, "unbekannt": True})
    erg = str(d.get("ergebnis") or "")
    if erg not in ("geoeffnet", "vorn", "verschoben", "fehler"):
        return jsonify({"ok": False, "error": "ergebnis ungültig"}), 400
    a["quittung"] = {"at": time.time(), "ergebnis": erg, "grund": re.sub(r"\s+", " ", str(d.get("grund") or ""))[:200]}
    print(f"[tab-auftrag] {pc}: {erg} — {a['quittung']['grund']}", flush=True)
    return jsonify({"ok": True})


def tab_stand_offen_n(plaene, hedge_hier):
    """REIN RECHNEND (testbar, FS1 10.11.2026): Zahl offener Trades für den Neulade-Riegel im Sofort-Weg — offene Pläne der IDs dieses PCs plus offene
    Pläne anderer IDs, deren Hedge dieser PC hält (je Plan einmal)."""
    ids = {str(x.get("id") or f"#{i}") for i, x in enumerate(plaene or ()) if str(x.get("status")) == "open"}
    return len(ids | {str(x.get("id") or f"h#{i}") for i, x in enumerate(hedge_hier or ())})


def lotse_plan_stand(signale_laeuft, plaene, uids, pc, jetzt):
    """REIN RECHNEND (testbar): Felder für den Lotse-Agenten (Finn 02.11.2026: „MT5 Trades sind ja nicht unser Problem“). Es zählen alle Routen außer Echo (LT_ECHO_ROUTEN), also auch
    eine leere Route (Orbit) und jede unbekannte: Im Zweifel sperrt das mehr. Ein Plan nennt keinen PC, darum die IDs dieses PCs. plaene_offen_tv None = IDs unbekannt, gilt beim Agenten als unklar."""
    tv = [x for x in plaene or () if str(x.get("route") or "") not in LT_ECHO_ROUTEN]
    return {"plaene_offen_tv": (sum(1 for x in tv if str(x.get("status")) == "open") if uids else None),
            "riegel_tv": tab_stand_riegel(signale_laeuft, tv, pc, jetzt)}


# ══ TÄGLICHER NEUSTART JE PC (DR1, Finn 05.11.2026: „Wenn man das komplette Backend und auch die Prophos-Seite daily einmal neu startet, dann
# müsste ja der RAM in der Cache gelöscht werden.“). Railway sagt dem Panel im Tab-Stand nur, OB dieser PC jetzt neu starten darf; den Neustart
# macht das Panel (panel.py TÄGLICHER NEUSTART). Einstellung: puls_heim_regel.pc_neustart (sql/2026-11-05_pc_neustart.sql) — an (Standard aus),
# Fenster von/bis in tz (Vorschlag 02:30–05:00 Dubai), nur_pcs (leer = alle), ruhe_vor_start_min (30). Ruhig = kein Signal läuft auf dem PC,
# kein Polar-Lauf der IDs, kein Plan open, kein Überprüfen-Plan mit offenem Hedge, kein Start in den nächsten ruhe_vor_start_min (Handpläne und
# bestätigte Vorschläge), kein Claim < 15 min. Gelesen wird nur, wenn an + PC frei + Fenster offen (sonst keine Abfrage). Fehler → nicht ruhig. ══
PC_NEUSTART_STANDARD = {"an": False, "tz": "Asia/Dubai", "von": "02:30", "bis": "05:00", "nur_pcs": [], "ruhe_vor_start_min": 30,
                        "teile": {"backend": True, "reader": True}}   # DR1b: lokales Backend + Reader, je Teil abschaltbar


def pc_neustart_regel(roh):
    """REIN RECHNEND (testbar): puls_heim_regel.pc_neustart → vollständige Regel; Fehlendes/Ungültiges → Standard (an bleibt dann aus)."""
    r = dict(PC_NEUSTART_STANDARD, teile=dict(PC_NEUSTART_STANDARD["teile"]))
    if not isinstance(roh, dict):
        return r
    if isinstance(roh.get("teile"), dict):              # DR1b: nur ein echtes false schaltet einen Teil ab
        r["teile"] = {k: roh["teile"].get(k) is not False for k in r["teile"]}
    r["an"] = roh.get("an") is True
    for k in ("von", "bis"):
        v = str(roh.get(k) or "")
        if re.fullmatch(r"([01]\d|2[0-3]):[0-5]\d", v):
            r[k] = v
    if isinstance(roh.get("tz"), str) and roh.get("tz"):
        try:
            _ap_tz(roh["tz"])
            r["tz"] = roh["tz"]
        except Exception:
            pass
    if r["von"] == r["bis"]:
        r["an"] = False                              # leeres Fenster = nie
    if isinstance(roh.get("nur_pcs"), list):
        r["nur_pcs"] = [str(x).strip().lower() for x in roh["nur_pcs"] if re.fullmatch(r"pc-[a-z0-9]{4,12}", str(x).strip().lower())]
        if roh["nur_pcs"] and not r["nur_pcs"]:
            r["nur_pcs"] = ["-"]                     # nur Tippfehler in der Liste → KEIN PC (leer hieße „alle“)
    try:
        r["ruhe_vor_start_min"] = max(5, min(240, int(roh.get("ruhe_vor_start_min"))))
    except (TypeError, ValueError):
        pass
    return r


def pc_neustart_fenster(regel, jetzt):
    """REIN RECHNEND (testbar): (tag, offen, vorbei) in regel.tz. tag = Kalendertag des Fensterbeginns (über Mitternacht: Vortag)."""
    lok = jetzt.astimezone(_ap_tz(regel.get("tz") or "Asia/Dubai"))
    m, von, bis = lok.hour * 60 + lok.minute, _ap_hhmm(regel["von"]), _ap_hhmm(regel["bis"])
    if von < bis:
        return lok.date().isoformat(), von <= m < bis, m >= bis
    # Fenster über Mitternacht (z. B. 23:30–02:00): vor bis = Fenster vom Vortag; zwischen bis und von = das zuletzt beendete Fenster, also auch
    # vom Vortag (sonst wäre der neue Tag nach dem Fensterende schon „vorbei, nicht erledigt“ → täglicher Fehlalarm, Prüfer DR1); ab von = heute
    ab_von = m >= von
    tag = lok.date() if ab_von else (lok.date() - timedelta(days=1))
    return tag.isoformat(), ab_von or m < bis, bis <= m < von


def pc_neustart_unruhe(plaene, signale, polar, jetzt, ruhe_min, pc):
    """REIN RECHNEND (testbar): EIN Grund, warum der PC gerade nicht neu starten darf, sonst ''."""
    if signale:
        return f"Puls/Signal läuft auf diesem PC ({len(signale)})"
    if polar:
        return "Polar-Lauf der IDs dieses PCs"
    for p in plaene or ():
        st = str(p.get("status") or "")
        hp = p.get("hedge_pc")
        if st == "open":
            return "Trade läuft (open)"
        if st == "review" and p.get("hedge_status") in ("offen", "oeffnet", "schliesst", "unklar") and (not hp or hp == pc):
            return "Überprüfen-Plan mit offenem Hedge"
        if st != "planned":
            continue
        gest, su = _ap_ts(p.get("start_um_gestartet_at")), _ap_ts(p.get("start_um"))
        if gest is not None and (jetzt - gest).total_seconds() < 900:
            return "Start geclaimt (< 15 min)"
        # bis 60 min NACH start_um kann der Tab noch starten (Nachholen, Farmer-Fenster 60 min, Startsperren — Prüfer DR1)
        if gest is None and su is not None and -3600 <= (su - jetzt).total_seconds() <= ruhe_min * 60 \
                and (not p.get("auto_plan") or p.get("auto_bestaetigt_at")):
            return f"Start in {max(0, int((su - jetzt).total_seconds() // 60))} min"
    return ""


def pc_neustart_sicht(regel_roh, pc, jetzt, laden):
    """Feld tages_neustart des Tab-Stands. laden(ruhe_min) → (plaene, polar) wird nur aufgerufen, wenn an + PC frei + Fenster offen."""
    r = pc_neustart_regel(regel_roh)
    tag, offen, vorbei = pc_neustart_fenster(r, jetzt)
    out = {"an": r["an"], "pc_frei": (not r["nur_pcs"]) or pc in r["nur_pcs"], "tag": tag, "offen": offen, "vorbei": vorbei,
           "ruhig": False, "grund": "", "teile": r["teile"]}
    if not (out["an"] and out["pc_frei"] and offen):
        return out
    try:
        plaene, polar, signale = laden(r["ruhe_vor_start_min"])
    except Exception as e:
        out["grund"] = f"Ruhe nicht prüfbar ({type(e).__name__})"
        return out
    out["grund"] = pc_neustart_unruhe(plaene, signale, polar, jetzt, r["ruhe_vor_start_min"], pc)
    out["ruhig"] = not out["grund"]
    return out


def _pc_neustart_laden(uids, sig, jetzt, pc):
    def laden(ruhe_min):
        if not uids:
            raise ValueError("keine ID an diesem PC")
        u = "in.(" + ",".join(uids) + ")"
        sel = ("status,start_um,start_um_gestartet_at,auto_plan,auto_bestaetigt_at,"
               "hedge_status:mt5_baseline->hedge->>status,hedge_pc:mt5_baseline->hedge->>pc")
        plaene = sb_select("trade_plans", {"select": sel,
                                           "user_id": u, "or": f"(status.in.(open,review),and(status.eq.planned,start_um.is.null),"
                                                               f"and(status.eq.planned,start_um.lte.{(jetzt + timedelta(minutes=ruhe_min)).isoformat()},"
                                                               f"start_um.gte.{(jetzt - timedelta(hours=12)).isoformat()}))", "limit": "500"}) or []
        # Hedges, die DIESER PC hält, auch für IDs, die nicht in seinen mt5_live-Zeilen stehen (Prüfer DR1, wie puls_heim_pruefen)
        plaene += sb_select("trade_plans", {"select": sel, "status": "in.(open,review)", "mt5_baseline->hedge->>pc": f"eq.{pc}",
                                            "limit": "50"}) or []
        polar = sb_select("polar_lauf", {"select": "id", "status": "not.in.(fertig,abbruch)", "or": f"(master_user_id.{u},slave_user_id.{u})",
                                         "updated_at": "gte." + (jetzt - timedelta(minutes=30)).isoformat(), "limit": "3"}) or []
        return plaene, polar, sig
    return laden


TAB_NEXT_START_S = 600   # F-B: Startzeiten bis jetzt + 10 min (der Plan-Abruf unten reicht genau so weit; das Panel prüft 2–3 min vorher)


def tab_stand_next_starts(plaene, jetzt):
    """REIN RECHNEND (testbar, F-B Tab-Vorflug, Slave 4 8e292a66): nächste Startzeiten der IDs dieses PCs für das Panel (/code/tab-stand „next_start_um“,
    ISO-Liste, aufsteigend, höchstens 20). Nur Pläne, die wirklich von selbst starten: geplant, Startzeit in (jetzt, jetzt + TAB_NEXT_START_S], noch nicht
    geclaimt, kein unbestätigter Auto-Vorschlag (tpStartUmTick startet die nie)."""
    out = set()
    for x in plaene or ():
        if str(x.get("status") or "") != "planned" or x.get("start_um_gestartet_at"):
            continue
        if x.get("auto_plan") is True and not x.get("auto_bestaetigt_at"):
            continue
        t = _ap_ts(x.get("start_um"))
        if t is None or not (jetzt < t <= jetzt + timedelta(seconds=TAB_NEXT_START_S)):
            continue
        out.add(t.astimezone(timezone.utc).isoformat().replace("+00:00", "Z"))
    return sorted(out)[:20]


@app.route("/code/tab-stand/<pc>", methods=["GET"])
def code_tab_stand(pc):
    """GET (X-Code-Token wie /code/stand) → {ok, origin, tab_build, tab_gleich, tab_bw, tab_at, riegel, …, next_start_um}. Nur Lesen."""
    if not _code_zugang():
        return jsonify({"ok": False, "msg": "kein gültiger Schlüssel"}), 403
    pc = str(pc or "").strip().lower()
    if not re.fullmatch(r"pc-[a-z0-9]{4,12}", pc):
        return jsonify({"ok": False, "msg": "pc ungültig"}), 400
    try:
        with open(os.path.join(_CODE_WURZEL, "mt5-copier", "VERSION"), encoding="utf-8") as f:
            origin = f.read().strip()
    except OSError:
        origin = None
    jetzt = datetime.now(timezone.utc)
    try:
        rows = sb_select("mt5_live", {"select": "updated_at,user_id:status->>user_id,tab_build:status->>tab_build,"
                                                "tab_gleich:status->>tab_gleich,tab_bw:status->tab_bw",
                                      "pc_name": f"eq.{pc}", "order": "updated_at.desc", "limit": "20"}) or []
        r0 = rows[0] if rows else {}
        uids = sorted({str(r.get("user_id")) for r in rows if r.get("user_id")})
        sig = sb_select("order_signale", {"select": "id", "status": "eq.laeuft", "pc": f"eq.{pc}", "limit": "5"}) or []
        plaene = []
        if uids:
            plaene = sb_select("trade_plans", {"select": "status,start_um,start_um_gestartet_at,auto_plan,auto_bestaetigt_at,route,master_account_id,"
                                                         "hedge_status:mt5_baseline->hedge->>status,hedge_pc:mt5_baseline->hedge->>pc",
                                               "user_id": "in.(" + ",".join(uids) + ")", "status": "in.(planned,open)",
                                               # nur bis jetzt + 10 min, jüngste zuerst (Hinweis S2: sonst Folgetage im Limit, ein frischer Claim fehlt)
                                               # status.eq.open (S9 02.11.2026): Ein offener Plan, der mehr als 10 min vor start_um begann, fehlte sonst (Lotse-Zahl, echo_logins)
                                               "or": f"(start_um.is.null,start_um.lte.{(jetzt + timedelta(minutes=10)).isoformat()},status.eq.open)",
                                               "order": "start_um.desc.nullslast", "limit": "300"}) or []
        riegel = tab_stand_riegel(sig, plaene, pc, jetzt)
        # FS1 (10.11.2026): offene Trades der IDs dieses PCs + offene Pläne, deren Hedge dieser PC hält — das Panel lädt im Sofort-Weg (Puls meldete
        # tab_nicht_erreichbar) nur bei 0 neu. Ohne IDs unbekannt (None = Panel lädt nicht neu).
        offen_n = None
        if uids:
            try:   # Prüfer FS1 (SOLLTE 2/3): eigene Abfragen, eigenes try — Fehler kosten den Tab-Stand nie, offen_n bleibt dann None (= nicht neu laden)
                offene = sb_select("trade_plans", {"select": "id,status", "status": "eq.open", "user_id": "in.(" + ",".join(uids) + ")", "limit": "50"}) or []
                hedge_hier = sb_select("trade_plans", {"select": "id", "status": "in.(open,review)", "mt5_baseline->hedge->>pc": f"eq.{pc}",
                                                       "mt5_baseline->hedge->>status": "in.(offen,oeffnet,schliesst,unklar)", "limit": "20"}) or []
                offen_n = tab_stand_offen_n(offene, hedge_hier)
            except Exception as e:
                print(f"[tab-stand] {pc}: offene Trades nicht lesbar ({type(e).__name__})", flush=True)
        # EA-SELBSTHEILUNG IM PANEL (30.10.2026, Befund ECHO-AUSSETZER: Jacob …2655 Lese-EA eingefroren, offener Echo-Plan, Snapshot ohne
        # Position → der Copier wusste nicht, dass die Instanz gebraucht wird): Master-Logins OFFENER Echo-Pläne (mt5/mt5v2) der IDs dieses PCs
        echo_ids = sorted({str(x.get("master_account_id")) for x in plaene
                           if str(x.get("status")) == "open" and str(x.get("route") or "") in ("mt5", "mt5v2") and x.get("master_account_id")})
        echo_logins = sorted({str(a.get("external_id") or "").strip() for a in (sb_select("accounts", {"select": "external_id",
                              "id": "in.(" + ",".join(echo_ids) + ")"}) or [])} - {""}) if echo_ids else []
        # nur Logins, deren jüngste Copier-Zeile von DIESEM PC kommt (Prüfer S2 30.10.2026: ein Login kann auf zwei PCs eingetragen sein —
        # geheilt wird nur dort, wo er zuletzt lief, nie ein zweites Terminal)
        if echo_logins:
            echo_logins = sorted(lg for lg, z in lt_echo_live_wahl(sb_select("mt5_live", {"select": "master_login,pc_name,updated_at",
                                 "master_login": "in.(" + ",".join(echo_logins) + ")"}) or []).items() if str(z.get("pc_name") or "") == pc)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Stand nicht lesbar: {type(e).__name__}"}), 503
    if request.headers.get("User-Agent") != "prophos-agent":   # der Lotse-Agent fragt je Eingabe: Das darf kein totes Panel als „an“ ausgeben (S9 02.11.2026)
        _panel_herz[pc] = time.time()   # Herzschlag des Panels (PANEL-HERZSCHLAG, 30.10.2026)
    spur = (request.args.get("panel") or "").strip()[:200]
    if spur and _tab_stand_spur.get(pc) != spur:
        _tab_stand_spur[pc] = spur
        print(f"[tab-stand] {pc}: {spur}", flush=True)
    if request.headers.get("User-Agent") != "prophos-agent":   # der Lotse-Agent schickt keine Spur, sonst wäre der Grund bei jeder Eingabe leer
        tab_nl_merken(_tab_nl_stand, pc, spur, (request.args.get("ergebnis") or "").strip()[:300], request.args.get("ergebnis_at"), time.time())
    try:   # DR1 (05.11.2026): täglicher Neustart — Fehler nie den Tab-Stand kosten lassen, dann eben „aus“
        tn = pc_neustart_sicht((_puls_heim_regel() or {}).get("pc_neustart"), pc, jetzt, _pc_neustart_laden(uids, sig, jetzt, pc))
    except Exception as e:
        tn = {"an": False, "grund": f"nicht lesbar ({type(e).__name__})"}
    return jsonify({"ok": True, "origin": origin, "tab_build": r0.get("tab_build"), "tab_gleich": r0.get("tab_gleich"),
                    "tab_bw": r0.get("tab_bw"), "tab_at": r0.get("updated_at"), "riegel": riegel, "echo_logins": echo_logins,
                    "tages_neustart": tn, "offen_n": offen_n,
                    "next_start_um": tab_stand_next_starts(plaene, jetzt),   # F-B (11.11.2026): Panel prüft den Tab 2–3 min vor jedem Start
                    **lotse_plan_stand(sig, plaene, uids, pc, jetzt),
                    "auftrag": tab_auftrag_offen(_tab_auftrag.get(pc), time.time())})


@app.route("/reader-kurs", methods=["POST", "OPTIONS"])
def reader_kurs_schreiben():
    """POST vom reader-server (Header X-Reader-Token) → tv_kurse + tv_kurs_1m (Upsert, idempotent)."""
    if request.method == "OPTIONS":
        return "", 200
    wer = reader_feed_token_pruefen(request.headers.get("X-Reader-Token") or "")
    if not wer:
        return jsonify({"ok": False, "msg": "Schlüssel ungültig"}), 401
    if (request.content_length or 0) > READER_FEED_MAX:
        return jsonify({"ok": False, "msg": "zu groß"}), 413
    # Supabase-Bremse offen (01.10.2026, AUSFALL-BREMSE): sofort 503 + Retry-After statt 2 × 12 s Hänger je Paket; der Reader wartet
    # dann länger (feed_pause). Der Drossel-Merker bleibt unberührt, das nächste Paket geht vollständig raus.
    _rest = sb_bremse_rest_s()
    if _rest > 0:
        return jsonify({"ok": False, "msg": "Datenbank gestört — später"}), 503, {"Retry-After": str(max(SB_BREMSE_HALB_S, int(_rest)))}
    kurse, kerzen = reader_feed_zeilen(wer[1], request.get_json(silent=True), datetime.now(timezone.utc).isoformat())
    jetzt = time.time()
    with _reader_feed_lock:   # Drossel (01.10.2026, s. reader_feed_drosseln)
        kurse, kerzen, neu = reader_feed_drosseln(wer[1], kurse, kerzen, _reader_feed_merk, jetzt)
    try:
        if kurse:
            sb_upsert("tv_kurse", kurse)
        if kerzen:
            sb_upsert("tv_kurs_1m", kerzen)
    except SupabaseGesperrt as e:
        return jsonify({"ok": False, "msg": "Datenbank gestört — später"}), 503, {"Retry-After": str(max(SB_BREMSE_HALB_S, int(e.rest_s)))}
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht speicherbar ({type(e).__name__})"}), 502
    with _reader_feed_lock:
        _reader_feed_merk.update(neu)
        if len(_reader_feed_merk) > 2000:   # alte Minuten wegräumen (10 min)
            for key in [k for k, v in _reader_feed_merk.items() if jetzt - v[1] > 600]:
                _reader_feed_merk.pop(key, None)
    return jsonify({"ok": True, "kurse": len(kurse), "kerzen": len(kerzen)})

# ══ TV-KONTEN AUS DEM KONTO-UMSCHALTER (29.10.2026, Finn 03:10: „Konten automatisch anlegen über das Konto-Dropdown in TradingView — fast
# noch besser als Mail"). Der Puls-Chrome-Reader (Userscript ≥ 0.9.13) liest die Einträge der Tradovate-Konto-Liste, sobald sie ohnehin offen
# ist (Puls-Kontowechsel oder Hand — nie ein eigener Klick, kein Eingriff in Order-Pfade), der reader-server schickt die Namen hierher
# (POST /reader/tv-konten, Schlüssel uid.pc.sig wie /reader-kurs → user_id + PC aus dem Schlüssel, nie aus dem Body). Tabelle tv_konten
# (sql/2026-10-29_tv_konten.sql, nur Service-Key): je (user_id, name) zuerst/zuletzt gesehen. GET /admin/tv-konten (Gate wie /admin/konto-mails,
# HT-Sicht) liefert die Liste mit in_prophos (accounts.external_id bzw. Name, Apex-Form PA-APEX-685010-01 → PAAPEX6850100000001) — der
# Reiter „Konten aus Mail & TV" (S7) zeigt neue Namen als Zeile. Schnittstelle fest (Master 29.10.2026). ══
TV_KONTEN_MAX = 32 * 1024
TV_KONTEN_NAME_RE = re.compile(r"^[A-Z0-9][A-Z0-9_-]{5,39}$")
TV_KONTEN_QUELLEN = ("dropdown", "umschalter")


def tv_konto_normal(roh):
    """REIN RECHNEND (testbar): Kontoname aus TradingView → Schreibweise in Prophos. Apex „PA-APEX-685010-01" → „PAAPEX6850100000001",
    „APEX-641699-21" → „APEX6416990000021"; alles andere nur groß und getrimmt."""
    k = str(roh or "").strip().upper()
    m = re.fullmatch(r"(PA-)?APEX-([0-9]{5,})-([0-9]{1,3})", k)
    if m:
        return ("PAAPEX" if m.group(1) else "APEX") + m.group(2) + m.group(3).zfill(7)
    return k


def tv_konten_zeilen(body, uid, pc, jetzt_iso):
    """REIN RECHNEND (testbar): Body {konten:[{name, quelle}]} → Upsert-Zeilen [{user_id, name, pc_id, quelle, zuletzt_at}] — Namen groß,
    nur Kennungs-Form (TV_KONTEN_NAME_RE, gekürzte „…"-Namen fallen raus), ohne Dubletten, höchstens 200. zuerst_at schickt niemand mit:
    die Tabelle setzt sie beim Insert, der Upsert (merge-duplicates) lässt sie stehen."""
    aus, gesehen = [], set()
    liste = (body or {}).get("konten") if isinstance(body, dict) else None
    for k in (liste if isinstance(liste, list) else [])[:200]:
        if not isinstance(k, dict):
            continue
        name = tv_konto_normal(k.get("name"))
        if not TV_KONTEN_NAME_RE.fullmatch(name) or name in gesehen:
            continue
        quelle = str(k.get("quelle") or "dropdown")
        gesehen.add(name)
        aus.append({"user_id": uid, "name": name, "pc_id": pc, "quelle": quelle if quelle in TV_KONTEN_QUELLEN else "dropdown", "zuletzt_at": jetzt_iso})
        if len(aus) >= 200:   # gleiche Grenze wie der Reader-Merker (Pruefer-Hinweis 2)
            break
    return aus


def tv_konto_in_prophos(name, konten, uid):
    """REIN RECHNEND (testbar): steht der TV-Kontoname bei dieser ID in Prophos? → Konto-Zeile oder None. Beide Seiten normiert
    (tv_konto_normal, ohne Sonderzeichen): external_id GLEICH oder ein ganzes Wort des Kontonamens gleich — nie Teilstring (Prüfer 29.10.2026:
    Apex-Eval „APEX6843320000001" steckt in „PAAPEX6843320000001" des PA-Kontos und hätte als „in Prophos" gegolten)."""
    norm = lambda x: re.sub(r"[^A-Z0-9]", "", tv_konto_normal(x))
    key = norm(name)
    if len(key) < 6:
        return None
    for a in konten or []:
        if str(a.get("user_id")) != str(uid):
            continue
        if norm(a.get("external_id")) == key or any(norm(w) == key for w in re.findall(r"[A-Za-z0-9_-]{6,}", str(a.get("name") or ""))):
            return a
    return None


@app.route("/reader/tv-konten", methods=["POST", "OPTIONS"])
def reader_tv_konten_schreiben():
    """POST vom reader-server (Header X-Reader-Token) {pc_id, konten:[{name, quelle}]} → Upsert tv_konten (user_id + PC aus dem Schlüssel).
    → {ok, n}. Wirft nie nach außen."""
    if request.method == "OPTIONS":
        return "", 200
    wer = reader_feed_token_pruefen(request.headers.get("X-Reader-Token") or "")
    if not wer:
        return jsonify({"ok": False, "msg": "Schlüssel ungültig"}), 401
    if request.content_length is None:   # chunked ohne Längenangabe → kein Deckel prüfbar (Prüfer S2 29.10.2026, wie /mail/eingang)
        return jsonify({"ok": False, "msg": "Content-Length fehlt"}), 411
    if request.content_length > TV_KONTEN_MAX:
        return jsonify({"ok": False, "msg": "zu groß"}), 413
    _rest = sb_bremse_rest_s()
    if _rest > 0:
        return jsonify({"ok": False, "msg": "Datenbank gestört — später"}), 503, {"Retry-After": str(max(SB_BREMSE_HALB_S, int(_rest)))}
    zeilen = tv_konten_zeilen(request.get_json(silent=True), wer[0], wer[1], datetime.now(timezone.utc).isoformat())
    if not zeilen:
        return jsonify({"ok": True, "n": 0})
    try:
        r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/tv_konten", params={"on_conflict": "user_id,name"}, json=zeilen,
                        headers=_sb_headers("resolution=merge-duplicates,return=minimal"))
        _sb_pruefen(r)
    except SupabaseGesperrt as e:
        return jsonify({"ok": False, "msg": "Datenbank gestört — später"}), 503, {"Retry-After": str(max(SB_BREMSE_HALB_S, int(e.rest_s)))}
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht speicherbar ({type(e).__name__}) — Tabelle tv_konten da? (sql/2026-10-29_tv_konten.sql)"}), 502
    return jsonify({"ok": True, "n": len(zeilen)})


def tvk_wartend(auftraege, pc_user, liste):
    """REIN RECHNEND (testbar, L7 05.11.2026 — Mail-Aufträge seit 29.10. nie gelaufen, weil die Weiche nur pc-c19p2l freigab): offene Mail-Aufträge,
    deren ID keinen freigegebenen PC hat → [{user_id, firma, faellig_at}]. pc_user = {pc: user_id} (PCs der letzten 24 h), liste = Weiche
    (tv_konten_pcs). „alle" → nichts wartet. Eine ID ohne PC der letzten 24 h wartet ebenfalls (kein Tab, der abholen könnte)."""
    frei = {str(x).lower() for x in (liste or ())}
    if "alle" in frei:
        return []
    mit_pc = {str(u) for pc, u in (pc_user or {}).items() if str(pc).lower() in frei and u}
    return [{"user_id": str(a.get("user_id")), "firma": a.get("firma"), "faellig_at": a.get("faellig_at")} for a in auftraege or ()
            if a.get("status") == "offen" and a.get("art") == "mail" and str(a.get("user_id")) not in mit_pc]


@app.route("/admin/tv-konten-pcs", methods=["GET", "POST", "OPTIONS"])
def admin_tv_konten_pcs():
    """Weiche „TV-Konten lesen auf" (Finn 29.10.2026). GET → {ok, pcs, quelle, bekannte:[{pc, name}]} (PCs der letzten 24 h aus mt5_live, Namen aus
    pc_namen; nur Hermann-Technologies-PCs). POST {pcs:[pc-… | "alle"]} → auto_plan_regeln.regeln.tv_konten_pcs. Nur Admin (wie die anderen
    Schalter, _ap_zugang)."""
    if request.method == "OPTIONS":
        return "", 200
    admin, uid, reg, err = _ap_zugang()
    if err:
        return err
    if not admin:
        return jsonify({"ok": False, "msg": "Nur für Admins"}), 403
    if request.method == "POST":
        body = request.get_json(silent=True) or {}
        roh = body.get("pcs")
        if not isinstance(roh, list) or len(roh) > 60:
            return jsonify({"ok": False, "msg": "pcs = Liste von PC-Kennungen (pc-…) oder [\"alle\"]"}), 400
        neu = sorted({str(x).strip().lower() for x in roh if TVK_PCS_MUSTER.fullmatch(str(x).strip().lower())})
        regeln = dict((reg or {}).get("regeln") or {})
        regeln["tv_konten_pcs"] = neu
        try:
            sb_update("auto_plan_regeln", {"id": "eq.1"}, {"regeln": regeln, "updated_at": datetime.now(timezone.utc).isoformat()})
        except Exception as e:
            return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
        _tvk_pcs_merk.update(s=0.0, liste=None)
        print(f"[tv-konten] Weiche: {', '.join(neu) or 'kein PC'} ({uid})", flush=True)
    liste, quelle = _tv_konten_pcs()
    bekannte = []
    try:
        ab = (datetime.now(timezone.utc) - timedelta(hours=24)).isoformat()
        live = sb_select("mt5_live", {"select": "pc_name,user_id:status->>user_id", "updated_at": f"gte.{ab}", "order": "updated_at.desc", "limit": "1000"}) or []
        _n, aus = _ap_namen()
        pcs = {}
        for z in live:
            pc, u = str(z.get("pc_name") or ""), str(z.get("user_id") or "")
            if re.fullmatch(r"pc-[a-z0-9]{4,12}", pc) and pc not in pcs:
                pcs[pc] = u
        namen = {k: v.get("name") for k, v in (_pc_namen_daten() or {}).items() if v}
        bekannte = [{"pc": pc, "name": namen.get(pc) or pc} for pc, u in pcs.items() if u and u not in aus and not _alarm_fremd_verwaltet(u)]
        bekannte.sort(key=lambda x: str(x["name"]).lower())
    except Exception as e:
        pcs, aus = None, set()
        print(f"[tv-konten] PC-Liste: {type(e).__name__}", flush=True)
    # L7 (05.11.2026): offene Mail-Aufträge ohne freigegebenen PC ihrer ID — die Zeile im Admin zeigt sie, damit sie nicht still liegen bleiben
    wartend = None
    try:
        if pcs is not None:
            offen = sb_select("tv_konten_auftrag", {"select": "user_id,firma,art,status,faellig_at", "status": "eq.offen", "art": "eq.mail",
                                                    "order": "faellig_at.asc", "limit": "200"}) or []
            pn = _ap_namen()[0]
            wartend = [dict(w, person=pn.get(w["user_id"]) or w["user_id"][:8]) for w in tvk_wartend(offen, pcs, liste)
                       if w["user_id"] not in aus and not _alarm_fremd_verwaltet(w["user_id"])]   # wie bekannte: ausgeblendete IDs und Emins Gruppe nie
    except Exception as e:
        print(f"[tv-konten] wartende Aufträge: {type(e).__name__}", flush=True)
    return jsonify({"ok": True, "pcs": liste, "quelle": quelle, "bekannte": bekannte, "wartend": wartend})


@app.route("/admin/tv-konten", methods=["GET", "OPTIONS"])
def admin_tv_konten():
    """GET /admin/tv-konten[?tage=30] → {ok, konten:[{user_id, person, name, pc_id, quelle, zuerst_at, zuletzt_at, ignoriert_at, angelegt_account_id,
    in_prophos, konto_id, konto_name}],
    n_neu, n_drin}. Gate wie /admin/mail (_admin_mail_auth), HT-Sicht. Nur lesen. Feld „konten" = Vertrag mit dem Reiter „Konten aus Mail & TV"
    (S7, eaa9a07a liest t.konten)."""
    if request.method == "OPTIONS":
        return "", 200
    err = _admin_mail_auth()
    if err:
        return err
    try:
        disp, sicht = _admin_mail_sicht()
    except Exception as e:
        return jsonify({"ok": False, "msg": f"IDs nicht lesbar: {str(e)[:120]}"}), 502
    try:
        tage = max(1, min(365, int(request.args.get("tage") or 30)))
    except ValueError:
        tage = 30
    if not sicht:
        return jsonify({"ok": True, "konten": [], "n_neu": 0, "n_drin": 0, "tage": tage})
    seit = (datetime.now(timezone.utc) - timedelta(days=tage)).isoformat()
    ids = ",".join(sorted(sicht))
    try:
        rows = _sb_all("tv_konten", {"select": "user_id,name,pc_id,quelle,zuerst_at,zuletzt_at,ignoriert_at,angelegt_account_id", "user_id": f"in.({ids})", "zuletzt_at": f"gte.{seit}",
                                     "order": "zuletzt_at.desc"}) or []
        konten = _sb_all("accounts", {"select": "id,user_id,name,firm,external_id", "user_id": f"in.({ids})"}) or []
    except Exception as e:
        return jsonify({"ok": False, "msg": f"tv_konten nicht lesbar ({str(e)[:100]}) — Tabelle da? (sql/2026-10-29_tv_konten.sql)"}), 503
    zeilen, n_neu, n_drin = [], 0, 0
    for r in rows:
        uid = str(r.get("user_id") or "")
        a = tv_konto_in_prophos(r.get("name"), konten, uid)
        z = dict(r, user_id=uid, person=disp.get(uid, uid[:8]), in_prophos=bool(a), konto_id=(a or {}).get("id"), konto_name=(a or {}).get("name"))
        n_drin += bool(a); n_neu += not a
        zeilen.append(z)
    return jsonify({"ok": True, "konten": zeilen, "n_neu": n_neu, "n_drin": n_drin, "tage": tage})


# ── AUFTRÄGE „Konto-Liste lesen" (Finn 29.10.2026 03:25: „Jedes Mal, wenn eine Konto-Mail reinkommt, wird im Zufallsintervall 5 Minuten bis
# 3 Stunden einmal ganz kurz in den jeweiligen Trading-Account über TradingView eingeloggt und alle neuen externen IDs gelesen"). Nur Firmen,
# deren Konten im TradingView-Konto-Umschalter (Tradovate) stehen — Topstep (TopstepX), FundedNext/FundingPips/FTMO (MT5) nie. Je ID × Firma
# höchstens EIN offener Auftrag (Index tv_konten_auftrag_offen_uq): weitere Kauf-Mails bündeln sich, das frühere faellig_at bleibt.
# Finn 29.10.2026 03:58: der eigentliche Auslöser ist die KAUFQUITTUNG — „ready" kommt bei Tradeify nur bei ~54 % der Käufe, „Your Tradeify
# order is confirmed" (Select $150k) bei jedem; Level-Up-Produkte (Payout-Programm) zählen nicht (Text „Level Up"). Topstep (TopstepX),
# FundedNext/FundingPips/FTMO (MT5) stehen NICHT im TradingView-Konto-Umschalter — für sie gibt es nichts zu lesen, ihre Konto-Mails tragen die
# Kennung ohnehin selbst (Reiter „Konten aus Mail").
TV_KONTO_MAIL_MUSTER = (
    ("Tradeify", r"tradeify", r"Tradeify order is confirmed|Tradovate account is (ready|active)|account reset is confirmed|You.re funded"),
    ("Apex Trader", r"apextrader", r"Payment Receipt|Performance Account is active|Activation Steps|being activated"),
)
TV_KONTO_MAIL_NICHT = re.compile(r"Level\s*-?\s*Up", re.I)   # Tradeify-Quittung eines Level-Up-Produkts → kein Konto im Dropdown
TV_KONTEN_FIRMEN = ("Tradeify", "Apex Trader", "Lucid Trading", "MyFundedFutures", "FundedNext Futures")   # Tages-Fallback: Tradovate-Firmen
TV_AUFTRAG_MIN_S, TV_AUFTRAG_MAX_S = 300, 3 * 3600
TV_AUFTRAG_LAUF_MAX_S = 20 * 60          # „laeuft" länger als das (Tab neu geladen, PC aus) → wieder offen
TV_TAEGLICH_MIN_S, TV_TAEGLICH_MAX_S = 20 * 3600, 28 * 3600
# TAGES-FALLBACK AUS (Finn 04.11.2026: „Sicherheitsnetz: zusätzlich liest Puls einmal am Tag je Firma, auch ohne Mail — ne, das nicht."):
# False → pc_tv_konten_auftrag legt keine Aufträge art 'taeglich' mehr an und gibt keine mehr aus; noch offene werden beim nächsten Abholen
# als „fehler" (verworfen) geschlossen — sie hielten sonst den eindeutigen Index (je ID × Firma ein offener Auftrag) und blockierten die
# Mail-Aufträge derselben Firma. Mail-Aufträge und das passive Mitlesen bleiben. True = wieder wie bis 04.11.2026.
TV_KONTEN_TAEGLICH = False
TV_TAEGLICH_VERWORFEN = {"msg": "Tages-Auftrag verworfen — Tages-Fallback abgeschaltet (Finn 04.11.2026), nur noch Mail-Aufträge", "code": "taeglich_aus"}
# PROBELAUF-WEICHE (Master 29.10.2026: Klick-Pfad erst auf EINEM PC): Railway-Variable TV_KONTEN_PCS = Komma-Liste der PC-Kennungen, die
# Aufträge bekommen; „alle" = jeder Puls-PC. Nicht gesetzt → kein PC bekommt einen Auftrag (Aufträge sammeln sich nur an). Sicherer Standard.
# WEICHE IN DER DB (Finn 29.10.2026: „Ich möchte nicht immer Railway-Variablen hinzufügen"): auto_plan_regeln.regeln.tv_konten_pcs = Liste
# der PC-Kennungen bzw. ["alle"], gesetzt im Admin → Konten aus Mail & TV (POST /admin/tv-konten-pcs). Fehlt der Schlüssel, gilt wie bisher die
# Railway-Variable TV_KONTEN_PCS (Fallback). 60 s gemerkt.
TVK_PCS_MUSTER = re.compile(r"pc-[a-z0-9]{4,12}|alle")
_tvk_pcs_merk = {"s": 0.0, "liste": None, "quelle": ""}


def tv_konten_pcs_aus(regeln, env):
    """REIN RECHNEND (testbar): (liste, quelle) — quelle 'db' (Schlüssel in regeln, auch leere Liste = keiner), 'railway' (Variable) oder 'aus'."""
    if isinstance(regeln, dict) and isinstance(regeln.get("tv_konten_pcs"), list):
        return sorted({str(x).strip().lower() for x in regeln["tv_konten_pcs"] if TVK_PCS_MUSTER.fullmatch(str(x).strip().lower())}), "db"
    liste = sorted({x.strip().lower() for x in str(env or "").split(",") if x.strip()})
    return liste, ("railway" if liste else "aus")


def _tv_konten_pcs(jetzt=None):
    jetzt = time.time() if jetzt is None else jetzt
    if _tvk_pcs_merk["liste"] is not None and jetzt - _tvk_pcs_merk["s"] < 60:
        return _tvk_pcs_merk["liste"], _tvk_pcs_merk["quelle"]
    try:
        regeln = ((sb_select("auto_plan_regeln", {"select": "regeln", "id": "eq.1"}) or [{}])[0].get("regeln")) or {}
    except Exception:
        regeln = None   # DB nicht lesbar → Railway-Variable (wie vor dieser Weiche)
    liste, quelle = tv_konten_pcs_aus(regeln, os.environ.get("TV_KONTEN_PCS", ""))
    _tvk_pcs_merk.update(s=jetzt, liste=liste, quelle=quelle)
    return liste, quelle


def tv_konten_pc_frei(pc, roh=None):
    """REIN RECHNEND (testbar) mit roh (Komma-Text wie die Railway-Variable); ohne roh aus der DB-Weiche (Fallback Railway-Variable)."""
    if roh is not None:
        liste = {x.strip().lower() for x in str(roh or "").split(",") if x.strip()}
    else:
        liste = set(_tv_konten_pcs()[0])
    return "alle" in liste or (bool(pc) and str(pc).strip().lower() in liste)


TV_FALLBACK_PRUEF_S = 30 * 60           # Tages-Fallback je ID höchstens alle 30 min prüfen (Prüfer S2: GET kostet sonst 4+ DB-Zugriffe je Abfrage)
_tv_fallback_merk = {}                  # uid → letzte Prüfung (time.time())


def tv_konto_mail_firma(von, betreff, text=""):
    """REIN RECHNEND (testbar): Kaufquittung/Konto-/Reset-Mail einer TradingView-Firma → Firmenname (wie accounts.firm) oder None.
    Tradeify-Quittung eines Level-Up-Produkts (Text „Level Up") → None."""
    v, b = str(von or ""), str(betreff or "")
    for firma, von_re, bet_re in TV_KONTO_MAIL_MUSTER:
        if re.search(von_re, v, re.I) and re.search(bet_re, b, re.I):
            if firma == "Tradeify" and re.search(r"order is confirmed", b, re.I) and TV_KONTO_MAIL_NICHT.search(str(text or "")[:20000]):
                return None
            return firma
    return None


def tv_auftrag_verzug_s(r=None):
    """REIN RECHNEND (testbar): Wartezeit bis zum Lesen in Sekunden, gestreut zwischen 5 min und 3 h (Jitter-Regel: nie fest), kurze häufiger
    (r^1.6) — Finn will die Konten bald sehen, nur nicht im Takt aller PCs gleichzeitig."""
    r = random.random() if r is None else min(1.0, max(0.0, float(r)))
    return int(TV_AUFTRAG_MIN_S + (TV_AUFTRAG_MAX_S - TV_AUFTRAG_MIN_S) * (r ** 1.6))


def tv_konten_mail_auftraege(zeilen, uid):
    """Nach dem Insert in /mail/eingang: je Firma mit Kauf-Mail im Stapel EIN Auftrag (falls noch keiner offen ist). Wirft nie."""
    try:
        je_firma = {}
        for z in zeilen or []:
            f = tv_konto_mail_firma(z.get("von"), z.get("betreff"), z.get("text"))
            if f and f not in je_firma:
                je_firma[f] = z
        for firma, z in je_firma.items():
            offen = sb_select("tv_konten_auftrag", {"select": "id,art,status", "user_id": f"eq.{uid}", "firma": f"eq.{firma}", "status": "in.(offen,laeuft)", "limit": "1"}) or []
            if offen and not TV_KONTEN_TAEGLICH and offen[0].get("art") == "taeglich" and offen[0].get("status") == "offen":
                # Tages-Fallback aus (04.11.2026, Fremd-Review): ein noch offener Tages-Auftrag würde verworfen — die Kauf-Mail darf nicht an ihm
                # hängen bleiben. Ihn hier schließen (nur noch offen → fehler, verworfen) und den Mail-Auftrag anlegen.
                sb_update("tv_konten_auftrag", {"id": f"eq.{offen[0]['id']}", "status": "eq.offen"},
                          {"status": "fehler", "erledigt_at": datetime.now(timezone.utc).isoformat(), "ergebnis": TV_TAEGLICH_VERWORFEN})
                offen = []
            if offen:
                continue
            faellig = (datetime.now(timezone.utc) + timedelta(seconds=tv_auftrag_verzug_s())).isoformat()
            try:
                sb_insert("tv_konten_auftrag", {"user_id": uid, "firma": firma, "art": "mail", "quelle_mail": str(z.get("gmail_msg_id") or "")[:80] or None, "faellig_at": faellig})
                print(f"[tv-konten] Auftrag {firma} für {str(uid)[:8]} fällig {faellig[:16]} (Mail: {str(z.get('betreff') or '')[:60]})", flush=True)
            except Exception as e:   # zweiter Stapel gleichzeitig → eindeutiger Index greift, harmlos
                print(f"[tv-konten] Auftrag {firma} nicht angelegt: {type(e).__name__}: {str(e)[:120]}", flush=True)
    except Exception as e:
        print(f"[tv-konten] ⚠️ Mail-Aufträge: {type(e).__name__}: {e}", flush=True)


TV_WIEDER_MIN_S, TV_WIEDER_MAX_S = 30 * 60, 60 * 60


def tv_auftrag_nach_fehler(versuche, jetzt, r, ergebnis):
    """REIN RECHNEND (testbar): Fehlversuch → Update-Body. Erster Fehler: wieder „offen", fällig in 30–60 min (r 0..1), versuche + 1;
    jeder weitere: „fehler" mit Grund (kein Dauer-Retry)."""
    if int(versuche or 0) < 1:
        warte = int(TV_WIEDER_MIN_S + (TV_WIEDER_MAX_S - TV_WIEDER_MIN_S) * min(1.0, max(0.0, float(r))))
        return {"status": "offen", "laeuft_at": None, "versuche": int(versuche or 0) + 1,
                "faellig_at": (jetzt + timedelta(seconds=warte)).isoformat(), "ergebnis": dict(ergebnis or {}, wiederholung_in_s=warte)}
    return {"status": "fehler", "erledigt_at": jetzt.isoformat(), "versuche": int(versuche or 0) + 1, "ergebnis": ergebnis}


def tv_taeglich_faellig(letzte_iso, jetzt, streu_r):
    """REIN RECHNEND (testbar): braucht diese ID × Firma einen Tages-Auftrag? letzte_iso = letzter Auftrag (egal welcher Stand) oder None;
    Abstand gestreut 20–28 h (streu_r 0..1, je Firma fest aus der user_id+Firma gewürfelt, damit nicht alle PCs gleich ticken)."""
    if not letzte_iso:
        return True
    try:
        t = datetime.fromisoformat(str(letzte_iso).replace("Z", "+00:00"))
    except ValueError:
        return True
    return (jetzt - t).total_seconds() >= TV_TAEGLICH_MIN_S + (TV_TAEGLICH_MAX_S - TV_TAEGLICH_MIN_S) * min(1.0, max(0.0, streu_r))


@app.route("/pc/tv-konten-auftrag", methods=["GET", "OPTIONS"])
def pc_tv_konten_auftrag():
    """PC-Tab der ID (sb-token): → {ok, auftrag: {id, firma, art, ext} | null}. Holt den ältesten fälligen Auftrag und setzt ihn auf „laeuft"
    (atomar: nur offen → laeuft). Ohne Mail-Auftrag: je Tradovate-Firma mit Konten dieser ID höchstens 1× in 20–28 h ein Tages-Auftrag —
    seit 04.11.2026 aus (TV_KONTEN_TAEGLICH = False, Finn): nur noch Mail-Aufträge, offene Tages-Aufträge werden verworfen.
    ext = External ID eines Kontos dieser Firma (der Puls braucht sie für den Login-Weg). Aufräumen: „laeuft" > 20 min → wieder offen."""
    if request.method == "OPTIONS":
        return "", 200
    uid, _mail, err = _login_uid_mail()
    if err:
        return err
    if not tv_konten_pc_frei(request.args.get("pc")):
        return jsonify({"ok": True, "auftrag": None, "pc_frei": False})   # Probelauf-Weiche: dieser PC liest (noch) nicht
    jetzt = datetime.now(timezone.utc)
    try:
        alt = (jetzt - timedelta(seconds=TV_AUFTRAG_LAUF_MAX_S)).isoformat()
        sb_update("tv_konten_auftrag", {"user_id": f"eq.{uid}", "status": "eq.laeuft", "laeuft_at": f"lt.{alt}"}, {"status": "offen", "laeuft_at": None})
        konten = _sb_all("accounts", {"select": "id,firm,external_id,created_at", "user_id": f"eq.{uid}", "order": "created_at.desc"}) or []
        firmen_mit = [f for f in TV_KONTEN_FIRMEN if any(a.get("firm") == f and a.get("external_id") for a in konten)]
        if time.time() - _tv_fallback_merk.get(uid, 0) < TV_FALLBACK_PRUEF_S:
            firmen_mit = []                     # gerade erst geprüft
        else:
            _tv_fallback_merk[uid] = time.time()
            if not TV_KONTEN_TAEGLICH:
                # Tages-Fallback aus (04.11.2026): offene Tages-Aufträge schließen (im selben 30-min-Takt wie früher das Anlegen, kein Zugriff je
                # Abfrage). „fehler" statt „erledigt": gelesen wurde nichts. Laufende dürfen zu Ende laufen. Fehler hier: Merker zurück, damit die
                # nächste Abfrage es wieder versucht, und Mail-Aufträge trotzdem ausgeben (Fremd-Review)
                try:
                    sb_update("tv_konten_auftrag", {"user_id": f"eq.{uid}", "art": "eq.taeglich", "status": "eq.offen"},
                              {"status": "fehler", "erledigt_at": jetzt.isoformat(), "ergebnis": TV_TAEGLICH_VERWORFEN})
                except Exception as e:
                    _tv_fallback_merk.pop(uid, None)
                    print(f"[tv-konten] ⚠️ Tages-Aufträge nicht verworfen: {type(e).__name__}: {str(e)[:120]}", flush=True)
        if not TV_KONTEN_TAEGLICH:
            firmen_mit = []                     # kein Tages-Auftrag mehr anlegen
        for f in firmen_mit:   # Tages-Fallback anlegen, wo nötig
            letzte = sb_select("tv_konten_auftrag", {"select": "created_at", "user_id": f"eq.{uid}", "firma": f"eq.{f}", "order": "created_at.desc", "limit": "1"}) or []
            streu = int(hashlib.sha256(f"{uid}|{f}".encode()).hexdigest()[:4], 16) / 65535
            if tv_taeglich_faellig((letzte[0] if letzte else {}).get("created_at"), jetzt, streu):
                try:
                    sb_insert("tv_konten_auftrag", {"user_id": uid, "firma": f, "art": "taeglich", "faellig_at": jetzt.isoformat()})
                except Exception:
                    pass   # offener Auftrag dieser Firma existiert schon (Index) — gut so
        faellig = sb_select("tv_konten_auftrag", dict({"select": "id,firma,art,faellig_at", "user_id": f"eq.{uid}", "status": "eq.offen",
                                                       "faellig_at": f"lte.{jetzt.isoformat()}", "order": "faellig_at.asc", "limit": "1"},
                                                      **({} if TV_KONTEN_TAEGLICH else {"art": "eq.mail"}))) or []   # Tages-Fallback aus: nie ausgeben
        if not faellig:
            return jsonify({"ok": True, "auftrag": None})
        a = faellig[0]
        got = sb_update("tv_konten_auftrag", {"id": f"eq.{a['id']}", "status": "eq.offen"}, {"status": "laeuft", "laeuft_at": jetzt.isoformat()}) or []
        if not got:
            return jsonify({"ok": True, "auftrag": None})   # anderer Tab war schneller
        # Bezugskonto für den Login-Weg: das jüngste NICHT archivierte Konto dieser Firma (Prüfer 29.10.2026: ein archiviertes/geblowtes
        # Konto ließe den Login-Weg ins Leere laufen); Archiv wie im Frontend (user_settings 'archive')
        try:
            _arch = ((sb_select("user_settings", {"select": "value", "user_id": f"eq.{uid}", "key": "eq.archive", "limit": "1"}) or [{}])[0].get("value")) or {}
        except Exception:
            _arch = {}
        _arch = _arch if isinstance(_arch, dict) else {}
        _lebt = [k for k in konten if k.get("firm") == a["firma"] and k.get("external_id") and not ((_arch.get(str(k.get("id"))) or {}).get("archived"))]
        ext = (_lebt[0] if _lebt else {}).get("external_id")
        if not ext:   # kein lebendes Konto dieser Firma → nichts zu lesen, Auftrag als Fehler (kein Puls-Lauf)
            sb_update("tv_konten_auftrag", {"id": f"eq.{a['id']}", "status": "eq.laeuft"},
                      {"status": "fehler", "erledigt_at": jetzt.isoformat(), "ergebnis": {"msg": "kein aktives Konto dieser Firma in Prophos"}})
            return jsonify({"ok": True, "auftrag": None})
        return jsonify({"ok": True, "auftrag": {"id": a["id"], "firma": a["firma"], "art": a["art"], "ext": ext}})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Aufträge nicht lesbar ({type(e).__name__}: {str(e)[:100]}) — Tabelle tv_konten_auftrag da?"}), 503


@app.route("/pc/tv-konten-auftrag/erledigt", methods=["POST", "OPTIONS"])
def pc_tv_konten_auftrag_erledigt():
    """PC-Tab der ID: {id, ok, konten:[name …], pc_id, msg} → Auftrag erledigt/fehler, Namen → tv_konten (Upsert, quelle 'dropdown')."""
    if request.method == "OPTIONS":
        return "", 200
    uid, _mail, err = _login_uid_mail()
    if err:
        return err
    b = request.get_json(silent=True) or {}
    aid = str(b.get("id") or "")
    if not re.fullmatch(r"[0-9a-f-]{36}", aid):
        return jsonify({"ok": False, "msg": "id ungültig"}), 400
    pc = str(b.get("pc_id") or "").strip()
    pc = pc if READER_KENNUNG_MUSTER.fullmatch(pc) else None
    jetzt = datetime.now(timezone.utc).isoformat()
    zeilen = tv_konten_zeilen({"konten": [{"name": n, "quelle": "dropdown"} for n in (b.get("konten") or []) if isinstance(n, str)]}, uid, pc, jetzt) if b.get("ok") else []
    try:
        if zeilen:
            r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/tv_konten", params={"on_conflict": "user_id,name"}, json=zeilen,
                            headers=_sb_headers("resolution=merge-duplicates,return=minimal"))
            _sb_pruefen(r)
        erg = {"n": len(zeilen), "msg": str(b.get("msg") or "")[:300], "code": str(b.get("code") or "")[:40], "pc_id": pc}
        # Spur + Fehlerfoto (Master/Finn 29.10.2026: „bei jedem Fehler Spur und Foto"): Bot-trail (≤ 2000 Zeichen) und fehlerbild-Pfad
        # (<pc>/<JJJJ-MM-TT>/<id>, Bucket puls-fehlerbilder) ins ergebnis — nur kurze Texte, Pfad nur in der bekannten Form
        tr = str(b.get("trail") or "")[-2000:]
        if tr:
            erg["trail"] = tr
        fb = str(b.get("fehlerbild") or "").strip()
        if PULS_FEHLERBILD_PRAEFIX_RE.fullmatch(fb):   # dasselbe Muster wie die Fehlerfoto-Route (S2 29.10.2026)
            erg["fehlerbild"] = fb
        sch = str(b.get("schritt") or "")[:40]
        if sch:
            erg["schritt"] = sch
        if b.get("ok"):
            body = {"status": "erledigt", "erledigt_at": jetzt, "ergebnis": erg}
        elif str(b.get("code") or "") == "belegt":
            # PC-Tab gibt zurück, weil inzwischen etwas läuft (Start, Puls, Polar) — kein Fehlversuch, in 5–15 min (gestreut) erneut
            body = {"status": "offen", "laeuft_at": None, "faellig_at": (datetime.now(timezone.utc) + timedelta(seconds=random.randint(300, 900))).isoformat(),
                    "ergebnis": erg}
        else:
            # Fehlversuch (Master 29.10.2026): höchstens EINMAL nach 30–60 min (gestreut) neu, dann „fehler" mit Grund — kein Dauer-Retry
            alt = (sb_select("tv_konten_auftrag", {"select": "versuche", "id": f"eq.{aid}", "user_id": f"eq.{uid}"}) or [{}])[0]
            body = tv_auftrag_nach_fehler(int(alt.get("versuche") or 0), datetime.now(timezone.utc), random.random(), erg)
        sb_update("tv_konten_auftrag", {"id": f"eq.{aid}", "user_id": f"eq.{uid}", "status": "eq.laeuft"}, body)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht speicherbar ({type(e).__name__})"}), 502
    return jsonify({"ok": True, "n": len(zeilen)})


@app.route("/tv-konten/mein", methods=["GET", "PATCH", "OPTIONS"])
def tv_konten_mein():
    """Eigene ID (eingeloggt, sb-token). GET[?tage=60] → {ok, konten:[{name, pc_id, quelle, zuerst_at, zuletzt_at, ignoriert_at, angelegt_account_id,
    in_prophos, konto_id, konto_name}]} — für den Kasten „Neue Konten aus TradingView · noch zu bestätigen" unter Accounts (S7).
    PATCH {name, ignoriert: true|false[, angelegt_account_id]} → setzt/leert ignoriert_at (bzw. merkt das angelegte Konto) für (eigene ID, name) → {ok, n}."""
    if request.method == "OPTIONS":
        return "", 200
    uid, _mail, err = _login_uid_mail()
    if err:
        return err
    if request.method == "PATCH":
        b = request.get_json(silent=True) or {}
        return _tv_konten_markieren(uid, b.get("name"), b.get("ignoriert"), b.get("angelegt_account_id"))
    try:
        tage = max(1, min(365, int(request.args.get("tage") or 60)))
    except ValueError:
        tage = 60
    seit = (datetime.now(timezone.utc) - timedelta(days=tage)).isoformat()
    try:
        rows = _sb_all("tv_konten", {"select": "name,pc_id,quelle,zuerst_at,zuletzt_at,ignoriert_at,angelegt_account_id", "user_id": f"eq.{uid}",
                                     "zuletzt_at": f"gte.{seit}", "order": "zuerst_at.desc"}) or []
        konten = _sb_all("accounts", {"select": "id,user_id,name,firm,external_id", "user_id": f"eq.{uid}"}) or []
    except Exception as e:
        return jsonify({"ok": False, "msg": f"tv_konten nicht lesbar ({str(e)[:100]})"}), 503
    aus = []
    for r in rows:
        a = tv_konto_in_prophos(r.get("name"), konten, uid)
        aus.append(dict(r, user_id=uid, in_prophos=bool(a), konto_id=(a or {}).get("id"), konto_name=(a or {}).get("name")))
    return jsonify({"ok": True, "konten": aus})


@app.route("/tv-konten/ignorieren", methods=["POST", "OPTIONS"])
def tv_konten_ignorieren():
    """POST {name[, ignoriert=true]} (eingeloggt, eigene ID) → wie PATCH /tv-konten/mein. Zweite Schreibweise aus dem Master-Nachtrag 29.10.2026."""
    if request.method == "OPTIONS":
        return "", 200
    uid, _mail, err = _login_uid_mail()
    if err:
        return err
    b = request.get_json(silent=True) or {}
    return _tv_konten_markieren(uid, b.get("name"), b.get("ignoriert", True), None)


def _tv_konten_markieren(uid, name, ignoriert, angelegt_account_id):
    """ignoriert_at setzen/leeren bzw. angelegt_account_id merken — nur für eine Zeile der EIGENEN ID (user_id aus dem Login)."""
    n = tv_konto_normal(name)
    if not TV_KONTEN_NAME_RE.fullmatch(n):
        return jsonify({"ok": False, "msg": "name ungültig"}), 400
    body = {}
    if ignoriert is not None:
        body["ignoriert_at"] = datetime.now(timezone.utc).isoformat() if ignoriert else None
    if angelegt_account_id:
        if not re.fullmatch(r"[0-9a-f-]{36}", str(angelegt_account_id)):
            return jsonify({"ok": False, "msg": "angelegt_account_id ungültig"}), 400
        body["angelegt_account_id"] = str(angelegt_account_id)
    if not body:
        return jsonify({"ok": False, "msg": "nichts zu ändern (ignoriert oder angelegt_account_id)"}), 400
    try:
        rows = sb_update("tv_konten", {"user_id": f"eq.{uid}", "name": f"eq.{n}"}, body) or []
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht speicherbar ({type(e).__name__})"}), 502
    return jsonify({"ok": True, "n": len(rows)})


# ══ KONTEN PRÜFEN (27.09.2026, Auftrag Koordination B10 für F11: Konten per Einfügen des Tradeify-Dashboard-Texts
# anlegen, Dubletten über ALLE Nutzer ausschließen) ════════════════════════════════════════════════════════════════
# accounts liegt unter RLS am Login — ob eine External ID schon bei einer ANDEREN Person liegt, sieht nur der Service-Key.
# Ausgeliefert werden nur die Treffer (External ID, Konto-ID, Person, Name, Firma, Typ, archiviert), nichts sonst.
# „archiviert" = derselbe Archiv-Stand wie in /admin/overview (user_settings key 'archive', je Konto-ID).
KONTEN_PRUEFEN_MAX = 200


def konten_pruefen_ids(roh):
    """REIN RECHNEND (testbar): Eingabe → Liste getrimmter External IDs (Reihenfolge, ohne Leere/Dubletten, max. 200,
    je max. 64 Zeichen). None, wenn keine Liste."""
    if not isinstance(roh, list):
        return None
    out, gesehen = [], set()
    for x in roh:
        if not isinstance(x, (str, int)):
            continue
        v = str(x).strip()[:64]
        k = v.casefold()
        if v and k not in gesehen:
            gesehen.add(k)
            out.append(v)
        if len(out) >= KONTEN_PRUEFEN_MAX:
            break
    return out


def konten_treffer(ids, konten, disp, archiviert):
    """REIN RECHNEND (testbar): welche External IDs gibt es schon (Groß/klein egal, getrimmt), bei wem?
    → [{external_id, account_id, person, name, firm, account_type, archiviert}] in der Reihenfolge der Eingabe;
    external_id = wie am Konto gespeichert. Mehrere Konten mit derselben ID → alle."""
    je = {}
    for a in konten or []:
        e = str((a or {}).get("external_id") or "").strip()
        if e:
            je.setdefault(e.casefold(), []).append(a)
    aus = {str(x) for x in (archiviert or ())}
    out = []
    for i in ids or []:
        for a in je.get(str(i).strip().casefold(), []):
            uid = str(a.get("user_id") or "")
            out.append({"external_id": str(a.get("external_id") or "").strip(), "account_id": str(a.get("id")),
                        "person": (disp or {}).get(uid) or uid[:8], "name": a.get("name") or "",
                        "firm": a.get("firm") or "", "account_type": a.get("account_type") or "",
                        "archiviert": str(a.get("id")) in aus})
    return out


@app.route("/admin/konten-pruefen", methods=["POST", "OPTIONS"])
def admin_konten_pruefen():
    """POST /admin/konten-pruefen  Body {external_ids: [...]} (≤ 200) → {treffer: [{external_id, account_id, person, name,
    firm, account_type, archiviert}]}. Auth: eingeloggt (sb-token), wie /admin/wd-heute."""
    if request.method == "OPTIONS":
        return "", 200
    me, err = _wd_login()
    if err:
        return err
    ids = konten_pruefen_ids((request.get_json(silent=True) or {}).get("external_ids"))
    if ids is None:
        return jsonify({"error": "external_ids muss eine Liste sein"}), 400
    if not ids:
        return jsonify({"treffer": []})
    try:
        konten = _sb_all("accounts", {"select": "id,user_id,name,firm,account_type,external_id", "external_id": "not.is.null"})
        sicht = _admin_sicht()   # nur eigene Daten (27.09.2026), seit 08.10.2026 die Gruppe: fremde Kontonummern nicht verraten
        if sicht is not None:
            konten = [k for k in konten if str(k.get("user_id") or "") in sicht]
        disp, _excluded = _wd_personen()
        return jsonify({"treffer": konten_treffer(ids, konten, disp, _acc_plan_archiviert())})
    except Exception as e:
        print(f"[konten-pruefen] ⚠️ {type(e).__name__}: {e}", flush=True)
        return jsonify({"error": f"Prüfung nicht möglich ({type(e).__name__})"}), 502


# ══ BULK-VORLAGEN (27.09.2026, Auftrag Koordination B11 für F12: zentrale Vorlagen fürs Bulk-Hinzufügen, für alle IDs) ══
# Tabelle bulk_vorlagen (sql/2026-09-27_bulk_vorlagen.sql): Lesen per RLS für alle Eingeloggten, Schreiben NUR hier —
# Admin-Gate wie Rechnungen/Payout-Kalender (_admin_auth, ADMIN_EMAILS). Nur die Spalten der Tabelle, Typen geprüft.
# account_templates (pro Nutzer) bleibt unberührt.
BULK_VORLAGE_TEXT = ("name", "firm", "account_type", "purchase_ccy", "goal_kind", "name_template", "plattform",
                     "muster_titel", "muster_praefix")
BULK_VORLAGE_ZAHL = ("account_size", "starting_balance", "max_drawdown", "max_daily_drawdown", "max_loss_per_trade",
                     "max_profit_per_trade", "purchase_cost", "consistency_pct")   # consistency_pct seit 25.10.2026
BULK_VORLAGE_GANZ = ("goal_target", "sortierung")
BULK_VORLAGE_BOOL = ("wd_farm", "aktiv")


def bulk_vorlage_pruefen(v):
    """REIN RECHNEND (testbar): Vorlage aus dem Body → (body, None) oder (None, fehlertext). Nur bekannte Spalten; fehlende
    Schlüssel bleiben weg (beim Ändern unverändert), '' / None = leeren. name Pflicht (1–80 Zeichen)."""
    if not isinstance(v, dict):
        return None, "vorlage fehlt"
    body = {}
    for k in BULK_VORLAGE_TEXT:
        if k in v:
            x = v.get(k)
            if x is not None and not isinstance(x, (str, int, float)):
                return None, f"{k} muss Text sein"
            x = str(x).strip() if x is not None else ""
            body[k] = x[:120] or None
    for k in BULK_VORLAGE_ZAHL + BULK_VORLAGE_GANZ:
        if k in v:
            x = v.get(k)
            if x in (None, ""):
                body[k] = None
                continue
            if isinstance(x, bool):
                return None, f"{k} muss eine Zahl sein"
            try:
                f = float(str(x).replace(",", ".")) if isinstance(x, str) else float(x)
            except (TypeError, ValueError):
                return None, f"{k} muss eine Zahl sein"
            if f != f or abs(f) > 1e9:
                return None, f"{k} außerhalb des Bereichs"
            if k in BULK_VORLAGE_GANZ:
                if f != int(f):
                    return None, f"{k} muss eine ganze Zahl sein"
                f = int(f)
            body[k] = f
    for k in BULK_VORLAGE_BOOL:
        if k in v:
            x = v.get(k)
            if not isinstance(x, bool):
                return None, f"{k} muss true/false sein"
            body[k] = x
    if not body.get("name"):
        return None, "name ist Pflicht"
    if len(body["name"]) > 80:
        return None, "name höchstens 80 Zeichen"
    return body, None


@app.route("/admin/bulk-vorlagen", methods=["POST", "OPTIONS"])
def admin_bulk_vorlagen():
    """POST /admin/bulk-vorlagen {aktion: 'speichern'|'loeschen', vorlage: {…}} → {ok, vorlage}. Speichern: mit id → ändern,
    ohne id → neu anlegen (name eindeutig, sonst 409). Löschen: id Pflicht, Antwort = die gelöschte Zeile."""
    if request.method == "OPTIONS":
        return "", 200
    mail, err = _admin_auth()
    if err:
        return err
    b = request.get_json(silent=True) or {}
    aktion = b.get("aktion")
    v = b.get("vorlage") if isinstance(b.get("vorlage"), dict) else {}
    vid = str(v.get("id") or "").strip()
    if vid and not re.fullmatch(r"[0-9a-fA-F-]{36}", vid):
        return jsonify({"ok": False, "error": "id ungültig"}), 400
    try:
        if aktion == "loeschen":
            if not vid:
                return jsonify({"ok": False, "error": "id fehlt"}), 400
            r = _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/bulk_vorlagen", params={"id": f"eq.{vid}"},
                                headers=_sb_headers("return=representation"), timeout=12)
            r.raise_for_status()
            rows = r.json() or []
            if not rows:
                return jsonify({"ok": False, "error": "Vorlage nicht gefunden"}), 404
            return jsonify({"ok": True, "vorlage": rows[0]})
        if aktion != "speichern":
            return jsonify({"ok": False, "error": "aktion muss 'speichern' oder 'loeschen' sein"}), 400
        body, fehler = bulk_vorlage_pruefen(v)
        if fehler:
            return jsonify({"ok": False, "error": fehler}), 400
        body["updated_at"] = datetime.now(timezone.utc).isoformat()
        body["updated_by"] = request.environ.get("prophos.admin_uid")
        if vid:
            r = _sb_anfrage("PATCH", f"{SUPABASE_URL}/rest/v1/bulk_vorlagen", params={"id": f"eq.{vid}"}, json=body,
                               headers=_sb_headers("return=representation"), timeout=12)
        else:
            r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/bulk_vorlagen", json=body,
                              headers=_sb_headers("return=representation"), timeout=12)
        if r.status_code == 409 or "duplicate key" in (r.text or ""):
            return jsonify({"ok": False, "error": f"Eine Vorlage „{body['name']}\" gibt es schon"}), 409
        r.raise_for_status()
        rows = r.json() or []
        if not rows:
            return jsonify({"ok": False, "error": "Vorlage nicht gefunden"}), 404
        print(f"[bulk-vorlagen] {mail}: {'geändert' if vid else 'neu'} „{body['name']}\"", flush=True)
        return jsonify({"ok": True, "vorlage": rows[0]})
    except Exception as e:
        print(f"[bulk-vorlagen] ⚠️ {type(e).__name__}: {e}", flush=True)
        return jsonify({"ok": False, "error": f"nicht speicherbar ({type(e).__name__})"}), 502


# ══ KONTO-BALANCE LESEN AUF ZURUF (27.09.2026, Auftrag Koordination B12 mit F19: Refresh-Knopf neben der Futures-Balance
# in der Accounts-Liste — Puls liest am PC der Konto-ID die Account Balance dieses Kontos) ═════════════════════════════
# Muster wie „Jetzt lesen" (Endlesung): Railway legt eine order_signale-Zeile im Namen des Konto-BESITZERS an
# (order_signale-RLS: nur eigene Zeilen) — dessen PC-Tab claimt sie (orderSignalTick, aktion 'konto_balance'), liest per
# Puls (tv-lesen mit Konto wie die Balance-Lesung seit .625) und schreibt accounts.tv_balance/_at/_quelle 'puls' +
# ergebnis {ok, balance, equity, msg}. plan_id ist in order_signale Pflicht → 'konto:<account_id>'.
# Ein offener Auftrag je Konto (wartet/laeuft, jünger als 10 min → derselbe wird zurückgegeben); älter = verfallen.
# Auth: Admin (ADMIN_EMAILS) ODER Besitzer des Kontos.
KONTO_BALANCE_VERFALL_S = 600


def _login_uid_mail():
    """(user_id, email, None) oder (None, None, (resp, status)) — eingeloggt über sb-token."""
    if not SUPABASE_SERVICE_KEY:
        return None, None, (jsonify({"error": "Server nicht konfiguriert (SUPABASE_SERVICE_KEY fehlt)"}), 503)
    token = (request.headers.get("sb-token") or "").strip()
    if not token:
        return None, None, (jsonify({"error": "Nicht angemeldet"}), 401)
    try:
        r = _auth_user_anfrage(token)
        u = r.json() or {}
        if r.status_code != 200 or not u.get("id"):
            return None, None, (jsonify({"error": "Nicht angemeldet"}), 401)
        return str(u["id"]), str(u.get("email") or "").strip().lower(), None
    except Exception:
        return None, None, (jsonify({"error": "Anmeldung nicht prüfbar"}), 502)


def konto_balance_darf(uid, mail, konto, admins, gruppe=None):
    """REIN RECHNEND (testbar): Admin oder Besitzer des Kontos — seit den Admin-Gruppen (08.10.2026) auch der Verwalter, wenn das Konto
    einer ID seiner Gruppe gehört (gruppe = seine Menge, sonst None)."""
    return bool(konto) and (str(konto.get("user_id") or "") == str(uid or "#") or (mail or "#") in (admins or ())
                            or bool(gruppe and str(konto.get("user_id") or "") in gruppe))


def _konto_balance_gruppe(uid, mail):
    """Gruppe des Aufrufers für konto_balance_darf (nur Verwalter, Admin-Gruppen 08.10.2026). Admin braucht sie nicht; nicht lesbar →
    None (dann bleibt es bei Admin oder Besitzer)."""
    if (mail or "#") in ADMIN_EMAILS or not _admin_ansicht():   # Gruppe nur aus der Admin-Ansicht (Nachbesserung A)
        return None
    try:
        sicht, verwalter = admin_sicht_lesen(str(uid))
        return sicht if verwalter else None
    except Exception:
        return None


def konto_balance_signal(konto, von, aktion="konto_balance", login=""):
    """REIN RECHNEND (testbar): order_signale-Zeile fuer den Auftrag. aktion/login aus balance_lese_weg (CFD → 'mt5_balance' mit Login)."""
    params = {"aktion": aktion, "account_id": str(konto["id"]),
              "external_id": str(konto.get("external_id") or "").strip(), "firm": konto.get("firm") or "",
              "name": konto.get("name") or "", "von": von}
    if login:
        params["login"] = str(login)
    return {"user_id": str(konto["user_id"]), "plan_id": f"konto:{konto['id']}", "status": "wartet", "params": params}


def konto_balance_stand(sig, jetzt_s, verfall_s=KONTO_BALANCE_VERFALL_S):
    """REIN RECHNEND (testbar): Signal-Zeile → Antwort {status, grund, balance, equity, balance_at, pc, updated_at, account_id,
    verfallen}. wartet/laeuft aelter als verfall_s → status 'verfallen'."""
    e = sig.get("ergebnis") if isinstance(sig.get("ergebnis"), dict) else {}
    st = str(sig.get("status") or "")
    try:
        alt_s = jetzt_s - datetime.fromisoformat(str(sig.get("created_at")).replace("Z", "+00:00")).timestamp()
    except (TypeError, ValueError):
        alt_s = 0
    verfallen = st in ("wartet", "laeuft") and alt_s > verfall_s
    grund = e.get("msg") or e.get("grund") or ""
    if verfallen:
        grund = ("Kein PC-Tab hat den Auftrag abgeholt" if st == "wartet" else "PC-Tab hat nicht fertig gemeldet") + \
                f" (älter als {int(verfall_s // 60)} min) — läuft Prophos am PC der ID?"
    return {"status": "verfallen" if verfallen else st, "grund": str(grund)[:300],
            "balance": _wd_num(e.get("balance")), "equity": _wd_num(e.get("equity")), "balance_at": e.get("balance_at"),
            "pc": sig.get("pc"), "updated_at": sig.get("updated_at"),
            "account_id": str((sig.get("params") or {}).get("account_id") or ""), "verfallen": verfallen}


@app.route("/admin/konto-balance-lesen", methods=["POST", "OPTIONS"])
def admin_konto_balance_lesen():
    """POST {aktion:'start', account_id} → {ok, signal_id, status, neu}; POST {aktion:'stand', signal_id} → {ok, status,
    grund, balance, equity, balance_at, pc, updated_at, account_id, verfallen}. Auth: Admin oder Besitzer des Kontos."""
    if request.method == "OPTIONS":
        return "", 200
    uid, mail, err = _login_uid_mail()
    if err:
        return err
    b = request.get_json(silent=True) or {}
    try:
        if b.get("aktion") == "start":
            aid = str(b.get("account_id") or "").strip()
            if not re.fullmatch(r"[0-9a-fA-F-]{36}", aid):
                return jsonify({"ok": False, "error": "account_id fehlt/ungültig"}), 400
            rows = sb_select("accounts", {"select": "id,user_id,name,firm,external_id,account_type", "id": f"eq.{aid}", "limit": "1"})
            konto = rows[0] if rows else None
            if not konto:
                return jsonify({"ok": False, "error": "Konto nicht gefunden"}), 404
            if not konto_balance_darf(uid, mail, konto, ADMIN_EMAILS, _konto_balance_gruppe(uid, mail)):
                return jsonify({"ok": False, "error": "Nur Admin oder Besitzer des Kontos"}), 403
            if not str(konto.get("external_id") or "").strip():
                return jsonify({"ok": False, "error": "Konto ohne External ID — Puls weiß nicht, welches Konto er wählen soll"}), 409
            jetzt = time.time()
            offen = sb_select("order_signale", {"select": "id,status,created_at,updated_at,pc,ergebnis,params",
                                                "plan_id": f"eq.konto:{aid}", "status": "in.(wartet,laeuft)",
                                                "order": "created_at.desc", "limit": "5"}) or []
            for sg in offen:
                if konto_balance_stand(sg, jetzt)["verfallen"]:
                    sb_update("order_signale", {"id": f"eq.{sg['id']}", "status": f"eq.{sg['status']}"},
                              {"status": "fehler", "updated_at": datetime.now(timezone.utc).isoformat(),
                               "ergebnis": {"ok": False, "verfallen": True, "msg": konto_balance_stand(sg, jetzt)["grund"]}})
                else:
                    return jsonify({"ok": True, "signal_id": str(sg["id"]), "status": sg.get("status"), "neu": False})
            # CFD nie über Tradovate (08.10.2026): Weg wie „↻ Balance lesen" in /admin/wd-plaene — MT5-Login aus mt5_links, sonst External ID
            ml = sb_select("mt5_links", {"select": "mt5_login", "account_id": f"eq.{aid}", "limit": "1"}) or []
            weg, x = balance_lese_weg(konto.get("firm"), (ml[0] if ml else {}).get("mt5_login") or "", konto.get("external_id"))
            if not weg:
                return jsonify({"ok": False, "error": x}), 409
            if weg == "mt5_balance":   # kein lebender PC der ID mit diesem Login → sofort sagen (08.10.2026, s. mt5_login_ort)
                ort = _mt5_ort_fehler(str(konto.get("user_id")), x)
                if ort:
                    return jsonify({"ok": False, "error": ort, "code": "kein_pc_login"}), 409
            sig = sb_insert("order_signale", konto_balance_signal(konto, "admin" if str(konto.get("user_id")) != uid else "besitzer",
                                                                  weg, x if weg == "mt5_balance" else ""))
            return jsonify({"ok": True, "signal_id": str((sig or {}).get("id") or ""), "status": "wartet", "neu": True, "art": weg})
        if b.get("aktion") == "stand":
            sid = str(b.get("signal_id") or "").strip()
            if not re.fullmatch(r"[0-9a-fA-F-]{36}", sid):
                return jsonify({"ok": False, "error": "signal_id fehlt/ungültig"}), 400
            rows = sb_select("order_signale", {"select": "id,user_id,status,created_at,updated_at,pc,ergebnis,params", "id": f"eq.{sid}", "limit": "1"})
            sg = rows[0] if rows else None
            if not sg or (sg.get("params") or {}).get("aktion") not in ("konto_balance", "mt5_balance"):   # CFD liest über MT5 (08.10.2026)
                return jsonify({"ok": False, "error": "Auftrag nicht gefunden"}), 404
            if not konto_balance_darf(uid, mail, {"user_id": sg.get("user_id")}, ADMIN_EMAILS, _konto_balance_gruppe(uid, mail)):
                return jsonify({"ok": False, "error": "Nur Admin oder Besitzer des Kontos"}), 403
            st = konto_balance_stand(sg, time.time())
            if st["verfallen"]:
                sb_update("order_signale", {"id": f"eq.{sid}", "status": f"eq.{sg['status']}"},
                          {"status": "fehler", "updated_at": datetime.now(timezone.utc).isoformat(),
                           "ergebnis": {"ok": False, "verfallen": True, "msg": st["grund"]}})
            return jsonify({"ok": True, **st})
        return jsonify({"ok": False, "error": "aktion muss 'start' oder 'stand' sein"}), 400
    except Exception as e:
        print(f"[konto-balance] ⚠️ {type(e).__name__}: {e}", flush=True)
        return jsonify({"ok": False, "error": f"nicht möglich ({type(e).__name__})"}), 502


# ══ PULS-INVENTAR (27.09.2026, Auftrag Koordination B20) — volles TopstepX-Inventar je PC (puls_inventar) ═══════════════
PULS_INVENTAR_MAX = 150_000


def puls_inventar_saeubern(d):
    """REIN RECHNEND (testbar): nur bekannte Felder, Elemente als [name ≤ 60, typ ≤ 20, [l,t,r,b] Zahlen], Größendeckel."""
    if not isinstance(d, dict):
        return None

    def txt(v, n=120):
        return str(v)[:n] if v is not None else None

    def rechteck(r):
        return [int(x) for x in r][:4] if isinstance(r, (list, tuple)) and len(r) == 4 and all(
            isinstance(x, (int, float)) and not isinstance(x, bool) for x in r) else None

    def elemente(lst, n):
        out = []
        for e in (lst or [])[:n] if isinstance(lst, list) else []:
            if isinstance(e, (list, tuple)) and len(e) >= 3:
                out.append([txt(e[0], 60), txt(e[1], 20), rechteck(e[2])])
        return out
    inv = d.get("inventar") if isinstance(d.get("inventar"), dict) else {}
    er = d.get("erkannt") if isinstance(d.get("erkannt"), dict) else {}
    out = {"ok": bool(d.get("ok")), "code": txt(d.get("code"), 20), "msg": txt(d.get("msg"), 200), "schritt": txt(d.get("schritt"), 20),
           "titel": txt(d.get("titel")), "url": txt(d.get("url"), 200), "seite": rechteck(d.get("seite")),
           "erkannt": {k: bool(er.get(k)) for k in ("titel_tsx", "url_tsx", "titel_tv")},
           "tabs": [{"name": txt(t.get("name"), 70), "tsx": bool(t.get("tsx")), "tv": bool(t.get("tv"))}
                    for t in (d.get("tabs") or [])[:20] if isinstance(t, dict)] if isinstance(d.get("tabs"), list) else [],
           "edits": [txt(x, 50) for x in (d.get("edits") or [])][:8] if isinstance(d.get("edits"), list) else [],
           "inventar": {k: elemente(inv.get(k), 260) for k in ("grund", "seite_150", "konto_offen", "bracket_offen") if k in inv},
           # B26 (Inventar v2): Felder mit Wert + Kästchen-Zustand, auch unbenannte — [name, typ, rect, wert, toggle]
           "felder": {k: [[txt(f[0], 60), txt(f[1], 20), rechteck(f[2]), txt(f[3], 60),
                           f[4] if isinstance(f[4], int) and not isinstance(f[4], bool) else None]
                          for f in (inv.get(k) or [])[:120] if isinstance(f, (list, tuple)) and len(f) >= 5]
                      for k in ("felder_grund", "felder_bracket") if isinstance(inv.get(k), list)},
           "ausloeser_kandidaten": elemente(d.get("ausloeser_kandidaten"), 30),
           "zeilen_kandidaten": [[txt(z[0], 120), rechteck(z[1])] for z in (d.get("zeilen_kandidaten") or [])[:20]
                                 if isinstance(z, (list, tuple)) and len(z) >= 2] if isinstance(d.get("zeilen_kandidaten"), list) else [],
           "trail": txt(d.get("trail"), 3000)}
    return out if len(json.dumps(out, ensure_ascii=False)) <= PULS_INVENTAR_MAX else None


@app.route("/puls-inventar/<pc_id>", methods=["POST", "OPTIONS"])
def puls_inventar_schreiben(pc_id):
    if request.method == "OPTIONS":
        return "", 200
    if not PC_ID_MUSTER.fullmatch(pc_id or ""):
        return jsonify({"ok": False, "msg": "pc_id ungültig"}), 400
    if (request.content_length or 0) > PULS_INVENTAR_MAX * 2:
        return jsonify({"ok": False, "msg": "zu groß"}), 413
    d = puls_inventar_saeubern(request.get_json(silent=True))
    if d is None:
        return jsonify({"ok": False, "msg": "Inventar ungültig"}), 400
    try:
        sb_upsert("puls_inventar", {"pc_id": pc_id, "inventar": d, "at": datetime.now(timezone.utc).isoformat()})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht speicherbar ({type(e).__name__})"}), 502
    return jsonify({"ok": True})


# ── PULS-AUGEN über CDP (29.09.2026, Etappe E0, Finns Go) ────────────────────────────────────────────────────────────
# Schalter je PC: wd_farmer_regeln.puls_augen_cdp (text[] der pc_ids mit 'cdp'), gelesen über GET /puls-regel/<pc_id> —
# der Puls (order_bot.py) hat keinen DB-Zugang und fragt hier; jeder Fehler heißt dort 'uia' (wie bisher). Ergebnisse
# (Lesestand/Inventar aus augen.js) schreibt der Puls über POST /puls-augen/<pc_id> in puls_augen (RLS an, nur Service-Key).
# SQL: sql/2026-09-29_puls_augen.sql. E0 = nur lesen, kein Klick.
PULS_AUGEN_MAX = 60_000
_PULS_REGEL_CACHE = {"at": 0.0, "cdp": [], "tsx": [], "gut": False, "tsx_gut": False}
# TopstepX-Arten (30.09.2026, Topstep-Paket B, sql/2026-09-30_puls-augen-tsx.sql — live ausgeführt, derselbe DB-Check):
# 'stand_tsx', 'inventar_tsx' und 'inventar_tsx_<teil>' (1–16 Kleinbuchstaben, z. B. _grund/_konto/_bracket) — eine Zeile je
# Zustand (PK pc_id + art), je Zeile eigener 60-KB-Deckel (der Bot kürzt selbst darunter); die TV-/Tradovate-Zeilen
# 'stand'/'inventar' werden nie überschrieben. Dazu die daten-Schlüssel 'zustand' und 'bot'.
PULS_AUGEN_ARTEN = ("stand", "inventar", "stand_tsx", "inventar_tsx")
_PULS_AUGEN_ART_TEIL = re.compile(r"inventar_tsx_[a-z]{1,16}")


def puls_augen_modus(pc_id, cdp_liste):
    """REIN RECHNEND (testbar): 'cdp', wenn pc_id in der Liste steht, sonst 'uia'."""
    return "cdp" if isinstance(cdp_liste, list) and pc_id in [str(x) for x in cdp_liste] else "uia"


def puls_augen_saeubern(d):
    """REIN RECHNEND (testbar): {art, daten} mit bekannter Art, daten nur als Objekt mit bekannten Schlüsseln, Größendeckel.
    -> (art, daten) | None"""
    art = d.get("art") if isinstance(d, dict) else None
    if not isinstance(art, str) or not (art in PULS_AUGEN_ARTEN or _PULS_AUGEN_ART_TEIL.fullmatch(art)) or not isinstance(d.get("daten"), dict):
        return None
    erlaubt = ("v", "ts", "url", "titel", "geo", "sichtbar", "fokus", "popups", "konto", "ticket", "kauf_knopf", "positionen",
               "orders", "toasts", "konto_summary", "inventar", "fehler", "dauer_ms", "target", "chrome",
               "zustand", "bot",   # zustand/bot seit 30.09.2026 (TopstepX-Inventare je Zustand, Bot-Version)
               "kopf", "positionen_sichtbar", "flach")   # AUGEN-WL-2 (30.09.2026): stand_tsx von augen_tsx.js (K1-Vertrag mit Terminal 3)
    daten = {k: v for k, v in d["daten"].items() if k in erlaubt}
    if len(json.dumps(daten, ensure_ascii=False)) > PULS_AUGEN_MAX:
        return None
    return d["art"], daten


# Cache der Regel-Zeile (30.09.2026, Vorfall Mike pc-l5o8bv: puls_topstep_pcs war schon gesetzt, der 60-s-Cache lieferte beim Einschalten
# noch tsx 'uia' — der Bot lief einmal über den alten UIA-Weg im normalen Chrome). 10 s statt 60 s für die ganze Zeile: der Bot fragt
# nicht im Takt (Augen-Regel lokal 10 min gemerkt, Topstep vor jedem Lauf), das sind höchstens 6 Ein-Zeilen-Reads je Minute und nur,
# wenn überhaupt gefragt wird.
PULS_REGEL_CACHE_S = 10


def puls_regel_stand(jetzt, lesen=None):
    """Regel-Zeile auffrischen, wenn der Cache älter als PULS_REGEL_CACHE_S ist (lesen = sb_select, im Test ersetzbar).
    -> True = Stand brauchbar (frisch oder letzter guter), False = noch nie gelesen und gerade nicht lesbar (→ 503)."""
    # Fehl-Cache (01.10.2026, AUSFALL-BREMSE): auch ein gescheiterter Versuch hält PULS_REGEL_CACHE_S — ohne guten Stand heißt das
    # 10 s lang 503 ohne DB-Read (vorher las nach einem Start im Ausfall jede Anfrage bis 24 s). NIE True ohne guten Stand: dann
    # meldete /puls-regel ausdrücklich 'uia' für alle PCs, und der Bot schlösse das Puls-Chrome (Vorfall 29.09.)
    if jetzt - _PULS_REGEL_CACHE["at"] <= PULS_REGEL_CACHE_S:
        return _PULS_REGEL_CACHE["gut"]
    lesen = lesen or sb_select
    try:
        # puls_topstep_pcs (30.09.2026, Topstep-Paket B, sql/2026-09-30_puls-topstep-pcs.sql): Schalter je PC für den Topstep-Puls
        # → tsx 'cdp' | 'uia'. Fehlt die Spalte noch, NICHT die ganze Regel verlieren (die Augen-Regel trägt Orbit auf allen PCs):
        # dann ohne sie lesen — und tsx NICHT ausdrücklich 'uia' melden (Vertrag wie bei augen): letzter guter Stand, sonst ohne
        # den Schlüssel (der Bot behält seine gemerkte Regel).
        tsx_da = True
        try:
            zeilen = lesen("wd_farmer_regeln", {"id": "eq.1", "select": "puls_augen_cdp,puls_topstep_pcs"})
        except Exception as e:
            if getattr(e, "sb_netz", False):      # Timeout/5xx/Bremse ist kein „Spalte fehlt" — kein zweiter Read
                raise
            zeilen, tsx_da = lesen("wd_farmer_regeln", {"id": "eq.1", "select": "puls_augen_cdp"}), False
        _PULS_REGEL_CACHE["cdp"] = (zeilen[0].get("puls_augen_cdp") if zeilen else None) or []
        if tsx_da:
            _PULS_REGEL_CACHE["tsx"] = (zeilen[0].get("puls_topstep_pcs") if zeilen else None) or []
            _PULS_REGEL_CACHE["tsx_gut"] = True
        _PULS_REGEL_CACHE["at"], _PULS_REGEL_CACHE["gut"] = jetzt, True
    except Exception:
        # DB weg / Spalte fehlt: NIE ausdrücklich 'uia' melden (29.09.2026, Finns Live-Test 14:44 UTC — ein ausdrückliches 'uia'
        # schickt den Bot auf den alten Weg und schließt das Puls-Chrome). Letzten guten Stand weiter nutzen und nach Ablauf des
        # Caches erneut lesen; gab es noch keinen, False → 503, der Bot behält seine gemerkte Regel (Client-Rückfall seit .809).
        _PULS_REGEL_CACHE["at"] = jetzt
        if not _PULS_REGEL_CACHE["gut"]:
            return False
    return True


# ECHO-TEMPO (ES3, Finn 05.11.2026: „Orders sollen viel schneller prozessiert werden, wie es ganz am Anfang war"; Befund ES1: Bot bis Fill
# 24 s statt 16 s seit .1798 „alles aus Zufall"): Tipp-Tempo im F9-Dialog, Denkpausen an/aus und Bot-Versatz als Einstellung in
# wd_farmer_regeln.puls_echo_tempo (jsonb, sql/2026-11-05_echo_tipp_tempo.sql). Reist mit GET /puls-regel/<pc_id> als „echo_tempo" an den
# Bot (der merkt es lokal in echo_tempo.json). EIGENER Cache und eigener Read: fehlt die Spalte noch oder ist die DB weg, bleibt die
# Augen-/Topstep-Regel unberührt und der Schlüssel fehlt in der Antwort → der Bot nimmt seine gemerkten bzw. die heutigen Werte.
# Gegenprüfung ES3: (1) Spalte null nach einem guten Read → {} senden (= „heutige Werte"), sonst behielte jeder PC nach dem Rückbau die zuletzt
# geholten Werte für immer; (2) der Read läuft NIE im Request-Pfad (sb_select kann bei hängender DB > 10 s brauchen, die Augen-/Topstep-Antwort
# hat beim Bot 2 s) — veraltet der Stand, frischt ein Hintergrund-Thread auf, die Anfrage nimmt sofort den letzten Stand.
_PULS_ECHO_CACHE = {"at": 0.0, "wert": None, "gut": False, "laeuft": False}
PULS_ECHO_CACHE_S = 60


def puls_echo_tempo_lesen(jetzt, lesen=None):
    """Ein Read von puls_echo_tempo in den Cache (lesen = sb_select, im Test ersetzbar). Fehler/fehlende Spalte: Stand bleibt."""
    try:
        z = (lesen or sb_select)("wd_farmer_regeln", {"id": "eq.1", "select": "puls_echo_tempo"})
        w = (z[0].get("puls_echo_tempo") if z else None)
        _PULS_ECHO_CACHE["wert"], _PULS_ECHO_CACHE["gut"] = (w if isinstance(w, dict) else {}), True
    except Exception:
        pass
    finally:
        _PULS_ECHO_CACHE["laeuft"] = False


def puls_echo_tempo_stand(jetzt, lesen=None, sofort=False):
    """Letzter guter Stand von puls_echo_tempo -> dict ({} = Spalte null = heutige Werte) | None (noch nie gut gelesen → Schlüssel fehlt).
    Älter als PULS_ECHO_CACHE_S → EIN Hintergrund-Read (sofort=True liest im Aufruf, nur für Tests); die Anfrage wartet nie darauf."""
    if jetzt - _PULS_ECHO_CACHE["at"] > PULS_ECHO_CACHE_S and not _PULS_ECHO_CACHE["laeuft"]:
        _PULS_ECHO_CACHE["at"], _PULS_ECHO_CACHE["laeuft"] = jetzt, True
        if sofort:
            puls_echo_tempo_lesen(jetzt, lesen)
        else:
            try:
                threading.Thread(target=puls_echo_tempo_lesen, args=(jetzt, lesen), daemon=True).start()
            except Exception:
                _PULS_ECHO_CACHE["laeuft"] = False
    return _PULS_ECHO_CACHE["wert"] if _PULS_ECHO_CACHE["gut"] else None


@app.route("/puls-regel/<pc_id>", methods=["GET", "OPTIONS"])
def puls_regel_lesen(pc_id):
    if request.method == "OPTIONS":
        return "", 200
    if not PC_ID_MUSTER.fullmatch(pc_id or ""):
        return jsonify({"ok": False, "msg": "pc_id ungültig"}), 400
    if not puls_regel_stand(time.time()):
        return jsonify({"ok": False, "msg": "Regel gerade nicht lesbar"}), 503
    out = {"ok": True, "augen": puls_augen_modus(pc_id, _PULS_REGEL_CACHE["cdp"])}
    if _PULS_REGEL_CACHE["tsx_gut"]:
        out["tsx"] = puls_augen_modus(pc_id, _PULS_REGEL_CACHE["tsx"])   # 'cdp' genau dann, wenn pc in puls_topstep_pcs (Vertrag T3)
        out["topstep_pc"] = out["tsx"] == "cdp"                          # dasselbe als bool (erste Fassung, falls jemand es liest)
    et = puls_echo_tempo_stand(time.time())                              # ES3 (05.11.2026): nur mit gutem Stand ({} = heute), sonst ohne Schlüssel
    if et is not None:
        out["echo_tempo"] = et
    return jsonify(out)


# ── PULS-ERGEBNISSE (29.09.2026, Finns Live-Test 15:49–15:50 UTC, Plan 5ab15b24) ───────────────────────────────────────
# Der neue Puls platzierte BUY 1 MNQZ6 sauber, die Antwort erreichte den Prophos-Tab aber nie — Plan blieb „Geplant", Position offen
# und für Prophos unsichtbar. Seit .822 meldet der Bot jede scharfe Order und jedes Schließen zusätzlich hierher (direkt nach dem
# Klick stufe 'geklickt', am Ende 'ende'); der PC-Tab des Besitzers übernimmt nie verarbeitete Ergebnisse. Eine Zeile je Plan+Art,
# jede Meldung setzt abgeholt_at zurück (ein neuer Lauf desselben Plans zählt wieder). SQL: sql/2026-09-29_puls_ergebnisse.sql.
PULS_ERGEBNIS_MAX = 30_000
# KANONISCH (30.09.2026, Topstep-Paket B): dieselbe Liste 1:1 in mt5-copier/order_bot.py (PULS_ERGEBNIS_FELDER) — neu für TopstepX:
# mll, rpl, tp_level, sl_level, positionen, plattform. Reihenfolge egal, Menge muss gleich sein (app.py zuerst deployen, dann Bot).
PULS_ERGEBNIS_FELDER = ("ok", "code", "schritt", "msg", "gesendet", "bestaetigt", "bestaetigung", "geklickt", "retry_ok",
                        "einstieg", "einstieg_quelle", "tp_limit", "tp_limit_quelle", "sl_limit", "sl_limit_quelle", "order_klick_ms",
                        "klick_at", "balance_start", "equity_start", "today_pnl_start", "today_pnl", "balance_end", "equity_end",
                        "tv_symbol", "menge", "konto_aktiv", "pruefung", "meldung_roh", "positionen_danach", "close_fill", "storniert",
                        "symbol", "richtung", "konto", "trail_ende", "quelle",
                        "mll", "rpl", "tp_level", "sl_level", "positionen", "plattform",
                        # B37 (30.09.2026): Warnung trotz ok (z. B. SL-Bracket abgelehnt) + unklar (Klick raus, Position nicht belegbar) — das
                        # Tab braucht beide auch beim Nachholen (Karten-Chip bzw. UNKLAR-Marke); order_bot.py führt dieselbe Liste
                        "warnung", "unklar",
                        # TSV2-PNL (01.10.2026): TopstepX-Balance als Zahl + Basis (Express 0-basiert), UP&L beim Klick und die summary —
                        # sonst verliert ein nachgeholter tsx-close die End-Balance. order_bot.py zieht nach (app.py zuerst deployen)
                        "balance", "balance_relativ", "upl", "summary",
                        # Nova-Brackets (29.10.2026): fehlende Brackets nach dem Fill ({risk, tp, bild?}) + Dialog über der Tabelle (Titel, Foto)
                        "brackets_fehlen", "bracket_dialog", "bracket_dialog_bild")
_PLAN_ID_MUSTER = re.compile(r"[A-Za-z0-9-]{8,64}")


def puls_ergebnis_saeubern(d, pc_id):
    """REIN RECHNEND (testbar): Paket des Bots → Tabellenzeile für puls_ergebnisse | None. Nur bekannte Schlüssel, Listen/Texte
    gekürzt, Größendeckel; Top-Level konto/symbol/richtung/at_ms wandern ins ergebnis, falls es sie nicht selbst trägt."""
    if not isinstance(d, dict) or not isinstance(d.get("ergebnis"), dict):
        return None
    plan_id, art, stufe = str(d.get("plan_id") or ""), d.get("art"), d.get("stufe") or "ende"
    if not _PLAN_ID_MUSTER.fullmatch(plan_id) or art not in ("order", "close") or stufe not in ("geklickt", "ende"):
        return None
    e = {k: v for k, v in d["ergebnis"].items() if k in PULS_ERGEBNIS_FELDER}
    for k in ("konto", "symbol", "richtung"):
        if e.get(k) in (None, "") and d.get(k) not in (None, ""):
            e[k] = d.get(k)
    if isinstance(d.get("at_ms"), (int, float)):
        e["at_ms"] = int(d["at_ms"])
    if isinstance(e.get("meldung_roh"), list):
        e["meldung_roh"] = [str(x)[:300] for x in e["meldung_roh"][:14]]
    for k in ("positionen_danach", "positionen"):     # TopstepX-Positionen (30.09.2026) wie positionen_danach gekappt
        if isinstance(e.get(k), list):
            e[k] = e[k][:10]
    for k in ("msg", "trail_ende"):
        if isinstance(e.get(k), str):
            e[k] = e[k][:1500]
    if isinstance(e.get("warnung"), str):
        e["warnung"] = e["warnung"][:300]
    if len(json.dumps(e, ensure_ascii=False, default=str)) > PULS_ERGEBNIS_MAX:
        e.pop("pruefung", None)
        e.pop("trail_ende", None)
        if len(json.dumps(e, ensure_ascii=False, default=str)) > PULS_ERGEBNIS_MAX:
            return None
    return {"plan_id": plan_id, "art": art, "pc_id": pc_id, "stufe": stufe, "ergebnis": e, "abgeholt_at": None}


@app.route("/puls-ergebnis/<pc_id>", methods=["POST", "OPTIONS"])
def puls_ergebnis_schreiben(pc_id):
    if request.method == "OPTIONS":
        return "", 200
    if not PC_ID_MUSTER.fullmatch(pc_id or ""):
        return jsonify({"ok": False, "msg": "pc_id ungültig"}), 400
    if (request.content_length or 0) > PULS_ERGEBNIS_MAX * 3:
        return jsonify({"ok": False, "msg": "zu groß"}), 413
    zeile = puls_ergebnis_saeubern(request.get_json(silent=True), pc_id)
    if zeile is None:
        return jsonify({"ok": False, "msg": "Ergebnis ungültig"}), 400
    zeile["at"] = datetime.now(timezone.utc).isoformat()
    try:
        sb_upsert("puls_ergebnisse", zeile, kritisch=True)   # an der Supabase-Bremse vorbei: der Bot wiederholt nicht
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht speicherbar ({type(e).__name__})"}), 502
    # TAB-WÄCHTER (30.10.2026, order_bot tab_wache_warten): der Tab schläft, also meldet hier der Bot — 🔴 an die Master-IDs. Wirft nie (alarm_senden, try)
    if zeile["art"] == "order" and zeile["ergebnis"].get("code") == "tab_nicht_erreichbar":
        tab_wache_alarm(zeile, pc_id)
    return jsonify({"ok": True})


def tab_wache_alarm(zeile, pc_id):
    """🔴 „Order abgebrochen, Tab schläft" EINMAL je Vorfall (S2 30.10.2026: der Plan versucht es im 15-min-Takt ohne Deckel, ein Schlüssel mit der Minute hätte
    jedes Mal gemeldet): Schlüssel Plan + PC + Tag, vorher im alarm_log nachsehen wie alarm_ereignisse. alarm_log nicht lesbar → senden, lieber doppelt als eine 🔴
    verschluckt. Wirft nie."""
    try:
        schluessel = f"{zeile['plan_id']}|{pc_id}|tab_nicht_erreichbar|{str(zeile.get('at') or '')[:10]}"
        schon = alarm_im_log([schluessel], 86400)
        if schon and schluessel in schon:
            return False
        pl = (sb_select("trade_plans", {"select": "user_id,master_name,master_firm", "id": f"eq.{zeile['plan_id']}"}) or [{}])[0]
        uid = str(pl.get("user_id") or "")
        if not uid or _alarm_fremd_verwaltet(uid):
            return False
        pn = (_pc_namen_daten().get(pc_id) or {}).get("name")
        wer_pc = f"PC von {pn or _ap_namen()[0].get(uid, uid[:8])} ({pc_id})"
        grund = str(zeile["ergebnis"].get("msg") or "Prophos-Tab hat während des Starts nicht geantwortet — nichts gesendet.")[:200]
        alarm_senden(1, "tab_nicht_erreichbar", f"Order abgebrochen, Tab schläft: {wer_pc}"[:120],
                     f"{pl.get('master_firm') or ''} {pl.get('master_name') or ''} auf {wer_pc}: {grund} Tab am PC nach vorn holen; der Plan versucht es danach wieder.",
                     uid=uid, plan_id=zeile["plan_id"], schluessel=schluessel)
        return True
    except Exception as e:
        print(f"[puls-ergebnis] Tab-Wächter-Alarm: {type(e).__name__}: {str(e)[:160]}", flush=True)
        return False


@app.route("/puls-augen/<pc_id>", methods=["POST", "OPTIONS"])
def puls_augen_schreiben(pc_id):
    if request.method == "OPTIONS":
        return "", 200
    if not PC_ID_MUSTER.fullmatch(pc_id or ""):
        return jsonify({"ok": False, "msg": "pc_id ungültig"}), 400
    if (request.content_length or 0) > PULS_AUGEN_MAX * 2:
        return jsonify({"ok": False, "msg": "zu groß"}), 413
    g = puls_augen_saeubern(request.get_json(silent=True))
    if g is None:
        return jsonify({"ok": False, "msg": "Augen-Daten ungültig"}), 400
    try:
        sb_upsert("puls_augen", {"pc_id": pc_id, "art": g[0], "daten": g[1], "at": datetime.now(timezone.utc).isoformat()})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht speicherbar ({type(e).__name__})"}), 502
    return jsonify({"ok": True})


