def wd_plan_eigen(uid, plan_id):
    """Gehört der Plan dem Login? (uid, plan_id) → bool. Nicht lesbar oder unklar → False (dann sperrt das Gate wie bisher)."""
    pid = str(plan_id or "").strip()
    if not uid or len(pid) < 10:
        return False
    try:
        z = sb_select("trade_plans", {"select": "user_id", "id": f"eq.{pid}", "limit": "1"}) or []
    except Exception:
        return False
    return bool(z) and str(z[0].get("user_id")) == str(uid)


def _wd_login_uid_still():
    """user_id des Logins ohne Fehler-Antwort (None, wenn nicht angemeldet)."""
    try:
        uid, err = _wd_login()
        return None if err else uid
    except Exception:
        return None


def planer_schreib_recht(admin, uid, gruppe_menge, voll_uids):
    """REIN RECHNEND (testbar): darf dieser Login in den Planern ändern? admin = ADMIN_EMAILS bzw. admin_voll (_planer_admin_auth),
    gruppe_menge = IDs seiner Gruppe MIT Verwalter (admin_lese_gruppe_menge) oder None (HT), voll_uids = admin_voll."""
    if admin:
        return True
    if gruppe_menge:
        return True                      # Emins Gruppe: unverändert (Rechte je Route wie bisher, Sicht je Gruppe)
    return bool(uid) and str(uid) in (voll_uids or ())


def _planer_admin_auth():
    """Wie _admin_auth (→ (mail, None) | (None, Fehler)), in den Planer-Routen aber auch für admin_voll (admin_voll_frei: „Finn + Pascal",
    „Pascal") — beide gelten dort wie ein Admin. Rechnungen/Kasse nutzen weiter _admin_auth."""
    mail, err = _admin_auth()
    if err is None or err[1] != 403:
        return mail, err
    uid = str(request.environ.get("prophos.admin_uid") or "")
    try:
        frei = admin_voll_frei(uid, admin_voll_uids(), admin_sicht_lesen(uid)[0]) if uid else False
    except Exception:
        return None, (jsonify({"ok": False, "error": "Anmeldung nicht prüfbar", "msg": "Anmeldung nicht prüfbar"}), 502)
    return (f"admin_voll {uid[:8]}", None) if frei else (None, err)


def _planer_schreib_gate():
    """Schreib-Riegel der Planer-Routen (PLANER-RECHTE HT): None = darf, sonst die Fehler-Antwort (401/403/502)."""
    _mail, err = _planer_admin_auth()
    if err is None:
        return None
    if err[1] != 403:
        return err
    uid, err2 = _wd_login()
    if err2:
        return err2
    try:
        ok = planer_schreib_recht(False, uid, admin_lese_gruppe_menge(str(uid), admin_gruppen_daten()), admin_voll_uids())
    except Exception as e:
        print(f"[planer-rechte] ⚠️ nicht prüfbar ({type(e).__name__}) — gesperrt", flush=True)
        return jsonify({"ok": False, "error": "Rechte nicht prüfbar", "msg": "Rechte nicht prüfbar — nichts geändert"}), 502
    if ok:
        return None
    msg = "Nur „Finn + Pascal“ und „Pascal“ dürfen im Planer etwas ändern — diese ID kann hier nur ansehen"
    try:   # welche ID angemeldet ist (02.11.2026: Finn sah den Toast, ohne zu wissen, unter welcher ID der Tab lief)
        _nm = _ap_namen()[0].get(str(uid))
        if _nm:
            msg += f" (angemeldet: {_nm})"
    except Exception:
        pass
    print(f"[planer-rechte] ⛔ {str(uid)[:8]} {request.method} {request.path}", flush=True)
    return jsonify({"ok": False, "error": msg, "msg": msg, "nur_ansehen": True}), 403


@app.route("/admin/planer-rechte", methods=["GET", "OPTIONS"])
def admin_planer_rechte():
    """GET → {ok, schreiben, grund?} — darf dieser Login in den Planern ändern (PLANER-RECHTE HT, _planer_schreib_gate)? Für das Ausgrauen der
    Knöpfe im Frontend (S3); der Server prüft an jeder Schreib-Route trotzdem selbst. Nicht prüfbar → schreiben false."""
    if request.method == "OPTIONS":
        return "", 200
    e = _planer_schreib_gate()
    if e is not None and e[1] == 401:
        return e
    out = jsonify({"ok": True, "schreiben": e is None, **({} if e is None else {"grund": (e[0].get_json(silent=True) or {}).get("msg")})})
    out.headers["Cache-Control"] = "no-store"
    return out


def ap_admin_reiter_ok(admin, im_planer, nur_eigene, sicht, verwalter=False):
    """REIN RECHNEND (08.10.2026): darf dieser Login die LESE-Routen des Trade-Planers (/admin/auto-plan GET, /delta) nutzen?
    Admin oder ID im Planer. Die kurze Öffnung für jeden Login mit sicht="admin" (.1248) ist seit Option A (Finn 08.10.2026) wieder zu —
    sicht ist ein Client-Parameter; was eine Planer-ID dann sieht (alle oder eigene), entscheidet ap_sicht_uid.
    ADMIN-GRUPPEN (08.10.2026): dazu ein Verwalter im Admin-Reiter (sicht="admin") — er sieht dort nur seine Gruppe (ap_sicht_uid).
    Seit 30.10.2026 übergeben beide Aufrufer (_ap_zugang, GET /admin/auto-plan) für den Verwalter fest AP_SICHT_ADMIN: er liest auch ohne
    ?sicht=admin, dann nur die eigene ID (Finn als Emin: „Delta-Daten nicht geladen (HTTP 403)")."""
    # seit Option A (Finn 08.10.2026): sicht=admin öffnet für Logins außerhalb des Planers nichts mehr — außer für Verwalter (Gruppe)
    return bool(admin) or bool(im_planer) or (bool(verwalter) and str(sicht or "").strip().lower() == AP_SICHT_ADMIN)


def ap_eingriff_filter(aktion, plan_ids, sicht_uid=None):
    """REIN RECHNEND (BESTÄTIGEN FÜR ALLE IDS, Master 07.10.2026 03:58 Dubai, Finn: „eine Seite, wo ich alle Trades sehe UND bestätigen
    kann"): PostgREST-Filter + Body für die Routen /admin/auto-plan/bestaetigen | zurueck | loeschen. Dieselben Bedingungen wie das
    Frontend per supabase-js (apBestaetigen: planned + auto_plan + unbestätigt; apZuruecknehmen/deleteTradePlan: planned + auto_plan +
    ungestartet) als Guard in derselben Anfrage; sicht_uid (Nicht-Admin, „nur eigene") engt auf die eigene ID ein, eine Menge
    (Verwalter, Admin-Gruppen 08.10.2026) auf die IDs seiner Gruppe.
    → (params, body, 'patch'|'delete') oder (None, None, Fehlertext)."""
    # PULS-PAUSE (14.10.2026 18:28 Dubai, Mike c3fffac0: trotz Pause-Marke um 12:45 UTC wieder bestätigt — Echo-Order platziert, während Finn
    # den Polar-Trade von Hand machte): ein Plan mit mt5_baseline.puls_pause wird über „bestätigen" nie wieder scharf — Rückweg nur über die
    # SQL-Datei (Marke entfernen), nicht über den Knopf
    bed = {"bestaetigen": ({"status": "eq.planned", "auto_plan": "eq.true", "auto_bestaetigt_at": "is.null", "mt5_baseline->puls_pause": "is.null"}, "patch"),
           "zurueck": ({"status": "eq.planned", "auto_plan": "eq.true", "start_um_gestartet_at": "is.null"}, "patch"),
           "loeschen": ({"status": "eq.planned", "auto_plan": "eq.true", "start_um_gestartet_at": "is.null"}, "delete")}.get(str(aktion or ""))
    if not bed:
        return None, None, "aktion = bestaetigen | zurueck | loeschen"
    ids = []
    for i in plan_ids or []:
        t = str(i or "").strip().lower()
        if re.match(r"^[0-9a-f-]{36}$", t) and t not in ids:
            ids.append(t)
    if not ids:
        return None, None, "plan_ids: keine gültige Plan-ID"
    if len(ids) > AP_EINGRIFF_MAX:
        return None, None, f"höchstens {AP_EINGRIFF_MAX} Pläne je Aufruf"
    params = dict(bed[0], id=("eq." + ids[0]) if len(ids) == 1 else ("in.(" + ",".join(ids) + ")"))
    if isinstance(sicht_uid, (str, int)) and str(sicht_uid):
        params["user_id"] = "eq." + str(sicht_uid)
    elif sicht_uid is not None and not isinstance(sicht_uid, (str, int)):   # Gruppe des Verwalters (nie leer: er selbst gehört dazu)
        params["user_id"] = "in.(" + ",".join(sorted(str(u) for u in sicht_uid) or ["00000000-0000-0000-0000-000000000000"]) + ")"
    body = {"auto_bestaetigt_at": datetime.now(timezone.utc).isoformat()} if aktion == "bestaetigen" \
        else {"auto_bestaetigt_at": None} if aktion == "zurueck" else None
    return params, body, bed[1]


def ap_ende_unter_boden(regel, phase, balance_start, balance_end):
    """REIN RECHNEND (testbar, Finn 09.10.2026: „auch nur kurz unter der Max-Loss-Grenze = geblowt"): liegt die Balance NACH dem
    Trade auf/unter dem Boden des Kontos (Boden aus ap_boden_konto mit der Balance VOR dem Trade, dieselbe Quelle wie Planer-Kappung und
    Balken)? Eine gemessene Mindest-Equity je Plan gibt es nicht (weder mt5_live noch Copier/Panel) — die End-Balance entscheidet.
    Ohne Boden (unbekannt, Futures ohne Kernwerte) oder ohne Balancen → False (nie geraten)."""
    if not regel or balance_start is None or balance_end is None:
        return False
    try:
        b = ap_boden_konto(regel, phase, float(balance_start)) or {}
    except Exception:
        return False
    bo = b.get("boden")
    return bo is not None and float(balance_end) <= float(bo)


def ap_blow_ausschluss(plaene_konto, bal, stand):
    """REIN RECHNEND (testbar): Planer-Ausschluss „geblowt" (Finn 09.10.2026) → True, solange der LETZTE beendete Plan des Kontos blown ist
    UND seitdem keine neue Balance-Lesung vorliegt (ap_balance_live). Kommt nach dem Blow eine frische Lesung (Reset gekauft, neue Phase auf
    derselben accounts-Zeile — Hinweis Prüfer T3), entscheidet wieder der normale Weg: Balance ≤ Boden → „geblowt?" in ap_konto_rechnen,
    sonst wird geplant."""
    fertig = [p for p in plaene_konto or () if p.get("ended_at") or p.get("completed_at")]
    if not fertig:
        return False
    p = max(fertig, key=lambda x: str(x.get("ended_at") or x.get("completed_at") or ""))
    if p.get("blown") is not True:
        return False
    return not (bal and ap_balance_live(stand, str(p.get("ended_at") or p.get("completed_at") or "")))


def _ap_blow_beim_abhaken(plan, master_pl):
    """Beim „Erledigt" (Radar/Abschluss-Popup): Ende auf/unter dem Boden → True (Plan blown). Nur Challenge/Phasen (AP_TYPEN), nur mit
    Firmen-Regel. End-Balance = final.balance_end, sonst Start + master_pl; Start = tv.balance_start bzw. balance_start der Baseline.
    Fehler beim Lesen → False (das Abhaken selbst darf daran nie scheitern). Archiviert NICHT — das macht Finn."""
    try:
        bl = plan.get("mt5_baseline") if isinstance(plan.get("mt5_baseline"), dict) else {}
        tv = bl.get("tv") if isinstance(bl.get("tv"), dict) else {}
        fin = bl.get("final") if isinstance(bl.get("final"), dict) else {}
        bs = _wd_num(tv.get("balance_start")) or _wd_num(bl.get("balance_start"))
        be = _wd_num(fin.get("balance_end"))
        # Echo V2 (09.10.2026, Fall FundedNext 100k Phase 2): vorher/nachher stehen dort in master_balance / bal_nach — vorher las
        # dieser Weg nur die Orbit-Felder und sagte bei Echo nie „geblowt"
        echt = ap_echte_balancen(plan)
        if echt:
            bs = bs if bs is not None else echt[0]
            be = be if be is not None else echt[1]
        if be is None and bs is not None and master_pl is not None:
            be = float(bs) + float(master_pl)
        if bs is None or be is None or not plan.get("master_account_id"):
            return False
        acc = (sb_select("accounts", {"select": "id,user_id,firm,account_type,consistency_pct,ziel_pct_konto,max_drawdown",
                                      "id": f"eq.{plan['master_account_id']}", "limit": "1"}) or [None])[0]
        phase = str(plan.get("konto_typ") or (acc or {}).get("account_type") or "")
        if not acc or phase not in AP_TYPEN:
            return False
        reg = (sb_select("auto_plan_regeln", {"select": "regeln", "id": "eq.1"}) or [{}])[0]
        # UNT3: Boden nach der Regel des Unternehmens der ID (Standard + Abweichung); Unternehmen unbekannt → keine Regel → nicht blown (Finn hakt)
        regel = ap_regel_unternehmen(acc.get("user_id") or plan.get("user_id"), ((reg.get("regeln") or {}).get("firmen") or []), acc.get("firm"))
        if not regel:
            return False
        return ap_ende_unter_boden(ap_regel_konto(regel, acc, float(bs)), phase, bs, be)
    except Exception as e:
        print(f"[erledigt] Boden-Prüfung übersprungen ({type(e).__name__}: {e})", flush=True)
        return False


# ══ GEBLOWT AUTOMATISCH ABHAKEN (09.10.2026, Finn über Master ~20:45 Dubai, Fall FundedNext 100k Phase 2, Plan 4d43a7a5: Echo V2
# SELL 2,4 Lot, Ende 14:38 Dubai, MT5-Balance danach 89.942 $ unter dem Boden 90.000 — stand trotzdem in „Überprüfen", ohne Chip, Konto
# aktiv). Zwei Lücken: _ap_blow_beim_abhaken las nur die Orbit-Felder (tv.balance_start / final.balance_end) — Echo V2 schreibt
# mt5_baseline.master_balance (vorher) und bal_nach / final.master_balance (nachher); und die Prüfung lief nur beim Klick auf „Erledigt".
# Finns Regel: echte gelesene Balance nach dem Trade auf/unter dem Boden = geblowt → automatisch. ap_loop prüft alle AP_BLOW_AUTO_S die
# Pläne in „Überprüfen": Plan completed + blown mit P&L = nachher − vorher, Konto im Archiv des Besitzers als „blown" (+ Echo-Löschauftrag;
# die geplanten Trades räumt ap_archiv_sweep), Push an Inhaber + Admins. Nur echte Lesungen, nie Demo/Schätzung/Hand. Topstep-Kette
# (Route tsv2, Firmen mit regel.kette) hat ihre eigene MLL-Logik; Pläne mit Hedge bleiben beim Abhaken von Hand (Hedge-P&L gehört dazu).
AP_BLOW_AUTO_S = 300
AP_BLOW_AUTO_ROUTEN = ("mt5v2", "tvv2")
_ap_blow_auto = {"at": 0.0, "n": 0, "fehler": ""}


def ap_echte_balancen(plan):
    """REIN RECHNEND (testbar): (vorher, nachher, quelle) aus ECHTEN Lesungen, sonst None.
    Echo V2 (mt5v2): vorher = mt5_baseline.master_balance (Copier beim Start), nachher = bal_nach.balance (Nachlesung, ok) bzw.
    final.master_balance. Orbit V2 (tvv2): vorher = tv.balance_start, nachher = final.balance_end nur mit final.quelle 'puls'
    (Puls-Endlesung) — Demo-, Hand-, Level- und Reader-Werte zählen nie. Topstep V2 (tsv2) zusätzlich final.quelle 'auge' (29.10.2026:
    Endlesung aus dem TopstepX-Auge mit Flach-Beweis, exaktem Konto, zwei gleichen RP&L-Lesungen und Balance-Diff = RP&L-Delta)."""
    bl = plan.get("mt5_baseline") if isinstance((plan or {}).get("mt5_baseline"), dict) else {}
    fin = bl.get("final") if isinstance(bl.get("final"), dict) else {}
    route = str((plan or {}).get("route") or "")
    if route == "mt5v2":
        bn = bl.get("bal_nach") if isinstance(bl.get("bal_nach"), dict) else {}
        vorher = _wd_num(bl.get("master_balance"))
        nachher, q = (_wd_num(bn.get("balance")), "mt5_nachlesung") if bn.get("ok") is True else (None, None)
        if nachher is None:
            nachher, q = _wd_num(fin.get("master_balance")), "mt5_final"
    elif route in ("tvv2", "tsv2"):   # tsv2 (.1493): Puls-Endlesung in TopstepX schreibt dasselbe final (quelle 'puls')
        tv = bl.get("tv") if isinstance(bl.get("tv"), dict) else {}
        vorher = _wd_num(tv.get("balance_start"))
        nachher, q = (_wd_num(fin.get("balance_end")), "puls") if fin.get("quelle") == "puls" else (None, None)
        if nachher is None and route == "tsv2" and fin.get("quelle") == "auge":   # Nova-Endlesung aus dem TopstepX-Auge (29.10.2026, prophos.html tsxAugeEndeUrteil)
            nachher, q = _wd_num(fin.get("balance_end")), "auge"
    else:
        return None
    if not vorher or vorher <= 0 or not nachher or nachher <= 0:
        return None
    return float(vorher), float(nachher), q


def ap_blow_lesung_at(plan):
    """REIN RECHNEND: Zeitpunkt der End-Lesung (bal_nach.live_at/at, sonst final.at, sonst ended_at) als ISO-Text oder ''."""
    bl = plan.get("mt5_baseline") if isinstance((plan or {}).get("mt5_baseline"), dict) else {}
    bn = bl.get("bal_nach") if isinstance(bl.get("bal_nach"), dict) else {}
    fin = bl.get("final") if isinstance(bl.get("final"), dict) else {}
    return str(bn.get("live_at") or bn.get("at") or fin.get("at") or (plan or {}).get("ended_at") or "")


def _ap_iso_ts(v):
    try:
        return datetime.fromisoformat(str(v).replace("Z", "+00:00")).timestamp()
    except (TypeError, ValueError):
        return None


def ap_blow_auto_pruefen(plan, acc, regel, neuer_plan=False):
    """REIN RECHNEND (testbar): geblowt laut echter Lesung? → {vorher, nachher, pl, boden, quelle} oder None.
    Nur status 'review', noch nicht blown, Route AP_BLOW_AUTO_ROUTEN, Phase in AP_TYPEN (konto_typ des Plans, sonst des Kontos), Firmen-Regel
    ohne Kette, kein Hedge am Plan, Boden bekannt (ap_boden_konto mit der Balance VOR dem Trade wie ap_ende_unter_boden).
    RESET-RIEGEL (Vorprüfung Terminal 3, 09.10.2026): ein alter geblowter Plan in „Überprüfen" darf nie ein Konto archivieren, das auf
    derselben accounts-Zeile neu angefangen hat (Reset gekauft, nächste Phase) — dann bliebe ein gesundes Konto archiviert und Echo bekäme
    den Terminal-Löschauftrag. Kein Automatik-Blow, wenn (a) konto_typ des Plans ≠ account_type des Kontos, (b) die Konto-Balance
    (tv_balance) NACH der End-Lesung gelesen wurde und über dem Boden liegt, (c) es einen neueren Plan auf dem Konto gibt (neuer_plan).
    Diese Fälle bleiben beim Abhaken von Hand."""
    p = plan or {}
    if neuer_plan:
        return None
    if p.get("status") != "review" or p.get("blown") is True or str(p.get("route") or "") not in AP_BLOW_AUTO_ROUTEN:
        return None
    if not acc or not regel or ap_kette_regel(regel):
        return None
    phase = str(p.get("konto_typ") or acc.get("account_type") or "")
    if phase not in AP_TYPEN:
        return None
    if p.get("konto_typ") and acc.get("account_type") and str(p.get("konto_typ")) != str(acc.get("account_type")):
        return None                                # (a) Konto ist inzwischen in einer anderen Phase
    bl = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    if bl.get("hedge"):
        return None
    echt = ap_echte_balancen(p)
    if not echt:
        return None
    vorher, nachher, q = echt
    try:
        bo = (ap_boden_konto(ap_regel_konto(regel, acc, vorher), phase, vorher) or {}).get("boden")
    except Exception:
        return None
    if bo is None or nachher > float(bo):
        return None
    kb, kb_ts, les_ts = _wd_num(acc.get("tv_balance")), _ap_iso_ts(acc.get("tv_balance_at")), _ap_iso_ts(ap_blow_lesung_at(p))
    if kb is not None and kb > float(bo) and kb_ts is not None and (les_ts is None or kb_ts > les_ts):
        return None                                # (b) neuere gesunde Lesung am Konto
    return {"vorher": vorher, "nachher": nachher, "pl": round(nachher - vorher, 2), "boden": float(bo), "quelle": q}


def _konto_archiv_eintragen(uid, aid, grund, jetzt_iso, name=None):
    """Konto im Archiv des Besitzers eintragen (user_settings key 'archive' {konto_id: {archived, reason, at}}: lesen → ergänzen →
    upsert; ein schon archiviertes Konto bleibt unverändert) + Echo-Löschauftrag wie archiveAccount() im Frontend (07.09.2026), still,
    falls keins verknüpft. grund 'blown' | 'passed_pending'. → True (neu archiviert) | False (war schon). Wirft bei DB-Fehlern.
    AC3 (05.11.2026): Schreiben mit updated_at-Wächter wie _archiv_eintrag_entfernen — hat ein Tab/anderer Lauf zwischen Lesen und Schreiben das Archiv
    geändert, neu lesen und nur diesen Eintrag ergänzen (bis 3 Versuche); ohne Zeile anlegen (gleichzeitig angelegt → neu lesen). Nie ein fremder Stand weg."""
    neu = False
    for _versuch in range(3):
        z = sb_select("user_settings", {"select": "value,updated_at", "user_id": f"eq.{uid}", "key": "eq.archive", "limit": "1"})
        zeile = z[0] if z else None
        v = (zeile or {}).get("value")
        if isinstance(v, str):
            v = json.loads(v)
        arch = dict(v) if isinstance(v, dict) else {}
        neu = not (isinstance(arch.get(aid), dict) and arch[aid].get("archived"))
        if not neu:
            break
        arch[aid] = {"archived": True, "reason": grund, "at": jetzt_iso}
        if zeile is None:
            r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/user_settings",
                            json={"user_id": uid, "key": "archive", "value": arch, "updated_at": jetzt_iso},
                            headers=_sb_headers("return=minimal"), timeout=12)
            if r.status_code == 409:      # gleichzeitig angelegt → neu lesen und ergänzen
                continue
            r.raise_for_status()
            break
        guard = {"user_id": f"eq.{uid}", "key": "eq.archive"}
        if zeile.get("updated_at"):
            guard["updated_at"] = f"eq.{zeile['updated_at']}"
        else:
            guard["updated_at"] = "is.null"
        if sb_update("user_settings", guard, {"value": arch, "updated_at": jetzt_iso}):
            break
        # 0 Zeilen: dazwischen geschrieben → neu lesen
    else:
        raise RuntimeError("Archiv nach 3 Versuchen nicht geschrieben (Wächter updated_at)")
    try:
        ml = sb_select("mt5_links", {"select": "mt5_login", "account_id": f"eq.{aid}", "limit": "1"})
        if ml and ml[0].get("mt5_login"):
            _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/echo_loesch_auftraege", params={"on_conflict": "mt5_login"},
                        json={"mt5_login": str(ml[0]["mt5_login"]), "grund": grund, "account_name": name, "angelegt_am": jetzt_iso,
                              "erledigt_am": None, "erledigt_info": None},
                        headers=_sb_headers("resolution=merge-duplicates,return=minimal"), timeout=12).raise_for_status()
    except Exception as e:
        print(f"[archiv] ⚠️ Echo-Löschauftrag {aid}: {type(e).__name__}: {e}", flush=True)
    return neu


def _ap_blow_auto_abhaken(plan, acc, k):
    """Einen geblowten Plan abhaken (completed + blown, P&L aus der Lesung), Konto archivieren, Push. Optimistische Sperre: nur solange
    der Plan noch in 'review' und nicht blown steht — hat ihn inzwischen jemand abgehakt, passiert nichts. → True, wenn abgehakt."""
    pid = str(plan["id"])
    jetzt_iso = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    upd, fehler = _wd_erledigt_upd(plan, k["pl"], None, jetzt_iso, _cme_handelstag())
    if fehler:
        print(f"[blow-auto] {pid[:8]} nicht abgehakt: {fehler[1]}", flush=True)
        return False
    upd["blown"] = True
    if not sb_update("trade_plans", {"id": f"eq.{pid}", "status": "eq.review", "blown": "not.is.true"}, upd):
        return False
    uid, aid = str(plan.get("user_id") or acc.get("user_id") or ""), str(acc.get("id") or "")
    try:
        neu = _konto_archiv_eintragen(uid, aid, "blown", jetzt_iso, plan.get("master_name")) if uid and aid else False
    except Exception as e:
        neu = None
        print(f"[blow-auto] ⚠️ {pid[:8]} abgehakt, Konto NICHT archiviert ({type(e).__name__}: {e}) — im Account von Hand archivieren", flush=True)
    e4 = re.sub(r"[^A-Za-z0-9]", "", str(acc.get("external_id") or ""))[-4:]
    try:
        namen, _aus = _ap_namen()
    except Exception:
        namen = {}
    de = lambda v: f"{v:,.0f}".replace(",", ".")
    text = (f"{acc.get('firm') or 'Konto'}{' …' + e4 if e4 else ''}{' · ' + namen.get(uid, '') if namen.get(uid) else ''}: Balance "
            f"{de(k['nachher'])} $ ≤ Boden {de(k['boden'])} $ → geblowt, abgehakt ({'−' if k['pl'] < 0 else '+'}{de(abs(k['pl']))} $) · "
            + ("als geblowt archiviert" if neu else "war schon archiviert" if neu is False else "Archivieren fehlgeschlagen — von Hand"))
    zu = 0
    for ziel in ({uid} if uid else set()) | (_zw_admin_uids() or set()):
        try:
            a_, _b = push_an_user(ziel, "💀 Geblowt", text, "https://prophos.pages.dev/prophos#accounts", "blow-" + aid[:8])
            zu += a_
        except Exception as e:
            print(f"[blow-auto] ⚠️ Push {ziel[:8]}: {type(e).__name__}: {e}", flush=True)
    print(f"[blow-auto] 💀 Plan {pid[:8]} · {text} (Quelle {k['quelle']}, {zu} Geräte)", flush=True)
    return True


def ap_blow_auto_tick(force=False):
    """Alle AP_BLOW_AUTO_S: Pläne in 'review' gegen den Boden prüfen (ap_blow_auto_pruefen) und geblowte abhaken. → Anzahl | None."""
    if not force and time.time() - _ap_blow_auto["at"] < AP_BLOW_AUTO_S:
        return None
    _ap_blow_auto["at"] = time.time()
    plaene = _sb_all("trade_plans", {"select": "id,user_id,route,status,blown,master_account_id,master_name,konto_typ,mt5_baseline,"
                                               "ended_at,completed_at,started_at,updated_at",
                                     "status": "eq.review", "blown": "not.is.true", "route": f"in.({','.join(AP_BLOW_AUTO_ROUTEN)})"})
    plaene = [p for p in plaene or [] if p.get("master_account_id")]
    if not plaene:
        return 0
    ids = sorted({str(p["master_account_id"]) for p in plaene})
    konten = {str(a["id"]): a for a in sb_select("accounts", {
        "select": "id,user_id,name,firm,account_type,consistency_pct,ziel_pct_konto,max_drawdown,external_id,tv_balance,tv_balance_at",
        "id": f"in.({','.join(ids)})"}) or []}
    # (c) neuere Pläne je Konto (Reset-Riegel): jeder Plan desselben Kontos, der nach dem Ende dieses Plans angelegt wurde
    alle = _sb_all("trade_plans", {"select": "id,master_account_id,created_at", "master_account_id": f"in.({','.join(ids)})"}) or []
    firmen = ((sb_select("auto_plan_regeln", {"select": "regeln", "id": "eq.1"}) or [{}])[0].get("regeln") or {}).get("firmen") or []
    n = 0
    for p in plaene:
        acc = konten.get(str(p["master_account_id"]))
        try:
            ende = _ap_iso_ts(p.get("ended_at") or p.get("completed_at"))
            neuer = ende is None or any(str(q.get("master_account_id")) == str(p["master_account_id"]) and str(q.get("id")) != str(p["id"])
                                        and (_ap_iso_ts(q.get("created_at")) or 0) > ende for q in alle)
            k = ap_blow_auto_pruefen(p, acc, ap_regel_unternehmen(acc.get("user_id"), firmen, acc.get("firm")) if acc else None, neuer)   # UNT3
            if k and _ap_blow_auto_abhaken(p, acc, k):
                n += 1
        except Exception as e:
            print(f"[blow-auto] ⚠️ {str(p['id'])[:8]}: {type(e).__name__}: {e}", flush=True)
    if n:
        try:
            ap_archiv_sweep(force=True)          # geplante Trades der eben archivierten Konten sofort weg
        except Exception as e:
            print(f"[archiv-sweep] ⚠️ {type(e).__name__}: {e}", flush=True)
    _ap_blow_auto["n"] = n
    return n


# ══ GEBLOWTE KONTEN AUS „BRAUCHT DICH" VON SELBST ARCHIVIEREN (26.10.2026, Finn am Admin → Braucht dich, Topstep 150k Challenge, Chip
# „geblowt", „gelesen 145.447 $ · Boden 145.500 $", rechts „archivieren nur mit Admin-Login": „Der Current Balance unter dem Max Loss.
# Deswegen einfach hier automatisch wegblowen, fertig. Er muss mir nicht immer noch angezeigt werden."). Der Blow-Takt oben hakt PLÄNE in
# „Überprüfen" ab (Schalter abhaken_auto_blow, aus — geblowte Trades will Finn im Radar sehen, 21.10.2026); diese Zeilen sind KONTEN, die der
# Planer mit Grund „geblowt?" auslässt, ihre Trades sind schon abgehakt. Für sie gab es nur den Klick „Als geblowt archivieren" im Tab, beim
# fremden Konto nur mit Admin-Login. Jetzt alle AP_BLOW_KONTO_S: Geblowt-Zeilen des letzten Laufs (dieselbe Erkennung wie tplBraucht), Boden wie
# tplBlowBoden (boden → boden_min → Größe − Drawdown aus dem Grund), Lesung = accounts.tv_balance einer echten Lesung (Puls/MT5, keine
# Dashboard-Übernahme) NACH dem Ende des letzten Trades. Auf/unter dem Boden → Archiv des Besitzers „blown" (_konto_archiv_eintragen wie der
# Blow-Takt), ap_archiv_sweep räumt die geplanten Trades; GET /admin/auto-plan filtert die Zeile dann weg (ap_ohne_archiv). Läuft auf dem Konto
# ein Trade oder wartet einer aufs Abhaken (open/review), bleibt alles wie bisher. Kein Push. Aus nur per regeln.blow_konto_auto = false.
AP_BLOW_KONTO_S = 300
AP_BLOW_KONTO_RE = re.compile(r"geblasen|geblowt|Polster aufgebraucht", re.I)   # = istBlow in tplBraucht (prophos.html)
AP_BLOW_KONTO_QUELLEN = (None, "", "puls", "mt5", "auge")   # tv_balance_quelle einer eigenen Lesung; null = Puls (vor F11, 27.09.2026); auge = TopstepX-Auge (29.10.2026)
_ap_blow_konto = {"at": 0.0, "n": 0, "fehler": "", "letzt": []}


def ap_blow_konto_boden(zeile, acc):
    """REIN RECHNEND (testbar): Boden einer Geblowt-Zeile — der TIEFERE aus boden/boden_min (ap_boden_zeile), sonst Kontogröße − Drawdown
    aus dem Grundtext („… des Drawdowns 4.500 $", Größe wie kontoGroesseAnzeige/_wd_konto_groesse). → float | None (unbekannt).
    Nicht „boden zuerst" wie tplBlowBoden (S2-Befund 26.10.2026): boden ist das sichere Level, bei boden_art „nachziehend_geschaetzt" liegt es
    ÜBER dem echten Boden — ein Konto knapp darüber würde sonst archiviert (bei MT5 samt Echo-Löschauftrag). Archiviert wird nur unter beiden."""
    z = zeile or {}
    bs = [float(b) for b in (_wd_num(z.get(k)) for k in ("boden", "boden_min")) if b is not None and b > 0]
    if bs:
        return min(bs)
    m = re.search(r"Drawdowns\s+([\d.]+)\s*\$", str(z.get("grund") or ""))
    if not m:
        return None
    dd = float(m.group(1).replace(".", ""))
    g = _wd_konto_groesse({"name": z.get("konto") or (acc or {}).get("name"), "starting_balance": (acc or {}).get("starting_balance")}) or 0
    return g - dd if g > dd > 0 else None


def ap_blow_konto_pruefen(zeile, acc, plaene_konto, archiviert=False):
    """REIN RECHNEND (testbar): Konto dieser ausgelassen[]-Zeile jetzt als geblowt archivieren? → {balance, boden, at, quelle} oder None.
    Nur Geblowt-Grund, Konto nicht archiviert, kein Trade offen/in „Überprüfen", Boden bekannt, Lesung echt (AP_BLOW_KONTO_QUELLEN), jünger
    als das Ende des letzten Trades und ≤ Boden. Topstep Express liest 0-basiert (ist_topstep_express) → nie."""
    z = zeile or {}
    if archiviert or not acc or not AP_BLOW_KONTO_RE.search(str(z.get("grund") or "")):
        return None
    if str(acc.get("id") or "") != str(z.get("konto_id") or "") or ist_topstep_express(acc):
        return None
    plaene_konto = list(plaene_konto or ())
    if any(str(p.get("status") or "") in ("open", "review") for p in plaene_konto):
        return None                                # Trade läuft oder wartet aufs Abhaken → Radar, Finn
    if acc.get("tv_balance_quelle") not in AP_BLOW_KONTO_QUELLEN:
        return None                                # Dashboard-Übernahme — keine Lesung nach dem Trade
    bal, at = _wd_num(acc.get("tv_balance")), acc.get("tv_balance_at")
    at_ts = _ap_iso_ts(at)
    if bal is None or bal <= 0 or at_ts is None:
        return None
    enden = [t for t in (_ap_iso_ts(p.get("ended_at") or p.get("completed_at")) for p in plaene_konto) if t is not None]
    if not enden or at_ts <= max(enden):
        return None                                # kein Wert älter als der letzte Trade (und ohne Trade kein „geblowt?")
    boden = ap_blow_konto_boden(z, acc)
    if boden is None or bal > boden:
        return None
    return {"balance": round(bal, 2), "boden": round(boden, 2), "at": str(at), "quelle": acc.get("tv_balance_quelle") or "puls"}


# NUR CHALLENGE-LÄUFE (30.10.2026, Befund S3): der Funded-Planer (quelle 'funded') und der Funded-CFD-Planer ('funded_cfd') schreiben ihre
# Läufe ebenfalls in auto_plan_lauf. Wer den letzten Lauf des CHALLENGE-Planers liest (GET /admin/auto-plan, /ids, Nachplanen, Balance-Takt,
# Blow-Takt, Hypo-Bilanz), nahm sonst den jüngsten Funded-CFD-Lauf (Waiting-for-Payout-Zeilen in Challenge „Braucht dich"). Ältere Zeilen
# ohne quelle bleiben drin. Funded-Läufe liest niemand aus dieser Tabelle zurück (fdp/fcp rechnen frisch).
AP_LAUF_NUR_CHALLENGE = {"or": "(quelle.is.null,quelle.not.in.(funded,funded_cfd))"}


def ap_blow_konto_tick(force=False):
    """Alle AP_BLOW_KONTO_S: Geblowt-Zeilen des letzten Planer-Laufs prüfen (ap_blow_konto_pruefen) und das Konto als geblowt archivieren.
    → Anzahl neu archivierter Konten | None (nicht dran)."""
    if not force and time.time() - _ap_blow_konto["at"] < AP_BLOW_KONTO_S:
        return None
    _ap_blow_konto["at"] = time.time()
    reg = (sb_select("auto_plan_regeln", {"select": "regeln", "id": "eq.1"}) or [{}])[0].get("regeln") or {}
    if reg.get("blow_konto_auto") is False:
        return 0
    rows = sb_select("auto_plan_lauf", dict(AP_LAUF_NUR_CHALLENGE, select="tag,at,ergebnis", order="at.desc", limit="1"))   # derselbe Lauf wie GET /admin/auto-plan
    erg = (rows[0].get("ergebnis") if rows else None) or {}
    zeilen = [z for z in (erg.get("ausgelassen") if isinstance(erg, dict) else None) or []
              if isinstance(z, dict) and z.get("konto_id") and AP_BLOW_KONTO_RE.search(str(z.get("grund") or ""))]
    if not zeilen:
        return 0
    ids = sorted({str(z["konto_id"]) for z in zeilen})
    archiv = _ap_archiviert(streng=True)
    konten = {str(a["id"]): a for a in sb_select("accounts", {
        "select": "id,user_id,name,firm,account_type,starting_balance,external_id,tv_balance,tv_balance_at,tv_balance_quelle",
        "id": f"in.({','.join(ids)})"}) or []}
    plaene = _sb_all("trade_plans", {"select": "id,master_account_id,status,ended_at,completed_at",
                                     "master_account_id": f"in.({','.join(ids)})"}) or []
    n, letzt = 0, []
    for z in zeilen:
        kid = str(z["konto_id"])
        acc = konten.get(kid)
        try:
            k = ap_blow_konto_pruefen(z, acc, [p for p in plaene if str(p.get("master_account_id")) == kid], kid in archiv)
            if not k:
                continue
            uid = str(acc.get("user_id") or z.get("user_id") or "")
            if not uid:
                continue
            jetzt_iso = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
            if _konto_archiv_eintragen(uid, kid, "blown", jetzt_iso, acc.get("name")):
                n += 1
                archiv.add(kid)
                letzt.append({"konto_id": kid, "user_id": uid, "konto": acc.get("name"), "firma": acc.get("firm"), **k, "archiviert_at": jetzt_iso})
                print(f"[blow-konto] 💀 {acc.get('firm') or 'Konto'} {acc.get('name') or kid[:8]} ({uid[:8]}): Lesung {k['balance']:.2f} $ "
                      f"({k['quelle']}, {k['at']}) ≤ Boden {k['boden']:.2f} $ → als geblowt archiviert", flush=True)
        except Exception as e:
            print(f"[blow-konto] ⚠️ {kid[:8]}: {type(e).__name__}: {e}", flush=True)
    _ap_blow_konto["n"] = n
    if letzt:
        _ap_blow_konto["letzt"] = (letzt + _ap_blow_konto["letzt"])[:20]
    return n



# ══ NORMALE TRADES AUTOMATISCH ABHAKEN (14.10.2026, Finn am Radar „Erledigt · Abhaken 8": „die ganz normalen Trades, bei denen einfach
# nichts passiert — kein Blow, nicht bestanden — müsst ihr mir nicht jedes Mal zeigen, die können insta selber abgehakt werden. Bestanden
# oder geblowt will ich einmal sehen, und wenn irgendwas nicht klar ist, erledige ich sie"). Das Gegenstück zum Blow-Takt, im selben
# ap_loop-Takt (AP_BLOW_AUTO_S) und mit denselben Riegeln: nur echte Lesungen vorher/nachher (ap_echte_balancen, nie Demo/Hand/Schätzung),
# Routen Orbit V2 / Echo V2 ohne Hedge, Phase des Plans = Phase des Kontos (Challenge/Phase 1/Phase 2), Firmen-Regel ohne Kette. „Normal" =
# Ende ÜBER dem Boden und UNTER dem Ziel der Phase (zw_ziel, dieselbe Rechnung wie die Ziel-Wache), Konto ohne Ziel-Tag, kein Balance-Sprung
# (Auszahlung o. Ä.), kein Kennzeichen „Manuelle Arbeit"/Review. Tage-Mini zählt seit 21.10.2026 NICHT mehr als
# normal (sofort von Hand zu, Konto bestanden — Finn: „genau wie ich es gesagt habe“). Abhaken = dasselbe Update wie der Knopf (_wd_erledigt_upd, P&L = nachher − vorher), Kennzeichen
# mt5_baseline.auto_abgehakt. Alles andere bleibt in „Abhaken" für Finn. Kein Push — es ist ja nichts passiert.
AP_NORMAL_AUTO_ROUTEN = AP_BLOW_AUTO_ROUTEN
_ap_normal_auto = {"n": 0, "fehler": ""}
# NUR WENN NICHTS PASSIERT IST (Finn 21.10.2026 ~21:55 Dubai, nach 11 still archivierten Blow-Plänen um 21:48: „Automatisch abhaken nur,
# wenn ein normaler Orbit- oder normaler Echo-Trade ohne Gegenhedge gelaufen ist und NICHTS passiert ist. Sehen will ich weiter: geblowt,
# bestanden, Rest/Take-Profit-Fälle, bei denen ich entscheide, ob es zum Planer geht"). Dieselben Grenzen wie der Radar:
# Rest bis Ziel unter AP_FEHLT_ZEIGEN_USD = Radar-Chip „fehlen noch … → Rest von Hand" (WDL_FEHLT_ZEIGEN_USD) → Finn;
# Ende nur am TP oder SL — Orbit V2 mit Demo-Ende demo_tp/demo_sl (Vorzeichen passt zum P&L), sonst (Echo V2 schreibt keinen Grund,
# Orbit nach reader_leer) echter P&L ≈ +master_tp bzw. −master_sl (± AP_NORMAL_TPSL_TOL, mind. AP_NORMAL_TPSL_MIN_USD — Schlupf/Kommission);
# Schließen-Knopf, Auto-Close, Hand-Ende, Tage-Mini (sofort zu) nie. Konto weg / nicht erreicht / TopstepX-Blow-Beweis an der Endlesung → Finn (so kann auch
# „wahrscheinlich bestanden · nicht mehr im Dropdown" nie hier landen — dort fehlt ohnehin die echte Endbalance).
AP_FEHLT_ZEIGEN_USD = 500
AP_NORMAL_TPSL_TOL = 0.15
AP_NORMAL_TPSL_MIN_USD = 50.0
AP_NORMAL_HAND_GRUENDE = ("beendet_knopf", "hand", "close", "demo_beide", "demo_liq", "demo_unklar", "demo_konto_weg", "demo_konto_unklar", "konto_weg", "tsx_geblowt")


def ap_normal_tpsl_ende(plan, pl):
    """REIN RECHNEND (testbar): Endete der Trade am TP oder SL? → 'tp' | 'sl' | None (unklar/von Hand → Finn)."""
    p = plan or {}
    bl = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    fin = bl.get("final") if isinstance(bl.get("final"), dict) else {}
    grund = str(fin.get("grund") or "")
    if grund in AP_NORMAL_HAND_GRUENDE or str(fin.get("ende_quelle") or "") in ("close", "hand") or str(fin.get("quelle") or "") in ("close", "hand"):
        return None                                # Schließen-Knopf / Auto-Close / Liquidation / unklares Demo-Ende
    if grund in ("demo_tp", "demo_sl"):
        return ("tp" if pl > 0 else None) if grund == "demo_tp" else ("sl" if pl < 0 else None)
    tp, sl = _wd_num(p.get("master_tp")), _wd_num(p.get("master_sl"))
    nah = lambda soll: abs(pl - soll) <= max(AP_NORMAL_TPSL_MIN_USD, abs(soll) * AP_NORMAL_TPSL_TOL)
    if tp and tp > 0 and pl > 0 and nah(tp):
        return "tp"
    if sl and abs(sl) > 0 and pl < 0 and nah(-abs(sl)):
        return "sl"
    return None


def ap_normal_auto_pruefen(plan, acc, regel):
    """REIN RECHNEND (testbar): normaler Trade laut echter Lesung? → {vorher, nachher, pl, boden, ziel, quelle} oder None (s. o.)."""
    p = plan or {}
    if p.get("status") != "review" or p.get("blown") is True or str(p.get("route") or "") not in AP_NORMAL_AUTO_ROUTEN:
        return None
    if not acc or not regel or ap_kette_regel(regel):
        return None
    phase = str(p.get("konto_typ") or acc.get("account_type") or "")
    if phase not in AP_TYPEN:
        return None
    if p.get("konto_typ") and acc.get("account_type") and str(p.get("konto_typ")) != str(acc.get("account_type")):
        return None                                # Konto ist inzwischen in einer anderen Phase
    bl = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    if bl.get("hedge") or (_wd_num(p.get("hedge_eur")) or 0) > 0:
        return None                                # Hedge-P&L gehört dazu → von Hand
    if isinstance(bl.get("kette"), dict) and bl["kette"].get("von"):
        return None                                # WS2-Kette (09.11.2026): Teile hakt tt_tick ab, den letzten Finn einmal am Tagesergebnis
    m = bl.get("manuell")
    if isinstance(m, dict) and m.get("at"):
        return None                                # Finn hat ihn nach „Manuelle Arbeit"/Review gelegt
    if acc.get("ziel_erreicht_at"):
        return None                                # bestanden → Finn will es sehen (auch Tage-Mini, s. u.)
    tv = bl.get("tv") if isinstance(bl.get("tv"), dict) else {}
    fin = bl.get("final") if isinstance(bl.get("final"), dict) else {}
    if lt_balance_sprung(str(p.get("route") or ""), tv, fin):
        return None                                # Balance-Differenz ≠ Tages-P&L
    echt = ap_echte_balancen(p)
    if not echt:
        return None
    vorher, nachher, q = echt
    try:
        rk = ap_regel_konto(regel, acc, vorher)
        bo = (ap_boden_konto(rk, phase, vorher) or {}).get("boden")
        zg = zw_ziel(rk, phase, vorher)
    except Exception:
        return None
    if bo is None or nachher <= float(bo):
        return None                                # Blow (macht der Blow-Takt) oder Boden unbekannt
    if not zg or zw_erreicht(zg[0], nachher, phase):
        return None                                # bestanden oder Ziel unbekannt
    if fin.get("konto_weg") or fin.get("konto_weg_vermutet") or fin.get("konto_geblowt") \
            or re.match(r"konto_(nicht_erreicht|weg|geblowt)", str(fin.get("puls_fehler") or "")):
        return None                                # Konto weg / unklare Lesung → Finn (21.10.2026)
    if float(zg[0]) - nachher < AP_FEHLT_ZEIGEN_USD:
        return None                                # „fehlen noch … → Rest von Hand / Planer" — Finn entscheidet (21.10.2026)
    ende = ap_normal_tpsl_ende(p, nachher - vorher)
    if not ende:
        return None                                # nicht am TP/SL beendet (von Hand, Auto-Close, Tage-Mini sofort zu, unklar) → Finn
    return {"vorher": vorher, "nachher": nachher, "pl": round(nachher - vorher, 2), "boden": float(bo),
            "ziel": float(zg[0]), "quelle": q, "ende": ende}


def _ap_normal_auto_abhaken(plan, k):
    """Einen normalen Plan abhaken (completed, P&L aus der Lesung). Optimistische Sperre: nur solange er unverändert in 'review' steht."""
    pid = str(plan["id"])
    jetzt_iso = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    upd, fehler = _wd_erledigt_upd(plan, k["pl"], None, jetzt_iso, _cme_handelstag())
    if fehler:
        print(f"[normal-auto] {pid[:8]} nicht abgehakt: {fehler[1]}", flush=True)
        return False
    base = upd.get("mt5_baseline") or (plan.get("mt5_baseline") if isinstance(plan.get("mt5_baseline"), dict) else {})
    upd["mt5_baseline"] = dict(base, auto_abgehakt={"at": jetzt_iso, "quelle": k["quelle"], "vorher": k["vorher"], "nachher": k["nachher"]})
    filt = {"id": f"eq.{pid}", "status": "eq.review", "blown": "not.is.true"}
    if plan.get("updated_at"):
        filt["updated_at"] = f"eq.{plan['updated_at']}"
    if not sb_update("trade_plans", filt, upd):
        return False
    print(f"[normal-auto] ✓ Plan {pid[:8]} · {plan.get('master_name') or ''} · {k['pl']:+.2f} $ ({k['vorher']:.2f} → {k['nachher']:.2f}, "
          f"Boden {k['boden']:.0f}, Ziel {k['ziel']:.0f}, Ende {k['ende']}) abgehakt", flush=True)
