            upd["mt5_baseline"] = dict(base, auto_abgehakt={"at": jetzt_iso, "quelle": k["quelle"], "grund": k["grund"]})
            filt = {"id": f"eq.{pid}", "status": "eq.review", "blown": "not.is.true"}
