# Keine Regel- oder Risikoprüfung — nur der Zustand des Plans. Nie ein Plan, dessen Start oder Claim < 2 h her ist (wie wd_plan_wegraeumbar).
TR_FILL_FELDER = ("today_pnl", "balance_end", "exit_fill", "einstieg", "einstieg_nq", "einstieg_fill", "master_pl", "master_pl_schaetzung",
                  "preis", "ticket")
TR_GRUND = "tagesende_unklar"


def tagesreset_tag(p, tz):
    """REIN RECHNEND: Handelstag eines Plans als 'JJJJ-MM-TT' — planned_for, sonst das Datum von start_um in tz, sonst None."""
    pf = str(p.get("planned_for") or "").strip()[:10]
    if len(pf) == 10:
        return pf
    t = _ap_ts(p.get("start_um"))
    return t.astimezone(tz).strftime("%Y-%m-%d") if t else None


def tagesreset_hinweis(p):
    """REIN RECHNEND: Beleg, dass eine Order am Konto sein KANN (→ nie löschen) — Text oder None. Nur was am Plan steht."""
    b = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    fin = b.get("final") if isinstance(b.get("final"), dict) else None
    sf = b.get("start_fehler") if isinstance(b.get("start_fehler"), dict) else None
    if p.get("orbit_gesendet_at"):
        return "Order an Orbit gesendet"
    if b.get("hedge"):
        return "Fusion-Hedge am Plan"
    if b.get("puls_unklar"):
        return "Puls-Ergebnis unklar (Klick kann raus sein)"
    if sf and (sf.get("unklar") is True or str(sf.get("schritt") or "") == "unklar"):
        return "Start-Fehler unklar (Order kann raus sein)"
    if b.get("ticket") or (isinstance(b.get("live"), dict) and b["live"].get("offen")):
        return "Ticket/Position am Plan"
    if isinstance(b.get("tv"), dict) and b["tv"]:
        return "TradingView-Spur am Plan (Puls war bis zur Order)"
    # Polar (S2-Prüfung 21.10.2026): polar_auftrag schreibt /polar/plan schon beim SPEICHERN — kein Lauf. Ein Lauf steht in polar_lauf
    # (eingebettet geladen) bzw. als Abrechnung in mt5_baseline.polar
    if b.get("polar") or p.get("polar_lauf"):
        return "Polar-Lauf am Plan"
    if b.get("versuche_alt"):
        return "Leer-Versuche mit Fusion-Hedge am Plan"
    if b.get("puls_pause"):
        return "Puls-Pause-Marke (Trade evtl. von Hand)"
    if fin is not None:
        if any(fin.get(k) not in (None, "", 0, False) for k in TR_FILL_FELDER):
            return "Fill-/Ergebnis-Beleg im Ende-Eintrag"
        if not fin.get("puls_aufgegeben"):
            return "Ende-Eintrag ohne Aufgabe"
    return None


def tagesreset_art(p, tag, jetzt, tz):
    """REIN RECHNEND (testbar, selftest_tagesreset.py): was der Nachtlauf mit Plan p macht, wenn `tag` (JJJJ-MM-TT, Zieltag des
    Nachtlaufs) beginnt → {"art": 'weg'|'pruefen'|None, "grund": str}. None = nicht betroffen (läuft/lief, heute oder später, Start oder
    Claim < 2 h her, kein Datum)."""
    if str(p.get("status") or "") != "planned" or p.get("started_at"):
        return {"art": None, "grund": "nicht geplant oder schon gestartet"}
    ptag = tagesreset_tag(p, tz)
    if not ptag or ptag >= str(tag):
        return {"art": None, "grund": "Plan ohne Datum oder für heute/später"}
    st = _ap_ts(p.get("start_um"))                        # _ap_ts statt wd_plan_wegraeumbar: liest auch „ +00"/Nachkommastellen
    if p.get("start_um") and (not st or st >= jetzt - timedelta(hours=2)):
        return {"art": None, "grund": "Start < 2 h her oder steht noch bevor"}
    claim = _ap_ts(p.get("start_um_gestartet_at"))
    if claim and claim >= jetzt - timedelta(hours=2):
        return {"art": None, "grund": "Claim < 2 h her"}
    h = tagesreset_hinweis(p)
    if h:
        return {"art": "pruefen", "grund": h}
    # Gespeicherter Polar-Plan ohne Lauf (S2-Prüfung 21.10.2026; S1 baut „speichern, später starten"): bleibt stehen — Finns Handarbeit,
    # kein Konto-Blocker des Auto-Planers. Ob er nachts weg soll, entscheidet der Master (dann hier "weg" statt None).
    if str(p.get("route") or "") == "polar":
        return {"art": None, "grund": "Polar-Plan ohne Lauf (gespeichert, nie gestartet) — bleibt stehen"}
    b = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    fin = b.get("final") if isinstance(b.get("final"), dict) else None
    sf = b.get("start_fehler") if isinstance(b.get("start_fehler"), dict) else None
    if not claim:
        return {"art": "weg", "grund": "nie gestartet (kein Claim)"}
    if fin is not None and fin.get("puls_aufgegeben"):
        return {"art": "weg", "grund": "Puls gab vor dem Kauf auf: " + str(fin.get("puls_fehler") or fin.get("grund") or "?")[:80]}
    sf_at = _ap_ts((sf or {}).get("at"))
    if sf and sf.get("unklar") is False and sf_at and sf_at >= claim:
        return {"art": "weg", "grund": f"Start-Fehler ohne Order ({sf.get('schritt') or '?'}, Bot: nichts platziert)"}
    return {"art": "pruefen", "grund": "geclaimt, aber kein Ergebnis am Plan"}


def ap_tagesreset(tag, jetzt, trocken=False):
    """NACHTLAUF (21.10.2026): liegengebliebene Pläne früherer Tage aufräumen — tagesreset_art je Plan, dann löschen bzw. nach
    „Überprüfen". Guards in derselben Anfrage (noch planned, nie gestartet/gesendet, Claim unverändert alt), Fehler je Plan nur
    protokolliert. trocken = nur einteilen. → {"weg": [...], "pruefen": [...], "fehler": n}"""
    tz = _ap_tz("Asia/Dubai")
    tag0 = datetime.fromisoformat(str(tag)).replace(tzinfo=tz)
    sel = ("id,user_id,route,status,auto_plan,notes,master_name,planned_for,start_um,start_um_gestartet_at,orbit_gesendet_at,started_at,"
           "result_notes,mt5_baseline,polar_lauf(id,status)")
    rows = (_sb_all("trade_plans", {"select": sel, "status": "eq.planned", "started_at": "is.null", "planned_for": f"lt.{tag}", "order": "id.asc"}) or []) \
        + (_sb_all("trade_plans", {"select": sel, "status": "eq.planned", "started_at": "is.null", "planned_for": "is.null",
                                   "start_um": f"lt.{tag0.isoformat()}", "order": "id.asc"}) or [])
    out = {"weg": [], "pruefen": [], "fehler": 0}
    alt = (jetzt - timedelta(hours=2)).astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")   # ohne „+"/Nachkommastellen im or-Filter
    for p in rows:
        e = tagesreset_art(p, tag, jetzt, tz)
        if not e["art"]:
            continue
        pid = str(p["id"])
        z = {"plan_id": pid, "user_id": p.get("user_id"), "konto": p.get("master_name"), "tag": tagesreset_tag(p, tz), "grund": e["grund"]}
        if trocken:
            out[e["art"]].append(z)
            continue
        # Guards (S2-Prüfung 21.10.2026): beide nur „noch planned, nie gestartet, Claim leer oder alt"; „nie an Orbit gesendet" NUR beim
        # Löschen — ein gesendeter Plan ist gerade ein pruefen-Fall, mit diesem Guard fände das Update ihn nie (blieb still planned liegen)
        guard = {"id": f"eq.{pid}", "status": "eq.planned", "started_at": "is.null",
                 "or": f"(start_um_gestartet_at.is.null,start_um_gestartet_at.lt.{alt})"}
        try:
            if e["art"] == "weg":
                if sb_delete("trade_plans", dict(guard, orbit_gesendet_at="is.null")):
                    out["weg"].append(z)
                else:
                    print(f"[tages-reset] {pid[:8]}: nicht gelöscht — Plan hat sich seit dem Lesen geändert (Guard)", flush=True)
                continue
            hinweis = f"Plan von {z['tag'] or 'gestern'} nie fertig — Order am Konto prüfen ({e['grund']})"
            ende = p.get("start_um") or f"{z['tag']}T12:00:00+00:00"
            alt_n = str(p.get("result_notes") or "").strip()
            notiz = "Tages-Reset (Nachtlauf): " + hinweis
            if not sb_update("trade_plans", guard, {"status": "review", "ended_at": ende,
                                                    "result_notes": (alt_n + "\n" + notiz) if alt_n else notiz}):
                print(f"[tages-reset] {pid[:8]}: nicht nach Überprüfen — Plan hat sich seit dem Lesen geändert (Guard)", flush=True)
                continue
            # Ende am toten Tag (wie _ap_leichen_abschliessen): keine Demo-/Userscript-Nachlese von heute; kein today_pnl = nicht „gelesen"
            _b = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
            fin = dict(_b["final"]) if isinstance(_b.get("final"), dict) else {}
            fin.update(grund=TR_GRUND, art="unklar", quelle="tagesreset", hinweis=hinweis, at=ende, datum=z["tag"],
                       tagesreset_at=jetzt.isoformat())
            rr = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/rpc/mt5_baseline_patch", headers=_sb_headers(), timeout=(5, 15),
                             json={"p_plan": pid, "p_patch": {"final": fin}, "p_status": "review"})
            _sb_pruefen(rr)
            out["pruefen"].append(z)
        except Exception as ex:
            out["fehler"] += 1
            print(f"[tages-reset] ⚠️ {pid[:8]}: {type(ex).__name__}: {ex}", flush=True)
    if out["weg"] or out["pruefen"] or out["fehler"]:
        print(f"[tages-reset] {tag}: {len(out['weg'])} weg ({', '.join(x['plan_id'][:8] for x in out['weg'])}) · "
              f"{len(out['pruefen'])} → Überprüfen ({', '.join(x['plan_id'][:8] for x in out['pruefen'])})"
              f"{' · ' + str(out['fehler']) + ' Fehler' if out['fehler'] else ''}{' (trocken)' if trocken else ''}", flush=True)
    return out


def _ap_fest_ref(p, mitternacht, jetzt):
    """Bezug eines festlegenden Plans für ap_fest_am_start (09.10.2026): (Minute ab `mitternacht` | None, Richtung, läuft).
    Laufend: Start (started_at), unbekannt → jetzt; geplant: start_um, ohne Startzeit None (gilt dann vorsichtshalber den ganzen Tag)."""
    def minute(roh):
        t = _ap_ts(roh)                # Postgres-Formen („ +00", 1–6 Nachkommastellen) sicher
        return (t - mitternacht).total_seconds() / 60.0 if t else None
    if p.get("status") == "open":
        # LÄUFT = legt die Richtung fest, solange er läuft (Finn 09.10.2026 ~09:25 Dubai: „Gegenrichtung ist verboten"; Anlass Topstep-Kette
        # 333d4791 BUY gegen d369e8d5 SELL derselben ID) — das Ende ist unbekannt, also ohne 90-min-Fenster: Minute None = ganzer Tag
        return (None, p.get("richtung"), True)
    if ap_claim_laeuft(p, jetzt):   # frisch geclaimt/gesendet ohne Start-Fehler = Start läuft
        m = minute(p.get("start_um"))
        return (m if m is not None else (jetzt - mitternacht).total_seconds() / 60.0, p.get("richtung"), True)
    return (minute(p.get("start_um")), p.get("richtung"), False)


def ap_richtung_fest_plan(p, tag, tz):
    """REIN RECHNEND (07.10.2026, Richtungsschutz nur gleichzeitig): legt Plan p die Richtung seiner ID+Firma für den Tag `tag`
    (deutsches Datum) fest? Ja, wenn er läuft (open) oder am selben Tag geplant ist (planned_for bzw. Start in dt) — ohne
    beides vorsichtshalber ja. Beendete Trades und Pläne anderer Tage nie."""
    if p.get("richtung") not in ("buy", "sell"):
        return False
    if p.get("status") == "open":
        return True
    if p.get("status") != "planned":
        return False
    if p.get("start_um"):
        try:
            t = datetime.fromisoformat(str(p["start_um"]).replace("Z", "+00:00"))
            if t.tzinfo is None:
                t = t.replace(tzinfo=timezone.utc)
            return t.astimezone(tz).strftime("%Y-%m-%d") == tag
        except ValueError:
            pass
    if p.get("planned_for"):
        return str(p["planned_for"])[:10] == tag
    return True


# FINALER TRADEIFY HALTEN (Finn 29.10.2026 ~16:05 Dubai, Master „TRADEIFY-FINAL-HALTEN"): finale Tradeify-Futures-Trades (TP erreicht oder
# überschreitet das Ziel, z. B. 157k → 159k) starten nicht, bis die Gegenhedge-Logik für den letzten Trade steht — sie werden nicht geplant
# (ap_planen: Grund AP_TRADEIFY_FINAL_GRUND) und ein schon geplanter startet nicht (DB-Trigger trade_plans_a_final_halten, sql/2026-10-29_
# tradeify_final_halten.sql: bleibt planned, Start +1 Tag gestreut, hand_werte_at schützt vor dem Löschen, ⚪ über alarm_tick). Schalter
# auto_plan_regeln.regeln.tradeify_final_halten (fehlt = AN). Tradeify CFD, andere Firmen und nicht-finale Trades laufen weiter.
AP_TRADEIFY_FINAL_GRUND = "finaler Tradeify-Trade wartet auf Gegenhedge"


def ap_tradeify_final_halten(regeln, firma, w):
    """REIN RECHNEND (testbar): hält der Planer diesen Trade zurück? Nur Tradeify Futures (nie Tradeify CFD), nur bei Schalter an, nur final —
    dieselbe Regel wie prophos_plan_final_text in der DB: Stufe „letzter Trade"/„Klein-Trade" ist final, „Tage sammeln" nie, sonst TP ≥ Rest
    bis Ziel (Rest ≤ 0 = Ziel schon erreicht)."""
    if (regeln or {}).get("tradeify_final_halten") is False:
        return False
    if tfh_param(regeln)["an"]:
        return False                    # Gegenhedge-Weg an (tfh_tick): finale Trades werden geplant und kurz vor dem Start Orbit V3
    f = re.sub(r"[^a-z0-9]", "", str(firma or "").lower())
    if "tradeify" not in f or _ist_tradeify_cfd(firma):
        return False
    stufe = str((w or {}).get("stufe") or "")
    if stufe.startswith("Tage sammeln"):
        return False
    if stufe.startswith("letzter Trade") or stufe.startswith("Klein-Trade"):
        return True
    rest, tp = _wd_num((w or {}).get("rest")), _wd_num((w or {}).get("tp"))
    if rest is None:
        return False
    return rest <= 0 or (tp is not None and tp > 0 and tp >= rest)


def ap_planen(tag=None, trocken=False, quelle="hand", nur_uid=None, seed=None, sicht_uid=None, fingerabdruck=None, ids=None,
              nur_konten=None, gruppe=None):
    """Plant den Tag `tag` (Dubai-Datum, Standard heute) für alle IDs aus auto_plan_regeln. trocken = nur rechnen.
    quelle 'nacht' claimt den Tag (ein Lauf je Tag). Hand-Lauf am selben Tag: unbestätigte Auto-Pläne werden ersetzt,
    Startzeiten frühestens jetzt + 10 min. → Ergebnis-Dict (auch in auto_plan_lauf).
    06.10.2026 (Probelauf-Ansicht, Finn: „er will alles sichtbar haben und am Frontend durchgehen"): seed macht den Lauf
    wiederholbar — derselbe seed auf demselben Datenstand legt GENAU an, was der Probelauf zeigte (Konten/Pläne geordnet,
    unbestätigte Vorschläge zählen auch im Probelauf nicht, gelöscht wird erst direkt vor dem Anlegen). fingerabdruck
    (aus dem Probelauf) beim Anlegen: weicht der neue Stand ab, wird nichts gelöscht und nichts angelegt. trocken liefert
    zusätzlich tranchen[] + ausgleich{} (Kontowert in €, Delta €/Pkt je Konto/Tranche, Netto-Verlauf, Band).
    06.10.2026 (Delta-Vertrag + Korrektur Finn): Richtung je Tranche nach delta_eur_pkt (ap_richtungen_delta), je PC nie zwei Starts zugleich.
    sicht_uid: Antwort nur mit den Zeilen dieser ID (Nicht-Admin); geplant wird trotzdem über alle IDs.
    ids="alle" (PROBELAUF-ALLE-IDS, 07.10.2026): nur mit trocken — rechnet über alle IDs mit Konten in AP_TYPEN statt
    auto_plan_regeln.user_ids (ap_ids_laden), legt nie an, schreibt kein Protokoll; Antwort zusätzlich ids_benutzt[].
    nur_konten (NACHPLANEN, 08.10.2026, Finn setzte um 01:20 fünf IDs in den Planer — sie bekamen bis zum nächsten Nachtlauf
    nichts): nur GENAU diese Konto-IDs werden gerechnet und angelegt; bestehende Vorschläge/bestätigte Pläne zählen als
    vorhanden und werden NIE gelöscht oder ersetzt (anders als Hand-/Nachtlauf), Startzeiten frühestens jetzt + 15 min,
    Protokoll in auto_plan_lauf nur, wenn etwas geplant wurde (kein Log-Spam alle 10 min). Delta/Richtung: dieselbe Strecke.
    gruppe (GRUPPE WIE HT, 30.10.2026, Finn: „Emins Trades sollen eins zu eins mit der gleichen Logik geplant werden wie bei Hermann
    Technologies … er bestätigt sie einzeln" + „Emin hat eine eigene Waage zwischen Long und Short … jede Gruppe wiegt für sich"):
    {gruppe_id, name, ids} einer Verwalter-Gruppe (ap_planer_gruppen) — geplant werden GENAU ihre IDs statt auto_plan_regeln.user_ids,
    mit derselben Strecke (Regeln, Zeiten, Tagesdeckel, Richtung/Delta, Abstände). Der Live-Stand (laufende/geplante Trades, Waage,
    Firma × Tag, PC-Belegung) kommt nur aus der Gruppe (ap_gruppe_ausgeblendet), HT blendet die Gruppe weiter aus. Kein Nacht-Claim und
    kein Protokoll in auto_plan_lauf (HTs „letzter Lauf" bleibt HT) — Claim und Protokoll schreibt ap_gruppe_planen in auto_plan_gruppe."""
    reg = (sb_select("auto_plan_regeln", {"select": "*", "id": "eq.1"}) or [None])[0]
    if not reg:
        return {"ok": False, "msg": "auto_plan_regeln fehlt (SQL 2026-10-05_auto_planer.sql einspielen)"}
    if gruppe:   # REGEL JE UNTERNEHMEN (Phase 1): die Gruppe plant mit Standard + ihren Abweichungen (ap_reg_unternehmen); ohne Abweichung = Standard
        try:
            reg = ap_reg_unternehmen(reg, (sb_select("auto_plan_gruppe", {"select": "*", "gruppe_id": f"eq.{gruppe.get('gruppe_id')}"}) or [None])[0])
        except Exception as e:   # fail-closed (Fremd-Review): nie still mit HT-Werten für die Gruppe planen
            print(f"[auto-plan] ⚠️ Regel des Unternehmens {str(gruppe.get('gruppe_id'))[:8]}: {type(e).__name__}: {e} — nicht geplant", flush=True)
            return {"ok": False, "msg": f"Regel des Unternehmens nicht lesbar ({type(e).__name__}) — nicht geplant"}
    alle_ids = bool(ids) and ap_ids_alle(ids, trocken)      # PROBELAUF-ALLE-IDS (07.10.2026): nur im Probelauf, nie beim Anlegen
    uids = ap_ids_laden() if alle_ids else [str(u) for u in (reg.get("user_ids") or [])]
    if gruppe:
        uids = sorted(str(u) for u in (gruppe.get("ids") or ()))   # GRUPPE WIE HT (30.10.2026): genau die IDs der Verwalter-Gruppe
    else:   # UNT2 (G2 A4): der HT-Lauf plant nie IDs einer Verwalter-Gruppe — auch wenn sie in user_ids stünden (live 0); Gruppen nicht lesbar → nicht planen
        try:
            _ht = ap_unternehmen_filter(None, admin_gruppen_daten())
        except Exception as e:
            print(f"[auto-plan] ⚠️ Gruppen nicht lesbar ({type(e).__name__}: {e}) — HT nicht geplant", flush=True)
            return {"ok": False, "msg": f"Gruppen nicht lesbar ({type(e).__name__}) — nicht geplant (sonst ohne Trennung der Unternehmen)"}
        _weg_u = [u for u in uids if not _ht(u)]
        if _weg_u:   # UNT0: ID ohne Unternehmen (oder Verwalter-Gruppe) plant nicht mit HT — erst zuordnen (Admin), dann plant ihr Unternehmen
            print(f"[auto-plan] ℹ️ {len(_weg_u)} ID(s) nicht im HT-Lauf (Verwalter-Gruppe oder ohne Unternehmen): {', '.join(u[:8] for u in _weg_u)}", flush=True)
        uids = [u for u in uids if _ht(u)]
    if nur_uid and nur_uid not in uids:
        return {"ok": False, "msg": "Diese ID ist nicht im Auto-Planer"}
    if not uids:
        return {"ok": False, "msg": "Keine ID mit Konten in challenge/phase1/phase2" if alle_ids
                else "Keine IDs im Auto-Planer (auto_plan_regeln.user_ids leer)"}
    zeiten = ap_zeiten_mit_zufall(reg)          # E3b (05.11.2026): + _zufall aus regeln.zufall (Rückfall Code) — nur im Speicher
    firmen = (reg.get("regeln") or {}).get("firmen") or []
    _fm_gruppe = None                                  # MO1c: Gruppen-Lauf — firmen_modell der Gruppe schaltet Firmen an/aus (ap_gruppe_firma_an)
    if gruppe:
        try:
            _fm_gruppe = next((v for u, v in ap_gruppen_modelle().items() if u in {str(x) for x in (gruppe.get("ids") or ())}), {})
        except Exception as e:
            print(f"[auto-plan] ⚠️ Firmen der Gruppe: {type(e).__name__}: {e} — wie HT", flush=True)
            _fm_gruppe = {}
    jetzt = datetime.now(timezone.utc)
    tag = tag or jetzt.astimezone(_ap_tz(AP_TZ_LAUF)).strftime("%Y-%m-%d")
    tag_d = datetime.strptime(tag, "%Y-%m-%d")
    zeiten["_tag"] = tag          # ZU1b: Fenster/Fensterende/CFD-Grenzen dieses Laufs für den Plan-Tag (ap_zeiten_heute), nur im Speicher
    if tag_d.weekday() >= 5:
        return {"ok": True, "tag": tag, "msg": "Wochenende — nichts geplant", "geplant": [], "ausgelassen": []}
    if quelle == "nacht" and not trocken and not gruppe:      # Gruppe: Claim in auto_plan_gruppe (ap_gruppe_planen)
        try:
            sb_insert("auto_plan_lauf", {"tag": tag, "quelle": "nacht"})
        except requests.exceptions.HTTPError as e:
            if getattr(e.response, "status_code", 0) == 409:
                return {"ok": True, "tag": tag, "msg": "schon geplant (anderer Lauf)"}
            raise
    tz = _ap_tz(zeiten.get("tz") or "Europe/Berlin")
    mitternacht = datetime(tag_d.year, tag_d.month, tag_d.day, tzinfo=tz)
    nachplanen = bool(nur_konten)
    nur_set = {str(x) for x in (nur_konten or ())}
    frueh = max(0, int(((jetzt + timedelta(minutes=AP_NACHPLAN_VORLAUF_MIN if nachplanen else 10)) - mitternacht).total_seconds() // 60) + 1)
    in_uids = "in.(" + ",".join(uids) + ")"

    # Unbestätigte, nie gestartete Auto-Vorschläge (Finn: „unbestätigte verfallen") ersetzt dieser Lauf — sie zählen schon beim
    # Rechnen nicht (sonst stünden ihre Konten im Probelauf als „hat schon einen Plan"); gelöscht wird erst vor dem Anlegen.
    # NACHPLANEN (nur_konten): nichts wird ersetzt — jeder bestehende Vorschlag zählt als Plan und bleibt stehen.
    # TW1 HANDELS-WÜRFEL (Prüfer S2 11.11.2026): einmal je Lauf gelesen — ein unbestätigter Vorschlag eines Kontos, das heute Pause-Tag hat (Wert nach dem
    # Nachtlauf gesenkt / SQL später eingespielt), bleibt stehen statt ersetzt: der Würfel nimmt nur NEUE Pläne weg, nie bestehende
    try:
        _tw_w, _tw_k = tw_werte(), ap_unt_kontext()
    except Exception as e:
        print(f"[handels-wuerfel] ⚠️ Challenge-Planer: {type(e).__name__}: {e} — alle Konten handeln", flush=True)
        _tw_w, _tw_k = {}, {}
    try:   # RV1 RANGE-WÜRFEL (11.11.2026): Einstellung einmal je Lauf; get: ältere Selftest-Lader ziehen ap_planen ohne den RV1-Block
        _rv_w = globals()["rv_werte"]() if "rv_werte" in globals() else {}
        _rv_k = (_tw_k or ap_unt_kontext()) if _rv_w else {}   # eigener Kontext, falls der Handels-Würfel ihn nicht lesen konnte (Prüfer RV1)
    except Exception as e:
        print(f"[range-wuerfel] ⚠️ Challenge-Planer: {type(e).__name__}: {e} — normale Trades", flush=True)
        _rv_w, _rv_k = {}, {}

    def _tw_pause_plan(p):
        if not _tw_w or not p.get("master_account_id"):
            return False
        pl = "challenge_futures" if ap_klasse(p.get("route"), p.get("master_firm")) == "futures" else "challenge_cfd"   # Route des Vorschlags wie die Konto-Schleife
        return bool(tw_pause_grund(pl, {"id": p.get("master_account_id"), "user_id": p.get("user_id"), "firm": p.get("master_firm")},   # TW3: Firma für den Firmen-Wurf
                                   str(p.get("planned_for") or tag)[:10], _tw_w, _tw_k))

    def _vorschlag_roh(p):
        return (not nachplanen) and p.get("auto_plan") is True and p.get("status") == "planned" and not p.get("auto_bestaetigt_at") \
            and not p.get("start_um_gestartet_at") and not p.get("hand_werte_at")   # Werte von Hand → bleibt stehen (08.10.2026)

    def _vorschlag(p):
        return _vorschlag_roh(p) and not _tw_pause_plan(p)   # Pause-Tag-Konto → Vorschlag bleibt stehen (TW1, Prüfer S2) — auch beim DELETE unten
    konten = _ap_konten_laden({"user_id": in_uids, "order": "id.asc",
                                  "account_type": "in.(" + ",".join(AP_TYPEN) + ")"})
    # LIEGENGEBLIEBENE AUTO-PLÄNE (08.10.2026, Master: Jacob 72c2a073 The5%ers + 1429b717 FundingPips seit 07.10., Chris 840c8097):
    # ein Auto-Plan, der an seinem Tag nie gesendet wurde (Start-Fehler bis Tagesende, PC aus …), blieb auf planned liegen — und
    # „hat schon einen geplanten/laufenden Plan" ließ das Konto in jedem folgenden Lauf aus, obwohl die Karte „der Nachtlauf plant neu"
    # verspricht. Jetzt zählt so ein Plan (auto_plan, planned, ohne started_at/orbit_gesendet_at, Start VOR dem geplanten Tag) hier
    # nicht mehr; er bleibt unverändert stehen (kein Datenverlust, keine P&L-Zeile) und startet nie mehr von selbst — Claim gesetzt,
    # sfTick nimmt nur Pläne des eigenen Tages. Handpläne bleiben, wie sie sind (Finns Entscheidung). Heutige Pläne erst nach start_bis
    # (ap_verfallen_grenze) — vorher holt sfTick sie noch nach.
    _grenze = ap_verfallen_grenze(jetzt, mitternacht, tz, ap_start_bis(zeiten))

    def _liegengeblieben(p):
        return ap_plan_verfallen(p, _grenze, jetzt)
    roh_plaene = _ap_plaene_mit_hand({"select": "id,user_id,master_account_id,master_firm,route,status,richtung,master_tp,master_pl,blown,"
                                                "ended_at,completed_at,auto_plan,auto_bestaetigt_at,start_um_gestartet_at,"
                                                "start_um,planned_for,started_at,orbit_gesendet_at,mt5_baseline->final,mt5_baseline->start_fehler,"
                                                "kette_te:mt5_baseline->kette->tagesende", "order": "id.asc",
                                      "user_id": in_uids, "created_at": "gte." + (jetzt - timedelta(days=30)).isoformat()})
    verfallen = [{"plan_id": p.get("id"), "user_id": p.get("user_id"), "konto_id": p.get("master_account_id"), "firma": p.get("master_firm"),
                  "start_um": p.get("start_um")} for p in roh_plaene if _liegengeblieben(p)]
    plaene = [p for p in roh_plaene if not _vorschlag(p) and not _liegengeblieben(p) and not ap_ist_waise(p)]   # Waise: Konto gelöscht (09.10.2026)
    # TW1 (Prüfer Runde 2): Vorschläge von Pause-Tag-Konten, die stehen bleiben — vom Lösch-Filter vor dem Anlegen ausgenommen (sonst wären sie trotzdem weg)
    _tw_behalt_ids = sorted({str(p.get("id")) for p in roh_plaene if p.get("id") and _vorschlag_roh(p) and _tw_pause_plan(p)})
    # Letzter Topstep-Trade des Tages (kette_te, Finn 30.10.2026): Ergebnis genau gelesen, wartet nur auf Finns Haken — für den Planer wie abgehakt:
    # heute „schon gehandelt", am Folgetag frei, geblowt über blown ausgeschlossen. Nur im Speicher, in der DB bleibt er in Überprüfen
    plaene = [dict(p, status="completed", completed_at=p.get("completed_at") or p.get("ended_at"))
              if p.get("status") == "review" and isinstance(p.get("kette_te"), dict) else p for p in plaene]
    # Nachtlauf: Leichen mit Fusion-Spread aus Leer-Versuchen nach „Überprüfen" (_ap_leichen_abschliessen) — Probelauf/Hand/Nachplanen nicht
    leichen_zu = _ap_leichen_abschliessen([v["plan_id"] for v in verfallen], jetzt) if (not trocken and quelle == "nacht") else []
    for v in verfallen:
        v["abgeschlossen"] = str(v.get("plan_id")) in leichen_zu
    # TOTE AUTO-PLÄNE FRÜHERER TAGE WEGRÄUMEN (14.10.2026 abends, Finn: „diese ganzen Fehler unter Admin … damit die Trades sauber durchlaufen"):
    # neun Leichen vom 07.–13.10. standen mit rotem Start-Fehler in „Braucht dich", weil dieser Lauf sie nur als tot zählte und liegen ließ.
    # Nur im Nachtlauf, nur Auto-Pläne, nie gestartet/gesendet, Start vor dem heutigen Tag (Dubai), nie mit Puls-Pause-Marke, nie die eben
    # auf „Überprüfen" gesetzten Leichen (leichen_zu). Heutige Leichen bleiben bis morgen stehen — Finn soll den Fehler des Tages noch sehen.
    if not trocken and quelle == "nacht":
        _h0 = jetzt.astimezone(tz)
        _heute0 = datetime(_h0.year, _h0.month, _h0.day, tzinfo=tz)
        _weg = 0
        for v in verfallen:
            _t, _pid = _ap_ts(v.get("start_um")), str(v.get("plan_id") or "")
            if not _t or _t >= _heute0 or not _pid or _pid in leichen_zu:
                continue
            try:
                sb_delete("trade_plans", {"id": f"eq.{_pid}", "status": "eq.planned", "auto_plan": "eq.true", "started_at": "is.null",
                                          "orbit_gesendet_at": "is.null", "mt5_baseline->puls_pause": "is.null"})
                _weg += 1
            except Exception as e:
                print(f"[auto-plan] ⚠️ Leiche {_pid[:8]} nicht gelöscht: {type(e).__name__}: {e}", flush=True)
        if _weg:
            print(f"[auto-plan] 🧹 {_weg} tote Auto-Pläne früherer Tage weggeräumt", flush=True)
    archiv = _ap_archiviert()
    echo_bal, dup_bal = _ap_balance_karten()
    namen, ausgeblendet = _ap_namen()   # direkt aus der Nutzerliste — _wd_personen braucht einen Request (Nachtlauf hat keinen)
    if gruppe and not namen:   # Nutzerliste nicht lesbar → Ausblendung wäre leer, die Gruppe plante gegen den ganzen HT-Stand (Prüfung 30.10.2026)
        return {"ok": False, "tag": tag, "msg": "Nutzerliste nicht lesbar — Gruppe nicht geplant (sonst gegen den HT-Stand)"}
    if gruppe:
        ausgeblendet = ap_gruppe_ausgeblendet(namen, uids)   # jede Gruppe wiegt für sich (Finn 30.10.2026): Stand nur aus der Gruppe
    seed = int(seed) if seed not in (None, "") else random.SystemRandom().randrange(1, 2 ** 31)
    rnd = random.Random(seed)

    je_konto = {}
    for p in plaene:
        je_konto.setdefault(str(p.get("master_account_id")), []).append(p)
    # FRISCHE KONTEN (Finn 09.10.2026): ohne jede Lesung → einmal den ganzen Trade-Verlauf dieser Konten prüfen (ap_startwert_frisch)
    _ohne_bal = [a["id"] for a in konten if str(a["id"]) not in archiv and (not nachplanen or str(a["id"]) in nur_set)
                 and acc_balance_wahl(a, echo_bal, dup_bal)[0] is None]
    _gehandelt = _ap_konten_mit_trade(_ohne_bal) if _ohne_bal else set()
    # ZWILLING-LOGIN (12.10.2026, Finn-Screenshot Ina FundedNext …4124 „Ziel erreicht" mit Plan 12:03): Konto 1e0903e6 „100k funded next
    # 14314124" hatte das Ziel am 08.10. erreicht, 21:16 UTC wurde für denselben Login ein zweiter Eintrag „100k bestanden (Trading tage
    # sammeln) 14314124" angelegt — ohne eigene Lesung und ohne eigenen Trade galt er als frisch, der Nachtlauf 22:45 UTC rechnete mit dem
    # Startwert 100.000 („Rest 5.000") statt der echten 108.055 und plante einen vollen Trade (die Start-Sperre hielt ihn 09.10. auf).
    # Frisch heißt: der Login gehört keinem älteren Konto-Eintrag. Lesefehler → None (kein Startwert, wie _ap_konten_mit_trade).
    if _gehandelt is not None and _ohne_bal:
        _zwillinge = _ap_login_zwillinge([a for a in konten if str(a["id"]) in set(map(str, _ohne_bal))])
        _gehandelt = None if _zwillinge is None else (_gehandelt | _zwillinge)
    sperren = _ap_sperren()
    ausgelassen, kandidaten = [], []
    for a in konten:
        aid, wer = str(a["id"]), namen.get(str(a["user_id"]), str(a["user_id"])[:8])
        zeile = {"user": wer, "user_id": str(a["user_id"]), "konto_id": aid, "konto": a.get("name"), "firma": a.get("firm"),
                 "typ": a.get("account_type")}
        if nachplanen and aid not in nur_set:
            continue                                   # NACHPLANEN: nur die neuen Konten, alle anderen bleiben unberührt (keine Meldung)
        if aid in archiv:
            continue                                   # archiviert = weg, keine Meldung
        if _ap_norm(a.get("firm")) in AP_STILL_FIRMEN:
            continue                                   # Gegenhedge-Konto (Fusion), nie planen, keine Meldung
        if ist_topstep_express(a):
            continue                                   # Topstep Express/XFA (Finn 07.10.2026: nur Combine im Auto-Plan), keine Meldung
        if a.get("auto_planer") is False:              # Haken im Konto aus (Finn 08.10.2026, accounts.auto_planer) — sichtbar ausgelassen
            ausgelassen.append(dict(zeile, grund=AP_GRUND_DEAKTIVIERT if a.get("deaktiviert") else "vom Auto-Planer ausgenommen (Haken im Konto aus)"))
            continue
        if ap_firma_gesperrt(a, sperren):              # Muster-Portfolio (16.10.2026): Firma bei der ID gesperrt — sichtbar ausgelassen
            ausgelassen.append(dict(zeile, grund=AP_GRUND_GESPERRT))
            continue
        # ZIEL ERREICHT = NIE PLANEN (Finn 12.10.2026: „Wenn ein Account als Ziel erreicht ist, dann soll dort nie im Leben ein Trade geplant
        # werden"): Markierung der Ziel-Wache zählt vor jeder Balance-Rechnung — ein falscher Startwert oder eine alte Lesung kann sie nicht
        # mehr überstimmen. Einzige Ausnahme bleibt der Mini-Trade „Tage sammeln" (Mindesttage fehlen, Finn über Master 09.10.2026).
        if a.get("ziel_erreicht_at"):
            _tg = ap_tage_ist(a, je_konto.get(aid, []))
            if not (_tg and int(_tg[0]) < int(_tg[1])):
                ausgelassen.append(dict(zeile, grund="Ziel erreicht (Ziel-Wache) — Phase umstellen, der Bot plant hier nie"))
                continue
        regel = ap_regel_finden(firmen, a.get("firm"))
        # planen:false = nur Kernwerte (Kontowert/Vorrat), z. B. Topstep, FTMO; MO1c: eine Gruppe schaltet über firmen_modell ein/aus
        if not regel or not (ap_gruppe_firma_an(regel, _fm_gruppe) if _fm_gruppe is not None else regel.get("planen") is not False):
            _aus_g = bool(regel) and _fm_gruppe is not None and (_fm_gruppe or {}).get((regel.get("namen") or [""])[0]) == AP_GRUPPE_AUS
            ausgelassen.append(dict(zeile, grund="in der Gruppe aus (Einstellungen → Modell)" if _aus_g else "keine Regel für diese Firma"))
            continue
        if ap_ext_fehlt(a, regel):                         # Puls-Weg ohne External ID → sichtbar ausgelassen statt roter Start (08.10.2026)
            ausgelassen.append(dict(zeile, grund=AP_GRUND_EXT))
            continue
        eig = je_konto.get(aid, [])
        if any(p.get("status") in ("planned", "open") for p in eig):
            ausgelassen.append(dict(zeile, grund="hat schon einen geplanten/laufenden Plan"))
            continue
        # „Überprüfen" aus „Master nie gefüllt" am Tagesende (_ap_leichen_abschliessen) blockiert nicht — es gab keinen Trade, nur den
        # Fusion-Spread zum Bestätigen (Master 08.10.2026)
        if any(p.get("status") == "review" and (p.get("final") if isinstance(p.get("final"), dict) else {}).get("grund") != AP_NIE_GEFUELLT_GRUND for p in eig):
            ausgelassen.append(dict(zeile, grund="letzter Trade noch nicht erledigt (Überprüfen)"))
            continue
        _bw = acc_balance_wahl(a, echo_bal, dup_bal)
        if ap_blow_ausschluss(eig, _bw[0], _bw[3]):
            # Finn 09.10.2026: auch nur kurz unter dem Boden = geblowt — der letzte Trade ist als geblowt abgehakt, kein Rest-Plan mehr;
            # eine frische Lesung danach (Reset/neue Phase) hebt den Ausschluss auf (ap_blow_ausschluss)
            ausgelassen.append(dict(zeile, grund="geblowt (letzter Trade als geblowt abgehakt) — Reset gekauft? → Balance lesen, dann plant der Bot wieder"))
            continue
        if any(p.get("status") == "completed" and _ap_plan_am_tag(p, tag, tz) for p in eig):
            # 08.10.2026 Finn: „maximal ein Trade pro Tag pro Account" — heute schon gehandelt (abgehakt) → erst morgen wieder
            ausgelassen.append(dict(zeile, grund=AP_GRUND_HEUTE_GEHANDELT))
            continue
        bal, _ccy, quelle_b, stand = acc_balance_wahl(a, echo_bal, dup_bal)
        letzt = max((str(p.get("ended_at") or p.get("completed_at") or "") for p in eig), default="")
        if letzt and (bal is None or not ap_balance_live(stand, letzt)):   # seit 08.10.2026 über ap_balance_live (auch Delta/ids/Guard)
            # Balance seit dem letzten Trade nicht nachgelesen → Endstand der Nachlesung, sonst auslassen (Finn: Notfall)
            fin = next((p.get("final") for p in sorted(eig, key=lambda p: str(p.get("ended_at") or p.get("completed_at") or ""),
                                                        reverse=True) if isinstance(p.get("final"), dict)), None)
            be = _wd_num((fin or {}).get("balance_end"))
            if be:
                bal, quelle_b = be, "Nachlesung"
            else:
                ausgelassen.append(dict(zeile, grund="Balance nicht live (seit dem letzten Trade nicht nachgelesen)"))
                continue
        _lg = str(a.get("external_id") or "").strip()
        _ht, _gel = (None if _gehandelt is None else aid in _gehandelt), bool(_lg) and (_lg in echo_bal or _lg in dup_bal)
        if not bal and not letzt:
            sw = ap_startwert_frisch(a, _ht, gelesen=_gel)
            if sw:
                bal, quelle_b, stand = sw, AP_STARTWERT_QUELLE, ""
        if not bal:
            # genauer Grund statt „keine Balance bekannt" allein (Finn 09.10.2026)
            gb_ = ap_grund_ohne_balance(a, True if letzt else _ht, gelesen=_gel)
            ausgelassen.append(dict(zeile, grund=gb_["text"], grund_code=gb_["code"], fix=gb_["fix"]))
            continue
        gb = ap_letzter_trade_geblasen(regel, float(bal), eig, bal_stand=stand)   # stand = Zeit der Balance (08.10.2026: frische Balance über dem Boden schlägt die Schätzung)
        if gb:
            # geblowt? — Boden/Balance/Stand für die Anzeige (Slave 6, 08.10.2026)
            ausgelassen.append(dict(zeile, grund=gb, **ap_boden_zeile(regel, a, float(bal), stand if quelle_b != "Nachlesung" else letzt)))
            continue
        regel_kk = ap_regel_konto(regel, a, float(bal))
        regel_kk = ap_cons_regel(regel, regel_kk, a, float(bal), eig)   # Consistency-Ziel (M2 05.11.2026)
        kandidaten.append({"a": a, "regel": regel_kk, "bal": float(bal), "bal_quelle": quelle_b, "zeile": zeile,
                           "tage": ap_tage_ist(a, eig),          # Mindesttage (ist, soll) oder None — Mini-Trade bei Ziel erreicht (09.10.2026)
                           "bal_stand": stand if quelle_b != "Nachlesung" else letzt,
                           "tkey": str(a["user_id"]) + "|" + _ap_norm(a.get("firm"))})

    # TW1 HANDELS-WÜRFEL (11.11.2026, Finn: „Der Tag wird quasi gewürfelt … Es geht hier um jedes Konto, also alles komplett"): je Konto × Tag fester
    # Wurf (tw_handelt) — Pause-Tag = heute kein neuer Plan, sichtbar ausgelassen. Vor dem Tagesdeckel: ein Pause-Konto belegt keinen Deckel-Platz und
    # geht nicht in Waage/Delta. CFD bzw. Futures nach ap_klasse (Route vor Firma). Bestehende Pläne erreichen diese Stelle gar nicht (oben „schon geplant").
    # _tw_w/_tw_k: oben einmal je Lauf gelesen (bei _vorschlag)
    if _tw_w:
        _tw_behalten = []
        for k in kandidaten:
            _tw_p = "challenge_futures" if ap_klasse((k.get("regel") or {}).get("route"), k["a"].get("firm")) == "futures" else "challenge_cfd"
            _tw_g = tw_pause_grund(_tw_p, k["a"], tag, _tw_w, _tw_k)
            if _tw_g:
                ausgelassen.append(dict(k["zeile"], grund=_tw_g))
            else:
                _tw_behalten.append(k)
        kandidaten = _tw_behalten

    # TAGESDECKEL JE FIRMA (19.10.2026, Finn: Apex 2–3 Trades je ID und Tag, bis er etwas anderes sagt; CFD weiter wie immer):
    # regel.max_konten_tag, Rest sichtbar ausgelassen — vor dem Delta, damit nur die behaltenen Konten in den Live-Stand gehen
    kandidaten, _deckel_raus = ap_tagesdeckel(firmen, kandidaten, plaene, tag, tz, rnd)
    ausgelassen.extend(_deckel_raus)

    # DELTA (06.10.2026, Vertrag §2): Live-Stand ALLER IDs — laufende Trades, heute schon geplante Pläne (ohne die Vorschläge,
    # die dieser Lauf ersetzt), Firma × Tag; Kontowert + Punktwert der neuen Konten aus demselben Kontext
    param = ap_ausgleich_param(reg.get("regeln"))
    stand = _ap_stand_laden(reg, jetzt, tag, ersetzt=lambda p: str(p.get("user_id")) in uids and _vorschlag(p),
                            extra_konten=[k["a"]["id"] for k in kandidaten], echo_bal=echo_bal, dup_bal=dup_bal,
                            namen=namen, ausgeblendet=ausgeblendet, eigene=uids if gruppe else None)   # UNT2: Stand nur aus dem Unternehmen
    if gruppe:   # ORBIT PRIO 2 AUS DER WAAGE (MO1b): die Gruppe wiegt mit IHREN Modellen — Prio-2-Firmen der Gruppe raus, HT-Einträge gelten ihr nicht
        try:
            _fm_g = _fm_gruppe or {}
            param = ap_waage_param_gruppe(param, (reg.get("regeln") or {}).get("ausgleich"), (reg.get("regeln") or {}).get("firmen"), _fm_g)
            stand["param"] = ap_waage_param_gruppe(stand.get("param"), (reg.get("regeln") or {}).get("ausgleich"), (reg.get("regeln") or {}).get("firmen"), _fm_g)
        except Exception as e:
            print(f"[auto-plan] ⚠️ Waage der Gruppe (Orbit Prio 2): {type(e).__name__}: {e}", flush=True)
    # TAGES-WAAGE AUCH BEIM PLANEN (.1556, Finn 14.10.2026: „nicht nur am Ende vom Tag, auch die ganze Zeit ein gutes Long-Short-
    # Verhältnis"): plant dieser Lauf den HEUTIGEN Tag (Nachplan-Takt, „Plan heute", Gruppen-Planer), verteilt ap_richtungen_delta die neuen
    # Tranchen gegen das Eröffnungs-Gewicht aller heute gestarteten Trades (ap_tages_saldo), nicht nur gegen das laufende Buch — sonst
    # hätte der Nachplan-Takt nach toten Longs wieder Longs „zum Ausgleich" verteilt. Nachtlauf für den Folgetag: Tag frisch, nichts beendet.
    # ZWEI WAAGEN (17.10.2026): Finn wiegt nur das laufende Buch — mit regeln.ausgleich.waage (Standard) bleibt die Basis laufend
    if tag == jetzt.astimezone(_ap_tz(AP_HB_TZ)).strftime("%Y-%m-%d") and not param.get("waage"):
        try:
            stand["heute_beendet"], stand["heute_ab"] = ap_heute_beendet_gemerkt((reg.get("regeln") or {}).get("firmen") or [], jetzt,
                                                                                 unternehmen=frozenset(uids) if gruppe else "ht")   # UNT2
            ap_tages_saldo(stand)
        except Exception as e:
            stand["heute_beendet_fehler"] = f"{type(e).__name__}: {e}"
            print(f"[auto-plan] ⚠️ Tages-Waage (Planen): {stand['heute_beendet_fehler']}", flush=True)
    dinfo = {}

    # Tranchen + Zufall je Tranche
    tranchen = {}
    for k in kandidaten:
        tranchen.setdefault(k["tkey"], []).append(k)
    tr_info, plan_roh, roh_tr = {}, [], []
    # Topstep-Kette mit DLL (08.10.2026): höchster belegter Tagesschluss je Konto für den MLL — nur für Kettenkonten (eine Abfrage, 60 s Cache).
    # Lesefehler (streng → None): Kettenkonten mit DLL bekommen KEINEN Plan („MLL nicht prüfbar", Prüfung Slave 2) — nie mit zu tiefem MLL
    # planen. Ein Konto ohne jeden belegten Stand (frisch) hat peak None → MLL ab Größe/Balance, das ist richtig.
    kette_tripel = [(k["a"], k["regel"], k["bal"]) for k in kandidaten if ap_kette_regel(k["regel"])]
    peaks_kette = _ap_peaks([a for a, _r, _b in kette_tripel], streng=True) if kette_tripel else {}
    # 15.10.2026 (Mike …8280 „geblowt?" bei lebendem Konto): MLL aus der TopstepX-Lesung/Tagesschlüssen, nicht aus Zwischenständen
    mlls_kette = (_ap_kette_mlls(kette_tripel, streng=True, peaks=peaks_kette) if kette_tripel else {}) if peaks_kette is not None else None
    for key, liste in tranchen.items():
        rechnung, tps_tranche = [], set()
        for k in liste:
            # EIGENER ZUFALL JE KONTO (Finn 09.10.2026 ~07:45 Dubai, „Zu bestätigen" Finn+Pascal: vier Tradeify-150k-Challenges einer
            # ID alle TP 3.450 $ und 2 NQ). Ursache: u wurde EINMAL je Tranche (ID × Firma) gezogen und für jedes Konto wiederverwendet —
            # so gewollt seit 05.10.2026 („alle laufen gemeinsam in TP oder SL"), nur die Topstep-Kette zog schon je Konto. Jetzt zieht
            # jedes Konto TP, SL, Menge und Puffer selbst innerhalb der Regel-Spanne; Richtung und Richtungsschutz bleiben je Tranche,
            # Rest-/Klein-Trade und Ziel-/Boden-Kappung wirken wie bisher in ap_konto_rechnen.
            u_k = {x: rnd.random() for x in ("tp", "sl", "menge", "puffer")}
            if peaks_kette is None and (ap_kette_regel(k["regel"]) or {}).get("daily_usd") and k["a"].get("account_type") == "challenge":
                ausgelassen.append(dict(k["zeile"], grund="MLL nicht prüfbar (Verlauf nicht lesbar) — kein Kettenplan"))
                continue
            w, grund = ap_konto_rechnen(k["regel"], k["a"]["account_type"], k["bal"], u_k, peak=(peaks_kette or {}).get(str(k["a"].get("id"))),
                                        ppl=ap_cfd_ppl(stand.get("ctx"), k["a"]), tage=k.get("tage"),   # CFD: Punkte-Puffer + Klein-Trade; Tage sammeln (09.10.2026)
                                        mll_belegt=(mlls_kette or {}).get(str(k["a"].get("id"))), rest_planer=bool(k["a"].get("rest_planer_at")))
            # KEINE ZWEI GLEICHEN TP je ID×Firma (Finn 09.10.2026): eine Spanne wie 3.450–3.550 hat nur ~100 ganze Werte — zwei Konten
            # treffen sich bei 10 Konten in gut jedem dritten Lauf. Bei Gleichstand neu ziehen (höchstens 20×); gekappte TP (Rest bis
            # Ziel) bleiben, wie sie sind
            for _ in range(20):
                if grund or not w or w.get("tp") not in tps_tranche or re.search(r"letzter Trade|Rest bis Ziel|Tage sammeln", str(w.get("stufe") or "")):
                    break
                u_k = {x: rnd.random() for x in ("tp", "sl", "menge", "puffer")}
                w, grund = ap_konto_rechnen(k["regel"], k["a"]["account_type"], k["bal"], u_k, peak=(peaks_kette or {}).get(str(k["a"].get("id"))),
                                            ppl=ap_cfd_ppl(stand.get("ctx"), k["a"]), tage=k.get("tage"),
                                            mll_belegt=(mlls_kette or {}).get(str(k["a"].get("id"))), rest_planer=bool(k["a"].get("rest_planer_at")))
            if w and not grund and _rv_w:
                # RV1 RANGE-WÜRFEL (Finn 11.11.2026 07:35: „nur bei 25 % der Trades wird's angepasst … Stop Loss, Take Profit und Lotanzahl … für alle drei wird
                # einzeln gewürfelt“): Etappe × drei feste Faktoren je Konto × Tag, NACH Boden-/Tagesgrenze-Kappung, VOR Trades pro Tag (Tagesziel, Haupt-Lots
                # und SL der Neben-Teile kommen so schon vom kleinen Trade). Kein Wert / kein Treffer / Fehler → w unverändert
                w = rv_planer_haken(w, k["a"], k["regel"], tag, ap_cfd_ppl(stand.get("ctx"), k["a"]), _rv_w, _rv_k)
                # RV1d (Prüfer-SOLLTE zu 6bc12ab7): die Gleichstand-Schleife oben sah nur den TP VOR dem Würfel — skalierten TP noch einmal gegen die Tranche
                # prüfen (deterministisch ±1 $, kein Zufallszug); get: ältere Selftest-Lader ziehen ap_planen ohne rv_tp_frei
                if w and "rv_tp_frei" in globals():
                    w = rv_tp_frei(w, tps_tranche, ap_cfd_ppl(stand.get("ctx"), k["a"]))
            if w and not grund and ap_tradeify_final_halten(reg.get("regeln"), k["a"].get("firm"), w):
                grund = AP_TRADEIFY_FINAL_GRUND   # finaler Tradeify-Trade wartet auf Gegenhedge (29.10.2026) — nicht planen
            if w and not grund and "tt_param" in globals():   # get: ältere Selftest-Lader ziehen ap_planen ohne die WS2-Helfer
                # WS2 TRADES PRO TAG AUFTEILEN (Finn 09.11.2026, tt_planer_haken): Würfel 1–4 Trades, Trade 1 holt seinen Anteil; dazu der Zufalls-Schluss
                # (WS2c) je Plan. Nur wenn tt_gilt — sonst kein rnd-Zug, der Lauf bleibt bitgleich zu vorher
                try:
                    _tt_p = tt_param(reg.get("regeln"))
                    if tt_gilt(_tt_p, (k["regel"].get("namen") or [""])[0], (gruppe or {}).get("gruppe_id"), k["a"].get("id"), k["a"].get("account_type"),
                               user_id=k["a"].get("user_id"), route=k["regel"].get("route")):          # TT1: Test-IDs nur Echo
                        _tt_n = _tt_p.get("test_n") if (_tt_p.get("test_ids") and _tt_p.get("test_n")) else None
                        # Nachzug 10.11.2026 (Master): finaler/Klein-Trade (Tradeify final → Orbit V3/tfh, TT_EIN_TRADE_STUFE) bekommt keinen
                        # Zufalls-Schluss — am Plan VOR dem Haken gemessen (der Haken stellt „Tag 1/n …“ vor die Stufe)
                        _tt_fest = tt_ein_trade_fest(w, k["regel"].get("route"))
                        w = tt_planer_haken(w, k["regel"], k["a"].get("account_type"), _tt_p, rnd, ppl=ap_cfd_ppl(stand.get("ctx"), k["a"]), n_fest=_tt_n)
                        # WZ1 (10.11.2026): Wurf immer belegen, auch Nieten — in kette.zs_wurf, ohne Kette (1-Trade-Tag) in mt5_baseline.zs_wurf;
                        # finaler/Klein-Trade: kein Zug (bitgleich), Beleg „fest“
                        _zs, _wurf = (None, {"aus": "fest"}) if _tt_fest else tt_zschluss_wurf(_tt_p, rnd)
                        if _zs:
                            w = dict(w, zschluss=_zs)
                        w = dict(w, kette=dict(w["kette"], zs_wurf=_wurf)) if (isinstance(w.get("kette"), dict) and w["kette"]) else dict(w, zs_wurf=_wurf)   # leere Kette nie zur Schein-Kette machen (Prüfer WZ1)
                except Exception as e:
                    print(f"[auto-plan] ⚠️ Tagesteilung {str(k['a'].get('id'))[:8]}: {type(e).__name__}: {e} — ein Trade wie bisher", flush=True)
            if w and not grund:
                tps_tranche.add(w.get("tp"))
            if grund and "Boden" in grund:
                # „Balance auf/unter dem Boden — geblowt?" — Boden/Balance/Stand für die Anzeige (Slave 6, 08.10.2026); k["regel"] ist schon
                # die Konto-Regel, ap_regel_konto darauf ändert nichts mehr
                ausgelassen.append(dict(k["zeile"], grund=grund, **ap_boden_zeile(k["regel"], k["a"], k["bal"], k.get("bal_stand"))))
            elif grund:
                # „Rest … von Hand" (20.10.2026) bekommt einen grund_code, damit die Zeile in „Braucht dich" auch dann steht, wenn das Konto
                # dort schon eine Balance-Zeile hat (tplDaten übergeht Planer-Gründe ohne Code)
                ausgelassen.append(dict(k["zeile"], grund=grund, **({"grund_code": "rest_von_hand"} if str(grund).startswith("Rest ") else {})))
            else:
                rechnung.append((k, w))
        if not rechnung:
            continue
        # Richtungsschutz: läuft/steht an derselben Firma bei derselben ID schon eine Richtung, gilt sie für die Tranche
        firm_n = key.split("|", 1)[1]
        # 07.10.2026 (Finn: Richtungsschutz gilt nur GLEICHZEITIG — nie Long und Short derselben ID+Firma zur selben Zeit offen;
        # ist der Long beendet, darf später Short): fest nur durch einen laufenden Plan oder einen geplanten an DIESEM Tag
        # (ohne Tag/Startzeit vorsichtshalber auch); geplante Pläne anderer Tage überlappen nie (ap_richtung_fest_plan)
        # Seit 09.10.2026 (Finn, gemischt über den Tag): ein solcher Plan legt die Richtung nur noch in seiner Nähe fest — als Bezug
        # (Minute, Richtung, läuft) je Plan; welcher Teil fest ist, entscheidet sich erst mit seiner Startzeit (ap_fest_am_start, je Wurf)
        fest_ps = [p for p in plaene if str(p.get("user_id")) == key.split("|")[0]
                   and _ap_norm(p.get("master_firm")) == firm_n and ap_richtung_fest_plan(p, tag, tz)]
        fest_p = fest_ps[0] if fest_ps else None
        fest = [_ap_fest_ref(p, mitternacht, jetzt) for p in fest_ps]
        route_t = rechnung[0][0]["regel"].get("route") or "mt5v2"
        sym_t = str(rechnung[0][0]["regel"].get("symbol") or "NQ") if route_t in ("tvv2", "tsv2") else None
        bew = {}
        for k, w in rechnung:      # Delta + Einsatz je Konto (Betrag; das Vorzeichen kommt mit der Richtung)
            # Mini-Trade (Tage sammeln) läuft auf MNQ statt NQ — Einsatz/Delta mit dem Symbol des Plans, sonst ×10 zu schwer (Master 09.10.2026)
            bew[str(k["a"]["id"])] = _ap_bewerten(stand["ctx"], k["a"], k["bal"], w["menge"], route_t, w.get("symbol") or sym_t, "buy", w["tp"], w["sl"])
        eins = {aid: float(((b or {}).get("g") or {}).get("verlust_eur") or 0) for aid, b in bew.items()}
        roh_tr.append((key, firm_n, fest, fest_p, rechnung, bew, eins))
    # Große Trades einzeln (Finn 07.10.2026): Schwelle = gross_ab_eur bzw. oberes Viertel der Einsätze dieses Laufs; eine Tranche
    # mit einem großen Konto wird in Einzelkonten mit eigenen Startzeiten aufgeteilt (Schlüssel ID|Firma#n, gruppe ID|Firma =
    # eine Richtung, Richtungsschutz bleibt). Seit 08.10.2026 (Verteilen, Finn zu Ina „nicht durchrattern"): JEDE Tranche mit mehr als
    # einem Konto — ap_zeiten_verteilen hält die Teile AP_ABSTAND_ID_FIRMA_MIN auseinander, die gruppe hält die Richtung gleich
    gross_ab = ap_gross_ab([e for t in roh_tr for e in t[6].values()] + [z.get("einsatz_abs") for z in stand["geplant"]],
                           param["gross_ab_eur"])
    abst = zeiten.get("abstand_konto_s") or [60, 120]
    for key, firm_n, fest, fest_p, rechnung, bew, eins in roh_tr:
        if len(rechnung) > 1:
            teile = [(f"{key}#{i + 1}", [(k, w)]) for i, (k, w) in enumerate(rechnung)]
        else:
            teile = [(key, rechnung)]
        for ukey, r_teil in teile:
            versatz = [0]
            for _ in r_teil[1:]:
                versatz.append(versatz[-1] + rnd.randint(int(abst[0]), int(abst[1])))
            for k, _w in r_teil:
                dinfo[(ukey, str(k["a"]["id"]))] = bew[str(k["a"]["id"])]
            tr_info[ukey] = {"key": ukey, "user": key.split("|")[0], "firma": firm_n, "fest": None, "fest_refs": fest, "gruppe": key,
                             "route": r_teil[0][0]["regel"].get("route") or "mt5v2",          # Klasse CFD/Futures (08.10.2026)
                             "ab_min": ap_cfd_ab(zeiten) if (r_teil[0][0]["regel"].get("route") or "mt5v2") in AP_CFD_ROUTEN else 0,
                             "bis_min": min([x for x in (
                                 _ap_hhmm(ap_kette_regel(r_teil[0][0]["regel"])["t1_bis"]) if (r_teil[0][1].get("kette") and ap_kette_regel(r_teil[0][0]["regel"])) else None,   # Topstep-Kette: Trade 1 bis t1_bis dt (WS2: Orbit/Echo-Ketten ohne Kettenregel)
                                 ap_klasse_bis(zeiten, r_teil[0][0]["regel"].get("route") or "mt5v2", tag_d.date())) if x is not None]),   # CFD bis zeiten.cfd_bis (16.10.2026)
                             "fest_durch": (("laufender Plan" if fest_p.get("status") == "open" else "geplanter Plan") if fest_p else None),
                             "dauer_min": versatz[-1] / 60.0 + 2, "gewicht": sum(w["tp"] for _, w in r_teil),
                             "fkey": ap_firma_key(firmen, r_teil[0][0]["a"].get("firm")),
                             "delta_abs": round(sum(abs(bew[str(k["a"]["id"])]["delta_eur_pkt"] or 0) for k, _ in r_teil), 3),
                             "einsatz_abs": round(sum(eins[str(k["a"]["id"])] for k, _ in r_teil), 1)}
            plan_roh += [(ukey, k, w, versatz[i]) for i, (k, w) in enumerate(r_teil)]
    # PC je ID: heute schon geplante Pläne derselben ID belegen ihren Start (nie zwei Puls-Starts gleichzeitig)
    # Richtung je TRANCHE (fest nur durch Richtungsschutz ID+Firma). 07.10.2026 (Finn, einfach): EINE Kennzahl = Einsatz € —
    # Ziel kleinstes größtes |Netto-Einsatz| zu jeder Zeit (jeder Trade zählt laufzeit_min ab Start, Master 07.10.2026: „frühe
    # Starts gemischt long/short, kein Block aus 4 Shorts" — kumuliert bis Tagesende glich der Morgen-Short den Nachmittags-Long
    # aus), große gleich gerichtet nicht hintereinander, Malus davor (ap_richtungen_delta mit einsatz); die Zeiten werden bis
    # AP_GEGEN_WUERFE-mal neu gewürfelt, der beste Lauf gilt. Keine harte Grenze, nichts wird deswegen ausgelassen
    fest_ev = [(z["start_min"], z["delta_eur_pkt"]) for z in stand["geplant"]
               if z.get("start_min") is not None and z.get("delta_eur_pkt") is not None]
    bestehend_pc = [{"user": z["user_id"], "start": z["start_min"], "dauer_min": 2,
                     "gruppe": str(z["user_id"]) + "|" + _ap_norm(z.get("firma")),       # Abstand je ID × Firma auch zu schon geplanten
                     "fkey": z.get("firma_key")}                                          # Firmen-Abstand zu anderen IDs (08.10.2026)
                    for z in stand["geplant"] if z.get("start_min") is not None]
    bestehend_pc += [{"user": x["user_id"], "start": x["start"], "dauer_min": 2, "gruppe": None, "fkey": x.get("firma")}
                     for x in stand.get("starts_heute") or () if x.get("start") is not None]   # heute gestartete: PC + Firmen-Abstand
    ek = ap_einsatz_kontext(stand, param)
    ek["gross_ab"] = gross_ab
    ek["fest_ev"] = [(z["start_min"], z["einsatz_eur"]) for z in stand["geplant"]
                     if z.get("start_min") is not None and z.get("einsatz_eur") is not None]
    # FIRMEN-MISCHUNG (08.10.2026, Finn: „nicht, dass an einem Tag eine Prop-Firm nur in einer Richtung getradet wird"): Trades des Tages
    # mit fester Richtung — schon geplante Pläne (alle IDs, Hand/WD eingeschlossen; die ersetzten Vorschläge fehlen im Stand) und heute
    # gestartete bzw. gewürfelte Winning-Days-Blöcke (starts_heute) — zählen in der Tages-Mischung je Firma mit
    # Seit 08.10.2026 abends (Mischung je Zeitfenster × Firma/Klasse) mit Startminute und Weg (Klasse CFD/Futures, ap_klasse)
    firma_fest = [{"user_id": z["user_id"], "firma": z.get("firma_key"), "richtung": z.get("richtung"), "start": z.get("start_min"),
                   "route": z.get("route")} for z in stand["geplant"]]
    firma_fest += [{"user_id": x.get("user_id"), "firma": x.get("firma"), "richtung": x.get("richtung"), "start": x.get("start"),
                    "route": x.get("route")} for x in stand.get("starts_heute") or ()]
    bester = None
    for _wurf in range(int((zeiten.get("_zufall") or {}).get("gegen_wuerfe", AP_GEGEN_WUERFE))):     # E3b: regeln.zufall, sonst Code
        zinfo_w = {}
        minuten_w = ap_zeiten_verteilen(list(tr_info.values()), zeiten, rnd, frueheste_min=frueh, info=zinfo_w,
                                        bestehend=bestehend_pc)
        tr_w = {key: {"fest": ap_fest_am_start(tr_info[key]["fest_refs"], minuten_w[key]), "user": tr_info[key]["user"], "firma": tr_info[key]["fkey"],
                      "start": minuten_w[key], "delta_abs": tr_info[key]["delta_abs"], "gruppe": tr_info[key]["gruppe"],
                      "einsatz_abs": tr_info[key]["einsatz_abs"], "route": tr_info[key]["route"],   # Klasse CFD/Futures (08.10.2026)
                      "n_plaene": sum(1 for (kk_, _k, _w2, _v) in plan_roh if kk_ == key)} for key in minuten_w}   # ID-Mischung (08.10.2026)
        richtung_w, netto_w, wert_w = ap_richtungen_delta(tr_w, stand["basis_netto"], stand["basis_brutto"], rnd,
                                                          param["zielband_pct"], fest_ev, bestehende=stand["starts_heute"],
                                                          einsatz=ek, mit_wert=True, firma_fest=firma_fest, zeiten=zeiten)
        if bester is None or (-len(minuten_w), wert_w) < (-len(bester[1]), bester[0]):
            bester = (wert_w, minuten_w, zinfo_w, richtung_w, netto_w)
        if all(x == 0 for x in wert_w[:6]):
            break                      # kein Malus, Firmen gemischt, ID × Firma gemischt, |Netto| unter einer Stufe, ID-Mischung ok, keine Große-Folge
    _w, minuten, zinfo, richtung, netto_max = bester
    # PAARE JE FUTURES-FIRMA (Finn 19.10.2026 ~02:50 Dubai, Zeitstrahl: „Ich sehe es immer in Paaren — Tradeify Long und Tradeify Short,
    # zwei IDs, innerhalb von 10 Minuten. Warum machst du es nicht?"): nach Zeiten und Richtungen legt der Planer je Firma der Futures-Waage
    # (Tradeify, Topstep, Lucid, FNF Futures …, nicht Apex) Long und Short VERSCHIEDENER IDs zu Paaren — der spätere der beiden rückt auf
    # Anker + 2–10 min (Zufall je Paar). Schon geplante Trades des Tages sind feste Anker; PC ± 3 min, Firma 1 min zu anderen IDs,
    # Fenster der Tranche und Richtungsschutz am neuen Start bleiben. Was keinen Partner findet, bleibt stehen.
    # Seit 25.10.2026 (Finn) zuerst PROPFIRM-EXTERN (Tradeify ↔ Topstep/Lucid/FNF …, 2–5 min, auch dieselbe ID), erst der Rest intern
    # (dieselbe Firma, zwei IDs, 2–30 min) — Richtung bleibt immer, nur die Startzeit rückt.
    try:
        minuten, paare_info = ap_paare_legen(minuten, richtung, tr_info, bestehend_pc, firma_fest, rnd, ohne=ap_waage_ohne_liste({"param": param}),
                                             frueh=frueh, zufall=zeiten.get("_zufall"))      # 19.10.2026: Anker nur in der Zukunft (Nachplanen am Nachmittag)
        if paare_info:
            print(f"[auto-plan] {tag} Paare: " + " · ".join(f"{p.get('art', 'intern')} {p['firma']} {p['user']} {p['richtung']} {_ap_hhmm_txt(p['von'])}→{_ap_hhmm_txt(p['nach'])}"
                                                           f" (zu {p.get('anker_firma') or p['firma']})" for p in paare_info), flush=True)
    except Exception as e:
        print(f"[auto-plan] ⚠️ Paare: {type(e).__name__}: {e}", flush=True)
    for key in minuten:                # fest am gewählten Start — für Probelauf/Anzeige („Richtung fest: laufender Plan …")
        tr_info[key]["fest"] = ap_fest_am_start(tr_info[key]["fest_refs"], minuten[key])
        if not tr_info[key]["fest"]:
            tr_info[key]["fest_durch"] = None
    # ID-MISCHUNG für den Delta-Monitor (08.10.2026): je ID long/short-Zählung der Zuteilung dieses Laufs (nur neue Tranchen)
    tr_best = {key: {"user": tr_info[key]["user"], "firma": tr_info[key]["fkey"], "n_plaene": sum(1 for (kk_, _k, _w2, _v) in plan_roh if kk_ == key),
                     "start": minuten[key], "route": tr_info[key]["route"]}
               for key in minuten}
    id_misch = [dict(v, user_id=u, user=namen.get(u, u[:8])) for u, v in ap_id_misch(richtung, tr_best)[1].items()]
    id_misch.sort(key=lambda x: (-x["n"], x["user"]))
    # FIRMEN-MISCHUNG für Probelauf/Protokoll (08.10.2026): je Firma long/short über den ganzen Tag (neu + fest), seltenere Richtung
    _fm_st, _fm_lage = ap_misch_lage(richtung, tr_best, firma_fest, zeiten)
    firma_misch = [dict(v, firma=f) for f, v in _fm_lage["tag_firma"].items()]
    firma_misch.sort(key=lambda x: (-x["n"], x["firma"]))
    # MISCHUNG JE ZEITFENSTER (08.10.2026 abends): Fenster × Firma / × Klasse / gesamt / Kippen — für Probelauf und Protokoll
    misch_fenster = [c for c in _fm_lage["zellen"] if c.get("ebene") != "tag_firma"]
    for key in [k for k in tr_info if k not in minuten]:
        for (kk, k, _w2, _v) in plan_roh:
            if kk == key:
                ausgelassen.append(dict(k["zeile"], grund="kein freies Zeitfenster mehr"))
    einsatz_info = dict(ap_einsatz_lage(ek["basis"], ek["fest_ev"] + [
        (minuten[k], tr_info[k]["einsatz_abs"] * (1 if richtung[k] == "buy" else -1)) for k in minuten], gross_ab,
        laufzeit_min=ek["laufzeit"]), laufzeit_min=ek["laufzeit"],
        gross_ab_eur=round(gross_ab), basis_eur=round(ek["basis"]),
        long_eur=round(sum(tr_info[k]["einsatz_abs"] for k in minuten if richtung[k] == "buy")
                       + sum(max(e, 0) for _, e in ek["fest_ev"]) + max(ek["basis"], 0)),
        short_eur=round(sum(tr_info[k]["einsatz_abs"] for k in minuten if richtung[k] == "sell")
                        + sum(max(-e, 0) for _, e in ek["fest_ev"]) + max(-ek["basis"], 0)))
    einsatz_info.pop("schlimmst_vz", None)

    frontcode = _wd_futures_frontcode(mitternacht.astimezone(timezone.utc))
    zeilen, geplant = [], []
    peaks = _ap_peaks([k["a"] for _key, k, _w, _v in plan_roh])   # Höchststand für den geschätzten Boden (08.10.2026)
    for key, k, w, vers in plan_roh:
        if key not in minuten:
            continue
        a, regel = k["a"], k["regel"]
        start = mitternacht + timedelta(minutes=minuten[key], seconds=vers)
        route = regel.get("route") or "mt5v2"
        rest_txt = f"{w['rest']:,}".replace(",", ".")
        zeilen.append({
            "user_id": a["user_id"], "master_account_id": a["id"], "master_name": a.get("name"), "master_firm": a.get("firm"),
            "master_contracts": w["menge"], "master_risk": w["risiko"] if w["risiko"] is not None else _wd_num(a.get("max_drawdown")),
            "master_tp": w["tp"], "master_sl": w["sl"], "richtung": richtung[key], "route": route,
            "tages_grenze_usd": w.get("tages_grenze_usd"),   # Tagesgrenze-Rest ohne Puffer (26.10.2026, Vertrag Teil B/C) — null = keine Prüfung
            "master_symbol": (str(w.get("symbol") or regel.get("symbol") or "NQ") + frontcode) if route in ("tvv2", "tsv2") else None,   # tsv2 = Topstep V2 (07.10.2026); Mini: MNQ
            "start_um": start.astimezone(timezone.utc).isoformat(), "status": "planned", "priority": "medium",
            "planned_for": tag, "auto_plan": True,
            # TL1b (12.11.2026): Kettenpläne tragen ihren konto_typ ab dem Anlegen — Plan 272809d8 (09.11.) wurde von Hand abgeschlossen und bekam keinen
            # (sonst stempeln erst das Abhaken bzw. der Tab planKontoTypMerken), seine MLL-Lesung fiel aus ap_kette_mll_belegt. Andere Pläne wie bisher
            "konto_typ": (a.get("account_type") or None) if w.get("kette") else None,
            "mt5_baseline": ({"kette": dict(w["kette"], tag=tag)} if w.get("kette")                       # Topstep-Kette Trade 1 (08.10.2026)
                             else {"tage_mini": dict(w["tage_mini"], tag=tag)} if w.get("tage_mini") else None),   # Tage sammeln (09.10.2026)
            # Tausender-Punkt nur für Rest und Balance (09.10.2026): das alte .replace(",", ".") über die ganze Notiz machte aus der
            # Klein-Trade-Stufe „0,18 Lots" ein „0.18 Lots" (Stufen mit Tausendern formatieren sich selbst, z. B. Topstep-Kette)
            "notes": ap_notiz(w["stufe"], rest_txt, k["bal"], k["bal_quelle"])})
        if w.get("zschluss"):                    # WS2c Zufalls-Schluss (09.11.2026, tt_zschluss im Planer-Haken): eigener Schlüssel neben kette/tage_mini
            zeilen[-1]["mt5_baseline"] = dict(zeilen[-1]["mt5_baseline"] or {}, zschluss=w["zschluss"])
        if w.get("zs_wurf") and not w.get("kette"):   # WZ1: Wurf-Beleg ohne Kette (mit Kette steht er in kette.zs_wurf)
            zeilen[-1]["mt5_baseline"] = dict(zeilen[-1]["mt5_baseline"] or {}, zs_wurf=w["zs_wurf"])
        if w.get("range"):                       # RV1: Beleg (Faktoren, Normal-Werte, Punkte) am Plan; mit Kette auch dort — tt_folge_rechnen skaliert den Haupt-Teil damit
            _b = dict(zeilen[-1]["mt5_baseline"] or {}, range=w["range"])
            if isinstance(_b.get("kette"), dict) and _b["kette"]:
                _b["kette"] = dict(_b["kette"], range=w["range"])
            zeilen[-1]["mt5_baseline"] = _b
        if param["auto_start"] and not gruppe:   # regeln.ausgleich.auto_start (Standard aus): Plan gilt sofort als bestätigt — Gruppe nie (Finn 30.10.: „er bestätigt sie einzeln")
            zeilen[-1]["auto_bestaetigt_at"] = jetzt.isoformat()
        d = dinfo.get((key, str(a["id"]))) or {}
        dd = d.get("delta_eur_pkt")
        geplant.append(dict(k["zeile"], start=start.strftime("%H:%M"), richtung=richtung[key], tp=w["tp"], sl=w["sl"],
                            menge=w["menge"], stufe=w["stufe"], rest=w["rest"], balance=round(k["bal"]), bal_quelle=k["bal_quelle"],
                            tages_grenze_usd=w.get("tages_grenze_usd"),
                            delta_eur_pkt=(round(abs(dd), 3) * (1 if richtung[key] == "buy" else -1)) if dd is not None else None,
                            einsatz_eur=round(float((d.get("g") or {}).get("verlust_eur") or 0)) * (1 if richtung[key] == "buy" else -1),
                            tp_punkte=d.get("tp_punkte"), sl_punkte=d.get("sl_punkte"), bestaetigt=bool(param["auto_start"]) and not gruppe,
                            **ap_boden_sicher(None, a, k["bal"], peaks, regel=k["regel"])))   # Boden für den Balance-Balken (08.10.2026)
    # E3 (Finn 03.11.2026 ~23:10 Dubai: „Es ist kein einziger Trade des CFD-Planers, ganz egal was. CFD-Planer only Echo, fertig." — HT und Emin;
    # Master: „KEIN V2-Fallback … gar nicht anlegen"): CFD-Challenges gleich als Echo mit Fusion-Hedge. Ist der Hedge beim Planen nicht stellbar (kein
    # Fusion-Konto, kein Kontowert, < 0,01 Lot, Schalter aus, Rechenfehler), wird das Konto NICHT geplant: ausgelassen mit Grund + ⚪ einmal je Konto und Tag.
    # Minis „Tage sammeln" bleiben Echo V2 (E2). Vor dem Fingerabdruck, damit Probelauf und Anlegen dasselbe zeigen.
    _konten_e3 = {str(k["a"]["id"]): (k["a"], k["bal"]) for _key, k, _w, _v in plan_roh}
    try:
        _e3 = ap_echo_hedge_anlegen(zeilen, _konten_e3, reg.get("regeln") or {})
    except Exception as e:
        _g3 = f"Echo-Hedge nicht rechenbar ({type(e).__name__}: {str(e)[:80]})"
        try:
            _weg3 = [z for z in zeilen if ap_echo_kandidat(z, _konten_e3)]
        except Exception:   # Prüfung E3: der Rückfall wirft nie selbst — dann jede Echo-V2-Zeile außer Minis nicht anlegen
            _weg3 = [z for z in zeilen if str(z.get("route") or "") == "mt5v2" and not ((z.get("mt5_baseline") or {}).get("tage_mini"))]
        _e3 = {"echo": 0, "weg": [(z, _g3) for z in _weg3]}
        print(f"[auto-plan] ⚠️ Echo-Hedge beim Planen: {type(e).__name__}: {e} — {len(_e3['weg'])} CFD-Challenge(s) nicht angelegt", flush=True)
    if _e3["weg"]:
        _weg_ids = {id(z) for z, _g in _e3["weg"]}
        _weg_konten = {}
        for z, g in _e3["weg"]:
            _weg_konten[str(z.get("master_account_id"))] = g
        zeilen = [z for z in zeilen if id(z) not in _weg_ids]
        _zeile_je_konto = {str(k["a"]["id"]): k["zeile"] for _key, k, _w, _v in plan_roh}
        geplant = [g for g in geplant if str(g.get("konto_id")) not in _weg_konten]
        for aid, g in _weg_konten.items():
            ausgelassen.append(dict(_zeile_je_konto.get(aid) or {"konto_id": aid}, grund=f"kein Echo-Hedge stellbar — {g} (CFD-Challenges nur mit Hedge)"))
            if not trocken:
                ap_echo_ohne_melden(_zeile_je_konto.get(aid) or {"konto_id": aid}, g, tag)
    if _e3["echo"]:      # PostgREST-Batch: alle Zeilen brauchen dieselben Schlüssel (PGRST102, Prüfung E3) — Hedge-Felder sonst null
        for z in zeilen:
            for f_ in ("slave_account_id", "slave_name", "slave_firm", "multiplier", "slave_risk"):
                z.setdefault(f_, None)
    if _e3["echo"] or _e3["weg"]:
        print(f"[auto-plan] {tag} Echo mit Hedge: {_e3['echo']} geplant, {len(_e3['weg'])} nicht geplant (kein Hedge stellbar)", flush=True)
    geplant.sort(key=lambda g: (g["start"], g["konto_id"]))
    fp = hashlib.sha1(json.dumps([[g["konto_id"], g["start"], g["richtung"], g["tp"], g["sl"], g["menge"]] for g in geplant],
                                 sort_keys=True).encode()).hexdigest()[:12]
    if not trocken and fingerabdruck and fingerabdruck != fp:
        # Stand hat sich seit dem Probelauf geändert (Balance, Plan beendet, Uhrzeit) — nichts löschen, nichts anlegen
        return {"ok": False, "tag": tag, "seed": seed, "fingerabdruck": fp, "abweichung": True,
                "msg": "Stand hat sich seit dem Probelauf geändert — bitte Probelauf neu ansehen, nichts angelegt"}
    if not trocken and not nachplanen:             # NACHPLANEN löscht nie (bestehende Vorschläge/Pläne bleiben)
        weg = {"user_id": in_uids, "auto_plan": "eq.true", "status": "eq.planned",
               "auto_bestaetigt_at": "is.null", "start_um_gestartet_at": "is.null"}
        if _tw_behalt_ids:
            weg["id"] = "not.in.(" + ",".join(_tw_behalt_ids) + ")"   # TW1: Vorschlag eines Pause-Tag-Kontos bleibt (beide DELETE-Zweige unten)
        try:                                       # von Hand geänderte Vorschläge bleiben (hand_werte_at, 08.10.2026)
            _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/trade_plans", headers=_sb_headers(),
                        params=dict(weg, hand_werte_at="is.null")).raise_for_status()
        except Exception as e:
            if not _ap_hand_spalte_fehlt(e):
                raise
            _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/trade_plans", headers=_sb_headers(), params=weg).raise_for_status()
    if zeilen and not trocken:
        r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/trade_plans", json=zeilen,
                        headers=_sb_headers("return=minimal"), timeout=(5, 30))
        if r.status_code == 400 and "tages_grenze_usd" in (r.text or ""):
            # Spalte noch nicht da (sql/2026-10-26_tagesgrenze.sql nicht eingespielt) — ohne sie anlegen, der SL ist schon gekappt
            print("[auto-plan] ⚠️ trade_plans.tages_grenze_usd fehlt — Pläne ohne das Feld angelegt", flush=True)
            r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/trade_plans", json=[{x: v for x, v in z.items() if x != "tages_grenze_usd"} for z in zeilen],
                            headers=_sb_headers("return=minimal"), timeout=(5, 30))
        _sb_pruefen(r)
    erg = {"ok": True, "tag": tag, "quelle": quelle, "trocken": bool(trocken), "at": jetzt.isoformat(), "seed": seed,
           "verfallen": verfallen,   # liegengebliebene Auto-Pläne früherer Tage, die das Konto nicht mehr blockieren (08.10.2026)
           "fingerabdruck": fp, "geplant": geplant, "ausgelassen": ausgelassen, "netto_max_abs": netto_max,
           "band_pct": param["zielband_pct"], "auto_start": param["auto_start"], "einsatz": einsatz_info, "id_misch": id_misch,
           "firma_misch": firma_misch, "misch_fenster": misch_fenster}
    if alle_ids:
        erg["ids_benutzt"] = ap_ids_benutzt(geplant, ausgelassen, namen)     # welche IDs der Lauf über alle IDs wirklich enthält
    if nachplanen:
        erg["nur_konten"] = sorted(nur_set)
    if trocken:
        try:
            erg.update(_ap_probelauf(tr_info, plan_roh, minuten, zinfo, richtung, zeiten, namen, stand, dinfo))
        except Exception as e:      # die Ansicht baut notfalls aus geplant[] — der Probelauf selbst scheitert nicht daran
            print(f"[auto-plan] ⚠️ Probelauf-Zusatz: {type(e).__name__}: {e}", flush=True)
            erg["probelauf_fehler"] = f"{type(e).__name__}: {e}"
    if gruppe:
        erg.update(gruppe_id=str(gruppe.get("gruppe_id") or ""), gruppe=gruppe.get("name"))
    if not trocken and not (nachplanen and not geplant) and not gruppe:   # NACHPLANEN ohne Treffer: kein Lauf-Eintrag, kein Log
        try:
            if quelle == "nacht":
                sb_update("auto_plan_lauf", {"tag": f"eq.{tag}", "quelle": "eq.nacht"}, {"ergebnis": erg})
            else:
                sb_insert("auto_plan_lauf", {"tag": tag, "quelle": quelle, "ergebnis": erg})
        except Exception as e:
            print(f"[auto-plan] ⚠️ Protokoll: {type(e).__name__}: {e}", flush=True)
    if not (nachplanen and not geplant):
        print(f"[auto-plan] {tag} {quelle}: {len(geplant)} geplant, {len(ausgelassen)} ausgelassen", flush=True)
    return ap_sicht(erg, sicht_uid) if sicht_uid is not None else erg   # Protokoll oben vollständig, Antwort nur die eigene ID/Gruppe


# ══ GRUPPEN-PLANER (13.10.2026, Finn: „für Emin so eine kleinere Variante … für seine drei IDs … alle Echo-Trades mit Gegenhedge bei
