def gp_push_ereignisse(plaene, namen, seit_iso):
    """REIN RECHNEND (testbar): Plan-Zeilen {id,user_id,master_name,master_firm,richtung,master_contracts,started_at,sf,ss} → Ereignisse
    [(schluessel, titel, text)] seit seit_iso. Gestartet (started_at) = „Trade gestartet — hat alles geklappt"; Start-Fehler (sf rot) und
    Richtungsschutz (ss, nur der erste Versuch je Plan) = „nicht gestartet" mit Grund."""
    out = []
    for p in plaene or ():
        pid = str(p.get("id"))
        wer = namen.get(str(p.get("user_id")), str(p.get("user_id"))[:8])
        konto = f"{p.get('master_firm') or ''} {p.get('master_name') or ''}".strip()
        if str(p.get("started_at") or "") > seit_iso:
            r = "Long" if p.get("richtung") == "buy" else "Short" if p.get("richtung") == "sell" else ""
            m = _wd_num(p.get("master_contracts"))
            out.append((pid + "|start", "✅ Trade gestartet",
                        f"{wer} · {konto}: {r} {m:g} — hat alles geklappt".replace("  ", " ") if m else f"{wer} · {konto}: hat alles geklappt"))
        sf = p.get("sf") if isinstance(p.get("sf"), dict) else None
        if sf and sf.get("status") == "rot" and str(sf.get("at") or "") > seit_iso and sf.get("schritt") != "ziel_erreicht":
            out.append((f"{pid}|sf|{sf.get('at')}", "⚠ Trade nicht gestartet", f"{wer} · {konto}: {str(sf.get('msg') or 'Start-Check rot')[:150]}"))
        ss = p.get("ss") if isinstance(p.get("ss"), dict) else None
        if ss and ss.get("art") in ("final_halten", "hedge_freigabe", "apex_hedge", "echo_hedge"):   # echo_hedge: ⚪ kommt aus _eh_ohne
            ss = None                                # finaler Tradeify gehalten (29.10.2026): eigene ⚪-Meldung in alarm_ereignisse
        if ss and str(ss.get("at") or "") > seit_iso:
            out.append((pid + "|ss", "⛔ Order ging nicht durch — Richtungsschutz",
                         f"{wer} · {konto}: {str(ss.get('text') or '')[:150]} — neuer Versuch alle ~10 min, Gegen-Trade abhaken löst es"))
    return out


def gp_verwalter_karte():
    """{mitglied_uid: verwalter_uid} aller Gruppen mit Verwalter UND Zeile in auto_plan_gruppe."""
    daten = admin_gruppen_daten()
    zeilen = {str(z.get("gruppe_id")) for z in sb_select("auto_plan_gruppe", {"select": "gruppe_id"}) or []}
    verw = {str(x["id"]): str(x["verwalter_id"]) for x in daten.get("gruppen") or () if x.get("verwalter_id") and str(x["id"]) in zeilen}
    return {str(m.get("user_id")): verw[str(m.get("gruppe_id"))] for m in daten.get("mitglieder") or () if str(m.get("gruppe_id")) in verw}


# ══ GRUPPE WIE HT (30.10.2026, Finn 04:24: „Emins Trades sollen eins zu eins mit der gleichen Logik geplant werden wie bei Hermann
# Technologies, bei Echo genauso … Die Trades werden geplant, er bestätigt sie einzeln" + „Emin hat eine eigene Waage zwischen Long und
# Short … Jede Gruppe wiegt für sich"). Statt des eigenen Gruppen-Planers (gp_planen/gp_tick, abgeschaltet, nicht gelöscht) plant der
# HT-Planer (ap_planen) jede Verwalter-Gruppe mit Zeile in auto_plan_gruppe getrennt: gleicher Nachtlauf-Zeitpunkt, gleiche Regeln,
# Stand/Waage/Abstände nur aus der Gruppe. Echo mit Hedge, finaler Tradeify und Apex-Hedge stellen ihre Pläne um wie bei HT
# (ap_planer_gruppen_ids). Bestätigen bleibt einzeln (Auto-Bestätigen gilt nur auto_plan_regeln.user_ids). Firmen-Abstand und
# Gegenrichtungs-Riegel bleiben in der DB je Gruppe (prophos_gruppe_von). Claim + Protokoll je Gruppe in auto_plan_gruppe.letzter_lauf. ══
def ap_planer_gruppen_ids():
    """IDs aller Verwalter-Gruppen mit Planer-Zeile (Verwalter + Mitglieder) als set — sie laufen seit 30.10.2026 wie HT durch die Umsteller."""
    k = gp_verwalter_karte()
    return {str(u) for u in k} | {str(u) for u in k.values()}


def ap_gruppe_ausgeblendet(namen, ids):
    """REIN RECHNEND: Ausblendung für den Stand EINER Gruppe — alle bekannten IDs außer ihren (jede Gruppe wiegt für sich)."""
    return {str(u) for u in (namen or ())} - {str(u) for u in (ids or ())}


# ══ UNTERNEHMEN HABEN NICHTS GEGENEINANDER (UNT2, 05.11.2026, Finn-Grundsatz; berichte G2 A1–A5/A11, G2b Schritt 2): der Stand eines
# Unternehmens wird EXPLIZIT aus der Gruppen-Zugehörigkeit gefiltert, nicht aus der Sicht des Requests (_admin_standard_aus ist bei
# eingeschränktem Login / Gruppen-Chip leer — dann zählte HT Emins Pläne mit) und nicht aus der „Rest"-Annahme über die Nutzerliste.
# HT = die IDs der Gruppe(n) ohne Verwalter, eine Gruppe = genau ihre IDs. OHNE UNTERNEHMEN (UNT0, Master 05.11.2026: „ohne Unternehmen = nur sich
# selbst, nichts gekoppelt"): eine ID ohne Zeile in id_gruppe_mitglied (und nicht Verwalter) ist ein Topf für sich — nie im HT-Stand, keine Waage,
# kein Deckel, kein WD-Pool mit irgendwem (wie admin_ohne_unternehmen). Ohne Gruppen-Tabellen (gruppen leer) ist wie vor den Gruppen alles HT. ══
def ap_unternehmen_filter(eigene, daten):
    """REIN RECHNEND: gehört(uid) → bool für den Stand EINES Unternehmens. eigene=None → HT (daten = admin_gruppen_daten(): weder in einer
    Verwalter-Gruppe noch ohne Unternehmen), sonst genau die IDs in eigene."""
    if eigene is None:
        daten = daten or {}
        fremd = frozenset(_admin_verwalter_gruppen_ids(daten))
        if not (daten.get("gruppen") or ()):
            return lambda u: str(u) not in fremd
        drin = frozenset(str(m.get("user_id")) for m in daten.get("mitglieder") or ())
        return lambda u: str(u) in drin and str(u) not in fremd
    eig = frozenset(str(u) for u in eigene)
    return lambda u: str(u) in eig


def ap_unternehmen_ids(uid, daten):
    """REIN RECHNEND: IDs (frozenset) des Unternehmens von uid, wenn es nicht HT ist — Verwalter-Gruppe (Verwalter + Mitglieder) bzw. bei einer
    ID ohne Unternehmen (UNT0) nur sie selbst —, sonst None = HT."""
    daten = daten or {}
    for x in daten.get("gruppen") or ():
        v = x.get("verwalter_id")
        if not v:
            continue
        ids = frozenset({str(v)} | {str(m.get("user_id")) for m in daten.get("mitglieder") or () if str(m.get("gruppe_id")) == str(x.get("id"))})
        if str(uid) in ids:
            return ids
    if (daten.get("gruppen") or ()) and str(uid) not in {str(m.get("user_id")) for m in daten.get("mitglieder") or ()}:
        return frozenset({str(uid)})               # ohne Unternehmen: Topf für sich
    return None


def ap_unternehmen_karte(daten):
    """REIN RECHNEND: {uid: Schlüssel} — Verwalter-Gruppe = gruppe_id, HT-Mitglied = „ht". Leer ohne Gruppen-Tabellen (dann alles HT).
    Nachschlagen über ap_unternehmen_schluessel (ID ohne Unternehmen = eigener Schlüssel „solo:<uid>")."""
    daten = daten or {}
    out = {}
    gruppen = daten.get("gruppen") or ()
    mit_v = {str(x.get("id")) for x in gruppen if x.get("verwalter_id")}
    for m in daten.get("mitglieder") or ():
        out[str(m.get("user_id"))] = str(m.get("gruppe_id")) if str(m.get("gruppe_id")) in mit_v else "ht"
    for x in gruppen:
        if x.get("verwalter_id"):
            out[str(x["verwalter_id"])] = str(x.get("id"))
    return out


def ap_unternehmen_schluessel(uid, karte):
    """REIN RECHNEND: Unternehmens-Schlüssel einer ID aus ap_unternehmen_karte — unbekannt: „ht", solange es keine Gruppen gibt (karte leer),
    sonst „solo:<uid>" (ohne Unternehmen, UNT0: koppelt mit niemandem)."""
    k = (karte or {}).get(str(uid))
    if k is not None:
        return k
    return "ht" if not karte else "solo:" + str(uid)


# ══ LESEWEGE NUR IM EIGENEN UNTERNEHMEN (UNT5, 05.11.2026, Finn: „Finn + Pascal sehen als HT-Admins nichts von Emin, und Emin sieht nichts von HT";
# G2b Schritt 1, Rest im Backend, den die G3-RLS nicht abdeckt). Fail-closed: Unternehmen nicht lesbar → nur die eigene ID. ══
def ap_unternehmen_von_login(uid, daten):
    """REIN RECHNEND: gehört(u) → bool = gleiches Unternehmen wie der Login uid (HT / Verwalter-Gruppe / ohne Unternehmen = nur er selbst)."""
    return ap_unternehmen_filter(ap_unternehmen_ids(uid, daten), daten)


def unt_sicht_login(uid):
    """gehört(u) für das Unternehmen des Logins — Gruppen nicht lesbar → nur die eigene ID (fail-closed, Meldung)."""
    try:
        return ap_unternehmen_von_login(uid, admin_gruppen_daten())
    except Exception as e:
        print(f"[unternehmen] ⚠️ Gruppen nicht lesbar ({type(e).__name__}: {e}) — Sicht nur die eigene ID", flush=True)
        return lambda u: str(u) == str(uid)


def ap_admins_fuer(uid, ht_admins, daten):
    """REIN RECHNEND: Admins des Unternehmens der ID uid (Empfänger von Pushes über ihre Konten): HT → ht_admins (ADMIN_EMAILS-IDs, wie bisher);
    Verwalter-Gruppe → ihr Verwalter; ohne Unternehmen → keiner (nur der Besitzer selbst bekommt die Meldung)."""
    eig = ap_unternehmen_ids(uid, daten)
    if eig is None:
        return set(ht_admins or ())
    daten = daten or {}
    for x in daten.get("gruppen") or ():
        v = x.get("verwalter_id")
        if v and str(v) in eig:
            return {str(v)}
    return set()


def _admins_fuer_uid(uid, ht_admins):
    """ap_admins_fuer mit admin_gruppen_daten — nicht lesbar → keiner (nur der Besitzer, fail-closed)."""
    try:
        return ap_admins_fuer(uid, ht_admins, admin_gruppen_daten())
    except Exception as e:
        print(f"[unternehmen] ⚠️ Gruppen nicht lesbar ({type(e).__name__}: {e}) — Push nur an den Besitzer", flush=True)
        return set()


def ap_ppl_firma_je_unternehmen(rows, karte, norm=None):
    """REIN RECHNEND: firm_specs-Zeilen → {unternehmen: je_firma} (ap_ppl_karte je Unternehmen getrennt) — der Fallback-Punktwert einer
    Firma kommt nur aus dem eigenen Unternehmen (G2 A2)."""
    teile = {}
    for r in rows or ():
        teile.setdefault(ap_unternehmen_schluessel(r.get("user_id"), karte), []).append(r)
    return {k: ap_ppl_karte(v, norm=norm)[1] for k, v in teile.items()}


def ap_ppl_firma_wahl(ctx, uid, fk):
    """Fallback-Punktwert (ppl, symbol, unit) der Firma fk für die ID uid: mit ctx["ppl_firma_je"] aus ihrem Unternehmen
    (ctx["unternehmen_von"] = ap_unternehmen_karte), sonst ctx["ppl_firma"] (der ctx kennt nur ein Unternehmen, z. B. der Planer-Stand)."""
    je = (ctx or {}).get("ppl_firma_je")
    if je is not None:
        return (je.get(ap_unternehmen_schluessel(uid, (ctx or {}).get("unternehmen_von"))) or {}).get(fk)
    return ((ctx or {}).get("ppl_firma") or {}).get(fk)


def ap_ppl_ctx_unternehmen(rows, norm=None):
    """firm_specs-Zeilen (mehrerer Unternehmen) → {ppl, ppl_firma, ppl_firma_je, unternehmen_von} für die Hedge-/Funded-Takte.
    Gruppen nicht lesbar → wie vor UNT2 (ein Fallback über alle, Meldung): ein fehlender Punktwert hielte sonst einen Hedge an."""
    ppl, ppl_firma = ap_ppl_karte(rows, norm=norm)
    ctx = {"ppl": ppl, "ppl_firma": ppl_firma}
    try:
        karte = ap_unternehmen_karte(admin_gruppen_daten())
        ctx.update(ppl_firma_je=ap_ppl_firma_je_unternehmen(rows, karte, norm=norm), unternehmen_von=karte)
    except Exception as e:
        print(f"[unternehmen] ⚠️ Gruppen für den Punktwert-Rückfall nicht lesbar ({type(e).__name__}: {e}) — Rückfall über alle", flush=True)
    return ctx


def _ap_stand_fuer_uid(reg, uid, jetzt=None, **kw):
    """Live-Stand des Unternehmens, zu dem die ID uid gehört (Hand-Eingriffe je Plan: Nachholen, Startzeit, Bot-Eingriff) — HT-Plan gegen den
    HT-Stand, Gruppen-Plan gegen den Stand seiner Gruppe. Gruppen nicht lesbar → Fehler fliegt (nie still gegen beide Unternehmen)."""
    eig = ap_unternehmen_ids(uid, admin_gruppen_daten())
    if eig is None:
        return _ap_stand_laden(reg, jetzt, **kw)
    namen, _aus = _ap_namen()
    return _ap_stand_laden(reg, jetzt, namen=namen, ausgeblendet=ap_gruppe_ausgeblendet(namen, eig), eigene=eig, **kw)


def ap_planer_gruppen(nur_aktiv=False):
    """[{gruppe_id, name, ids (frozenset), aktiv, letzter_lauf}] — Verwalter-Gruppen mit Zeile in auto_plan_gruppe."""
    daten = admin_gruppen_daten()
    zeilen = {str(z.get("gruppe_id")): z for z in sb_select("auto_plan_gruppe", {"select": "gruppe_id,aktiv,letzter_lauf"}) or []}
    out = []
    for x in daten.get("gruppen") or ():
        gid, z = str(x.get("id")), zeilen.get(str(x.get("id")))
        if not x.get("verwalter_id") or not z or (nur_aktiv and not z.get("aktiv")):
            continue
        ids = frozenset({str(x["verwalter_id"])} | {str(m.get("user_id")) for m in daten.get("mitglieder") or ()
                                                    if str(m.get("gruppe_id")) == gid})
        out.append({"gruppe_id": gid, "name": x.get("name"), "ids": ids, "aktiv": bool(z.get("aktiv")), "letzter_lauf": z.get("letzter_lauf")})
    return out


_ap_gruppen_cache = {"bis": 0.0, "liste": None}


def ap_gruppe_von_uid(uid, gruppen=None):
    """Planer-Gruppe (ap_planer_gruppen-Zeile) dieser ID oder None (= HT). Ohne gruppen: Liste 30 s gemerkt — GET /admin/auto-plan fragt
    das je PC-Tab beim Laden; Claim/Protokoll (ap_gruppe_planen, Nachtlauf) lesen immer frisch."""
    if gruppen is None:
        with _kurz_cache_lock:
            if _ap_gruppen_cache["liste"] is not None and _ap_gruppen_cache["bis"] > time.time():
                gruppen = _ap_gruppen_cache["liste"]
        if gruppen is None:
            gruppen = ap_planer_gruppen()
            with _kurz_cache_lock:
                _ap_gruppen_cache.update(bis=time.time() + 30, liste=gruppen)
    for gr in gruppen:
        if str(uid) in gr["ids"]:
            return gr
    return None


def ap_gruppe_tag(tag, jetzt=None):
    """tag aus Knopf/Body → Planer-Tag (Dubai-Datum wie ap_planen): None/'' = heute, 'heute', 'morgen' (nächster Handelstag) oder JJJJ-MM-TT."""
    t = str(tag or "").strip().lower()
    if not t or t == "heute":
        return None
    jetzt = jetzt or datetime.now(timezone.utc)
    return gp_tag_wahl(t, jetzt.astimezone(_ap_tz(AP_TZ_LAUF))).isoformat()


def ap_gruppe_lauf_ohne_erledigt(letzter):
    """REIN RECHNEND (GRUPPE NACHPLANEN, 02.11.2026): Lauf ohne die „letzter Trade noch nicht erledigt"-Zeilen — für die Kandidaten, nicht
    für die Anzeige. Der Grund gilt in AP_NACHPLAN_FEST_GRUENDE als fest, stimmt aber nach dem Abhaken nicht mehr; ohne die Zeile entscheidet
    der Stand der Pläne: noch in Überprüfen oder heute abgehakt → _ap_plan_am_tag belegt das Konto, sonst wird es nachgeplant."""
    if not isinstance(letzter, dict) or not isinstance(letzter.get("ausgelassen"), list):
        return letzter
    return dict(letzter, ausgelassen=[z for z in letzter["ausgelassen"]
                                      if not str((z or {}).get("grund") or "").startswith("letzter Trade ")])


def ap_gruppe_lauf_mischen(alt, erg, nur_konten):
    """REIN RECHNEND (GRUPPE NACHPLANEN, 02.11.2026): (Protokoll, geändert?) nach einem Nachplanen. Die Gruppe hat nur EINE Lauf-Zeile: die
    Zeilen der nicht nachgerechneten Konten bleiben stehen, sonst fielen ihre festen Gründe aus „Braucht dich" und die Konten würden im
    nächsten Takt neu gerechnet. geändert = neuer Plan oder ein anderer Grund bei einem nachgerechneten Konto; sonst kein Schreiben."""
    alt = alt if isinstance(alt, dict) else {}
    nur = {str(k) for k in nur_konten or ()}
    gleicher_tag = str(alt.get("tag") or "") == str(erg.get("tag") or "")
    alt_aus = [z for z in alt.get("ausgelassen") or [] if isinstance(z, dict)] if gleicher_tag else []
    neu_aus = [z for z in erg.get("ausgelassen") or [] if isinstance(z, dict)]

    def _gruende(zeilen):
        return {str(z.get("konto_id")): str(z.get("grund") or "") for z in zeilen if str(z.get("konto_id")) in nur}
    geaendert = bool(erg.get("geplant")) or _gruende(alt_aus) != _gruende(neu_aus)
    merk = dict(erg, geplant=(list(alt.get("geplant") or []) if gleicher_tag else []) + list(erg.get("geplant") or []),
                ausgelassen=[z for z in alt_aus if str(z.get("konto_id")) not in nur] + neu_aus)
    return merk, geaendert


def ap_gruppe_planen(gruppe_id, trocken=False, quelle="hand", tag=None, seed=None, nur_konten=None):
    """Plant eine Verwalter-Gruppe mit dem HT-Planer (ap_planen gruppe=…). Nicht trocken: Ergebnis in auto_plan_gruppe.letzter_lauf
    (nacht_tag bleibt erhalten — er ist der Nacht-Claim der Gruppe). → Ergebnis-Dict wie ap_planen.
    nur_konten (GRUPPE NACHPLANEN, 02.11.2026): nur diese Konten für genau diesen Tag, bestehende Vorschläge bleiben; Protokoll gemischt
    (ap_gruppe_lauf_mischen) und nur bei Änderung."""
    gr = next((x for x in ap_planer_gruppen() if x["gruppe_id"] == str(gruppe_id)), None)
    if not gr:
        return {"ok": False, "msg": "Gruppe ohne Planer-Zeile (auto_plan_gruppe) oder ohne Verwalter"}
    if quelle == "nacht":
        # Nachtlauf (Prüfung 30.10.2026): der fällige Tag kommt fertig aus ap_nacht_ziel — nie über gp_tag_wahl klemmen (zwischen
        # Dubai-Mitternacht und 01:00 Dubai wäre „heute in Dubai" schon T+1, nacht_tag ≠ Takt-Tag → alle 10 min neu gewürfelt).
        # Claim VOR dem Lauf wie HT (auto_plan_lauf-Insert): nur wer nacht_tag in derselben Anfrage setzt, plant — zweiter Container/
        # Takt bekommt keine Zeile zurück. Schlägt das Planen danach fehl, bleibt der Claim (wie HT: kein Neuwürfeln im Minutentakt).
        tag = str(tag or "")
        alt = gr.get("letzter_lauf") if isinstance(gr.get("letzter_lauf"), dict) else {}
        if not re.match(r"^\d{4}-\d{2}-\d{2}$", tag):
            return {"ok": False, "msg": "Nachtlauf ohne Tag"}
        try:
            claim = sb_update("auto_plan_gruppe", {"gruppe_id": f"eq.{gr['gruppe_id']}",
                                                   "or": f"(letzter_lauf.is.null,letzter_lauf->>nacht_tag.is.null,letzter_lauf->>nacht_tag.neq.{tag})"},
                              {"letzter_lauf": dict(alt, nacht_tag=tag, nacht_claim_at=datetime.now(timezone.utc).isoformat()),
                               "updated_at": datetime.now(timezone.utc).isoformat()})
        except Exception as e:
            print(f"[gruppen-plan] ⚠️ Nacht-Claim {str(gr['gruppe_id'])[:8]}: {type(e).__name__}: {e}", flush=True)
            return {"ok": False, "msg": f"Nacht-Claim nicht möglich: {type(e).__name__}"}
        if not claim:
            return {"ok": True, "tag": tag, "msg": "schon geplant (anderer Lauf)", "geplant": [], "ausgelassen": []}
    elif not nur_konten:                               # Nachplanen: der Takt gibt den Tag fertig vor (deutscher Tag, wie HT)
        try:
            tag = ap_gruppe_tag(tag)
        except ValueError:
            return {"ok": False, "msg": "tag = heute | morgen | JJJJ-MM-TT"}
    erg = ap_planen(tag, trocken=trocken, quelle=quelle, seed=seed, gruppe=gr, nur_konten=nur_konten)
    if not trocken and erg.get("ok"):
        alt = gr.get("letzter_lauf") if isinstance(gr.get("letzter_lauf"), dict) else {}
        basis, geaendert = ap_gruppe_lauf_mischen(alt, erg, nur_konten) if nur_konten else (erg, True)
        if not geaendert:
            return erg
        merk = dict(basis, nacht_tag=tag if quelle == "nacht" else alt.get("nacht_tag"))
        try:
            sb_update("auto_plan_gruppe", {"gruppe_id": f"eq.{gr['gruppe_id']}"}, {"letzter_lauf": merk,
                                                                                 "updated_at": datetime.now(timezone.utc).isoformat()})
        except Exception as e:
            print(f"[gruppen-plan] ⚠️ Protokoll {str(gr['gruppe_id'])[:8]}: {type(e).__name__}: {e}", flush=True)
    return erg


_ap_gruppen_nacht = {"fehler": "", "letzt": {}}


def ap_gruppen_nacht_tick(jetzt, zustand):
    """Nachtlauf der Verwalter-Gruppen (aus ap_loop, jede Minute): derselbe fällige Tag wie HT (ap_nacht_ziel mit zeiten.nachtlauf aus
    zustand, ap_nacht_tick liest sie) — je aktiver Gruppe einmal ap_gruppe_planen(quelle='nacht'), Claim = letzter_lauf.nacht_tag.
    Es gelten beide Schalter: auto_plan_regeln.aktiv (HT-Pause pausiert auch die Gruppen) und auto_plan_gruppe.aktiv."""
    param = zustand.get("nacht_param") or dict(AP_NACHT_STANDARD)
    faellig, _naechster = ap_nacht_ziel(jetzt, param)
    if not faellig:
        return None
    tag = faellig[0].isoformat()
    if _ap_gruppen_nacht.get("tag") == tag and time.time() - (_ap_gruppen_nacht.get("geprueft") or 0) < 600:
        return None
    _ap_gruppen_nacht.update(tag=tag, geprueft=time.time())
    # eins zu eins wie HT (Prüfung 30.10.2026): pausiert Finn den Planer (auto_plan_regeln.aktiv = false), plant auch keine Gruppe
    if not (sb_select("auto_plan_regeln", {"select": "aktiv", "id": "eq.1"}) or [{}])[0].get("aktiv"):
        return None
    for gr in ap_planer_gruppen(nur_aktiv=True):
        ll = gr.get("letzter_lauf") if isinstance(gr.get("letzter_lauf"), dict) else {}
        if ll.get("nacht_tag") == tag:
            continue
        try:
            erg = ap_gruppe_planen(gr["gruppe_id"], quelle="nacht", tag=tag)
            _ap_gruppen_nacht["letzt"][gr["gruppe_id"]] = {"tag": tag, "geplant": len(erg.get("geplant") or []), "msg": erg.get("msg")}
            _ap_gruppen_nacht["fehler"] = ""
        except Exception as e:
            _ap_gruppen_nacht["fehler"] = f"{type(e).__name__}: {e}"
            print(f"[gruppen-plan] ⚠️ Nachtlauf {str(gr['gruppe_id'])[:8]}: {_ap_gruppen_nacht['fehler']}", flush=True)
    return True


def gp_push_senden(verwalter, meldungen):
    """meldungen [(titel, text)] an die Geräte des Verwalters — mehr als 3 in einem Takt als EINE Sammelmeldung."""
    if not meldungen:
        return
    if len(meldungen) > 3:
        meldungen = [(f"Prophos · {len(meldungen)} Meldungen", " · ".join(t for _ti, t in meldungen)[:220])]
    for titel, text in meldungen:
        link = GP_PUSH_LINK_BESTAETIGEN if "bestätigen" in titel else GP_PUSH_LINK
        push_an_user(verwalter, titel, text, url=link, tag="gp-" + hashlib.sha1(text.encode()).hexdigest()[:10], renotify=True)


def gp_push_tick():
    """Railway-Takt (ap_loop): jede Minute Starts/Fehler der Gruppen-IDs der letzten GP_PUSH_FENSTER_MIN an den Verwalter."""
    if time.time() - _gp_push["letzt"] < GP_PUSH_TAKT_S or not push_bereit():
        return
    _gp_push["letzt"] = time.time()
    karte = gp_verwalter_karte()
    if not karte:
        return
    jetzt = datetime.now(timezone.utc)
    seit = max(datetime.fromtimestamp(_gp_push["start"], timezone.utc), jetzt - timedelta(minutes=GP_PUSH_FENSTER_MIN)).isoformat()
    rows = _sb_all("trade_plans", {"select": "id,user_id,master_name,master_firm,richtung,master_contracts,started_at,"
                                             "sf:mt5_baseline->start_fehler,ss:mt5_baseline->start_sperre",
                                   "user_id": "in.(" + ",".join(sorted(karte)) + ")", "updated_at": f"gte.{seit}"})
    namen, _aus = _ap_namen()
    je = {}
    for key, titel, text in gp_push_ereignisse(rows, namen, seit):
        if key in _gp_push["gemeldet"]:
            continue
        _gp_push["gemeldet"][key] = time.time()
        uid = key.split("|", 1)[0]
        user = next((str(r.get("user_id")) for r in rows if str(r.get("id")) == uid), None)
        if user in karte:
            je.setdefault(karte[user], []).append((titel, text))
    for verwalter, meldungen in je.items():
        gp_push_senden(verwalter, meldungen)
        print(f"[gruppen-push] {len(meldungen)} Meldung(en) an Verwalter {verwalter[:8]}", flush=True)
    alt = time.time() - 86400
    _gp_push["gemeldet"] = {k: v for k, v in _gp_push["gemeldet"].items() if v > alt}


def gp_takt_faellig(lokal, zeiten):
    """REIN RECHNEND (testbar): darf der Gruppen-Planer jetzt (lokal = deutsche Zeit) laufen? Mo–Fr, ab zeiten.lauf bis bis − Vorlauf."""
    if lokal.weekday() >= 5:
        return False
    m = lokal.hour * 60 + lokal.minute
    return _ap_hhmm(zeiten.get("lauf") or "06:00") <= m < _ap_hhmm(zeiten.get("bis") or "17:20") - GP_VORLAUF_MIN


def gp_auftrag_tick():
    """EINMAL-AUFTRAG per DB (13.10.2026, Finn: „plan die Trades für morgen zum Testen"): auto_plan_gruppe.zeiten.auftrag = 'morgen' |
    'heute' | 'JJJJ-MM-TT' → einmal gp_planen(tag=…), unabhängig vom Takt-Fenster. Der Auftrag wird vorher per bedingtem Update
    weggenommen (Claim) — zwei Container planen nie doppelt. Läuft im 60-s-Takt mit den Handy-Meldungen."""
    for z in sb_select("auto_plan_gruppe", {"select": "gruppe_id,zeiten", "zeiten->>auftrag": "not.is.null"}) or []:
        zeiten = dict(z.get("zeiten") or {})
        auftrag = str(zeiten.pop("auftrag", "") or "").strip()
        r = _sb_anfrage("PATCH", f"{SUPABASE_URL}/rest/v1/auto_plan_gruppe", headers=_sb_headers("return=representation"),
                        params={"gruppe_id": f"eq.{z['gruppe_id']}", "zeiten->>auftrag": f"eq.{auftrag}"}, json={"zeiten": zeiten})
        _sb_pruefen(r)
        if not r.json():
            continue                                  # ein anderer Container hat ihn schon
        erg = gp_planen(z["gruppe_id"], quelle="auftrag", tag=auftrag or None)
        print(f"[gruppen-plan] Auftrag {auftrag}: {erg.get('msg') or str(len(erg.get('geplant') or [])) + ' geplant'}", flush=True)


def gp_tick(jetzt=None):
    """Railway-Takt (ap_loop): alle GP_TAKT_S je aktiver Gruppe gp_planen(quelle='takt') — plant nur Konten ohne Plan für heute."""
    if time.time() - (_gp_info.get("letzter_takt") or 0) < GP_TAKT_S:
        return
    _gp_info["letzter_takt"] = time.time()
    jetzt = jetzt or datetime.now(timezone.utc)
    for z in sb_select("auto_plan_gruppe", {"select": "gruppe_id,aktiv,zeiten", "aktiv": "is.true"}) or []:
        zeiten = dict(GP_ZEITEN_STANDARD, **(z.get("zeiten") or {}))
        if not gp_takt_faellig(jetzt.astimezone(_ap_tz(zeiten["tz"])), zeiten):
            continue
        try:
            gp_planen(z["gruppe_id"], quelle="takt")
            _gp_info["laeufe"] = (_gp_info.get("laeufe") or 0) + 1
            _gp_info["fehler"] = ""
        except Exception as e:
            _gp_info["fehler"] = f"{type(e).__name__}: {e}"
            print(f"[gruppen-plan] ⚠️ {str(z.get('gruppe_id'))[:8]}: {_gp_info['fehler']}", flush=True)


