AP_WAAGE_TOL_EUR = 250.0          # CFD: Lücke bis 250 € passt (Finn 18.10.2026: „Toleranz auf 250 anpassen", vorher 180) …
AP_WAAGE_TOL_PCT = 0.20           # … oder bis 20 % der schwereren Seite
