# auf firma_key/Firmenname, klein); [] = alle Firmen wiegen wieder mit.
AP_WAAGE_OHNE_FIRMEN = ("apex",)


def ap_waage_an(regeln):
    """Schalter regeln.ausgleich.waage — Standard an; nur ein echtes false schaltet zurück auf den alten Ausgleichs-Bot."""
    a = (regeln or {}).get("ausgleich") if isinstance(regeln, dict) else None
    return not (isinstance(a, dict) and a.get("waage") is False)


def ap_waage_ohne_liste(stand):
    """Firmen, die in keiner Waage mitzählen: stand['param']['waage_ohne'] (aus regeln.ausgleich.waage_ohne), sonst AP_WAAGE_OHNE_FIRMEN."""
    p = (stand or {}).get("param") if isinstance(stand, dict) else None
    o = p.get("waage_ohne") if isinstance(p, dict) else None
    if isinstance(o, (list, tuple)):
        return tuple(str(x).strip().lower() for x in o if str(x).strip())
    return AP_WAAGE_OHNE_FIRMEN


def ap_waage_ohne(z, ohne):
    """REIN RECHNEND: gehört die Zeile zu einer Firma ohne Waage (Apex, 19.10.2026)? Teilstring auf firma_key oder Firmenname."""
    if not ohne:
        return False
    t = f"{z.get('firma_key') or ''}|{z.get('firma') or ''}".lower()
    # TM1 (Fremd-Review 05.11.2026): Tradeify Futures auf Orbit Prio 2 legt den Schlüssel 'tradeify' in waage_ohne — als Teilstring träfe er auch
    # „Tradeify CFD“ und nähme sie aus der CFD-Waage. Für eine Tradeify-CFD-Zeile zählen nur Schlüssel, die selbst „cfd“ enthalten (Erkennung wie
    # _ist_tradeify_cfd, hier ohne Aufruf, weil die Waage-Selbsttests ap_waage_ohne einzeln laden)
    _tn = "".join(c for c in t if c.isascii() and c.isalnum())
    if "tradeify" in _tn and "cfd" in _tn:
        return any(k and k in t and "cfd" in k for k in ohne)
    return any(k and k in t for k in ohne)


def _ap_waage_gewicht(z):
    """Eröffnungs-Gewicht € eines Trades (verlust_eur = min(Satz × SL, Kontowert), ohne SL = Kontowert) — voll, kein SL-Rest."""
    for k in ("verlust_eur", "einsatz_abs"):
        g = _wd_num(z.get(k))
        if g is not None:
            return abs(float(g))
    e = _wd_num(z.get("einsatz_eur"))
    return abs(float(e)) if e is not None else 0.0


def _ap_waage_startet(z):
    """Ein geplanter Plan startet wirklich: Hand-Plan, bestätigter Auto-Plan oder schon geclaimt."""
    return (not z.get("auto_plan")) or bool(z.get("bestaetigt")) or bool(z.get("geclaimt"))


def ap_waage_zeile_zaehlt(z, jetzt_min, pc_lebt=None, laufend=False):
    """REIN RECHNEND: zählt die Zeile in der Waage? Eigene Planer-Trades (AP_TYPEN) ohne Hedge mit Richtung; laufend immer,
    geplant nur, wenn er in ≤ AP_WAAGE_BALD_MIN startet (oder geclaimt ist und noch nicht 15 min drüber) und sein PC lebt."""
    if z.get("richtung") not in ("buy", "sell") or z.get("gehedgt") or str(z.get("typ") or "") not in AP_TYPEN:
        return False
    if z.get("tage_mini"):
        return False          # TAGE-MINI (30.10.2026, Befund S6): 0,01 Lot „Tage sammeln" zählt nie in der Waage — weder laufend noch geplant
    if laufend:
        return True
    if z.get("folgetag") or z.get("start_min") is None:
        return False
    if pc_lebt is not None and str(z.get("user_id")) not in pc_lebt:
        return False
    m, jm = float(z["start_min"]), float(jetzt_min)
    if z.get("geclaimt"):
        return jm - AP_WAAGE_CLAIM_MAX_MIN <= m <= jm + AP_WAAGE_BALD_MIN
    return _ap_waage_startet(z) and jm - 1.0 <= m <= jm + AP_WAAGE_BALD_MIN


def _ap_eur_txt(x):
    return f"{float(x):,.0f}".replace(",", ".")


def ap_waage_passt(klasse, w):
    """REIN RECHNEND: (passt, grund, leichte Richtung 'buy'|'sell'|None) einer Klassen-Waage {long_eur, short_eur, n_long, n_short}."""
    nl, ns = int(w.get("n_long") or 0), int(w.get("n_short") or 0)
    l, s = float(w.get("long_eur") or 0), float(w.get("short_eur") or 0)
    if nl == 0 and ns == 0:
        return True, None, None
    if nl == 0:
        return False, f"{ns} Short{'s' if ns != 1 else ''} laufen, kein Long", "buy"
    if ns == 0:
        return False, f"{nl} Long{'s' if nl != 1 else ''} laufen, kein Short", "sell"
    if klasse == "futures":
        if nl > AP_WAAGE_FUT_MAX * ns:
            return False, f"{nl} Long : {ns} Short (höchstens 2 : 1)", "sell"
        if ns > AP_WAAGE_FUT_MAX * nl:
            return False, f"{nl} Long : {ns} Short (höchstens 1 : 2)", "buy"
        return True, None, None
    tol = max(AP_WAAGE_TOL_EUR, AP_WAAGE_TOL_PCT * max(l, s))
    if abs(l - s) > tol:
        return False, f"Lücke {_ap_eur_txt(abs(l - s))} € ({_ap_eur_txt(l)} Long : {_ap_eur_txt(s)} Short, höchstens {_ap_eur_txt(tol)} €)", \
            ("buy" if l < s else "sell")
    return True, None, None


AP_WAAGE_GROESSE_RE = re.compile(r"(?:^|[^0-9])(\d{2,3})\s*k(?:\b|tc)", re.I)


def ap_waage_groesse(name, account_size):
    """REIN RECHNEND (testbar) — Waage-Deckel je Kontogröße (Finn 02.11.2026): „150k“ aus dem Namen zuerst (auch Topstep „150KTC-…“), sonst
    account_size, sonst „unbekannt“. Dieselbe Regel wie sql/2026-11-02_waage_deckel_je_groesse.sql prophos_waage_groesse; starting_balance nie."""
    m = AP_WAAGE_GROESSE_RE.search(str(name or ""))
    if m:
        return f"{int(m.group(1))}k"
    g = _wd_num(account_size)
    return f"{int(round(g / 1000))}k" if g and g > 0 else "unbekannt"


def ap_waage_deckel(klasse, w, richtung, max_abstand=2.0, groesse=None):
    """REIN RECHNEND (testbar) — WAAGE-DECKEL (Finn 23.10.2026, live 1 Long : 7 Short: „4:1 ist too much, 7:1 sowieso. Dann lieber gar keinen
    Trade starten. Verschieben geht" — „Mach die Regel mit ‚würde‘" — ~14:05: „Nie mehr als 2 darf der Abstand sein. 3:1 okay, 4:1 nicht okay.
    2:0 okay, 3:0 nicht mehr. Immer 2 darf der Abstand sein.").
    w = Futures-Waage MIT diesem Start (ap_klassen_waage extra / start_lage nachher). Ein automatischer Start, nach dem seine Seite mehr als
    max_abstand Trades über der anderen liegt, startet nicht — keine Ausnahme durch „Gegentrade folgt", Paar oder Drehen. Nur Futures (CFD hat
    die €-Waage), nur die Seite, die er schwerer macht: ein Start in die leichte Seite ist nie gesperrt. 3 : 1 / 2 : 0 / 6 : 4 frei,
    4 : 1 / 3 : 0 / 7 : 4 gesperrt. → (sperrt, grund)
    JE KONTOGRÖSSE (Finn 02.11.2026): mit groesse zählt nur w["je_groesse"][groesse] — ein 50k-Long gleicht keinen 150k-Short aus. „unbekannt“ sperrt
    immer (eigene Waage, nie frei). Ohne groesse wie bisher über die ganze Klasse."""
    if klasse != "futures" or richtung not in ("buy", "sell"):
        return False, None
    try:
        m = max(1.0, float(max_abstand))
    except (TypeError, ValueError):
        m = 2.0
    if groesse is not None:
        if groesse == "unbekannt":
            return True, "Futures: Kontogröße unbekannt (Name ohne „…k“, account_size leer) — eigene Waage, startet nie automatisch"
        w = dict((w.get("je_groesse") or {}).get(groesse) or {"n_long": 0, "n_short": 0}, groesse=groesse)
    nl, ns = int(w.get("n_long") or 0), int(w.get("n_short") or 0)
    seite, andere = (nl, ns) if richtung == "buy" else (ns, nl)
    if seite - andere <= m:
        return False, None
    return True, (f"Futures{' ' + w['groesse'] if w.get('groesse') else ''} würde {nl} Long : {ns} Short (Abstand höchstens {m:g}) — der {'Long' if richtung == 'buy' else 'Short'} "
                  f"startet nicht, bis das Buch es zulässt")


def _ap_waage_note(klasse, w):
    """Sortierschlüssel: (passt nicht, Schieflage) — kleiner = besser. Futures nach Anzahl, CFD nach €."""
    ok = ap_waage_passt(klasse, w)[0]
    if klasse == "futures":
        return (0 if ok else 1, abs(int(w.get("n_long") or 0) - int(w.get("n_short") or 0)))
    return (0 if ok else 1, round(abs(float(w.get("long_eur") or 0) - float(w.get("short_eur") or 0)), 1))


def ap_klassen_waage(stand, pc_lebt=None, extra=None):
    """REIN RECHNEND (testbar): {'futures'|'cfd': {long_eur, short_eur, n_long, n_short, delta_eur, passt, grund, leicht,
    plan_ids, firmen{buy, sell}}} aus stand['offen'] (laufend) + stand['geplant'] (Start in ≤ 2 min). extra = {plan_id, richtung}:
    dieser Plan zählt zusätzlich mit genau dieser Richtung (Start-Prüfung „was wäre, wenn er jetzt startet")."""
    out = {k: {"long_eur": 0.0, "short_eur": 0.0, "n_long": 0, "n_short": 0, "plan_ids": [], "firmen": {"buy": [], "sell": []}, "je_groesse": {}}
           for k in ("futures", "cfd")}
    jm = float(stand.get("jetzt_min") or 0)
    ex = str((extra or {}).get("plan_id") or "")
    ohne = ap_waage_ohne_liste(stand)            # Apex zählt in keiner Waage (19.10.2026)

    def dazu(z, r):
        if ap_waage_ohne(z, ohne):
            return
        w = out[ap_klasse(z.get("route"), z.get("firma"))]
        g = _ap_waage_gewicht(z)
        jg = w["je_groesse"].setdefault(z.get("groesse_key") or "unbekannt", {"n_long": 0, "n_short": 0})   # Waage-Deckel je Kontogröße (02.11.2026)
        if r == "buy":
            w["long_eur"] += g
            w["n_long"] += 1
            jg["n_long"] += 1
        else:
            w["short_eur"] += g
            w["n_short"] += 1
            jg["n_short"] += 1
        w["plan_ids"].append(str(z.get("plan_id")))
        fk = z.get("firma_key") or ""
        if fk and fk not in w["firmen"][r]:
            w["firmen"][r].append(fk)

    gesehen = set()
    for z in stand.get("offen") or ():
        pid = str(z.get("plan_id"))
        if pid != ex and ap_waage_zeile_zaehlt(z, jm, laufend=True):
            dazu(z, z["richtung"])
            gesehen.add(pid)
    for z in stand.get("geplant") or ():
        pid = str(z.get("plan_id"))
        if pid in gesehen or pid == ex:
            continue
        if ap_waage_zeile_zaehlt(z, jm, pc_lebt=pc_lebt):
            dazu(z, z["richtung"])
            gesehen.add(pid)
    if ex and (extra or {}).get("richtung") in ("buy", "sell"):
        z = next((x for x in list(stand.get("geplant") or ()) + list(stand.get("offen") or ()) if str(x.get("plan_id")) == ex), None)
        if z is not None and not z.get("gehedgt") and str(z.get("typ") or "") in AP_TYPEN:
            dazu(z, extra["richtung"])
    for k, w in out.items():
        w["long_eur"], w["short_eur"] = round(w["long_eur"], 1), round(w["short_eur"], 1)
        w["delta_eur"] = round(w["long_eur"] - w["short_eur"], 1)
        w["passt"], w["grund"], w["leicht"] = ap_waage_passt(k, w)
    return out


def ap_eh_wird_hedgen(z, eh_an):
    """REIN RECHNEND (testbar): wird eh_tick diesen geplanten Plan vor dem Start auf Echo mit Hedge umstellen? Schalter an, Echo V2
    (mt5v2), CFD-Challenge (EH_TYPEN), kein Tage-Mini. Dann zählt er in der Waage nach dem Start als gehedgt (0)."""
    return bool(eh_an) and str(z.get("route") or "") == "mt5v2" and str(z.get("typ") or "") in EH_TYPEN and not z.get("tage_mini")


def _ap_waage_kandidat(z, klasse, richtung, jm, pc_lebt, schon, ohne=(), eh_an=False):
    """Darf dieser geplante Plan als Gegentrade vorgezogen werden? Nur änderbare Auto-Pläne (keine Hand-Werte, keine Kette,
    nicht fällig, keine Hand-Richtung) der eigenen Kontoarten, später als jetzt + 3 min, heute, PC lebt, kein roter Start-Fehler.
    Firmen ohne Waage (Apex, 19.10.2026) nie — ein 50-€-Konto ist kein Gegengewicht.
    Nie einen Plan, den eh_tick gleich hedgt (30.10.2026, Befund S3 „nur Shorts"): er zählte danach als gehedgt 0, die Waage sah
    wieder „1 Long, kein Short" und zog den nächsten Short vor — zehn Shorts in 30 min. Ein Gegentrade mit Hedge gleicht nichts aus.
    Richtungen und Startzeiten des Planers bleiben unberührt (Finn 30.10.2026: „An der Logik, wie viele Longs und wie viele Shorts,
    soll sich nichts ändern … Der alte Trade-Planer war perfekt"); die Waage verschiebt nur keine solchen Pläne mehr."""
    if not (z.get("aenderbar") and z.get("auto_plan")) or z.get("gehedgt") or z.get("folgetag") or ap_waage_ohne(z, ohne):
        return False
    if ap_eh_wird_hedgen(z, eh_an):
        return False
    if str(z.get("typ") or "") not in AP_TYPEN or z.get("richtung") != richtung or z.get("start_min") is None:
        return False
    m = float(z["start_min"])
    if not (jm + AP_WAAGE_VORZUG_MIN[1] + 1.0 < m < 24 * 60):
        return False
    if ap_klasse(z.get("route"), z.get("firma")) != klasse or str(z.get("plan_id")) in schon:
        return False
    if pc_lebt is not None and str(z.get("user_id")) not in pc_lebt:
        return False
    sf = z.get("start_fehler")
    return not (isinstance(sf, dict) and sf.get("status") == "rot")


def _ap_waage_rs_frei(stand, z, richtung, ziel):
    """Richtungsschutz je ID × Firma (alle Wege und Kontoarten, auch WD/Funded): keine laufende Gegenrichtung und keine, die in
    ± 30 min um die neue Startzeit wirklich startet. Unverändert hart (Finn 17.10.: „ich mich nicht intern gegenhedge")."""
    key = f"{z.get('user_id')}|{z.get('firma_key')}"
    f = (stand.get("id_fest") or {}).get(key)
    if f and f.get("richtung") != richtung and str(f.get("plan_id")) != str(z.get("plan_id")):
        return False
    gegen = "sell" if richtung == "buy" else "buy"
    for g in list(stand.get("geplant") or ()) + list(stand.get("folgetag") or ()):
        if g is z or f"{g.get('user_id')}|{g.get('firma_key')}" != key or g.get("richtung") != gegen or g.get("start_min") is None:
            continue
        if _ap_waage_startet(g) and abs(float(g["start_min"]) - float(ziel)) <= AP_WAAGE_RS_HORIZONT_MIN:
            return False
    return True


def _ap_waage_zielminute(stand, z, richtung, jm, rnd, belegt):
    """Neue Startminute für einen vorgezogenen Gegentrade: jetzt + 2–3 min; dieselbe Firma 1–10 min (Zufall je Zug) nach der
    Gegenrichtung, 1 min zu anderen IDs derselben Firma, derselbe PC ± 3 min frei. → Minute | None (in den nächsten 13 min kein Platz)."""
    uid, fk = str(z.get("user_id")), z.get("firma_key")
    gegen = "sell" if richtung == "buy" else "buy"
    ziel = jm + rnd.uniform(*AP_WAAGE_VORZUG_MIN)
    abstand = rnd.uniform(*AP_WAAGE_GEGEN_FIRMA)       # 1–10 min, einmal je Zug (Finn 19.10.2026)
    for o in stand.get("offen") or ():
        sm = o.get("start_min")
        if o.get("firma_key") == fk and o.get("richtung") == gegen and sm is not None and float(sm) > jm - AP_WAAGE_GEGEN_FIRMA[1]:
            ziel = max(ziel, float(sm) + abstand)
    andere = [g for g in stand.get("geplant") or () if g is not z and g.get("start_min") is not None and _ap_waage_startet(g)]
    for g in andere:
        if g.get("firma_key") == fk and g.get("richtung") == gegen and abs(float(g["start_min"]) - ziel) < AP_WAAGE_GEGEN_FIRMA_MIN:
            ziel = max(ziel, float(g["start_min"]) + abstand)

    def frei(m):
        for o in stand.get("starts_heute") or ():
            if str(o.get("user_id")) == uid and o.get("start") is not None and abs(float(o["start"]) - m) < AP_WAAGE_PC_ABSTAND_MIN:
                return False
        for g in andere:
            d = abs(float(g["start_min"]) - m)
            if str(g.get("user_id")) == uid and d < AP_WAAGE_PC_ABSTAND_MIN:
                return False
            if g.get("firma_key") == fk and str(g.get("user_id")) != uid and d < AP_WAAGE_FIRMA_ABSTAND_MIN:
                return False
        for u, f_, m2 in belegt:
            if (u == uid and abs(m2 - m) < AP_WAAGE_PC_ABSTAND_MIN) or (f_ == fk and u != uid and abs(m2 - m) < AP_WAAGE_FIRMA_ABSTAND_MIN):
                return False
        return True

    m = ziel
    while m <= jm + AP_WAAGE_SPAET_MIN:
        if frei(m):
            return round(m, 2)
        m += 0.75
    return None


def ap_waage_folgt(stand, klasse, richtung, jm, pc_lebt=None, ohne=()):
    """PAARE (Finn 19.10.2026): steht in der Klasse schon ein Gegentrade der leichten Richtung in den nächsten AP_WAAGE_FOLGT_MIN min
    (geplant, startet wirklich, PC lebt, nicht Apex)? → diese Zeile, sonst None. Dann zieht die Waage nichts vor (der Planer hat das Paar
    mit 2–5 min extern bzw. 2–30 min intern gelegt, seit 25.10.2026) und der PC-Tab lässt den ersten des Paares starten. Der Waage-Deckel
    (ap_waage_deckel) gilt trotzdem."""
    for g in stand.get("geplant") or ():
        if g.get("richtung") != richtung or g.get("start_min") is None or g.get("gehedgt") or g.get("folgetag"):
            continue
        if str(g.get("typ") or "") not in AP_TYPEN or ap_klasse(g.get("route"), g.get("firma")) != klasse or ap_waage_ohne(g, ohne):
            continue
        if pc_lebt is not None and str(g.get("user_id")) not in pc_lebt:
            continue
        m = float(g["start_min"])
        if _ap_waage_startet(g) and jm - 0.5 <= m <= jm + (AP_WAAGE_FOLGT_MIN if klasse == "futures" else AP_WAAGE_GEGEN_FIRMA[1]):
            return g
    return None


def ap_waage_nachschub(stand, waage, rnd, pc_lebt=None, dubai_min=0.0, nur_klasse=None, schon=()):
    """REIN RECHNEND (testbar): Je Klasse, die nicht passt: geplante Auto-Pläne der leichten Richtung derselben Klasse auf
    jetzt + 2–3 min vorziehen, bis die Klasse passt (Futures: Anzahl) bzw. ≈ 75 % der Lücke gedeckt sind (CFD), mindestens einer,
    höchstens AP_WAAGE_ZUEGE_MAX. Reihenfolge: bestätigt vor unbestätigt, andere Firma als die schwere Seite vor derselben, früher vor
    später. Richtung bleibt immer (nie drehen). → (aenderungen für _ap_aenderungen_anwenden, info je Klasse)"""
    jm = float(stand.get("jetzt_min") or 0)
    aend, info, belegt, schon = [], [], [], set(str(x) for x in schon or ())
    ohne = ap_waage_ohne_liste(stand)
    for kl in ("futures", "cfd"):
        if nur_klasse and kl != nur_klasse:
            continue
        w = {k: (list(v) if isinstance(v, list) else dict(v) if isinstance(v, dict) else v) for k, v in (waage.get(kl) or {}).items()}
        ok, grund, leicht = ap_waage_passt(kl, w)
        if ok or not leicht:
            continue
        folgt = ap_waage_folgt(stand, kl, leicht, jm, pc_lebt, ohne)
        if folgt is not None and str(folgt.get("plan_id")) not in schon:   # Paar liegt schon (19.10.2026): nichts vorziehen
            info.append({"klasse": kl, "grund": grund, "leicht": leicht, "gezogen": 0, "kandidaten": 0, "passt_danach": False,
                         "folgt": {"plan_id": folgt.get("plan_id"), "user": folgt.get("user"), "firma": folgt.get("firma"), "start_min": folgt.get("start_min")}})
            continue
        schwer = "sell" if leicht == "buy" else "buy"
        schwer_firmen = set((w.get("firmen") or {}).get(schwer) or ())
        luecke = abs(float(w.get("long_eur") or 0) - float(w.get("short_eur") or 0))
        kand = [z for z in stand.get("geplant") or () if _ap_waage_kandidat(z, kl, leicht, jm, pc_lebt, schon, ohne, stand.get("eh_an"))]
        kand.sort(key=lambda z: (0 if z.get("bestaetigt") else 1, 0 if z.get("firma_key") not in schwer_firmen else 1,
                                 float(z["start_min"]), str(z.get("plan_id"))))
        dazu, n = 0.0, 0
        for z in kand:
            if n >= AP_WAAGE_ZUEGE_MAX:
                break
            ziel = _ap_waage_zielminute(stand, z, leicht, jm, rnd, belegt)
            if ziel is None or not _ap_waage_rs_frei(stand, z, leicht, ziel):
                continue
            von = float(z["start_min"])
            seite = "Long" if leicht == "buy" else "Short"
            aend.append({"plan_id": z["plan_id"], "user_id": z["user_id"], "art": "start", "von_richtung": leicht, "nach_richtung": leicht,
                         "von_start_min": von, "nach_start_min": ziel,
                         "grund": (f"[Waage] {AP_KLASSE_TXT.get(kl, kl)}: {grund} — {seite} vorgezogen, {z.get('user')} {z.get('firma')} "
                                   f"{_ap_hhmm_txt(von + dubai_min)} → {_ap_hhmm_txt(ziel + dubai_min)}{' Dubai' if dubai_min else ''}")})
            belegt.append((str(z.get("user_id")), z.get("firma_key"), ziel))
            schon.add(str(z.get("plan_id")))
            g = _ap_waage_gewicht(z)
            w["long_eur" if leicht == "buy" else "short_eur"] = float(w.get("long_eur" if leicht == "buy" else "short_eur") or 0) + g
            w["n_long" if leicht == "buy" else "n_short"] = int(w.get("n_long" if leicht == "buy" else "n_short") or 0) + 1
            dazu += g
            n += 1
            if ap_waage_passt(kl, w)[0] or (kl == "cfd" and dazu >= AP_WAAGE_ANTEIL * luecke):
                break
        info.append({"klasse": kl, "grund": grund, "leicht": leicht, "gezogen": n, "kandidaten": len(kand),
                     "passt_danach": ap_waage_passt(kl, w)[0]})
    return aend, info


_ap_waage = {"sig": None, "voll_at": 0.0, "letzter_lauf": None, "letztes": None, "fehler": ""}


def ap_waage_tick(regeln_param=None):
    """Sofort-Nachschub (Railway, aus _ap_bot_tick jede Minute): ändert sich das laufende Buch (Trade startet/endet), sofort ein voller
    Lauf, sonst alle 5 min. Zieht Gegentrades vor (ap_waage_nachschub) und protokolliert als quelle 'bot' mit „[Waage]"."""
    try:
        offen = sb_select("trade_plans", {"select": "id", "status": "eq.open"}) or []
    except Exception as e:
        _ap_waage["fehler"] = f"offene Trades nicht lesbar ({type(e).__name__})"
        return None
    sig = tuple(sorted(str(r.get("id")) for r in offen))
    if sig == _ap_waage["sig"] and time.time() - _ap_waage["voll_at"] < AP_WAAGE_VOLL_S:
        return None
    reg = (sb_select("auto_plan_regeln", {"select": "*", "id": "eq.1"}) or [None])[0]
    if not reg:
        return None
    stand = _ap_stand_laden(reg)
    pc = _ap_pc_lebt()
    waage = ap_klassen_waage(stand, pc_lebt=pc)
    aend, info = ap_waage_nachschub(stand, waage, random.SystemRandom(), pc_lebt=pc, dubai_min=_ap_dubai_versatz(stand["mitternacht"]))
    umpl, fehler = _ap_aenderungen_anwenden(stand, aend, "bot") if aend else ([], None)
    _ap_waage.update(sig=sig, voll_at=time.time(), letzter_lauf=datetime.now(timezone.utc).isoformat(), fehler=fehler or "",
                     letztes={"waage": {k: {f: v.get(f) for f in ("long_eur", "short_eur", "n_long", "n_short", "passt", "grund")}
                                        for k, v in waage.items()}, "info": info, "gezogen": len(umpl)})
    # JEDE GRUPPE WIEGT FÜR SICH (Finn 30.10.2026: „Emin hat eine eigene Waage zwischen Long und Short … Jede Gruppe wiegt für sich"):
    # dieselbe Waage je Verwalter-Gruppe mit Planer-Zeile, Stand nur aus ihren IDs — HT oben sieht die Gruppen weiter nicht (eigener try)
    try:
        namen, _aus = _ap_namen()
        for gr in (ap_planer_gruppen(nur_aktiv=True) if namen else []):   # ohne Nutzerliste keine Gruppen-Waage (nie gegen HT wiegen)
            st_g = _ap_stand_laden(reg, namen=namen, ausgeblendet=ap_gruppe_ausgeblendet(namen, gr["ids"]), eigene=gr["ids"])
            try:     # ORBIT PRIO 2 (MO1b): wie ap_planen — die Gruppe wiegt mit ihren eigenen Modellen
                _fm_g = next((v for u, v in ap_gruppen_modelle().items() if u in {str(x) for x in (gr.get("ids") or ())}), {})
                st_g["param"] = ap_waage_param_gruppe(st_g.get("param"), (reg.get("regeln") or {}).get("ausgleich"), (reg.get("regeln") or {}).get("firmen"), _fm_g)
            except Exception as e:
                print(f"[waage] ⚠️ Gruppe {str(gr.get('gruppe_id'))[:8]} Orbit Prio 2: {type(e).__name__}: {e}", flush=True)
            w_g = ap_klassen_waage(st_g, pc_lebt=pc)
            a_g, i_g = ap_waage_nachschub(st_g, w_g, random.SystemRandom(), pc_lebt=pc, dubai_min=_ap_dubai_versatz(st_g["mitternacht"]))
            u_g, f_g = _ap_aenderungen_anwenden(st_g, a_g, "bot") if a_g else ([], None)
            umpl = list(umpl) + list(u_g or [])
            _ap_waage.setdefault("gruppen", {})[gr["gruppe_id"]] = {
                "name": gr.get("name"), "fehler": f_g or "", "gezogen": len(u_g or []), "info": i_g,
                "waage": {k: {f: v.get(f) for f in ("long_eur", "short_eur", "n_long", "n_short", "passt", "grund")} for k, v in w_g.items()}}
    except Exception as e:
        _ap_waage["gruppen_fehler"] = f"{type(e).__name__}: {e}"
        print(f"[waage] ⚠️ Gruppen: {_ap_waage['gruppen_fehler']}", flush=True)
    return umpl


def ap_waage_start_lage(stand, plan_id, richtung, pc_lebt=None):
    """REIN RECHNEND (testbar): Start-Prüfung eines Plans → {klasse, vorher, nachher {passt, besser, grund}, gegen {passt, besser}}.
    besser = die Klasse liegt nach dem Start näher an ±0 als vorher (Futures nach Anzahl, CFD nach €)."""
    z = next((x for x in stand.get("geplant") or () if str(x.get("plan_id")) == str(plan_id)), None)
    if z is None:
        return None
    kl = ap_klasse(z.get("route"), z.get("firma"))
    vor = ap_klassen_waage(stand, pc_lebt=pc_lebt, extra={"plan_id": plan_id, "richtung": None})[kl]
    out = {"klasse": kl, "zaehlt": (not z.get("gehedgt")) and str(z.get("typ") or "") in AP_TYPEN,
           "vorher": {f: vor.get(f) for f in ("long_eur", "short_eur", "n_long", "n_short", "passt", "grund")}}
    gegen = "sell" if richtung == "buy" else "buy"
    if z.get("tage_mini"):
        # TAGE-MINI OHNE WAAGE (30.10.2026, Befund S6: FundedNext Phase 1 …9859, 0,01 Lot / 3,6 $ SL, hing seit 07:01 an „CFD-Waage: 1 Short
        # laufen, kein Long — kein Gegen-Trade vorziehbar"): startet wie geplant wie Apex/WD, nur der Richtungsschutz dreht
        g = "Tage sammeln (Mini) zählt nicht in der Waage — startet ohne Waage-Prüfung"
        out.update(zaehlt=False, ohne_waage=True)
        for name, r in (("nachher", richtung), ("gegen", gegen)):
            out[name] = {"richtung": r, "passt": True, "besser": False, "grund": g,
                         **{f: vor.get(f) for f in ("long_eur", "short_eur", "n_long", "n_short")}}
        return out
    if ap_waage_ohne(z, ap_waage_ohne_liste(stand)):
        # APEX OHNE WAAGE (19.10.2026): startet wie geplant, zieht nichts vor, dreht nur der Richtungsschutz — der PC-Tab sieht „passt"
        g = f"{z.get('firma') or 'Firma'} zählt nicht in der Waage (Apex, Finn 19.10.2026) — startet ohne Waage-Prüfung"
        out["ohne_waage"] = True
        for name, r in (("nachher", richtung), ("gegen", gegen)):
            out[name] = {"richtung": r, "passt": True, "besser": False, "grund": g,
                         **{f: vor.get(f) for f in ("long_eur", "short_eur", "n_long", "n_short")}}
        return out
    for name, r in (("nachher", richtung), ("gegen", gegen)):
        w = ap_klassen_waage(stand, pc_lebt=pc_lebt, extra={"plan_id": plan_id, "richtung": r})[kl]
        _pa = stand.get("param") or {}
        # groesse_key setzt _ap_stand_laden an jeder Zeile („unbekannt“, wenn nicht bestimmbar); fehlt das Feld ganz, gilt der Deckel wie vor dem 02.11. über die Klasse
        sperrt, dgrund = ap_waage_deckel(kl, w, r, _pa.get("waage_max_abstand") or 2.0, z.get("groesse_key")) \
            if _pa.get("waage_deckel_an", True) is not False else (False, None)
        out[name] = {"richtung": r, "passt": bool(w["passt"]), "besser": _ap_waage_note(kl, w) < _ap_waage_note(kl, vor), "grund": w["grund"],
                     "deckel_sperrt": bool(sperrt and out["zaehlt"]), "deckel_grund": dgrund if out["zaehlt"] else None,   # WAAGE-DECKEL (23.10.2026)
                     **{f: w.get(f) for f in ("long_eur", "short_eur", "n_long", "n_short")}}
    # PAARE (19.10.2026): der erste eines Paares darf starten, wenn sein Gegentrade (gleiche Klasse) in ≤ AP_WAAGE_FOLGT_MIN (30) min folgt —
    # NIE über den Waage-Deckel (23.10.2026): ein gesperrter Start bleibt gesperrt, „folgt" macht nur die weiche Waage passend
    if not out["nachher"]["passt"] and out["zaehlt"] and not out["nachher"]["deckel_sperrt"]:
        jm = float(stand.get("jetzt_min") or 0)
        folgt = ap_waage_folgt(dict(stand, geplant=[g for g in stand.get("geplant") or () if str(g.get("plan_id")) != str(plan_id)]),
                               kl, gegen, jm, pc_lebt, ap_waage_ohne_liste(stand))
        if folgt is not None:
            out["nachher"] = dict(out["nachher"], passt=True, folgt={"plan_id": folgt.get("plan_id"), "user": folgt.get("user"), "firma": folgt.get("firma"),
                                                                     "start_min": folgt.get("start_min")},
                                  grund=f"Gegentrade folgt: {folgt.get('user')} {folgt.get('firma')} in {max(0.0, float(folgt['start_min']) - jm):.0f} min")
    return out


def _ap_stand_plaene(stand):
    """Geplante Pläne des Stands in der Form für ap_umplanen/ap_eingriff_pruefen (Firma = Schlüssel)."""
    return [{"plan_id": z["plan_id"], "user_id": z["user_id"], "user": z["user"], "firma": z["firma_key"], "firma_name": z["firma"],
             "richtung": z["richtung"],
             "start_min": z["start_min"], "delta_abs": z["delta_abs"], "aenderbar": z["aenderbar"], "fest_durch": z["fest_durch"],
             "einsatz_abs": z.get("einsatz_abs") or 0.0,
             # SZENARIO (08.10.2026): was ap_szenario_trade braucht
             "satz_eur_je_usd": z.get("satz_eur_je_usd"), "usd_pro_pkt": z.get("usd_pro_pkt"), "wert_eur": z.get("wert_eur"),
             "polster_usd": z.get("polster_usd"), "daily_usd": z.get("daily_usd"), "tp_punkte": z.get("tp_punkte"),
             "sl_punkte": z.get("sl_punkte"),
             # RICHTUNG AM START (07.10.2026): für ap_richtung_konflikte
             "route": z.get("route"), "gehedgt": z.get("gehedgt"), "auto_plan": z.get("auto_plan"), "bestaetigt": z.get("bestaetigt"),
             "richtung_konflikt": z.get("richtung_konflikt"), "folgetag": bool(z.get("folgetag")),
             "start_fehler": z.get("start_fehler")}
            for z in list(stand["geplant"]) + list(stand.get("folgetag") or ()) if z.get("start_min") is not None]   # Folgetag: fest


def _ap_min_iso(stand, m):
    return (stand["mitternacht"] + timedelta(minutes=float(m))).astimezone(timezone.utc).isoformat() if m is not None else None


def _ap_umplanungen_heute(stand):
    """Protokoll des Tages aus auto_plan_umplanung → (liste, hinweis). Tabelle fehlt → [] + Hinweis (SQL einspielen)."""
    try:
        rows = sb_select("auto_plan_umplanung", {"select": "*", "um": "gte." + stand["mitternacht"].isoformat(), "order": "um.desc",
                                                 "limit": "200"}) or []
    except Exception as e:
        return [], f"auto_plan_umplanung nicht lesbar ({type(e).__name__}) — sql/2026-10-06_auto_plan_delta.sql einspielen"
    return [{"um": r.get("um"), "plan_id": r.get("plan_id"), "user_id": r.get("user_id"),
             "user": stand["namen"].get(str(r.get("user_id")), str(r.get("user_id"))[:8]), "firma": r.get("firma"),
             "von_richtung": r.get("von_richtung"), "nach_richtung": r.get("nach_richtung"), "von_start": r.get("von_start"),
             "nach_start": r.get("nach_start"), "grund": r.get("grund"), "quelle": r.get("quelle")} for r in rows], None


def _ap_bot_stand(param, jetzt=None):
    """bot{} für GET /admin/auto-plan/delta: Schalter, letzter Lauf (dieser Prozess = Railway), nächster Lauf."""
    jetzt = jetzt or datetime.now(timezone.utc)
    letzter = _ap_bot.get("letzter_lauf")
    naechster = None
    if param.get("aktiv"):
        t = (datetime.fromisoformat(letzter) + timedelta(minutes=param["takt_min"])) if letzter else jetzt + timedelta(minutes=1)
        naechster = max(t, jetzt).isoformat()           # rund um die Uhr (08.10.2026), ohne Arbeit nur die kleine Vorab-Abfrage
    return {"aktiv": bool(param.get("aktiv")), "takt_min": param.get("takt_min"), "zielband_pct": param.get("zielband_pct"),
            "auto_start": bool(param.get("auto_start")), "letzter_lauf": letzter, "naechster_lauf": naechster,
            "letztes": _ap_bot.get("letztes"), "fehler": _ap_bot.get("fehler") or None, "thread": bool(_ap_info.get("started"))}


def _ap_eur_bei(ve, minute):
    """€-Einsatz-Verlauf (ap_verlauf in €) am Zeitpunkt `minute` → {netto_eur, brutto_eur, band_eur} (letzter Punkt ≤ minute)."""
    p = None
    for x in ve["verlauf"]:
        if x["min"] <= minute + 1e-9:
            p = x
    p = p or ve["verlauf"][0]
    return {"netto_eur": round(p["netto_delta"]), "brutto_eur": round(p["brutto_delta"]), "band_eur": round(p["band_delta"])}


def ap_delta_antwort(stand, sicht_uid=None, pc_lebt=None):
    """GET /admin/auto-plan/delta (Vertrag §4) aus dem Stand. Nicht-Admin: Listen nur die eigene ID, Summen über alle.
    pc_lebt (Set der user_ids mit lebendem PC-Tab, None = unbekannt): Pläne anderer IDs zählen im Verlauf und in der Szenario-Kurve
    +60 nicht mit (Phantom, wie im Bot — Master 08.10.2026) und tragen pc_tot an der Zeile."""
    pct = stand["param"]["zielband_pct"]
    ab = max(0.0, stand["jetzt_min"])
    zaehlt = [z for z in stand["geplant"] if pc_lebt is None or str(z.get("user_id")) in pc_lebt]
    v = ap_verlauf(stand["basis_netto"], stand["basis_brutto"],
                   [(z["start_min"], z["delta_eur_pkt"]) for z in zaehlt if z.get("start_min") is not None], pct, ab_min=ab)
    # 07.10.2026 (Finn: EINE Kennzahl = Einsatz €): Netto/Band/Verlauf zusätzlich in € Einsatz; €/Pkt-Felder bleiben zur Info
    ve = ap_verlauf(stand.get("basis_einsatz") or 0.0, stand.get("brutto_einsatz") or 0.0,
                    [(z["start_min"], z["einsatz_eur"]) for z in zaehlt
                     if z.get("start_min") is not None and z.get("einsatz_eur") is not None], pct, ab_min=ab,
                    laufzeit_min=stand["param"].get("laufzeit_min"))
    umpl, h_umpl = _ap_umplanungen_heute(stand)
    offen = [{k: z.get(k) for k in ("plan_id", "user_id", "user", "firma", "richtung", "delta_eur_pkt", "einsatz_eur", "tp_punkte_rest", "sl_punkte_rest",
                                    "stand", "tp_punkte", "sl_punkte", "konto", "ende4", "typ", "route", "menge", "usd_pro_pkt",
                                    "punktwert_quelle", "wert_eur", "satz_eur_je_usd", "gehedgt", "hedge", "hinweis",
                                    "hinweis_code", "hinweis_fix", "konto_id", "ext_fehlt")} for z in stand["offen"]]
    geplant = [{k: z.get(k) for k in ("plan_id", "user_id", "user", "firma", "richtung", "start", "delta_eur_pkt", "einsatz_eur", "fest_durch", "bestaetigt",
                                      "start_txt", "start_min", "aenderbar", "auto_plan", "richtung_fest_durch", "tp_punkte", "sl_punkte",
                                      "konto", "ende4", "typ", "route", "menge", "usd_pro_pkt", "punktwert_quelle", "wert_eur", "gehedgt",
                                      "hinweis", "richtung_konflikt", "hinweis_code", "hinweis_fix", "ext_fehlt",   # genauer Grund + Fix (09.10.2026)
                                      # 08.10.2026: Balance live (Braucht dich/Firmen-Block) und Boden (Balance-Balken) — standen in _ap_stand_laden
                                      # schon an der Zeile, kamen aber ohne diese Liste nie im Frontend an (.1224)
                                      "balance_live", "boden", "boden_min", "boden_art",
                                      # 08.10.2026: liest tplDaten (Braucht dich: Start-Fehler/geclaimt fremder Pläne, Konto-Zuordnung)
                                      "konto_id", "start_fehler", "geclaimt",
                                      "puls_pause",   # 20.10.2026: Braucht dich „kann nicht starten — Puls-Pause" auch für fremde IDs
                                      "lots_deckel", "lots_kt", "lots_mult",   # 02.11.2026: Lots-Deckel, Braucht dich mit OK
                                      "notes", "balance")}
               for z in sorted(stand["geplant"], key=lambda z: (z.get("start_min") or 0, z["plan_id"]))]
    if pc_lebt is not None:
        for g in geplant:
            g["pc_tot"] = str(g.get("user_id")) not in pc_lebt      # zählt nicht mit (Phantom), Bot fasst ihn nicht an
    hinweise = list(stand["hinweise"]) + ([{"grund": h_umpl}] if h_umpl else [])
    # Master 06.10.2026 (Frontend .1084 schon live): band als ZAHL in €/Pkt (± um null, jetzt), Details in band_info; je
    # Verlaufspunkt zusätzlich band (= band_delta); fenster[] aus auto_plan_regeln.zeiten für die Grenzlinien im Chart
    w_summe = sum(float(f[2]) for f in ap_fenster_liste(stand["zeiten"])) or 1.0
    out = {"ok": True, "um": stand["jetzt"].isoformat(), "tag": stand["tag"],
           "band": round(pct / 100.0 * stand["basis_brutto"], 2), "zielband_pct": pct,
           "band_info": {"pct": pct, "eur_pkt": round(pct / 100.0 * stand["basis_brutto"], 2), "gehalten": v["gehalten"],
                         "netto_max_abs": v["netto_max_abs"], "ueber": v["ueber"][:20]},
           "netto_jetzt": round(stand["basis_netto"], 2), "brutto_jetzt": round(stand["basis_brutto"], 2),
           "netto_eur": round(stand.get("basis_einsatz") or 0.0),   # .1552: Tages-Saldo (laufend + heute beendet), wenn lauf_netto_eur da ist
           "lauf_netto_eur": None if stand.get("lauf_einsatz") is None else round(stand["lauf_einsatz"]),
           "beendet_netto_eur": None if stand.get("beendet_einsatz") is None else round(stand["beendet_einsatz"]),
           "beendet_long_eur": stand.get("beendet_long_eur"), "beendet_short_eur": stand.get("beendet_short_eur"),
           "tag_long_eur": stand.get("tag_long_eur"), "tag_short_eur": stand.get("tag_short_eur"),   # .1553: Eröffnungs-Gewicht je Seite
           "long_eur": round(sum(max(z.get("einsatz_eur") or 0, 0) for z in stand["offen"] + stand["geplant"])),
           "short_eur": round(sum(max(-(z.get("einsatz_eur") or 0), 0) for z in stand["offen"] + stand["geplant"])),
           "band_eur": round(pct / 100.0 * (stand.get("brutto_einsatz") or 0.0)),
           "brutto_eur": round(stand.get("brutto_einsatz") or 0.0), "saldo_frei_eur": AP_SALDO_FREI_EUR,   # Saldo-Riegel im PC-Tab (.1545)
           "netto_eur_max_abs": round(ve["netto_max_abs"]), "gross_ab_eur": stand["param"].get("gross_ab_eur"),
           "verlauf_eur": [{"min": x["min"], "netto_eur": round(x["netto_delta"]), "brutto_eur": round(x["brutto_delta"]),
                            "band_eur": round(x["band_delta"])} for x in ve["verlauf"]],
           "offen": offen, "geplant": geplant, "verlauf": [dict(x, band=x["band_delta"], **_ap_eur_bei(ve, x["min"])) for x in v["verlauf"]],
           "umplanungen": umpl,
           "fenster": [{"von": f[0], "bis": f[1], "anteil": round(float(f[2]) / w_summe * 100, 1)}
                       for f in ap_fenster_liste(stand["zeiten"])],
           # 16.10.2026: das Frontend (sfTagesEnde, Neu-Einplanen) liest d.start_bis — fehlte bisher, der Tab nahm 16:30 dt an
           "start_bis": _ap_hhmm_txt(ap_start_bis(stand["zeiten"])),
           "cfd_bis": None if ap_cfd_bis(stand["zeiten"]) is None else _ap_hhmm_txt(ap_cfd_bis(stand["zeiten"])),   # CFD-Ende (sfTagesEnde)
           "bot": _ap_bot_stand(stand["param"], stand["jetzt"]), "hinweise": hinweise,
           "echo_hedge": eh_stand(),   # HT Echo-Hedge B2 (29.10.2026): Schalter neben „Bot an/aus"
           "apex_hedge": ah_stand(),   # Apex-Challenge-WD-Hedge (30.10.2026): Schalter neben „Echo-Hedge"
           "tradeify_final_hedge": tfh_stand()}   # finaler Tradeify mit Gegenhedge (30.10.2026): Schalter neben „Apex-Hedge"
    # SZENARIO (08.10.2026, für Slave 5s Anzeige): Kurve jetzt (laufende) und +60 min (mit den in 60 min startenden), Steigung, schlimmster
    # Fall links/rechts über ±AP_SZENARIO_R; Trades ohne Satz/$ je Pkt zählen 0 und stehen in szenario.ohne
    try:
        lauf_t = [ap_szenario_trade_aus_zeile(z, True) for z in stand["offen"]]
        jm_ = float(stand.get("jetzt_min") or 0)
        folge_z = [z for z in stand.get("folgetag") or () if pc_lebt is None or str(z.get("user_id")) in pc_lebt]   # über 00:00 dt
        plan_t = [ap_szenario_trade_aus_zeile(z, False) for z in zaehlt + folge_z
                  if z.get("start_min") is not None and jm_ <= float(z["start_min"]) <= jm_ + 60]
        l0, l60 = ap_szenario_lage(lauf_t), ap_szenario_lage(lauf_t + plan_t)
        out["delta_eur_pkt"] = l0["delta_eur_pkt"]
        out["szenario"] = {"r_pkt": AP_SZENARIO_R, "jetzt": l0["kurve"], "plus60": l60["kurve"],
                           "schlimmst": {"links": l0["links"], "rechts": l0["rechts"]},   # Vertrag Slave 5 (844d9ef): jetzt
                           "schlimmst_jetzt": {"links": l0["links"], "rechts": l0["rechts"], "min_eur": l0["min_eur"]},
                           "schlimmst_plus60": {"links": l60["links"], "rechts": l60["rechts"], "min_eur": l60["min_eur"]},
                           "ohne": [z["plan_id"] for z in stand["offen"] + stand["geplant"]
                                    if not z.get("satz_eur_je_usd") or not z.get("usd_pro_pkt")]}
    except Exception as e:
        out["szenario"] = {"fehler": f"{type(e).__name__}: {e}"}
    # HEUTE BEENDET (Finn 08.10.2026): heute (Dubai) beendete Trades mit € wie die Hypo-Bilanz — vom Delta-Route-Aufruf in den Stand gelegt
    # (ap_heute_beendet_gemerkt); fehlt der Schlüssel (Bot, Selbsttests), bleibt das Feld weg. Die Sicht filtert unten wie offen[]/geplant[].
    if isinstance(stand.get("heute_beendet"), list):
        out["heute_beendet"], out["heute_ab"] = list(stand["heute_beendet"]), stand.get("heute_ab")
    elif stand.get("heute_beendet_fehler"):
        out["heute_beendet"], out["heute_beendet_fehler"] = None, stand["heute_beendet_fehler"]
    # FREMD-POSITIONEN (08.10.2026): vom Delta-Route-Aufruf in den Stand gelegt (fp_delta_zeilen); Sicht filtert wie die Listen
    if isinstance(stand.get("fremd"), list):
        out["fremd"] = list(stand["fremd"])
    if sicht_uid is not None:
        # eine ID (str) oder eine Gruppe (Menge: Verwalter bzw. Finns ?gruppe=, Admin-Gruppen 08.10.2026) — Summen bleiben über alle IDs
        sicht = str(sicht_uid) if isinstance(sicht_uid, (str, int)) else frozenset(str(u) for u in sicht_uid)
        drin = (lambda u: str(u) == sicht) if isinstance(sicht, str) else (lambda u: str(u) in sicht)
        for f in ("offen", "geplant", "umplanungen", "hinweise", "heute_beendet", "fremd"):
            if isinstance(out.get(f), list):
                out[f] = [x for x in out[f] if drin(x.get("user_id"))]
        out["sicht"] = "eigene" if isinstance(sicht, str) else "gruppe"
    return out


def ap_stand_sicht(stand, sicht):
    """REIN RECHNEND (Admin-Gruppen, Master 08.10.2026 Nachbesserung B: „HT-Gesamtsummen sind HT-Daten"): Stand nur mit den Zeilen der
    Sicht (eine ID oder eine Menge) — offen/geplant/folgetag/hinweise/heute_beendet/fremd gefiltert und die Basis der laufenden Trades
    (Delta €/Pkt und € Einsatz) mit denselben Summen wie _ap_stand_laden aus den gefilterten neu gerechnet. Netto, Band, Long/Short,
    Verlauf und Szenario der Delta-Antwort entstehen danach nur aus dieser Sicht. Für eingeschränkte Logins und Finns Gruppenfilter;
    der Bot und HT ohne Filter rechnen weiter über alle IDs."""
    sicht = str(sicht) if isinstance(sicht, (str, int)) else frozenset(str(u) for u in sicht)
    drin = (lambda z: str((z or {}).get("user_id")) == sicht) if isinstance(sicht, str) else (lambda z: str((z or {}).get("user_id")) in sicht)
    out = dict(stand or {})
    for f in ("offen", "geplant", "folgetag", "hinweise", "heute_beendet", "fremd"):
        if isinstance(out.get(f), list):
            out[f] = [z for z in out[f] if drin(z)]
    offen = out.get("offen") or []
    ds = [z["delta_eur_pkt"] for z in offen if z.get("delta_eur_pkt") is not None]
    ein = [z["einsatz_eur"] for z in offen if z.get("einsatz_eur") is not None]
    for k in ("lauf_einsatz", "lauf_brutto", "beendet_long_eur", "beendet_short_eur", "beendet_einsatz", "tag_brutto_eur", "tag_long_eur", "tag_short_eur"):
        out.pop(k, None)                      # .1552: Tages-Waage aus den gefilterten Zeilen neu
    out.update(basis_netto=round(sum(ds), 3), basis_brutto=round(sum(abs(d) for d in ds), 3),
               basis_einsatz=round(sum(ein), 1), brutto_einsatz=round(sum(abs(e) for e in ein), 1))
    return ap_tages_saldo(out)


AP_LAUF_SUMMEN = ("netto_max_abs", "id_misch", "firma_misch", "misch_fenster", "ids_benutzt", "nur_konten")   # nur_konten: Konto-IDs aller IDs


def ap_lauf_ohne_summen(erg):
    """REIN RECHNEND (Nachbesserung B, 08.10.2026): Lauf-Antwort für eingeschränkte Logins — die Listen (schon auf die Sicht gefiltert)
    bleiben, Summen und Mischungen über alle IDs fallen weg; aus einsatz bleibt nur laufzeit_min (das Einzige, was die Oberfläche
    liest), aus ausgleich nur die gefilterten Listen."""
    out = {k: v for k, v in (erg or {}).items() if k not in AP_LAUF_SUMMEN}
    if isinstance(out.get("einsatz"), dict):
        out["einsatz"] = {k: v for k, v in out["einsatz"].items() if k == "laufzeit_min"}
    if isinstance(out.get("ausgleich"), dict):
        out["ausgleich"] = {k: v for k, v in out["ausgleich"].items() if k in ("offen", "hinweise", "fenster", "auto_start")}
    return out


def _ap_aenderungen_anwenden(stand, aenderungen, quelle, nur_unbestaetigt=False):
    """Schreibt Umplanungen: nur Plan-Zeilen, die noch geplant, ungestartet, Auto-Plan, in der alten Richtung und nicht
    bestätigt-und-fällig sind (Guard in derselben PATCH-Anfrage), danach je Plan eine Zeile in auto_plan_umplanung.
    → (geschrieben [{um, plan_id, …}], fehler | None). Ohne Protokoll-Tabelle wird NICHTS geändert (Vertrag §3: jede Änderung protokolliert).
    nur_unbestaetigt (RICHTUNG AM START, 07.10.2026): Guard verlangt auto_bestaetigt_at IS NULL — Bestätigtes wird nie still gedreht."""
    if not aenderungen:
        return [], None
    try:
        sb_select("auto_plan_umplanung", {"select": "id", "limit": "1"})
    except Exception as e:
        return [], f"auto_plan_umplanung fehlt ({type(e).__name__}) — sql/2026-10-06_auto_plan_delta.sql einspielen, nichts geändert"
    je = {z["plan_id"]: z for z in stand["geplant"]}
    faellig = (datetime.now(timezone.utc) + timedelta(minutes=AP_FAELLIG_MIN)).strftime("%Y-%m-%dT%H:%M:%SZ")
    um = datetime.now(timezone.utc).isoformat()
    geschrieben, protokoll = [], []
    for a in aenderungen:
        z = je.get(a["plan_id"])
        if not z:
            continue
        upd = {}
        if a["nach_richtung"] != a["von_richtung"]:
            upd["richtung"] = a["nach_richtung"]
        von_start = z.get("start")
        nach_start = von_start
        if abs(float(a["nach_start_min"]) - float(a["von_start_min"])) >= 1e-6 and von_start:
            nach_start = (datetime.fromisoformat(str(von_start).replace("Z", "+00:00"))
                          + timedelta(minutes=float(a["nach_start_min"]) - float(a["von_start_min"]))).astimezone(timezone.utc).isoformat()
            upd["start_um"] = nach_start
        if not upd:
            continue
        guard = {"id": f"eq.{a['plan_id']}", "status": "eq.planned", "auto_plan": "eq.true",
                 "start_um_gestartet_at": "is.null", "started_at": "is.null", "orbit_gesendet_at": "is.null",
                 "richtung": f"eq.{a['von_richtung']}"}
        if nur_unbestaetigt:
            guard["auto_bestaetigt_at"] = "is.null"
        elif not a.get("rueckfall"):
            guard["or"] = f"(auto_bestaetigt_at.is.null,start_um.gt.{faellig})"
        # Rückfall (08.10.2026): überfällig und ungeclaimt — start_um_gestartet_at/started_at/orbit_gesendet_at IS NULL bleibt der Schutz
        rows = sb_update("trade_plans", guard, upd)
        if not rows:
            continue                  # inzwischen gestartet/bestätigt/geändert — Guard hat gegriffen, nichts protokolliert
        zeile = {"um": um, "plan_id": a["plan_id"], "user_id": a["user_id"], "firma": z.get("firma"),
                 "von_richtung": a["von_richtung"], "nach_richtung": a["nach_richtung"], "von_start": von_start, "nach_start": nach_start,
                 "grund": a["grund"][:500], "quelle": quelle}
        protokoll.append(zeile)
        geschrieben.append(dict(zeile, user=z.get("user"), art=a.get("art")))
    if protokoll:
        try:
            r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/auto_plan_umplanung", json=protokoll,
                            headers=_sb_headers("return=minimal"), timeout=(5, 20))
            _sb_pruefen(r)
        except Exception as e:
            print(f"[auto-plan] ⚠️ Umplanung-Protokoll: {type(e).__name__}: {e}", flush=True)
            return geschrieben, f"geändert, Protokoll nicht geschrieben ({type(e).__name__})"
    return geschrieben, None


def _ap_rk_flag(plan_id, wert):
    """mt5_baseline.richtung_konflikt am geplanten Plan setzen (dict) oder löschen (None) — atomar über das RPC mt5_baseline_patch
    (merged in der DB, kein anderer Schreiber verliert Felder), Status-Guard 'planned'. → True, wenn eine Zeile geschrieben wurde."""
    r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/rpc/mt5_baseline_patch", headers=_sb_headers(), timeout=(5, 15),
                    json={"p_plan": str(plan_id), "p_patch": {"richtung_konflikt": wert}, "p_status": "planned"})
    _sb_pruefen(r)
    try:
        return r.json() is not None
    except ValueError:
        return False


def ap_richtungsschutz(stand, trocken=False, quelle="bot"):
    """Vorab-Prüfung RICHTUNG AM START (Finn 07.10.2026) — bei jedem Bot-Takt, auch wenn das Band hält. Unbestätigte Auto-Pläne
    (änderbar) werden auf die laufende Richtung gedreht (Guard: auto_bestaetigt_at IS NULL, protokolliert in auto_plan_umplanung,
    Grund „Richtungsschutz: läuft schon short"), Bestätigte und Hand-Pläne bekommen nur das Flag mt5_baseline.richtung_konflikt
    (quelle 'bot') — der Delta-Monitor zeigt es. Ein Bot-Flag ohne Konflikt wird gelöscht; Flags des PC-Tabs (quelle 'start'/'puls')
    fasst der Bot nicht an. Danach steht die neue Richtung auch im Stand (für den Ausgleich im selben Lauf).
    → {gedreht [Umplanungen], markiert [plan_id …], frei [plan_id …], fehler}"""
    offen = [{"user_id": z["user_id"], "firma": z["firma_key"], "richtung": z.get("richtung"), "start_min": z.get("start_min")}
             for z in stand["offen"]]
    erg = ap_richtung_konflikte([x for x in _ap_stand_plaene(stand) if not x["folgetag"]], offen, max(0.0, stand["jetzt_min"]),
                                netto_eur=stand.get("basis_einsatz"))   # Saldo-Riegel (.1501)
    je = {z["plan_id"]: z for z in stand["geplant"]}
    out = {"gedreht": [], "markiert": [], "frei": [], "fehler": None, "konflikte": erg}
    if trocken:
        out["gedreht"] = [{"plan_id": a["plan_id"], "user_id": a["user_id"], "user": (je.get(a["plan_id"]) or {}).get("user"),
                           "firma": (je.get(a["plan_id"]) or {}).get("firma"), "art": "richtung", "von_richtung": a["von_richtung"],
                           "nach_richtung": a["nach_richtung"], "grund": a["grund"]} for a in erg["drehen"]]
        geschrieben = erg["drehen"]
    else:
        out["gedreht"], out["fehler"] = _ap_aenderungen_anwenden(stand, erg["drehen"], quelle, nur_unbestaetigt=True)
        geschrieben = [a for a in erg["drehen"] if any(g["plan_id"] == a["plan_id"] for g in out["gedreht"])]
    for a in geschrieben:          # Stand nachziehen: der Ausgleich im selben Lauf rechnet mit der neuen Richtung
        z = je.get(a["plan_id"])
        if z:
            z["richtung"] = a["nach_richtung"]
            if z.get("delta_eur_pkt") is not None:
                z["delta_eur_pkt"] = abs(z["delta_eur_pkt"]) * (1 if a["nach_richtung"] == "buy" else -1)
    jetzt_iso = stand["jetzt"].isoformat()
    for m in erg["markieren"]:
        alt = (je.get(m["plan_id"]) or {}).get("richtung_konflikt")
        if isinstance(alt, dict) and (alt.get("quelle") not in (None, "bot")
                                      or (alt.get("gegen") == m["gegen"] and alt.get("durch") == m["durch"])):
            continue               # PC-Tab-Zustand (wartet/aufgegeben) oder schon so markiert — nichts schreiben
        wert = {"quelle": "bot", "status": "konflikt", "um": jetzt_iso, "gegen": m["gegen"], "durch": m["durch"], "text": m["text"]}
        if trocken:
            out["markiert"].append(m["plan_id"])
            continue
        try:
            if _ap_rk_flag(m["plan_id"], wert):
                out["markiert"].append(m["plan_id"])
                if je.get(m["plan_id"]):
                    je[m["plan_id"]]["richtung_konflikt"] = wert
        except Exception as e:
            print(f"[auto-plan] ⚠️ Richtungskonflikt-Flag {m['plan_id']}: {type(e).__name__}: {e}", flush=True)
    for pid in erg["frei"]:
        if trocken:
            out["frei"].append(pid)
            continue
        try:
            if _ap_rk_flag(pid, None):
                out["frei"].append(pid)
                if je.get(pid):
                    je[pid]["richtung_konflikt"] = None
        except Exception as e:
            print(f"[auto-plan] ⚠️ Richtungskonflikt-Flag löschen {pid}: {type(e).__name__}: {e}", flush=True)
    if erg["drehen"] or erg["markieren"]:
        print(f"[auto-plan] Richtungsschutz{' trocken' if trocken else ''}: {len(out['gedreht'])} gedreht, "
              f"{len(out['markiert'])} markiert", flush=True)
    return out


def _ap_pc_lebt():
    """Set der user_ids, deren PC-Tab lebt (mt5_live-Herzschlag < PC_STAND_LEBT_S, pc_stand_zusammenfassen wie /admin/pc-stand).
    Nicht lesbar → None (kein Filter, der Bot arbeitet wie bisher)."""
    try:
        rows = sb_select("mt5_live", {"select": "id,pc_name,updated_at,user_id:status->>user_id", "order": "updated_at.desc",
                                      "limit": "400"}) or []
        return {u for u, v in pc_stand_zusammenfassen(rows, datetime.now(timezone.utc)).items() if v.get("lebt")}
    except Exception as e:
        print(f"[auto-plan] ⚠️ PC-Stand nicht lesbar ({type(e).__name__}) — Vorziehen ohne PC-Filter", flush=True)
        return None


def _ap_pc_stand_je():
    """{user_id: {aus, alt_s, pc_name, …}} wie /admin/pc-stand (pc_stand_zusammenfassen). Nicht lesbar → None (kein Riegel, kein Push)."""
    try:
        rows = sb_select("mt5_live", {"select": "id,pc_name,updated_at,user_id:status->>user_id", "order": "updated_at.desc",
                                      "limit": "400"}) or []
        return pc_stand_zusammenfassen(rows, datetime.now(timezone.utc))
    except Exception as e:
        print(f"[pc-aus] ⚠️ PC-Stand nicht lesbar ({type(e).__name__})", flush=True)
        return None


def pc_aus_dauer(alt_s):
    """REIN: Sekunden ohne Herzschlag → „12 min" / „5 h" / „2 T"."""
    alt = max(0, int(alt_s or 0))
    return f"{max(1, round(alt / 60))} min" if alt < 3600 else f"{round(alt / 3600)} h" if alt < 48 * 3600 else f"{round(alt / 86400)} T"


def _ap_pc_aus_text(uid, stand=None):
    """Klartext „PC von Ina ist aus (seit 2 T, pc-xc5c52)" oder '' (PC lebt / unbekannt). stand = _ap_pc_stand_je() oder None."""
    stand = _ap_pc_stand_je() if stand is None else stand
    z = (stand or {}).get(str(uid)) if stand else None
    if not z or not z.get("aus"):
        return ""
    try:
        namen, _aus = _ap_namen()
    except Exception:
        namen = {}
    wer = namen.get(str(uid), "der ID")
    return f"PC von {wer} ist aus (seit {pc_aus_dauer(z.get('alt_s'))}{', ' + z['pc_name'] if z.get('pc_name') else ''})"


_ap_pc_lebt_cache = {"bis": 0.0, "ids": None}
AP_PC_LEBT_CACHE_S = 30


def _ap_pc_lebt_gecacht():
    """_ap_pc_lebt für /admin/auto-plan/delta, 30 s gemerkt — jeder Admin-Tab fragt alle paar Sekunden (Supabase-Last, vgl. .1296);
    der Bot liest frisch. Nicht lesbar (None) wird nicht gemerkt."""
    jetzt = time.time()
    with _kurz_cache_lock:
        if _ap_pc_lebt_cache["ids"] is not None and _ap_pc_lebt_cache["bis"] > jetzt:
            return _ap_pc_lebt_cache["ids"]
    ids = _ap_pc_lebt()
    if ids is not None:
        with _kurz_cache_lock:
            _ap_pc_lebt_cache.update(bis=jetzt + AP_PC_LEBT_CACHE_S, ids=ids)
    return ids


def ap_zuege_je_id(rows):
    """REIN: Ausgleichs-Züge je ID aus dem heutigen Protokoll (auto_plan_umplanung) für den Deckel AP_BOT_ZUEGE_JE_ID_TAG — nur quelle
    'bot', ohne Verteilung (Klumpen) und Rückfall („verpufft"); ein Lauf (Minute) × Firma = ein Zug (eine gedrehte Tranche mit 3
    Plänen zählt einmal). → {user_id: n}"""
    out, keys = {}, set()
    for r in rows or ():
        g = str(r.get("grund") or "")
        if r.get("quelle") != "bot" or not r.get("user_id") or g.startswith("Verteilung:") or "verpufft" in g or g.startswith("[Balance-Wache]"):
            continue                                       # Balance-Wache (22.10.2026) nimmt Pläne heraus — kein Ausgleichs-Zug
        k = (str(r["user_id"]), str(r.get("um") or "")[:16], str(r.get("firma") or ""))
        if k not in keys:
            keys.add(k)
            out[k[0]] = out.get(k[0], 0) + 1
    return out


def _ap_zug_nach_vorn(grund, von_min, nach_min):
    """Protokollzeile eines Bot-Zugs nach VORN? „Gegenrichtung vorziehen" („Ausgleich: … vorgezogen …") und seit 08.10.2026 auch der
    Band-Schritt („…: Tranche X HH:MM → HH:MM im eigenen Fenster …"), wenn er früher gelegt hat (Master, Befund Slave 2: Mikes PC
    tot — ein nach vorn geschobener Plan, den kein Tab claimt, fällt wie beim Vorziehen auf seine alte Zeit zurück). Solche Pläne
    stehen in vorgezogen_heute (Pingpong-Bremse) und alt_start (Rückfall, _ap_verpufft)."""
    g = str(grund or "")
    if g.startswith("Ausgleich:") and "vorgezogen" in g:
        return True
    return (": Tranche " in g and " im eigenen Fenster" in g and von_min is not None and nach_min is not None
            and float(nach_min) < float(von_min))


def _ap_verpufft(stand, alt_start):
    """Heute vorgezogene Pläne (alt_start = {plan_id: (alt_min, neu_min)} aus dem Protokoll), die noch auf der vorgezogenen Zeit stehen,
    seit AP_VORZIEHEN_RUECKFALL_MIN überfällig und ungeclaimt sind → [{plan_id, alt_min}] für den Rückfall in ap_umplanen."""
    out = []
    for z in stand.get("geplant") or ():
        pid = str(z.get("plan_id"))
        if pid not in alt_start or z.get("geclaimt") or z.get("start_min") is None:
            continue
        alt_m, neu_m = alt_start[pid]
        if neu_m is None or abs(float(z["start_min"]) - float(neu_m)) > 1:
            continue                                   # inzwischen anders verschoben — nicht unser Zug
        if float(z["start_min"]) + AP_VORZIEHEN_RUECKFALL_MIN <= float(stand["jetzt_min"]):
            out.append({"plan_id": pid, "alt_min": alt_m})
    return out


def _ap_dubai_versatz(mitternacht):
    """Minuten, die Dubai der deutschen Zeit voraus ist (Sommerzeit 120, Winterzeit 180) — nur für Klartext im Protokoll."""
    try:
        from zoneinfo import ZoneInfo
        return (mitternacht.astimezone(ZoneInfo(AP_TZ_LAUF)).utcoffset() - mitternacht.utcoffset()).total_seconds() / 60.0
    except Exception:
        return 0


def ap_ausgleichen(trocken=False, quelle="bot", jetzt=None, seed=None):
    """Ausgleichs-Bot einmal (Takt, Extra-Lauf 14:00 oder POST /admin/auto-plan/ausgleichen). trocken = nur rechnen.
    Ändert nur geplante, nicht gestartete Auto-Pläne (ap_umplanen) — nie laufende Trades, nie Orders.
    netto_vorher/_nachher = größtes |Netto-Delta| ab jetzt bis Tagesende (€/Pkt), ueber_band_* = Überschreitung nächste 60 min."""
    reg = (sb_select("auto_plan_regeln", {"select": "*", "id": "eq.1"}) or [None])[0]
    if not reg:
        return {"ok": False, "msg": "auto_plan_regeln fehlt"}
    stand = _ap_stand_laden(reg, jetzt)
    param = stand["param"]
    # TAGES-SALDO (.1552): der Bot wiegt den Tag (laufend + heute beendet), nicht nur das laufende Buch — Lesefehler → wie bisher
    try:
        stand["heute_beendet"], stand["heute_ab"] = ap_heute_beendet_gemerkt((reg.get("regeln") or {}).get("firmen") or [], jetzt)
        ap_tages_saldo(stand)
    except Exception as e:
        stand["heute_beendet_fehler"] = f"{type(e).__name__}: {e}"
        print(f"[auto-plan] ⚠️ Tages-Saldo (Bot): {stand['heute_beendet_fehler']}", flush=True)
    # RICHTUNG AM START (07.10.2026): erst der Richtungsschutz der nächsten 60 min — läuft bei jedem Takt, auch wenn das Band hält
    try:
        rs = ap_richtungsschutz(stand, trocken=trocken, quelle="bot")
    except Exception as e:
        rs = {"gedreht": [], "markiert": [], "frei": [], "fehler": f"{type(e).__name__}: {e}"}
        print(f"[auto-plan] ⚠️ Richtungsschutz: {rs['fehler']}", flush=True)
    seed = int(seed) if seed not in (None, "") else random.SystemRandom().randrange(1, 2 ** 31)
    # DÄMPFUNG (08.10.2026): letzte Umplanung je Plan heute (auto_plan_umplanung, bot UND hand) als Minute des Tages → Ruhezeit
    zuletzt, vorgez_h, verteilt_h, alt_start, hinaus_h = {}, set(), set(), {}, set()

    try:
        for r in (_ap_umplanungen_heute(stand)[0] or []):
            um = r.get("um")
            if not um or not r.get("plan_id"):
                continue
            g_ = str(r.get("grund") or "")
            if _ap_zug_nach_vorn(g_, _ap_iso_min(r.get("von_start"), stand["mitternacht"]),
                                 _ap_iso_min(r.get("nach_start"), stand["mitternacht"])):
                vorgez_h.add(str(r["plan_id"]))       # Pingpong-Bremse (08.10.2026)
                if str(r["plan_id"]) not in alt_start:   # Protokoll neu → alt: der erste Treffer ist der jüngste Zug
                    alt_start[str(r["plan_id"])] = (_ap_iso_min(r.get("von_start"), stand["mitternacht"]),
                                                    _ap_iso_min(r.get("nach_start"), stand["mitternacht"]))
            elif g_.startswith("Verteilung:"):
                verteilt_h.add(str(r["plan_id"]))
            elif g_.startswith("Ausgleich:") and "hinausgeschoben" in g_:
                hinaus_h.add(str(r["plan_id"]))       # Pingpong-Bremse der Suche: heute nicht wieder vorziehen
            m = (datetime.fromisoformat(str(um).replace("Z", "+00:00")) - stand["mitternacht"]).total_seconds() / 60.0
            pid = str(r["plan_id"])
            zuletzt[pid] = max(zuletzt.get(pid, -1e9), m)
    except Exception as e:
        print(f"[auto-plan] ⚠️ Dämpfung: Protokoll nicht lesbar ({type(e).__name__}) — ohne Ruhezeit", flush=True)
    zuege_gesperrt = False
    try:
        _rows, _hinw = _ap_umplanungen_heute(stand)    # schluckt Lesefehler selbst und meldet sie als Hinweis
        if _hinw:
            raise RuntimeError(_hinw)
        zuege_h = ap_zuege_je_id(_rows or [])          # Deckel AP_BOT_ZUEGE_JE_ID_TAG (08.10.2026)
    except Exception as e:
        # Fail-safe (Prüfer Slave 2): ohne Protokoll keine gedeckelten Ausgleichs-Züge in diesem Lauf (Verteilung/Rückfall bleiben)
        zuege_h, zuege_gesperrt = {}, True
        print(f"[auto-plan] ⚠️ Deckel je ID: Protokoll nicht lesbar ({type(e).__name__}) — dieser Lauf ohne Ausgleichs-Züge", flush=True)
    erg = ap_umplanen(_ap_stand_plaene(stand), stand["basis_netto"], stand["basis_brutto"], max(0.0, stand["jetzt_min"]),
                      stand["zeiten"], param["zielband_pct"], random.Random(seed), gestartet=stand["starts_heute"],
                      id_fest=stand["id_fest"], einsatz=ap_einsatz_kontext(stand, param), zuletzt=zuletzt,
                      dubai_min=_ap_dubai_versatz(stand["mitternacht"]), vorgezogen_heute=vorgez_h, verteilt_heute=verteilt_h,
                      pc_lebt=_ap_pc_lebt(), verpufft=_ap_verpufft(stand, alt_start), hinaus_heute=hinaus_h, zuege_heute=zuege_h, zuege_gesperrt=zuege_gesperrt,
                      laufend=[{"user_id": z["user_id"], "firma": z.get("firma_key"), "richtung": z.get("richtung"), "start": None}
                               for z in stand["offen"]])   # Gegenhedge über IDs (08.10.2026)
    je = {z["plan_id"]: z for z in stand["geplant"]}
    if trocken:
        umpl = [{"um": None, "plan_id": a["plan_id"], "user_id": a["user_id"], "user": (je.get(a["plan_id"]) or {}).get("user"),
                 "firma": (je.get(a["plan_id"]) or {}).get("firma"), "art": a["art"], "von_richtung": a["von_richtung"],
                 "nach_richtung": a["nach_richtung"], "von_start": _ap_min_iso(stand, a["von_start_min"]),
                 "nach_start": _ap_min_iso(stand, a["nach_start_min"]), "grund": a["grund"]} for a in erg["aenderungen"]]
        fehler = None
    else:
        umpl, fehler = _ap_aenderungen_anwenden(stand, erg["aenderungen"], quelle)
    umpl = list(rs["gedreht"]) + list(umpl)       # Richtungsschutz-Drehungen zuerst (stehen auch im Protokoll)
    fehler = fehler or rs.get("fehler")
    out = {"ok": fehler is None, "trocken": bool(trocken), "tag": stand["tag"], "seed": seed, "umplanungen": umpl,
           "netto_vorher": erg["vorher"]["netto_max_abs"], "netto_nachher": erg["nachher"]["netto_max_abs"],
           "ueber_band_vorher": erg["vorher"]["ueber_band"], "ueber_band_nachher": erg["nachher"]["ueber_band"],
           "gross_folge_vorher": erg["vorher"].get("gross_folge"), "gross_folge_nachher": erg["nachher"].get("gross_folge"),
           "netto_jetzt": round(stand["basis_netto"], 2), "band_pct": param["zielband_pct"], "ausloeser": erg["ausloeser"],
           "daempfung": erg.get("daempfung"),   # DÄMPFUNG (08.10.2026): Hysterese €, Ruhe min, Pläne in Ruhe
           "hinweise": stand["hinweise"],
           "richtungsschutz": {"gedreht": rs["gedreht"], "markiert": rs["markiert"], "frei": rs["frei"], "fehler": rs["fehler"]}}
    if fehler:
        out["msg"] = fehler
    print(f"[auto-plan] Ausgleich {quelle}{' trocken' if trocken else ''}: {len(umpl)} Umplanung(en), "
          f"max |Netto-Einsatz| {out['netto_vorher']} → {out['netto_nachher']} €", flush=True)
    return out


def _ap_bot_hat_arbeit(jetzt=None):
    """Gibt es etwas auszugleichen? Ein laufender Trade oder ein geplanter mit Start ab jetzt − AP_BOT_ARBEIT_VORLAUF_MIN (fällige
    eingeschlossen). Eine Abfrage, limit 1. Nicht lesbar → True (lieber ein Lauf zu viel als einer zu wenig)."""
    jetzt = jetzt or datetime.now(timezone.utc)
    ab = (jetzt - timedelta(minutes=AP_BOT_ARBEIT_VORLAUF_MIN)).isoformat().replace("+00:00", "Z")
    try:
        return bool(sb_select("trade_plans", {"select": "id", "or": f"(status.eq.open,and(status.eq.planned,start_um.gte.{ab}))",
                                              "limit": "1"}))
    except Exception as e:
        print(f"[auto-plan] ⚠️ Bot-Vorab-Abfrage: {type(e).__name__} — Lauf trotzdem", flush=True)
        return True


_ap_kette = {"letzter": 0.0, "letztes": None, "fehler": "", "erledigt": {}}   # Topstep-Kette: Takt + Gründe je Trade 1 (Anzeige/Log)
AP_KETTE_TAKT_S = 60


def ap_kette_t1_fertig(t1):
    """REIN: Ist Trade 1 der Kette GENAU nachgelesen? → (balance_start, balance_end) oder (None, Grund). Finn 08.10.2026: „nachdem Trade 1
    abgeschlossen ist, muss einmal die Balance ganz genau gelesen werden, und dann von der Balance der nächste geplant werden" — nur die
    Puls-Nachlesung in TopstepX zählt (final.quelle puls, plattform tsx), kein Folgetrade-Wert, keine Schätzung."""
    mb = t1.get("mt5_baseline") if isinstance(t1.get("mt5_baseline"), dict) else {}
    tv, fin = mb.get("tv") or {}, mb.get("final") or {}
    b0, b1 = _wd_num(tv.get("balance_start")), _wd_num(fin.get("balance_end"))
    if b0 is None:
        return None, "ohne Start-Balance von Trade 1"
    if b1 is None or fin.get("quelle") != "puls" or fin.get("plattform") != "tsx" or fin.get("balance_quelle") == "folgetrade":
        return None, "wartet auf die genaue Balance-Nachlesung"
    return (b0, b1), None


AP_KETTE_STARTWERT_TOLERANZ = 50.0      # $ Abweichung der ersten echten Lesung vom Startwert, ab der ein Kettenplan neu gerechnet wird
AP_KETTE_SW_FELDER = "id,name,firm,external_id,account_size,starting_balance,topstep_balance,topstep_last_check,meta_api_balance,meta_api_last_check,tv_balance,tv_balance_at"   # Felder für acc_balance_wahl


def ap_kette_startwert_veraltet(plan, konto):
    """REIN RECHNEND (testbar): Ist ein Ketten-Trade-1 aus dem STARTWERT gerechnet (ap_startwert_frisch, Notiz „Startwert") und weicht die
    erste echte Lesung jetzt um mehr als AP_KETTE_STARTWERT_TOLERANZ davon ab? Nur unbestätigte, ungestartete Auto-Pläne (planned, ohne
    auto_bestaetigt_at / start_um_gestartet_at / started_at / orbit_gesendet_at) — bestätigte oder gestartete fasst das nie an.
    Anlass 09.10.2026 (Ina Topstep …3822): Plan 06:39 Dubai mit 150.000 gerechnet, Puls las 06:44 147.093,66 → angefressen, hätte ein
    Reparatur-Tag sein müssen. → (True, grund) | (False, None)"""
    p, a = plan or {}, konto or {}
    k = (p.get("mt5_baseline") or {}).get("kette") or {}
    if (p.get("status") != "planned" or not p.get("auto_plan") or p.get("auto_bestaetigt_at") or p.get("start_um_gestartet_at")
            or p.get("started_at") or p.get("orbit_gesendet_at") or str(k.get("nr")) != "1" or AP_STARTWERT_QUELLE not in str(p.get("notes") or "")):
        return False, None
    soll = _wd_num(k.get("tagesstart_plan"))
    bal, _ccy, quelle, stand = acc_balance_wahl(a, {}, {})
    # nur eine Lesung NACH dem Anlegen zählt (sonst wäre sie schon im Plan) — ohne Zeitstempel kein Eingriff
    if soll is None or bal is None or not stand or str(stand) <= str(p.get("created_at") or ""):
        return False, None
    if abs(float(bal) - soll) <= AP_KETTE_STARTWERT_TOLERANZ:
        return False, None
    de = lambda v, n: f"{v:,.{n}f}".replace(",", "X").replace(".", ",").replace("X", ".")   # noqa: E731 — nur die Zahl, das Satzkomma bleibt
    return True, f"Kettenplan mit Startwert {de(soll, 0)} gerechnet, erste Lesung {de(float(bal), 2)} ({quelle}) — neu planen"


def ap_kette_startwert_neu(jetzt=None):
    """Takt (aus ap_kette_tick): löscht unbestätigte, ungestartete Ketten-Trade-1, die aus dem Startwert gerechnet sind und deren erste
    echte Lesung abweicht (ap_kette_startwert_veraltet) — das Konto hat dann keinen Plan mehr, der Nachplan-Takt rechnet es aus der echten
    Balance neu (z. B. Reparatur-Tag). Löschen nur mit denselben Bedingungen im Filter (Rennen mit Bestätigen/Claim). → [plan_id, …]"""
    try:
        plaene = sb_select("trade_plans", {
            "select": "id,user_id,master_account_id,status,auto_plan,auto_bestaetigt_at,start_um_gestartet_at,started_at,orbit_gesendet_at,"
                      "created_at,notes,mt5_baseline", "route": "eq.tsv2", "status": "eq.planned", "auto_plan": "is.true",
            "auto_bestaetigt_at": "is.null", "start_um_gestartet_at": "is.null", "mt5_baseline->kette->>nr": "eq.1",
            "notes": "ilike.*Startwert*"}) or []
        if not plaene:
            return []
        ids = sorted({str(p["master_account_id"]) for p in plaene if p.get("master_account_id")})
        konten = {str(a["id"]): a for a in (sb_select("accounts", {"select": AP_KETTE_SW_FELDER, "id": "in.(" + ",".join(ids) + ")"}) or [])} if ids else {}
    except Exception as e:
        print(f"[kette] ⚠️ Startwert-Prüfung nicht lesbar ({type(e).__name__}: {e})", flush=True)
        return []
    weg, fenster = [], None
    for p in plaene:
        ja, grund = ap_kette_startwert_veraltet(p, konten.get(str(p.get("master_account_id"))))
        if not ja:
            continue
        # NUR SOLANGE NACHGEPLANT WERDEN KANN (Vorprüfung Terminal 3, 09.10.2026): nach start_bis − Vorlauf plant der Nachplan-Takt heute
        # nicht mehr — dann bliebe das Konto ohne Plan, statt dass Finn den unbestätigten Plan sieht und von Hand korrigiert. Dann nur der
        # Grund am ⛓ von Trade 1 (kette.t2_grund), der Plan bleibt. Regeln nicht lesbar → wie Fenster zu (nie blind löschen).
        if fenster is None:
            try:
                zeiten = ((sb_select("auto_plan_regeln", {"select": "zeiten", "id": "eq.1"}) or [{}])[0]).get("zeiten")
                fenster = ap_nachplan_fenster((jetzt or datetime.now(timezone.utc)).astimezone(_ap_tz(AP_TZ_TAG)), zeiten)
            except Exception:
                fenster = False
        if not fenster:
            _ap_kette_grund(p, f"⚠ {grund.replace(' — neu planen', '')} — heute kein Nachplanen mehr: Plan prüfen/von Hand anpassen")
            continue
        try:
            if sb_delete("trade_plans", {"id": f"eq.{p['id']}", "status": "eq.planned", "auto_bestaetigt_at": "is.null",
                                         "start_um_gestartet_at": "is.null", "started_at": "is.null", "orbit_gesendet_at": "is.null"}):
                weg.append(str(p["id"]))
                print(f"[kette] ↻ {str(p['id'])[:8]} gelöscht: {grund}", flush=True)
        except Exception as e:
            print(f"[kette] ⚠️ {str(p['id'])[:8]} nicht gelöscht ({type(e).__name__}: {e})", flush=True)
    return weg


def ap_kette_tick(jetzt=None, rnd=None):
    """TOPSTEP-KETTE Trade 2 (08.10.2026, s. AP_KETTE_STANDARD): jede Minute aus ap_loop. Sucht heute beendete Ketten-Trade-1 (tsv2,
    review/completed, mt5_baseline.kette.nr 1) ohne Trade 2, rechnet aus der genau nachgelesenen Balance TP2/SL2 und legt Trade 2 an:
    Start frühestens Ende + t2_abstand_min (Zufall) und t2_ab, spätestens t2_bis dt, erste regelkonforme Minute (ap_nachhol_minute:
    Richtungsschutz, Firmen-Abstand, Abstand je ID, Gegenhedge über IDs über die Laufzeit), Richtung frei (die mit dem früheren freien
    Platz, Gleichstand Zufall). Bestätigt, wenn Trade 1 bestätigt war (Finn). Eine kleine Abfrage je Takt, Stand nur bei einem Treffer."""
    jetzt = jetzt or datetime.now(timezone.utc)
    rnd = rnd or random.SystemRandom()
    tz = _ap_tz(AP_TZ_TAG)
    d = jetzt.astimezone(tz)
    mitternacht = datetime(d.year, d.month, d.day, tzinfo=tz)
    abgehakt = ap_kette_abhaken(jetzt)
    startwert_neu = ap_kette_startwert_neu(jetzt)   # Startwert-Pläne mit abweichender erster Lesung neu planen lassen (09.10.2026)
    t1s = [p for p in (sb_select("trade_plans", {
        "select": "id,user_id,master_account_id,master_firm,master_name,master_symbol,richtung,auto_plan,auto_bestaetigt_at,ended_at,"
                  "planned_for,status,konto_typ,mt5_baseline", "route": "eq.tsv2", "status": "in.(review,completed)",
        "ended_at": "gte." + mitternacht.isoformat(), "mt5_baseline->kette->>nr": "eq.1"}) or [])]
    if not t1s:
        return {"neu": [], "abgehakt": abgehakt}
    t2s = sb_select("trade_plans", {"select": "id,vor:mt5_baseline->kette->>vor",
                                    "mt5_baseline->kette->>vor": "in.(" + ",".join(str(p["id"]) for p in t1s) + ")"}) or []
    schon = {str(x.get("vor")) for x in t2s}
    offen_t1 = [p for p in t1s if str(p["id"]) not in schon and not ((p.get("mt5_baseline") or {}).get("kette") or {}).get("von")]   # WS2-Ketten: tt_tick
    if not offen_t1:
        return {"neu": []}
    reg = (sb_select("auto_plan_regeln", {"select": "*", "id": "eq.1"}) or [None])[0]
    if not reg:
        return {"neu": [], "fehler": "auto_plan_regeln fehlt"}
    firmen = (reg.get("regeln") or {}).get("firmen") or []
    param = ap_ausgleich_param(reg.get("regeln"))
    stand_je = {}                  # UNT2 (Prüfung): Trade 2 gegen den Stand des Unternehmens seiner ID (HT-Kette nie gegen Emins Pläne und umgekehrt)
    neu, gruende = [], {}
    sperren = _ap_sperren()        # Muster-Portfolio (16.10.2026): gesperrte Firma je ID → kein Trade 2; Lesefehler → leer (wie bisher)
    for t1 in offen_t1:
        pid = str(t1["id"])
        regel = ap_regel_unternehmen(t1.get("user_id"), firmen, t1.get("master_firm"), streng=False)   # UNT3: Regel des Unternehmens (Kettenfelder bleiben Standard, dd_usd je Unternehmen)
        kette = ap_kette_regel(regel)
        if not kette:
            gruende[pid] = "Firma ohne Kettenregel"
            continue
        if ap_firma_gesperrt({"user_id": t1.get("user_id"), "firm": t1.get("master_firm")}, sperren):
            gruende[pid] = AP_GRUND_GESPERRT
            _ap_kette_grund(t1, AP_GRUND_GESPERRT)
            continue
        bal, grund = ap_kette_t1_fertig(t1)
        if not grund:
            werte, grund = ap_kette_trade2((t1.get("mt5_baseline") or {}).get("kette"), bal[0], bal[1], regel, kette, rnd.random())
        if grund:
            gruende[pid] = grund
            _ap_kette_grund(t1, grund)
            continue
        if ((t1.get("mt5_baseline") or {}).get("kette") or {}).get("tagesende"):
            continue                                  # Tag ist abgeschlossen und wartet auf Finns Haken — kein Trade 2 mehr (30.10.2026)
        _uk = ap_unternehmen_ids(t1.get("user_id"), admin_gruppen_daten())
        if _uk not in stand_je:
            stand_je[_uk] = _ap_stand_fuer_uid(reg, t1.get("user_id"), jetzt)
        stand = stand_je[_uk]
        ende_min = (datetime.fromisoformat(str(t1["ended_at"]).replace("Z", "+00:00")) - stand["mitternacht"]).total_seconds() / 60.0
        abst, streu = kette.get("t2_abstand_min") or [5, 20], kette.get("t2_streuung_min") or [0, 45]
        # frühestens Ende + Abstand, frühestens Fensterbeginn + Streuung (sonst stünden alle Trade 2 genau um 11:00 — Muster)
        ab = max(ende_min + float(abst[0]) + rnd.random() * (float(abst[1]) - float(abst[0])),
                 float(_ap_hhmm(kette["t2_ab"])) + float(streu[0]) + rnd.random() * (float(streu[1]) - float(streu[0])))
        zeiten2 = dict(stand.get("zeiten") or {}, start_bis=kette["t2_bis"])
        laufend = [{"user_id": z["user_id"], "firma": z.get("firma_key"), "richtung": z.get("richtung"), "start": None} for z in stand["offen"]]
        fkey = ap_firma_key(stand.get("firmen") or firmen, t1.get("master_firm"))
        plaene = _ap_stand_plaene(stand)
        beste = None
        richtungen = ["buy", "sell"]
        rnd.shuffle(richtungen)
        for r in richtungen:
            m, f_ = ap_nachhol_minute({"plan_id": "kette-" + pid, "user_id": str(t1["user_id"]), "firma": fkey, "richtung": r}, plaene,
                                      stand["starts_heute"], stand["id_fest"], stand["jetzt_min"], zeiten2, param.get("laufzeit_min"),
                                      laufend, rnd=rnd, ab_min=ab)
            if m is not None and (beste is None or m < beste[0]):
                beste = (m, r)
        if beste is None:
            gruende[pid] = f"kein regelkonformer Start für Trade 2 bis {kette['t2_bis']} dt"
            _ap_kette_grund(t1, gruende[pid])   # sichtbar am Trade 1, der bis t2_bis in Überprüfen wartet (S2 30.10.2026); schreibt nur bei Änderung
            continue
        m, r = beste
        start = stand["mitternacht"] + timedelta(minutes=m)
        k2 = {"nr": 2, "vor": pid, "e1": werte["e1"], "tagesziel": werte["tagesziel"], "verlust_grenze": werte["verlust_grenze"],
              "balance_start_tag": bal[0], "balance_nach_t1": bal[1]}
        _tt = ((t1.get("mt5_baseline") or {}).get("kette") or {}).get("tag_typ")
        if _tt:
            k2["tag_typ"] = _tt                                          # Trade 2 erbt den Tag-Typ von Trade 1 (Anzeige, 09.10.2026)
        if werte.get("mll") is not None:
            k2.update(mll=werte["mll"], daily_usd=werte.get("daily_usd"))   # Abhaken: geblowt nur am MLL (DLL 3.000, 08.10.2026)
        for x in ("angefressen", "abstand_mll", "reparatur", "dll_puffer"):   # Weg B (08.10.2026): Ende am MLL = blown, auch unter DLL + 50
            if werte.get(x) is not None:
                k2[x] = werte[x]
        if werte.get("angefressen") and werte.get("mll") is not None:
            tag_ende = f"MLL {werte['mll']:,.0f} (Blow)"                # angefressen: der MLL beendet den Tag vor dem DLL
        elif werte.get("dll_puffer"):
            tag_ende = f"SL −{werte['verlust_grenze']:,.0f} $ (vor dem Tageslimit −{int(werte['daily_usd']):,} $)"   # 12.10.2026
        elif werte.get("daily_usd"):
            tag_ende = "Tageslimit −" + format(int(werte["daily_usd"]), ",") + " $"
        else:
            tag_ende = "geblowt"
        zeile = {"user_id": t1["user_id"], "master_account_id": t1["master_account_id"], "master_name": t1.get("master_name"),
                 "master_firm": t1.get("master_firm"), "master_contracts": werte["menge"], "master_risk": werte["sl"],
                 "master_tp": werte["tp"], "master_sl": werte["sl"], "richtung": r, "route": "tsv2", "master_symbol": t1.get("master_symbol"),
                 "start_um": start.astimezone(timezone.utc).isoformat(), "status": "planned", "priority": "medium",
                 "planned_for": t1.get("planned_for"), "auto_plan": True,
                 "konto_typ": t1.get("konto_typ") or "challenge",   # TL1b: Kette gibt es nur in der Challenge (Topstep Combine), wie ap_kette_abhaken
                 "auto_bestaetigt_at": jetzt.isoformat() if t1.get("auto_bestaetigt_at") else None,
                 "mt5_baseline": {"kette": k2},
                 "notes": (f"Auto-Planer · {AP_KETTE_TXT} 2/2 · Trade 1 {werte['e1']:+,.0f} $ → TP {werte['tp']:,} / SL {werte['sl']:,} $ "
                           f"(Tag +{werte['tagesziel']:,} $ oder {tag_ende}) · "
                           f"Balance {bal[1]:,.0f} (Nachlesung)").replace(",", ".")}
        if (sb_select("trade_plans", {"select": "id", "mt5_baseline->kette->>vor": f"eq.{pid}"}) or []):
            continue                              # inzwischen angelegt (zweiter Takt) — nie doppelt
        try:
            sb_insert("trade_plans", zeile)
        except requests.exceptions.HTTPError as e:
            # Unique-Index trade_plans_kette_vor_uniq (Prüfer Slave 2: beim Railway-Deploy laufen alter und neuer Container kurz
            # parallel, jeder mit eigenem ap_loop) — der andere war schneller, Trade 2 steht schon
            if getattr(e.response, "status_code", 0) == 409:
                continue
            raise
        _ap_kette_grund(t1, f"Trade 2 angelegt: {r} {werte['menge']} NQ, TP {werte['tp']} / SL {werte['sl']} $, Start "
                            f"{start.astimezone(tz).strftime('%H:%M')} dt")
        neu.append({"vor": pid, "start": start.isoformat(), "richtung": r, "tp": werte["tp"], "sl": werte["sl"], "menge": werte["menge"]})
        print(f"[auto-plan] Topstep-Kette: Trade 2 zu {pid[:8]} — E1 {werte['e1']:+.0f} $ → TP {werte['tp']} / SL {werte['sl']} $, "
              f"{r} {werte['menge']} NQ, Start {start.astimezone(tz).strftime('%H:%M')} dt", flush=True)
    _ap_kette["erledigt"] = gruende
    return {"neu": neu, "gruende": gruende, "abgehakt": abgehakt}


def ap_kette_letzter_trade(k, bal, regel, kette):
    """REIN RECHNEND (testbar): War das der letzte Trade des Tages dieses Kontos? (Finn 30.10.2026 13:41: „Nach dem ersten Trade nicht,
    weil ja beide Trades am Tag durchlaufen müssen, aber nach dem zweiten dann, dass ich das Endresultat vom Tag sehe und das auch noch
    abhaken muss.") Kette 2/2 und Reparatur-Tag immer; ein 1/2 nur, wenn ap_kette_trade2 keinen Trade 2 mehr gibt (geblowt, Tagesziel,
    Tageslimit …) — dieselbe Rechnung, die sonst Trade 2 anlegt. Ohne Kettenregel bleibt 1/2 automatisch wie bisher."""
    k = k or {}
    if int(k.get("nr") or 0) == 2 or k.get("reparatur") or k.get("ein_trade"):
        return True
    if not regel or not kette:
        return False
    _w, grund = ap_kette_trade2(k, bal[0], bal[1], regel, kette, 0.5)
    return bool(grund)


def ap_kette_tagesende(k, bal, mpl, e_tag, blown, jetzt_iso):
    """REIN RECHNEND (testbar): mt5_baseline.kette.tagesende — das Tagesergebnis, das die Radar-Karte zeigt (/admin/live-trades kette_tag).
    Trade 1 aus kette.e1 (genaue Lesung beim Anlegen von Trade 2), sonst Tag − Trade 2."""
    zwei = int((k or {}).get("nr") or 0) == 2
    e1 = _wd_num((k or {}).get("e1"))
    t1 = (e1 if e1 is not None else round(float(e_tag) - float(mpl), 2)) if zwei else float(mpl)
    return {"tag_pl": round(float(e_tag), 2), "t1_pl": t1, "t2_pl": float(mpl) if zwei else None, "trades": 2 if zwei else 1,
            "balance": float(bal[1]), "blown": bool(blown), "at": jetzt_iso}


def ap_kette_lesen_bis(k, ended_at, kette, tz, fenster_tz=None):
    """REIN RECHNEND (testbar): Bis wann darf nach Trade 1 noch ein Trade 2 kommen? → ISO (UTC) oder None.
    Topstep-Tag (Finn 02.11.2026 ~19:15 Dubai: „ich will nur einmal abhaken"): solange ein Trade 2 möglich ist, ist Trade 1 keine Abhak-Zeile — der
    Radar hält ihn in „Wartet", Puls liest nach den 8 Versuchen weiter bis zu diesem Zeitpunkt (Ende des Fensters t2_bis am Handelstag des Endes, wie
    _ap_kette_t1_stand). t2_bis gilt wie beim Anlegen von Trade 2 (ap_kette_tick → ap_start_bis) in zeiten.fenster_tz, falls gesetzt, sonst in tz.
    Reparatur-Tag oder ein_trade: kein Trade 2 → None. Ohne Kettenregel → None (dann gilt der alte Weg)."""
    k = k or {}
    if int(k.get("nr") or 0) != 1 or k.get("reparatur") or k.get("ein_trade") or not kette or not kette.get("t2_bis"):
        return None
    ende = _ap_ts(ended_at)
    if not ende:
        return None
    tag = ende.astimezone(tz).date()
    m = _ap_hhmm(kette["t2_bis"])
    bis = datetime(tag.year, tag.month, tag.day, m // 60, m % 60, tzinfo=_ap_tz(fenster_tz) if fenster_tz else tz)
    return bis.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


def _ap_kette_t1_stand(p, kette, tz, jetzt, sperren):
    """Trade 1, nach dem rechnerisch ein Trade 2 kommt (S2 30.10.2026): → "weiter" (Trade 2 steht, abhaken wie immer), "warten" (noch nicht angelegt, bleibt
    in Überprüfen, der Tick kann ihn auch von dort anlegen) oder "letzter" (Firma gesperrt oder Fenster bis t2_bis vorbei: es kommt keiner mehr). Vorher
    war Trade 1 schon erledigt, wenn der Tick scheiterte, und der Tag stand ohne Ergebnis da. Lesefehler → "weiter", die Kette darf nicht stehen bleiben."""
    try:
        if sb_select("trade_plans", {"select": "id", "mt5_baseline->kette->>vor": f"eq.{p['id']}", "limit": "1"}):
            return "weiter"
    except Exception as e:
        print(f"[auto-plan] ⚠️ Topstep-Kette Trade 2 lesen: {type(e).__name__}: {e}", flush=True)
        return "weiter"
    if ap_firma_gesperrt({"user_id": p.get("user_id"), "firm": p.get("master_firm")}, sperren):
        return "letzter"
    d = jetzt.astimezone(tz)
    ende = _ap_ts(p.get("ended_at"))
    if ende and ende.astimezone(tz).date() != d.date():
        return "letzter"
    return "letzter" if d.hour * 60 + d.minute >= float(_ap_hhmm(kette["t2_bis"])) else "warten"


def ap_kette_abhaken(jetzt=None):
    """AUTOMATISCH ABHAKEN (Finn 08.10.2026: „die Trades bei Topstep werden automatisch abgehakt — läuft durch, wird in 1–35 min per
    Zufall überprüft, und sobald überprüft, direkt für den zweiten Trade freigeschaltet, sodass ich sie im Radar nicht mehr abhaken
    muss"): Ketten-Trades (tsv2, mt5_baseline.kette nr 1/2) in Überprüfen, deren Balance Puls GENAU nachgelesen hat (ap_kette_t1_fertig),
    gehen auf Erledigt — wie „Erledigt" im Radar (_wd_erledigt_upd): master_pl = Balance danach − davor ($), pl_quelle 'tv',
    completed_at, ended_at falls leer; Blow (Tagesverlust ab Tagesstart ≥ DD − 50 $) setzt blown am Plan (das Konto archiviert Finn wie bisher im
    Radar). Optimistische Sperre über updated_at. → [plan_id …]
    Seit 30.10.2026 (Finn 13:41) nur noch Trades, nach denen am Tag noch einer kommt: der letzte Trade (ap_kette_letzter_trade) bekommt
    P&L, blown und kette.tagesende, bleibt aber in Überprüfen, bis Finn das Tagesergebnis im Radar abhakt."""
    jetzt = jetzt or datetime.now(timezone.utc)
    rows = sb_select("trade_plans", {"select": "id,route,status,user_id,master_account_id,master_firm,master_pl,mt5_baseline,updated_at,"
                                               "ended_at,completed_at,konto_typ", "route": "eq.tsv2", "status": "eq.review",
                                     "mt5_baseline->kette->>nr": "in.(1,2)"}) or []
    fertig = []
    firmen = sperren = regeln = None
    for p in rows:
        if ((p.get("mt5_baseline") or {}).get("kette") or {}).get("tagesende"):
            continue                                  # wartet schon auf Finns Haken — nicht jede Minute neu schreiben
        if ((p.get("mt5_baseline") or {}).get("kette") or {}).get("von"):
            continue                                  # WS2-Kette (09.11.2026): Abhaken und Tagesende macht tt_tick
        bal, grund = ap_kette_t1_fertig(p)
        if grund:
            if regeln is None:
                regeln = _ap_kette_regeln_laden()
            _ap_kette_lesen_bis_schreiben(p, regeln, jetzt)   # Topstep-Tag: ungelesener Trade 1 → Fensterende für Radar und Puls
            continue
        jetzt_iso = jetzt.isoformat().replace("+00:00", "Z")
        mpl = round(float(bal[1]) - float(bal[0]), 2)
        k = (p.get("mt5_baseline") or {}).get("kette") or {}
        # Prüfer Slave 2 zu ed079ca: dieselbe Plausibilitätsgrenze wie ap_kette_trade2 — passen Start- und End-Balance nicht zusammen
        # (relativ gegen absolut, z. B. Express 0-basiert), wäre P&L −148.000 $ und „geblowt" ohne dass jemand hinschaut. Gemessen am
        # TAG (Trade 2: ab balance_start_tag): oberhalb max(SL/TP Trade 1, Tagesziel) + 1.500 bzw. unterhalb −(Verlustgrenze + 1.500)
        # bleibt der Trade in Überprüfen, Grund an Trade 1 bzw. am Plan selbst
        tag0_p = _wd_num(k.get("balance_start_tag")) or float(bal[0])
        e_tag = float(bal[1]) - tag0_p
        oben = max(float(AP_KETTE_STANDARD["t1_sl"][1]), float(AP_KETTE_STANDARD["t1_tp"][1]),
                   float(k.get("tagesziel") or AP_KETTE_STANDARD["tagesziel_usd"])) + 1500
        unten = -(float(k.get("verlust_grenze") or (AP_KETTE_DD_STANDARD + AP_KETTE_STANDARD["blow_puffer_usd"])) + 1500)
        vg = float(k.get("verlust_grenze") or 4700)          # eigener P&L von Trade 2 reicht bis SL2 = Verlustgrenze + E1 bzw. TP2
        # Weg B (08.10.2026): angefressen ist die Verlustgrenze klein (Abstand MLL + 200, z. B. 250), SL2 = Verlustgrenze + E1 kann aber
        # bis Verlustgrenze + TP1 (2.650) reichen — der eigene P&L von Trade 2 darf so tief, ohne „unplausibel" hängen zu bleiben.
        # Gesunde Konten (Verlustgrenze 3.200 ≥ 2.650) behalten genau die alte Grenze
        vg_t2 = max(vg, float(AP_KETTE_STANDARD["t1_tp"][1]))
        _kb = p.get("mt5_baseline") or {}
        _sp = lt_balance_sprung(p.get("route"), _kb.get("tv") or {}, _kb.get("final") or {})
        if _sp:
            # Balance-Sprung (08.10.2026): Balance-Differenz mehr als 100 $ UNTER dem Tages-P&L (Auszahlung o. Ä.) → nicht automatisch abhaken
            _ap_kette_grund(p, f"Balance-Sprung: Balance {_sp['balance']:+,.0f} $ · Tages-P&L {_sp['tages']:+,.0f} $ · Differenz "
                            f"{_sp['differenz']:+,.0f} $ (Auszahlung?) — von Hand abhaken".replace(",", "."))
            continue
        if not (unten <= e_tag <= oben) or not (unten - vg_t2 <= mpl <= oben + vg):
            _ap_kette_grund(p, f"Ergebnis unplausibel ({mpl:+,.0f} $, Tag {e_tag:+,.0f} $, Balance-Basis prüfen) — von Hand abhaken"
                            .replace(",", "."))
            continue
        upd, fehler = _wd_erledigt_upd(p, mpl, None, jetzt_iso, _cme_handelstag())
        if fehler:
            continue
        upd["pl_quelle"] = "tv"
        _mll_u = ((ap_kette_mll_urteil(k, _kb.get("tv")) if "ap_kette_mll_urteil" in globals() else float(k["mll"]))   # TL1: neueste TopstepX-Lesung vor dem Plan-MLL
                  if _wd_num(k.get("mll")) is not None else None)                                                     # get: ältere Selftest-Lader ohne TL1
        if _mll_u is not None:
            # DLL 3.000 (08.10.2026): ein Tag am Daily Loss Limit ist Tageslimit (soft, Konto lebt) — geblowt nur am MLL. Sichere Variante
            # (Prüfung Slave 2 / Master): Ende ≤ MLL (ohne Toleranz) UND Tagesverlust über DLL + 50 — ein reiner DLL-Tag ist nie geblowt.
            # Weg B (Finn 08.10.2026 ~22:15 Dubai): begann der Tag angefressen (Abstand MLL < DLL, Reparatur-Tag oder ab 150.000 mit
            # gelocktem MLL), endet er am MLL, BEVOR das DLL greift — Tagesverlust ≤ Abstand + 200 < DLL + 50. Dann zählt nur Ende am MLL,
            # mit Toleranz: Ende ≤ MLL + 50 (Master 08.10.2026, Nachbesserung zu cc7a857 — das MLL ist dort die einzige Verlustgrenze,
            # Gebühren/Schlupf bzw. Topstep schließt knapp darüber). Gesunde Tage (Abstand ≥ DLL): Ende ≤ MLL UND Tagesverlust > DLL + 50
            daily_k = float(k.get("daily_usd") or 0)
            if ap_kette_angefressen(k):
                if float(bal[1]) <= _mll_u + AP_KETTE_MLL_TOLERANZ:
                    upd["blown"] = True
            elif float(bal[1]) <= _mll_u and (not daily_k or e_tag < -(daily_k + 50)):
                upd["blown"] = True
        else:
            dd = AP_KETTE_DD_STANDARD
            if k.get("verlust_grenze"):
                dd = float(k["verlust_grenze"]) - float(AP_KETTE_STANDARD["blow_puffer_usd"])
            if e_tag <= -(dd - 50):                   # Trade 2: der TAG zählt (Tagesstart), nicht sein eigener P&L
                upd["blown"] = True
        if not p.get("konto_typ"):
            upd["konto_typ"] = "challenge"            # Kette gibt es nur in der Challenge (Topstep Combine)
        filt = {"id": f"eq.{p['id']}", "status": "eq.review"}
        if p.get("updated_at"):
            filt["updated_at"] = f"eq.{p['updated_at']}"
        if firmen is None:
            if regeln is None:
                regeln = _ap_kette_regeln_laden()     # Lesefehler → {}: 1/2 läuft weiter automatisch, die Kette darf nicht stehen bleiben
            firmen = regeln.get("firmen") or []
        regel = ap_regel_unternehmen(p.get("user_id"), firmen, p.get("master_firm"), streng=False)   # UNT3
        kette_r = ap_kette_regel(regel) if regel else None
        letzter = bool(upd.get("blown")) or ap_kette_letzter_trade(k, bal, regel, kette_r)
        if not letzter and kette_r:
            if sperren is None:
                sperren = _ap_sperren()
            t1_stand = _ap_kette_t1_stand(p, kette_r, _ap_tz(AP_TZ_TAG), jetzt, sperren)
            if t1_stand == "warten":
                if p.get("master_pl") is None:        # P&L schon eintragen: gelesener Trade sperrt den Richtungs-Riegel nicht (prophos_plan_gelesen)
                    try:
                        sb_update("trade_plans", filt, {x: upd[x] for x in ("master_pl", "pl_quelle", "konto_typ", "ended_at") if x in upd})
                    except Exception as e:
                        print(f"[auto-plan] ⚠️ Topstep-Kette P&L {str(p['id'])[:8]}: {type(e).__name__}: {e}", flush=True)
                # Topstep-Tag: erst NACH dem Schreiben mit updated_at-Sperre (das RPC setzt updated_at neu), Radar zeigt „Trade 2 folgt"
                _ap_kette_lesen_bis_schreiben(p, regeln or {}, jetzt)
                continue
            letzter = t1_stand == "letzter"
        if letzter:
            # Letzter Trade des Tages (Finn 30.10.2026): bleibt in Überprüfen. master_pl + final puls lassen den Richtungs-Riegel frei
            # (prophos_plan_gelesen), blown wirkt sofort im Planer; tagesende zuletzt, damit ein gescheiterter Schritt im nächsten Takt nachläuft
            halb = {x: upd[x] for x in ("master_pl", "pl_quelle", "blown", "konto_typ", "ended_at") if x in upd}   # ended_at: sonst bleibt der Richtungs-Riegel zu (prophos_plan_gelesen)
            try:
                if sb_update("trade_plans", filt, halb):
                    r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/rpc/mt5_baseline_patch_in", headers=_sb_headers(), timeout=(5, 15),
                                    json={"p_plan": str(p["id"]), "p_key": "kette", "p_status": None,
                                          "p_patch": {"tagesende": ap_kette_tagesende(k, bal, mpl, e_tag, upd.get("blown"), jetzt_iso)}})
                    _sb_pruefen(r)
                    print(f"[auto-plan] Topstep-Kette: {str(p['id'])[:8]} letzter Trade des Tages — P&L {mpl:+.2f} $, Tag {e_tag:+.2f} $"
                          f"{' (geblowt)' if upd.get('blown') else ''}, wartet auf Abhaken", flush=True)
            except Exception as e:
                print(f"[auto-plan] ⚠️ Topstep-Kette Tagesende {str(p['id'])[:8]}: {type(e).__name__}: {e}", flush=True)
            continue
        try:
            if sb_update("trade_plans", filt, upd):
                fertig.append(str(p["id"]))
                print(f"[auto-plan] Topstep-Kette: {str(p['id'])[:8]} automatisch abgehakt — P&L {mpl:+.2f} $"
                      f"{' (geblowt)' if upd.get('blown') else ''}", flush=True)
        except Exception as e:
            print(f"[auto-plan] ⚠️ Topstep-Kette abhaken {str(p['id'])[:8]}: {type(e).__name__}: {e}", flush=True)
    return fertig


def _ap_kette_regeln_laden():
    """auto_plan_regeln.regeln (firmen, zeiten) für ap_kette_abhaken; Lesefehler → {} (geloggt)."""
    try:
        return (sb_select("auto_plan_regeln", {"select": "regeln", "id": "eq.1"}) or [{}])[0].get("regeln") or {}
    except Exception as e:
        print(f"[auto-plan] ⚠️ Topstep-Kette Regeln: {type(e).__name__}: {e}", flush=True)
        return {}


def _ap_kette_lesen_bis_schreiben(p, regeln, jetzt):
    """Topstep-Tag (Finn 02.11.2026 ~19:15 Dubai: „ich will nur einmal abhaken"): Fensterende für Trade 2 (ap_kette_lesen_bis) einmal an Trade 1 schreiben
    (kette.lesen_bis) — Radar (Wartet statt Abhak-Zeile) und Puls (liest über die 8 Versuche hinaus) lesen es. lesen_bis_at merkt, dass gerechnet wurde
    (auch bei None), damit nicht jede Minute geschrieben wird. Ohne Regel/Ende nichts (nächster Takt). Nur ungelesene bzw. wartende Trade 1 — das RPC
    setzt updated_at neu, darum nie vor einem Schreiben mit updated_at-Sperre im selben Takt (Gegencheck S19). Fehler nur loggen."""
    k0 = (p.get("mt5_baseline") or {}).get("kette") or {}
    if int(k0.get("nr") or 0) != 1 or k0.get("lesen_bis_at") or k0.get("tagesende"):
        return
    regel = ap_regel_unternehmen(p.get("user_id"), (regeln or {}).get("firmen") or [], p.get("master_firm"), streng=False) if (regeln or {}).get("firmen") else None   # UNT3
    kr = ap_kette_regel(regel) if regel else None
    ende = p.get("ended_at") or ((p.get("mt5_baseline") or {}).get("final") or {}).get("at")
    if not kr or not ende:
        return
    try:
        r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/rpc/mt5_baseline_patch_in", headers=_sb_headers(), timeout=(5, 15),
                        json={"p_plan": str(p["id"]), "p_key": "kette", "p_status": None,
                              "p_patch": {"lesen_bis": ap_kette_lesen_bis(k0, ende, kr, _ap_tz(AP_TZ_TAG), ((regeln or {}).get("zeiten") or {}).get("fenster_tz")),
                                          "lesen_bis_at": jetzt.isoformat().replace("+00:00", "Z")}})
        _sb_pruefen(r)
    except Exception as e:
        print(f"[auto-plan] ⚠️ Topstep-Kette lesen_bis {str(p['id'])[:8]}: {type(e).__name__}: {e}", flush=True)


def _ap_kette_grund(t1, grund):
    """Wartegrund bzw. Ergebnis der Kette an Trade 1 sichtbar machen (Prüfer Slave 2: „fehlt tv.balance_start, wartet T2 still für
    immer — bitte zeigen"): mt5_baseline.kette.t2_grund, nur wenn er sich ändert (sonst jede Minute ein Schreiben). Atomar über das RPC
    mt5_baseline_patch_in (merged eine Ebene tief). Fehler nur loggen."""
    k = ((t1.get("mt5_baseline") or {}).get("kette") or {})
    if k.get("t2_grund") == grund:
        return
    try:
        r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/rpc/mt5_baseline_patch_in", headers=_sb_headers(), timeout=(5, 15),
                        json={"p_plan": str(t1["id"]), "p_key": "kette",
                              "p_patch": {"t2_grund": grund, "t2_grund_at": datetime.now(timezone.utc).isoformat()}, "p_status": None})
        _sb_pruefen(r)
    except Exception as e:
        print(f"[auto-plan] ⚠️ Topstep-Kette Grund: {type(e).__name__}: {e}", flush=True)


def _ap_kette_takt():
    """aus ap_loop: höchstens alle AP_KETTE_TAKT_S ap_kette_tick (Fehler nur loggen)."""
    if time.time() - _ap_kette["letzter"] < AP_KETTE_TAKT_S:
        return
    _ap_kette["letzter"] = time.time()
    try:
        _ap_kette["letztes"] = ap_kette_tick()
        _ap_kette["fehler"] = ""
    except Exception as e:
        _ap_kette["fehler"] = f"{type(e).__name__}: {e}"
        print(f"[auto-plan] ⚠️ Topstep-Kette: {e}", flush=True)


