def _tt_spanne(v, lo, hi):
    """[a, b] mit lo ≤ a ≤ b ≤ hi → [float, float] | None."""
    if not isinstance(v, (list, tuple)) or len(v) != 2 or any(isinstance(x, bool) or not isinstance(x, (int, float)) or x != x for x in v):
        return None
    a, b = float(v[0]), float(v[1])
    return [a, b] if lo <= a <= b <= hi else None


def _tt_anteile(v):
    """[p1, p2, p3, p4] je 0–100, Summe 100 (±0,5) → [float × 4] | None."""
    if not isinstance(v, (list, tuple)) or len(v) != 4 or any(isinstance(x, bool) or not isinstance(x, (int, float)) or x != x or x < 0 or x > 100 for x in v):
        return None
    return [float(x) for x in v] if abs(sum(float(x) for x in v) - 100.0) <= 0.5 else None


def tt_param(regeln):
    """REIN RECHNEND (testbar): regeln.tagesteilung → wirksame Parameter. Jedes Feld einzeln geprüft, Ungültiges fällt auf TT_STANDARD."""
    roh = (regeln or {}).get("tagesteilung") if isinstance(regeln, dict) else None
    roh = roh if isinstance(roh, dict) else {}
    out = json.loads(json.dumps(TT_STANDARD))
    out["an"] = roh.get("an") is True
    for k in ("schluss_topstep", "schluss_news_sperre"):
        if isinstance(roh.get(k), bool):
            out[k] = roh[k]
    if roh.get("lots_bezug") in TT_LOTS_BEZUG:
        out["lots_bezug"] = roh["lots_bezug"]
    if isinstance(roh.get("gruppen"), list):           # Unternehmen (id_gruppen.id) zusätzlich zu HT — leer = nur HT (Master 09.11.2026, mit WS2b abgestimmt)
        out["gruppen"] = [str(x) for x in roh["gruppen"] if isinstance(x, str) and re.fullmatch(r"[0-9a-fA-F-]{36}", x)]
    if isinstance(roh.get("firmen"), list):
        out["firmen"] = [str(x) for x in roh["firmen"] if isinstance(x, str) and x]
    a = _tt_anteile(roh.get("anteile"))
    if a:
        out["anteile"] = a
    for k, (lo, hi) in TT_SPANNEN.items():
        v = roh.get(k)
        if k in ("neben_tp_teiler", "neben_lots_streu") and not isinstance(v, bool) and isinstance(v, (int, float)):
            v = [v, v]                               # WS3c/WS3d: ein einzelner Wert gilt als fest
        s = _tt_spanne(v, lo, hi)
        if s:
            out[k] = s
    for k, (lo, hi) in TT_ZAHLEN.items():
        v = roh.get(k)
        if not isinstance(v, bool) and isinstance(v, (int, float)) and v == v and lo <= float(v) <= hi:
            out[k] = float(v)
    if isinstance(roh.get("nur_konten"), list):
        out["nur_konten"] = [str(x) for x in roh["nur_konten"] if isinstance(x, str) and re.fullmatch(r"[0-9a-fA-F-]{36}", x)]
    if isinstance(roh.get("test_ids"), list):           # TT1 (11.11.2026): Test-IDs
        out["test_ids"] = [str(x) for x in roh["test_ids"] if isinstance(x, str) and re.fullmatch(r"[0-9a-fA-F-]{36}", x)]
    tn = roh.get("test_n")
    out["test_n"] = int(tn) if (not isinstance(tn, bool) and isinstance(tn, (int, float)) and float(tn).is_integer() and 1 <= tn <= 4) else None
    return out


def tt_firmen_auswahl(firmen, param=None):
    """REIN RECHNEND: [{key, name, art: futures|topstep|cfd, an}] — alle Challenge-Firmen der Regel außer Apex (WS2b: Häkchen je Firma)."""
    out, an = [], set((param or {}).get("firmen") or ())
    for f in firmen or ():
        if not isinstance(f, dict):
            continue
        key = str((f.get("namen") or [""])[0] or "")
        if not key or key.startswith("apex"):
            continue
        route = str(f.get("route") or "mt5v2")
        art = "topstep" if route == "tsv2" else "cfd" if route in AP_CFD_ROUTEN else "futures"
        out.append({"key": key, "name": f.get("name") or key, "art": art, "an": key in an})
    return out


def tt_gruppen_auswahl(gruppen, param=None):
    """REIN RECHNEND: [{gruppe_id, name, an}] aus id_gruppen (admin_gruppen_daten) — WS2b: Häkchen je Unternehmen, HT ist immer dabei."""
    an = set((param or {}).get("gruppen") or ())
    return [{"gruppe_id": str(g.get("id")), "name": g.get("name"), "an": str(g.get("id")) in an} for g in gruppen or () if g.get("id")]


def tt_ids_auswahl(user_ids, namen, param=None):
    """REIN RECHNEND (TT1, 11.11.2026): [{user_id, name, an}] — alle IDs des HT-Challenge-Planers (auto_plan_regeln.user_ids), nach Name sortiert;
    an = in param.test_ids. Test-IDs, die nicht mehr im Planer sind, bleiben sichtbar (an, name None), damit man sie abhaken kann."""
    an = [str(x) for x in (param or {}).get("test_ids") or ()]
    planer = [str(u) for u in user_ids or ()]
    out = [{"user_id": u, "name": (namen or {}).get(u), "an": u in an, "im_planer": u in planer} for u in dict.fromkeys(planer + an)]
    return sorted(out, key=lambda x: (str(x["name"] or "~").lower(), x["user_id"]))


def tt_einst_anwenden(regeln, aenderungen, firmen_keys=None, gruppen_ids=None, ids_bekannt=None):
    """REIN RECHNEND (testbar): regeln (Kopie) + {feld: wert} für den Block tagesteilung → (regeln_neu, None) | (None, grund). Alles oder nichts;
    grund nennt die EINE Ursache mit dem Wert. Fehlt der Block, wird er aus TT_STANDARD angelegt.
    TT1 (11.11.2026): test_ids nur bekannte HT-Planer-IDs (ids_bekannt); jedes Speichern von test_ids leert den alten Testkonten-Eintrag
    (nur_konten, Weg entfällt). Ergäbe die Änderung „an“ ohne Test-ID (= ALLE Konten der angehakten Firmen), nur mit alle_ok = true
    (Finn 10.11.2026: „nicht dass das gleich direkt alle auf einmal sprengt“)."""
    if not isinstance(aenderungen, dict) or not aenderungen:
        return None, "tagesteilung = {Feld: Wert}"
    aenderungen = dict(aenderungen)
    alle_ok = aenderungen.pop("alle_ok", None) is True
    if not aenderungen:
        return None, "tagesteilung = {Feld: Wert}"
    neu = json.loads(json.dumps(regeln if isinstance(regeln, dict) else {}))
    blk = neu.get("tagesteilung") if isinstance(neu.get("tagesteilung"), dict) else json.loads(json.dumps(TT_STANDARD))
    for k, v in aenderungen.items():
        if k in ("an", "schluss_topstep", "schluss_news_sperre"):
            if not isinstance(v, bool):
                return None, f"{k} = true | false"
        elif k == "anteile":
            if _tt_anteile(v) is None:
                s = sum(float(x) for x in v if isinstance(x, (int, float)) and not isinstance(x, bool)) if isinstance(v, list) else None
                return None, ("anteile: Summe {:g} statt 100".format(s) if (isinstance(v, list) and len(v) == 4 and s is not None)
                              else "anteile = [1 Trade %, 2 Trades %, 3 Trades %, 4 Trades %], je 0–100, Summe 100")
        elif k in TT_SPANNEN:
            lo, hi = TT_SPANNEN[k]
            if k in ("neben_tp_teiler", "neben_lots_streu") and not isinstance(v, bool) and isinstance(v, (int, float)):
                v = [float(v), float(v)]             # WS3c/WS3d: ein einzelner Wert = fest
            if _tt_spanne(v, lo, hi) is None:
                return None, f"{k} = [von, bis] mit {lo:g} ≤ von ≤ bis ≤ {hi:g}"
        elif k in TT_ZAHLEN:
            lo, hi = TT_ZAHLEN[k]
            if isinstance(v, bool) or not isinstance(v, (int, float)) or v != v or not (lo <= float(v) <= hi):
                return None, f"{k} = Zahl {lo:g}–{hi:g}"
        elif k == "firmen":
            if not isinstance(v, list) or any(not isinstance(x, str) for x in v):
                return None, "firmen = [Firmen-Schlüssel]"
            fremd = [x for x in v if firmen_keys is not None and x not in firmen_keys]
            if fremd:
                return None, f"firmen: „{fremd[0]}“ gibt es nicht (oder Apex — nie geteilt)"
        elif k == "gruppen":
            if not isinstance(v, list) or any(not (isinstance(x, str) and re.fullmatch(r"[0-9a-fA-F-]{36}", x)) for x in v):
                return None, "gruppen = [Unternehmen-IDs] (leer = nur Hermann Technologies)"
            fremd = [x for x in v if gruppen_ids is not None and x not in gruppen_ids]
            if fremd:
                return None, f"gruppen: Unternehmen {fremd[0][:8]}… gibt es nicht"
        elif k == "nur_konten":
            if not isinstance(v, list) or any(not (isinstance(x, str) and re.fullmatch(r"[0-9a-fA-F-]{36}", x)) for x in v):
                return None, "nur_konten = [Konto-IDs]"
        elif k == "lots_bezug":
            if v not in TT_LOTS_BEZUG:
                return None, "lots_bezug = tagesziel | haupt"
        elif k == "test_n":
            if v is not None and (isinstance(v, bool) or not isinstance(v, (int, float)) or not float(v).is_integer() or not 1 <= v <= 4):
                return None, "test_n = null | 1–4"
            v = int(v) if v is not None else None
        elif k == "test_ids":
            if not isinstance(v, list) or any(not (isinstance(x, str) and re.fullmatch(r"[0-9a-fA-F-]{36}", x)) for x in v):
                return None, "test_ids = [IDs]"
            _bek = None if ids_bekannt is None else set(ids_bekannt) | {str(x) for x in (blk.get("test_ids") or ())}   # schon gespeicherte bleiben erlaubt
            fremd = [x for x in v if _bek is not None and x not in _bek]
            if fremd:
                return None, f"test_ids: ID {fremd[0][:8]}… ist nicht im Challenge-Planer (Hermann Technologies)"
            v = list(dict.fromkeys(v))
        else:
            return None, f"tagesteilung/{k} ist hier nicht änderbar"
        blk[k] = v
    if "test_ids" in aenderungen and "nur_konten" not in aenderungen:
        blk["nur_konten"] = []                          # TT1: Test-IDs ersetzen die Testkonten ganz (der alte Eintrag sperrte sonst weiter, tt_gilt)
    if any(k in aenderungen for k in ("an", "test_ids", "nur_konten")) and blk.get("an") is True and not blk.get("test_ids"):
        if not alle_ok:
            return None, "ohne Test-ID gilt „Trades pro Tag“ für ALLE Konten der angehakten Firmen — Test-ID anhaken oder ausdrücklich bestätigen (alle_ok)"
        blk["nur_konten"] = []                          # bestätigt „alle“: der alte Testkonten-Eintrag darf das nicht still wieder auf „nichts“ drehen
    neu["tagesteilung"] = blk
    return neu, None


def tt_gilt(param, fkey, gruppe_id, konto_id, konto_typ, user_id=None, route=None):
    """REIN RECHNEND (testbar): wird für dieses Konto heute geteilt? Schalter an, Firma in der Liste (Apex nie), Unternehmen: HT (gruppe_id None)
    immer, ein anderes nur, wenn seine id_gruppen.id in param.gruppen steht; Challenge-Typ; bei nur_konten nur diese Konten.
    TT1 (Finn 11.11.2026, „erstmal nur für Echo-Konten“ / „ich will keine Testkonten mehr“): stehen Test-IDs in param.test_ids, gilt es NUR für
    Konten dieser IDs und nur auf Echo-Wegen (route der Firma mt5v2/mt5, wie tt_planer_haken ohne route = mt5v2). Der Testkonten-Weg (nur_konten)
    ist raus: steht dort ohne Test-IDs noch ein alter Eintrag (Test 10.11.), wird NICHTS geteilt — nie still alle Konten."""
    if not (param or {}).get("an") or not fkey or str(fkey).startswith("apex") or str(fkey) not in (param.get("firmen") or ()):
        return False
    if gruppe_id and str(gruppe_id) not in (param.get("gruppen") or ()):
        return False
    if str(konto_typ or "") not in AP_TYPEN:
        return False
    ti = param.get("test_ids") or []
    if ti:
        return user_id is not None and str(user_id) in ti and str(route or "mt5v2") in AP_CFD_ROUTEN
    return not (param.get("nur_konten") or [])


def tt_wuerfeln(param, rnd, n_fest=None):
    """REIN RECHNEND (testbar): Würfel des Tages → {n, haupt_an, anteile} (anteile in Reihenfolge, Summe 1). n aus param.anteile (bzw. n_fest),
    Haupt-Platz gleichverteilt, Haupt-Anteil aus haupt_pct, der Rest zufällig (Schnittpunkte) auf die Neben-Trades."""
    if n_fest:
        n = int(n_fest)
    else:
        x, summe, n = rnd.random() * sum(param["anteile"]), 0.0, 4
        for i, p in enumerate(param["anteile"]):
            summe += p
            if x < summe:
                n = i + 1
                break
    h = _ap_spanne(param["haupt_pct"], rnd.random()) / 100.0
    if n == 1:
        return {"n": 1, "haupt_an": 1, "anteile": [1.0]}
    haupt_an = rnd.randint(1, n)
    schnitte = sorted(rnd.random() for _ in range(n - 2))
    teile = [b - a for a, b in zip([0.0] + schnitte, schnitte + [1.0])]
    neben = [(1.0 - h) * t for t in teile]
    anteile = neben[:haupt_an - 1] + [h] + neben[haupt_an - 1:]
    return {"n": n, "haupt_an": haupt_an, "anteile": [round(a, 4) for a in anteile]}


def tt_zusammenlegen(plan, ziel_usd, min_tp, ab=0):
    """REIN RECHNEND (testbar): Teile ab Platz ab (0-basiert), deren erwarteter TP (Anteil × ziel_usd, auf die Restanteile gerechnet) unter min_tp liegt,
    mit dem nächsten Teil zusammenlegen (der letzte mit dem vorigen). Haupt bleibt Haupt. → plan (Kopie)."""
    an = list(plan["anteile"])
    ha = int(plan["haupt_an"]) - 1
    while len(an) - ab > 1:
        rest = sum(an[ab:])
        klein = [i for i in range(ab, len(an)) if rest > 0 and ziel_usd * an[i] / rest < min_tp]
        if not klein:
            break
        i = klein[0]
        j = i + 1 if i + 1 < len(an) else i - 1
        if j < ab:
            break
        a, b = min(i, j), max(i, j)
        an[a] = round(an[a] + an[b], 4)
        del an[b]
        if ha == b or ha == a:
            ha = a
        elif ha > b:
            ha -= 1
    return {"n": len(an), "haupt_an": ha + 1, "anteile": an}


def tt_neben(tp_usd, art, pv, haupt_menge, param, u_pkt, u_sl, schritt=None, symbol=None):
    """REIN RECHNEND (testbar): Neben-Trade → {menge, symbol, tp, sl, tp_pkt, sl_pkt} | None. art 'fut' (Orbit: NQ/MNQ), 'fut_nq' (Topstep: nur NQ),
    'cfd' (Lots, Schritt). Punkte p aus neben_pkt (u_pkt); Lots = TP ÷ (p × Punktwert), höchstens neben_menge_max × Haupt-Lots, mindestens ein Schritt;
    liegt der TP danach über neben_pkt.hi Punkten, wird er auf hi Punkte gekürzt (der Rest bleibt für spätere Teile), unter lo auf lo angehoben.
    SL = Faktor (u_sl) × TP-Punkte."""
    lo, hi = param["neben_pkt"]
    p = _ap_spanne(param["neben_pkt"], u_pkt)
    f = _ap_spanne(param["neben_sl_faktor"], u_sl)
    mx = float(param["neben_menge_max"])
    if not tp_usd or tp_usd <= 0 or not pv or not haupt_menge:
        return None
    if art == "fut":
        mikro_pv = pv / 10.0
        cap = max(1, int(float(haupt_menge) * mx * 10 + 1e-9))
        n = max(1, min(cap, int(round(tp_usd / (p * mikro_pv)))))
        if n % 10 == 0:
            menge, wert, sym = n // 10, pv, symbol
        else:
            menge, wert, sym = n, mikro_pv, TT_MIKRO.get(str(symbol or "NQ"), "MNQ")
    elif art == "fut_nq":
        cap = max(1, int(float(haupt_menge) * mx + 1e-9))
        menge = max(1, min(cap, int(round(tp_usd / (p * pv)))))
        wert, sym = pv, symbol
    else:
        s = float(schritt or 0.01)
        cap = max(s, int(float(haupt_menge) * mx / s + 1e-9) * s)
        menge = max(s, min(cap, round(round(tp_usd / (p * pv) / s) * s, 4)))
        menge = int(menge) if s >= 1 else round(menge, 4)
        wert, sym = pv, None
    tp_pkt = tp_usd / (float(menge) * wert)
    if tp_pkt > hi:
        tp_pkt = hi                                  # Lots am Deckel: TP auf hi Punkte gekürzt, der Rest bleibt für spätere Teile
    elif tp_pkt < lo:
        tp_pkt = lo
    tp = round(tp_pkt * float(menge) * wert)
    sl_pkt = tp_pkt * f
    return {"menge": menge, "symbol": sym, "tp": tp, "sl": round(sl_pkt * float(menge) * wert), "tp_pkt": round(tp_pkt, 2), "sl_pkt": round(sl_pkt, 2)}


# ══ WS3 LOTS JE TEIL PROPORTIONAL (Master 10.11.2026; Finn: „Am Anfang vom Tag wird ein Ziel gesetzt und auf alle Trades aufgeteilt. Der Haupttrade macht so
# 80 % vom Ziel aus, die Nebentrades nur so 12 %, 8 % oder so jeweils. Dann sollen die auch nur so viel Prozent der Lots kaufen. Wenn der zweite Trade 6 % vom
# gesamten Take Profit ausmacht, dann soll er nur 6 % von den Lots vom ersten kaufen.“ Anlass: The5%ers-Test 10.11., Haupt 53 Lot, Neben je 26 Lot mit TP-Deckel
# 650 $ = 25 Pkt). Ersetzt tt_neben (halbe Lots, 10–25 Pkt) für Neben-Teile: Lots = Haupt-Lots × Anteil (lots_bezug „tagesziel“, Finns Formel) bzw.
# × Anteil ÷ Haupt-Anteil („haupt“: derselbe Punkt-Abstand wie der Haupt-Trade), auf den Lot-Schritt gerundet, mindestens das kleinste Lot (Vermerk).
# WS3b (Finn 10.11.2026 nach der Beispiel-Tabelle: „Lots trotzdem klein halten … Aber den Take Profit runterholen, z. B. durch 4“): TP-Punkte = TP-Punkte des
# Haupt-Trades (Anteil_Haupt × Tagesziel ÷ Haupt-Lots ÷ Punktwert) ÷ neben_tp_teiler, TP $ = Lots × Punkte × Punktwert (höchstens tp_max_usd = Rest bis
# Ziel bei Folge-Teilen). SL-Punkte = Haupt-SL-Punkte ÷ Teiler (TP:SL wie beim Haupt); ohne Haupt-SL (Orbit-Haupt ohne SL) wie bisher Faktor
# WS3d (Finn 10.11.2026: „TP und Lots sollen beide Varianz kriegen“): Lots zusätzlich × Würfel neben_lots_streu (Standard 0,7–1,3) vor dem Runden.
# neben_sl_faktor × TP-Punkte. Fusion-Hedge: der Echo-Copier rechnet je Master-Lot (multiplier) — mit den kleineren Lots also proportional.
def tt_teil(anteil, anteil_haupt, art, pv, haupt_menge, tp_pkt_haupt, sl_pkt_haupt, param, u_t, u_sl, schritt=None, symbol=None, tp_max_usd=None, u_l=None):
    """REIN RECHNEND (testbar): Neben-Teil → {menge, symbol, tp, sl, tp_pkt, sl_pkt, lots_roh, aufgerundet, teiler} | None. art 'fut' (Orbit: NQ, sonst MNQ in
    Zehnteln), 'fut_nq' (Topstep: nur NQ), 'cfd' (Lots im Schritt). tp_pkt_haupt / sl_pkt_haupt = Punkte des Haupt-Trades (pv-Einheit des Regel-Symbols).
    u_t = Zufallszahl für den Teiler (WS3c, gleichverteilt in neben_tp_teiler), u_sl = Zufallszahl für den SL-Faktor (nur ohne Haupt-SL),
    u_l = Zufallszahl für die Lots-Streuung (WS3d, gleichverteilt in neben_lots_streu; None = Streuung 1, ohne Würfel).
    WS3c (Master 11.11.2026, Prüfer-SOLLTE): Lots nie über den Haupt-Lots (auch bei geänderten Einstellungen, Vermerk gedeckelt); TP- und SL-Abstand
    mindestens neben_min_pkt (Standard 10 Pkt, „Invalid stops“ FS2) — drückt der Rest bis Ziel (tp_max_usd) den TP darunter, kommt
    {"zu_eng": True, "grund": …} statt eines Teils (lieber kein Neben-Trade als ein zu enger); CFD ohne Lot-Schritt = 1 wie beim Haupt."""
    try:
        anteil, haupt_menge, pv, tph = float(anteil or 0), float(haupt_menge or 0), float(pv or 0), float(tp_pkt_haupt or 0)
        sp_t = (param or {}).get("neben_tp_teiler") or [4.0, 4.0]
        teiler = round(_ap_spanne(sp_t if isinstance(sp_t, (list, tuple)) else [sp_t, sp_t], u_t), 3)
    except (TypeError, ValueError):
        return None
    if anteil <= 0 or pv <= 0 or haupt_menge <= 0 or tph <= 0 or teiler < 1:
        return None
    faktor = anteil
    if (param or {}).get("lots_bezug") == "haupt":
        try:
            ah = float(anteil_haupt or 0)
        except (TypeError, ValueError):
            ah = 0.0
        if ah <= 0:
            return None
        faktor = anteil / ah
    streu = 1.0
    if u_l is not None:
        sp_l = (param or {}).get("neben_lots_streu") or [1.0, 1.0]
        try:
            streu = round(_ap_spanne(sp_l if isinstance(sp_l, (list, tuple)) else [sp_l, sp_l], u_l), 3)
        except (TypeError, ValueError):
            streu = 1.0
        if not streu > 0:
            return None
    roh = haupt_menge * faktor * streu
    gedeckelt = roh > haupt_menge
    if gedeckelt:
        roh = haupt_menge                            # WS3c: nie mehr Lots als der Haupt-Trade
    auf = False
    menge_nq = None                                  # Lots in Haupt-Einheit (Orbit: NQ) für den Deckel
    if art == "fut":
        n = int(round(roh * 10))                     # MNQ-Kontrakte (1 NQ = 10 MNQ)
        if n < 1:
            n, auf = 1, True
        menge_nq = n / 10.0
        if n % 10 == 0:
            menge, wert, sym = n // 10, pv, symbol
        else:
            menge, wert, sym = n, pv / 10.0, TT_MIKRO.get(str(symbol or "NQ"), "MNQ")
    elif art == "fut_nq":
        menge = int(round(roh))
        if menge < 1:
            menge, auf = 1, True
        wert, sym = pv, symbol
    else:
        st = float(schritt or 1)                     # WS3c: ohne Lot-Schritt 1 wie beim Haupt (ap_konto_rechnen menge_schritt or 1)
        if st <= 0:
            st = 1.0
        menge = round(round(roh / st) * st, 4)
        if menge < st:
            menge, auf = st, True
        menge = int(round(menge)) if st >= 1 else round(menge, 4)
        wert, sym = pv, None
    if (menge_nq if menge_nq is not None else float(menge)) > haupt_menge + 1e-9:
        return None                                  # Mindest-Lot größer als der Haupt-Trade → kein Neben-Trade (WS3c-Deckel)
    try:
        min_pkt = float((param or {}).get("neben_min_pkt") or 0)
    except (TypeError, ValueError):
        min_pkt = 0.0
    tp_pkt = max(tph / teiler, min_pkt)
    tp = round(tp_pkt * float(menge) * wert, 2)      # Prüfer WS3 (S2): auf Cent, nie still auf 0 $ (kleine Lots)
    try:
        cap = float(tp_max_usd) if tp_max_usd is not None else None
    except (TypeError, ValueError):
        cap = None
    if cap is not None and 0 < cap < tp:
        tp = round(cap, 2)                           # Folge-Teil: nie über den Rest bis Ziel
    if tp <= 0:
        return None
    tp_pkt = tp / (float(menge) * wert)
    if min_pkt and tp < round(min_pkt * float(menge) * wert, 2) - 0.005:   # in Cent verglichen (Prüfer WS3c: Cent-Rundung allein ist nie „zu eng“)
        return {"zu_eng": True, "grund": f"Neben-TP wäre nur {tp_pkt:.1f} Pkt (Mindest {min_pkt:g} Pkt) — Rest bis Ziel {tp:,.0f} $ zu klein".replace(",", ".")}
    try:
        slh = float(sl_pkt_haupt) if sl_pkt_haupt is not None and float(sl_pkt_haupt) > 0 else None
    except (TypeError, ValueError):
        slh = None
    sl_pkt = max(slh / teiler if slh else tp_pkt * _ap_spanne(param["neben_sl_faktor"], u_sl), min_pkt)   # WS3c: nie enger als neben_min_pkt
    sl = round(sl_pkt * float(menge) * wert, 2)
    if tp < 0.01 or sl < 0.01:
        return None                                  # nie ein Teil mit TP/SL 0 $ (Prüfer WS3 S2)
    return {"menge": menge, "symbol": sym, "tp": tp, "sl": sl, "tp_pkt": round(tp_pkt, 2),
            "sl_pkt": round(sl_pkt, 2), "lots_roh": round(roh, 4), "aufgerundet": auf, "teiler": teiler, "lots_streu": streu, "gedeckelt": gedeckelt}


def tt_sl_pkt(sl_usd, menge, art, pv, symbol=None):
    """REIN RECHNEND (testbar): SL-Abstand des Haupt-Trades in Punkten (SL $ ÷ Lots ÷ Punktwert; MNQ mit pv/10) | None."""
    try:
        sl, m, pv = float(sl_usd or 0), float(menge or 0), float(pv or 0)
    except (TypeError, ValueError):
        return None
    if sl <= 0 or m <= 0 or pv <= 0:
        return None
    wert = pv / 10.0 if art == "fut" and str(symbol or "") in TT_MIKRO.values() else pv
    return sl / (m * wert)


def tt_tp_pkt_haupt(ziel, anteil_haupt, haupt_menge, pv):
    """REIN RECHNEND (testbar): TP-Abstand des Haupt-Trades in Punkten = Anteil_Haupt × Tagesziel ÷ Haupt-Lots ÷ Punktwert (Regel-Symbol) | None."""
    try:
        z, a, m, pv = float(ziel or 0), float(anteil_haupt or 0), float(haupt_menge or 0), float(pv or 0)
    except (TypeError, ValueError):
        return None
    return z * a / (m * pv) if z > 0 and a > 0 and m > 0 and pv > 0 else None


def tt_teil_art(route):
    return "fut_nq" if route == "tsv2" else "cfd" if route in AP_CFD_ROUTEN else "fut"


def tt_planer_haken(w, regel, phase, param, rnd, ppl=None, n_fest=None):
    """REIN RECHNEND (testbar): Trade 1 eines Tages, den ap_konto_rechnen gerechnet hat (w) → w2 (Kopie). Würfelt n; n = 1 → Orbit/Echo unverändert
    (kein kette-Block), Topstep wird ein Ein-Trade-Tag (TP = Tagesziel, SL die Trade-1-Spanne von heute). n > 1 → Trade 1 holt seinen Anteil vom
    Tagesziel: als Haupt mit Lots/SL von w, als Neben klein (tt_neben). Schreibt w2.kette {nr 1, von, rolle, plan, tagesziel, haupt_menge, …}.
    Immer ein Trade: Klein-/Mini-/Gewinntag-/finaler Orbit-Trade (TT_EIN_TRADE_STUFE), Topstep-Reparatur-Tag, CFD ohne Punktwert, Futures-Symbol ohne Punktwert."""
    route = str(regel.get("route") or "mt5v2")
    k0 = dict(w.get("kette") or {}) if isinstance(w.get("kette"), dict) else None
    if route == "tsv2" and not k0:
        return w                                    # Topstep ohne Kettenregel: nie anfassen
    if k0 and (k0.get("reparatur") or k0.get("ein_trade")):
        return w                                    # Reparatur-Tag bleibt ein Trade (alter Weg)
    if w.get("symbol") or (route != "tsv2" and tt_ein_trade_fest(w, route)):
        return w
    art = tt_teil_art(route)
    sym = str(regel.get("symbol") or "NQ")
    pv = float(ppl) if art == "cfd" and ppl else TT_FUT_PV.get(sym) if art != "cfd" else None
    if not pv:
        return w
    ziel = float(k0["tagesziel"]) if k0 else float(w["tp"])
    plan = tt_wuerfeln(param, rnd, n_fest)
    if plan["n"] > 1:
        plan = tt_zusammenlegen(plan, ziel, float(param["min_tp_usd"]))
    if plan["n"] == 1 and not k0:
        return w
    w2 = dict(w)
    haupt = plan["haupt_an"] == 1
    a1 = plan["anteile"][0]
    k = dict(k0 or {}, nr=1, von=plan["n"], rolle="haupt" if haupt else "neben", plan=plan, tagesziel=round(ziel), haupt_menge=w["menge"])
    schritt = ((regel.get("phasen") or {}).get(str(phase)) or {}).get("menge_schritt")
    if art == "cfd":
        k.update(ppl=pv, menge_schritt=schritt)
    if haupt:
        w2["tp"] = round(ziel * a1) if plan["n"] > 1 else round(ziel)
        txt = f"Haupt {round(a1 * 100)} %"
    else:
        sl_cap = w.get("sl")
        if route == "tsv2":
            sl_cap = (k0 or {}).get("verlust_grenze") or sl_cap
        ah = plan["anteile"][plan["haupt_an"] - 1]
        # WS3c/WS3d: Teiler-Würfel an der Stelle des früheren Punkte-Würfels, dann SL-Würfel, dann (neu, dritter Zug) Lots-Würfel — an Mehr-Trade-Tagen
        # verschieben sich damit die späteren Züge; 1-Trade-Tage ziehen hier nie (bitgleich). TP höchstens der Ein-Trade-TP (Rest bis Konto-Ziel, Prüfer WS3)
        nb = tt_teil(a1, ah, art, pv, w["menge"], tt_tp_pkt_haupt(ziel, ah, w["menge"], pv), tt_sl_pkt(w.get("sl"), w["menge"], art, pv, sym),
                     param, rnd.random(), rnd.random(), schritt=schritt, symbol=sym, u_l=rnd.random(),     # WS3d: Lots-Würfel als dritter Zug
                     tp_max_usd=(float(w["tp"]) if _wd_num(w.get("tp")) else None))
        if not nb or nb.get("zu_eng"):
            return w                                # WS3c: zu eng / nicht rechenbar → Trade 1 bleibt ein Trade wie heute
        _sl1 = min(nb["sl"], round(float(sl_cap), 2)) if sl_cap else nb["sl"]   # auf Cent wie tt_folge_rechnen (Prüfer WS3c)
        if _sl1 < nb["sl"] and nb["sl_pkt"] * _sl1 / nb["sl"] < float(param.get("neben_min_pkt") or 0) - 1e-6:
            return w                                # WS3c: von der Grenze unter den Mindest-Abstand gekürzt → kein Neben-Trade
        w2.update(menge=nb["menge"], tp=nb["tp"], sl=_sl1, puffer=0)
        w2["risiko"] = w2["sl"]
        if nb.get("symbol") and nb["symbol"] != sym:
            w2["symbol"] = nb["symbol"]
        k.update(tp_pkt=nb["tp_pkt"], sl_pkt=nb["sl_pkt"], lots_roh=nb["lots_roh"], lots_bezug=param.get("lots_bezug"), tp_teiler=nb["teiler"],
                 lots_streu=nb["lots_streu"], lots_gedeckelt=nb["gedeckelt"])
        txt = f"Neben {round(a1 * 100)} % · {nb['menge']:g} Lot{' (Mindest-Lot)' if nb['aufgerundet'] else ''} · {nb['tp_pkt']:g} Pkt"
    anteile_txt = " · ".join(("Haupt " if i + 1 == plan["haupt_an"] else "") + f"{round(x * 100)} %" for i, x in enumerate(plan["anteile"]))
    w2["stufe"] = f"Tag 1/{plan['n']} · {txt} (Tag: {anteile_txt}, Ziel +{round(ziel):,} $)".replace(",", ".") + " · " + str(w.get("stufe") or "")
    w2["kette"] = k
    return w2


def tt_ein_trade_fest(w, route=None):
    """REIN (testbar; Nachzug 10.11.2026 nach Prüfer-OK, Master): ist w ein finaler oder kleiner Trade, der EIN Trade bleibt und KEINEN Zufalls-Schluss
    (zschluss) bekommt? Sonst schlösse WS2c einen Pass-Trade zufällig vor dem Ziel. Klein-/Mini-/Gewinntag-/Rest-/letzter Trade (tage_mini,
    TT_EIN_TRADE_STUFE) und final wie ap_tradeify_final_halten / prophos_plan_final_text: Rest ≤ 0 oder TP ≥ Rest bis Ziel — genau die Pläne, die
    tfh_tick kurz vor dem Start auf Orbit V3 hebt. Topstep (tsv2): Stufen-Texte der Kette zählen nicht (eigene Texte), nur tage_mini und Rest/TP."""
    w = w if isinstance(w, dict) else {}
    if w.get("tage_mini"):
        return True
    stufe = str(w.get("stufe") or "")
    if str(route or "") != "tsv2" and TT_EIN_TRADE_STUFE.search(stufe):
        return True
    if stufe.startswith("Tage sammeln"):
        return False
    rest, tp = _wd_num(w.get("rest")), _wd_num(w.get("tp"))
    if rest is None:
        return False
    return rest <= 0 or (tp is not None and tp > 0 and tp >= rest)


def tt_bal_wache_ok(k):
    """REIN (Gegenprüfung 09.11.2026): darf die Balance-Wache diesen Ketten-Plan prüfen? Nur Trade 1 eines Orbit-/Echo-Tags (WS2, kette.von, ohne Topstep-
    Verlustgrenze) — er ist aus der Konto-Balance geplant wie jeder normale Plan. Topstep und Folge-Teile (aus der genauen Lesung) nie."""
    k = k if isinstance(k, dict) else {}
    try:
        return bool(k.get("von")) and int(k.get("nr") or 0) == 1 and k.get("verlust_grenze") is None
    except (TypeError, ValueError):
        return False


def tt_zschluss(param, rnd):
    """REIN RECHNEND (testbar): Zufalls-Schluss je Plan (WS2c) → {nach_min} mit Wahrscheinlichkeit aus schluss_pct, sonst None."""
    return tt_zschluss_wurf(param, rnd)[0]


def tt_zschluss_wurf(param, rnd):
    """REIN RECHNEND (testbar): wie tt_zschluss, dazu der Wurf als Beleg (WZ1, Master 10.11.2026 nach dem WS2-Test: „0 von 3 ausgelöst“ war
    nicht prüfbar, weil nur Treffer gespeichert wurden) → (zschluss | None, {p, zug, treffer[, nach_min]}). p = gewürfelte Wahrscheinlichkeit
    aus schluss_pct (0..1), zug = Zufallszahl dagegen; Treffer bei zug < p. Dieselben rnd-Züge in derselben Reihenfolge wie bisher — der
    Planer-Lauf bleibt bitgleich."""
    p = _ap_spanne(param["schluss_pct"], rnd.random()) / 100.0
    zug = rnd.random()
    wurf = {"p": round(p, 4), "zug": round(zug, 4), "treffer": zug < p}
    if zug >= p:
        return None, wurf
    zs = {"nach_min": int(round(_ap_spanne(param["schluss_min"], rnd.random()))),
          "topstep": param.get("schluss_topstep") is True, "news_sperre": param.get("schluss_news_sperre") is not False}
    wurf["nach_min"] = zs["nach_min"]
    return zs, wurf


def tt_echt(plan):
    """REIN RECHNEND (testbar): genaue Lesung eines beendeten Teils → (vorher, nachher) | None. Orbit/Topstep/Echo V2 über ap_echte_balancen (nur
    Puls-Endlesung bzw. Nachlesung, nie Demo/Level/Folgetrade); Echo mit Hedge (mt5): master_balance + bal_nach (ok, Nachlesung)."""
    p = plan or {}
    bl = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    if str(p.get("route") or "") == "mt5":
        bn = bl.get("bal_nach") if isinstance(bl.get("bal_nach"), dict) else {}
        v, n = _wd_num(bl.get("master_balance")), _wd_num(bn.get("balance"))
        return (float(v), float(n)) if (bn.get("ok") is True and v and n and v > 0 and n > 0) else None
    fin = bl.get("final") if isinstance(bl.get("final"), dict) else {}
    if fin.get("balance_quelle") == "folgetrade":
        return None
    e = ap_echte_balancen(p)
    return (e[0], e[1]) if e else None


def tt_hat_fusion(plan):
    """REIN (testbar): läuft dieser Teil mit Fusion-Gegenhedge? Echo mit Copier-Hedge (route mt5) oder ein Fusion-Solo-Hedge am Plan (mt5_baseline.hedge)."""
    p = plan or {}
    bl = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    h = bl.get("hedge")
    # Fusion-Solo nur, wenn er wirklich offen war (Ticket bzw. offen/schließt/geschlossen) — status 'fehler' (nie geöffnet) hat keinen Fusion-P&L
    return str(p.get("route") or "") == "mt5" or (isinstance(h, dict) and bool(h.get("ticket") or h.get("status") in ("offen", "schliesst", "geschlossen")))


def tt_fusion_pl(plan):
    """REIN RECHNEND (testbar, WS2E-Tag 10.11.2026): belegter Fusion-P&L (€) eines Teils | None. Echo (mt5): slave_pl am Plan, sonst final.closed_sum
    (Σ closed_hedges.profit des Copiers). Fusion-Solo (mt5_baseline.hedge): hedge.pl, sonst slave_pl. Ohne Hedge oder ohne Beleg None."""
    p = plan or {}
    if not tt_hat_fusion(p):
        return None
    bl = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    if str(p.get("route") or "") == "mt5":
        fin = bl.get("final") if isinstance(bl.get("final"), dict) else {}
        v = _wd_num(p.get("slave_pl"))
        if v is None:
            v = _wd_num(fin.get("closed_sum"))
    else:
        # Gegenprüfung: slave_pl zuerst — es ist die Summe aller Versuche (hedgePlGesamt mit versuche_alt), hedge.pl nur der letzte (wie der Radar)
        v = _wd_num(p.get("slave_pl"))
        if v is None:
            v = _wd_num((bl.get("hedge") or {}).get("pl"))
    return round(float(v), 2) if v is not None else None


def tt_abhak_werte(plan, echt):
    """REIN RECHNEND (testbar): darf tt_tick einen Teil MIT Nachfolger selbst abhaken? → (master_pl, slave_pl, pl_quelle) | None (bleibt bei Finn).
    Orbit/Topstep ohne Fusion-Solo-Hedge wie bisher (slave_pl None, Quelle tv). WS2E (Master 10.11.2026, Finn „einmal abhaken“ auch bei Echo): Echo mit
    Copier-Hedge (mt5) nur mit BELEGTEM Fusion-P&L — slave_pl am Plan (atMoveToReview schreibt ihn aus final.closed_sum) bzw. final.closed_sum selbst
    (Σ closed_hedges.profit des Copiers im Trade-Fenster; null = Hedge extern zu / Ring gekürzt / kein Beleg → Finn trägt ein). Echo V2 (mt5v2) bleibt wie
    bisher bei Finn (Gegenprüfung: Folge-Teile sind immer mt5, und _wd_erledigt_upd würde sein slave_pl 0 mit null überschreiben).
    master_pl immer aus der genauen Lesung (echt = tt_echt)."""
    p = plan or {}
    if not echt:
        return None
    bl = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    route = str(p.get("route") or "")
    mpl = round(float(echt[1]) - float(echt[0]), 2)
    if route in ("tvv2", "tsv2"):
        return None if bl.get("hedge") else (mpl, None, "tv")
    if route == "mt5":
        spl = tt_fusion_pl(p)
        return (mpl, spl, "echo") if spl is not None else None
    return None


def tt_zschluss_versucht(zs):
    """REIN (testbar): hat der Zufalls-Schluss (WS2c) an diesem Teil schon gegriffen bzw. begonnen? status geschlossen/war_flach/fehler — oder (WS2E
    10.11.2026) der PC-Tab hat den Versuch begonnen (zsAusfuehren schreibt versuche/letzter_versuch_at VOR dem Klick), status steht noch aus.
    'uebersprungen' (Orbit mit Hedge, finaler Pass-Trade) ist kein Versuch."""
    zs = zs if isinstance(zs, dict) else {}
    st = zs.get("status")
    if st in ("geschlossen", "war_flach", "fehler"):
        return True
    return not st and bool(zs.get("letzter_versuch_at") or zs.get("versuche"))


def tt_folge_rechnen(k, bal_tag0, bal_jetzt, regel, param, rnd, w_h=None, grund_h=None, kette_r=None):
    """REIN RECHNEND (testbar): nächster Teil nach dem genau gelesenen Teil k (kette-Block des vorigen) → (werte, None) | (None, (ende_code, text)).
    bal_tag0 = genaue Start-Balance von Trade 1, bal_jetzt = genaue End-Balance des vorigen Teils. w_h/grund_h = ap_konto_rechnen bei bal_jetzt (Orbit/Echo:
    Lots, SL, TP-Deckel des Haupt-Trades wie heute), kette_r = Topstep-Kettenregel (SL/Lots über ap_kette_trade2). werte = {nr, rolle, plan, menge, tp,
    sl, symbol?, tp_pkt?, sl_pkt?, e_bisher, rest}."""
    route = str(regel.get("route") or "mt5v2")
    nr = int(k.get("nr") or 1) + 1
    plan = dict(k.get("plan") or {})
    if not plan.get("anteile") or nr > int(plan.get("n") or len(plan["anteile"])):
        return None, ("alle", TT_ENDE_TXT["alle"])
    ziel = float(k.get("tagesziel") or 0)
    e = round(float(bal_jetzt) - float(bal_tag0), 2)
    rest = round(ziel - e, 2)
    if rest <= TT_ZIEL_REST_USD:
        return None, ("ziel", f"Tagesziel erreicht ({e:+,.0f} $ von +{ziel:,.0f} $)".replace(",", "."))
    plan = tt_zusammenlegen(plan, rest, float(param["min_tp_usd"]), ab=nr - 1) if nr < len(plan["anteile"]) else plan
    if nr > plan["n"]:
        return None, ("alle", TT_ENDE_TXT["alle"])
    s = sum(plan["anteile"][nr - 1:])
    tp_roh = rest if nr == plan["n"] else rest * plan["anteile"][nr - 1] / s
    if tp_roh < float(param["min_tp_usd"]):
        return None, ("rest_klein", f"Rest {rest:,.0f} $ unter dem Mindest-TP {float(param['min_tp_usd']):,.0f} $".replace(",", "."))
    haupt = nr == int(plan["haupt_an"])
    art = tt_teil_art(route)
    sym = str(regel.get("symbol") or "NQ")
    if route == "tsv2":
        w2, g2 = ap_kette_trade2(dict(k, e1=None), bal_tag0, bal_jetzt, regel, kette_r or AP_KETTE_STANDARD, rnd.random())
        if g2:
            return None, ("ziel" if "Tagesziel" in g2 else "verlust", g2)
        tp_cap, sl_h, menge_h, sym_h = float(w2["tp"]), w2["sl"], w2["menge"], None
    else:
        if grund_h or not w_h:
            g = str(grund_h or "nicht rechenbar")
            return None, ("ziel" if "Ziel erreicht" in g else "verlust", g)
        tp_cap, sl_h, menge_h, sym_h = float(w_h["tp"]), w_h.get("sl"), w_h["menge"], w_h.get("symbol")
    out = {"nr": nr, "rolle": "haupt" if haupt else "neben", "plan": plan, "e_bisher": e, "rest": round(rest)}
    if haupt:
        # risiko wie der Planer (ap_konto_rechnen: SL, sonst DD der Phase — Orbit-Haupt ohne SL); Topstep = SL2. Symbol IMMER gesetzt (Futures: Regel-
        # Symbol bzw. MNQ des Klein-Trades) — sonst erbte ein Haupt-Trade das MNQ eines Neben-Vorgängers (Gegenprüfung 09.11.2026: 3 MNQ statt 3 NQ)
        out.update(menge=menge_h, tp=round(min(tp_roh, tp_cap)), sl=sl_h, symbol=(None if art == "cfd" else (sym_h or sym)),
                   risiko=(sl_h if route == "tsv2" else (w_h.get("risiko") if w_h.get("risiko") is not None else sl_h)))
    else:
        pv = float(k.get("ppl") or 0) if art == "cfd" else TT_FUT_PV.get(sym)
        # WS3/WS3b: Lots = Haupt-Lots × Anteil, TP-/SL-Punkte = Punkte des Haupt-Trades ÷ Teiler (TP-Punkte aus dem Tagesplan, SL-Punkte aus dem Haupt bei der
        # jetzigen Balance), TP höchstens der Rest bis Ziel
        a_t = float(plan["anteile"][nr - 1])
        a_h = float(plan["anteile"][int(plan["haupt_an"]) - 1])
        hm = k.get("haupt_menge") or menge_h
        # WS3c/WS3d: Teiler-Würfel an der Stelle des früheren Punkte-Würfels, SL-Würfel, dann Lots-Würfel (dritter Zug). TP höchstens Rest bis Tagesziel UND
        # der TP-Deckel des Haupt-Trades bei der jetzigen Balance (tp_cap: Rest bis Konto-Ziel, Gewinn je Trade, Consistency — Prüfer WS3 MUSS, sonst würde ein
        # Neben-Teil still zum finalen Trade)
        nb = tt_teil(a_t, a_h, art, pv, hm, tt_tp_pkt_haupt(ziel, a_h, hm, pv), tt_sl_pkt(sl_h, menge_h, art, pv, sym_h or sym), param, rnd.random(),
                     rnd.random(), schritt=k.get("menge_schritt"), symbol=sym, tp_max_usd=min(rest, tp_cap), u_l=rnd.random())   # WS3d: Lots-Würfel
        if not nb:
            return None, ("verlust", "Neben-Trade nicht rechenbar (Punktwert fehlt)")
        if nb.get("zu_eng"):
            # WS3c: lieber kein Neben-Trade als einer mit „Invalid stops“. Auch vor dem Haupt (nr < haupt_an) endet der Tag: derselbe TP-Deckel
            # (Rest bis Konto-Ziel) machte den Haupt-TP ebenso klein (Prüfer WS3c)
            return None, ("rest_klein", nb["grund"])
        sl = nb["sl"]
        if sl_h:
            sl = min(sl, round(float(sl_h), 2))         # Prüfer WS3: auf Cent statt int — sonst gälte ein SL knapp unter sl_h schon als „gekürzt“
        elif route != "tsv2" and _wd_num(regel.get("daily_usd")):
            sl = min(sl, int(float(regel["daily_usd"]) - max(0.0, -e) - 100))
        # Prüfer WS3 (M1): Neben-SL ist jetzt von sich aus klein (Anteil × Haupt-SL ÷ Teiler) — stoppen nur, wenn die Grenze (Haupt-SL / Tagesverlust) ihn
        # gekürzt hat und er dann unter 50 $ liegt (ausgeschöpftes Restbudget wie bisher); ein natürlich kleiner SL läuft
        if sl < nb["sl"] and sl < 50:
            return None, ("verlust", f"SL für den Neben-Trade wäre nur {sl} $")
        if sl <= 0:
            return None, ("verlust", "SL für den Neben-Trade wäre 0 $")
        if sl < nb["sl"] and nb["sl_pkt"] * sl / nb["sl"] < float(param.get("neben_min_pkt") or 0) - 1e-6:
            return None, ("verlust", f"SL für den Neben-Trade wäre nur {nb['sl_pkt'] * sl / nb['sl']:.1f} Pkt (Mindest {float(param['neben_min_pkt']):g} Pkt)")
        out.update(menge=nb["menge"], tp=nb["tp"], sl=sl, symbol=(None if art == "cfd" else (nb["symbol"] or sym)), tp_pkt=nb["tp_pkt"], sl_pkt=nb["sl_pkt"],
                   lots_roh=nb["lots_roh"], aufgerundet=nb["aufgerundet"], tp_teiler=nb["teiler"], lots_streu=nb["lots_streu"],
                   lots_gedeckelt=nb["gedeckelt"])
    if route == "tsv2":
        out["verlust_grenze"] = w2.get("verlust_grenze")
    return out, None


_tt = {"letzter": 0.0, "letztes": None, "fehler": ""}
TT_TAKT_S = 60


def _tt_patch(pid, patch, key="kette"):
    """mt5_baseline.<key> eine Ebene tief mergen (RPC mt5_baseline_patch_in, atomar). Fehler nur loggen → bool."""
    try:
        r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/rpc/mt5_baseline_patch_in", headers=_sb_headers(), timeout=(5, 15),
                        json={"p_plan": str(pid), "p_key": key, "p_status": None, "p_patch": patch})
        _sb_pruefen(r)
        return True
    except Exception as e:
        print(f"[tagesteilung] ⚠️ {str(pid)[:8]} {key}: {type(e).__name__}: {e}", flush=True)
        return False


def _tt_tag_teile(tag_id, extra=None):
    """Alle Teile eines Tages (Trade 1 = tag_id selbst, Folgeteile über kette.tag_id) → [Plan] nach nr."""
    sel = "id,route,status,richtung,master_pl,slave_pl,ended_at,mt5_baseline"   # slave_pl: Fusion je Teil im Tagesende (WS2E-Tag, 10.11.2026)
    rows = (sb_select("trade_plans", {"select": sel, "id": f"eq.{tag_id}"}) or []) + \
           (sb_select("trade_plans", {"select": sel, "mt5_baseline->kette->>tag_id": f"eq.{tag_id}"}) or [])
    je = {str(r["id"]): r for r in rows}
    for r in extra or ():
        je[str(r["id"])] = r
    return sorted(je.values(), key=lambda r: int((((r.get("mt5_baseline") or {}).get("kette") or {}).get("nr")) or 0))


def _tt_fusion_feld(eintrag, p):
    """teile[]-Eintrag: fusion = belegter Fusion-P&L (€); Teil mit Hedge ohne Beleg → fusion None (Chip „fehlt"); ohne Hedge kein Schlüssel."""
    fu = tt_fusion_pl(p)
    if fu is not None:
        eintrag["fusion"] = fu
    elif tt_hat_fusion(p):
        eintrag["fusion"] = None


def _tt_fusion_summe(tl):
    """{fusion_sum, fusion_offen} für das Tagesende, nur wenn ein Teil einen Hedge hat. fusion_sum None, solange KEIN Teil belegt ist (nie „+0 €" aus Lücken)."""
    if not any("fusion" in x for x in tl):
        return {}
    werte = [x["fusion"] for x in tl if x.get("fusion") is not None]
    return {"fusion_sum": round(sum(werte), 2) if werte else None, "fusion_offen": sum(1 for x in tl if "fusion" in x and x["fusion"] is None)}


def tt_fusion_nachziehen(te, teile):
    """REIN RECHNEND (testbar): Tagesende mit fehlendem Fusion-P&L → neues Tagesende mit frischen Fusion-Feldern je Teil (nach nr), alles andere unverändert;
    None, wenn sich nichts ändert. Master-P&L, Summe, Grund bleiben, wie sie beim Tagesende geschrieben wurden."""
    if not isinstance(te, dict) or not isinstance(te.get("teile"), list):
        return None
    je = {int((((p.get("mt5_baseline") or {}).get("kette") or {}).get("nr")) or 0): p for p in teile or ()}
    tl = []
    for x in te["teile"]:
        y = dict(x)
        p = je.get(int(y.get("nr") or 0))
        if p is not None:
            y.pop("fusion", None)
            _tt_fusion_feld(y, p)
        tl.append(y)
    neu = dict(te, teile=tl, **_tt_fusion_summe(tl))
    return neu if neu != te else None


def tt_tagesende(teile, ende_code, text, bal_tag0, bal_ende, blown, jetzt_iso):
    """REIN RECHNEND (testbar): kette.tagesende am letzten Teil → {tag_pl, trades, teile, balance, blown, ende_grund, ende_text, at} (+ t1_pl/t2_pl für alte
    Topstep-Leser)."""
    tl = []
    for p in teile:
        kk = ((p.get("mt5_baseline") or {}).get("kette") or {})
        g = tt_echt(p)
        tl.append({"nr": int(kk.get("nr") or 0), "rolle": kk.get("rolle"), "richtung": p.get("richtung"),
                   "pl": round(g[1] - g[0], 2) if g else _wd_num(p.get("master_pl"))})
        _tt_fusion_feld(tl[-1], p)               # WS2E-Tag (Finn 10.11.2026): Fusion-P&L je Teil (€) für den Tag-Chip im Radar
    out = {"tag_pl": round(float(bal_ende) - float(bal_tag0), 2) if (bal_ende is not None and bal_tag0) else None, "trades": len(tl), "teile": tl,
           "balance": float(bal_ende) if bal_ende is not None else None, "blown": bool(blown), "ende_grund": ende_code, "ende_text": text, "at": jetzt_iso}
    out.update(_tt_fusion_summe(tl))
    if len(tl) >= 1:
        out["t1_pl"] = tl[0]["pl"]
    out["t2_pl"] = tl[1]["pl"] if len(tl) >= 2 else None
    return out


def tt_tick(jetzt=None, rnd=None):
    """WS2 Takt (jede Minute aus ap_loop über _tt_takt): beendete Ketten-Teile (kette.von, heute) ohne Nachfolger und ohne tagesende.
    Genau gelesen → nächster Teil (tt_folge_rechnen, Start Lesung + abstand_min, erste regelkonforme Minute bis Fensterende, Richtung frei) oder Tag
    fertig (tagesende am letzten Teil, bleibt in Überprüfen bis Finns einem Haken). Teile mit Nachfolger: Orbit/Topstep automatisch abhaken (P&L aus der
    genauen Lesung), Echo mit Hedge seit WS2E nur mit belegtem Fusion-P&L (tt_abhak_werte), sonst bei Finn. Ohne genaue Lesung: lesen_bis schreiben; nach
    Fensterende Tag fertig (keine_lesung)."""
    jetzt = jetzt or datetime.now(timezone.utc)
    rnd = rnd or random.SystemRandom()
    jetzt_iso = jetzt.isoformat().replace("+00:00", "Z")
    tz = _ap_tz(AP_TZ_TAG)
    d = jetzt.astimezone(tz)
    mitternacht = datetime(d.year, d.month, d.day, tzinfo=tz)
    rows = sb_select("trade_plans", {
        "select": "id,user_id,master_account_id,master_firm,master_name,master_symbol,richtung,route,status,auto_plan,auto_bestaetigt_at,"
                  "ended_at,completed_at,planned_for,master_pl,slave_pl,konto_typ,updated_at,mt5_baseline",
        "status": "in.(review,completed)", "ended_at": "gte." + (mitternacht - timedelta(hours=6)).isoformat(),
        "mt5_baseline->kette->>von": "not.is.null"}) or []
    # WS2E-Tag (Gegenprüfung 10.11.2026): fehlte beim Schreiben des Tagesendes noch ein Fusion-P&L (Echo: closed_sum/slave_pl kommen oft erst nach der
    # Nachlesung, oder Finn trägt ihn später ein), zieht der Takt NUR die Fusion-Felder nach, solange der letzte Teil in Überprüfen steht
    for p in rows:
        _te = (((p.get("mt5_baseline") or {}).get("kette") or {}).get("tagesende"))
        if isinstance(_te, dict) and int(_te.get("fusion_offen") or 0) > 0 and p.get("status") == "review":
            try:
                _k = (p.get("mt5_baseline") or {}).get("kette") or {}
                _neu = tt_fusion_nachziehen(_te, _tt_tag_teile(str(_k.get("tag_id") or p["id"]), extra=[p]))
                if _neu:
                    _tt_patch(str(p["id"]), {"tagesende": _neu})
            except Exception as e:
                print(f"[tagesteilung] ⚠️ {str(p.get('id'))[:8]} Fusion nachziehen: {type(e).__name__}: {e}", flush=True)
    rows = [p for p in rows if not (((p.get("mt5_baseline") or {}).get("kette") or {}).get("tagesende"))]
    # FF2 (11.11.2026): Pump-Ketten des Funded-Planers (mt5_baseline.funded_plan) führt fdp_pump_tick — nie hier (sonst schriebe die ausgeschaltete Tagesteilung
    # „aus“ als Tagesende an Trade 1, der PC-Tab hörte auf nachzulesen und Trade 2 entstünde nie)
    rows = [p for p in rows if not (isinstance((p.get("mt5_baseline") or {}).get("funded_plan"), dict))]
    if not rows:
        return {"neu": [], "ende": [], "abgehakt": []}
    nf = sb_select("trade_plans", {"select": "id,status,vor:mt5_baseline->kette->>vor",
                                   "mt5_baseline->kette->>vor": "in.(" + ",".join(str(p["id"]) for p in rows) + ")"}) or []
    nachfolger = {str(x.get("vor")): x for x in nf}
    reg = (sb_select("auto_plan_regeln", {"select": "*", "id": "eq.1"}) or [None])[0]
    if not reg:
        return {"neu": [], "fehler": "auto_plan_regeln fehlt"}
    regeln = reg.get("regeln") or {}
    firmen = regeln.get("firmen") or []
    param = tt_param(regeln)
    aparam = ap_ausgleich_param(regeln)
    zeiten_r = reg.get("zeiten") if isinstance(reg.get("zeiten"), dict) else {}
    sperren = _ap_sperren()
    stand_je, neu, ende, abgehakt = {}, [], [], []
    for p in rows:
        pid = str(p["id"])
        k = (p.get("mt5_baseline") or {}).get("kette") or {}
        route = str(p.get("route") or "")
        tag_id = str(k.get("tag_id") or pid)
        echt = tt_echt(p)
        try:
            if pid in nachfolger:
                # Nachfolger steht: Orbit/Topstep (ohne Hedge) automatisch abhaken; Echo (WS2E 10.11.2026) nur mit belegtem Fusion-P&L (tt_abhak_werte),
                # sonst bleibt der Teil bei Finn
                aw = tt_abhak_werte(p, echt) if p.get("status") == "review" else None
                if aw:
                    upd, fehler = _wd_erledigt_upd(p, aw[0], aw[1], jetzt_iso, _cme_handelstag())
                    if not fehler:
                        upd["pl_quelle"] = aw[2]
                        filt = {"id": f"eq.{pid}", "status": "eq.review"}
                        if p.get("updated_at"):
                            filt["updated_at"] = f"eq.{p['updated_at']}"
                        if sb_update("trade_plans", filt, upd):
                            abgehakt.append(pid)
                continue
            regel = ap_regel_unternehmen(p.get("user_id"), firmen, p.get("master_firm"), streng=False)
            bal_tag0 = _wd_num(k.get("balance_start_tag")) or (echt[0] if echt else None)
            ende_code = ende_text = None
            zs = (p.get("mt5_baseline") or {}).get("zschluss") or {}
            bis = tt_fenster_bis(zeiten_r, route, p.get("ended_at"), tz,
                                 t2_bis=((ap_kette_regel(regel) or {}).get("t2_bis") if (route == "tsv2" and regel) else None))
            ende_ts = _ap_ts(p.get("ended_at"))
            if bis and not k.get("lesen_bis"):
                # Nachzug 10.11.2026 (WS2e/S4): lesen_bis IMMER beim ersten Takt schreiben, auch wenn der Teil schon genau gelesen ist — sonst zeigt der
                # Radar 1–2 min eine Abhak-Zeile, bis Nachfolger/Tagesende stehen (die Topstep-Kette schreibt es ebenso an Trade 1)
                _tt_patch(pid, {"lesen_bis": bis})
            if not echt:
                if bis and jetzt > _ap_ts(bis):
                    ende_code, ende_text = "keine_lesung", TT_ENDE_TXT["keine_lesung"]
                else:
                    continue
            elif k.get("folge_id"):
                # Nachfolger war schon angelegt und ist weg (Finn hat ihn gelöscht, Gegenprüfung 09.11.2026) → Tag fertig, nie still neu anlegen
                ende_code, ende_text = "geloescht", TT_ENDE_TXT["geloescht"]
            elif int(k.get("nr") or 1) >= int(k.get("von") or 1):
                ende_code, ende_text = "alle", TT_ENDE_TXT["alle"]
            elif tt_zschluss_versucht(zs):
                # WS2c (S5 09.11.2026): der Tag zählt über zschluss.status — nach jedem Schluss-Versuch kein Folge-Teil (final.quelle 'close' ist kein Signal).
                # WS2E (10.11.2026): auch schon, wenn der PC-Tab den Versuch begonnen hat (versuche/letzter_versuch_at, VOR dem Klick geschrieben) und status
                # noch fehlt — bei Echo steht die Nachlesung oft vor dem Status (Hedge-Beweis bis 90 s), sonst entstand dazwischen ein Folge-Teil
                ende_code, ende_text = "zschluss", f"{TT_ENDE_TXT['zschluss']} ({zs.get('status') or 'Versuch'})"
            elif not param.get("an"):
                ende_code, ende_text = "aus", TT_ENDE_TXT["aus"]
            elif ap_firma_gesperrt({"user_id": p.get("user_id"), "firm": p.get("master_firm")}, sperren):
                ende_code, ende_text = "gesperrt", AP_GRUND_GESPERRT
            elif not regel:
                ende_code, ende_text = "verlust", "keine Regel für diese Firma"
            elif ende_ts and ende_ts.astimezone(tz).date() != d.date():
                ende_code, ende_text = "fenster", "Teil endete an einem früheren Tag — heute kein Folge-Trade"
            werte = None
            if not ende_code:
                bal_j = echt[1]
                kette_r = ap_kette_regel(regel) if route == "tsv2" else None
                w_h = grund_h = None
                if route != "tsv2":
                    konto = (sb_select("accounts", {"select": "*", "id": f"eq.{p['master_account_id']}"}) or [None])[0]
                    phase = str((konto or {}).get("account_type") or p.get("konto_typ") or "challenge")
                    w_h, grund_h = ap_konto_rechnen(ap_regel_konto(regel, konto, bal_j) if konto else regel, phase, bal_j, {x: rnd.random() for x in ("tp", "sl", "menge", "puffer")},
                                                    ppl=_wd_num(k.get("ppl")), heute_verlust=max(0.0, float(bal_tag0) - bal_j))
                    if w_h and not grund_h and isinstance(k.get("range"), dict) and "rv_anwenden" in globals():
                        # RV1 (11.11.2026): der Tag ist ein Range-Tag → Haupt-Lots/-SL (und TP-Deckel) mit DENSELBEN Faktoren wie Trade 1, sonst wäre ein
                        # späterer Haupt-Teil wieder groß (Master: „Neben-Trades rechnen wie bisher vom veränderten Haupt“)
                        w_h = rv_anwenden(w_h, k["range"], k.get("menge_schritt"), _wd_num(k.get("ppl")))
                werte, g = tt_folge_rechnen(k, bal_tag0, bal_j, regel, param, rnd, w_h=w_h, grund_h=grund_h, kette_r=kette_r)
                if g:
                    ende_code, ende_text = g
            if not ende_code:
                start, richtung, g = _tt_startplatz(p, k, reg, aparam, zeiten_r, firmen, route, stand_je, jetzt, rnd)
                if g:
                    ende_code, ende_text = "fenster", g
            if not ende_code:
                zeile = _tt_zeile(p, k, werte, start, richtung, tag_id, echt, bal_tag0, param, rnd, jetzt)
                if route in AP_CFD_ROUTEN:
                    zeile["route"] = "mt5v2"                     # E3: als Echo V2 rechnen, ap_echo_hedge_anlegen hebt auf Echo + Fusion-Hedge
                    e3 = ap_echo_hedge_anlegen([zeile], {str(p["master_account_id"]): (konto, echt[1])}, regeln)
                    if e3["weg"] or e3.get("echo") != 1:     # E3: nie Echo V2 ohne Hedge als Ersatz (auch nicht, wenn die Zeile kein Kandidat war)
                        ende_code, ende_text = "kein_hedge", f"{TT_ENDE_TXT['kein_hedge']}: " + (e3["weg"][0][1] if e3["weg"] else "Konto nicht lesbar oder kein CFD-Challenge-Typ")
            if ende_code:
                teile = _tt_tag_teile(tag_id, extra=[p])
                blown = False
                if route == "tsv2" and echt and _wd_num(k.get("mll")) is not None and bal_tag0:
                    # 1:1 ap_kette_abhaken (Gegenprüfung 09.11.2026): angefressen Ende ≤ MLL + 50; gesund Ende ≤ MLL UND Tagesverlust über DLL + 50
                    # TL1: MLL = neueste TopstepX-Lesung dieses Teils (tv.mll_start) vor dem Plan-MLL
                    _daily, _e_tag = float(k.get("daily_usd") or 0), echt[1] - float(bal_tag0)
                    _mll_u = (ap_kette_mll_urteil(k, (p.get("mt5_baseline") or {}).get("tv")) if "ap_kette_mll_urteil" in globals()
                              else float(k["mll"]))                                                   # get: ältere Selftest-Lader ohne TL1
                    if ap_kette_angefressen(k):
                        blown = echt[1] <= _mll_u + AP_KETTE_MLL_TOLERANZ
                    else:
                        blown = echt[1] <= _mll_u and (not _daily or _e_tag < -(_daily + 50))
                te = tt_tagesende(teile, ende_code, ende_text, bal_tag0, echt[1] if echt else None, blown, jetzt_iso)
                if echt and route in ("tvv2", "tsv2") and p.get("status") == "review" and p.get("master_pl") is None:
                    halb = {"master_pl": round(echt[1] - echt[0], 2), "pl_quelle": "tv"}   # Richtungs-Riegel frei (prophos_plan_gelesen), Status bleibt
                    if blown:
                        halb["blown"] = True
                    sb_update("trade_plans", {"id": f"eq.{pid}", "status": "eq.review"}, halb)
                if _tt_patch(pid, {"tagesende": te, "grund": f"Tag fertig: {ende_text}", "grund_at": jetzt_iso}):
                    ende.append(pid)
                    print(f"[tagesteilung] {pid[:8]} Tag fertig ({ende_code}): {ende_text}", flush=True)
                continue
            if (sb_select("trade_plans", {"select": "id", "mt5_baseline->kette->>vor": f"eq.{pid}"}) or []):
                continue                                         # inzwischen angelegt (zweiter Container) — nie doppelt
            try:
                ins = sb_insert("trade_plans", zeile)
            except requests.exceptions.HTTPError as e:
                if getattr(e.response, "status_code", 0) == 409:  # Unique-Index trade_plans_kette_vor_uniq: der andere Takt war schneller
                    continue
                raise
            _neu_id = ((ins[0] if isinstance(ins, list) and ins else ins) or {}).get("id") if isinstance(ins, (list, dict)) else None
            txt = (f"Trade {werte['nr']}/{werte['plan']['n']} angelegt: {'Haupt' if werte['rolle'] == 'haupt' else 'Neben'} {richtung} {werte['menge']} · "
                   f"TP {werte['tp']} / SL {werte['sl']} $ · Start {start.astimezone(tz).strftime('%H:%M')} dt")
            _tt_patch(pid, dict({"grund": txt, "grund_at": jetzt_iso}, folge_id=str(_neu_id or "angelegt")))   # folge_id: Löschen beendet den Tag
            neu.append({"vor": pid, "nr": werte["nr"], "start": start.isoformat(), "richtung": richtung, "tp": werte["tp"], "sl": werte["sl"]})
            print(f"[tagesteilung] {pid[:8]} → {txt}", flush=True)
        except Exception as e:
            print(f"[tagesteilung] ⚠️ {pid[:8]}: {type(e).__name__}: {e}", flush=True)
    return {"neu": neu, "ende": ende, "abgehakt": abgehakt}


def tt_fenster_bis(zeiten, route, ended_at, tz, t2_bis=None):
    """REIN RECHNEND (testbar): Fensterende (ISO UTC) des Handelstags, an dem der Teil endete — letzte Startminute der Klasse (ap_klasse_bis),
    Topstep t2_bis (wie ap_kette_lesen_bis)."""
    ende = _ap_ts(ended_at)
    if not ende:
        return None
    tag = ende.astimezone(tz).date()
    m = ap_klasse_bis(dict(zeiten or {}, start_bis=t2_bis) if t2_bis else (zeiten or {}), route, tag)
    bis = datetime(tag.year, tag.month, tag.day, tzinfo=tz) + timedelta(minutes=m)
    return bis.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


def _tt_startplatz(p, k, reg, aparam, zeiten_r, firmen, route, stand_je, jetzt, rnd):
    """Start des nächsten Teils: Lesung + abstand_min (Zufall), erste regelkonforme Minute (ap_nachhol_minute: Richtungsschutz, Firmen-Abstand,
    Abstand je ID, Gegenhedge) bis Fensterende der Klasse (Topstep t2_bis), Richtung = früherer freier Platz von buy/sell (gemischt).
    → (start, richtung, None) | (None, None, grund)."""
    param = tt_param(reg.get("regeln"))
    uk = ap_unternehmen_ids(p.get("user_id"), admin_gruppen_daten())
    if uk not in stand_je:
        stand_je[uk] = _ap_stand_fuer_uid(reg, p.get("user_id"), jetzt)
    stand = stand_je[uk]
    lesung = _ap_ts(ap_blow_lesung_at(p)) or jetzt
    ab = (max(lesung, jetzt - timedelta(minutes=1)) - stand["mitternacht"]).total_seconds() / 60.0 + _ap_spanne(param["abstand_min"], rnd.random())
    zeiten2 = dict(stand.get("zeiten") or zeiten_r or {})
    if route == "tsv2":                                # Topstep: bis t2_bis wie ap_kette_tick (in zeiten.fenster_tz, falls gesetzt)
        zeiten2["start_bis"] = (ap_kette_regel(ap_regel_unternehmen(p.get("user_id"), firmen, p.get("master_firm"), streng=False)) or AP_KETTE_STANDARD)["t2_bis"]
    m_bis = ap_klasse_bis(zeiten2, route)              # ap_nachhol_minute rechnet dasselbe Fensterende aus p.route (CFD bis cfd_bis)
    bis_txt = f"{int(m_bis) // 60:02d}:{int(m_bis) % 60:02d}"
    laufend = [{"user_id": z["user_id"], "firma": z.get("firma_key"), "richtung": z.get("richtung"), "start": None} for z in stand["offen"]]
    fkey = ap_firma_key(stand.get("firmen") or firmen, p.get("master_firm"))
    plaene = _ap_stand_plaene(stand)
    beste = None
    richtungen = ["buy", "sell"]
    rnd.shuffle(richtungen)
    for r in richtungen:
        m, _f = ap_nachhol_minute({"plan_id": "teil-" + str(p["id"]), "user_id": str(p["user_id"]), "firma": fkey, "richtung": r, "route": route}, plaene,
                                  stand["starts_heute"], stand["id_fest"], stand["jetzt_min"], zeiten2, aparam.get("laufzeit_min"),
                                  laufend, rnd=rnd, ab_min=ab)
        if m is not None and (beste is None or m < beste[0]):
            beste = (m, r)
    if beste is None:
        return None, None, f"kein regelkonformer Start mehr bis {bis_txt} dt"
    return stand["mitternacht"] + timedelta(minutes=beste[0]), beste[1], None


def _tt_zeile(p, k, werte, start, richtung, tag_id, echt, bal_tag0, param, rnd, jetzt):
    """Insert-Zeile des nächsten Teils (wie Topstep-Trade 2): Route, Konto, Symbol, Bestätigung von Trade 1; kette mit nr/von/rolle/plan/tag_id/vor."""
    k2 = {x: k.get(x) for x in ("tagesziel", "haupt_menge", "ppl", "menge_schritt", "tag_typ", "mll", "daily_usd", "dll_puffer", "angefressen",
                                "abstand_mll", "tag", "range") if k.get(x) is not None}   # range: RV1-Faktoren des Tages (Folge-Haupt)
    k2.update(nr=werte["nr"], von=werte["plan"]["n"], rolle=werte["rolle"], plan=werte["plan"], tag_id=tag_id, vor=str(p["id"]),
              e_bisher=werte["e_bisher"], balance_start_tag=bal_tag0, balance_vor=echt[1])
    if werte.get("verlust_grenze") is not None:
        k2["verlust_grenze"] = werte["verlust_grenze"]
    for x in ("tp_pkt", "sl_pkt", "lots_roh", "aufgerundet", "tp_teiler", "lots_streu", "lots_gedeckelt"):   # WS3: Lots-Rechnung + Würfe (Teiler, Streuung) als Beleg am Teil
        if werte.get(x) is not None:
            k2[x] = werte[x]
    if werte["rolle"] == "neben":
        k2["lots_bezug"] = param.get("lots_bezug")
    sym = p.get("master_symbol")
    _fm = re.match(r"^[A-Z]+?([FGHJKMNQUVXZ]\d{1,2})$", str(sym or ""))
    if werte.get("symbol") and _fm:
        sym = str(werte["symbol"]) + _fm.group(1)                          # MNQ/NQ + derselbe Frontmonat wie Trade 1 (MNQZ6 → NQZ6, nie NQ6)
    zs, k2["zs_wurf"] = tt_zschluss_wurf(param, rnd)   # WZ1 (10.11.2026): Wurf immer belegen, auch Nieten
    base = {"kette": k2}
    if zs:
        base["zschluss"] = zs
    rolle = "Haupt" if werte["rolle"] == "haupt" else (f"Neben {round(float(werte['plan']['anteile'][werte['nr'] - 1]) * 100)} % · {werte['menge']:g} Lot"
                                                       + (" (Mindest-Lot)" if werte.get("aufgerundet") else ""))
    # WS3: TP/SL der Neben-Teile sind jetzt Cent-Beträge — in der Notiz ganzzahlig (sonst „1.234.56 $“ nach dem Tausender-Tausch, Prüfer WS3)
    sl_txt = f"SL {float(werte['sl']):,.0f} $" if werte.get("sl") else "ohne SL"
    notiz = (f"Auto-Planer · Tag {werte['nr']}/{werte['plan']['n']} · {rolle} · bisher {werte['e_bisher']:+,.0f} $ → TP {float(werte['tp']):,.0f} $ / "
             f"{sl_txt} · Balance {echt[1]:,.0f} (Nachlesung)").replace(",", ".")
    return {"user_id": p["user_id"], "master_account_id": p["master_account_id"], "master_name": p.get("master_name"), "master_firm": p.get("master_firm"),
            "master_contracts": werte["menge"], "master_risk": werte.get("risiko") if werte.get("risiko") is not None else werte["sl"],
            "master_tp": werte["tp"], "master_sl": werte["sl"], "richtung": richtung,
            "route": p.get("route"), "master_symbol": sym, "start_um": start.astimezone(timezone.utc).isoformat(), "status": "planned",
            "priority": "medium", "planned_for": p.get("planned_for"), "auto_plan": True,
            "konto_typ": (p.get("konto_typ") or "challenge") if p.get("route") == "tsv2" else None,   # TL1b: nur Topstep-Kettenteile (tsv2) erben/setzen den konto_typ; CFD-Tagesteilung (WS2) bleibt NULL bis planKontoTypMerken beim Abhaken (Prüfer S2 SOLLTE 1, 12.11.2026: sonst trüge Teil 2 nach Phasenwechsel die alte Phase)
            "auto_bestaetigt_at": jetzt.isoformat() if p.get("auto_bestaetigt_at") else None, "mt5_baseline": base, "notes": notiz}


def _tt_takt():
    """aus ap_loop: höchstens alle TT_TAKT_S tt_tick (Fehler nur loggen)."""
    if time.time() - _tt["letzter"] < TT_TAKT_S:
        return
    _tt["letzter"] = time.time()
    try:
        _tt["letztes"] = tt_tick()
        _tt["fehler"] = ""
    except Exception as e:
        _tt["fehler"] = f"{type(e).__name__}: {e}"
        print(f"[tagesteilung] ⚠️ Takt: {e}", flush=True)


def _ap_bot_tick(d):
    """Ein Takt-Check des Ausgleichs-Bots (aus ap_loop, jede Minute). d = jetzt in deutscher Zeit. Schalter alle 2 min frisch.
    Rund um die Uhr (08.10.2026); ein fälliger Takt ohne geplante/laufende Trades zählt als Lauf, lädt aber keinen Stand."""
    m = d.hour * 60 + d.minute
    if _ap_bot.get("param") is None or time.time() - _ap_bot.get("gelesen", 0) >= 120:
        reg = (sb_select("auto_plan_regeln", {"select": "regeln", "id": "eq.1"}) or [{}])[0]
        _ap_bot["param"], _ap_bot["gelesen"] = ap_ausgleich_param(reg.get("regeln")), time.time()
    param = _ap_bot["param"]
    if not param.get("aktiv"):
        return
    if param.get("waage"):
        # ZWEI WAAGEN (17.10.2026): Sofort-Nachschub je Klasse ersetzt den alten Ausgleich (Tages-Saldo, Drehen am Bot) — kein
        # ap_ausgleichen mehr; der Richtungsschutz am Start (PC-Tab) verschiebt statt zu drehen. Jede Minute, voller Lauf bei Änderung.
        try:
            ap_waage_tick(param)
        except Exception as e:
            _ap_waage["fehler"] = f"{type(e).__name__}: {e}"
            print(f"[waage] ⚠️ {type(e).__name__}: {e}", flush=True)
        return
    tag = d.strftime("%Y-%m-%d")
    letzter = _ap_bot.get("letzter_lauf")
    faellig = not letzter or (datetime.now(timezone.utc) - datetime.fromisoformat(letzter)).total_seconds() >= param["takt_min"] * 60 - 5
    extra = m >= AP_BOT_EXTRA_MIN and _ap_bot.get("extra_tag") != tag
    if not (faellig or extra):
        return
    if extra:
        _ap_bot["extra_tag"] = tag
    _ap_bot["letzter_lauf"] = datetime.now(timezone.utc).isoformat()
    if not _ap_bot_hat_arbeit():
        _ap_bot["letztes"] = {"tag": tag, "umplanungen": 0, "msg": "nichts geplant oder laufend — kein Lauf nötig", "extra": bool(extra)}
        _ap_bot["fehler"] = ""
        return
    try:
        erg = ap_ausgleichen(quelle="bot")
        _ap_bot["letztes"] = {k: erg.get(k) for k in ("tag", "netto_vorher", "netto_nachher", "ausloeser", "msg")}
        _ap_bot["letztes"]["umplanungen"] = len(erg.get("umplanungen") or [])
        _ap_bot["letztes"]["richtungsschutz"] = {k: len((erg.get("richtungsschutz") or {}).get(k) or []) for k in ("gedreht", "markiert")}
        _ap_bot["letztes"]["extra"] = bool(extra)
        _ap_bot["fehler"] = ""
    except Exception as e:
        _ap_bot["fehler"] = f"{type(e).__name__}: {e}"
        print(f"[auto-plan] ⚠️ Ausgleich: {e}", flush=True)


def _ap_zugang(admin_reiter=False):
    """Gate wie /admin/auto-plan: Admin oder eine ID, die selbst im Auto-Planer ist (nur lesen, nur eigene Zeilen).
    admin_reiter=True (nur Lese-Routen, 08.10.2026): auch jeder andere Login mit sicht=admin, der nicht „nur eigene" ist (ap_admin_reiter_ok)
    — seit den Admin-Gruppen (08.10.2026) dazu ein Verwalter (sieht dort mit sicht=admin seine Gruppe; seit 30.10.2026 ohne sicht=admin
    nur die eigene ID statt 403).
    → (admin, uid, reg, None) oder (…, Fehler-Antwort)."""
    mail, err = _planer_admin_auth()
    uid = request.environ.get("prophos.admin_uid")
    admin = err is None
    if not admin:
        if err[1] != 403:
            return False, None, None, err
        uid, err2 = _wd_login()
        if err2:
            return False, None, None, err2
    reg = (sb_select("auto_plan_regeln", {"select": "*", "id": "eq.1"}) or [None])[0]
    if not reg:
        return admin, uid, None, (jsonify({"ok": False, "msg": "auto_plan_regeln fehlt"}), 503)
    if not admin and str(uid) not in [str(u) for u in (reg.get("user_ids") or [])]:
        ok = False
        # VERWALTER OHNE 403 (30.10.2026, Finn als Emin: „Delta-Daten nicht geladen (HTTP 403)"): ein Verwalter liest auch OHNE ?sicht=admin
        # (Abruf beim Login, Planer-Modus vor der Verwalter-Erkennung) — dann nur die eigene ID (_ap_sicht_aus_anfrage), mit sicht=admin seine
        # Gruppe. Jeder andere Login außerhalb des Planers bleibt gesperrt; Eingriffe prüfen ihre Rechte danach selbst (darf/gruppe_e).
        if admin_reiter:
            nur, gruppe = _ap_gruppe_lesen(uid)   # nicht lesbar → (True, None) → kein Verwalter, gesperrt
            # SICHT JE GRUPPE (30.10.2026): ein Mitglied einer Verwalter-Gruppe liest wie der Verwalter (Gruppe mit sicht=admin) —
            # Eingriffe prüfen danach weiter selbst (ap_eingriff_sicht: Mitglied = nur eigene Pläne)
            ok = ap_admin_reiter_ok(False, False, nur, AP_SICHT_ADMIN, verwalter=bool(gruppe) or bool(nur and ap_lese_gruppe(uid)))
        if not ok:
            return admin, uid, reg, (jsonify({"ok": False, "msg": "Diese ID ist nicht im Auto-Planer"}), 403)
    return admin, uid, reg, None


def _konto_dd_regeln(uid, typ):
    """(firmen, fcp_firmen) für konto_dd_aus_regel: auto_plan_regeln.firmen nach dem Unternehmen der ID (UNT3), bei Funded CFD dazu funded_cfd_plan_regeln.firmen
    (UNT4, fd_unt_reg). Wirft bei Lesefehlern — die Aufrufer fangen das ab und lassen das Feld dann leer."""
    reg = (sb_select("auto_plan_regeln", {"select": "regeln", "id": "eq.1"}) or [{}])[0]
    fs = ap_unt_firmen(uid, (reg.get("regeln") or {}).get("firmen") or [], streng=False)
    fcp = None
    if typ == "funded_cfd":
        fcp = (fd_unt_reg((sb_select("funded_cfd_plan_regeln", {"select": "firmen", "id": "eq.1"}) or [{}])[0], "cfd", uid) or {}).get("firmen")
    return fs, fcp


@app.route("/konto/dd-vorschlag", methods=["GET", "OPTIONS"])
def konto_dd_vorschlag():
    """GET ?firma=&groesse=&typ= → {ok, dd} aus dem Firmen-Kernwert (konto_dd_aus_regel). auto_plan_regeln liest nur der Server, jeder Login darf diese eine Zahl."""
    if request.method == "OPTIONS":
        return "", 200
    _uid, err = _wd_login()
    if err:
        return err
    try:
        # UNT3: Max DD nach der Regel des Unternehmens der ID, für die das Konto angelegt wird (?user_id=, sonst der Login); ?typ= (DD1): Funded CFD erst die Funded-CFD-Regel
        typ = str(request.args.get("typ") or "").strip() or None
        fs, fcp = _konto_dd_regeln(request.args.get("user_id") or _uid, typ)
        dd = konto_dd_aus_regel(fs, request.args.get("firma"), _wd_num(request.args.get("groesse")), typ, fcp)
        return jsonify({"ok": True, "dd": dd})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"{type(e).__name__}: {e}"}), 502


@app.route("/admin/auto-plan/delta", methods=["GET", "OPTIONS"])
def admin_auto_plan_delta():
    """GET → Delta-Stand jetzt (Vertrag §4): netto/brutto, offen[], geplant[], verlauf[], umplanungen[] (heute), bot{}."""
    if request.method == "OPTIONS":
        return "", 200
    admin, uid, reg, err = _ap_zugang(admin_reiter=True)
    if err:
        return err
    try:
        # 07.10.2026 TRADE-PLANER-ALLE-IDS: ?sicht=alle → alle IDs (außer „nur eigene"), sonst wie bisher Admin alle / eigene ID
        sicht_d = _ap_sicht_aus_anfrage(admin, uid)
        if isinstance(sicht_d, frozenset) and sicht_d and sicht_d <= _admin_verwalter_gruppen_ids(admin_gruppen_daten()):
            # GRUPPEN-SICHT (30.10.2026, Emin gleich wie Finn): Verwalter mit sicht=admin bzw. Finns Gruppen-Chip — Stand nur aus genau
            # diesen IDs. Vorher lud der Stand mit der Standard-Ausblendung (ADMIN_EXCLUDE), dem Verwalter fehlten seine eigenen Pläne.
            namen, _aus = _ap_namen()
            stand = _ap_stand_laden(reg, namen=namen, ausgeblendet=ap_gruppe_ausgeblendet(namen, sicht_d), eigene=sicht_d)
            _hb_u = sicht_d
        elif isinstance(sicht_d, str) and ap_unternehmen_ids(sicht_d, admin_gruppen_daten()):
            # UNT2 (Prüfung): eigene ID eines Gruppen-Mitglieds (PC-Tab ohne sicht, rkSaldo/Delta-Monitor) → Stand seines Unternehmens; der HT-Stand
            # kennt seine Pläne nicht mehr (vorher lieferte der eingeschränkte Login einen Stand über alle IDs)
            _eig = ap_unternehmen_ids(sicht_d, admin_gruppen_daten())
            namen, _aus = _ap_namen()
            stand = _ap_stand_laden(reg, namen=namen, ausgeblendet=ap_gruppe_ausgeblendet(namen, _eig), eigene=_eig)
            _hb_u = _eig
        else:
            stand = _ap_stand_laden(reg)
            _hb_u = "ht"
        if _hb_u != "ht":
            # SA3 (a) (S6/MO1b, NK1 05.11.2026): der Stand eines Unternehmens wiegt mit SEINER Waage-Liste und SEINEN Modellen — wie ap_planen, der
            # Waage-Takt und die Startprüfung (ap_waage_param_gruppe); vorher wog die Delta-Anzeige die Gruppe mit der HT-Liste waage_ohne. Fehler → HT-Liste
            try:
                _fm_g = next((v for u, v in ap_gruppen_modelle().items() if u in {str(x) for x in _hb_u}), {})
                stand["param"] = ap_waage_param_gruppe(stand.get("param"), (reg.get("regeln") or {}).get("ausgleich"), (reg.get("regeln") or {}).get("firmen"), _fm_g)
            except Exception as e:
                print(f"[auto-plan] ⚠️ Delta-Waage je Unternehmen: {type(e).__name__}: {e} — HT-Liste", flush=True)
        # HEUTE BEENDET (Finn 08.10.2026, ID-Detail + Kachel „Heute"): eigener try — fällt es aus, bleibt das übrige Delta unberührt
        try:   # UNT2: aus demselben Unternehmen wie der Stand
            stand["heute_beendet"], stand["heute_ab"] = ap_heute_beendet_gemerkt((reg.get("regeln") or {}).get("firmen") or [], unternehmen=_hb_u)
        except Exception as e:
            stand["heute_beendet_fehler"] = f"{type(e).__name__}: {e}"
            print(f"[auto-plan] ⚠️ heute beendet: {stand['heute_beendet_fehler']}", flush=True)
        ap_tages_saldo(stand)                     # TAGES-SALDO (.1552): netto_eur/Band für PC-Tab und Kachel wiegen den ganzen Tag
        stand["fremd"] = fp_delta_zeilen()        # FREMD-POSITIONEN (08.10.2026): Hand-Positionen ohne Plan, „Braucht dich"
        nur, gruppe = _ap_gruppe_lesen(uid)
        # SUMMEN NUR ÜBER DIE SICHT (Master 08.10.2026, Nachbesserung B: „HT-Gesamtsummen sind HT-Daten"): ein eingeschränkter Login
        # (Verwalter, Mitglied) und Finns Gruppenfilter bekommen Netto/Band/Long/Short/Verlauf/Szenario nur aus ihren Zeilen; eine
        # normale HT-ID auf der Planer-Seite sieht die Summen wie bisher über alle IDs (Neutralität übergreifend)
        if sicht_d is not None and ((not admin and nur) or not isinstance(sicht_d, str)):
            stand = ap_stand_sicht(stand, sicht_d)
        antwort = ap_delta_antwort(stand, sicht_d, pc_lebt=_ap_pc_lebt_gecacht())
        try:   # LOTS-DECKEL (02.11.2026): eigener try, fällt es aus, bleibt das übrige Delta unberührt
            antwort["lots_stops"] = ap_lots_stops(sicht_d, _ap_namen()[1])
        except Exception as e:
            print(f"[lots-deckel] ⚠️ Stops: {type(e).__name__}: {e}", flush=True)
        # ZWEI WAAGEN (17.10.2026): Futures/CFD je laufend + Start ≤ 2 min — PC-Tab (Start-Prüfung) und Planer-Kopf lesen es
        try:
            antwort["klassen"] = {k: {f: v.get(f) for f in ("long_eur", "short_eur", "n_long", "n_short", "delta_eur", "passt", "grund", "leicht")}
                                  for k, v in ap_klassen_waage(stand, pc_lebt=_ap_pc_lebt_gecacht()).items()}
            antwort["waage_an"] = bool(stand["param"].get("waage"))
            antwort["waage_bot"] = {k: _ap_waage.get(k) for k in ("letzter_lauf", "letztes", "fehler")}
        except Exception as e:
            antwort["klassen_fehler"] = f"{type(e).__name__}: {e}"
        try:
            antwort = ap_delta_ohne_archiv(antwort, _ap_archiviert_gemerkt())   # archivierte Konten (09.10.2026), eigener try
        except Exception as e:
            print(f"[auto-plan] ⚠️ Delta-Archiv: {type(e).__name__}: {e}", flush=True)
        # Kachel „Heute" nur HT (29.10.2026, _ap_ht_standard_aus): Netto/Band/Waage bleiben wie bisher, nur die Heute-Liste ohne Verwalter-Gruppen
        if isinstance(antwort.get("heute_beendet"), list):
            try:
                weg = _ap_ht_standard_aus(sicht_d)
                if weg:
                    antwort["heute_beendet"] = [z for z in antwort["heute_beendet"] if str(z.get("user_id")) not in weg]
            except Exception as e:
                antwort["heute_beendet"], antwort["heute_beendet_fehler"] = None, f"Gruppen nicht lesbar: {type(e).__name__}"
        antwort.setdefault("sicht", "alle")
        if not admin and nur:   # Bot-Zustand ist HT-weit (letzter Lauf, Zähler) — nur Schalter-Stand
            antwort["bot"] = {k: (antwort.get("bot") or {}).get(k) for k in ("aktiv", "auto_start", "takt_min", "zielband_pct")}
        # BESTÄTIGEN FÜR ALLE (07.10.2026): alle = darf dieser Login fremde Vorschläge bestätigen/zurücknehmen/löschen (ap_eingriff_sicht;
        # Nicht-Admin ist hier immer im Planer, _ap_zugang). admin_zugang nicht lesbar → vorsichtshalber false.
        # Admin-Gruppen (08.10.2026): ein Verwalter bekommt seine Gruppe — er darf alle Zeilen, die er sieht (alle true, Backend prüft je Plan)
        e_sicht = ap_eingriff_sicht(admin, uid, True, nur, _ap_sicht_param(), gruppe)
        return jsonify(dict(antwort, admin=admin, alle=e_sicht is None or not isinstance(e_sicht, str)))
    except Exception as e:
        return jsonify({"ok": False, "admin": admin, "msg": f"{type(e).__name__}: {e}"}), 502


@app.route("/admin/auto-plan/ausgleichen", methods=["POST", "OPTIONS"])
def admin_auto_plan_ausgleichen():
    """POST {trocken, seed?} → Ausgleichs-Bot sofort einmal (auch wenn ausgleich.aktiv aus ist). Nur Admin."""
    if request.method == "OPTIONS":
        return "", 200
    _gs = _planer_schreib_gate()              # PLANER-RECHTE HT (30.10.2026)
    if _gs is not None:
        return _gs
    admin, uid, reg, err = _ap_zugang()
    if err:
        return err
    if not admin:
        return jsonify({"ok": False, "msg": "Nur für Admins — Eingriffe macht nur Finn"}), 403
    body = request.get_json(silent=True) or {}
    seed = body.get("seed")
    if seed not in (None, "") and not re.match(r"^\d{1,10}$", str(seed)):
        return jsonify({"ok": False, "msg": "seed = Ganzzahl"}), 400
    try:
        return jsonify(dict(ap_ausgleichen(trocken=bool(body.get("trocken")), quelle="bot", seed=seed), admin=True))
    except Exception as e:
        return jsonify({"ok": False, "admin": True, "msg": f"{type(e).__name__}: {e}"}), 502


@app.route("/admin/auto-plan/ids", methods=["GET", "POST", "OPTIONS"])
def admin_auto_plan_ids():
    """ADMIN-REITER „TRADE-PLANER" (Finn 08.10.2026: „unter Admin einen Tab, wo ich alle IDs zum Trade-Planen zufügen kann und
    einen Überblick über alle IDs sehe, die ich gleichzeitig managen kann"). Nur Admin (ADMIN_EMAILS).
    GET → ids[]: jede ID mit planbaren Konten (ap_ids_laden) ∪ auto_plan_regeln.user_ids — {user_id, name, drin, konten,
    geplant, ausgelassen} (Konten = challenge/phase1/phase2 nicht archiviert; geplant/ausgelassen aus dem letzten Lauf), aktiv, tag.
    POST {user_id, drin} → ID in auto_plan_regeln.user_ids rein/raus (nur dieses Feld, Regeln/Zeiten unberührt)."""
    if request.method == "OPTIONS":
        return "", 200
    if request.method == "POST":
        _gs = _planer_schreib_gate()          # PLANER-RECHTE HT (30.10.2026)
        if _gs is not None:
            return _gs
    # Gate wie die anderen Admin-Reiter (Finn 08.10.2026, als „Finn + Pascal" eingeloggt: „ich komm nicht rein — mach, dass man aus
    # jedem Tab reinkommt, wenn der Admin-Code stimmt"): Admin (ADMIN_EMAILS) ODER jeder eingeloggte Login, der nicht admin_zugang
    # „nur eigene" ist — den Admin-Code prüft die Oberfläche beim Entsperren, wie bei Übersicht/Auftrag/Winning Days.
    # ADMIN-GRUPPEN (08.10.2026): ein Verwalter liest hier seine Gruppe (gruppe = Menge), schreibt aber NICHT — user_ids gehört zu
    # auto_plan_regeln (HT-weit, der Planer gleicht alle IDs gemeinsam aus). Finn filtert mit ?gruppe= (lese_sicht).
    mail, err = _planer_admin_auth()
    gruppe, lese_sicht = None, None
    if err:
        if err[1] != 403:
            return err
        uid, err2 = _wd_login()
        if err2:
            return err2
        nur, gruppe = _ap_gruppe_lesen(uid)
        if gruppe and not _admin_ansicht():
            gruppe = None                     # Gruppe nur aus der Admin-Ansicht (?ansicht=admin, Nachbesserung A)
        if nur and not gruppe and request.method == "GET" and _admin_ansicht():
            # SICHT JE GRUPPE (Finn 30.10.2026 05:08: „Eine ID von Emin soll … im Planer genau das Gleiche"): ein Mitglied einer Gruppe MIT
            # Verwalter liest im Planer die ganze Gruppe — nur GET, POST (Planer-Haken) bleibt unten gesperrt
            gruppe = ap_lese_gruppe(uid)
        if nur and not gruppe:
            return jsonify({"ok": False, "msg": "Diese ID sieht im Admin nur sich selbst"}), 403
        if gruppe and request.method == "POST":
            return jsonify({"ok": False, "msg": "Planer-Haken sind HT-weit (auto_plan_regeln) — nur Hermann Technologies"}), 403
        mail = f"uid {str(uid)[:8]}"
        lese_sicht = gruppe if gruppe else getattr(g, "admin_filter", None)
    else:
        try:
            lese_sicht = _admin_filter_aus_anfrage()
        except Exception as e:
            print(f"[auto-plan] ⚠️ ids: Gruppenfilter nicht lesbar ({type(e).__name__}: {e}) — ungefiltert", flush=True)
    reg = (sb_select("auto_plan_regeln", {"select": "aktiv,user_ids,firmen:regeln->firmen", "id": "eq.1"}) or [None])[0]   # firmen für boden (08.10.2026)
    if not reg:
        return jsonify({"ok": False, "msg": "auto_plan_regeln fehlt"}), 503
    drin = [str(u) for u in (reg.get("user_ids") or [])]
    # OPTION A (Finn 08.10.2026): Admin-Reiter nur für Admin oder IDs im Trade-Planer — vorher reichte jeder Login ohne „nur eigene",
    # und per POST konnte sich jeder selbst in user_ids eintragen (= sich selbst Admin-Rechte geben). Verwalter: seine Gruppe (oben).
    if err and not gruppe and str(uid) not in drin:
        return jsonify({"ok": False, "msg": AP_NUR_PLANER_TXT}), 403
    if request.method == "POST":
        body = request.get_json(silent=True) or {}
        uid = str(body.get("user_id") or "").strip()
        if not re.fullmatch(r"[0-9a-f-]{36}", uid):
            return jsonify({"ok": False, "msg": "user_id fehlt"}), 400
        soll = bool(body.get("drin"))
        try:
            _ht_id = ap_unternehmen_filter(None, admin_gruppen_daten())(uid)
        except Exception as e:
            return jsonify({"ok": False, "msg": f"Gruppen nicht lesbar ({type(e).__name__}) — nichts geändert"}), 502
        if soll and not _ht_id:   # UNT2 (G2 A4): Gruppen-IDs plant ihr eigener Lauf
            return jsonify({"ok": False, "msg": "Diese ID gehört nicht zu Hermann Technologies (Verwalter-Gruppe oder noch ohne Unternehmen) — erst im Admin zuordnen"}), 409
        neu = [u for u in drin if u != uid] + ([uid] if soll else [])
        sb_update("auto_plan_regeln", {"id": "eq.1"}, {"user_ids": neu})
        _ap_planer_cache_leeren()          # neue Planer-ID gilt sofort im Admin-Reiter (Cache _ap_im_planer)
        drin = neu
        print(f"[auto-plan] ID {uid[:8]} {'rein' if soll else 'raus'} (Admin {mail}) — {len(neu)} IDs im Planer", flush=True)
    namen, aus = _ap_namen()
    archiv = _ap_archiviert()
    konten = {}
    for r in _sb_all("accounts", {"select": "id,user_id", "account_type": "in.(" + ",".join(AP_TYPEN) + ")"}):
        if str(r.get("id")) not in archiv:
            konten[str(r.get("user_id"))] = konten.get(str(r.get("user_id")), 0) + 1
    rows = sb_select("auto_plan_lauf", dict(AP_LAUF_NUR_CHALLENGE, select="tag,ergebnis", order="at.desc", limit="1"))
    erg, tag = ((rows[0].get("ergebnis") or {}), rows[0].get("tag")) if rows else ({}, None)
    # Zahl „ausgelassen" wie die Zeilen in Braucht dich (Master 09.10.2026, Folge zu .1402): ohne seit dem Lauf archivierte Konten und ohne
    # Konten, die für den Lauftag inzwischen einen Plan haben — sonst zeigte die ID-Leiste eine Zahl, zu der unten keine Zeile steht
    try:
        erg = ap_ohne_archiv(erg, archiv)
    except Exception as e:
        print(f"[auto-plan] ⚠️ ids: Archiv-Filter: {type(e).__name__}: {e}", flush=True)
    if isinstance(erg, dict) and erg and not erg.get("tag") and tag:
        erg = dict(erg, tag=tag)
    gepl, ausg = ap_ids_zaehlen(ap_aus_ohne_plan_laden(erg) or {})
    # Verwalter: seine Gruppe, auch wenn der Server sie für HT ausblendet (ADMIN_EXCLUDE); Finn mit ?gruppe=: nur diese Gruppe — bei einer
    # Verwalter-Gruppe ebenfalls ohne die Ausblendung (Master 08.10.2026 C), bei HT mit
    ohne_aus = bool(gruppe) or (lese_sicht is not None and not _admin_filter_ist_ht())
    basis = set(ap_ids_laden(() if ohne_aus else aus)) | set(drin)
    if lese_sicht is not None:
        basis &= set(lese_sicht)
    alle = sorted(basis, key=lambda u: namen.get(u, u).lower())
    # GRUPPEN-PLANER (13.10.2026): IDs einer Gruppe mit eigenem Planer (auto_plan_gruppe) zählen in der ID-Leiste wie „im Planer" —
    # drin bleibt Finns user_ids (der Haken schreibt nur dorthin); Lesefehler → kein Flag
    gp_ids = set()
    try:
        gdat = admin_gruppen_daten()
        gp_gr = {str(z.get("gruppe_id")) for z in sb_select("auto_plan_gruppe", {"select": "gruppe_id", "aktiv": "is.true"}) or []}
        gp_ids = {str(m.get("user_id")) for m in gdat.get("mitglieder") or () if str(m.get("gruppe_id")) in gp_gr}
    except Exception as e:
        print(f"[auto-plan] ⚠️ ids: Gruppen-Planer nicht lesbar ({type(e).__name__})", flush=True)
    ids = [{"user_id": u, "name": namen.get(u, u[:8]), "drin": u in drin, "konten": konten.get(u, 0), "gruppen_planer": u in gp_ids,
            "geplant": gepl.get(u, 0), "ausgelassen": ausg.get(u, 0)} for u in alle]
    # LETZTE 7 TAGE je ID (Master/Slave 8, 08.10.2026, ID-Detail-Karte): bestanden/geblasen/beendet — jede Quelle einzeln, Fehler → null
    sieben, sieben_ab = _ap_sieben_tage_laden()
    for e in ids:
        e.update(sieben.get(e["user_id"]) or {k: (0 if sieben.get("_ok", {}).get(k) else None) for k in ("bestanden_7t", "geblasen_7t", "beendet_7t")})
    # ZU BESTÄTIGEN (Finn 08.10.2026): alle unbestätigten Auto-Vorschläge aller IDs, egal welcher Tag (heute/morgen) — das Delta kennt
    # nur den heutigen Tag, die Nacht plant aber schon den nächsten. Bestätigt wird über /admin/auto-plan/bestaetigen (alle IDs).
    # WARTET AUF START (12.10.2026, Finn-Screenshot .1446 um 01:54 Dubai: 45 Pläne bestätigt, Block zeigte „Wartet auf Start · 0"): das
    # Frontend wartet seit 08.10. auf bestaetigt[] (apIdsLaden) — ohne die Liste kannte es bestätigte Pläne nur aus dem Delta (heute deutscher
    # Zeit) und dem lokalen Merker, der beim Neuladen weg ist. Nach Mitternacht Dubai starten alle Pläne „morgen" → Block leer. Jetzt dieselbe
    # Abfrage für bestätigte, noch nicht gestartete Auto-Pläne, gleiche Zeilenform; bei Fehler null (Frontend behält dann den alten Stand).
    offen, bestaetigt = [], []
    try:
        seit = (datetime.now(timezone.utc) - timedelta(hours=12)).isoformat()
        pl = _sb_all("trade_plans", {"select": "id,user_id,master_account_id,master_firm,master_name,richtung,route,start_um,master_contracts,master_tp,master_sl,notes,auto_bestaetigt_at,"
                                               "hedge_freigabe_at,hart:mt5_baseline->>hedge_art,hvs:mt5_baseline->hedge_vorschau,orbit_v3,hedge_eur",
                                     "status": "eq.planned", "auto_plan": "eq.true", "start_um_gestartet_at": "is.null", "start_um": "gte." + seit,
                                     "order": "start_um.asc"})
        pl = [p for p in pl if (str(p.get("user_id")) in gruppe if gruppe
                                else (ohne_aus or str(p.get("user_id")) not in aus) and admin_in_sicht(p.get("user_id"), lese_sicht))
              and p.get("master_account_id") and str(p.get("master_account_id")) not in archiv]   # archiviert / Konto gelöscht (Waise): kein Vorschlag mehr (09.10.2026)
        acc_ids = sorted({str(p.get("master_account_id")) for p in pl if p.get("master_account_id")})
        accs, letzt_je = {}, {}
        for j in range(0, len(acc_ids), 150):
            for a in _ap_konten_laden({"id": "in.(" + ",".join(acc_ids[j:j + 150]) + ")"}):   # Felder für acc_balance_wahl, Rückfall ohne neue Spalten
                accs[str(a.get("id"))] = a
            # BALANCE LIVE (08.10.2026): Ende des letzten beendeten Trades je Konto — „Zu bestätigen" zeigt nicht-live Pläne nicht
            letzt_je.update(ap_letzt_je_konto(_sb_all("trade_plans", {"select": "master_account_id,status,ended_at,completed_at",
                                                                       "status": "in.(review,completed)",
                                                                       "master_account_id": "in.(" + ",".join(acc_ids[j:j + 150]) + ")"})))
        try:
            echo_bal, dup_bal = _ap_balance_karten()
        except Exception:
            echo_bal, dup_bal = {}, {}
        peaks = _ap_peaks(list(accs.values()))   # Höchststand für den geschätzten Boden (08.10.2026)
        for p in pl:
            a = accs.get(str(p.get("master_account_id")))
            (bestaetigt if p.get("auto_bestaetigt_at") else offen).append({"plan_id": str(p.get("id")), "user_id": str(p.get("user_id")), "user": namen.get(str(p.get("user_id")), str(p.get("user_id"))[:8]),
                          "firma": (a or {}).get("firm") or p.get("master_firm"), "konto": (a or {}).get("name") or p.get("master_name"),
                          "ende4": _ap_ende4(a), "typ": (a or {}).get("account_type"), "richtung": p.get("richtung"), "route": p.get("route"),
                          "start_um": p.get("start_um"), "menge": _wd_num(p.get("master_contracts")),
                          "tp": _wd_num(p.get("master_tp")), "sl": _wd_num(p.get("master_sl")),
                          # Stufe aus den Planer-Notes („Auto-Planer · Etappe · Rest …") — Admin-Reiter Spalte „Stufe" (08.10.2026)
                          "notes": _ap_notes_kurz(p.get("notes")), "stufe": (re.search(r"Auto-Planer · ([^·]+)", str(p.get("notes") or "")) or [None, None])[1],
                          # Balance, mit der der Planer rechnet (Slave 7, 08.10.2026) — wie delta.geplant[].balance
                          "balance": (lambda b: round(float(b), 2) if b is not None else None)(acc_balance_wahl(a, echo_bal, dup_bal)[0] if a else None),
                          "konto_id": str(p.get("master_account_id") or "") or None,
                          # EIN BESTÄTIGEN JE TRADE (Finn 30.10.2026): Hedge-Pläne (apex / tradeify_final) zeigen ihre Vorschau in derselben Zeile
                          **ap_ids_hedge_felder(p),
                          # WEG-CHIP (04.11.2026, Finn: „warum sind alle Modelle mit Orbit V2?"): Orbit mit Hedge vs. Orbit V2 ohne — wie Radar/Trades (wegLabel)
                          "orbit_v3": bool(p.get("orbit_v3")), "hedge_eur": _wd_num(p.get("hedge_eur")),
                          "balance_live": ap_balance_live(acc_balance_wahl(a, echo_bal, dup_bal)[3] if a else None,
                                                          letzt_je.get(str(p.get("master_account_id") or ""))),
                          # BODEN (08.10.2026, Balance-Balken Slave 4) — wie delta.geplant[]
                          **ap_boden_sicher(ap_unt_firmen((a or {}).get("user_id"), reg.get("firmen"), streng=False), a, acc_balance_wahl(a, echo_bal, dup_bal)[0], peaks)})   # UNT3
    except Exception as e:
        print(f"[auto-plan] ⚠️ ids/offen: {type(e).__name__}: {e}", flush=True)
        bestaetigt = None
    return jsonify({"ok": True, "ids": ids, "aktiv": bool(reg.get("aktiv")), "tag": tag, "offen": offen, "bestaetigt": bestaetigt, "sieben_tage_ab": sieben_ab})


