                ap_gruppe_regel_geaendert(gid, _j)   # NP1: Gruppen-Nachplanen rechnet „keine Regel"-Konten neu
                print(f"[gruppen-plan] {gid[:8]} Modell {body.get('firma')} → {body.get('modell')} ({'Admin' if admin else 'uid ' + str(uid)[:8]})", flush=True)
