def _ap_zahl(x):
    """Zahl aus dem Body (int/float/Zahl-String mit Komma) oder None; bool zählt nicht."""
    if isinstance(x, bool) or x is None:
        return None
    try:
        f = float(str(x).replace(",", ".")) if isinstance(x, str) else float(x)
    except (TypeError, ValueError):
        return None
    return f if f == f and f not in (float("inf"), float("-inf")) else None


AP_START_HAND_VORLAUF_MIN = 2       # Startzeit von Hand frühestens jetzt + 2 min (Finn 08.10.2026: Pläne selbst vorziehen)


def ap_start_zeit(roh, jetzt, tz=None):
    """REIN RECHNEND: start_um aus dem Body → (datetime UTC, None) oder (None, Klartext). „HH:MM" = Dubai, HEUTE (kein Sprung auf
    morgen — liegt die Zeit vorbei, ist das ein Fehler); sonst ISO."""
    t = str(roh or "").strip()
    if not t:
        return None, "start_um fehlt — HH:MM (Dubai) oder ISO"
    m = re.fullmatch(r"(\d{1,2}):(\d{2})", t)
    if m:
        h, mi = int(m.group(1)), int(m.group(2))
        if h > 23 or mi > 59:
            return None, "start_um = HH:MM (00:00–23:59, Dubai)"
        z = jetzt.astimezone(_ap_tz(tz or AP_7T_TZ))
        d = datetime(z.year, z.month, z.day, h, mi, tzinfo=z.tzinfo)
        if d <= jetzt:
            return None, f"Startzeit {t} (Dubai) liegt schon vorbei"
        return d.astimezone(timezone.utc), None
    d = _ap_ts(t)
    if d is None:
        return None, "start_um = HH:MM (Dubai) oder ISO"
    return d.astimezone(timezone.utc), None


def ap_start_hand_pruefen(plan_id, neu_min, plaene, starts, id_fest, jetzt_min, laufzeit_min=None, abstand_firma=None, zeit=None):
    """REIN RECHNEND (Startzeit per Klick, Finn 08.10.2026: Pläne selbst vorziehen; Vertrag Master/Slave 5): darf Plan plan_id auf
    Minute neu_min (ab 00:00 deutscher Zeit, wie der Stand) starten? plaene = _ap_stand_plaene (heute geplant, alle IDs), starts =
    stand.starts_heute [{user_id, firma, start, richtung}], id_fest = ap_id_fest. Regeln: frühestens jetzt + AP_START_HAND_VORLAUF_MIN,
    nur innerhalb des Planer-Tages; RICHTUNGSSCHUTZ — keine Gegenrichtung derselben ID × Firma, die läuft (id_fest „läuft gerade") oder
    als Plan/Start näher als laufzeit_min (Standard AP_VERTEIL_GEGEN_MIN) liegt; FIRMEN-ABSTAND — kein anderer Plan/Start derselben Firma
    (seit 08.10.2026 jede ID, auch die eigene) näher als abstand_firma (zeiten.abstand_firma_min, sonst AP_FIRMA_ABSTAND_MIN, wie da88e68).
    zeit = Minute → Text für die Meldung (Route: Dubai-Uhrzeit), sonst deutsche Zeit.
    → (None, None) oder (Klartext, vorschlag_min | None) mit der nächsten freien Minute ab dem Wunsch."""
    zt = zeit or (lambda m: _ap_hhmm_txt(m) + " dt")
    p = plan_id if isinstance(plan_id, dict) else next((x for x in plaene or () if str(x.get("plan_id")) == str(plan_id)), None)
    if not p:
        return "Startzeit ändern geht nur für geplante Pläne", None
    plan_id = p.get("plan_id")
    u, f, r = str(p["user_id"]), p["firma"], p.get("richtung")
    lz = float(laufzeit_min or AP_VERTEIL_GEGEN_MIN)
    gap = float(abstand_firma or AP_FIRMA_ABSTAND_MIN)
    ab = float(jetzt_min) + AP_START_HAND_VORLAUF_MIN
    gegen = {"buy": "sell", "sell": "buy"}.get(r)
    fest = (id_fest or {}).get(f"{u}|{f}") or {}
    anders = [(float(x["start_min"]), x) for x in plaene or () if str(x.get("plan_id")) != str(plan_id) and x.get("start_min") is not None]
    st = [(float(x["start"]), x) for x in starts or () if x.get("start") is not None]

    def grund(m):
        if m < ab:
            return f"Startzeit zu früh — frühestens {AP_START_HAND_VORLAUF_MIN} min ab jetzt"
        if m >= 24 * 60:
            return "Startzeit liegt nach dem Planer-Tag (00:00 deutsche Zeit)"
        # ein laufender Gegen-Trade blockiert nur innerhalb seiner Laufzeit ab jetzt (Start morgen früh: nicht mehr)
        if gegen and fest.get("richtung") == gegen and fest.get("durch") == "läuft gerade" and str(fest.get("plan_id")) != str(plan_id) \
                and m - float(jetzt_min) < AP_RICHTUNG_LAUF_FEST_MIN:     # 09.10.2026: wie der Planer (vorher laufzeit_min 180)
            return f"Richtungsschutz: bei dieser ID und Firma läuft gerade {AP_RICHTUNG_TXT[gegen]}"
        # geplante Pläne derselben ID × Firma sperren seit 09.10.2026 nicht mehr (Finn: Richtung je Trade frei, nur nie gleichzeitig) —
        # nur heute gestartete, solange sie laufen könnten
        for s, x in st:
            if str(x.get("user_id")) == u and x.get("firma") == f and gegen and x.get("richtung") == gegen and _ap_gegen_eigen(m, s, True):
                return f"Richtungsschutz: {AP_RICHTUNG_TXT[gegen]} derselben ID und Firma seit {zt(s)} — kann noch laufen"
        for s, x in anders + st:
            if x.get("firma") == f and str(x.get("user_id")) != u and abs(s - m) < gap:   # eigene ID frei seit 09.10.2026
                return f"Firmen-Abstand: andere ID bei derselben Firma um {zt(s)} — mindestens {gap:g} min Abstand"
        return None
    g = grund(float(neu_min))
    if not g:
        return None, None
    m = int(max(float(neu_min), ab) + 0.999)
    while m < 24 * 60:
        if not grund(float(m)):
            return g, m
        m += 1
    return g, None


AP_NACHHOL_VORLAUF_MIN = (2.0, 4.0)   # verpasster Start: frühestens jetzt + 2–4 min (Zufall), dann die erste regelkonforme Minute


def ap_nachhol_minute(p, plaene, starts, id_fest, jetzt_min, zeiten=None, laufzeit_min=None, laufend=None, rnd=None, ab_min=None):
    """REIN RECHNEND (08.10.2026, Master: Mikes PC offline — „kommt der PC wieder, sollen seine verpassten Pläne automatisch sauber neu
    eingeplant werden, mit allen Regeln: Firmen-Abstand, Gegenhedge, Klumpen — nicht still verfallen und nicht alle auf einmal starten").
    Bisher setzte sfNeuEinplanen jeden verpassten Plan auf jetzt + 2–6 min Zufall — kam ein Tab nach Stunden wieder, starteten alle
    verpassten Pläne binnen Minuten, ohne jede Regel. Jetzt: ab jetzt + AP_NACHHOL_VORLAUF_MIN (Zufall) die erste Minute, die
    (1) ap_start_hand_pruefen besteht (Richtungsschutz ID × Firma, Firmen-Abstand zu anderen IDs), (2) den Abstand je ID hält —
    gleiche Firma AP_ABSTAND_ID_FIRMA_MIN, andere Firma AP_ABSTAND_ID_MIN (zeiten überschreibt) — zu kommenden Plänen und heutigen
    Starts derselben ID (verpasste Pläne mit Start in der Vergangenheit zählen nicht, sie holt ihr eigener Lauf nach), (3) nicht
    ±AP_GEGEN_FIRMA_MIN neben einem gegenläufigen Start einer anderen ID derselben Firma liegt (_ap_gegen_firma — seit 08.10.2026
    ~17:00 Dubai keine Laufzeit-Sperre über IDs mehr, Finn: „kann natürlich eine ANDERE ID Tradeify short gehen"), (4) vor start_bis liegt. p = Zeile aus _ap_stand_plaene {plan_id, user_id, firma,
    richtung}; plaene = _ap_stand_plaene, starts = stand.starts_heute, laufend = [{user_id, firma, richtung, start}].
    → (minute ab 00:00 dt, None) | (None, Klartext)."""
    zeiten = zeiten or {}
    rnd = rnd or random
    u, f, r, pid = str(p["user_id"]), p.get("firma"), p.get("richtung"), str(p.get("plan_id"))
    gap_i = float(zeiten.get("abstand_id_gesamt_min") or AP_ABSTAND_ID_MIN)
    gap_f = float(zeiten.get("abstand_id_firma_min") or AP_ABSTAND_ID_FIRMA_MIN)
    # PC-Regel bleibt (60/20 min sind seit 08.10.2026 weg): nie zwei Puls-Starts derselben ID gleichzeitig — wie ap_verteilung (abstand_id_min + 2)
    gap_pc = float(zeiten.get("abstand_id_min") or 3) + 2
    gap_i, gap_f = max(gap_i, gap_pc), max(gap_f, gap_pc)
    bis, jm = float(ap_klasse_bis(zeiten, p.get("route"))), float(jetzt_min)   # CFD nur bis zeiten.cfd_bis (16.10.2026, Hinweis S2)
    kommend = [x for x in plaene or () if str(x.get("plan_id")) != pid and x.get("start_min") is not None and float(x["start_min"]) >= jm]
    eigen = [(float(x["start_min"]), x.get("firma")) for x in kommend if str(x.get("user_id")) == u]
    eigen += [(float(x["start"]), x.get("firma")) for x in starts or () if str(x.get("user_id")) == u and x.get("start") is not None]
    gegen_pl = [(float(x["start_min"]), x.get("richtung"), str(x.get("user_id")), x.get("firma")) for x in kommend]
    gegen_pl += [(float(x["start"]), x.get("richtung"), str(x.get("user_id")), x.get("firma")) for x in starts or () if x.get("start") is not None]
    m = jm + AP_NACHHOL_VORLAUF_MIN[0] + rnd.random() * (AP_NACHHOL_VORLAUF_MIN[1] - AP_NACHHOL_VORLAUF_MIN[0])
    if ab_min is not None:
        m = max(m, float(ab_min) + rnd.random())       # frühester Start von außen (Topstep-Kette Trade 2, 08.10.2026)
    letzter = None
    for _ in range(4000):
        if m >= bis:
            return None, f"kein regelkonformer Start mehr bis {_ap_hhmm_txt(bis)} dt" + (f" ({letzter})" if letzter else "")
        g, vors = ap_start_hand_pruefen(p, m, plaene, starts, id_fest, jm, laufzeit_min, zeiten.get("abstand_firma_min"))
        if g:
            if vors is None:
                return None, g
            letzter, m = g, (float(vors) if float(vors) > m else int(m) + 1.0) + rnd.random()   # nächste freie Minute + Streuung (Jitter-Regel)
            continue
        sperre = [s + (gap_f if fm == f else gap_i) for s, fm in eigen if abs(s - m) < (gap_f if fm == f else gap_i)]
        if sperre:
            letzter, m = "Abstand je ID", max(sperre) + rnd.random()
            continue
        if _ap_gegen_firma(m, u, f, r, gegen_pl, laufend, jm, laufzeit_min):
            letzter, m = "gegenläufiger Start einer anderen ID (±3 min)", int(m) + 1.0 + rnd.random()
            continue
        return round(m, 2), None
    return None, "kein regelkonformer Start gefunden"


# NACHHOLEN NACHEINANDER (08.10.2026, Slave-Terminal 4 — Befund Slave 2 zu 96a89a6: zwei Tabs derselben ID (gleiche pc_id, Fall pc-40mali)
# rufen „nachholen" parallel für verschiedene verpasste Pläne auf; beide laden denselben Stand, ap_nachhol_minute findet für beide dieselbe
# freie Minute → zwei Starts zu eng, Abstand je ID/Firmen-Abstand gebrochen). Ein Lock für ALLE IDs um Laden + Rechnen + Schreiben: auch
# zwei verschiedene IDs dürfen bei derselben Firma nicht dieselbe Minute bekommen. Railway läuft mit einem Prozess (gunicorn --workers 1
# --threads 48), ein threading.Lock reicht; nachholen ist selten, die Wartezeit ist die Dauer eines Laufs (≈ 1–2 s).
_AP_NACHHOL_LOCK = threading.Lock()


def _ap_nachholen(pid, alle, uid, jetzt=None, gruppe=None):
    """Serialisiert _ap_nachholen_kern (s. _AP_NACHHOL_LOCK). jetzt erst im Lock — der zweite Aufruf rechnet mit dem Stand nach dem ersten."""
    with _AP_NACHHOL_LOCK:
        return _ap_nachholen_kern(pid, alle, uid, jetzt, gruppe=gruppe)


def _ap_nachholen_kern(pid, alle, uid, jetzt=None, gruppe=None):
    """aktion „nachholen" (08.10.2026): verpassten Plan regelkonform neu einplanen (ap_nachhol_minute) — der PC-Tab der ID ruft das aus
    sfTick, wenn er nach einem Ausfall wieder läuft. Admin alle Pläne, sonst nur eigene (Gate wie werte). Nur solange nichts gesendet ist
    (Guard planned, started_at/orbit_gesendet_at leer); Claim zurück, Bestätigung bleibt; start_fehler → status „neu" (Anzeige im Planer).
    → {ok, start, start_dubai} | 409 {ok:false, msg, tagesende}."""
    rows = sb_select("trade_plans", {"select": "id,user_id,status,start_um,started_at,orbit_gesendet_at,master_firm,richtung,mt5_baseline",
                                     "id": f"eq.{pid}"})
    plan = rows[0] if rows else None
    if not plan:
        return jsonify({"ok": False, "msg": "Plan nicht gefunden"}), 404
    # gruppe (Admin-Gruppen 08.10.2026): Verwalter im Admin-Reiter — Pläne seiner Gruppe statt nur der eigenen
    if not alle and str(plan.get("user_id")) != str(uid) and not (gruppe and str(plan.get("user_id")) in gruppe):
        return jsonify({"ok": False, "msg": "nur eigene Pläne"}), 403
    if plan.get("status") != "planned" or plan.get("started_at") or plan.get("orbit_gesendet_at"):
        return jsonify({"ok": False, "msg": ap_plan_nicht_geplant_grund(plan)}), 409
    jetzt = jetzt or datetime.now(timezone.utc)
    reg = (sb_select("auto_plan_regeln", {"select": "*", "id": "eq.1"}) or [None])[0]
    if not reg:
        return jsonify({"ok": False, "msg": "auto_plan_regeln fehlt"}), 503
    stand = _ap_stand_fuer_uid(reg, plan.get("user_id"), jetzt)   # UNT2: gegen den Stand des eigenen Unternehmens
    plaene_tag = _ap_stand_plaene(stand)
    ziel = next((x for x in plaene_tag if str(x.get("plan_id")) == pid), None) or {
        "plan_id": pid, "user_id": str(plan.get("user_id")), "richtung": plan.get("richtung"),
        "firma": ap_firma_key(stand.get("firmen") or [], plan.get("master_firm"))}
    laufend = [{"user_id": z["user_id"], "firma": z.get("firma_key"), "richtung": z.get("richtung"), "start": None} for z in stand["offen"]]
    m, fehler = ap_nachhol_minute(ziel, plaene_tag, stand["starts_heute"], stand["id_fest"], stand["jetzt_min"], stand.get("zeiten"),
                                  (stand.get("param") or {}).get("laufzeit_min"), laufend)
    if m is None:
        return jsonify({"ok": False, "msg": fehler, "tagesende": True}), 409
    neu = stand["mitternacht"] + timedelta(minutes=m)
    rows = sb_update("trade_plans", {"id": f"eq.{pid}", "status": "eq.planned", "started_at": "is.null", "orbit_gesendet_at": "is.null"},
                     {"start_um": neu.astimezone(timezone.utc).isoformat(), "start_um_gestartet_at": None})
    if not rows:
        return jsonify({"ok": False, "msg": _ap_plan_nicht_geplant_msg(pid)}), 409
    dubai = neu.astimezone(_ap_tz(AP_7T_TZ)).strftime("%H:%M")
    alt = ((plan.get("mt5_baseline") or {}).get("start_fehler") or {}) if isinstance(plan.get("mt5_baseline"), dict) else {}
    flag = dict(alt if isinstance(alt, dict) else {}, status="neu", behoben=f"nachgeholt um {dubai} (Dubai) — Regeln geprüft",
                neu_at=jetzt.isoformat(), neu_start=neu.astimezone(timezone.utc).isoformat(), hand=False,
                versuche=int((alt or {}).get("versuche") or 0) + 1)
    try:
        r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/rpc/mt5_baseline_patch", headers=_sb_headers(), timeout=(5, 15),
                        json={"p_plan": str(pid), "p_patch": {"start_fehler": flag}, "p_status": "planned"})
        _sb_pruefen(r)
    except Exception as e:
        print(f"[auto-plan] ⚠️ nachholen Flag {pid}: {type(e).__name__}: {e}", flush=True)
    print(f"[auto-plan] nachholen {pid[:8]} → {dubai} Dubai durch {'Admin' if alle else 'ID ' + str(uid)[:8]}", flush=True)
    return jsonify({"ok": True, "start": neu.astimezone(timezone.utc).isoformat(), "start_dubai": dubai})


def ap_werte_pruefen(plan, body, jetzt=None, start=None):
    """REIN RECHNEND (testbar): TP/SL/Größe eines geplanten Trades von Hand (Finn 08.10.2026, Mini-Popup; Vertrag Master/Slave 5).
    plan = trade_plans-Zeile {status, start_um_gestartet_at, started_at, orbit_gesendet_at, route, master_symbol(_root), master_tp,
    master_sl, master_contracts, notes}; body = {tp_usd?, sl_usd?, groesse?}. Futures (Route nicht in AP_CFD_ROUTEN) = ganze Kontrakte ≥ 1,
    CFD (mt5v2/mt5) = Lots auf 2 Stellen > 0. sl_usd null oder 0 = ohne SL (master_sl null). Nur die drei Werte, keine Neuberechnung,
    Bestätigung bleibt. → (upd, antwort, None) oder (None, None, Klartext)."""
    if not plan:
        return None, None, "Plan nicht gefunden"
    if plan.get("start_um_gestartet_at") or plan.get("started_at") or plan.get("orbit_gesendet_at") or plan.get("status") == "open":
        return None, None, "Plan läuft schon — Werte nicht mehr änderbar"
    if plan.get("status") != "planned":
        return None, None, "Plan ist nicht mehr geplant — Werte nicht änderbar"
    cfd = str(plan.get("route") or "") in AP_CFD_ROUTEN
    sym = str(plan.get("master_symbol_root") or plan.get("master_symbol") or "").upper()
    einheit = "Lot" if cfd else ("MNQ" if sym.startswith("MNQ") else "NQ")
    upd, txt = {}, []

    def de(x):                                   # deutsch: 3.600 / 1,23
        if x is None:
            return "ohne"
        if float(x) == int(x):
            return f"{int(x):,}".replace(",", ".")
        return f"{float(x):,.2f}".rstrip("0").translate(str.maketrans(",.", ".,"))
    if "tp_usd" in body:
        tp = _ap_zahl(body.get("tp_usd"))
        if tp is None or tp <= 0:
            return None, None, "TP muss eine Zahl > 0 sein ($)"
        upd["master_tp"] = round(tp, 2)
        txt.append(f"TP {de(_wd_num(plan.get('master_tp')))} → {de(upd['master_tp'])}")
    if "sl_usd" in body:
        roh = body.get("sl_usd")
        sl = None if roh in (None, "") else _ap_zahl(roh)
        if roh not in (None, "") and (sl is None or sl < 0):
            return None, None, "SL muss eine Zahl ≥ 0 sein ($) oder leer (= ohne SL)"
        upd["master_sl"] = round(sl, 2) if sl else None          # 0 = ohne SL
        txt.append(f"SL {de(_wd_num(plan.get('master_sl')))} → {de(upd['master_sl'])}")
    if "groesse" in body:
        g = _ap_zahl(body.get("groesse"))
        if cfd:
            g = round(g, 2) if g is not None else None
            if g is None or g <= 0:
                return None, None, "Größe muss > 0 Lot sein (2 Nachkommastellen)"
        else:
            if g is None or g < 1 or g != int(g):
                return None, None, "Größe muss ganze Kontrakte sein (≥ 1)"
            g = int(g)
        upd["master_contracts"] = g
        txt.append(f"Größe {de(_wd_num(plan.get('master_contracts')))} → {de(float(g))} {einheit}")
    if start:
        # start = {iso, alt_txt, neu_txt} — schon geprüft (ap_start_zeit + ap_start_hand_pruefen), hier nur setzen + Notes
        upd["start_um"] = start["iso"]
        txt.append(f"Start {start.get('alt_txt') or '–'} → {start.get('neu_txt')}")
    if not upd:
        return None, None, "nichts zu ändern — tp_usd, sl_usd, groesse oder start_um angeben"
    z = (jetzt or datetime.now(timezone.utc)).astimezone(_ap_tz(AP_7T_TZ))
    zeile = f"✎ Hand {z.strftime('%d.%m %H:%M')}: " + " · ".join(txt)
    upd["notes"] = (str(plan.get("notes") or "").rstrip() + "\n" + zeile).strip()
    neu = {"master_tp": _wd_num(plan.get("master_tp")), "master_sl": _wd_num(plan.get("master_sl")),
           "master_contracts": _wd_num(plan.get("master_contracts"))}
    neu.update({k: v for k, v in upd.items() if k not in ("notes", "start_um")})
    return upd, {"plan_id": str(plan.get("id") or ""), "tp_usd": neu["master_tp"], "sl_usd": neu["master_sl"],
                 "groesse": neu["master_contracts"], "einheit": einheit, "start_um": upd.get("start_um") or plan.get("start_um")}, None


def _ap_werte_setzen(pid, body, admin, uid, gruppe=None):
    """aktion „werte" (08.10.2026): Admin alle Pläne, sonst nur eigene. Schreiben mit Guard in derselben Anfrage (planned, nichts
    gestartet/gesendet) — sonst 409. Bestätigung (auto_bestaetigt_at) bleibt unberührt."""
    rows = sb_select("trade_plans", {"select": "id,user_id,status,route,master_symbol,master_symbol_root,master_tp,master_sl,"
                                               "master_contracts,notes,start_um,start_um_gestartet_at,started_at,orbit_gesendet_at,"
                                               "master_firm,richtung", "id": f"eq.{pid}"})
    plan = rows[0] if rows else None
    # gruppe (Admin-Gruppen 08.10.2026): Verwalter im Admin-Reiter — Pläne seiner Gruppe statt nur der eigenen
    if plan and not admin and str(plan.get("user_id")) != str(uid) and not (gruppe and str(plan.get("user_id")) in gruppe):
        return jsonify({"ok": False, "msg": "nur eigene Pläne"}), 403
    start = None
    if plan and "start_um" in body:
        # STARTZEIT PER KLICK (08.10.2026, Vertrag Slave 5): ≥ jetzt + 2 min, Richtungsschutz, Firmen-Abstand — gegen den Live-Stand
        jetzt = datetime.now(timezone.utc)
        dt, fehler = ap_start_zeit(body.get("start_um"), jetzt)
        if fehler:
            return jsonify({"ok": False, "msg": fehler}), 400
        reg = (sb_select("auto_plan_regeln", {"select": "*", "id": "eq.1"}) or [None])[0]
        if not reg:
            return jsonify({"ok": False, "msg": "auto_plan_regeln fehlt"}), 503
        # Stand des TAGES, an dem der neue Start liegt (Planer-Tag = deutsche Zeit) — auch Pläne von morgen (Nachtlauf)
        stand = _ap_stand_fuer_uid(reg, plan.get("user_id"), jetzt, tag=dt.astimezone(_ap_tz(AP_TZ_TAG)).strftime("%Y-%m-%d"))   # UNT2
        neu_min = (dt - stand["mitternacht"]).total_seconds() / 60.0
        dubai = lambda d: d.astimezone(_ap_tz(AP_7T_TZ)).strftime("%H:%M") if d else None
        plaene_tag = _ap_stand_plaene(stand)
        ziel = next((x for x in plaene_tag if str(x.get("plan_id")) == pid), None) or {
            "plan_id": pid, "user_id": str(plan.get("user_id")), "richtung": plan.get("richtung"),
            "firma": ap_firma_key(stand.get("firmen") or [], plan.get("master_firm"))}   # Plan liegt bisher an einem anderen Tag
        fehler, vorschlag = ap_start_hand_pruefen(ziel, neu_min, plaene_tag, stand["starts_heute"], stand["id_fest"],
                                                 stand["jetzt_min"], (stand.get("param") or {}).get("laufzeit_min"),
                                                 (stand.get("zeiten") or {}).get("abstand_firma_min"),
                                                 zeit=lambda m: dubai(stand["mitternacht"] + timedelta(minutes=float(m))))
        if fehler:
            v = stand["mitternacht"] + timedelta(minutes=vorschlag) if vorschlag is not None else None
            return jsonify({"ok": False, "msg": fehler + (f" — nächste freie Zeit {dubai(v)} (Dubai)" if v else ""),
                            "vorschlag": v.astimezone(timezone.utc).isoformat() if v else None, "vorschlag_dubai": dubai(v)}), 400
        start = {"iso": dt.isoformat(), "alt_txt": dubai(_ap_ts(plan.get("start_um"))), "neu_txt": dubai(dt)}
    upd, antwort, fehler = ap_werte_pruefen(plan, body, start=start)
    if fehler:
        return jsonify({"ok": False, "msg": fehler}), 404 if fehler == "Plan nicht gefunden" else 400
    guard = {"id": f"eq.{pid}", "status": "eq.planned", "start_um_gestartet_at": "is.null", "started_at": "is.null", "orbit_gesendet_at": "is.null"}
    try:                                           # hand_werte_at: Bot fasst den Plan danach nicht mehr an (AP_FEST_HAND)
        neu = sb_update("trade_plans", guard, dict(upd, hand_werte_at=datetime.now(timezone.utc).isoformat()))
    except Exception as e:
        if not _ap_hand_spalte_fehlt(e):
            raise
        neu = sb_update("trade_plans", guard, upd)
    if not neu:
        return jsonify({"ok": False, "msg": "Plan läuft schon — Werte nicht mehr änderbar"}), 409
    print(f"[auto-plan] werte {pid[:8]} durch {'Admin' if admin else 'ID ' + str(uid)[:8]}: {upd['notes'].splitlines()[-1]}", flush=True)
    return jsonify({"ok": True, "plan": antwort})


@app.route("/admin/auto-plan/plan", methods=["POST", "OPTIONS"])
def admin_auto_plan_eingriff():
    """POST {plan_id, aktion: 'richtung_tauschen'|'start', start?, start_min?} → manueller Eingriff mit denselben harten Regeln wie der Bot
    (Verstoß = 400 Klartext). start = 'HH:MM' deutscher Zeit (heute) oder ISO. Gilt für die ganze Tranche (ID × Firma). Admin — seit
    08.10.2026 auch jeder Login im Admin-Reiter (sicht=admin, nicht „nur eigene", ap_eingriff_admin_reiter).
    Seit 08.10.2026 auch aktion 'werte' {tp_usd?, sl_usd?, groesse?} (Mini-Popup): Admin alle Pläne, jede andere ID nur eigene."""
    if request.method == "OPTIONS":
        return "", 200
    if str((request.get_json(silent=True) or {}).get("aktion") or "").strip() not in PLANER_PLAN_AUTOMATIK:
        _gs = _planer_schreib_gate()          # PLANER-RECHTE HT (30.10.2026) — nachholen ausgenommen (PC-Tab-Automatik)
        if _gs is not None:
            return _gs
    body = request.get_json(silent=True) or {}
    if str(body.get("aktion") or "").strip() in ("werte", "nachholen"):   # nachholen (08.10.2026): verpasste Pläne, gleiches Gate
        # eigenes Gate: auch IDs außerhalb des Auto-Planers dürfen ihre eigenen geplanten Trades ändern
        _mail, err = _planer_admin_auth()
        admin = err is None
        uid = request.environ.get("prophos.admin_uid") if admin else None
        if not admin:
            if err[1] != 403:
                return err
            uid, err2 = _wd_login()
            if err2:
                return err2
        pid = str(body.get("plan_id") or "").strip()
        if not re.match(r"^[0-9a-f-]{36}$", pid):
            return jsonify({"ok": False, "msg": "plan_id fehlt"}), 400
        try:
            # Admin-Reiter (08.10.2026): sicht="admin" und nicht „nur eigene" → alle Pläne wie ein Admin (ap_eingriff_sicht);
            # Verwalter (Admin-Gruppen 08.10.2026) → Pläne seiner Gruppe (gruppe_e)
            # EMIN-BESTAETIGEN (02.11.2026): werte ist ein Klick, der Verwalter braucht dafür keinen Marker (ap_verwalter_sicht). nachholen ruft der
            # PC-Tab selbst: ohne Marker bleibt der Verwalter dort bei der eigenen ID (Anzeige ≠ Ausführung, 08.10.2026)
            alle, gruppe_e = admin, None
            ist_werte = str(body.get("aktion") or "").strip() == "werte"
            if not admin and (_ap_sicht_param() == AP_SICHT_ADMIN or ist_werte):
                nur, gruppe = _ap_gruppe_lesen(uid)
                e_sicht = ap_eingriff_sicht(False, uid, _ap_im_planer(uid), nur, ap_verwalter_sicht(gruppe, _ap_sicht_param()), gruppe)
                alle = e_sicht is None
                gruppe_e = e_sicht if isinstance(e_sicht, frozenset) else None
            if str(body.get("aktion") or "").strip() == "nachholen":
                return _ap_nachholen(pid, alle, uid, gruppe=gruppe_e)
            return _ap_werte_setzen(pid, body, alle, uid, gruppe=gruppe_e)
        except Exception as e:
            return jsonify({"ok": False, "msg": f"{type(e).__name__}: {e}"}), 502
    # ADMIN-REITER DARF EINGREIFEN (Finn 08.10.2026 auf die Frage des Masters, ob auch „Finn + Pascal" und Ina bei fremden IDs neu starten,
    # Richtung tauschen und Tranchen verschieben dürfen: „Ja, sollen alle dies machen können."): richtung_tauschen/start/neu_starten
    # für Admin (ADMIN_EMAILS) UND jeden Login mit sicht="admin", der nicht admin_zugang „nur eigene" ist (ap_eingriff_admin_reiter);
    # Nicht-Planer-Logins kommen über _ap_zugang(admin_reiter=True) durch. Ausgleichen/Bot-Einstellung bleiben bei ADMIN_EMAILS.
    admin, uid, reg, err = _ap_zugang(admin_reiter=True)
    if err:
        return err
    body = request.get_json(silent=True) or {}
    pid, aktion = str(body.get("plan_id") or "").strip(), str(body.get("aktion") or "").strip()
    if not re.match(r"^[0-9a-f-]{36}$", pid):
        return jsonify({"ok": False, "msg": "plan_id fehlt"}), 400
    if not admin:
        nur, gruppe = _ap_gruppe_lesen(uid)   # nicht lesbar → (True, None) → nie fremde Pläne
        darf = ap_eingriff_admin_reiter(False, uid, nur, _ap_sicht_param(), _ap_im_planer(uid))
        if not darf and gruppe:
            # Admin-Gruppen (08.10.2026): Verwalter greift ein, aber nur in Pläne seiner Gruppe (die Tranche gehört zu genau einer ID).
            # Seit 02.11.2026 ohne Marker (EMIN-BESTAETIGEN): apdPlanAktion schickt nie sicht=admin, alle Aktionen hier sind Klicks
            try:
                darf = admin_in_sicht((sb_select("trade_plans", {"select": "user_id", "id": f"eq.{pid}"}) or [{}])[0].get("user_id"), gruppe)
            except Exception:
                darf = False
        if not darf:
            return jsonify({"ok": False, "msg": AP_NUR_PLANER_TXT}), 403
    if aktion not in ("richtung_tauschen", "richtung_plan", "start", "neu_starten"):
        return jsonify({"ok": False, "msg": "aktion = richtung_tauschen | richtung_plan | start | neu_starten | werte"}), 400
    if aktion == "neu_starten":
        return _ap_neu_starten(pid)
    if aktion == "richtung_plan":
        return _ap_richtung_plan(pid)
    try:
        # UNT2: Stand des Unternehmens, zu dem der Plan gehört (HT-Plan nie gegen Emins Pläne, Emins nie gegen HT)
        _puid = (sb_select("trade_plans", {"select": "user_id", "id": f"eq.{pid}"}) or [{}])[0].get("user_id")
        stand = _ap_stand_fuer_uid(reg, _puid)
        neu_min = None
        if aktion == "start":
            # start_min (Minuten ab 00:00 dt) hat Vorrang (Frontend .1084 schickt beides), sonst start 'HH:MM' dt oder ISO
            s = str(body.get("start") or "").strip()
            if _wd_num(body.get("start_min")) is not None and not isinstance(body.get("start_min"), bool):
                neu_min = _wd_num(body.get("start_min"))
            elif re.match(r"^\d{1,2}:\d{2}$", s):
                neu_min = _ap_hhmm(s)
            elif s:
                neu_min = _ap_iso_min(s, stand["mitternacht"])
            if neu_min is None:
                return jsonify({"ok": False, "msg": "start = HH:MM (deutsche Zeit) oder ISO"}), 400
        aend, fehler = ap_eingriff_pruefen(pid, aktion, _ap_stand_plaene(stand), stand["jetzt_min"], stand["zeiten"],
                                           stand["id_fest"], neu_min)
        if fehler:
            return jsonify({"ok": False, "msg": fehler}), 400
        umpl, fehler = _ap_aenderungen_anwenden(stand, aend, "hand")
        if fehler and not umpl:
            return jsonify({"ok": False, "msg": fehler}), 409
        if not umpl:
            return jsonify({"ok": False, "msg": "Plan hat sich inzwischen geändert (gestartet/bestätigt) — nichts geändert"}), 409
        return jsonify({"ok": True, "umplanungen": umpl, "msg": fehler})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"{type(e).__name__}: {e}"}), 502


def _ap_neu_starten(pid):
    """BEHOBEN → NEU EINPLANEN (Finn 07.10.2026 16:24 zu „Braucht dich": „Fehler behoben — da muss ich auf Abhaken drücken, sodass
    der Trade frisch reingeplant wird und noch starten kann; ich kann aktuell nur auf ‚Plan' drücken"). Für Pläne fremder IDs, die der
    Admin per RLS nicht selbst ändern darf (eigene macht der Tab direkt, sfNeuEinplanen): Startzeit jetzt + 1–3 min (Zufall), Claim
    zurück — nur solange nichts gesendet ist (Guard: planned, started_at/orbit_gesendet_at leer). Den Start macht der PC-Tab der ID
    mit allen Prüfungen; er gleicht seine Pläne alle 2 min ab. mt5_baseline.start_fehler → status 'neu' (Anzeige im Planer)."""
    # VERFALLEN (08.10.2026, Prüfer Slave 2): ein Auto-Plan eines früheren Tages, der nie gesendet wurde, zählt im Planer nicht mehr —
    # der Nachtlauf plant das Konto neu. „Neu starten" würde ihn NEBEN den Ersatzplan legen (zwei Trades auf einem Konto) → ablehnen.
    alt_p = (sb_select("trade_plans", {"select": "id,user_id,status,auto_plan,start_um,started_at,orbit_gesendet_at", "id": f"eq.{pid}"}) or [None])[0]
    # PC AUS (19.10.2026, Finn: „so lange der PC aus ist, muss Puls nicht versuchen, in 2 Minuten eine Order reinzudrücken"): kein PC-Tab
    # seit ≥ PC_AUS_S → nicht neu einplanen, Klartext zurück. Sobald der PC wieder läuft, holt sein Tab den Start von selbst nach (sfTick).
    pc_aus = _ap_pc_aus_text(alt_p.get("user_id")) if alt_p else ""
    if pc_aus:
        return jsonify({"ok": False, "pc_aus": True, "msg": f"{pc_aus} — einschalten, dann holt Puls den Start von selbst nach"}), 409
    _tz = _ap_tz(AP_TZ_TAG)
    _h = datetime.now(timezone.utc).astimezone(_tz)
    if alt_p and ap_plan_verfallen(alt_p, datetime(_h.year, _h.month, _h.day, tzinfo=_tz)):
        return jsonify({"ok": False, "verfallen": True,
                        "msg": "verfallen — der Plan war für einen früheren Tag und wurde nie gesendet; der Nachtlauf plant das Konto neu"}), 409
    neu = datetime.now(timezone.utc) + timedelta(seconds=60 + random.random() * 120)
    rows = sb_update("trade_plans", {"id": f"eq.{pid}", "status": "eq.planned", "started_at": "is.null", "orbit_gesendet_at": "is.null"},
                     {"start_um": neu.isoformat(), "start_um_gestartet_at": None})
    if not rows:
        return jsonify({"ok": False, "msg": _ap_plan_nicht_geplant_msg(pid)}), 409
    alt = ((rows[0].get("mt5_baseline") or {}).get("start_fehler") or {}) if isinstance(rows[0].get("mt5_baseline"), dict) else {}
    flag = dict(alt if isinstance(alt, dict) else {}, status="neu", behoben="von Hand (Admin)", neu_at=datetime.now(timezone.utc).isoformat(),
                neu_start=neu.isoformat(), hand=True, versuche=int((alt or {}).get("versuche") or 0) + 1)
    try:
        r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/rpc/mt5_baseline_patch", headers=_sb_headers(), timeout=(5, 15),
                        json={"p_plan": str(pid), "p_patch": {"start_fehler": flag}, "p_status": "planned"})
        _sb_pruefen(r)
    except Exception as e:
        print(f"[auto-plan] ⚠️ neu_starten Flag {pid}: {type(e).__name__}: {e}", flush=True)
    return jsonify({"ok": True, "start": neu.isoformat()})


def ap_richtung_plan_pruefen(plan, frei, jetzt):
    """REIN RECHNEND — RICHTUNG PER KLICK IM ADMIN-PLANER (Finn 14.10.2026, Aurels Tradeify-Short …9883 sollte vor dem Start BUY werden,
    ging nur per SQL): EIN geplanter, ungeclaimter Auto-Plan wird umgedreht — nicht die ganze Tranche wie richtung_tauschen, denn die
    Richtung ist seit .1401 je Trade frei. plan = trade_plans-Zeile, frei = Antwort von prophos_gegenrichtung_frei(plan, neue Richtung)
    (None = nicht lesbar). → (neu, None) oder (None, Klartext). Fail-closed: ohne lesbare Antwort wird nicht gedreht."""
    if not plan:
        return None, "Plan nicht gefunden"
    if plan.get("status") != "planned":
        return None, f"Plan ist nicht mehr geplant (Status {plan.get('status') or '?'}) — Richtung nicht änderbar"
    if plan.get("auto_plan") is not True:
        return None, "kein Auto-Plan — Hand-Pläne im Plan selbst ändern"
    if plan.get("start_um_gestartet_at") or plan.get("started_at") or plan.get("orbit_gesendet_at"):
        return None, "Start läuft schon (Plan geclaimt) — Richtung nicht mehr änderbar"
    alt = str(plan.get("richtung") or "").lower()
    if alt not in ("buy", "sell"):
        return None, "Plan hat keine Richtung"
    # bestätigt und in ≤ AP_FAELLIG_MIN fällig: der PC-Tab kann gerade claimen — derselbe Riegel wie bei Bot und richtung_tauschen
    if plan.get("auto_bestaetigt_at") and plan.get("start_um"):
        try:
            s = datetime.fromisoformat(str(plan["start_um"]).replace("Z", "+00:00"))
            if s <= jetzt + timedelta(minutes=AP_FAELLIG_MIN):
                return None, f"startet in ≤ {AP_FAELLIG_MIN} min und ist bestätigt — erst ↩ zurück, dann drehen"
        except (TypeError, ValueError):
            pass
    if not isinstance(frei, dict):
        return None, "Richtungsschutz nicht lesbar — nichts gedreht, gleich nochmal versuchen"
    if frei.get("frei") is not True:
        return None, "Gesperrt: " + str(frei.get("grund") or "Gegenrichtung bei derselben ID × Firma läuft")
    return ("sell" if alt == "buy" else "buy"), None


def ap_richtung_hand_fest(p):
    """REIN: gilt der Hand-Merker (mt5_baseline.richtung_hand) noch? Nur solange die Richtung des Plans die von Hand gesetzte ist —
    hat ein harter Riegel am Start (Saldo/rkVorStart) inzwischen gedreht, ist der Merker überholt und der Plan wieder normal."""
    rh = p.get("rh") if isinstance(p, dict) else None
    return isinstance(rh, dict) and rh.get("nach") in ("buy", "sell") and rh.get("nach") == str(p.get("richtung") or "").lower()


def _ap_richtung_plan(pid):
    """Admin-Planer „Zu bestätigen"/„Wartet auf Start": einen Plan umdrehen (ap_richtung_plan_pruefen), Guard in derselben PATCH-Anfrage
    (planned, Auto-Plan, alte Richtung, nichts geclaimt/gesendet), Protokoll in auto_plan_umplanung mit quelle 'hand'. Der Saldo-Riegel
    bleibt am Start (rkVorStart im PC-Tab, ap_richtung_konflikte im Bot) — er wird hier weder geprüft noch ausgehebelt."""
    plan = (sb_select("trade_plans", {"select": "id,user_id,status,auto_plan,richtung,master_firm,start_um,auto_bestaetigt_at,"
                                      "start_um_gestartet_at,started_at,orbit_gesendet_at", "id": f"eq.{pid}"}) or [None])[0]
    alt = str((plan or {}).get("richtung") or "").lower()
    frei = None
    if plan and alt in ("buy", "sell"):
        try:
            r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/rpc/prophos_gegenrichtung_frei", headers=_sb_headers(), timeout=(5, 15),
                            json={"p_plan": pid, "p_richtung": "sell" if alt == "buy" else "buy"})
            frei = r.json() if r.status_code == 200 else None
        except Exception as e:
            print(f"[auto-plan] ⚠️ richtung_plan Riegel {pid}: {type(e).__name__}: {e}", flush=True)
    jetzt = datetime.now(timezone.utc)
    neu, fehler = ap_richtung_plan_pruefen(plan, frei, jetzt)
    if fehler:
        return jsonify({"ok": False, "msg": fehler, "gesperrt": isinstance(frei, dict) and frei.get("frei") is False}), 409
    faellig = (jetzt + timedelta(minutes=AP_FAELLIG_MIN)).strftime("%Y-%m-%dT%H:%M:%SZ")
    rows = sb_update("trade_plans", {"id": f"eq.{pid}", "status": "eq.planned", "auto_plan": "eq.true", "richtung": f"eq.{alt}",
                                     "start_um_gestartet_at": "is.null", "started_at": "is.null", "orbit_gesendet_at": "is.null",
                                     "or": f"(auto_bestaetigt_at.is.null,start_um.gt.{faellig})"}, {"richtung": neu})
    if not rows:
        return jsonify({"ok": False, "msg": "Plan hat sich inzwischen geändert (gestartet/gedreht) — nichts geändert"}), 409
    zeile = {"um": jetzt.isoformat(), "plan_id": pid, "user_id": str(plan.get("user_id")), "firma": plan.get("master_firm"),
             "von_richtung": alt, "nach_richtung": neu, "von_start": plan.get("start_um"), "nach_start": plan.get("start_um"),
             "grund": f"von Hand (Admin-Planer): {AP_RICHTUNG_TXT[alt]} → {AP_RICHTUNG_TXT[neu]}", "quelle": "hand"}
    msg = None
    try:                                           # Hand-Merker: Bot wertet den Plan als fest (AP_FEST_RICHTUNG_HAND)
        _sb_pruefen(_sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/rpc/mt5_baseline_patch", headers=_sb_headers(), timeout=(5, 15),
                                json={"p_plan": pid, "p_patch": {"richtung_hand": {"um": jetzt.isoformat(), "von": alt, "nach": neu}},
                                      "p_status": "planned"}))
    except Exception as e:
        print(f"[auto-plan] ⚠️ richtung_plan Merker {pid}: {type(e).__name__}: {e}", flush=True)
        msg = f"gedreht, Hand-Merker nicht gesetzt ({type(e).__name__}) — der Bot könnte zurückdrehen"
    try:
        _sb_pruefen(_sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/auto_plan_umplanung", json=[zeile],
                                headers=_sb_headers("return=minimal"), timeout=(5, 20)))
    except Exception as e:
        print(f"[auto-plan] ⚠️ richtung_plan Protokoll {pid}: {type(e).__name__}: {e}", flush=True)
        msg = (msg + " · " if msg else "") + f"gedreht, Protokoll nicht geschrieben ({type(e).__name__})"
    return jsonify({"ok": True, "plan_id": pid, "richtung": neu, "msg": msg})


def ap_start_protokoll_zeile(plan, body, jetzt_iso):
    """REIN (RICHTUNG AM START, 07.10.2026): Protokollzeile für auto_plan_umplanung aus dem Eintrag des PC-Tabs → (zeile, None) oder
    (None, Klartext). Richtungen nur buy/sell/leer, Startzeiten ISO, Grund ≤ 500 Zeichen, quelle 'start'."""
    def ri(x):
        x = str(x or "").strip().lower()
        return x if x in ("buy", "sell") else None if not x else False

    def zeit(x):
        if x in (None, ""):
            return None
        try:
            return datetime.fromisoformat(str(x).replace("Z", "+00:00")).astimezone(timezone.utc).isoformat()
        except (TypeError, ValueError):
            return False
    von_r, nach_r, von_s, nach_s = ri(body.get("von_richtung")), ri(body.get("nach_richtung")), zeit(body.get("von_start")), zeit(body.get("nach_start"))
    if False in (von_r, nach_r):
        return None, "von_richtung/nach_richtung = buy | sell"
    if False in (von_s, nach_s):
        return None, "von_start/nach_start = ISO-Zeit"
    grund = str(body.get("grund") or "").strip()
    if not grund:
        return None, "grund fehlt"
    return {"um": jetzt_iso, "plan_id": str(plan.get("id")), "user_id": str(plan.get("user_id")), "firma": plan.get("master_firm"),
            "von_richtung": von_r, "nach_richtung": nach_r, "von_start": von_s, "nach_start": nach_s,
            "grund": grund[:500], "quelle": "start"}, None


@app.route("/admin/auto-plan/start-protokoll", methods=["POST", "OPTIONS"])
def admin_auto_plan_start_protokoll():
    """POST {plan_id, von_richtung, nach_richtung, von_start, nach_start, grund} — RICHTUNG AM START (Finn 07.10.2026): der PC-Tab
    hat einen Plan kurz vor dem Start wegen Richtungsschutz gedreht oder verschoben (die Änderung selbst schreibt er mit eigenem
    Guard über die RLS seiner ID) und protokolliert sie hier in auto_plan_umplanung (quelle 'start'; die Tabelle hat keine Policy,
    nur der Service-Key schreibt). Nur der Besitzer des Plans. Ist die quelle 'start' noch nicht freigeschaltet
    (sql/2026-10-07_umplanung_quelle_start.sql), steht die Zeile als quelle 'bot' mit „[Start]" vor dem Grund drin."""
    if request.method == "OPTIONS":
        return "", 200
    uid, err = _wd_login()
    if err:
        return err
    body = request.get_json(silent=True) or {}
    pid = str(body.get("plan_id") or "").strip()
    if not re.match(r"^[0-9a-f-]{36}$", pid):
        return jsonify({"ok": False, "msg": "plan_id fehlt"}), 400
    try:
        plan = (sb_select("trade_plans", {"select": "id,user_id,master_firm", "id": f"eq.{pid}"}) or [None])[0]
        if not plan or str(plan.get("user_id")) != str(uid):
            return jsonify({"ok": False, "msg": "Plan nicht gefunden oder nicht deiner"}), 404
        zeile, fehler = ap_start_protokoll_zeile(plan, body, datetime.now(timezone.utc).isoformat())
        if fehler:
            return jsonify({"ok": False, "msg": fehler}), 400
        r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/auto_plan_umplanung", json=[zeile],
                        headers=_sb_headers("return=minimal"), timeout=(5, 20))
        if r.status_code == 400 and "quelle" in (r.text or ""):
            zeile = dict(zeile, quelle="bot", grund=("[Start] " + zeile["grund"])[:500])
            r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/auto_plan_umplanung", json=[zeile],
                            headers=_sb_headers("return=minimal"), timeout=(5, 20))
        _sb_pruefen(r)
        return jsonify({"ok": True, "quelle": zeile["quelle"]})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"{type(e).__name__}: {e}"}), 502


@app.route("/admin/auto-plan/waage-start", methods=["POST", "OPTIONS"])
def admin_auto_plan_waage_start():
    """POST {plan_id, richtung, ziehen} — START-PRÜFUNG DER ZWEI WAAGEN (Finn 17.10.2026) für den PC-Tab (rkVorStart): Lage der
    Klasse (Futures/CFD), wenn der Plan jetzt in `richtung` startet, und wenn er gedreht startet. ziehen=true und der Start macht die
    Klasse weder passend noch besser → Gegentrades derselben Klasse sofort auf jetzt + 2–3 min vorziehen (ap_waage_nachschub, der
    Plan zählt dabei schon als laufend; nur wenn der Ausgleichs-Bot an ist). Nur der Besitzer des Plans.
    → {ok, waage_an, lage {klasse, zaehlt, vorher, nachher {passt, besser, grund}, gegen {…}}, gezogen [{plan_id, user, firma, nach_start}]}"""
    if request.method == "OPTIONS":
        return "", 200
    uid, err = _wd_login()
    if err:
        return err
    body = request.get_json(silent=True) or {}
    pid = str(body.get("plan_id") or "").strip()
    richtung = str(body.get("richtung") or "").strip()
    if not re.match(r"^[0-9a-f-]{36}$", pid) or richtung not in ("buy", "sell"):
        return jsonify({"ok": False, "msg": "plan_id/richtung fehlt"}), 400
    try:
        plan = (sb_select("trade_plans", {"select": "id,user_id", "id": f"eq.{pid}"}) or [None])[0]
        if not plan or str(plan.get("user_id")) != str(uid):
            return jsonify({"ok": False, "msg": "Plan nicht gefunden oder nicht deiner"}), 404
        reg = (sb_select("auto_plan_regeln", {"select": "*", "id": "eq.1"}) or [None])[0]
        if not reg:
            return jsonify({"ok": False, "msg": "auto_plan_regeln fehlt"}), 503
        param = ap_ausgleich_param(reg.get("regeln"))
        if not param.get("waage"):
            return jsonify({"ok": True, "waage_an": False})
        # JEDE GRUPPE WIEGT FÜR SICH (30.10.2026): Plan einer Verwalter-Gruppe → Waage nur aus ihren IDs, sonst HT wie bisher
        gr = ap_gruppe_von_uid(plan.get("user_id"))
        if gr:
            namen, _aus = _ap_namen()
            stand = _ap_stand_laden(reg, namen=namen, ausgeblendet=ap_gruppe_ausgeblendet(namen, gr["ids"]), eigene=gr["ids"])
            try:     # ORBIT PRIO 2 (Fremd-Review MO1b): die Startprüfung wiegt die Gruppe mit IHREN Modellen wie ap_planen und der Bot
                _fm_g = next((v for u, v in ap_gruppen_modelle().items() if u in {str(x) for x in (gr.get("ids") or ())}), {})
                stand["param"] = ap_waage_param_gruppe(stand.get("param"), (reg.get("regeln") or {}).get("ausgleich"), (reg.get("regeln") or {}).get("firmen"), _fm_g)
            except Exception as e:
                print(f"[waage-start] ⚠️ Gruppe Orbit Prio 2: {type(e).__name__}: {e}", flush=True)
        else:   # UNT2: HT-Plan → HT-Stand; Verwalter-Gruppe ohne Planer-Zeile → Stand ihrer Gruppe (nie der HT-Stand)
            stand = _ap_stand_fuer_uid(reg, plan.get("user_id"))
        pc = _ap_pc_lebt_gecacht()
        lage = ap_waage_start_lage(stand, pid, richtung, pc_lebt=pc)
        if lage is None:
            return jsonify({"ok": False, "msg": "Plan steht heute nicht im Planer-Stand"}), 404
        gezogen, fehler = [], None
        nh = lage["nachher"]
        if body.get("ziehen") is True and param.get("aktiv") and lage["zaehlt"] and not (nh["passt"] or nh["besser"]):
            waage = ap_klassen_waage(stand, pc_lebt=pc, extra={"plan_id": pid, "richtung": richtung})
            aend, _info = ap_waage_nachschub(stand, waage, random.SystemRandom(), pc_lebt=pc,
                                             dubai_min=_ap_dubai_versatz(stand["mitternacht"]), nur_klasse=lage["klasse"], schon=[pid])
            umpl, fehler = _ap_aenderungen_anwenden(stand, aend, "bot") if aend else ([], None)
            gezogen = [{"plan_id": u.get("plan_id"), "user": u.get("user"), "firma": u.get("firma"), "nach_start": u.get("nach_start")}
                       for u in umpl]
        return jsonify({"ok": True, "waage_an": True, "lage": lage, "gezogen": gezogen, "fehler": fehler})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"{type(e).__name__}: {e}"}), 502


@app.route("/admin/auto-plan/ausgleich-einstellung", methods=["POST", "OPTIONS"])
def admin_auto_plan_ausgleich_einstellung():
    """POST {aktiv?, takt_min?, zielband_pct?, auto_start?} → auto_plan_regeln.regeln.ausgleich (nur genannte Felder). Nur Admin.
    auto_plan_regeln.aktiv (Nachtlauf) bleibt unberührt."""
    if request.method == "OPTIONS":
        return "", 200
    _gs = _planer_schreib_gate()              # PLANER-RECHTE HT (30.10.2026)
    if _gs is not None:
        return _gs
    admin, uid, reg, err = _ap_zugang()
    if err:
        return err
    if not admin:
        return jsonify({"ok": False, "msg": "Nur für Admins"}), 403
    body = request.get_json(silent=True) or {}
    regeln = dict(reg.get("regeln") or {})
    if "echo_hedge" in body:          # HT ECHO-HEDGE B2 (29.10.2026): nur regeln.echo_hedge.an — eigener Schalter, ausgleich bleibt unberührt
        if not isinstance(body["echo_hedge"], bool):
            return jsonify({"ok": False, "msg": "echo_hedge = true | false"}), 400
        eh_roh = regeln.get("echo_hedge") if isinstance(regeln.get("echo_hedge"), dict) else {}
        regeln["echo_hedge"] = dict(eh_roh, an=body["echo_hedge"])
        try:
            sb_update("auto_plan_regeln", {"id": "eq.1"}, {"regeln": regeln, "updated_at": datetime.now(timezone.utc).isoformat()})
        except Exception as e:
            return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
        _eh["at"] = 0.0                # nächster Schleifendurchlauf nimmt den Schalter sofort
        print(f"[echo-hedge] Schalter {'AN' if body['echo_hedge'] else 'AUS'} ({uid})", flush=True)
        return jsonify({"ok": True, "echo_hedge": eh_stand(regeln)})
    if "apex_hedge" in body:          # APEX-CHALLENGE-WD-HEDGE (30.10.2026): nur regeln.apex_hedge.an — eigener Schalter
        if not isinstance(body["apex_hedge"], bool):
            return jsonify({"ok": False, "msg": "apex_hedge = true | false"}), 400
        ah_roh = regeln.get("apex_hedge") if isinstance(regeln.get("apex_hedge"), dict) else {}
        regeln["apex_hedge"] = dict(ah_roh, an=body["apex_hedge"])
        try:
            sb_update("auto_plan_regeln", {"id": "eq.1"}, {"regeln": regeln, "updated_at": datetime.now(timezone.utc).isoformat()})
        except Exception as e:
            return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
        _ah["at"] = 0.0
        print(f"[apex-hedge] Schalter {'AN' if body['apex_hedge'] else 'AUS'} ({uid})", flush=True)
        return jsonify({"ok": True, "apex_hedge": ah_stand(regeln)})
    if "tradeify_final_hedge" in body:   # FINALER TRADEIFY MIT GEGENHEDGE (Finn/Master 30.10.2026): nur regeln.tradeify_final_hedge.an — aus =
        if not isinstance(body["tradeify_final_hedge"], bool):   # Final-Trades werden weiter gehalten (Halte-Riegel)
            return jsonify({"ok": False, "msg": "tradeify_final_hedge = true | false"}), 400
        tf_roh = regeln.get("tradeify_final_hedge") if isinstance(regeln.get("tradeify_final_hedge"), dict) else {}
        regeln["tradeify_final_hedge"] = dict(tf_roh, an=body["tradeify_final_hedge"])
        try:
            sb_update("auto_plan_regeln", {"id": "eq.1"}, {"regeln": regeln, "updated_at": datetime.now(timezone.utc).isoformat()})
        except Exception as e:
            return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
        _tfh["at"] = 0.0
        print(f"[tradeify-hedge] Schalter {'AN' if body['tradeify_final_hedge'] else 'AUS'} ({uid})", flush=True)
        return jsonify({"ok": True, "tradeify_final_hedge": tfh_stand(regeln)})
    if "tradeify_final_hedge_firma" in body:   # LF1 (Finn 06.11.2026): Zusatz-Firma (Lucid) in den Final-Weg — regeln.tradeify_final_hedge.firmen;
        tf_f = body["tradeify_final_hedge_firma"]   # der Hauptschalter .an bleibt, Tradeify ist immer drin
        if not (isinstance(tf_f, dict) and tf_f.get("firma") in TFH_FIRMEN_ERLAUBT and tf_f.get("firma") != "tradeify"
                and isinstance(tf_f.get("an"), bool)):
            return jsonify({"ok": False, "msg": "tradeify_final_hedge_firma = {firma: lucid, an: true | false}"}), 400
        tf_roh = regeln.get("tradeify_final_hedge") if isinstance(regeln.get("tradeify_final_hedge"), dict) else {}
        alt = [k for k in tfh_param(regeln)["firmen"] if k != "tradeify"]
        neu_f = sorted((set(alt) | {tf_f["firma"]}) if tf_f["an"] else (set(alt) - {tf_f["firma"]}))
        regeln["tradeify_final_hedge"] = dict(tf_roh, firmen=["tradeify"] + neu_f)
        try:
            sb_update("auto_plan_regeln", {"id": "eq.1"}, {"regeln": regeln, "updated_at": datetime.now(timezone.utc).isoformat()})
        except Exception as e:
            return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
        _tfh["at"] = 0.0
        print(f"[tradeify-hedge] Firma {tf_f['firma']} {'AN' if tf_f['an'] else 'AUS'} ({uid})", flush=True)
        return jsonify({"ok": True, "tradeify_final_hedge": tfh_stand(regeln)})
    neu = dict(ap_ausgleich_param(regeln))
    for k in ("aktiv", "auto_start"):
        if k in body:
            if not isinstance(body[k], bool):
                return jsonify({"ok": False, "msg": f"{k} = true | false"}), 400
            neu[k] = body[k]
    for k, lo, hi in (("takt_min", 2, 120), ("zielband_pct", 1, 100), ("gross_ab_eur", 0, 100000), ("laufzeit_min", 30, 1440)):
        if k in body:
            v = _wd_num(body[k])
            if v is None or isinstance(body[k], bool) or not (lo <= v <= hi):
                return jsonify({"ok": False, "msg": f"{k} = {lo}–{hi}"}), 400
            neu[k] = int(v) if k in ("takt_min", "laufzeit_min") else round(v, 1)
    regeln["ausgleich"] = neu
    try:
        sb_update("auto_plan_regeln", {"id": "eq.1"}, {"regeln": regeln, "updated_at": datetime.now(timezone.utc).isoformat()})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
    _ap_bot["param"], _ap_bot["gelesen"] = ap_ausgleich_param(regeln), time.time()
    return jsonify({"ok": True, "ausgleich": neu, "bot": _ap_bot_stand(neu)})


