def ap_einst_wert(alt, neu, feld):
    """REIN RECHNEND (testbar): neuer Wert für ein vorhandenes Feld → (wert, None) | (None, grund). Gleicher Typ wie alt: Zahl, Spanne [von, bis]
    (von ≤ bis) oder Ja/Nein (nur AP_EINST_SCHALTER); Zahlen in AP_EINST_GRENZEN[feld]. Unbekanntes Feld oder anderer Typ → nie."""
    if feld in AP_EINST_SCHALTER:
        return (neu, None) if isinstance(alt, bool) and isinstance(neu, bool) else (None, f"{feld} = true | false")
    if feld in AP_EINST_UHR:
        u = ap_einst_uhr(neu)
        return (u, None) if isinstance(alt, str) and u else (None, f"{feld} = Uhrzeit HH:MM")
    if feld not in AP_EINST_GRENZEN:
        return None, f"{feld} ist hier nicht änderbar"
    lo, hi = AP_EINST_GRENZEN[feld]

    def zahl(x, wie):
        v = None if isinstance(x, bool) else _wd_num(x)
        if v is None or not (lo <= v <= hi):
            return None
        if isinstance(wie, int) and not float(v).is_integer() and feld in AP_EINST_GANZ:
            return None                     # ganze Kontrakte / Schritt 1 bleiben ganz (S6-Review: 1,5 NQ, falsche Puffer-Stufe)
        return int(v) if isinstance(wie, int) and float(v).is_integer() else v   # ganze Zahl bleibt ganz (gleicher Typ wie bisher)
    if isinstance(alt, (int, float)) and not isinstance(alt, bool):
        v = zahl(neu, alt)
        return (v, None) if v is not None else (None, f"{feld} = Zahl {lo:g}–{hi:g}")
    if isinstance(alt, list) and len(alt) == 2 and all(isinstance(x, (int, float)) and not isinstance(x, bool) for x in alt):
        if not (isinstance(neu, list) and len(neu) == 2):
            return None, f"{feld} = [von, bis]"
        a, b = zahl(neu[0], alt[0]), zahl(neu[1], alt[1])
        if a is None or b is None or a > b:
            return None, f"{feld} = [von, bis], {lo:g}–{hi:g}, von ≤ bis"
        return [a, b], None
    return None, f"{feld}: bisheriger Wert ist weder Zahl noch Spanne — hier nicht änderbar"


def ap_einst_anwenden(firmen, firma, aenderungen):
    """REIN RECHNEND (testbar): firmen[] (Kopie) + Firmen-Schlüssel (namen[0]) + [{pfad:[…], wert}] → (firmen_neu, None) | (None, grund).
    Alles oder nichts; jeder Pfad muss schon existieren (nie neue Schlüssel), Tiefe ≤ AP_EINST_PFAD_MAX."""
    neu = json.loads(json.dumps(firmen or []))
    ziel = next((f for f in neu if isinstance(f, dict) and (f.get("namen") or [None])[0] == firma), None)
    if ziel is None:
        return None, f"Firma {firma!r} nicht in den Kernwerten"
    if not isinstance(aenderungen, list) or not aenderungen or len(aenderungen) > 60:
        return None, "aenderungen = Liste mit 1–60 Einträgen"
    for a in aenderungen:
        pfad = a.get("pfad") if isinstance(a, dict) else None
        if not (isinstance(pfad, list) and 1 <= len(pfad) <= AP_EINST_PFAD_MAX and all(isinstance(x, str) and x for x in pfad)):
            return None, "pfad = Liste von Schlüsseln"
        if pfad[0] in ("namen", "route", "boden", "symbol"):
            return None, f"{pfad[0]} ist hier nicht änderbar"
        if pfad == ["planen"] and "planen" not in ziel:       # Firma an/aus (E3b Zusatz 4): fehlt = an; darf als Ja/Nein angelegt werden
            if not isinstance(a.get("wert"), bool):
                return None, "planen = true | false"
            ziel["planen"] = a["wert"]
            continue
        if pfad[0] == "je_groesse" and len(pfad) >= 3:
            grund = ap_einst_block_anlegen(ziel, pfad[1], pfad[2])
            if grund:
                return None, f"{'/'.join(pfad)}: {grund}"
        knoten = ziel
        for k in pfad[:-1]:
            if not isinstance(knoten, dict) or k not in knoten:
                return None, f"Pfad {'/'.join(pfad)} gibt es nicht"
            knoten = knoten[k]
        letzter = pfad[-1]
        if not isinstance(knoten, dict) or letzter not in knoten:
            return None, f"Pfad {'/'.join(pfad)} gibt es nicht"
        # Grenze nach dem letzten Feld-Namen; Größen-Schlüssel („100000" in kauf_eur) und Phasen einer Zuordnung („phase1" in ziel_pct)
        # nehmen den Namen davor — phasen/phase1/tp bleibt „tp"
        zuord = lambda k: k.isdigit() or k in AP_EINST_ZUORDNUNG   # noqa: E731
        feld = letzter if not zuord(letzter) else next((k for k in reversed(pfad[:-1]) if not zuord(k)), letzter)
        wert, grund = ap_einst_wert(knoten[letzter], a.get("wert"), feld)
        if grund:
            return None, f"{'/'.join(pfad)}: {grund}"
        knoten[letzter] = wert
    kette = ziel.get("kette") if isinstance(ziel.get("kette"), dict) else {}
    if all(isinstance(kette.get(k), str) for k in AP_EINST_UHR):       # Kette: Trade 1 bis ≤ Trade 2 ab < Trade 2 bis (E3b)
        t1, t2a, t2b = (_ap_hhmm(kette[k]) for k in AP_EINST_UHR)
        if not (t1 <= t2a < t2b):
            return None, "kette: Trade 1 bis ≤ Trade 2 ab < Trade 2 bis"
    return neu, None


# GRÖSSE OHNE EIGENEN BLOCK (E3f, Nachtrag 9, Finn: „Es gibt immer ‚Standard‘ — lass das weg … einfach immer nur die Schablonen"): die
# Einstellungen zeigen nur echte Größen. Speichert man an einer Größe einen Wert, den sie noch von der Firma erbt, legt das Speichern
# je_groesse[g][feld] als Kopie des Firmenwerts an (ganzes Feld — phasen bzw. ziel_pct —, weil der Planer je Größe flach mischt:
# dict(regel, **je_groesse[g]); ein halber phasen-Block würde die übrigen Phasen verdrängen) und ändert nur dort. Andere Größen bleiben,
# wie sie sind. Teilen ALLE Größen die Firmenwerte (kein je_groesse), schreibt das Frontend direkt in die Firmenwerte (Hinweis „gilt auch für …").
AP_EINST_BLOCK_FELDER = ("phasen", "ziel_pct", "dd_usd", "dd_pct", "daily_usd", "tp_max", "max_konten_tag")


def ap_einst_block_anlegen(firma, g, feld):
    """REIN RECHNEND (testbar, ändert firma): je_groesse[g][feld] aus dem Firmenwert anlegen, falls es fehlt → None | grund.
    Nur echte Größen der Firma (groessen/wert_groessen), nur AP_EINST_BLOCK_FELDER, die die Firma selbst trägt. Größe außerhalb von
    standard_groessen ohne eigenen Block → nie (ap_regel_flex: dort „Werte fehlen" — eine Kopie legte die Werte einer anderen Größe darauf)."""
    gr = {str(int(float(x))) for x in list(firma.get("groessen") or []) + list(firma.get("wert_groessen") or []) if _wd_num(x)}
    je = firma.get("je_groesse") if isinstance(firma.get("je_groesse"), dict) else None
    blk = (je or {}).get(g)
    if isinstance(blk, dict) and feld in blk:
        return None                                   # gibt es schon — normaler Pfad
    if g not in gr:
        return f"{g} ist keine Größe der Firma"
    if feld not in AP_EINST_BLOCK_FELDER or feld not in firma:
        return f"{feld} kann je Größe nicht angelegt werden"
    std = {str(int(float(x))) for x in (firma.get("standard_groessen") or []) if _wd_num(x)}
    if std and g not in std and not isinstance(blk, dict):
        return f"{int(g) // 1000}k ist keine Standard-Größe — Werte für diese Größe legt Finn an"
    if isinstance(blk, dict) and feld == "phasen":
        # Block ohne phasen = der Planer plant diese Größe nicht (ap_konto_rechnen: keine Regel für die Phase) — nicht still einschalten
        return f"{int(g) // 1000}k hat keine eigenen Phasen-Werte — die Größe plant der Planer nicht"
    if not isinstance(blk, dict):
        # NEUER BLOCK (Prüfer-Stopp E3f): ein vorhandener Block ersetzt im Planer die Phasen (ap_konto_rechnen, ap_boden_konto, zw_ziel — kein
        # Rückfall) und der Boden nimmt dann nicht mehr den DD je Größe aus ap_kw_param. Darum immer die vollen Firmen-Phasen mitkopieren und,
        # wenn die Kernwerte für die Größe einen eigenen DD kennen, auch dd_usd — dann rechnet der Planer genau wie vorher. Skalierte Firmen
        # (The5ers: Phasen in 100k-Einheiten × Größe ÷ 100k, Block-Werte unskaliert) nur bei 100k, wo der Faktor 1 ist.
        if firma.get("skaliert") and g != "100000":
            return f"{int(g) // 1000}k: skalierte Firma — Werte je Größe legt Finn an"
        if not isinstance(firma.get("phasen"), dict) or not firma["phasen"]:
            return "Firma ohne Phasen — kein Block je Größe"
        neu_blk = {"phasen": json.loads(json.dumps(firma["phasen"]))}
        ddg = ((ap_kw_param(firma) or {}).get("dd_je_groesse") or {}).get(g)
        if _wd_num(ddg) and "dd_usd" not in neu_blk:
            neu_blk["dd_usd"] = float(ddg)
        if je is None:
            je = firma["je_groesse"] = {}
        je[g] = neu_blk
    if feld not in je[g]:
        je[g][feld] = json.loads(json.dumps(firma[feld]))
    return None


def ap_einst_uhr(x):
    """REIN RECHNEND: „H:MM“/„HH:MM“ (00:00–23:59) → „HH:MM“, sonst None."""
    m = re.match(r"^(\d{1,2}):(\d{2})$", str(x or "").strip()) if isinstance(x, str) else None
    if not m or int(m.group(1)) > 23 or int(m.group(2)) > 59:
        return None
    return f"{int(m.group(1)):02d}:{m.group(2)}"


# ZEITEN (Spalte auto_plan_regeln.zeiten, E3b 05.11.2026): erlaubte Pfade → Art. Uhrzeiten nur die Uhr, die Zeitzone bleibt.
AP_EINST_ZEITEN = {
    ("nachtlauf", "uhr"): "uhr", ("cfd_ab", "uhr"): "uhr", ("cfd_bis", "uhr"): "uhr", ("neu_bis", "uhr"): "uhr", ("start_bis",): "uhr",
    # abstand_id_min ab 1: die Leser rechnen „or 3" — 0 würde still zu 3 (S6-Review E3b). pause_firma_min liest der Planer seit 06.10.2026 nicht
    # mehr (_ap_zeiten_verteilen_einmal) — darum weder Anzeige noch Schreibweg.
    ("abstand_id_min",): ("zahl", 1.0, 30.0), ("abstand_konto_s",): ("spanne", 0.0, 900.0),
}
AP_EINST_BESTAETIGEN = {"aus": False, "cfd": "cfd", "alle": True}   # regeln.auto_bestaetigen (ap_auto_best_umfang)
# Zahlen in den Regel-Blöcken (E3b Nachtrag 2, Finn: „Winning Days als Beispiel … alle wichtigen Sachen kann ich anpassen"): Block → Feld →
# (min, max, ganz). Fehlt das Feld im Block, legt es das Speichern an (die Leser eh_param/ah_param/tfh_param/ap_ausgleich_param nehmen sonst
# ihren Standard). Die An/Aus-Schalter der Hedge-Wege und des Ausgleich-Bots bleiben bei POST /ausgleich-einstellung.
# Grenzen GENAU wie die Leser (eh_param/tfh_param/ah_param verwerfen sonst still und nehmen den Standard — S6-Review E3b Befund 1)
_AP_EINST_HEDGE = {"vorlauf_min": (3.0, 120.0, False), "nachlauf_min": (0.0, 60.0, False), "netto_faktor": (0.5, 1.0, False), "min_lot": (0.01, 1.0, False)}
AP_EINST_BLOECKE = {
    "echo_hedge": dict(_AP_EINST_HEDGE, max_lots=(1.0, 1000.0, False)), "apex_hedge": dict(_AP_EINST_HEDGE),
    "tradeify_final_hedge": dict(_AP_EINST_HEDGE, max_lots=(1.0, 1000.0, False)),
    "ausgleich": {"takt_min": (2, 120, True), "zielband_pct": (1.0, 100.0, False), "gross_ab_eur": (0.0, 100000.0, False),
                  "laufzeit_min": (30, 1440, True), "waage_max_abstand": (1.0, 20.0, False)},   # waage_max_abstand liest auch der DB-Claim-Riegel
}
AP_EINST_REGEL_SCHALTER = {("abhaken_auto_normal",), ("abhaken_auto_blow",), ("tradeify_final_halten",), ("ausgleich", "waage_deckel_an")}


def ap_einst_zeiten_anwenden(zeiten, aenderungen):
    """REIN RECHNEND (testbar): zeiten (Kopie) + [{pfad, wert}] → (zeiten_neu, None) | (None, grund). Alles oder nichts.
    Pfade aus AP_EINST_ZEITEN plus Start-Fenster ["fenster", "<i>", "0"|"1"] (von/bis eines vorhandenen Fensters, Anteil bleibt).
    Fehlt nachtlauf/neu_bis, legt die Uhr sie mit der Standard-Zeitzone an (die Anzeige zeigte bisher den Standard). Danach: jedes Fenster
    von < bis, CFD ab < CFD bis (gleiche Zeitzone)."""
    neu = json.loads(json.dumps(zeiten if isinstance(zeiten, dict) else {}))
    if not isinstance(aenderungen, list) or not aenderungen or len(aenderungen) > 30:
        return None, "zeiten = Liste mit 1–30 Einträgen"
    for a in aenderungen:
        pfad = a.get("pfad") if isinstance(a, dict) else None
        if not (isinstance(pfad, list) and pfad and all(isinstance(x, str) and x for x in pfad)):
            return None, "pfad = Liste von Schlüsseln"
        txt, w = "/".join(pfad), a.get("wert")
        if pfad[0] == "fenster" and len(pfad) == 3 and pfad[1].isdigit() and pfad[2] in ("0", "1"):
            fl = neu.get("fenster")
            i = int(pfad[1])
            if not (isinstance(fl, list) and i < len(fl) and isinstance(fl[i], list) and len(fl[i]) >= 2):
                return None, f"{txt}: Fenster gibt es nicht"
            u = ap_einst_uhr(w)
            if not u:
                return None, f"{txt} = Uhrzeit HH:MM"
            fl[i][int(pfad[2])] = u
            continue
        art = AP_EINST_ZEITEN.get(tuple(pfad))
        if art is None:
            return None, f"{txt} ist hier nicht änderbar"
        if art == "uhr":
            u = ap_einst_uhr(w)
            if not u:
                return None, f"{txt} = Uhrzeit HH:MM"
            if len(pfad) == 1:
                neu[pfad[0]] = u
                continue
            knoten = neu.get(pfad[0])
            if isinstance(knoten, str) and pfad[0] in ("cfd_ab", "cfd_bis"):
                neu[pfad[0]] = u                     # alte Form „HH:MM" deutscher Zeit bleibt dieselbe Form
                continue
            if not isinstance(knoten, dict):
                if pfad[0] == "nachtlauf":
                    knoten = neu[pfad[0]] = {"tz": AP_NACHT_STANDARD["tz"]}
                elif pfad[0] == "neu_bis":
                    knoten = neu[pfad[0]] = {"tz": AP_NEU_BIS_STANDARD["tz"]}
                else:
                    return None, f"{txt} gibt es nicht"
            knoten["uhr"] = u
            continue
        kind, lo, hi = art
        alt = neu.get(pfad[0])
        if alt is None:
            return None, f"{txt} gibt es nicht"
        ok = lambda x: not isinstance(x, bool) and isinstance(x, (int, float)) and lo <= x <= hi   # noqa: E731
        if kind == "zahl":
            if not ok(w):
                return None, f"{txt} = Zahl {lo:g}–{hi:g}"
            neu[pfad[0]] = int(w) if isinstance(alt, int) and float(w).is_integer() else w
        else:
            if not (isinstance(alt, list) and len(alt) == 2):
                return None, f"{txt}: bisheriger Wert ist keine Spanne"
            if not (isinstance(w, list) and len(w) == 2 and ok(w[0]) and ok(w[1]) and w[0] <= w[1]):
                return None, f"{txt} = [von, bis], {lo:g}–{hi:g}, von ≤ bis"
            neu[pfad[0]] = [int(x) if float(x).is_integer() and all(isinstance(y, int) for y in alt) else x for x in w]
    for i, f in enumerate(neu.get("fenster") or ()):
        if isinstance(f, list) and len(f) >= 2 and ap_einst_uhr(f[0]) and ap_einst_uhr(f[1]) and _ap_hhmm(f[0]) >= _ap_hhmm(f[1]):
            return None, f"Start-Fenster {i + 1}: von < bis"
    ca, cb = neu.get("cfd_ab"), neu.get("cfd_bis")
    if isinstance(ca, dict) and isinstance(cb, dict) and ca.get("tz") == cb.get("tz") and ap_einst_uhr(ca.get("uhr")) and ap_einst_uhr(cb.get("uhr")) \
            and _ap_hhmm(ca["uhr"]) >= _ap_hhmm(cb["uhr"]):
        return None, "CFD: ab < bis"
    return neu, None


def ap_einst_regeln_anwenden(regeln, zufall=None, auto_bestaetigen=None, bloecke=None, schalter=None):
    """REIN RECHNEND (testbar): regeln (Kopie) + Zufall-Parameter {k: wert} + auto_bestaetigen ("aus"|"cfd"|"alle") + bloecke {block: {feld:
    zahl}} (AP_EINST_BLOECKE) + schalter [{pfad, wert: bool}] (AP_EINST_REGEL_SCHALTER) → (regeln_neu, None) | (None, grund). Alles oder nichts.
    Zufall: nur AP_ZUFALL_FELDER, Typ/Grenzen ap_zufall_pruefen; regeln.zufall wird angelegt, wenn es fehlt."""
    neu = json.loads(json.dumps(regeln if isinstance(regeln, dict) else {}))
    if bloecke is not None:
        if not isinstance(bloecke, dict) or not bloecke:
            return None, "bloecke = {Block: {Feld: Zahl}}"
        for blk, werte in bloecke.items():
            erlaubt = AP_EINST_BLOECKE.get(blk)
            if erlaubt is None or not isinstance(werte, dict) or not werte:
                return None, f"{blk} ist hier nicht änderbar"
            ziel = neu.get(blk) if isinstance(neu.get(blk), dict) else {}
            for k, v in werte.items():
                if k not in erlaubt:
                    return None, f"{blk}/{k} ist hier nicht änderbar"
                lo, hi, ganz = erlaubt[k]
                if isinstance(v, bool) or not isinstance(v, (int, float)) or v != v or not (lo <= v <= hi) or (ganz and not float(v).is_integer()):
                    return None, f"{blk}/{k} = {'ganze Zahl' if ganz else 'Zahl'} {lo:g}–{hi:g}"
                ziel[k] = int(v) if ganz else v
            neu[blk] = ziel
    if schalter is not None:
        if not isinstance(schalter, list) or not schalter:
            return None, "schalter = [{pfad, wert}]"
        for x in schalter:
            pfad = tuple(x.get("pfad") or ()) if isinstance(x, dict) and isinstance(x.get("pfad"), list) else ()
            if pfad not in AP_EINST_REGEL_SCHALTER or not isinstance(x.get("wert"), bool):
                return None, f"{'/'.join(map(str, pfad)) or '?'} = true | false (nur {', '.join('/'.join(q) for q in sorted(AP_EINST_REGEL_SCHALTER))})"
            if len(pfad) == 1:
                neu[pfad[0]] = x["wert"]
            else:
                blk = neu.get(pfad[0]) if isinstance(neu.get(pfad[0]), dict) else {}
                blk[pfad[1]] = x["wert"]
                neu[pfad[0]] = blk
    if zufall is not None:
        if not isinstance(zufall, dict) or not zufall:
            return None, "zufall = {Schlüssel: Wert}"
        z = neu.get("zufall") if isinstance(neu.get("zufall"), dict) else {}
        for k, v in zufall.items():
            w, grund = ap_zufall_pruefen(k, v)
            if grund:
                return None, f"zufall/{k}: {grund}"
            z[k] = w
        neu["zufall"] = z
    if auto_bestaetigen is not None:
        if auto_bestaetigen not in AP_EINST_BESTAETIGEN:
            return None, "auto_bestaetigen = aus | cfd | alle"
        neu["auto_bestaetigen"] = AP_EINST_BESTAETIGEN[auto_bestaetigen]
    return neu, None


# FIRMEN-REGELN (E3b, Finn: „eine Info wie bei den Regeln der Props, wo der Drawdown drin ist und was als Take Profit zählt"): die passenden
# Abschnitte aus firm_rules.json (gleiche Quelle wie „Regeln der Props"), nur zur Anzeige. Planer-Firma → id in firm_rules.json.
AP_REGEL_INFO_ID = {"tradeify": "tradeify", "apextrader": "apex", "fundednext": "fundednext", "fundingpips": "fundingpips",
                    "the5ers": "the5ers", "topstep": "topstep", "ftmo": "ftmo"}
AP_REGEL_INFO_ABSCHNITTE = (("Daily Loss", r"daily loss|\bdll\b"), ("Drawdown", r"drawdown|max loss|\bmll\b"), ("Ziel", r"profit.?target"),
                            ("Consistency", r"consisten|best day"), ("Zeit & Mindesttage", r"time.?rules"))
_ap_regel_info_cache = {}


def ap_regel_info_abschnitte(md, max_zeichen=2400):
    """REIN RECHNEND: Markdown einer Firma → [{gruppe, kopf, text}] — je „### …“-Abschnitt, dessen Kopf zu einer Gruppe passt (erste Gruppe gewinnt)."""
    teile, kopf, zeilen = [], None, []
    for z in (str(md or "") + "\n### ").splitlines():
        if z.startswith("### ") or z.startswith("## "):
            if kopf is not None:
                for gruppe, muster in AP_REGEL_INFO_ABSCHNITTE:
                    if re.search(muster, kopf, re.I):
                        txt = "\n".join(zeilen).strip()
                        teile.append({"gruppe": gruppe, "kopf": kopf, "text": txt[:max_zeichen] + (" …" if len(txt) > max_zeichen else "")})
                        break
            kopf, zeilen = (z[4:].strip() if z.startswith("### ") else None), []
        else:
            zeilen.append(z)
    rang = {g: i for i, (g, _m) in enumerate(AP_REGEL_INFO_ABSCHNITTE)}
    return sorted(teile, key=lambda t: rang[t["gruppe"]])


def ap_regel_info():
    """firm_rules.json (neben app.py) → {planer_firma: {name, id, updated_at, abschnitte}} — je Dateistand einmal gelesen."""
    pfad = os.path.join(os.path.dirname(os.path.abspath(__file__)), "firm_rules.json")
    try:
        mt = os.path.getmtime(pfad)
    except OSError:
        return {}
    if _ap_regel_info_cache.get("mt") != mt:
        with open(pfad, encoding="utf-8") as fh:
            d = json.load(fh)
        je = {str(f.get("id")): f for f in (d.get("firms") or []) if isinstance(f, dict)}
        _ap_regel_info_cache.update(mt=mt, daten={k: {"id": i, "name": je[i].get("name"), "updated_at": je[i].get("updated_at"),
                                                          "abschnitte": ap_regel_info_abschnitte(je[i].get("rules_markdown"))}
                                                       for k, i in AP_REGEL_INFO_ID.items() if i in je})
    return _ap_regel_info_cache["daten"]


@app.route("/admin/auto-plan/einstellungen", methods=["GET", "OPTIONS"])
def admin_auto_plan_einstellungen():
    """GET → {ok, admin, firmen, zeiten, aktiv, schalter, echo_hedge, apex_hedge, tradeify_final_hedge, ausgleich, fest, updated_at} — nur lesen.
    Nur Admin oder eine ID im Auto-Planer (HT): Verwalter-Gruppen sehen die HT-weiten Kernwerte nicht (S6-Review E3)."""
    if request.method == "OPTIONS":
        return "", 200
    admin, uid, reg, err = _ap_zugang()
    unt, err = _ap_einst_unternehmen(admin, uid, reg, err)
    if err:
        return err
    zeile = None
    if unt:
        zeile = (sb_select("auto_plan_gruppe", {"select": "*", "gruppe_id": f"eq.{unt}"}) or [None])[0]
        if not zeile:
            return jsonify({"ok": False, "msg": "Unternehmen ohne Planer-Zeile"}), 404
        reg = ap_reg_unternehmen(reg, zeile)
    regeln = reg.get("regeln") if isinstance(reg.get("regeln"), dict) else {}
    zeiten = reg.get("zeiten") if isinstance(reg.get("zeiten"), dict) else {}

    def sicher(fn):
        try:
            return fn(regeln)
        except Exception as e:
            return {"fehler": f"{type(e).__name__}: {e}"}
    tz_neu, min_neu = ap_nachplan_neu_bis(zeiten)
    out = {"ok": True, "admin": bool(admin), "updated_at": reg.get("updated_at"), "aktiv": reg.get("aktiv") is True,
           "firmen": regeln.get("firmen") if isinstance(regeln.get("firmen"), list) else [],
           "zeiten": dict(zeiten, nachtlauf=ap_nacht_param(zeiten), neu_bis={"tz": tz_neu, "uhr": f"{min_neu // 60:02d}:{min_neu % 60:02d}"}),
           "schalter": {"auto_bestaetigen": ap_auto_best_umfang(regeln), "abhaken_auto_normal": regeln.get("abhaken_auto_normal") is True,
                        "abhaken_auto_blow": regeln.get("abhaken_auto_blow") is True, "tradeify_final_halten": regeln.get("tradeify_final_halten") is True},
           "echo_hedge": sicher(eh_param), "apex_hedge": sicher(ah_param), "tradeify_final_hedge": sicher(tfh_param),
           "ausgleich": sicher(ap_ausgleich_param), "fest": ap_einst_fest(),
           # ORBIT PRIO 2 (MO1): wirksames Modell je Futures-Firma der HT-Regel (ohne Feld: Apex → orbit_prio2, sonst orbit_v2)
           "modelle": {(f.get("namen") or [""])[0]: ap_firma_modell(f, None) for f in (regeln.get("firmen") or []) if isinstance(f, dict)},
           "modell_namen": AP_MODELL_NAME,
           # MO1b: Modelle je Verwalter-Gruppe (auto_plan_gruppe.firmen_modell; spalte False = SQL noch nicht eingespielt) — nur für Admins
           "gruppen_modelle": ap_gruppen_modell_sicht(regeln.get("firmen") or []) if admin else [],
           "modell_nicht": {},   # TM1: Tradeify wählbar (Prio 2 nur nicht-finale Trades); Schlüssel bleibt fürs Frontend (Topstep-Grund kommt aus der Route)
           # E3b: Zufall-Parameter (wirksam, Code-Rückfall, welche aus der Tabelle) + Firmen-Regeln aus firm_rules.json
           "zufall": ap_zufall(regeln), "zufall_code": ap_zufall_code(),
           "zufall_db": sorted(k for k, v in (regeln.get("zufall") or {}).items() if ap_zufall_pruefen(k, v)[1] is None)
           if isinstance(regeln.get("zufall"), dict) else [],
           "zeiten_db": zeiten, "regel_info": sicher(lambda _r: ap_regel_info()),
           # WS2 Trades pro Tag (09.11.2026): wirksame Werte (tt_param) + Häkchen je Challenge-Firma; tagesteilung_db = Block steht in der DB (SQL eingespielt)
           "tagesteilung": sicher(tt_param),
           "tagesteilung_firmen": sicher(lambda r: tt_firmen_auswahl(r.get("firmen") or [], tt_param(r))),
           "tagesteilung_gruppen": sicher(lambda r: tt_gruppen_auswahl(admin_gruppen_daten().get("gruppen") or [], tt_param(r))),
           # TT1 (11.11.2026): HT-Planer-IDs für die Häkchen „Test-IDs“ (Echo-Konten je ID zählt die Seite aus /konten-stand)
           "tagesteilung_ids": (sicher(lambda r: tt_ids_auswahl(reg.get("user_ids") or [], _ap_namen()[0], tt_param(r))) if (admin and not unt) else []),
           "tagesteilung_db": isinstance(regeln.get("tagesteilung"), dict)}
    if unt:
        namen_g = {str(g.get("id")): g.get("name") for g in admin_gruppen_daten().get("gruppen") or ()}
        fm = zeile.get("firmen_modell") if isinstance(zeile.get("firmen_modell"), dict) else {}
        modelle = {(f.get("namen") or [""])[0]: ap_firma_modell(f, None) for f in (regeln.get("firmen") or []) if isinstance(f, dict)}
        out.update(admin=bool(admin), gruppe_darf=True, unt_felder=list(AP_UNT_FELDER), modelle=modelle,
                   abweichung=ap_unt_abweichung_liste(zeile.get("regeln"), fm),
                   unternehmen={"gruppe_id": unt, "name": namen_g.get(unt), "aktiv": zeile.get("aktiv") is True,
                                "spalte_regeln": "regeln" in zeile, "spalte_modell": "firmen_modell" in zeile},
                   gruppe_sicht={"gruppe_id": unt, "name": namen_g.get(unt), "aktiv": zeile.get("aktiv") is True, "spalte": "firmen_modell" in zeile},
                   gruppen_modelle=[{"gruppe_id": unt, "name": namen_g.get(unt), "spalte": "firmen_modell" in zeile, "modelle": modelle,
                                     "an": {(f.get("namen") or [""])[0]: f.get("planen") is not False for f in (regeln.get("firmen") or []) if isinstance(f, dict)}}])
    if admin:
        try:
            out["unternehmen_liste"] = [{"gruppe_id": None, "name": "Hermann Technologies (Standard)"}] + \
                [{"gruppe_id": str(g["gruppe_id"]), "name": g.get("name")} for g in ap_planer_gruppen()]
        except Exception as e:
            print(f"[einstellungen] ⚠️ Unternehmen-Liste: {type(e).__name__}: {e}", flush=True)
    resp = jsonify(json.loads(json.dumps(out, default=str)))
    resp.headers["Cache-Control"] = "no-store"
    return resp


def _ap_unt_zugang(gid):
    """Schreibrecht auf die Regel eines Unternehmens (Verwalter-Gruppe) → (uid, reg, zeile, None) | (…, Fehler). Admin oder Verwalter GENAU dieser Gruppe
    (wie die übrigen Gruppen-Felder, /admin/gruppen-plan). zeile ohne Spalte regeln → 503 (sql/2026-11-05_regel_unternehmen.sql)."""
    admin, uid, reg, err = _ap_zugang()
    if err and (not uid or err[1] != 403):
        return uid, None, None, err
    if not reg:
        return uid, None, None, (jsonify({"ok": False, "msg": "auto_plan_regeln fehlt"}), 503)
    if not admin:
        eigene = {str(g.get("id")) for g in admin_gruppen_daten().get("gruppen") or () if g.get("verwalter_id") and str(g["verwalter_id"]) == str(uid)}
        if str(gid) not in eigene:
            return uid, None, None, (jsonify({"ok": False, "msg": "Nur der Verwalter dieses Unternehmens (oder Admin)"}), 403)
    zeile = (sb_select("auto_plan_gruppe", {"select": "*", "gruppe_id": f"eq.{gid}"}) or [None])[0]
    if not zeile:
        return uid, None, None, (jsonify({"ok": False, "msg": "Unternehmen ohne Planer-Zeile"}), 404)
    # Spalte regeln fehlt (SQL noch nicht eingespielt): Firma an/aus + Modell gehen über firmen_modell trotzdem; eine Abweichung je Feld meldet
    # der Schreibweg klar mit AP_UNT_NICHT_FREI (Master 05.11.2026: statt rohem 400/503-Text)
    return uid, reg, zeile, None


@app.route("/admin/auto-plan/kernwert", methods=["POST", "OPTIONS"])
def admin_auto_plan_kernwert():
    """POST {firma: namen[0], aenderungen: [{pfad: [...], wert}]} → regeln.firmen[] (nur vorhandene Felder, s. ap_einst_anwenden). Nur Admin."""
    if request.method == "OPTIONS":
        return "", 200
    _gs = _planer_schreib_gate()
    if _gs is not None:
        return _gs
    body = request.get_json(silent=True) or {}
    if body.get("gruppe_id"):
        # REGEL JE UNTERNEHMEN (Phase 1): nur die Abweichung der Gruppe ändern (ap_unt_kernwert), der Standard bleibt
        gid = str(body.get("gruppe_id"))
        uid, reg, zeile, err = _ap_unt_zugang(gid)
        if err:
            return err
        abw, fm, f_neu, grund = ap_unt_kernwert((reg.get("regeln") or {}).get("firmen"), zeile.get("regeln"), zeile.get("firmen_modell"),
                                                str(body.get("firma") or ""), body.get("aenderungen") or [], body.get("standard") or [])
        if grund:
            return jsonify({"ok": False, "msg": grund}), 400
        if "regeln" not in zeile and abw:
            return jsonify({"ok": False, "msg": AP_UNT_NICHT_FREI, "code": "unt_nicht_frei"}), 409
        jetzt_iso = datetime.now(timezone.utc).isoformat()
        g_flt, g_upd = ap_unt_stempel(zeile, jetzt_iso)       # gleichzeitiges Speichern (Modell-Dropdown, zweiter Tab) überschreibt sich nicht
        upd = dict({"regeln": abw, "updated_at": jetzt_iso} if "regeln" in zeile else {"updated_at": jetzt_iso}, **g_upd)
        if "firmen_modell" in zeile:
            upd["firmen_modell"] = fm
        elif fm != (zeile.get("firmen_modell") or {}):
            return jsonify({"ok": False, "msg": "Spalte firmen_modell fehlt — sql/2026-11-05_orbit_prio2.sql einspielen"}), 503
        flt = dict({"gruppe_id": f"eq.{gid}"}, **g_flt)
        try:
            rows = sb_update("auto_plan_gruppe", flt, upd)
        except Exception as e:
            return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
        if not rows:
            return jsonify({"ok": False, "msg": "inzwischen geändert — Einstellungen neu laden und noch einmal speichern"}), 409
        ap_gruppe_regel_geaendert(gid, jetzt_iso)   # NP1
        print(f"[einstellungen] Unternehmen {gid[:8]} {body.get('firma')}: {len(body.get('aenderungen') or [])} geändert, "
              f"{len(body.get('standard') or [])} auf Standard ({uid})", flush=True)
        # UNT3 Fremd-Review: Max DD/Daily je Unternehmen ändern die Kernwerte, nicht die Konten — accounts.max_drawdown bleibt (Radar-Boden, und
        # Orbit Prio 2 stoppt bei „Max DD am Konto ≠ Kernwerte"). Hinweis statt stillem Auseinanderlaufen.
        hinweis = None
        if any(isinstance(a, dict) and isinstance(a.get("pfad"), list) and a["pfad"] and a["pfad"][-1] in ("dd_usd", "dd_pct", "daily_usd")
               for a in (body.get("aenderungen") or [])):
            hinweis = ("Max DD/Daily gilt für Planer, Kontowert und Boden — die Konten behalten ihr Max DD (Accounts): bitte dort gleich setzen, "
                       "sonst stoppt Orbit Prio 2 mit „Max DD am Konto ≠ Kernwerte\"")
        return jsonify({"ok": True, "firma": f_neu, "abweichung": ap_unt_abweichung_liste(abw, fm), "hinweis": hinweis})
    admin, uid, reg, err = _ap_zugang()
    if err:
        return err
    if not admin:
        return jsonify({"ok": False, "msg": "Nur für Admins"}), 403
    regeln = dict(reg.get("regeln") or {})
    neu, grund = ap_einst_anwenden(regeln.get("firmen"), str(body.get("firma") or ""), body.get("aenderungen"))
    if grund:
        return jsonify({"ok": False, "msg": grund}), 400
    regeln["firmen"] = neu
    try:
        sb_update("auto_plan_regeln", {"id": "eq.1"}, {"regeln": regeln, "updated_at": datetime.now(timezone.utc).isoformat()})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
    _ap_kw_cache.clear()   # Kontowert/Kernwerte-Antworten (60 s) gleich mit den neuen Werten
    print(f"[einstellungen] Kernwerte {body.get('firma')}: {len(body.get('aenderungen') or [])} Feld(er) geändert ({uid})", flush=True)
    return jsonify({"ok": True, "firma": next((f for f in neu if (f.get('namen') or [None])[0] == body.get("firma")), None)})


def ap_modell_setzen(firmen, firma, modell):
    """REIN RECHNEND (testbar): regeln.firmen mit modell an der Firma namen[0] == firma → (neue Liste, None) | (None, Grund). Nur Futures-Firmen
    (CFD fährt immer Echo mit Hedge, E3: e3ArtVon); Werte AP_MODELLE. Die anderen Felder bleiben unberührt (Kopie, kein Umsortieren)."""
    if modell not in AP_MODELLE:
        return None, "modell = " + " | ".join(AP_MODELLE)
    neu, treffer = [], False
    for f in firmen or []:
        if isinstance(f, dict) and ((f.get("namen") or [None])[0] == firma):
            if f.get("route") in AP_CFD_ROUTEN:          # wie e3ArtVon im Frontend: route mt5/mt5v2 = CFD
                return None, f"CFD-Firma — fährt immer {MODELL_NAME['echo']}"
            if f.get("route") == "tsv2":                 # Topstep V2: eigener Weg in TopstepX, ah_tick nimmt nur tvv2
                return None, f"{MODELL_NAME['topstep_v2']} — eigener Weg, kein Modell wählbar"
            # Tradeify seit TM1 wählbar: Prio 2 nimmt nur die nicht-finalen Trades, der finale bleibt bei tfh_tick (ah_tradeify_final) — nie beide
            f = dict(f, modell=modell)
            treffer = True
        neu.append(f)
    if not treffer:
        return None, f"Firma {firma!r} nicht in den Regeln"
    return neu, None


def ap_waage_schluessel(regel):
    """Teilstrings einer Firma für regeln.ausgleich.waage_ohne: Regel-Schlüssel namen[0] (Planer: firma_key) und der Firmenname klein (DB-Riegel
    prophos_waage_deckel_lage vergleicht mit lower(prophos_firma_key(firm) | firm), z. B. 'lucid trading')."""
    n = ((regel or {}).get("namen") or [""])[0]
    return [k for k in dict.fromkeys([str(n).strip().lower(), str(_firm_norm(n) or "").strip().lower()]) if k]


def ap_waage_ohne_modell(ausgleich, firmen):
    """REIN RECHNEND (testbar): ORBIT PRIO 2 AUS DER WAAGE WIE APEX (MO1b, Master 05.11.2026) → neues regeln.ausgleich: waage_ohne = bisherige Liste
    (fehlt sie: AP_WAAGE_OHNE_FIRMEN) ohne die früher vom Modell gesetzten Einträge (waage_ohne_modell) + Schlüssel jeder HT-Firma mit Modell
    orbit_prio2 außer Apex (steht schon drin). Von Hand gesetzte Einträge bleiben. Dieselbe Liste liest der DB-Claim-Riegel (prophos_waage_deckel_param)."""
    a = dict(ausgleich or {})
    wo = a.get("waage_ohne")
    basis = [str(x).strip().lower() for x in wo if str(x).strip()] if isinstance(wo, list) else list(AP_WAAGE_OHNE_FIRMEN)
    vorher = {str(x).strip().lower() for x in (a.get("waage_ohne_modell") or []) if str(x).strip()}
    basis = [x for x in basis if x not in vorher]
    neu = []
    for f in firmen or []:
        if not isinstance(f, dict) or ap_regel_finden([f], AH_FIRMA) is f or ap_firma_modell(f, None) != "orbit_prio2":
            continue
        neu += [k for k in ap_waage_schluessel(f) if k not in basis and k not in neu]
    a["waage_ohne"] = basis + neu
    a["waage_ohne_modell"] = neu
    return a


def ap_waage_param_gruppe(param, ausgleich_roh, firmen, fm):
    """REIN RECHNEND (testbar): Waage-Parameter für den Lauf EINER Verwalter-Gruppe (MO1b): waage_ohne ohne die Einträge, die das HT-Modell gesetzt hat
    (ausgleich.waage_ohne_modell), plus die Schlüssel der Firmen, die in DIESER Gruppe orbit_prio2 fahren (außer Apex). Der DB-Claim-Riegel wiegt
    Gruppen nicht (prophos_waage_ausgeblendet) — dort wirkt nur dieser Parameter. Ohne Gruppen-Feld (fm leer): nur die HT-Einträge fallen weg."""
    p = dict(param or {})
    ht = {str(x).strip().lower() for x in ((ausgleich_roh or {}).get("waage_ohne_modell") or []) if str(x).strip()}
    try:   # SA1 #8b: auch die beim Laden abgeleiteten HT-Modell-Einträge (ap_ausgleich_param) — sonst wöge die Gruppe HT-Prio-2-Firmen nicht mit
        ht |= {str(x).strip().lower() for x in (ap_waage_ohne_modell(ausgleich_roh, firmen).get("waage_ohne_modell") or []) if str(x).strip()}
    except Exception:
        pass
    ohne = [x for x in (p.get("waage_ohne") or []) if x not in ht]
    for f in firmen or []:
        if isinstance(f, dict) and ap_regel_finden([f], AH_FIRMA) is not f and ap_firma_modell(f, None, fm or {}) == "orbit_prio2":
            ohne += [k for k in ap_waage_schluessel(f) if k not in ohne]
    p["waage_ohne"] = ohne
    return p


def ap_gruppe_modell_setzen(fm, firmen, firma, modell):
    """REIN RECHNEND (testbar): {namen[0]: modell} einer Gruppe → (neue Zuordnung, None) | (None, Grund). Gleiche Grenzen wie die HT-Firma (ap_modell_setzen)."""
    _neu, grund = ap_modell_setzen(firmen, firma, "orbit_v2" if modell == AP_GRUPPE_AUS else modell)   # gleiche Grenzen (CFD/Topstep/Tradeify/unbekannt)
    if grund:
        return None, grund
    return dict({str(k): v for k, v in (fm or {}).items() if v in AP_MODELLE + (AP_GRUPPE_AUS,)}, **{firma: modell}), None


@app.route("/admin/auto-plan/modell", methods=["POST", "OPTIONS"])
def admin_auto_plan_modell():
    """POST {firma: namen[0], modell: orbit_v2 | orbit_prio2} → regeln.firmen[].modell (HT). ORBIT PRIO 2 (MO1, 05.11.2026): ein neues Feld,
    darum nicht über /kernwert (das ändert nur vorhandene). Nur Admin + Planer-Schreibrecht. Verwalter-Gruppen: auto_plan_gruppe.firmen_modell (SQL)."""
    if request.method == "OPTIONS":
        return "", 200
    _gs = _planer_schreib_gate()
    if _gs is not None:
        return _gs
    admin, uid, reg, err = _ap_zugang()
    if err:
        return err
    if not admin:
        return jsonify({"ok": False, "msg": "Nur für Admins"}), 403
    body = request.get_json(silent=True) or {}
    regeln = dict(reg.get("regeln") or {})
    neu, grund = ap_modell_setzen(regeln.get("firmen"), str(body.get("firma") or ""), str(body.get("modell") or ""))
    if grund:
        return jsonify({"ok": False, "msg": grund}), 400
    regeln["firmen"] = neu
    regeln["ausgleich"] = ap_waage_ohne_modell(regeln.get("ausgleich"), neu)   # MO1b: Prio-2-Firmen aus der Waage wie Apex (Planer + DB-Riegel)
    try:
        sb_update("auto_plan_regeln", {"id": "eq.1"}, {"regeln": regeln, "updated_at": datetime.now(timezone.utc).isoformat()})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
    print(f"[einstellungen] Modell {body.get('firma')} → {body.get('modell')} ({uid})", flush=True)
    f = next((x for x in neu if (x.get("namen") or [None])[0] == body.get("firma")), None)
    return jsonify({"ok": True, "firma": f, "modell": ap_firma_modell(f, None), "waage_ohne": regeln["ausgleich"].get("waage_ohne")})


# KONTEN JE FIRMA (E3b Zusatz 4, Finn 05.11.2026: „Genau das Gleiche auch für den Challenge-Planer … mit Zielen, Consistency, alles. Bei
# Tradeify geht's manchmal mit 40 %, manchmal mit 50 %, sodass man auswählen kann"): Kontoliste je Firma mit Ziel-Fortschritt und — wo die
# Firma eine Consistency hat (Futures mit tp_max) — größter Tag ÷ Ziel-$ gegen die Grenze. Nur Lesen, gleiche Quellen wie der Planer
# (acc_balance_wahl, ap_regel_konto, zw_ziel). Consistency je Konto = accounts.consistency_pct (bestehende Logik ap_regel_konto: tp_max =
# pct × Ziel-$); leer = Firmen-Standard, der im TP-Deckel steckt (tp_max ÷ Ziel-$). Ändern: POST /konto-consistency, nur Admin.
_ap_ks_cache = {}
AP_KS_TTL_S = 60


def ap_konten_stand_zeile(a, regel, bal, tage_pl):
    """REIN RECHNEND (testbar): ein Konto → {groesse, balance, ziel, ziel_usd, gewinn, fortschritt, cons_pct, cons_quelle, groesster_tag,
    cons_anteil}. tage_pl = {tag: Summe master_pl} der abgeschlossenen Pläne des Kontos. Ohne Regel/Balance: nur, was bekannt ist."""
    out = {"balance": bal, "groesse": None, "ziel": None, "ziel_usd": None, "gewinn": None, "fortschritt": None,
           "cons_pct": None, "cons_quelle": None, "cons_firma": None, "cons_waehlbar": False, "groesster_tag": None, "cons_anteil": None}
    if not regel or not bal:
        return out
    rk = ap_regel_konto(regel, a, float(bal))
    z = zw_ziel(rk, a.get("account_type"), float(bal))
    if not z:
        return out
    ziel, groesse = z
    ziel_usd = round(ziel - groesse, 2)
    out.update(groesse=groesse, ziel=ziel, ziel_usd=ziel_usd, gewinn=round(float(bal) - groesse, 2),
               fortschritt=round((float(bal) - groesse) / ziel_usd, 4) if ziel_usd > 0 else None)
    ch_firma = ((regel.get("phasen") or {}).get("challenge") or {}) if isinstance(regel.get("phasen"), dict) else {}
    jg = ((regel.get("je_groesse") or {}).get(str(int(groesse))) or {}) if isinstance(regel.get("je_groesse"), dict) else {}
    jg_ph = isinstance(jg, dict) and isinstance(jg.get("phasen"), dict) and bool(jg["phasen"])
    ch = (((jg.get("phasen") or {}).get("challenge")) or ch_firma) if jg_ph else ch_firma
    # Konto-Wert greift, wo ap_regel_konto ihn einträgt — seit Prüfer-Stopp E3f auch im Größen-Block (je_groesse[g].phasen.challenge)
    wirkt = bool(ch) and str(a.get("account_type")) == "challenge"
    if _wd_num(ch.get("tp_max")) and ziel_usd > 0:
        out["cons_firma"] = round(float(ch["tp_max"]) / ziel_usd * 100.0, 1)
    kp = _wd_num(a.get("consistency_pct"))
    out["cons_waehlbar"] = wirkt and out["cons_firma"] is not None
    if kp and wirkt:
        out.update(cons_pct=float(kp), cons_quelle="konto")
    elif out["cons_firma"] is not None:
        out.update(cons_pct=out["cons_firma"], cons_quelle="firma")
    if out["cons_pct"] and tage_pl:
        gt = max([v for v in tage_pl.values() if v is not None] or [0])
        out.update(groesster_tag=round(gt, 2), cons_anteil=round(gt / ziel_usd, 4) if ziel_usd > 0 and gt > 0 else 0.0)
    return out


def ap_konten_stand(reg, jetzt=None):
    """Kontoliste des Challenge-Planers (IDs aus auto_plan_regeln.user_ids, Typen AP_TYPEN, ohne Archiv) mit Ziel/Consistency je Konto."""
    uids = [str(u) for u in (reg.get("user_ids") or [])]
    if not uids:
        return []
    firmen = (reg.get("regeln") or {}).get("firmen") or []
    konten = _ap_konten_laden({"user_id": "in.(" + ",".join(uids) + ")", "account_type": "in.(" + ",".join(AP_TYPEN) + ")", "order": "id.asc"})
    archiv = _ap_archiviert_gemerkt()
    konten = [a for a in konten if str(a.get("id")) not in archiv]
    echo_bal, dup_bal = _ap_balance_karten()
    namen, _aus = _ap_namen()
    tage = {}
    ids = [str(a["id"]) for a in konten]
    tz_b = _ap_tz("Europe/Berlin")
    for i in range(0, len(ids), 80):
        for p in _sb_all("trade_plans", {"select": "master_account_id,status,started_at,ended_at,completed_at,master_pl",
                                         "master_account_id": "in.(" + ",".join(ids[i:i + 80]) + ")", "status": "eq.completed", "master_pl": "not.is.null"}):
            # Tag wie der Planer (ap_tage_ist): Berlin-Tag des Trade-Endes, sonst Start, sonst Abschluss (Prüfer E3c: nicht der UTC-Tag von started_at)
            ts = _ap_ts(p.get("ended_at") or p.get("started_at") or p.get("completed_at"))
            if ts is None:
                continue
            t = ts.astimezone(tz_b).date().isoformat()
            d = tage.setdefault(str(p["master_account_id"]), {})
            d[t] = d.get(t, 0.0) + float(p["master_pl"])
    out = []
    for a in konten:
        regel = ap_regel_finden(firmen, a.get("firm"))
        bal = acc_balance_wahl(a, echo_bal, dup_bal)[0]
        zeile = ap_konten_stand_zeile(a, regel, bal, tage.get(str(a["id"])))
        out.append(dict(zeile, id=str(a["id"]), user_id=str(a.get("user_id")), user=namen.get(str(a.get("user_id")), str(a.get("user_id"))[:8]), name=a.get("name"),
                        external_id=a.get("external_id"), typ=a.get("account_type"), firma=ap_firma_key(firmen, a.get("firm")),
                        deaktiviert=bool(a.get("deaktiviert")), konto_cons=_wd_num(a.get("consistency_pct"))))
    return out


def _ap_einst_unternehmen(admin, uid, reg, err):
    """REGEL JE UNTERNEHMEN (Phase 1): welches Unternehmen zeigen die Einstellungen? → (gruppe_id | None = Standard, Fehler | None). Ein Verwalter
    (403 aus _ap_zugang, weil nicht im HT-Planer) sieht SEIN Unternehmen, ein Admin wählt ?unternehmen=<gruppe_id>. Statt „⚠ Diese ID ist nicht
    im Auto-Planer" (Finn-Foto Login Emin). Gemeinsam für GET /einstellungen und /konten-stand."""
    if err:
        if not (uid and not admin and reg and err[1] == 403):
            return None, err
        unt = None
        try:
            unt = next((str(g["id"]) for g in admin_gruppen_daten().get("gruppen") or () if g.get("verwalter_id") and str(g["verwalter_id"]) == str(uid)), None)
        except Exception as e:
            print(f"[einstellungen] ⚠️ Unternehmen {str(uid)[:8]}: {type(e).__name__}: {e}", flush=True)
        return (unt, None) if unt else (None, err)
    if admin and request.args.get("unternehmen"):
        return str(request.args.get("unternehmen")), None
    return None, None


@app.route("/admin/auto-plan/konten-stand", methods=["GET", "OPTIONS"])
def admin_auto_plan_konten_stand():
    """GET → {ok, konten: [...]} — Kontoliste je Firma für die Einstellungen (60 s gemerkt). Gate wie /einstellungen."""
    if request.method == "OPTIONS":
        return "", 200
    admin, uid, reg, err = _ap_zugang()
    unt, err = _ap_einst_unternehmen(admin, uid, reg, err)
    if err:
        return err
    if unt:
        # REGEL JE UNTERNEHMEN (Finn-Foto Login Emin .2065: „0 im Planer" bei jeder Firma): Konten der IDs DIESES Unternehmens, gezählt wie bei HT
        # (AP_TYPEN, ohne Archiv), Ziel/Consistency nach seiner wirksamen Regel. Der Verwalter sieht alle Konten seiner Gruppe.
        c = _ap_ks_cache.setdefault("je", {}).setdefault(unt, {})
        if c.get("bis", 0) < time.time():
            try:
                gr = next((g for g in ap_planer_gruppen() if str(g["gruppe_id"]) == unt), None)
                if not gr:
                    return jsonify({"ok": False, "msg": "Unternehmen ohne Planer-Zeile"}), 404
                zeile = (sb_select("auto_plan_gruppe", {"select": "*", "gruppe_id": f"eq.{unt}"}) or [None])[0]
                reg_u = dict(ap_reg_unternehmen(reg, zeile), user_ids=sorted(gr["ids"]))
                c.update(konten=ap_konten_stand(reg_u), bis=time.time() + AP_KS_TTL_S, fehler=None)
            except Exception as e:
                c.update(konten=[], bis=time.time() + 10, fehler=f"{type(e).__name__}: {e}")
        konten, fehler = c.get("konten") or [], c.get("fehler")
    else:
        if _ap_ks_cache.get("bis", 0) < time.time():
            try:
                _ap_ks_cache.update(konten=ap_konten_stand(reg), bis=time.time() + AP_KS_TTL_S, fehler=None)
            except Exception as e:
                _ap_ks_cache.update(konten=[], bis=time.time() + 10, fehler=f"{type(e).__name__}: {e}")
        # ohne Admin nur die eigenen Konten (Gate _ap_zugang: eine Planer-ID sieht nur ihre Zeilen — S6-Review E3c)
        konten, fehler = _ap_ks_cache.get("konten") or [], _ap_ks_cache.get("fehler")
        if not admin:
            konten = [k for k in konten if k.get("user_id") == str(uid)]
    resp = jsonify(json.loads(json.dumps({"ok": True, "admin": bool(admin), "konten": konten, "unternehmen": unt,
                                          "fehler": fehler}, default=str)))
    resp.headers["Cache-Control"] = "no-store"
    return resp


def ap_nicht_drin_mischen(laeufe):
    """REIN RECHNEND (testbar, HN1 Finn 12.11.2026: „in jedem Planer … welche Accounts heute nicht drangekommen sind und warum"): alle Challenge-Läufe
    EINES Tags (Nachtlauf + Nachplan-Läufe) → {tag, at, quelle, ausgelassen}. Ein Nachplan-Lauf führt nur seine eigenen Konten — darum gilt je Konto
    die NEUESTE Aussage über alle Läufe des Tags: ausgelassen mit Grund, oder geplant → nicht mehr in der Liste. Trockenläufe (Probelauf) zählen nicht.
    laeufe: [{tag, at, quelle, aus: [...], gep: [...], trocken}] in beliebiger Reihenfolge. Nur lesen, plant nichts."""
    stand, at, quelle, tag = {}, None, None, None
    for l in sorted([l for l in (laeufe or []) if isinstance(l, dict)], key=lambda l: str(l.get("at") or "")):
        if str(l.get("trocken") or "").lower() == "true":
            continue
        tag = tag or l.get("tag")
        at, quelle = l.get("at") or at, l.get("quelle") or quelle
        for z in l.get("gep") or []:
            if isinstance(z, dict) and z.get("konto_id"):
                stand[str(z["konto_id"])] = None
        for z in l.get("aus") or []:
            if isinstance(z, dict) and z.get("konto_id"):
                stand[str(z["konto_id"])] = z
    return {"tag": tag, "at": at, "quelle": quelle, "ausgelassen": [z for z in stand.values() if z]}


@app.route("/admin/auto-plan/nicht-drin", methods=["GET", "OPTIONS"])
def admin_auto_plan_nicht_drin():
    """GET ?tag=YYYY-MM-DD&sicht=admin → {ok, tag, at, quelle, ausgelassen[]} — Abschnitt „Heute nicht drin" im Challenge-Planer (HN1, 12.11.2026).
    Wie GET /admin/auto-plan (Gate _ap_zugang mit Admin-Reiter, Sicht je ID/Gruppe, Verwalter-Gruppe aus auto_plan_gruppe.letzter_lauf), aber
    über ALLE Läufe des Tags gemischt (ap_nicht_drin_mischen) statt nur den neuesten. Ohne ?tag der Tag des neuesten Laufs. Nur lesen."""
    if request.method == "OPTIONS":
        return "", 200
    admin, uid, _reg, err = _ap_zugang(admin_reiter=True)
    if err:
        return err
    sicht = _ap_sicht_aus_anfrage(admin, uid)
    tag = str(request.args.get("tag") or "").strip()[:10]
    if tag and not re.match(r"^\d{4}-\d{2}-\d{2}$", tag):
        return jsonify({"ok": False, "msg": "tag als YYYY-MM-DD"}), 400
    try:
        gr_lauf = None if admin else ap_gruppe_von_uid(uid)
    except Exception as e:
        print(f"[nicht-drin] ⚠️ Gruppe: {type(e).__name__}: {e}", flush=True)
        gr_lauf = None
    try:
        if gr_lauf:   # Verwalter-Gruppe: nur ihr eigener letzter Lauf (wie GET /admin/auto-plan), nie der HT-Lauf
            ll = gr_lauf.get("letzter_lauf") if isinstance(gr_lauf.get("letzter_lauf"), dict) else {}
            laeufe = [{"tag": ll.get("tag"), "at": ll.get("at"), "quelle": ll.get("quelle"), "aus": ll.get("ausgelassen"), "gep": ll.get("geplant"),
                       "trocken": ll.get("trocken")}] if ll and (not tag or str(ll.get("tag") or "")[:10] == tag) else []
        else:
            if not tag:
                neu = sb_select("auto_plan_lauf", dict(AP_LAUF_NUR_CHALLENGE, select="tag", order="at.desc", limit="1")) or []
                tag = str((neu[0] if neu else {}).get("tag") or "")[:10]
            laeufe = sb_select("auto_plan_lauf", dict(AP_LAUF_NUR_CHALLENGE, select="tag,quelle,at,aus:ergebnis->ausgelassen,gep:ergebnis->geplant,trocken:ergebnis->>trocken",
                                                      tag=f"eq.{tag}", order="at.desc", limit="400")) if tag else []   # Prüfer: neueste zuerst — über 400 fielen sonst die geltenden weg (Mischen sortiert selbst)
    except Exception as e:
        print(f"[nicht-drin] ⚠️ Läufe: {type(e).__name__}: {e}", flush=True)
        return jsonify({"ok": False, "msg": f"Läufe nicht lesbar: {type(e).__name__}"}), 503
    erg = ap_nicht_drin_mischen(laeufe)
    erg["tag"] = erg.get("tag") or tag or None
    try:
        erg = ap_ohne_archiv(erg, _ap_archiviert())   # inzwischen archiviert → nicht mehr in der Liste
    except Exception as e:
        print(f"[nicht-drin] ⚠️ Archiv-Filter: {type(e).__name__}: {e}", flush=True)
    erg = ap_aus_ohne_plan_laden(erg)   # Konto hat inzwischen einen Plan für den Tag → drin
    # HN1-Nachtrag (Master 12.11.2026, Befund S4): HT-IDs ohne Haken in auto_plan_regeln.user_ids liest der Lauf gar nicht ein — ihre Challenge-
    # Konten hier mit Grund (nur lesen, der Lauf bleibt unverändert). Nur im HT-Lauf; Planer-Gruppen (Emin) planen ihre IDs selbst.
    still = []
    if not gr_lauf:
        try:
            drin = {str(u) for u in (_reg or {}).get("user_ids") or ()} | {str(u) for u in _fd_gruppen_ids()}
            raus = [u for u in _fdp_ht_ids() if u not in drin]
            if raus:
                archiv, namen = _ap_archiviert(), _ap_namen()[0]
                for a in _sb_all("accounts", {"select": "id,user_id,name,firm,account_type,external_id,tv_balance", "user_id": "in.(" + ",".join(raus) + ")",
                                              "account_type": "in.(" + ",".join(AP_TYPEN) + ")"}) or []:
                    if str(a.get("id")) in archiv or _ap_norm(a.get("firm")) in AP_STILL_FIRMEN or ist_topstep_express(a):
                        continue   # wie der Lauf: archiviert, Gegenhedge-Konto, Topstep Express nie im Challenge-Planer
                    still.append({"konto_id": str(a.get("id")), "user_id": str(a.get("user_id")), "user": namen.get(str(a.get("user_id"))) or str(a.get("user_id"))[:8],
                                  "konto": a.get("name"), "firma": a.get("firm"), "typ": a.get("account_type"), "balance": _wd_num(a.get("tv_balance")), "grund": AP_GRUND_ID_AUS})
        except Exception as e:
            print(f"[nicht-drin] ⚠️ IDs außerhalb des Planers: {type(e).__name__}: {e}", flush=True)
    out = ap_sicht(erg, sicht) if sicht is not None else erg
    if sicht is not None:
        still = ap_sicht({"ausgelassen": still}, sicht).get("ausgelassen") or []
    resp = jsonify(json.loads(json.dumps({"ok": True, "tag": out.get("tag"), "at": out.get("at"), "quelle": out.get("quelle"),
                                          "ausgelassen": out.get("ausgelassen") or [], "nicht_im_planer": still}, default=str)))
    resp.headers["Cache-Control"] = "no-store"
    return resp


@app.route("/admin/auto-plan/konto-consistency", methods=["POST", "OPTIONS"])
def admin_auto_plan_konto_consistency():
    """POST {konto_id, pct: null | 1–100} → accounts.consistency_pct (null = Firmen-Standard). Nur Admin, nur Challenge-Konten des Planers."""
    if request.method == "OPTIONS":
        return "", 200
    _gs = _planer_schreib_gate()
    if _gs is not None:
        return _gs
    admin, uid, reg, err = _ap_zugang()
    if err:
        return err
    if not admin:
        return jsonify({"ok": False, "msg": "Nur für Admins"}), 403
    body = request.get_json(silent=True) or {}
    kid, pct = str(body.get("konto_id") or ""), body.get("pct")
    if pct is not None and (isinstance(pct, bool) or not isinstance(pct, (int, float)) or not (1 <= pct <= 100)):
        return jsonify({"ok": False, "msg": "pct = leer (Standard) oder 1–100"}), 400
    rows = sb_select("accounts", {"select": "id,user_id,account_type", "id": f"eq.{kid}"}) if re.match(r"^[0-9a-f-]{36}$", kid) else []
    if not rows or rows[0].get("account_type") not in AP_TYPEN or str(rows[0].get("user_id")) not in {str(u) for u in (reg.get("user_ids") or [])}:
        return jsonify({"ok": False, "msg": "Konto nicht im Challenge-Planer"}), 400
    try:
        sb_update("accounts", {"id": f"eq.{kid}"}, {"consistency_pct": pct})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
    _ap_ks_cache.clear()
    _ap_kw_cache.clear()
    print(f"[einstellungen] Consistency Konto {kid}: {pct if pct is not None else 'Standard'} ({uid})", flush=True)
    return jsonify({"ok": True, "konto_id": kid, "pct": pct})


# ══ KONTO-ZIELE (K1, Finn 05.11.2026 ~07:00 Dubai, Foto Blue Guardian 100k …8631: „In den Dashboards der Propfirmen steht zu jedem Account, ob er
# payout-eligible ist … Wenn ich auf einen Account drücke, das komplett umbauen — Max Drawdown, Daily Loss usw. — so wie bei der Prop."). GET /konto-ziele?id=
# → Kopf-Kachel Payout/Phase (Ja/Nein + Checkliste), Trading Objectives (Ziel, Max Loss, Max Daily Loss, Consistency, Tage) und Balance-Verlauf für die
# Konto-Detailseite. NUR ANZEIGE, KEINE ZWEITE WAHRHEIT: jede Zahl kommt aus derselben Funktion wie im Planer/Radar — Challenge ap_konten_stand_zeile
# (Ziel, Consistency) + ap_boden_sicher (Boden) + ap_tage_ist, Funded CFD fcp_konto_ziel_boden + fcp_gewinntage_ist + fcp_tage_zyklus + fcp_consistency_pct,
# Winning Days wd_auto_stand + wd_zyklus_stand + wd_firmen_regel (+ Recoverer/Tradeify-Zyklus aus _wd_zyklus_anhaengen), Max Loss sonst liq_konto_boden,
# Daily Loss aus den Firmen-Kernwerten (ap_tagesgrenze) bzw. liq_regeln (Tagesstart/Stufen), Balance acc_balance_wahl (inkl. tv_balance). Fehlt eine Regel:
# Kachel „—" mit Grund. Gate: eigenes Konto, Admin (wie die Planer-Routen) oder die eigene Gruppe — sonst 403, nie fremde Konten.
KZ_PLAN_SEL = ("id,master_account_id,status,route,konto_typ,started_at,ended_at,completed_at,master_pl,"
               "tv:mt5_baseline->tv,fin:mt5_baseline->final")
KZ_KONTO_SEL = (AP_KONTO_FELDER + ",ziel_usd,waiting_payout_since,payout_ready_at,wd_farm,wd_zyklus_regel,goal_wd_korrektur,goal_wd_seit,goal_wd_hand_tage")
KZ_CHART_MAX = 60
_kz_karten_cache = {}
KZ_KARTEN_TTL_S = 60


def kz_usd(v, d=0, vz=False):
    """REIN: 5.510 $ / −4.010 $ / +9.005 $ (vz = Vorzeichen auch bei Plus)."""
    if v is None:
        return "—"
    s = _liq_de(abs(float(v)), d)
    return ("−" if float(v) < 0 else "+" if vz and float(v) > 0 else "") + s + " $"


def kz_tag(iso):
    """REIN: '2026-10-28…' → '28.10.' (leer → '')."""
    t = str(iso or "")[:10]
    return f"{t[8:10]}.{t[5:7]}." if re.fullmatch(r"\d{4}-\d{2}-\d{2}", t) else t


def kz_pct(v, d=1):
    """REIN: Anteil 0,388 → „38,8 %"."""
    if v is None:
        return "—"
    s = f"{float(v) * 100:.{d}f}".replace(".", ",")
    return (s[:-2] if s.endswith(",0") else s) + " %"


def kz_plan_bal(p):
    """REIN: belegte Balance nach einem Trade — final.balance_end (Orbit/Topstep), sonst final.master_balance (Echo) | None."""
    fin = p.get("fin") if isinstance(p.get("fin"), dict) else {}
    for k in ("balance_end", "master_balance"):
        v = _wd_num(fin.get(k))
        if v and v > 0:
            return float(v)
    return None


def kz_phase_plaene(plaene, typ):
    """REIN: Trades der aktuellen Phase des Kontos (konto_typ gleich der Kontoart; ohne konto_typ zählt der Trade — Echo trägt das Feld nicht immer).
    Funded und Winning Days sind dasselbe Funded-Konto (Big Trade, dann WD auf derselben Zeile) — beide zählen."""
    fam = {"funded", "winning_days"} if str(typ or "").lower() in ("funded", "winning_days") else {str(typ or "").lower()}
    return [p for p in plaene or () if not p.get("konto_typ") or str(p.get("konto_typ")).lower() in fam]


def kz_chart(plaene, typ):
    """REIN (testbar): Balance-Verlauf → [{t, bal}] der beendeten Trades der Phase, sortiert nach Ende, höchstens KZ_CHART_MAX (die jüngsten)."""
    pts = []
    for p in sorted(kz_phase_plaene(plaene, typ), key=lambda x: str(x.get("ended_at") or x.get("completed_at") or "")):
        t, b = p.get("ended_at") or p.get("completed_at"), kz_plan_bal(p)
        if p.get("status") in ("completed", "review") and t and b:
            pts.append({"t": str(t), "bal": round(b, 2)})
    return pts[-KZ_CHART_MAX:]


def kz_tagesstart(plaene, bal, jetzt_iso=None):
    """REIN (testbar): Balance zu Beginn des CME-Handelstags → (wert, quelle). Frühester Trade von heute mit tv.balance_start, sonst Endbalance − P&L des
    frühesten beendeten Trades von heute (Echo), sonst die aktuelle Balance (heute noch kein Trade)."""
    heute = _cme_handelstag(jetzt_iso)
    kand = []
    for p in plaene or ():
        st = p.get("started_at")
        if not st or _cme_handelstag(st) != heute:
            continue
        bs = _wd_num((p.get("tv") or {}).get("balance_start")) if isinstance(p.get("tv"), dict) else None
        if not bs:
            be, pl = kz_plan_bal(p), _wd_num(p.get("master_pl"))
            bs = round(be - pl, 2) if (be and pl is not None and p.get("status") in ("completed", "review")) else None
        if bs and bs > 0:
            kand.append((str(st), float(bs)))
    if kand:
        return min(kand)[1], "Balance beim ersten Trade heute"
    return (float(bal) if bal else None), "aktuelle Balance (heute noch kein Trade)"


def kz_regel_groesse(regel, groesse):
    """REIN: Firmen-Kernwerte mit dem Block der Kontogröße eingemischt (wie zw_ziel/ap_boden_konto)."""
    if not regel or not groesse:
        return regel
    jg = (regel.get("je_groesse") or {}).get(str(int(groesse))) if isinstance(regel.get("je_groesse"), dict) else None
    return dict(regel, **{k: v for k, v in jg.items() if k != "phasen"}) if isinstance(jg, dict) and not jg.get("keine_werte") else regel


def kz_daily(ap_regel, liq_regel, groesse, tagesstart, bal):
    """REIN (testbar): Max Daily Loss → {betrag, level, uebrig, weich, text} | None (die Firma hat keins hinterlegt). Erst die Firmen-Kernwerte des Planers
    (ap_tagesgrenze: daily_pct/daily_usd), bei weichem Tagesstopp (Apex, soft) bzw. ohne Kernwert die liq_regeln-Zeile (tagesstart/stufen). Kein Rückgriff
    auf accounts.max_daily_drawdown (Master K1: nur wo die Firma eins hat)."""
    if tagesstart is None or not groesse:
        return None
    r = kz_regel_groesse(ap_regel, groesse)
    g = ap_tagesgrenze(r, groesse, tagesstart) if r else None
    if g:
        pct = _wd_num((r or {}).get("daily_pct"))
        txt = (f"{_liq_de(pct, 1 if pct % 1 else 0)} % ab " + ("Kontogröße" if str(r.get("daily_basis") or "") == "groesse" else "Tagesstart")) if pct else "fest"
        return {"betrag": round(g, 2), "level": round(tagesstart - g, 2), "uebrig": round(float(bal) - (tagesstart - g), 2) if bal else None,
                "weich": False, "text": txt, "quelle": "Firmen-Kernwerte des Planers"}
    if liq_regel and liq_regel.get("art") in ("tagesstart", "stufen"):
        lv, txt = liq_aus_regel(liq_regel, groesse, None, tagesstart)
        if lv is not None:
            weich = bool((ap_regel or {}).get("soft"))
            return {"betrag": round(tagesstart - lv, 2), "level": lv, "uebrig": round(float(bal) - lv, 2) if bal else None, "weich": weich,
                    "text": ("weicher Tagesstopp · " if weich else "") + ("Stufe nach Balance" if liq_regel.get("art") == "stufen" else "ab Tagesstart"),
                    "quelle": "liq_regeln · " + txt}
    return None


KZ_BODEN_ART = {"statisch": "statisch", "eod_trailing": "End-of-Day nachziehend", "nachziehend": "nachziehend", "nachziehend_lock": "nachziehend, Lock beim Start (Lucid Start + 100)",
                "nachziehend_geschaetzt": "nachziehend (geschätzt)"}


def kz_kachel(key, titel, wert=None, klein=None, unter=None, anteil=None, farbe="", linie=None, pill=None, info="", leer=False):
    return {"key": key, "titel": titel, "wert": wert if wert is not None else "—", "klein": klein, "unter": unter, "anteil": anteil, "farbe": farbe,
            "linie": linie, "pill": pill, "info": info, "leer": leer or wert is None}


def kz_ml_kachel(boden, dd, art, bal, quelle):
    """REIN: Max-Loss-Kachel aus Boden (Level), Max DD und Art."""
    if boden is None or not bal:
        return kz_kachel("max_loss", "Max Loss", None, unter="kein Boden bekannt", info=quelle or "")
    uebrig = round(float(bal) - float(boden), 2)
    a = max(0.0, min(1.0, uebrig / float(dd))) if dd else None
    farbe = "rot" if uebrig <= 0 or (a is not None and a < .25) else "warn" if (a is not None and a < .5) else "gut"
    pill = ["Verletzt", "rot"] if uebrig <= 0 else ["On track", "gut"] if farbe == "gut" else [f"{kz_pct(1 - a, 0)} weg", farbe]
    return kz_kachel("max_loss", "Max Loss", kz_usd(uebrig), "übrig", f"Level {kz_usd(boden)} · {KZ_BODEN_ART.get(art, art or 'statisch')}", a, farbe, None, pill,
                     (quelle or "") + (f" · Max DD {kz_usd(dd)}" if dd else ""))


def kz_dl_kachel(dl, grund):
    if not dl:
        return kz_kachel("daily_loss", "Max Daily Loss", None, unter="nicht hinterlegt", info=grund)
    if dl.get("uebrig") is None:
        return kz_kachel("daily_loss", "Max Daily Loss", None, unter="Balance unbekannt", info=f"Daily Loss {kz_usd(dl['betrag'])} · {dl.get('quelle_text') or ''}".strip(" ·"))
    a = max(0.0, min(1.0, (dl["uebrig"] or 0) / dl["betrag"])) if dl["betrag"] else None
    farbe = "rot" if (dl["uebrig"] or 0) <= 0 else "warn" if (a is not None and a < .5) else "gut"
    return kz_kachel("daily_loss", "Max Daily Loss", kz_usd(dl["uebrig"]), "übrig", f"Level {kz_usd(dl['level'])} · {dl['text']}", a, farbe, None,
                     ["Erreicht", "rot"] if farbe == "rot" else ["On track", "gut"] if farbe == "gut" else ["knapp", "warn"],
                     f"Daily Loss {kz_usd(dl['betrag'])} · {dl.get('quelle_text') or ''}".strip(" ·"))


def kz_cons_kachel(grenze_pct, anteil, bester, basis, basis_text, info, aus_grund=None):
    """REIN: Consistency-Kachel — größter Tag ÷ Basis gegen die Grenze (Balken-Skala bis 1,5 × Grenze, Strich bei der Grenze)."""
    if grenze_pct is None:
        return kz_kachel("consistency", "Consistency", None, unter="keine Regel", info=(info + (" · " + aus_grund if aus_grund else "")).strip(" ·"))
    g = float(grenze_pct) / 100.0
    if anteil is None:
        return kz_kachel("consistency", "Consistency", None, unter=f"Grenze {kz_pct(g, 0)} · " + (aus_grund or "noch kein Gewinn"), info=info,
                         pill=[f"≤ {kz_pct(g, 0)}", "grau"])
    ok = anteil <= g + 1e-9
    skala = 1.5 * g
    return kz_kachel("consistency", "Consistency", kz_pct(anteil), None, f"größter Tag {kz_usd(bester)} ÷ {basis_text} {kz_usd(basis)} · Grenze {kz_pct(g, 0)}",
                     min(1.0, anteil / skala) if skala else None, "gut" if ok else "rot", g / skala if skala else None,
                     ["In range", "gut"] if ok else ["Out of range", "rot"], info)


def kz_tage_kachel(key, titel, ist, soll, unter, info):
    if ist is None or not soll:
        return kz_kachel(key, titel, None, unter="kein Ziel hinterlegt", info=info)
    ok = ist >= soll
    return kz_kachel(key, titel, str(int(ist)), f"/ {int(soll)}", unter, min(1.0, ist / soll), "gut" if ok else "", None,
                     ["Erreicht", "gut"] if ok else ["Offen", "grau"], info)


def kz_trades_kachel(phase, seit=None):
    """REIN: beendete Trades der Phase (ab seit, Berlin-Tag des Endes) + der letzte mit P&L."""
    tz_b = _ap_tz("Europe/Berlin")
    fertig = []
    for p in phase or ():
        t = _ap_ts(p.get("ended_at") or p.get("completed_at"))
        if p.get("status") in ("completed", "review") and t is not None and (not seit or t.astimezone(tz_b).date().isoformat() >= str(seit)[:10]):
            fertig.append((t, p))
    if not fertig:
        return kz_kachel("trades", "Trades" + (" im Zyklus" if seit else ""), "0", unter="noch kein beendeter Trade", info="beendete Trades dieser Phase")
    t, p = max(fertig, key=lambda x: x[0])
    pl = _wd_num(p.get("master_pl"))
    return kz_kachel("trades", "Trades" + (" im Zyklus" if seit else ""), str(len(fertig)), None,
                     f"letzter {t.astimezone(tz_b).strftime('%d.%m.')}" + (f" · {kz_usd(pl, 0, True)}" if pl is not None else ""), None, "", None, None,
                     "beendete Trades dieser Phase" + (f" seit {kz_tag(seit)}" if seit else ""))


def kz_review_mitzaehlen(plaene, stand):
    """REIN RECHNEND (testbar, WP4 10.11.2026): Pläne für die Zyklus-Zählung der Konto-Seite — ein Plan in review mit P&L, der VOR der Balance-Lesung (stand)
    endete, zählt wie abgeschlossen (seine P&L steckt schon in der Balance). Ohne lesbare Lesezeit bleibt alles wie bisher (nur completed)."""
    st = _ap_ts(stand) if stand else None
    if st is None:
        return list(plaene or [])
    out = []
    for p in plaene or ():
        if p.get("status") == "review" and _wd_num(p.get("master_pl")) is not None:
            ts = _ap_ts(p.get("ended_at") or p.get("completed_at") or p.get("started_at"))
            if ts is not None and ts <= st:
                out.append(dict(p, status="completed"))
                continue
        out.append(p)
    return out


def kz_rechnen(a, ctx):
    """REIN RECHNEND (testbar): ein Konto + geladene Daten → {typ, groesse, balance, urteil, kacheln, chart}. ctx: bal, bal_quelle, bal_stand, plaene (alle
    Trades des Kontos, KZ_PLAN_SEL), jetzt (ISO), ap_firmen (auto_plan_regeln.regeln.firmen), fcp_regel (Zeile funded_cfd_plan_regeln), liq_regeln, peak
    (liq_peak), peak_eod, wd_firmen_regeln, wd_pay (pending/received + Buchungen wie _wd_zyklus_anhaengen), wd_zyklus (Feld zyklus | None),
    fcp_pay (pending, managed, buchungen)."""
    a = a or {}
    typ = str(a.get("account_type") or "").lower()
    aid = str(a.get("id") or "")
    bal = _wd_num(ctx.get("bal"))
    plaene = [p for p in (ctx.get("plaene") or []) if str(p.get("master_account_id") or aid) == aid]
    phase = kz_phase_plaene(plaene, typ)
    groesse = _wd_num(a.get("starting_balance")) if typ in AP_TYPEN and _wd_num(a.get("starting_balance")) else None
    groesse = _wd_konto_groesse(a) or groesse or liq_konto_groesse(a)
    out = {"ok": True, "id": aid, "typ": typ, "firma": a.get("firm"), "groesse": groesse,
           "balance": {"wert": bal, "quelle": ctx.get("bal_quelle"), "stand": ctx.get("bal_stand")},
           "urteil": None, "kacheln": [], "chart": {"punkte": kz_chart(phase, typ), "start": groesse, "ziel": None, "boden": None}}
    if typ == "live":
        return out
    ap_regel = ap_regel_finden(ctx.get("ap_firmen") or [], a.get("firm"))
    ts, ts_quelle = kz_tagesstart(phase, bal, ctx.get("jetzt"))
    # Liq-Regel wie der Radar (liq_regel_felder): Kontoart des Kontos (winning_days löst wie_kontotyp selbst auf), Winning Day = wd für liq_boden_kernwerte
    liq_typ = typ
    liq_r, _weg = liq_regel_waehlen(ctx.get("liq_regeln") or [], a.get("firm"), liq_typ, groesse)
    express = ist_topstep_express(a)
    dl = None if express else kz_daily(ap_regel, liq_r, groesse, ts, bal)
    if express:
        out["chart"]["start"] = None       # TopstepX zählt Express ab 0 $ — Kontogröße als Linie wäre falsch
    if dl:
        dl["quelle_text"] = f"{dl['quelle']} · Tagesstart {kz_usd(ts, 2)} ({ts_quelle})"
    dl_grund = ("Topstep Express — Daily Loss steht in TopstepX (Balance ab 0 $)" if express else
                "die Firma hat kein Daily Loss hinterlegt (Kernwerte/liq_regeln)" if ts is not None else "Balance unbekannt")
    checks, kach = [], []
    gewinn = round(bal - groesse, 2) if (bal and groesse) else None

    def liq_ml():
        r2, a2, g2 = liq_boden_kernwerte(liq_r, a, liq_typ, typ == "winning_days", ctx.get("ap_firmen"))
        eod = (r2 or {}).get("maxdd_art") == "eod_trailing"
        pk = ctx.get("peak_eod") if eod else ctx.get("peak")
        # start_bal None: ein Boden über der Balance (geblowt / Datenzweifel) bleibt sichtbar — die Kachel zeigt dann „Verletzt" statt „—"
        b, txt, dd, art = liq_konto_boden(r2, a2, g2, pk, None)
        if b is not None and bal and b >= bal:
            txt += " — liegt nicht unter der Balance (geblowt oder Datenzweifel)"
        return b, dd, art, txt

    if typ in AP_TYPEN:
        # ── Challenge / Phase 1 / Phase 2: wie der Challenge-Planer (Einstellungen → Konten) ──
        tage_pl = {}
        tz_b = _ap_tz("Europe/Berlin")
        for p in plaene:
            if p.get("status") != "completed" or _wd_num(p.get("master_pl")) is None:
                continue
            t = _ap_ts(p.get("ended_at") or p.get("started_at") or p.get("completed_at"))
            if t is not None:
                d = t.astimezone(tz_b).date().isoformat()
                tage_pl[d] = tage_pl.get(d, 0.0) + float(p["master_pl"])
        z = ap_konten_stand_zeile(a, ap_regel, bal, tage_pl or None)
        out["stand"] = z
        if z.get("groesse"):
            groesse = out["groesse"] = out["chart"]["start"] = z["groesse"]
            gewinn = z["gewinn"]
        # Ziel wie der Radar (admin_skala_felder): accounts.ziel_usd der Ziel-Wache, sonst die Planer-Regel (zw_ziel über ap_konten_stand_zeile)
        ziel_bal = _wd_num(a.get("ziel_usd")) or z.get("ziel")
        ziel_usd = round(ziel_bal - groesse, 2) if (ziel_bal and groesse) else None
        # erreicht: Markierung der Ziel-Wache gilt wie im Planer („Ziel erreicht = nie planen", auch wenn das Konto aus dem Login weg ist)
        erreicht = bool(a.get("ziel_erreicht_at")) or bool(ziel_bal and bal and zw_erreicht(ziel_bal, bal, typ))
        out["chart"]["ziel"] = ziel_bal
        quelle_z = "Ziel-Wache (accounts.ziel_usd)" if _wd_num(a.get("ziel_usd")) else "Planer-Regel (auto_plan_regeln)" if ziel_bal else ""
        if ziel_bal and gewinn is not None and ziel_usd:
            f = 1.0 if erreicht else max(0.0, min(1.0, gewinn / ziel_usd)) if ziel_usd > 0 else None
            kach.append(kz_kachel("ziel", "Ziel", kz_pct(f, 0) if erreicht else kz_usd(max(0.0, ziel_bal - bal)), None if erreicht else "fehlen",
                                  f"{kz_usd(gewinn, 0, True)} von {kz_usd(ziel_usd, 0, True)} · Ziel {kz_usd(ziel_bal)}", f, "gut" if erreicht else "",
                                  None, ["Erreicht", "gut"] if erreicht else ["Offen", "grau"], quelle_z))
        else:
            kach.append(kz_kachel("ziel", "Ziel", None, unter="keine Ziel-Regel", info="weder Planer-Regel (Firma/Größe) noch accounts.ziel_usd"))
        bk = ap_boden_sicher(ctx.get("ap_firmen") or [], a, bal, {aid: ctx.get("peak")}) if bal else {}
        b_ap = bk.get("boden") if bk.get("boden") is not None else bk.get("boden_min")   # wie ap_boden_zeile / zw_tick
        if b_ap is not None:
            dd = round(groesse - bk["boden_min"], 2) if (groesse and bk.get("boden_min") is not None) else _wd_num(a.get("max_drawdown"))
            kach.append(kz_ml_kachel(b_ap, dd, bk.get("boden_art") if bk.get("boden") is not None else "statisch", bal, "Boden wie im Planer (Kernwerte)"))
            out["chart"]["boden"] = b_ap
        else:
            b, dd, art, txt = liq_ml()
            kach.append(kz_ml_kachel(b, dd, art, bal, txt))
            out["chart"]["boden"] = b
        kach.append(kz_dl_kachel(dl, dl_grund))
        cons_ok = True
        if z.get("cons_pct"):
            an = z.get("cons_anteil")
            cons_ok = an is None or an <= float(z["cons_pct"]) / 100.0 + 1e-9
            kach.append(kz_cons_kachel(z["cons_pct"], an, z.get("groesster_tag"), ziel_usd, "Ziel",
                                       "größter Tag ÷ Ziel-$ wie der Challenge-Planer, Grenze " + ("am Konto" if z.get("cons_quelle") == "konto" else "Firmen-Standard"),
                                       "noch kein abgeschlossener Trade"))
        else:
            kach.append(kz_cons_kachel(None, None, None, None, "", "keine Consistency in den Kernwerten (tp_max)"))
        ti = ap_tage_ist(a, plaene)
        tage_titel = "Gewinntage" if ap_tage_gewinn(a) is not None else "Mindesttage"
        kach.append(kz_tage_kachel("tage", tage_titel, ti[0] if ti else None, ti[1] if ti else None,
                                   (f"Tage ≥ {kz_usd(ap_tage_gewinn(a))}" if ap_tage_gewinn(a) is not None else "Handelstage") if ti else "keine Mindesttage am Konto",
                                   "ap_tage_ist wie der Planer (Berlin-Tage ab goal_since)"))
        checks.append(["ok" if erreicht else "nein", f"Ziel {kz_usd(ziel_bal)}" if ziel_bal else "Ziel",
                       f"{kz_usd(gewinn, 0, True)} / {kz_usd(ziel_usd, 0, True)}" if (ziel_usd and gewinn is not None) else "—"])
        if z.get("cons_pct"):
            checks.append(["ok" if cons_ok else "nein", f"Consistency ≤ {kz_pct(float(z['cons_pct']) / 100, 0)}", kz_pct(z.get("cons_anteil"))])
        if ti:
            checks.append(["ok" if ti[0] >= ti[1] else "nein", tage_titel, f"{ti[0]} / {ti[1]}"])
        ok = erreicht and cons_ok and (not ti or ti[0] >= ti[1])
        if a.get("ziel_erreicht_at"):
            checks.append(["info", "Ziel-Wache", "erreicht am " + kz_tag(a["ziel_erreicht_at"])])
        if ok:
            checks.append(["info", "Nächster Schritt", "Konto umstellen (nächste Phase)"])
        fehlt = [c[1] for c in checks if c[0] == "nein"]
        out["urteil"] = {"art": "phase", "titel": "Phase", "ok": ok if ziel_bal else None,
                         "text": "Bestanden" if ok else "Noch nicht bestanden" if ziel_bal else "Ziel unbekannt",
                         "grund": ("alles erfüllt" if ok else "fehlt: " + ", ".join(fehlt)) if ziel_bal else "keine Ziel-Regel", "checks": checks}
    elif typ == "funded_cfd":
        # ── Funded CFD: wie der Funded-CFD-Planer (Ziel bis Waiting, Gewinntage, Consistency je Zyklus) ──
        freg = ap_regel_finden(((ctx.get("fcp_regel") or {}).get("firmen") or []), a.get("firm"))
        pend, verw, buch = (ctx.get("fcp_pay") or ([], [], []))
        n_pay = fcp_payouts_zaehlen(pend, verw, buch).get(aid, 0)
        zyklus = n_pay + 1
        z_ab = fcp_zyklus_start(pend, verw, buch).get(aid)
        z_ts = fcp_zyklus_anfrage_ts(pend, verw, buch).get(aid)     # WP4: am Anfrage-Tag zählt, was nach der Anfrage endete
        seit = fcp_gewinntage_seit(z_ab, a.get("created_at"))
        # WP4 (b): der Trade in review, der gerade abgehakt wird, steckt schon in der Balance — für Consistency/Gewinne zählt er mit, wenn er vor der Balance-Lesung
        # endete und seinen P&L hat (sonst lag Gewinn ≥ Ziel neben einer Consistency ohne diesen Tag: Fall 67,7 % statt 41,5 %)
        plaene_z = kz_review_mitzaehlen(plaene, ctx.get("bal_stand"))
        out["zyklus"] = {"nr": zyklus, "seit": seit, "payouts": n_pay}
        jg = fcp_je_groesse(freg, groesse) or {}
        zb = fcp_konto_ziel_boden(freg, groesse, zyklus, a.get("name")) if freg else None
        # O1 (Master 05.11.2026, Prüfer): Konto-Seite rechnet wie der Planer — On-Demand-Regel, festes Ziel des Zyklus, Consistency auf der Summe der Gewinn-Tage
        od_an = a.get("on_demand") is True and bool(freg) and bool(jg)
        _oda = fcp_on_demand_anwenden(freg, jg, groesse) if od_an else None
        if _oda:
            freg, jg = _oda
            _zbo, _dd = fcp_bereich(jg.get("ziel")), _wd_num(jg.get("dd"))
            zb = (float(groesse) + _zbo[0], float(groesse) - float(_dd or 0)) if (_zbo and groesse) else zb
        ep = fcp_erster_payout(freg) if (freg and zyklus == 1) else None
        bereich = fcp_bereich((ep or jg).get("ziel")) if (ep or jg) else None
        z_fest = None
        if bereich and isinstance(a.get("fcp_ziel"), dict):
            _z, _neu = fcp_ziel_fest(a.get("fcp_ziel"), zyklus, bereich, bereich[0])
            z_fest = None if _neu else max(_z, bereich[0])
        if zb and z_fest is not None and groesse:
            zb = (float(groesse) + z_fest, zb[1])
        out["on_demand"] = bool(_oda)
        out["ziel_fest"] = z_fest
        wartet = bool(a.get("waiting_payout_since"))
        _p_zt = fcp_param(ctx.get("fcp_regel") or {})   # ZT1: Ziel-Toleranz des Funded-CFD-Planers (Unternehmen der ID), dieselbe wie im Planer
        if _oda:
            _p_zt = dict(_p_zt, ziel_toleranz_pct=0.0)      # ZT1-Prüfer M1: On Demand = Payout-Mindestsumme der Firma, ohne Toleranz (wie der Planer)
        zt_info = None
        if zb and gewinn is not None:
            ziel_bal, boden = zb
            # ZT1 (Finn 10.11.2026): erreicht ab Ziel × (1 − Toleranz), Ziel wie bisher = Ziel-Balance − Größe (festes Ziel bzw. unterer Wert)
            _z_rel = float(ziel_bal) - float(groesse) if groesse else None
            _sw = fcp_ziel_schwelle(_z_rel, _p_zt) if _z_rel is not None else None
            erreicht = wartet or bal >= ziel_bal or (_sw is not None and gewinn >= _sw - 0.005)
            # Prüfer S2: Hinweis auch, wenn das Konto schon wartet (Planer hat es dank Toleranz umgestellt — WP3-Liste zeigt sonst Gewinn < Ziel mit ✓)
            zt_info = None if bal >= ziel_bal else (fcp_ziel_toleranz_info(_z_rel, gewinn, _p_zt) if _z_rel is not None else None)
            out["ziel_toleranz"] = dict(zt_info, pct_einstellung=_p_zt.get("ziel_toleranz_pct")) if zt_info else {"pct_einstellung": _p_zt.get("ziel_toleranz_pct")}
            out["chart"].update(ziel=ziel_bal, boden=boden)
            z_eff = z_fest if z_fest is not None else bereich[0]
            f = max(0.0, min(1.0, gewinn / z_eff)) if z_eff and z_eff > 0 else None
            kach.append(kz_kachel("ziel", "Ziel", kz_pct(f, 0) if erreicht else kz_usd(ziel_bal - bal),
                                  (f"−{_liq_de(zt_info['fehlt'])} $ in Toleranz" if zt_info else None) if erreicht else "fehlen",
                                  (f"Gewinn {kz_usd(gewinn, 0, True)} · Ziel fest {kz_usd(z_fest, 0, True)}" if z_fest is not None else
                                   f"Gewinn {kz_usd(gewinn, 0, True)} · Ziel {kz_usd(bereich[0], 0, True)}" + (f"–{_liq_de(bereich[1])} $" if bereich[1] != bereich[0] else "")),
                                  f, "gut" if erreicht else "", None, ["Erreicht", "gut"] if erreicht else ["Offen", "grau"],
                                  ("On-Demand-Ziel" if _oda else "Refund-Ziel 1. Zyklus" if ep else "Ziel je Zyklus")
                                  + (" · festes Ziel des Zyklus (accounts.fcp_ziel), wie der Planer" if z_fest is not None else " aus funded_cfd_plan_regeln; erreicht ab dem unteren Wert (wie Radar)")))
            dd = _wd_num(jg.get("dd"))
            kach.append(kz_ml_kachel(boden, dd, "statisch", bal, "Boden wie im Funded-CFD-Planer (Größe − dd)"))
        else:
            erreicht = wartet
            kach.append(kz_kachel("ziel", "Ziel", None, unter="Balance unbekannt" if (zb and gewinn is None) else "keine Ziel-Regel",
                                  info="keine Balance-Lesung" if (zb and gewinn is None) else "keine Werte für diese Firma/Größe in funded_cfd_plan_regeln"))
            b, dd, art, txt = liq_ml()
            kach.append(kz_ml_kachel(b, dd, art, bal, txt))
            out["chart"]["boden"] = b
        kach.append(kz_dl_kachel(dl, dl_grund))
        p_cons = fcp_consistency_pct(freg) if freg else None
        # O1 (Finn 05.11.2026 ~07:45): Basis = Summe der Gewinn-Tage im Zyklus (fcp_tage_zyklus_w, wie fcp_cons_finn im Planer), nicht der Netto-Gewinn
        tzw = fcp_tw_broker(plaene_z, seit, None, a.get("fcp_ziel"), z_ab, z_ts)   # CS1: Basis laut Broker (fcp_ziel.broker), sonst wie der Planer; WP4
        cons_ok = True
        an = None
        if p_cons:
            an = (tzw["b"] / tzw["w"]) if (tzw and tzw["w"] > 0) else None
            cons_ok = bool(an is not None and an <= p_cons / 100.0 + 1e-9) or bool(tzw and tzw["w"] == 0 and gewinn and gewinn > 0)
            kach.append(kz_cons_kachel(p_cons, an, tzw["b"] if tzw else None, tzw["w"] if tzw else None,
                                       "Summe der Gewinn-Tage" + (" (Basis laut Broker)" if tzw and tzw.get("broker") else ""),
                                       "Consistency je Zyklus: größter Tag ÷ Summe der Gewinn-Tage (wie der Funded-CFD-Planer)",
                                       "Zyklus nicht lesbar" if tzw is None else "noch kein Gewinn-Tag"))
        else:
            kach.append(kz_cons_kachel(None, None, None, None, "", "fcp_consistency_pct: keine"))
        gt = jg.get("gewinntage") if isinstance(jg.get("gewinntage"), dict) else None
        # GT2: Korrektur von Hand (accounts.fcp_gewinntage, nur dieser Zyklus) — dieselbe wie Planer und Radar; auto = Prophos-Zählung ohne Korrektur
        _gk = fcp_gt_korrektur(ctx.get("fcp_gt"), zyklus) if gt else 0   # Route liest accounts.fcp_gewinntage (fcp_gt_korr_laden) in ctx
        gti_auto = fcp_gewinntage_ist(gt, aid, plaene, seit) if gt else None
        gti = fcp_gewinntage_ist(gt, aid, plaene, seit, _gk) if gt else None
        if gt:
            kach.append(kz_tage_kachel("tage", "Gewinntage", gti[0] if gti else None, gti[1] if gti else None,
                                       f"Tage ≥ {kz_usd(_wd_num(gt.get('min')))} im Zyklus" + (f" · {_gk:+d} von Hand" if _gk else ""),
                                       "je_groesse.gewinntage — Zählung wie der Planer (Summe aller abgeschlossenen Trades je Berlin-Tag)"
                                       + (" + Korrektur von Hand (Account bearbeiten → Gewinntage)" if _gk else "")))
            out["gewinntage"] = {"ist": gti[0] if gti else None, "soll": gti[1] if gti else None, "auto": gti_auto[0] if gti_auto else None,
                                 "korrektur": _gk, "zyklus": zyklus, "min": _wd_num(gt.get("min"))}
            # AD1c (Master 11.11.2026): WELCHE Tage zählten — tage = Gewinn-Tage des laufenden Zyklus, zyklen = alle Zyklen (ältester zuerst), je Tag
            # {tag, summe, plaene, n}; dieselbe Zählung wie ist/auto (fcp_gewinntage_zyklen). Nur Felder dazu: nicht rechenbar → beide None, Rest unverändert
            try:
                _gz = fcp_gewinntage_zyklen(gt, aid, plaene, fcp_zyklus_grenz_tage(pend, verw, buch, aid), a.get("created_at"), _gk)
            except Exception as e:
                print(f"[konto-ziele] ⚠️ Gewinn-Tage-Liste {aid[:8]}: {type(e).__name__}: {e}", flush=True)
                _gz = None
            out["gewinntage"]["tage"] = _gz[-1]["tage"] if _gz else None
            out["gewinntage"]["zyklen"] = _gz
        checks.append(["ok" if erreicht else "nein", "Ziel bis Waiting" + (" (fest)" if z_fest is not None else ""),
                       (f"{kz_usd(gewinn, 0, True)} / {kz_usd(z_fest if z_fest is not None else bereich[0], 0, True)}" if (bereich and gewinn is not None) else "—")
                       + (f" · Ziel erreicht (−{_liq_de(zt_info['fehlt'])} $ in Toleranz)" if zt_info else "")])   # ZT1
        if _oda:
            checks.append(["info", "Add-on On Demand", "Ziel 2–2,25 % · Consistency " + (_liq_de(p_cons) + " %" if p_cons else "–")])
        if gt:
            checks.append([("ok" if gti[0] >= gti[1] else "nein") if gti else "info", f"Gewinntage ≥ {kz_usd(_wd_num(gt.get('min')))}", f"{gti[0]} / {gti[1]}" if gti else "—"])
        if p_cons:
            checks.append(["ok" if cons_ok else "nein", f"Consistency ≤ {_liq_de(p_cons)} %", kz_pct(an)])
        else:
            checks.append(["info", "Consistency", "keine"])
        checks.append(["info", "Refund-Trade", f"Ziel {_liq_de(bereich[0])}–{_liq_de(bereich[1])} $" if ep and bereich else "aus" if freg else "—"])
        checks.append(["ok" if wartet else "info", "Waiting for Payout", ("seit " + kz_tag(a["waiting_payout_since"])) if wartet else "—"])
        if _oda:   # OD1 (Finn 05.11.2026): On Demand hat kein Payout-Datum und keine Tage — anfragbar, sobald Ziel + Consistency erfüllt sind
            checks.append(["info", "Payout ab", "On Demand — sobald Ziel + Consistency erfüllt (kein Datum, keine Tage)"])
        elif a.get("payout_ready_at"):
            frei = str(a["payout_ready_at"])[:10] <= str(ctx.get("jetzt") or datetime.now(timezone.utc).isoformat())[:10]
            checks.append(["ok" if frei else "nein", "Payout ab", kz_tag(a["payout_ready_at"])])
        ok = bool(freg) and erreicht and cons_ok and (not gt or bool(gti and gti[0] >= gti[1]))
        # ABHAK-KARTE (AB1, Finn 05.11.2026 ~06:00 Dubai, Ja zur Vorschau): dieselben Zahlen wie oben + der nächste Trade aus fcp_konto_rechnen
        # (die Planer-Rechnung, ohne Zufall = Mitte der Spannen, mit dem Ziel aus Zeile 1). Nur Anzeige; nie Teil des Urteils.
        nx = None
        try:
            z_eff_ab = z_fest if z_fest is not None else (bereich[0] if bereich else None)
            if freg and jg and bal and groesse and not wartet:
                nx = fcp_konto_rechnen(jg, float(bal), float(groesse), zyklus, fcp_eins_prozent(a), 1.0, 1.0, None, freg,
                                       param=fcp_param(ctx.get("fcp_regel") or {}), tage=tzw,
                                       gewinne=fcp_gewinne(plaene_z, seit, z_ts), gewinntage=gti,
                                       ziel_fest=({"usd": z_eff_ab, "zyklus": zyklus} if z_eff_ab is not None else None))
        except Exception as e:
            print(f"[konto-ziele] ⚠️ nächster Trade {aid[:8]}: {type(e).__name__}: {e}", flush=True)
        # WP4 (3) (Finn 10.11.2026): das Abhak-Popup wählt bei Ziel + Consistency „Waiting“ vor und sagt warum; sonst steht genau da, was fehlt — mit Zahlen.
        # „Payout ab“ ist eine Sperre fürs Anfragen, nicht fürs Waiting (bereit prüft es nicht) → steht hier nicht.
        ab_ok, ab_fehlt = [], []
        _zb_rel = z_fest if z_fest is not None else (bereich[0] if bereich else None)
        if zb and gewinn is not None and _zb_rel is not None:
            if erreicht and not wartet:
                ab_ok.append(f"Ziel {kz_usd(gewinn, 0, True)} / {kz_usd(_zb_rel, 0, True)}" + (f" (−{_liq_de(zt_info['fehlt'])} $ in Toleranz)" if zt_info else ""))
            elif not erreicht:
                _sw_t = fcp_ziel_schwelle(_zb_rel, _p_zt)
                ab_fehlt.append(f"Ziel {kz_usd(gewinn, 0, True)} von {kz_usd(_zb_rel, 0, True)} — zählt ab {kz_usd(_sw_t, 0, True)}, fehlen {_liq_de(max(1.0, -(-(_sw_t - gewinn) // 1)) if _sw_t > gewinn else 0.0)} $")   # aufgerundet, nie „fehlen 0 $“
        elif not wartet:
            ab_fehlt.append("Ziel: keine Balance-Lesung" if zb else "Ziel: keine Regel für Firma/Größe")
        if p_cons:
            if an is not None:
                _ct = f"Consistency {kz_pct(an)} {'≤' if cons_ok else '>'} {_liq_de(p_cons)} % (größter Tag {_liq_de(tzw['b'])} $ / Gewinn-Tage {_liq_de(tzw['w'])} $)"
                (ab_ok if cons_ok else ab_fehlt).append(_ct)
            elif not cons_ok:
                ab_fehlt.append("Consistency nicht prüfbar (Zyklus nicht lesbar)" if tzw is None else "Consistency: noch kein Gewinn-Tag")
        if gt:
            if gti and gti[0] >= gti[1]:
                ab_ok.append(f"Gewinntage {gti[0]}/{gti[1]}")
            else:
                ab_fehlt.append(f"Gewinntage {gti[0]}/{gti[1]}" if gti else "Gewinntage nicht lesbar")
        out["abhak"] = {"bal": bal, "ziel_bal": zb[0] if zb else None, "rest": round(zb[0] - bal, 2) if (zb and bal) else None, "erreicht": erreicht,
                        "ok_text": " · ".join(ab_ok), "fehlt_text": " · ".join(ab_fehlt),
                        "cons": ({"p": p_cons, "b": (tzw or {}).get("b"), "w": (tzw or {}).get("w"), "anteil": an, "ok": cons_ok} if p_cons else None),
                        "gewinntage": list(gti) if (gt and gti) else None,
                        "naechster": ({"aktion": nx.get("aktion"), "tp": nx.get("tp"), "grund": nx.get("grund")} if isinstance(nx, dict) else None),
                        "bereit": bool(ok), "wartet": wartet}
        fehlt = [c[1] for c in checks if c[0] == "nein"]
        _seit_txt = (f" · seit {kz_tag(seit)}" if seit else "")
        if z_ts is not None and seit == z_ab:   # WP4: Zyklus beginnt mit der Anfrage (Trades danach zählen schon) — genaue Zeit zeigen
            _zb_l = z_ts.astimezone(_ap_tz("Europe/Berlin"))
            _seit_txt = f" · seit Anfrage {kz_tag(_zb_l.date().isoformat())} {_zb_l.strftime('%H:%M')}"
        out["urteil"] = {"art": "payout", "titel": "Payout", "ok": ok if freg else None, "sub": f"Zyklus {zyklus}" + _seit_txt,
                         "text": "Payout möglich" if ok else "Noch kein Payout" if freg else "keine Planer-Regel",
                         "grund": ("alles erfüllt" if ok else "fehlt: " + ", ".join(fehlt)) if freg else "Firma nicht im Funded-CFD-Planer", "checks": checks}
    else:
        # ── Funded Futures / Winning Days: wie der WD-Farmer (WDs, Zyklus, Firmen-Regel Consistency + Mindest-Net-Profit, Recoverer) ──
        b, dd, art, txt = liq_ml()
        kach.append(kz_ml_kachel(b, dd, art, bal, txt))
        out["chart"]["boden"] = b
        kach.append(kz_dl_kachel(dl, dl_grund))
        key = fdp_wd_schluessel(a.get("firm"), str(int(groesse)) if groesse else None)
        fr = wd_firmen_regel(ctx.get("wd_firmen_regeln") or {}, key)
        pay = ctx.get("wd_pay") or []
        echte = [t for t in pay if t.get("requested_at")]
        # Zyklus 1 (noch kein Payout): wd_zyklus_stand zählt erst nach einer Anfrage — für die Anzeige zählen dann alle Tage ab Zyklus-Beginn (goal_wd_seit,
        # sonst Anlegetag): ein gedachter Vortag als Anfrage, die Nummer bleibt 1
        seit0 = str(a.get("goal_wd_seit") or a.get("created_at") or "")[:10]
        if echte:
            st = wd_zyklus_stand(phase, echte)
        else:
            vortag = (datetime.strptime(seit0, "%Y-%m-%d") - timedelta(days=1)).strftime("%Y-%m-%d") if seit0 else "1970-01-01"
            st = dict(wd_zyklus_stand(phase, [{"requested_at": vortag, "status": "received"}]), nr=1, start=None)
        # Zyklus-Beginn = Tag NACH der Anfrage (wd_zyklus_stand zählt tag > start, wie fcp_zyklus_start)
        seit_z = (datetime.strptime(st["start"], "%Y-%m-%d") + timedelta(days=1)).strftime("%Y-%m-%d") if st["start"] else (seit0 or None)
        out["zyklus"] = {"nr": st["nr"], "seit": seit_z, "profit": st["profit"], "bester": st["bester"]}
        wz = ctx.get("wd_zyklus") if isinstance(ctx.get("wd_zyklus"), dict) else None
        soll = int(_wd_num(a.get("goal_target")) or 0) or (5 if wd_hand_erlaubt(a) else None)   # Futures-Funded zählt implizit mit 5 (wie _wd_good_day_konto_upd)
        ist = wd_auto_stand(a, plaene) if wd_auto_konto(a) else ((ap_tage_ist(a, plaene) or (None, None))[0] if soll else None)
        ist_wd = typ == "winning_days" or str(a.get("goal_kind") or "") == "winning_days"
        mg = wd_min_gewinn(a)
        kach.insert(0, kz_tage_kachel("tage", "Winning Days" if ist_wd else "Ziel-Tage", ist, soll,
                                      (f"Tage ≥ {kz_usd(mg)}" if mg else "Tage im Plus") + (" · automatisch gezählt" if wd_auto_konto(a) else ""),
                                      "wd_auto_stand wie der WD-Farmer (Auto-Tage ∪ Hand-Tage + Korrektur)"))
        kon = fr["konsistenz"]
        cons_ok = True
        best = max(st["bester"] or 0.0, 0.0)
        if kon.get("an") and kon.get("pct"):
            an = (best / st["profit"]) if st["profit"] > 0 else None
            # ohne Trade im Zyklus ist nichts verletzt; mit Trades und Gewinn ≤ 0 gibt es keinen Payout
            cons_ok = (an is not None and an <= kon["pct"] / 100.0 + 1e-9) or not st["tage"]
            kach.append(kz_cons_kachel(kon["pct"], an, best, st["profit"], "Zyklus-Gewinn", "WD-Firmenregel konsistenz (Winning Days → Einstellungen → Firma)",
                                       "noch kein Zyklus-Gewinn"))
        else:
            kach.append(kz_cons_kachel(None, None, None, None, "", "WD-Firmenregel: Consistency aus"))
        mn = fr["min_netto"]
        mn_gilt = bool(mn.get("an")) and st["nr"] >= int(mn.get("ab_zyklus") or 1)
        zg = (wz or {}).get("gewinn") if (wz and wz.get("art") == "tradeify" and wz.get("gewinn") is not None) else st["profit"]
        mn_ok = (not mn_gilt) or (zg is not None and zg >= float(mn.get("usd") or 0))
        if wz and wz.get("art") != "tradeify" and wz.get("firma_key"):
            # Verlusttag aus dem Zyklus dieser Seite (im 1. Zyklus zählt wd_zyklus_stand des Farmers noch keine Tage — der Recoverer gilt dort ohnehin nicht)
            _vl = wz.get("verlust") or st.get("verlust")
            kach.append(kz_kachel("recoverer", "Recoverer", kz_usd(-_vl) if _vl else "kein Verlusttag", "Verlusttag" if _vl else None,
                                  (f"Ziel {kz_usd(wz['ziel'])} · Hedge {_liq_de(wz['hedge_eur'])} €" if wz.get("aktiv") and wz.get("ziel") else wz.get("grund")),
                                  None, "", None, ["Aktiv", "warn"] if wz.get("aktiv") else ["Aus", "grau"], wz.get("grund") or ""))
        else:
            kach.append(kz_kachel("zyklus", "Zyklus-Gewinn", kz_usd(zg, 0, True) if zg is not None else None, None,
                                  (f"Mindest-Net-Profit {kz_usd(mn.get('usd'))} ab Zyklus {mn.get('ab_zyklus')}" if mn.get("an") else "kein Mindest-Net-Profit"),
                                  None, "gut" if (mn_gilt and mn_ok) else "rot" if mn_gilt else "", None,
                                  (["Erfüllt", "gut"] if mn_ok else ["Gesperrt", "rot"]) if mn_gilt else None,
                                  (wz or {}).get("grund") or "WD-Firmenregel min_netto"))
        if ist is not None and soll:
            checks.append(["ok" if ist >= soll else "nein", "Winning Days" if ist_wd else "Ziel-Tage", f"{ist} / {soll}"])
        if kon.get("an") and kon.get("pct"):
            checks.append([("ok" if cons_ok else "nein") if st["tage"] else "info", f"Consistency ≤ {kon['pct']} %",
                           kz_pct((best / st["profit"]) if st["profit"] > 0 else None) if st["tage"] else "noch kein Trade"])
        checks.append(["info", "Zyklus-Gewinn", kz_usd(zg, 0, True) if zg is not None else "—"])
        checks.append([("ok" if mn_ok else "nein") if mn_gilt else "info", "Mindest-Net-Profit",
                       (f"≥ {kz_usd(mn.get('usd'))}" if mn_gilt else f"ab Zyklus {mn.get('ab_zyklus')}") if mn.get("an") else "aus"])
        if wz and wz.get("art") != "tradeify" and wz.get("firma_key"):
            checks.append(["info", "Recoverer", ("aktiv · Tagesverlust " + kz_usd(-wz["verlust"])) if wz.get("aktiv") else "aus"])
        # „Payout ab" (Tage) gibt es nur bei CFD — bei Futures zählen nur die Winning Days (Finn 05.11.2026, K2)
        bekannt = ist is not None and soll
        ok = bool(bekannt and ist >= soll and cons_ok and mn_ok and not any(c[0] == "nein" for c in checks))
        fehlt = [c[1] for c in checks if c[0] == "nein"]
        out["urteil"] = {"art": "payout", "titel": "Payout", "ok": ok if bekannt else None,
                         "sub": f"Zyklus {st['nr']}" + (f" · seit {kz_tag(out['zyklus']['seit'])}" if out["zyklus"]["seit"] else ""),
                         "text": "Payout möglich" if ok else "Noch kein Payout" if bekannt else "kein WD-Ziel",
                         "grund": ("alles erfüllt" if ok else "fehlt: " + ", ".join(fehlt)) if bekannt else "am Konto kein Ziel (goal_target)", "checks": checks}
    if typ == "funded" and isinstance(ctx.get("fdp"), dict):
        try:
            out["abhak"] = kz_fdp_abhak(a, ctx["fdp"], bal, plaene, ctx.get("bal_quelle"))
        except Exception as e:
            print(f"[konto-ziele] ⚠️ Funded-Futures-Ziel {aid[:8]}: {type(e).__name__}: {e}", flush=True)
    kach.append(kz_trades_kachel(phase, (out.get("zyklus") or {}).get("seit")))
    out["kacheln"] = kach
    out["payouts"] = kz_payouts(*ctx["payouts"]) if ctx.get("payouts") else None
    return out


def kz_fdp_abhak(a, fdp, bal, plaene, bal_quelle=None):
    """REIN RECHNEND (testbar, AP6 11.11.2026): Abhak-Stand eines Funded-Futures-Kontos (Typ funded) — Ziel wie der Funded-Planer Futures (fdp_konto_anzeige:
    Zyklus-Start aus fdp_zyklus, Ziel = Start + fdp_ziel_gewinn, je Konto × Zyklus fest), erreicht wie fdp_konto_rechnen (Rest ≤ 0,005 $; mehr als ein Trade über dem
    Ziel = unplausibel → nicht erreicht, wie dort). Das Popup wählt dann „→ Winning Days“ vor — dieselbe Umstellung, die fdp_planen am Ziel macht.
    → {bal, start, ziel_bal, rest, erreicht, bereit, wartet, schritt, ok_text, fehlt_text, checks} | None (keine Werte für die Größe / keine Balance)."""
    regel = (fdp or {}).get("regel") or {}
    g = _wd_konto_groesse(a)
    jg = fdp_je_groesse(regel, g)
    if not jg or not g or bal is None:
        return None
    pl = [dict(p, bal_start=((p.get("tv") or {}) if isinstance(p.get("tv"), dict) else {}).get("balance_start")) for p in (plaene or [])]
    _eb = fdp_express_basis(a, g)
    if _eb:   # TS2: Topstep Express 0-basiert — absolut rechnen wie fdp_planen (Größe + TopstepX-Stand), sonst stünde jedes Konto „unplausibel“/weit vom Ziel
        if bal_quelle != "TSX":   # TS2-Prüfer: der alte TSX-Sync (acc_balance_wahl) ist schon absolut
            bal = float(bal) + _eb
        pl = [dict(p, bal_start=fdp_bal_start_abs(p.get("bal_start"), ((p.get("tv") or {}) if isinstance(p.get("tv"), dict) else {}).get("balance_relativ"), _eb, g))
              for p in pl]
    zy = fdp_zyklus(g, (fdp or {}).get("pay"), pl)
    an = fdp_konto_anzeige(g, jg, float(bal), zy, fdp_tage, pl, str(a.get("id")))
    start, ziel = an["start"], an["ziel"]
    dd = _wd_num(jg.get("dd"))
    if regel.get("tp_modus") == "pump2":
        # Prüfer-MUSS: Pump-Modell (Tradeify/Lucid) wie fdp_pump_konto — Ziel-Niveau aus fdp_pump_tag_wurf (fest je Konto × Zyklus, ohne Tag), plausibel bis Ziel + dd,
        # erreicht ab Rest < FDP_PUMP_TP_TOL_USD (fdp_pump_trade1)
        ziel = round(start + fdp_pump_tag_wurf(jg, str(a.get("id")), zy.get("nr"), "")["ziel_gewinn"], 2)
        plaus = float(bal) <= ziel + float(dd or 0)
        erreicht = plaus and (ziel - float(bal) < FDP_PUMP_TP_TOL_USD or fdp_ziel_tol_erreicht(jg, bal, start))   # FE1b wie fdp_pump_trade1
    else:
        plaus = float(bal) <= ziel + float(jg.get("max_trade") or (dd if regel.get("tp_modus") == "rest" else 0) or 0)
        erreicht = plaus and (ziel - float(bal) <= 0.005 or (float(bal) >= start - 0.005 and fdp_ziel_tol_erreicht(jg, bal, start)))   # FE1b wie fdp_konto_rechnen
    gew, z_rel = round(float(bal) - start, 2), round(ziel - start, 2)
    wert = f"{kz_usd(gew, 0, True)} / {kz_usd(z_rel, 0, True)}"
    fehlt = "" if erreicht else (f"Balance {_liq_de(bal)} $ unplausibel (Ziel {_liq_de(ziel)} $) — Balance neu lesen" if not plaus
                                 else f"Ziel {kz_usd(gew, 0, True)} von {kz_usd(z_rel, 0, True)} — fehlen {_liq_de(max(1.0, -(-(ziel - float(bal)) // 1)))} $")
    return {"bal": bal, "start": start, "ziel_bal": ziel, "rest": round(ziel - float(bal), 2), "erreicht": erreicht, "bereit": erreicht, "wartet": False,
            "schritt": "winning_days", "zyklus": zy.get("nr"), "ok_text": f"Ziel {wert}" if erreicht else "", "fehlt_text": fehlt,
            "checks": [["ok" if erreicht else "nein", "Ziel bis Winning Days", wert]]}


def _kz_fcp_tag(z, felder):
    """ZV1c: Berlin-Tag eines Payout-Eintrags genau wie fcp_zyklus_start (erstes gefülltes Feld; reines Datum = Berlin-Kalendertag) — None, wenn unlesbar."""
    t = next((str(z.get(f)) for f in felder if z.get(f)), None)
    if not t:
        return None
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", t):
        return t
    ts = _ap_ts(t)
    return ts.astimezone(_ap_tz("Europe/Berlin")).date().isoformat() if ts is not None else None


def kz_payouts(pend, verw, buch):
    """REIN (testbar, K2 Finn 05.11.2026: „darunter ein Payout-Verlauf"): Payouts eines Kontos → [{datum, betrag, waehrung, status}] neueste zuerst.
    pending_payouts: status pending → „angefragt", received → „erhalten" (Datum = received_at, sonst requested_at), sonst der Status selbst;
    transactions kind payout ohne Anfrage, die auf sie zeigt (received_tx_id) → „erhalten"; managed_payouts → „verbucht". Nichts gerechnet.
    ZV1b: Anfragen (pending/received) tragen zusätzlich "anfrage" = requested_at-Tag, Buchungen ohne Anfrage den occurred_at-Tag — dieselben Grenzen
    wie ctx["wd_pay"] → wd_zyklus_stand (managed_payouts zählen dort nicht, hier also auch nicht).
    ZV1c: "fcp" = Berlin-Tag je Eintrag wie fcp_zyklus_start / fcp_payouts_zaehlen (alle Anfragen, managed_payouts, freie Buchungen) — für Funded CFD."""
    verknuepft = {str(z.get("received_tx_id")) for z in pend or () if z.get("received_tx_id")}
    out = []
    for z in pend or ():
        st = str(z.get("status") or "pending")
        d = (z.get("received_at") if st == "received" else None) or z.get("requested_at") or z.get("created_at")
        e = {"datum": str(d or "")[:10], "betrag": _wd_num(z.get("amount")), "waehrung": z.get("currency") or "USD",
             "status": {"pending": "angefragt", "received": "erhalten"}.get(st, st)}
        # ZV1b (Finn 10.11.2026): Zyklusgrenze für den Trade-Verlauf der Konto-Seite — derselbe Tag wie wd_zyklus_stand (requested_at, nur pending/received),
        # damit die Zyklus-Nummer mit Radar und Recoverer übereinstimmt. Buchungen und managed_payouts bekommen keins (kein zweiter Grenz-Tag je Payout)
        if st in ("pending", "received") and z.get("requested_at"):
            e["anfrage"] = str(z.get("requested_at"))[:10]
        # ZV1c (Master 10.11.2026): Grenze für Funded CFD wie fcp_zyklus_start / fcp_payouts_zaehlen — jede Anfrage (jeder Status), Berliner Tag
        f = _kz_fcp_tag(z, ("requested_at", "created_at"))
        if f:
            e["fcp"] = f
        out.append(e)
    for t in buch or ():
        if str(t.get("id")) in verknuepft:
            continue
        e = {"datum": str(t.get("occurred_at") or "")[:10], "betrag": _wd_num(t.get("amount")), "waehrung": t.get("currency") or "EUR", "status": "erhalten"}
        if t.get("occurred_at"):   # ZV1b: Buchung ohne Anfrage = eigene Grenze, wie ctx["wd_pay"] / _wd_zyklus_anhaengen (verknüpfte sind oben schon raus)
            e["anfrage"] = str(t.get("occurred_at"))[:10]
        f = _kz_fcp_tag(t, ("occurred_at",))   # ZV1c: freie Buchung zählt auch bei fcp_zyklus_start
        if f:
            e["fcp"] = f
        out.append(e)
    for z in verw or ():
        e = {"datum": str(z.get("payout_date") or z.get("created_at") or "")[:10], "betrag": _wd_num(z.get("amount")), "waehrung": "USD", "status": "verbucht"}
        f = _kz_fcp_tag(z, ("payout_date", "created_at"))   # ZV1c: managed_payouts zählen bei Funded CFD (fcp_zyklus_start), bei WD nicht
        if f:
            e["fcp"] = f
        out.append(e)
    return sorted(out, key=lambda x: x["datum"], reverse=True)


def kz_darf(uid, konto_uid, admin, gruppe):
    """REIN (testbar): darf dieser Login die Ziele des Kontos sehen? Eigenes Konto, Admin (Planer-Gate) oder Konto einer ID der eigenen Lese-Gruppe."""
    if not uid or not konto_uid:
        return False
    return str(uid) == str(konto_uid) or bool(admin) or (bool(gruppe) and str(konto_uid) in {str(x) for x in gruppe})


def _kz_karten():
    """Echo-/Duplikum-Balances (alle Logins) 60 s gemerkt — die Detailseite fragt je Klick, nicht im Takt."""
    if _kz_karten_cache.get("bis", 0) < time.time():
        _kz_karten_cache.update(karten=_ap_balance_karten(), bis=time.time() + KZ_KARTEN_TTL_S)
    return _kz_karten_cache["karten"]


@app.route("/konto-ziele", methods=["GET", "OPTIONS"])
def konto_ziele():
    """GET ?id=<accounts.id> → kz_rechnen (s. oben). Nur lesen. 400 ohne id, 404 unbekannt, 403 fremdes Konto."""
    if request.method == "OPTIONS":
        return "", 200
    uid, err = _wd_login()
    if err:
        return err
    kid = str(request.args.get("id") or "").strip()
    if not re.fullmatch(r"[0-9a-fA-F-]{36}", kid):
        return jsonify({"ok": False, "msg": "id fehlt"}), 400
    try:
        try:
            try:   # O1: On Demand + festes Ziel (sql/2026-11-05_fcp_on_demand.sql) — fehlen die Spalten, wie bisher
                rows = sb_select("accounts", {"select": KZ_KONTO_SEL + ",on_demand,fcp_ziel", "id": f"eq.{kid}"}) or []
            except requests.exceptions.HTTPError as e:
                if "on_demand" not in str(getattr(e.response, "text", "") or e) and "fcp_ziel" not in str(getattr(e.response, "text", "") or e):
                    raise
                rows = sb_select("accounts", {"select": KZ_KONTO_SEL, "id": f"eq.{kid}"}) or []
        except requests.exceptions.HTTPError:
            rows = sb_select("accounts", {"select": AP_KONTO_FELDER_OHNE_CONS + ",ziel_usd,waiting_payout_since,payout_ready_at,wd_farm", "id": f"eq.{kid}"}) or []
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Konto nicht lesbar ({type(e).__name__})"}), 502
    if not rows:
        return jsonify({"ok": False, "msg": "Konto unbekannt"}), 404
    a = rows[0]
    darf = str(a.get("user_id")) == str(uid)
    if not darf:
        _mail, aerr = _planer_admin_auth()
        if aerr is not None and aerr[1] == 502:
            return aerr                    # Anmeldung nicht prüfbar — nicht als „fremdes Konto" melden
        darf = kz_darf(uid, a.get("user_id"), aerr is None, None if aerr is None else ap_lese_gruppe(uid))
    if not darf:
        return jsonify({"ok": False, "msg": "fremdes Konto"}), 403
    try:
        jetzt = datetime.now(timezone.utc).isoformat()
        echo_bal, dup_bal = _kz_karten()
        bal, _ccy, quelle, stand = acc_balance_wahl(a, echo_bal, dup_bal)
        plaene = _sb_all("trade_plans", {"select": KZ_PLAN_SEL, "master_account_id": f"eq.{kid}", "order": "started_at.asc"}) or []
        # Kernwerte und liq_regeln aus den 60-s-Caches des Radars (_liq_kw_laden = auto_plan_regeln.regeln.firmen, _liq_regeln_laden)
        ctx = {"bal": bal, "bal_quelle": quelle, "bal_stand": stand, "plaene": plaene, "jetzt": jetzt,
               "ap_firmen": ap_unt_firmen(a.get("user_id"), _liq_kw_laden() or [], streng=False), "liq_regeln": _liq_regeln_laden() or []}   # UNT3
        typ = str(a.get("account_type") or "").lower()
        verlauf = _liq_verlauf_laden([kid])
        ctx["peak"] = liq_peak({}, a, None, verlauf)
        ctx["peak_eod"] = liq_peak({"started_at": jetzt, "master_account_id": kid}, a, bal, verlauf,
                                   eod_tagesstart=kz_tagesstart(kz_phase_plaene(plaene, typ), bal, jetzt)[0], eod=True)
        if typ in ("funded_cfd", "funded", "winning_days"):
            # Payout-Zeilen EINMAL lesen (K2: dazu Betrag/Status für den Payout-Verlauf); Zählung/Zyklus unverändert aus denselben Zeilen
            pend = _sb_all("pending_payouts", {"select": "id,account_id,amount,currency,requested_at,status,received_at,received_tx_id,created_at",
                                               "account_id": f"eq.{kid}"}) or []
            verw = _sb_all("managed_payouts", {"select": "id,account_id,amount,payout_date,created_at", "account_id": f"eq.{kid}"}) or []
            buch = _sb_all("transactions", {"select": "id,account_id,amount,currency,occurred_at", "kind": "eq.payout", "account_id": f"eq.{kid}"}) or []
            ctx["payouts"] = (pend, verw, buch)
        if typ == "funded_cfd":
            ctx["fcp_regel"] = fd_unt_reg(_fcp_regeln_laden() or {}, "cfd", a.get("user_id")) or {}   # UNT4: Regel des Unternehmens der ID
            ctx["fcp_pay"] = ctx["payouts"]
            ctx["fcp_gt"] = fcp_gt_korr_laden([kid]).get(kid)   # GT2: Gewinntage von Hand (kz_rechnen bleibt rein rechnend)
        elif typ in ("funded", "winning_days"):
            ctx["wd_firmen_regeln"] = _wd_firmen_regeln_lesen()
            if typ == "funded":
                # AP6 (Finn 11.11.2026: „Ziel erreicht → Winning Days“ beim Abhaken): Regel des Funded-Planers Futures für Firma + Unternehmen der ID — dieselbe
                # Auswahl wie fdp_planen (fd_unt_an → ap_regel_finden), nur lesen; Firma nicht im Planer → kein Ziel (kz_rechnen lässt abhak weg)
                try:
                    _freg = _fdp_regeln_gemerkt() or {}   # KK1: 60 s gemerkt (je Funded-Konto sonst eine DB-Abfrage)
                    _fr = ap_regel_finden(fd_unt_an(_freg, "futures", a.get("user_id"), None, True), a.get("firm")) if _freg else None   # streng wie fdp_planen (an_von)
                    if _fr:
                        ctx["fdp"] = {"regel": _fr, "pay": [z.get("requested_at") or z.get("created_at") for z in pend] + [z.get("payout_date") or z.get("created_at") for z in verw]}
                except Exception as e:
                    print(f"[konto-ziele] ⚠️ Funded-Planer-Regel {kid[:8]}: {type(e).__name__}: {e}", flush=True)
            pay, verkn = [], set()
            for t in pend:                             # wie bisher: nur pending/received zählen für den Zyklus
                if str(t.get("status") or "") not in ("pending", "received"):
                    continue
                pay.append(t)
                if t.get("received_tx_id"):
                    verkn.add(str(t["received_tx_id"]))
            for t in buch:
                if str(t.get("id")) not in verkn and t.get("occurred_at"):
                    pay.append({"requested_at": str(t["occurred_at"])[:10], "status": "received"})
            ctx["wd_pay"] = pay
            if typ == "winning_days":
                k = {"id": kid, "user_id": str(a.get("user_id")), "name": a.get("name") or "", "firm": a.get("firm") or "",
                     "starting_balance": _wd_num(a.get("starting_balance")), "wd_farm": bool(a.get("wd_farm")),
                     "live_balance": _wd_num(a.get("tv_balance")) if (_wd_num(a.get("tv_balance")) or 0) > 0 else None,
                     "live_at": a.get("tv_balance_at"), "wd_zyklus_regel": a.get("wd_zyklus_regel")}
                if _wd_zyklus_anhaengen([k]):
                    ctx["wd_zyklus"] = k.get("zyklus")
        erg = kz_rechnen(a, ctx)
    except Exception as e:
        print(f"[konto-ziele] ⚠️ {kid[:8]}: {type(e).__name__}: {e}", flush=True)
        return jsonify({"ok": False, "msg": f"nicht rechenbar ({type(e).__name__})"}), 502
    erg["at"] = jetzt
    resp = jsonify(json.loads(json.dumps(erg, default=str)))
    resp.headers["Cache-Control"] = "no-store"
    return resp


@app.route("/admin/auto-plan/ablaufwert", methods=["POST", "OPTIONS"])
def admin_auto_plan_ablaufwert():
    """POST {zeiten?: [{pfad, wert}], zufall?: {k: wert}, auto_bestaetigen?: aus|cfd|alle, bloecke?: {block: {feld: zahl}}, schalter?: [{pfad,
    wert}], tagesteilung?: {feld: wert} (WS2, tt_einst_anwenden)} → Spalte zeiten und/oder regeln (E3b). Nur Admin.
    Alles oder nichts (ap_einst_zeiten_anwenden, ap_einst_regeln_anwenden); ein Update für beide Spalten."""
    if request.method == "OPTIONS":
        return "", 200
    _gs = _planer_schreib_gate()
    if _gs is not None:
        return _gs
    body = request.get_json(silent=True) or {}
    if body.get("gruppe_id"):
        # REGEL JE UNTERNEHMEN (Phase 1): nur das Startfenster der Gruppe (Abweichung zeiten.fenster); Schalter/Bestätigen/Zufall bleiben Standard
        gid = str(body.get("gruppe_id"))
        uid, reg, zeile, err = _ap_unt_zugang(gid)
        if err:
            return err
        if any(body.get(k) is not None for k in ("zufall", "auto_bestaetigen", "bloecke", "schalter", "aktiv", "tagesteilung")):
            return jsonify({"ok": False, "msg": "im Unternehmen ist nur das Startfenster änderbar (Schalter gelten für alle; Rest folgt in Phase 2)"}), 400
        if "regeln" not in zeile:
            return jsonify({"ok": False, "msg": AP_UNT_NICHT_FREI, "code": "unt_nicht_frei"}), 409
        abw, z_neu, grund = ap_unt_zeiten_aendern(reg.get("zeiten"), zeile.get("regeln"), body.get("zeiten") or [], body.get("standard") is True)
        if grund:
            return jsonify({"ok": False, "msg": grund}), 400
        jetzt_iso = datetime.now(timezone.utc).isoformat()
        g_flt, g_upd = ap_unt_stempel(zeile, jetzt_iso)       # gleichzeitiges Speichern überschreibt die Firmen-Abweichungen nicht
        flt = dict({"gruppe_id": f"eq.{gid}"}, **g_flt)
        try:
            rows = sb_update("auto_plan_gruppe", flt, dict({"regeln": abw, "updated_at": jetzt_iso}, **g_upd))
        except Exception as e:
            return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
        if not rows:
            return jsonify({"ok": False, "msg": "inzwischen geändert — Einstellungen neu laden und noch einmal speichern"}), 409
        ap_gruppe_regel_geaendert(gid, jetzt_iso)   # NP1
        print(f"[einstellungen] Unternehmen {gid[:8]} Startfenster {'auf Standard' if body.get('standard') is True else 'geändert'} ({uid})", flush=True)
        return jsonify({"ok": True, "zeiten": z_neu, "abweichung": ap_unt_abweichung_liste(abw, zeile.get("firmen_modell"))})
    admin, uid, reg, err = _ap_zugang()
    if err:
        return err
    if not admin:
        return jsonify({"ok": False, "msg": "Nur für Admins"}), 403
    patch = {}
    if body.get("zeiten") is not None:
        z_neu, grund = ap_einst_zeiten_anwenden(reg.get("zeiten"), body.get("zeiten"))
        if grund:
            return jsonify({"ok": False, "msg": grund}), 400
        patch["zeiten"] = z_neu
    if any(body.get(k) is not None for k in ("zufall", "auto_bestaetigen", "bloecke", "schalter")):
        r_neu, grund = ap_einst_regeln_anwenden(reg.get("regeln"), body.get("zufall"), body.get("auto_bestaetigen"), body.get("bloecke"),
                                                body.get("schalter"))
        if grund:
            return jsonify({"ok": False, "msg": grund}), 400
        patch["regeln"] = r_neu
    if body.get("tagesteilung") is not None:                  # WS2 Trades pro Tag (09.11.2026): Block regeln.tagesteilung, alles oder nichts
        _r0 = patch.get("regeln") or reg.get("regeln") or {}
        r_neu, grund = tt_einst_anwenden(_r0, body.get("tagesteilung"), {x["key"] for x in tt_firmen_auswahl(_r0.get("firmen") or [])},
                                         {str(g.get("id")) for g in admin_gruppen_daten().get("gruppen") or ()},
                                         {str(u) for u in (reg.get("user_ids") or ())})      # TT1: Test-IDs nur aus dem HT-Planer
        if grund:
            return jsonify({"ok": False, "msg": grund}), 400
        patch["regeln"] = r_neu
    if body.get("aktiv") is not None:                        # Planer an/aus (Spalte aktiv: Nachtlauf + Nachplanen)
        if not isinstance(body.get("aktiv"), bool):
            return jsonify({"ok": False, "msg": "aktiv = true | false"}), 400
        patch["aktiv"] = body["aktiv"]
    if not patch:
        return jsonify({"ok": False, "msg": "nichts zu ändern"}), 400
    patch["updated_at"] = datetime.now(timezone.utc).isoformat()
    try:
        sb_update("auto_plan_regeln", {"id": "eq.1"}, patch)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
    print(f"[einstellungen] Ablauf: {', '.join(k for k in patch if k != 'updated_at')} geändert ({uid})", flush=True)
    r = patch.get("regeln") or reg.get("regeln") or {}
    return jsonify({"ok": True, "zeiten": patch.get("zeiten", reg.get("zeiten")), "zufall": ap_zufall(r),
                    "auto_bestaetigen": ap_auto_best_umfang(r), "aktiv": patch.get("aktiv", reg.get("aktiv") is True), "tagesteilung": tt_param(r)})


# Nachtlauf-Uhrzeit (07.10.2026, Finn: „heute Nacht schon planen" — 01:00 Dubai statt 00:00 dt, = 23:00 dt Sommer / 22:00 dt
# Winter am Vorabend). Parameter auto_plan_regeln.zeiten.nachtlauf {uhr, tz}; fehlt er, gilt genau dieser Standard. Geplant wird
# der Handelstag (Mo–Fr, deutsches Datum), dessen Fenster ab 00:00 dt beginnen: Lauf für Tag T = letztes uhr@tz vor/um T 00:00 dt
# (Di 01:00 Dubai = Mo 23:00 dt → Dienstag). Verpasst (Deploy, Neustart, Railway weg) → sofort nachholen, solange T in dt noch
# läuft. Nie doppelt: der Claim in auto_plan_lauf (Unique-Index tag where quelle='nacht', ap_planen) — auch bei zwei Instanzen.
AP_NACHT_STANDARD = {"uhr": "01:00", "tz": "Asia/Dubai"}


def ap_nacht_param(zeiten):
    """zeiten.nachtlauf → {uhr 'HH:MM', tz}; Ungültiges fällt einzeln auf AP_NACHT_STANDARD zurück."""
    n = (zeiten or {}).get("nachtlauf") if isinstance(zeiten, dict) else None
    n = n if isinstance(n, dict) else {}
    uhr, tz = str(n.get("uhr") or "").strip(), str(n.get("tz") or "").strip()
    m = re.match(r"^(\d{1,2}):(\d{2})$", uhr)
    if not m or int(m.group(1)) > 23 or int(m.group(2)) > 59:
        uhr = AP_NACHT_STANDARD["uhr"]
    else:
        uhr = f"{int(m.group(1)):02d}:{m.group(2)}"
    try:
        _ap_tz(tz)
    except Exception:
        tz = AP_NACHT_STANDARD["tz"]
    return {"uhr": uhr, "tz": tz}


def ap_nacht_lauf_um(tag, param):
    """Lauf-Zeitpunkt (UTC) für den Handelstag `tag` (date, deutsches Datum): das letzte uhr@tz vor/um tag 00:00 dt."""
    beginn = datetime(tag.year, tag.month, tag.day, tzinfo=_ap_tz(AP_TZ_TAG))
    tz = _ap_tz(param["tz"])
    h, mi = (int(x) for x in param["uhr"].split(":"))
    lokal = beginn.astimezone(tz).date()
    um = datetime(lokal.year, lokal.month, lokal.day, h, mi, tzinfo=tz)
    if um > beginn:
        vortag = lokal - timedelta(days=1)
        um = datetime(vortag.year, vortag.month, vortag.day, h, mi, tzinfo=tz)
    return um.astimezone(timezone.utc)


def ap_nacht_ziel(jetzt, param):
    """→ (faellig, naechster): faellig = (tag, lauf_um) des jüngsten Handelstags, dessen Lauf-Zeitpunkt vorbei ist und der in dt
    noch nicht zu Ende ist (sonst None); naechster = (tag, lauf_um) des kommenden Laufs."""
    tz_tag = _ap_tz(AP_TZ_TAG)
    heute = jetzt.astimezone(tz_tag).date()
    faellig = naechster = None
    for i in range(-3, 5):
        t = heute + timedelta(days=i)
        if t.weekday() >= 5:
            continue
        um = ap_nacht_lauf_um(t, param)
        ende = datetime(t.year, t.month, t.day, tzinfo=tz_tag) + timedelta(days=1)   # Wanduhr-Mitternacht, auch bei Umstellung
        if um <= jetzt < ende:
            faellig = (t, um)
        elif um > jetzt and naechster is None:
            naechster = (t, um)
    return faellig, naechster


def ap_nacht_tick(jetzt, zustand):
    """Ein Takt des Nachtlaufs. zustand (= _ap_info) merkt im Speicher den erledigten Tag + die Parameter (alle 10 min neu
    gelesen); der dauerhafte Merker ist der Claim in ap_planen — nach einem Neustart prüft der erste Takt, ob schon gelaufen."""
    if time.time() - (zustand.get("nacht_gelesen") or 0) > 600:
        reg = (sb_select("auto_plan_regeln", {"select": "zeiten", "id": "eq.1"}) or [{}])[0]
        zustand["nacht_param"], zustand["nacht_gelesen"] = ap_nacht_param(reg.get("zeiten")), time.time()
    param = zustand.get("nacht_param") or dict(AP_NACHT_STANDARD)
    faellig, naechster = ap_nacht_ziel(jetzt, param)
    zustand["nachtlauf"] = dict(param, naechster_tag=naechster[0].isoformat() if naechster else None,
                                naechster_um=naechster[1].isoformat() if naechster else None)
    if not faellig:
        return None
    tag = faellig[0].isoformat()
    if zustand.get("letzter_tag") == tag:
        # 07.10.2026 (Neuplanen per sql/…_neu_planen.sql ohne Railway-Neustart): alle 10 min nachsehen, ob der Claim noch da ist —
        # wurde er umbenannt (oder war der Planer aus und ist jetzt an), läuft der Tag noch einmal
        if time.time() - (zustand.get("claim_geprueft") or 0) < 600:
            return None
        zustand["claim_geprueft"] = time.time()
        if sb_select("auto_plan_lauf", {"select": "id", "tag": f"eq.{tag}", "quelle": "eq.nacht", "limit": "1"}):
            return None
        zustand["letzter_tag"] = None
    # TAGES-RESET (21.10.2026, Finn: „das soll immer daily resetten") VOR dem Auto-Planer — auch, wenn der Planer aus ist: liegengebliebene
    # Pläne früherer Tage weg bzw. nach „Überprüfen", damit ihre Konten in derselben Nacht wieder planbar sind (eigener try: ein Fehler
    # hier hält den Nachtlauf nie auf)
    try:
        zustand["tagesreset"] = dict(ap_tagesreset(tag, jetzt), tag=tag, at=jetzt.isoformat())
    except Exception as e:
        zustand["tagesreset"] = {"tag": tag, "at": jetzt.isoformat(), "fehler_text": f"{type(e).__name__}: {e}"}
        print(f"[tages-reset] ⚠️ {type(e).__name__}: {e}", flush=True)
    reg = (sb_select("auto_plan_regeln", {"select": "aktiv", "id": "eq.1"}) or [{}])[0]
    erg = None
    if reg.get("aktiv"):
        erg = ap_planen(tag, quelle="nacht")
        spaet = int((jetzt - faellig[1]).total_seconds() // 60)
        if str(erg.get("msg") or "").startswith("schon geplant"):
            print(f"[auto-plan] {tag} nacht: schon geplant (Claim vorhanden)", flush=True)
        elif spaet >= 2:
            print(f"[auto-plan] Nachtlauf {tag} nachgeholt (fällig seit {spaet} min, {param['uhr']} {param['tz']}): "
                  f"{len(erg.get('geplant') or [])} geplant · {erg.get('msg') or 'ok'}", flush=True)
        zustand["last_run"] = time.time()
        zustand["runs"] = (zustand.get("runs") or 0) + 1
        zustand["letzter"] = {k: erg.get(k) for k in ("tag", "msg")}
    zustand["letzter_tag"] = tag      # aktiv aus → erst beim Claim-Nachsehen (10 min) bzw. nach Neustart wieder fragen
    zustand["claim_geprueft"] = time.time()
    return erg


# ══ NACHPLANEN (08.10.2026, Master/Finn; Zielbild Trade-Planer 07.10.2026: „Nachplanen neuer Konten alle 10 min bis start_bis").
# Anlass: Finn setzte am 08.10.2026 um 01:20 Dubai fünf IDs in auto_plan_regeln.user_ids — der Nachtlauf (01:00 Dubai) war durch,
# bis zum nächsten hätte niemand Vorschläge bekommen; einziger Weg war „Jetzt planen" von Hand (ersetzt dabei alle Vorschläge).
# Jetzt: alle 10 min (ap_loop) zwischen 00:00 dt und start_bis − 15 min prüft Railway, welche Konten der Planer-IDs HEUTE noch
# keinen Plan haben, und stößt für GENAU diese ap_planen(nur_konten=…) an — dieselbe Rechenstrecke (Tranchen, Fenster, Delta,
# Richtungsschutz), bestehende Pläne bleiben, Protokoll nur bei Treffer. Rein rechnende Teile (Fenster, Kandidaten) sind testbar.
AP_NACHPLAN_TAKT_S = 300                 # 5 min (Finn 15.10.2026, vorher 10): neue/umgestellte Konten sollen schneller im Plan stehen
# Gründe des letzten Laufs, die sich innerhalb des Tages nicht von selbst ändern — solche Konten werden nicht alle 10 min neu gerechnet
# „vom Auto-Planer ausgenommen" ist seit 08.10.2026 KEIN fester Grund mehr: der Haken wird je Konto live geprüft (auto_planer is False) —
# vorher blieb ein Konto, dessen Haken Finn wieder gesetzt hatte, bis zum nächsten Tag draußen (Grund aus dem letzten Lauf)
AP_GRUND_HEUTE_GEHANDELT = "heute schon gehandelt — ein Trade pro Konto und Tag"
AP_NACHPLAN_FEST_GRUENDE = ("heute schon gehandelt", "keine Regel für diese Firma", "kein freies Zeitfenster mehr",
                            "letzter Trade ", "Kontogröße", "Ziel erreicht", "bis zum Ziel")
# Davon hängen diese an auto_plan_regeln (Firmen-Regel, Größen/je_groesse, Zeitfenster) statt am Konto — sie gelten nur, solange die
# Regeln seit dem Lauf nicht geändert wurden (auto_plan_regeln.updated_at > Zeit des Laufs → Konto wieder Kandidat). Konto-Gründe
# (heute gehandelt, Ziel, letzter Trade) bleiben fest. Anlass Finn 08.10.2026: FTMO bekam ~03:45 UTC Werte + planen:true,
# FundingPips/FundedNext ~03:53/04:00 UTC je_groesse für 50k — Chris' FTMO 100k („keine Regel für diese Firma") und FundingPips/
# FundedNext 50k („… passt zu keiner Kontogröße") blieben trotzdem bis morgen draußen und unter „Braucht dich" (Grund aus dem 03:20-Lauf).
AP_NACHPLAN_REGEL_GRUENDE = ("keine Regel für diese Firma", "Kontogröße", "kein freies Zeitfenster mehr")


def ap_nachplan_fenster(d, zeiten):
    """REIN RECHNEND: darf jetzt nachgeplant werden? d = jetzt in deutscher Zeit. Mo–Fr, 00:00 ≤ jetzt < start_bis − Vorlauf."""
    if d.weekday() >= 5:
        return False
    m = d.hour * 60 + d.minute
    return 0 <= m < ap_start_bis(zeiten) - AP_NACHPLAN_VORLAUF_MIN


def _ap_plan_am_tag(p, tag, tz):
    """REIN RECHNEND: belegt dieser Plan das Konto für den Tag? Laufend/Überprüfen immer; geplant, wenn planned_for oder start_um
    (in tz) auf den Tag fällt — ein Plan ohne beides blockt vorsichtshalber auch."""
    st = str(p.get("status") or "")
    # letzter Topstep-Trade des Tages (kette_te, 30.10.2026): nur sein Tag ist belegt, auch wenn Finn ihn noch nicht abgehakt hat
    te = st == "review" and isinstance(p.get("kette_te"), dict)
    if st in ("open", "review") and not te:
        return True
    if st == "completed" or te:
        # 08.10.2026 EIN TRADE PRO KONTO UND TAG (Finn: „Es wird immer nur maximal ein Trade pro Tag gemacht?“): ein heute schon
        # beendeter (abgehakter) Trade belegt das Konto für den Rest des Tages. Vorfall: Inas drei Apex-Konten endeten 03:57 Dubai
        # im Tagesstopp, das Nachplanen legte um 07:20 Dubai für dieselben Konten neue Trades für HEUTE an (08:47/17:04/18:06).
        for k in ("started_at", "ended_at", "completed_at", "start_um"):
            v = p.get(k)
            if not v:
                continue
            try:
                if datetime.fromisoformat(str(v).replace("Z", "+00:00")).astimezone(tz).strftime("%Y-%m-%d") == tag:
                    return True
            except (TypeError, ValueError):
                continue
        return False
    if st != "planned":
        return False
    if p.get("planned_for"):
        return str(p.get("planned_for")) == tag
    su = p.get("start_um")
    if not su:
        return True
    try:
        return datetime.fromisoformat(str(su).replace("Z", "+00:00")).astimezone(tz).strftime("%Y-%m-%d") == tag
    except (TypeError, ValueError):
        return True


# ══ TW1 HANDELS-WÜRFEL (11.11.2026, Finn ~02:00/02:05 Dubai: „Aktuell wird ja jeder Trade jeden Tag geplant … 75 % aller Trades aller Accounts machen einen
# Trade, und die anderen 25 % nicht … Die werden einfach nicht getradet, fertig. Oder am nächsten Tag wird wieder neu gewürfelt. Es kann auch sein, dass mal
# kurz 1, 2, 3 Tage gar nicht getradet wird … Ich kann für jedes einzelne Ding diese Wahrscheinlichkeit selber einstellen, aber das Prinzip soll für alle gelten.")
# Je Planer × Unternehmen EIN Prozentwert (Tabelle planer_handel_wuerfel, sql/2026-11-11_tageswuerfel_75.sql): so viele Konten bekommen je Tag ihren Trade.
# Gewürfelt wird je Konto × Tag FEST (Hash statt Zufall je Lauf): das Nachplanen (5 min) hält ein Konto nur über die „festen Gründe" des letzten Laufs
# draußen und der Funded-Takt rechnet jedes Mal alle Konten neu — ein Würfel je Lauf hätte die Pause-Tage bis mittags wieder aufgefüllt (Befund TW1).
# Nachtlauf, Nachplanen, Knopf, Probelauf und Takt sehen so denselben Wurf. Der Würfel greift nur, wo ein NEUER Plan entstünde — bestehende, laufende und
# von Hand angelegte Pläne bleiben. Keine Zeile / Tabelle fehlt / Lesefehler → 100 % = wie vor TW1. Ein Unternehmen hat seine eigene Zeile; ohne sie gilt
# 100 % — es erbt den Wert von Hermann Technologies bewusst NICHT (Master 11.11.2026: „Emins Unternehmen eigene Einstellung, dort Standard 100 %"). ══
TW_PLANER = ("challenge_cfd", "challenge_futures", "funded_cfd", "funded_futures", "winning_days")
# TW3 FIRMEN-WÜRFEL (Finn 12.11.2026: „IDs haben Propfirms, Propfirms haben Accounts … eine Ebene höher: die Prop-Firma der jeweiligen ID soll zu 20 % an einem Tag
# gar nicht getradet werden — Risiko verteilen“; Korrektur 12.11.: „Zufalls-Propfirms bleiben bei 25 %“ → SQL HT 75 % handelt): EIN Wert je Unternehmen (Zeile planer = TW_FIRMA in planer_handel_wuerfel), fester Wurf je ID × Firma × Tag
# (tw_firma_wurf, Firma nach _ap_norm — „FundedNext“ und „FundedNext Futures“ sind getrennt). Trifft er, plant KEIN Planer für diese ID × Firma an dem Tag einen
# neuen Trade (ein Wurf für alle fünf Planer); danach greift der Konto-Wurf (TW1) für die übrigen. Ohne Zeile 100 % (wie bisher), ein Unternehmen erbt nicht.
TW_FIRMA = "firma_je_id"
TW_EINST = TW_PLANER + (TW_FIRMA,)
TW_PLANER_NAME = {"challenge_cfd": "Challenge-Planer CFD", "challenge_futures": "Challenge-Planer Futures", "funded_cfd": "Funded-Planer CFD",
                  "funded_futures": "Funded-Planer Futures", "winning_days": "Winning Days", "firma_je_id": "Firma je ID"}
TW_STANDARD_PCT = 100.0
TW_CACHE_S = 60
TW_GRUND = "Pause-Tag (Handels-Würfel {pct} %) — heute kein Trade, morgen neu gewürfelt"   # Schlüssel-Anfang „Pause-Tag" (HAND_PLANER_OHNE) — bewusst NICHT in AP_NACHPLAN_FEST_GRUENDE: hebt Finn den Wert tagsüber, holt das Nachplanen die Konten dazu
TW_GRUND_WD = "Pause-Tag (Handels-Würfel) – heute kein Trade, morgen neu gewürfelt"         # = prophos.html WD_HINWEIS_PAUSE — nie umbenennen
TW_GRUND_FIRMA = "Pause-Tag Firma (Firmen-Würfel {pct} %) — heute kein Trade bei {firma} für diese ID, morgen neu"   # TW3, Schlüssel-Anfang „Pause-Tag" (HAND_PLANER_OHNE)
TW_GRUND_FIRMA_WD = "Pause-Tag Firma (Firmen-Würfel) – heute kein Trade bei dieser Firma für diese ID, morgen neu"   # = prophos.html WD_HINWEIS_PAUSE_FIRMA — nie umbenennen
TW_ALT_S = 900          # Prüfer S3: bei einem kurzen Lesefehler gilt der letzte gute Stand bis zu 15 min weiter (wie ap_unt_kontext), sonst füllte ein
                        # einzelner Supabase-Aussetzer in diesem Lauf alle Pause-Tage auf
_tw = {"bis": 0.0, "werte": None, "tabelle": True, "fehler_at": 0.0, "gut": None, "gut_at": 0.0, "fehler": ""}
_tw_lock = threading.Lock()


def fest_wurf(text):
    """REIN RECHNEND (testbar): fester Wurf in [0, 1) aus einem Text (sha256, erste 13 Hex-Stellen ÷ 16^13, gleichverteilt) — gleicher Text, gleicher Wurf,
    ohne Speicher. Genutzt vom TW1-Würfel (tw_wurf, = prophos.html hwWurf) und vom Apex-Tagesdeckel (ap_tagesdeckel, AP1)."""
    return int(hashlib.sha256(str(text).encode("utf-8")).hexdigest()[:13], 16) / float(16 ** 13)


def tw_wurf(planer, konto_id, tag):
    """REIN RECHNEND (testbar): fester Wurf in [0, 1) je Planer × Konto × Tag (sha256, gleichverteilt). Gleiches Konto am gleichen Tag → gleicher Wurf."""
    return fest_wurf(f"tw1|{planer}|{konto_id}|{str(tag)[:10]}")


def tw_handelt(planer, konto_id, tag, pct):
    """REIN RECHNEND (testbar): bekommt das Konto heute seinen Trade? pct None/≥ 100 → immer, ≤ 0 → nie, sonst Wurf × 100 < pct."""
    p = _wd_num(pct)
    if p is None or p >= 100:
        return True
    if p <= 0:
        return False
    return tw_wurf(planer, konto_id, tag) * 100.0 < p


def tw_pct_von(werte, planer, gid):
    """REIN RECHNEND (testbar): Prozent für Planer × Unternehmen aus {(planer, gruppe): pct}; gid None/'' = Standard (HT). Fehlt die Zeile → 100."""
    v = _wd_num((werte or {}).get((str(planer), str(gid or ""))))
    return float(v) if v is not None and 0 <= v <= 100 else TW_STANDARD_PCT


def tw_werte(frisch=False):
    """{(planer, gruppe): pct} aus planer_handel_wuerfel, 60 s gemerkt. Tabelle fehlt → {} (= überall 100 %, wie vor TW1). Lesefehler → der letzte gute Stand,
    solange er ≤ TW_ALT_S alt ist, sonst {} (Prüfer S3). Höchstens stündlich geloggt; _tw["fehler"] trägt den Grund für GET /admin/handel-wuerfel."""
    jetzt = time.time()
    with _tw_lock:
        if not frisch and _tw["werte"] is not None and _tw["bis"] > jetzt:
            return _tw["werte"]
    try:
        rows = sb_select("planer_handel_wuerfel", {"select": "planer,gruppe,pct"}) or []
        werte = {(str(r.get("planer")), str(r.get("gruppe") or "")): _wd_num(r.get("pct")) for r in rows if r.get("planer") in TW_EINST}
        with _tw_lock:
            _tw.update(bis=jetzt + TW_CACHE_S, werte=werte, tabelle=True, gut=werte, gut_at=jetzt, fehler="")
        return werte
    except Exception as e:
        _r = getattr(e, "response", None)
        fehlt = getattr(_r, "status_code", None) in (400, 404) and "planer_handel_wuerfel" in str(getattr(_r, "text", "") or "")
        with _tw_lock:
            alt = (not fehlt) and _tw.get("gut") is not None and jetzt - (_tw.get("gut_at") or 0) <= TW_ALT_S
            werte = _tw["gut"] if alt else {}
            _tw.update(bis=jetzt + (TW_CACHE_S if fehlt else 15), werte=werte, tabelle=not fehlt,
                       fehler="" if fehlt else f"nicht lesbar ({type(e).__name__}){' — letzter Stand gilt' if alt else ''}")
        if jetzt - _tw["fehler_at"] > 3600:
            _tw["fehler_at"] = jetzt
            print(f"[handels-wuerfel] {'Tabelle fehlt (SQL 2026-11-11_tageswuerfel_75.sql) — alle Planer 100 %' if fehlt else '⚠️ nicht lesbar: ' + type(e).__name__ + (' — letzter Stand gilt' if alt else ' — alle Planer 100 %')}", flush=True)
        return werte


def tw_pct(planer, uid, werte=None, ktx=None):
    """Prozent für das Unternehmen der ID: HT/ohne Unternehmen → Standard-Zeile, Mitglied eines Unternehmens → dessen Zeile (ohne: 100).
    Kontext nicht sicher lesbar (ap_unt_kontext ok False) → 100 für jede ID (lieber wie bisher handeln als eine fremde Regel anwenden)."""
    w = tw_werte() if werte is None else werte
    if not w:
        return TW_STANDARD_PCT
    k = ktx if ktx is not None else ap_unt_kontext()
    if not k.get("ok"):
        return TW_STANDARD_PCT
    gid = (k.get("gid_von") or {}).get(str(uid or ""))
    return tw_pct_von(w, planer, gid)


def tw_firma_wurf(uid, firma, tag):
    """REIN RECHNEND (testbar, TW3): fester Wurf in [0, 1) je ID × Firma × Tag — unabhängig vom Konto-Wurf (anderer Schlüssel „tw3|…“), Firma nach _ap_norm."""
    return fest_wurf(f"tw3|{uid}|{_ap_norm(firma)}|{str(tag)[:10]}")


def tw_firma_handelt(uid, firma, tag, pct):
    """REIN RECHNEND (testbar, TW3): handelt die ID heute bei dieser Firma? pct None/≥ 100 → immer, ≤ 0 → nie, ohne ID/Firma → immer (wie bisher)."""
    p = _wd_num(pct)
    if p is None or p >= 100 or not uid or not str(firma or "").strip():
        return True
    if p <= 0:
        return False
    return tw_firma_wurf(uid, firma, tag) * 100.0 < p


def tw_pause_grund(planer, a, tag, werte=None, ktx=None):
    """Konto-Zeile a (id, user_id, firm bzw. master_firm) → Grund-Text, wenn heute Pause-Tag, sonst None. Jeder Fehler → None (handelt wie bisher).
    TW3: zuerst der Firmen-Wurf je ID × Firma × Tag (TW_FIRMA, gilt für alle Planer gleich), dann der Konto-Wurf (TW1) für die übrigen.
    TW2: von Hand reingenommen (Marke tw_hand je Konto × Tag, tw_hand_konten) → None — die Hand überstimmt beide Würfe, nur für dieses Konto an diesem Tag."""
    try:
        uid = (a or {}).get("user_id")
        firma = (a or {}).get("firm") or (a or {}).get("master_firm")
        grund = None
        pf = tw_pct(TW_FIRMA, uid, werte, ktx) if "TW_FIRMA" in globals() else TW_STANDARD_PCT   # get: ältere Selftest-Lader ohne TW3
        if pf < 100 and not tw_firma_handelt(uid, firma, tag, pf):
            grund = TW_GRUND_FIRMA_WD if planer == "winning_days" else TW_GRUND_FIRMA.format(pct=_tw_pct_txt(pf), firma=str(firma).strip())
        else:
            pct = tw_pct(planer, uid, werte, ktx)
            if pct >= 100 or tw_handelt(planer, str((a or {}).get("id") or ""), tag, pct):
                return None
            grund = TW_GRUND_WD if planer == "winning_days" else TW_GRUND.format(pct=_tw_pct_txt(pct))
        if "tw_hand_konten" in globals() and str((a or {}).get("id") or "") in tw_hand_konten(tag):   # get: ältere Selftest-Lader ziehen tw_pause_grund ohne TW2
            return None
        return grund
    except Exception as e:
        print(f"[handels-wuerfel] ⚠️ {planer}: {type(e).__name__}: {e} — handelt wie bisher", flush=True)
        return None


def _tw_pct_txt(p):
    return (f"{p:.1f}".rstrip("0").rstrip(".")).replace(".", ",")


def tw_nachplan_filter(kand, konten, tag, firmen):
    """Nachplan-Kandidaten (Konto-IDs) ohne die Konten, die heute Pause-Tag haben (Challenge-Planer). Jeder Fehler → Liste unverändert."""
    try:
        w = tw_werte()
        if not w or not kand:
            return kand
        if firmen is None:   # Aufrufer lesen auto_plan_regeln ohne die Spalte regeln (Prüfer Runde 2) — Route je Firma hier aus dem Standard
            firmen = ((sb_select("auto_plan_regeln", {"select": "regeln", "id": "eq.1"}) or [{}])[0].get("regeln") or {}).get("firmen") or []
        k, je = ap_unt_kontext(), {str(a.get("id")): a for a in konten or []}
        out = []
        for kid in kand:
            a = je.get(str(kid))
            regel = ap_regel_finden(firmen, a.get("firm")) if a else None
            pl = "challenge_futures" if ap_klasse((regel or {}).get("route"), (a or {}).get("firm")) == "futures" else "challenge_cfd"
            if not (a and tw_pause_grund(pl, a, tag, w, k)):
                out.append(kid)
        return out
    except Exception as e:
        print(f"[handels-wuerfel] ⚠️ Nachplan-Filter: {type(e).__name__}: {e}", flush=True)
        return kand


@app.route("/admin/handel-wuerfel", methods=["GET", "POST", "OPTIONS"])
def admin_handel_wuerfel():
    """TW1: GET [?unternehmen=gid] → {ok, werte: {planer: pct|None}, standard_pct, unternehmen: {gruppe_id, name}|None, darf, tabelle};
    POST {planer, pct: 0–100 | None (= Zeile weg = 100 %), gruppe_id?} → {ok, werte}. Unternehmen + Recht wie die Funded-Einstellungen (_fd_unternehmen:
    Admin wählt über ?unternehmen= bzw. gruppe_id, ohne = Standard = HT; sonst das eigene Unternehmen, ändern nur sein Verwalter). Karte „Handels-Würfel"
    unter den Einstellungen jedes Planers (prophos.html Sektion HANDELS-WÜRFEL)."""
    if request.method == "OPTIONS":
        return "", 200
    if request.method == "POST":
        _gs = _planer_schreib_gate()              # PLANER-RECHTE HT (30.10.2026)
        if _gs is not None:
            return _gs
    admin, uid, _lese, _schreib, err = _fcp_login()
    if err:
        return err
    gid, darf = _fd_unternehmen(admin, uid)
    if not admin and not gid:
        darf = False                              # HT-ID ohne Admin: nur ansehen (Standard ändert nur ein HT-Admin)
    name, bekannt = None, None
    if gid:
        try:
            _g = next((g for g in ap_planer_gruppen() if str(g.get("gruppe_id")) == str(gid)), None)
            name, bekannt = (_g or {}).get("name"), _g is not None
        except Exception:
            name, bekannt = None, None
    def antwort():
        werte = tw_werte(frisch=True)
        return {"ok": True, "werte": {p: werte.get((p, str(gid or ""))) for p in TW_EINST}, "standard_pct": TW_STANDARD_PCT,
                "unternehmen": ({"gruppe_id": str(gid), "name": name} if gid else None), "darf": bool(darf), "tabelle": bool(_tw.get("tabelle", True)),
                "planer_namen": TW_PLANER_NAME, **({"fehler": _tw["fehler"]} if _tw.get("fehler") else {})}   # Prüfer K1: Lesefehler sichtbar statt „100 %"
    if request.method == "GET":
        return jsonify(antwort())
    if not darf:
        return jsonify({"ok": False, "msg": "nur ansehen — ändern darf der Admin (Standard) bzw. der Verwalter des Unternehmens"}), 403
    if gid and bekannt is False:
        return jsonify({"ok": False, "msg": "Unternehmen unbekannt (keine Planer-Gruppe mit dieser gruppe_id)"}), 400   # Prüfer K3
    if gid and bekannt is None:
        return jsonify({"ok": False, "msg": "Unternehmen gerade nicht prüfbar — gleich noch einmal"}), 502
    body = request.get_json(silent=True) or {}
    planer = str(body.get("planer") or "")
    if planer not in TW_EINST:
        return jsonify({"ok": False, "msg": f"planer = {' | '.join(TW_EINST)}"}), 400
    roh = body.get("pct")
    pct = None if roh in (None, "") else _wd_num(roh)
    if roh not in (None, "") and (pct is None or isinstance(roh, bool) or not 0 <= pct <= 100):
        return jsonify({"ok": False, "msg": "pct = 0 bis 100 (leer = 100 %)"}), 400
    try:
        if pct is None:
            _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/planer_handel_wuerfel", params={"planer": f"eq.{planer}", "gruppe": f"eq.{str(gid or '')}"},
                        headers=_sb_headers("return=minimal"), timeout=12).raise_for_status()
        else:
            sb_upsert("planer_handel_wuerfel", {"planer": planer, "gruppe": str(gid or ""), "pct": round(float(pct), 2),
                                                "updated_at": datetime.now(timezone.utc).isoformat(), "updated_von": str(uid) if uid else None})
    except Exception as e:
        _r = getattr(e, "response", None)
        _txt = str(getattr(_r, "text", "") or "")
        hinweis = (" — sql/2026-11-12_tw3_firmen_wuerfel.sql eingespielt?" if planer == TW_FIRMA and ("planer_check" in _txt or "23514" in _txt)   # TW3 (Prüfer KANN 2)
                   else " — sql/2026-11-11_tageswuerfel_75.sql eingespielt?" if "planer_handel_wuerfel" in _txt else "")
        return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__}){hinweis}"}), 502
    print(f"[handels-wuerfel] {TW_PLANER_NAME[planer]} · {name or 'Standard (HT)'} → {'100 % (Zeile weg)' if pct is None else _tw_pct_txt(pct) + ' %'} "
          f"durch {str(uid)[:8]}", flush=True)
    return jsonify(antwort())


# ══ TW2 HAND ÜBERSTIMMT DEN PAUSE-TAG (Finn 11.11.2026 21:30 über den Master: „Wenn ein Konto per Würfel einen Pause-Tag hat, soll es überstimmt werden, wenn
# ich es von Hand reinnehme"). Marke je Konto × Plan-Tag in user_settings (keine neue Tabelle): user_id = Besitzer des Kontos, key „tw_hand:<YYYY-MM-DD>:<konto>",
# value {at, von}. Geschrieben NUR über POST /admin/handel-wuerfel/hand (Planer-Rechte + wd_hand_darf) — Knopf „heute rein" am Pause-Chip im Trade-Planer
# (Challenge, Funded CFD, Funded Futures) und „heute wieder rein" bei Winning Days. Gelesen in tw_pause_grund, also überall, wo der Würfel greift (5 Planer,
# Nachplan-Filter, WD-POST); der WD-Rückfall am PC-Tab liest dieselbe Zeile selbst (hwWdPause, eigene user_settings). Nachtlauf/Takt würfeln weiter wie bisher —
# nur dieses Konto an diesem Tag ist ausgenommen; der nächste Tag hat einen anderen Schlüssel = neu gewürfelt. Lesefehler → keine Marke (Pause bleibt, wie TW1). ══
TW_HAND_PREFIX = "tw_hand:"
TW_HAND_LIKE = "tw\\_hand:"      # für LIKE: „_“ ist sonst ein Platzhalter (Prüfer TW2 KANN 8)
TW_HAND_CACHE_S = 20
TW_HAND_TAGE_ALT = 7          # Marken älter als 7 Tage räumt das Schreiben mit weg
_tw_hand = {}                 # tag → (bis, set(konto_id))
_tw_hand_lock = threading.Lock()


def tw_hand_key(tag, konto_id):
    """REIN RECHNEND (testbar): Schlüssel der Marke je Konto × Tag."""
    return f"{TW_HAND_PREFIX}{str(tag)[:10]}:{konto_id}"


def tw_hand_aus_zeilen(rows, tag):
    """REIN RECHNEND (testbar): user_settings-Zeilen (key) → Menge der Konto-IDs mit Marke für genau diesen Tag."""
    vor = f"{TW_HAND_PREFIX}{str(tag)[:10]}:"
    return {str(r.get("key"))[len(vor):] for r in rows or [] if isinstance(r, dict) and str(r.get("key") or "").startswith(vor) and len(str(r.get("key"))) > len(vor)}


def tw_hand_tag_ok(tag, heute):
    """REIN RECHNEND (testbar): Plan-Tag für eine Marke erlaubt? Format YYYY-MM-DD, gestern bis übermorgen (Dubai) — der Funded-Planer plant auf Wunsch den
    nächsten Handelstag, ein CME-Tag kann einen Tag neben dem Dubai-Tag liegen."""
    try:
        t = datetime.strptime(str(tag or "")[:10], "%Y-%m-%d").date()
        h = datetime.strptime(str(heute)[:10], "%Y-%m-%d").date()
    except ValueError:
        return False
    return len(str(tag)) == 10 and -1 <= (t - h).days <= 2


def tw_hand_konten(tag, frisch=False):
    """Konto-IDs, die am Plan-Tag `tag` von Hand reingenommen wurden (TW2). 20 s gemerkt je Tag; POST /admin/handel-wuerfel/hand leert den Merker.
    Fehler → leere Menge (der Würfel gilt wie bisher), höchstens einmal je Minute geloggt."""
    t = str(tag or "")[:10]
    if not t:
        return set()
    jetzt = time.time()
    with _tw_hand_lock:
        z = _tw_hand.get(t)
        if not frisch and z and z[0] > jetzt:
            return z[1]
    try:
        rows = _sb_all("user_settings", {"select": "key", "key": f"like.{TW_HAND_LIKE}{t}:*"}) or []
        menge = tw_hand_aus_zeilen(rows, t)
    except Exception as e:
        with _tw_hand_lock:
            z = _tw_hand.get(t)
            if not z or jetzt - z[0] > 60:
                print(f"[handels-wuerfel] ⚠️ Hand-Marken {t} nicht lesbar ({type(e).__name__}) — Würfel gilt", flush=True)
            _tw_hand[t] = (jetzt + 15, set())
        return set()
    with _tw_hand_lock:
        for k in [k for k, v in _tw_hand.items() if v[0] < jetzt - 3600]:
            _tw_hand.pop(k, None)
        _tw_hand[t] = (jetzt + TW_HAND_CACHE_S, menge)
    return menge


def tw_pause_dazu(erg, basis):
    """REIN RECHNEND (testbar, Prüfer TW2 SOLLTE 4): der neueste Lauf ist ein Nachplan-Lauf (enthält nur seine nur_konten) → die „Pause-Tag“-Zeilen des
    Haupt-Laufs DESSELBEN Tags (basis) wieder dazu, damit der Knopf „heute rein“ am Chip bleibt. Nur Konten, die der neue Lauf nicht selbst führt."""
    if not isinstance(erg, dict) or not isinstance(basis, dict) or erg.get("quelle_lauf") != "nachplanen" or str(basis.get("tag") or "")[:10] != str(erg.get("tag") or "")[:10]:
        return erg
    drin = {str((z or {}).get("konto_id") or "") for f in ("geplant", "ausgelassen", "ziel") for z in (erg.get(f) or []) if isinstance(z, dict)}
    drin |= {str(k) for k in (erg.get("nur_konten") or [])}
    dazu = [z for z in (basis.get("ausgelassen") or []) if isinstance(z, dict) and str(z.get("grund") or "").startswith("Pause-Tag")
            and z.get("konto_id") and str(z.get("konto_id")) not in drin]
    return dict(erg, ausgelassen=list(erg.get("ausgelassen") or []) + dazu) if dazu else erg


@app.route("/admin/handel-wuerfel/hand", methods=["POST", "OPTIONS"])
def admin_handel_wuerfel_hand():
    """TW2: POST {konto_id, tag?: YYYY-MM-DD (Standard heute Dubai), rein?: true | false} → {ok, konto_id, tag, rein}. rein true = Marke setzen (Pause-Tag dieses
    Kontos an diesem Tag überstimmt), false = Marke weg (der Wurf gilt wieder). Rechte: Planer-Schreib-Gate (HT nur „Finn + Pascal“/„Pascal“) und wd_hand_darf
    (eigene Konten, Verwalter seine Gruppe, voller Admin HT). Plant selbst nichts — der nächste Nachplan-/Funded-Takt bzw. der WD-Weg legt den Plan an."""
    if request.method == "OPTIONS":
        return "", 200
    _gs = _planer_schreib_gate()
    if _gs is not None:
        return _gs
    me, err = _wd_login()
    if err:
        return err
    body = request.get_json(silent=True) or {}
    kid = str(body.get("konto_id") or "").strip()
    if not re.match(r"^[0-9a-f-]{36}$", kid):
        return jsonify({"ok": False, "msg": "konto_id fehlt"}), 400
    heute = datetime.now(_ap_tz("Asia/Dubai")).strftime("%Y-%m-%d")
    tag = str(body.get("tag") or heute).strip()[:10]
    if not tw_hand_tag_ok(tag, heute):
        return jsonify({"ok": False, "msg": "tag = YYYY-MM-DD, gestern bis übermorgen"}), 400
    rein = body.get("rein", True) is not False
    try:
        acc = (sb_select("accounts", {"select": "id,user_id,name", "id": f"eq.{kid}", "limit": "1"}) or [None])[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Konto nicht lesbar ({type(e).__name__})"}), 502
    if not acc or not acc.get("user_id"):
        return jsonify({"ok": False, "msg": "Konto nicht gefunden"}), 404
    try:
        recht = wd_hand_darf(me, acc.get("user_id"), getattr(g, "admin_sicht", None) if _admin_verwalter() else None, _admin_voll()[1] is None,
                             _admin_verwalter_gruppen_ids(admin_gruppen_daten()))
    except Exception:
        return jsonify({"ok": False, "msg": "Rechte nicht prüfbar — nichts geändert"}), 502
    if not recht:
        return jsonify({"ok": False, "msg": "Dieses Konto darfst du hier nicht reinnehmen (nur eigene, Admins ihre Gruppe)"}), 403
    key, jetzt = tw_hand_key(tag, kid), datetime.now(timezone.utc)
    try:
        if rein:
            _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/user_settings", params={"on_conflict": "user_id,key"},
                        json={"user_id": str(acc["user_id"]), "key": key, "value": {"at": jetzt.isoformat(), "von": str(me)}, "updated_at": jetzt.isoformat()},
                        headers=_sb_headers("resolution=merge-duplicates,return=minimal"), timeout=12).raise_for_status()
        else:
            _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/user_settings", params={"user_id": f"eq.{acc['user_id']}", "key": f"eq.{key}"},
                        headers=_sb_headers("return=minimal"), timeout=12).raise_for_status()
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__})"}), 502
    with _tw_hand_lock:
        _tw_hand.pop(tag, None)
    tw_hand_konten(tag, frisch=True)   # Prüfer KANN 7: ein Lesen, das vor dem Schreiben begann, legt sonst bis zu 20 s die alte Menge in den Merker
    try:   # alte Marken (> 7 Tage) mit wegräumen — Fehler egal
        alt = (jetzt - timedelta(days=TW_HAND_TAGE_ALT)).isoformat()
        _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/user_settings", params={"key": f"like.{TW_HAND_LIKE}*", "updated_at": f"lt.{alt}"},
                    headers=_sb_headers("return=minimal"), timeout=12)
    except Exception:
        pass
    print(f"[handels-wuerfel] ✋ {acc.get('name') or kid[:8]} am {tag} {'von Hand rein (Pause-Tag überstimmt)' if rein else 'Hand-Marke weg (Wurf gilt)'} "
          f"durch {str(me)[:8]}", flush=True)
    return jsonify({"ok": True, "konto_id": kid, "tag": tag, "rein": rein})


# ══ RV1 RANGE-WÜRFEL (11.11.2026, Finn 07:35 über den Master: „75 % der Trades bleiben gleich, und nur bei 25 % der Trades wird's angepasst … Stop Loss,
# Take Profit und Lotanzahl, alles drei … für alle drei wird einzeln gewürfelt“; davor: Faktor 10–100 % der aktuellen Spanne, „nie über dem jetzigen Max,
# sonst Daily Loss“, das Tagesziel zu verfehlen ist egal). Konstrukt: side-session-notes 2026-11-11_RV1_range_wuerfel_konstrukt.md.
# NUR Challenge-Planer CFD (Echo, ap_planen; der Gruppen-Planer gp_planen wie TW1 nicht). Je Haupt-Trade FEST gewürfelt: der Challenge-Planer gibt einem
# Konto höchstens EINEN Trade je Tag (08.10.2026 „maximal ein Trade pro Tag pro Account“, Trades pro Tag teilt ihn nur auf) → Schlüssel Konto × Tag.
# Nachtlauf, Nachplanen, Probelauf und der Folge-Teil des Tages (tt_folge_rechnen über kette.range) sehen dieselben Faktoren.
# Wirkt auf die Etappe und den letzten Trade (Rest bis Ziel; Master 11.11.2026: „auch klein erlaubt — Ziel nicht erreicht = morgen neu“, dann Stufe „Etappe …
# (statt letzter Trade)“); Klein-, Mini-, Gewinntag-Trade bleiben, wie sie sind. Punkte-Deckel: TP/SL nie weiter als der normale Trade bei maximaler Spanne
# (rv_punkte_deckel), nie enger als RV_MIN_PKT.
# Reihenfolge: ap_konto_rechnen würfelt und kappt (Boden, Tagesgrenze) wie immer, DANACH × Faktor — jeder Faktor ≤ 100 %, also nie über dem heutigen Wert.
# Weil die drei Faktoren unabhängig sind, ändern sich die Punkte (TP Pkt = TP $ ÷ (Lots × $/Pkt)): Lots ABgerundet aufs Raster der Phase (mindestens
# ein Schritt), TP- und SL-Punkte nie unter RV_MIN_PKT (wie WS3c „Invalid stops“) — sonst wird der Faktor so weit angehoben, höchstens auf 100 %.
# Der Fusion-Hedge (ap_echo_hedge_zeile → eh_hedge) rechnet aus master_contracts/master_risk des Plans, folgt also von selbst.
# Einstellung je Planer × Unternehmen (Tabelle planer_range_wuerfel, sql/2026-11-11_rv1_range_wuerfel.sql): pct = Anteil „klein“, von/bis = Faktor-Spanne.
# Keine Zeile / Tabelle fehlt / Lesefehler → 0 % = aus (wie vor RV1). Ein Unternehmen erbt den HT-Wert NICHT (wie TW1). ══
RV_PLANER = ("challenge_cfd",)
RV_PLANER_NAME = {"challenge_cfd": "Challenge-Planer CFD"}
RV_STANDARD = {"pct": 0.0, "von": 10.0, "bis": 100.0}
RV_MIN_PKT = 10.0       # Mindestabstand TP/SL in Punkten (= tt_param neben_min_pkt, WS3c FS2 „Invalid stops“)
RV_CACHE_S = 60
RV_ALT_S = 900          # wie TW_ALT_S: bei einem kurzen Lesefehler gilt der letzte gute Stand bis zu 15 min
RV_STUFE = "Range-Würfel"   # Stufen-Zusatz „· Range-Würfel TP x % · SL y % · Lots z %“ — Schlüssel-Anfang, nie umbenennen (Anzeige im Planer)
_rv = {"bis": 0.0, "werte": None, "tabelle": True, "fehler_at": 0.0, "gut": None, "gut_at": 0.0, "fehler": ""}
_rv_lock = threading.Lock()


def rv_wurf(planer, konto_id, tag, teil):
    """REIN RECHNEND (testbar): fester Wurf in [0, 1) je Teil ('klein' | 'tp' | 'sl' | 'lots') × Planer × Konto × Tag — eigenes Salz „rv1“, also
    unabhängig vom Handels-Würfel (tw1) und untereinander."""
    return fest_wurf(f"rv1|{teil}|{planer}|{konto_id}|{str(tag)[:10]}")


def rv_faktoren(planer, konto_id, tag, pct, von=None, bis=None):
    """REIN RECHNEND (testbar): None = normaler Trade, sonst {f_tp, f_sl, f_lots (0,1–1,0), pct, von, bis}. pct None/≤ 0 → nie, ≥ 100 → immer klein.
    von/bis in % (Standard 10–100), auf 1–100 begrenzt, vertauscht → sortiert. Jeder Faktor = von + (bis − von) × eigener Wurf."""
    p = _wd_num(pct)
    if p is None or p <= 0 or not konto_id:
        return None
    if p < 100 and rv_wurf(planer, konto_id, tag, "klein") * 100.0 >= p:
        return None
    lo = _wd_num(von)
    hi = _wd_num(bis)
    lo = min(100.0, max(1.0, RV_STANDARD["von"] if lo is None else lo))
    hi = min(100.0, max(1.0, RV_STANDARD["bis"] if hi is None else hi))
    lo, hi = min(lo, hi), max(lo, hi)
    fk = {f"f_{t}": round((lo + (hi - lo) * rv_wurf(planer, konto_id, tag, t)) / 100.0, 4) for t in ("tp", "sl", "lots")}
    return dict(fk, pct=round(p, 2), von=lo, bis=hi)


def rv_punkte_deckel(regel, phase, groesse, ppl):
    """REIN RECHNEND (testbar): (tp_max_pkt, sl_max_pkt) — so viele Punkte hätte der normale Trade dieses Kontos höchstens: oberes Ende der TP- bzw. SL-Spanne
    (tp_max geht vor) ÷ (kleinste Lots der Spanne, aufs Raster gerundet × $/Pkt). Je Kontogröße wie ap_konto_rechnen (je_groesse ohne, sonst skaliert × Größe/100k).
    Master 11.11.2026 (RV1, gegen TP bis 2.333 Pkt bei unabhängigen Faktoren): „TP- und SL-Punkte nie über die Punkte, die der normale Trade dieses Kontos bei
    maximaler Spanne hätte“. Nicht rechenbar → (None, None) = kein Deckel."""
    try:
        jg = (regel.get("je_groesse") or {}).get(str(int(groesse))) if (groesse and regel.get("je_groesse")) else None
        ph = ((jg.get("phasen") or {}) if jg else (regel.get("phasen") or {})).get(str(phase)) or {}
        f = 1.0 if jg else (float(groesse) / 100000.0 if regel.get("skaliert") else 1.0)
        lots = _ap_runden(_ap_spanne(ph.get("menge"), 0.0, f, gewichte=ph.get("menge_gewichte")), ph.get("menge_schritt") or 1)
        pv = float(ppl or 0)
        if not lots or float(lots) <= 0 or pv <= 0:
            return None, None
        tp_hi = float(ph["tp_max"]) * f if ph.get("tp_max") else (float(ph["tp"][1]) * f if ph.get("tp") else None)
        sl_hi = float(ph["sl"][1]) * f if ph.get("sl") else None
        nenner = float(lots) * pv
        return (round(tp_hi / nenner, 2) if tp_hi else None), (round(sl_hi / nenner, 2) if sl_hi else None)
    except (KeyError, TypeError, ValueError, IndexError, AttributeError):
        return None, None


RV_STATT_FINAL = "Ziel erst später"   # Zusatz eines klein gewürfelten letzten Trades, dessen TP das Ziel nicht mehr sicher erreicht
RV_FINAL_RE = re.compile(r"^letzter Trade \((?:Rest bis Ziel|auf Tageshöchstwert gedeckelt)\)")


def rv_anwenden(w, fk, schritt, ppl, min_pkt=RV_MIN_PKT):
    """REIN RECHNEND (testbar): Plan-Werte w aus ap_konto_rechnen × Range-Faktoren fk → w2 (Kopie) mit range-Beleg, oder w unverändert (kein fk, nicht Etappe/
    letzter Trade, CFD ohne SL/Punktwert). Lots = Lots × f_lots ABgerundet auf schritt (Raster der Phase), mindestens ein Schritt, höchstens die alten Lots.
    TP/SL = Wert × f, bei den neuen Lots aber nie enger als min_pkt und nie weiter als fk tp_max_pkt / sl_max_pkt (rv_punkte_deckel) — der Faktor wird auf die
    Grenze geklemmt, nie über den alten Wert. Stand der SL „hinter dem Boden“ (Stufe) und liegt jetzt davor, fällt der Zusatz weg — sonst läse echoV2Final
    den SL-Treffer als Blow.
    LETZTER TRADE (Master 11.11.2026: „letzter Trade (Ziel-Rest) auch klein erlaubt — Ziel nicht erreicht = morgen neu“): liegt sein TP danach unter dem Rest
    bis Ziel + Puffer der neuen Lots, ist er kein finaler Trade mehr → Stufe „Etappe … (Ziel erst später)“. Sonst hielten ihn prophos_plan_final_text / ap_plan_final_text
    („Auto-Planer · letzter Trade“ = final), der Schritt „Finale“ und Trades pro Tag (ein Trade) weiter für den Pass-Trade. Klein-, Mini-, Gewinntag-Trade bleiben."""
    st0 = str((w or {}).get("stufe") or "")
    final = bool(RV_FINAL_RE.match(st0))
    if not w or not fk or not (st0.startswith("Etappe") or final):
        return w
    try:
        m0, tp0, sl0, pv = float(w["menge"]), float(w["tp"]), float(w.get("sl") or 0), float(ppl or 0)
        fl, ft, fs = float(fk["f_lots"]), float(fk["f_tp"]), float(fk["f_sl"])
    except (KeyError, TypeError, ValueError):
        return w
    if m0 <= 0 or tp0 <= 0 or sl0 <= 0 or pv <= 0:
        return w
    s = float(schritt or 1)
    m = min(round(max(1, int(m0 * min(1.0, max(0.0, fl)) / s + 1e-9)) * s, 4), m0)
    m = int(round(m)) if s >= 1 else m

    def skal(wert, f, max_pkt):
        """→ (Wert $, 'min'|'max'|None): Wert × f, auf [min_pkt, max_pkt] Punkte bei den neuen Lots geklemmt, nie über wert."""
        je_pkt = float(m) * pv
        roh = wert * min(1.0, max(0.0, f))
        try:
            hoch = float(max_pkt) * je_pkt if max_pkt else None
        except (TypeError, ValueError):
            hoch = None
        tief = min_pkt * je_pkt
        if hoch is not None and roh > hoch + 1e-9 and hoch + 1e-9 >= tief:   # Deckel unter dem Mindestabstand → der Mindestabstand gewinnt (Prüfer RV1b)
            return int(min(wert, hoch // 1)), "max"                     # abrunden: nie über den Deckel
        if hoch is not None and hoch + 1e-9 < tief:
            # RV1d (Prüfer-SOLLTE zu 6bc12ab7, Master 11.11.2026): Deckel UNTER dem Mindestabstand — vorher fiel roh in den zweiten Zweig und kam UNgedeckelt
            # zurück (z. B. Faktor 1,0 → voller alter TP bei Deckel 8 Pkt). Jetzt genau der Mindestabstand (min_pkt bei den neuen Lots), nie über den alten Wert
            return int(min(wert, -((-(tief - 1e-9)) // 1))), "min"
        if roh + 1e-9 >= tief and round(roh) + 1e-9 >= tief:   # auch nach dem Runden nicht enger als min_pkt (Prüfer RV1)
            return int(round(roh)), None
        return int(min(wert, -((-(tief - 1e-9)) // 1))), "min"         # aufrunden ohne math (nicht importiert)

    tp, tp_kl = skal(tp0, ft, fk.get("tp_max_pkt"))
    sl, sl_kl = skal(sl0, fs, fk.get("sl_max_pkt"))
    stufe = st0
    hb = f", SL hinter den Boden (+{AP_SL_HINTER_BODEN} $)"
    if hb in stufe and sl < sl0 - AP_SL_HINTER_BODEN:   # genau auf dem Boden bleibt „hinter den Boden“ (Blow-Abgleich am Fill, Prüfer RV1)
        stufe = stufe.replace(hb, "")
    rest = _wd_num(w.get("rest"))
    # Prüfer RV1: final bleibt er nur mit dem Puffer der NEUEN Lots über dem Rest (wie ap_konto_rechnen AP_PUFFER_PKT × Lots × $/Pkt ÷ 3) — TP 3.007 bei Rest
    # 3.000 hätte sonst als Pass-Trade gegolten, ohne Platz für Spread/Schlupf
    puffer_neu = round(float(globals().get("AP_PUFFER_PKT", 4.5)) * float(m) * pv / 3)   # gerundet wie dort — unveränderte Lots + TP = alter letzter Trade
    statt = final and (rest is None or tp < rest + puffer_neu)
    if statt:
        stufe = RV_FINAL_RE.sub("Etappe", stufe, count=1)
    pz = lambda x: f"{round(x * 100):d}"   # noqa: E731
    # Zusatz bewusst OHNE die Wörter „letzter Trade“: TT_EIN_TRADE_STUFE sucht sie unverankert und machte den Tag sonst wieder zum Ein-Trade-Tag (Prüfer RV1)
    stufe += f" · {RV_STUFE} TP {pz(tp / tp0)} % · SL {pz(sl / sl0)} % · Lots {pz(float(m) / m0)} %" + (f" ({RV_STATT_FINAL})" if statt else "")
    beleg = {"f_tp": ft, "f_sl": fs, "f_lots": fl, "pct": fk.get("pct"), "von": fk.get("von"), "bis": fk.get("bis"),
             "tp_max_pkt": fk.get("tp_max_pkt"), "sl_max_pkt": fk.get("sl_max_pkt"),
             "tp_geklemmt": tp_kl, "sl_geklemmt": sl_kl, "statt_letzter": statt, "normal": {"menge": w["menge"], "tp": w["tp"], "sl": w.get("sl")},
             "tp_pkt": round(tp / (float(m) * pv), 1), "sl_pkt": round(sl / (float(m) * pv), 1)}
    w2 = dict(w, menge=m, tp=tp, sl=sl, stufe=stufe, range=beleg)
    if w.get("risiko") is not None:
        w2["risiko"] = sl            # CFD: risiko = SL (ap_konto_rechnen) — der Hedge (slave_risk) folgt dem neuen SL
    return w2


RV_TP_FREI_SCHRITTE = 50   # RV1d: höchstens ±50 $ vom skalierten TP weg, um einen TP-Gleichstand in der Tranche zu lösen


def rv_tp_frei(w, belegt, ppl, min_pkt=RV_MIN_PKT):
    """REIN RECHNEND (testbar, RV1d Prüfer-SOLLTE zu 6bc12ab7, Master 11.11.2026): „keine zwei gleichen TP je ID × Firma“ (Planer, Finn 09.10.2026) prüft den
    TP VOR dem Range-Würfel — der skalierte TP (rv_anwenden) konnte danach wieder auf einem TP der Tranche landen. Gleichstand → TP in 1-$-Schritten weg
    (erst −1, dann +1, −2, +2 … höchstens RV_TP_FREI_SCHRITTE), deterministisch (kein Zufallszug, der Lauf bleibt sonst bitgleich), innerhalb der Grenzen von
    rv_anwenden: nicht enger als min_pkt bei den neuen Lots, nicht über den normalen TP und den Punkte-Deckel (tp_max_pkt); ein klein gewürfelter letzter
    Trade („Ziel erst später“) nur nach unten. Gekappte TP (letzter Trade / Rest bis Ziel / Tage sammeln) bleiben wie in der Planer-Schleife. Kein Beleg,
    kein Gleichstand oder kein freier Wert → w unverändert."""
    if not w or not isinstance(w.get("range"), dict) or w.get("tp") not in (belegt or ()):
        return w
    if re.search(r"letzter Trade|Rest bis Ziel|Tage sammeln", str(w.get("stufe") or "")):
        return w
    rb = w["range"]
    try:
        tp, je_pkt, tp0 = int(w["tp"]), float(w["menge"]) * float(ppl or 0), float((rb.get("normal") or {})["tp"])
    except (KeyError, TypeError, ValueError):
        return w
    if je_pkt <= 0 or tp0 <= 0:
        return w
    tief = -((-(float(min_pkt) * je_pkt - 1e-9)) // 1)
    hoch = tp0
    try:
        if rb.get("tp_max_pkt"):
            hoch = min(hoch, float(rb["tp_max_pkt"]) * je_pkt // 1)
    except (TypeError, ValueError):
        pass
    if hoch < tief:
        hoch = tief                  # Deckel unter dem Mindestabstand: der Mindestabstand gilt (wie skal), nur nach unten frei
    hoch = min(hoch, tp0)            # Prüfer RV1d (KANN): nie über den Normal-TP — Normal-TP schon unter min_pkt → kein freier Wert, w bleibt
    hoch = min(hoch, tp) if rb.get("statt_letzter") else hoch
    for d in range(1, RV_TP_FREI_SCHRITTE + 1):
        for c in (tp - d, tp + d):
            if tief - 1e-9 <= c <= hoch + 1e-9 and c not in belegt:
                rb2 = dict(rb, tp_pkt=round(c / je_pkt, 1), tp_gleichstand=tp)
                stufe = re.sub(re.escape(RV_STUFE) + r" TP \d+ %", f"{RV_STUFE} TP {round(c / tp0 * 100):d} %", str(w.get("stufe") or ""), count=1)
                return dict(w, tp=int(c), stufe=stufe, range=rb2)
    return w


def rv_werte(frisch=False):
    """{(planer, gruppe): {pct, von, bis}} aus planer_range_wuerfel, 60 s gemerkt. Tabelle fehlt → {} (= aus). Lesefehler → letzter guter Stand ≤ RV_ALT_S,
    sonst {} (aus — lieber normale Trades als ein ungewollter Range-Würfel). Höchstens stündlich geloggt."""
    jetzt = time.time()
    with _rv_lock:
        if not frisch and _rv["werte"] is not None and _rv["bis"] > jetzt:
            return _rv["werte"]
    try:
        rows = sb_select("planer_range_wuerfel", {"select": "planer,gruppe,pct,von,bis"}) or []
        werte = {(str(r.get("planer")), str(r.get("gruppe") or "")): {"pct": _wd_num(r.get("pct")), "von": _wd_num(r.get("von")), "bis": _wd_num(r.get("bis"))}
                 for r in rows if r.get("planer") in RV_PLANER}
        with _rv_lock:
            _rv.update(bis=jetzt + RV_CACHE_S, werte=werte, tabelle=True, gut=werte, gut_at=jetzt, fehler="")
        return werte
    except Exception as e:
        _r = getattr(e, "response", None)
        fehlt = getattr(_r, "status_code", None) in (400, 404) and "planer_range_wuerfel" in str(getattr(_r, "text", "") or "")
        with _rv_lock:
            alt = (not fehlt) and _rv.get("gut") is not None and jetzt - (_rv.get("gut_at") or 0) <= RV_ALT_S
            werte = _rv["gut"] if alt else {}
            _rv.update(bis=jetzt + (RV_CACHE_S if fehlt else 15), werte=werte, tabelle=not fehlt,
                       fehler="" if fehlt else f"nicht lesbar ({type(e).__name__}){' — letzter Stand gilt' if alt else ''}")
        if jetzt - _rv["fehler_at"] > 3600:
            _rv["fehler_at"] = jetzt
            print(f"[range-wuerfel] {'Tabelle fehlt (sql/2026-11-11_rv1_range_wuerfel.sql) — aus' if fehlt else '⚠️ nicht lesbar: ' + type(e).__name__ + (' — letzter Stand gilt' if alt else ' — aus')}", flush=True)
        return werte


def rv_einstellung(planer, uid, werte=None, ktx=None):
    """{pct, von, bis} für das Unternehmen der ID (HT/ohne Unternehmen → Standard-Zeile '', Mitglied → dessen Zeile) oder None (= aus). Kontext nicht sicher
    lesbar → None (lieber normale Trades als eine fremde Einstellung)."""
    w = rv_werte() if werte is None else werte
    if not w:
        return None
    k = ktx if ktx is not None else ap_unt_kontext()
    if not k.get("ok"):
        return None
    gid = (k.get("gid_von") or {}).get(str(uid or ""))
    return w.get((str(planer), str(gid or "")))


def rv_planer_haken(w, a, regel, tag, ppl, werte, ktx):
    """ap_planen: Plan-Werte w eines Kontos a → w (unverändert) oder w × Range-Faktoren. Nur Echo-CFD-Challenges (Route mt5v2/mt5, Phase 1/2), nur Etappe.
    Jeder Fehler → w unverändert (normaler Trade)."""
    try:
        if not w or not werte or ((regel or {}).get("route") or "mt5v2") not in AP_CFD_ROUTEN or str((a or {}).get("account_type") or "") not in ("phase1", "phase2"):
            return w
        e = rv_einstellung("challenge_cfd", (a or {}).get("user_id"), werte, ktx)
        fk = rv_faktoren("challenge_cfd", str((a or {}).get("id") or ""), tag, (e or {}).get("pct"), (e or {}).get("von"), (e or {}).get("bis"))
        if not fk:
            return w
        # Raster genau wie ap_konto_rechnen: Phase der Kontogröße (je_groesse), sonst die Firmen-Phase; ohne menge_schritt 1 (Prüfer RV1)
        jg = (regel.get("je_groesse") or {}).get(str(int(w.get("groesse") or 0))) if regel.get("je_groesse") else None
        schritt = (((jg.get("phasen") if jg else regel.get("phasen")) or {}).get(str(a.get("account_type"))) or {}).get("menge_schritt") or 1
        tp_max_pkt, sl_max_pkt = rv_punkte_deckel(regel, a.get("account_type"), w.get("groesse"), ppl)
        return rv_anwenden(w, dict(fk, tp_max_pkt=tp_max_pkt, sl_max_pkt=sl_max_pkt), schritt, ppl)   # Deckel reist im Beleg (kette.range) zum Folge-Haupt
    except Exception as e:
        print(f"[range-wuerfel] ⚠️ {str((a or {}).get('id'))[:8]}: {type(e).__name__}: {e} — normaler Trade", flush=True)
        return w


@app.route("/admin/range-wuerfel", methods=["GET", "POST", "OPTIONS"])
def admin_range_wuerfel():
    """RV1: GET [?unternehmen=gid] → {ok, werte: {planer: {pct, von, bis}|None}, standard, unternehmen, darf, tabelle}; POST {planer, pct: 0–100 | None (= Zeile
    weg = aus), von, bis (1–100), gruppe_id?} → {ok, werte}. Recht und Unternehmen wie /admin/handel-wuerfel. Karte „Range-Würfel“ unter dem Handels-Würfel
    des Challenge-Planers CFD (prophos.html Sektion RANGE-WÜRFEL)."""
    if request.method == "OPTIONS":
        return "", 200
    if request.method == "POST":
        _gs = _planer_schreib_gate()
        if _gs is not None:
            return _gs
    admin, uid, _lese, _schreib, err = _fcp_login()
    if err:
        return err
    gid, darf = _fd_unternehmen(admin, uid)
    if not admin and not gid:
        darf = False
    name, bekannt = None, None
    if gid:
        try:
            _g = next((g for g in ap_planer_gruppen() if str(g.get("gruppe_id")) == str(gid)), None)
            name, bekannt = (_g or {}).get("name"), _g is not None
        except Exception:
            name, bekannt = None, None

    def antwort():
        werte = rv_werte(frisch=True)
        return {"ok": True, "werte": {p: werte.get((p, str(gid or ""))) for p in RV_PLANER}, "standard": RV_STANDARD,
                "unternehmen": ({"gruppe_id": str(gid), "name": name} if gid else None), "darf": bool(darf), "tabelle": bool(_rv.get("tabelle", True)),
                "planer_namen": RV_PLANER_NAME, "min_pkt": RV_MIN_PKT, **({"fehler": _rv["fehler"]} if _rv.get("fehler") else {})}
    if request.method == "GET":
        return jsonify(antwort())
    if not darf:
        return jsonify({"ok": False, "msg": "nur ansehen — ändern darf der Admin (Standard) bzw. der Verwalter des Unternehmens"}), 403
    if gid and bekannt is False:
        return jsonify({"ok": False, "msg": "Unternehmen unbekannt (keine Planer-Gruppe mit dieser gruppe_id)"}), 400
    if gid and bekannt is None:
        return jsonify({"ok": False, "msg": "Unternehmen gerade nicht prüfbar — gleich noch einmal"}), 502
    body = request.get_json(silent=True) or {}
    planer = str(body.get("planer") or "")
    if planer not in RV_PLANER:
        return jsonify({"ok": False, "msg": f"planer = {' | '.join(RV_PLANER)}"}), 400
    roh = body.get("pct")
    pct = None if roh in (None, "") else _wd_num(roh)
    if roh not in (None, "") and (pct is None or isinstance(roh, bool) or not 0 <= pct <= 100):
        return jsonify({"ok": False, "msg": "Anteil = 0 bis 100 (leer = aus)"}), 400
    von = _wd_num(body.get("von")) if body.get("von") not in (None, "") else RV_STANDARD["von"]
    bis = _wd_num(body.get("bis")) if body.get("bis") not in (None, "") else RV_STANDARD["bis"]
    if von is None or bis is None or isinstance(body.get("von"), bool) or isinstance(body.get("bis"), bool) or not (1 <= von <= bis <= 100):
        return jsonify({"ok": False, "msg": "Faktor-Spanne: 1 ≤ von ≤ bis ≤ 100 %"}), 400
    try:
        if pct is None:
            _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/planer_range_wuerfel", params={"planer": f"eq.{planer}", "gruppe": f"eq.{str(gid or '')}"},
                        headers=_sb_headers("return=minimal"), timeout=12).raise_for_status()
        else:
            sb_upsert("planer_range_wuerfel", {"planer": planer, "gruppe": str(gid or ""), "pct": round(float(pct), 2), "von": round(float(von), 2),
                                               "bis": round(float(bis), 2), "updated_at": datetime.now(timezone.utc).isoformat(),
                                               "updated_von": str(uid) if uid else None})
    except Exception as e:
        _r = getattr(e, "response", None)
        hinweis = " — sql/2026-11-11_rv1_range_wuerfel.sql eingespielt?" if "planer_range_wuerfel" in str(getattr(_r, "text", "") or "") else ""
        return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__}){hinweis}"}), 502
    print(f"[range-wuerfel] {RV_PLANER_NAME[planer]} · {name or 'Standard (HT)'} → "
          f"{'aus (Zeile weg)' if pct is None else _tw_pct_txt(pct) + ' % klein, Faktor ' + _tw_pct_txt(von) + '–' + _tw_pct_txt(bis) + ' %'} durch {str(uid)[:8]}", flush=True)
    return jsonify(antwort())


AP_GRUND_TAGESDECKEL = "Tagesdeckel der Firma — höchstens {n} Konten je ID und Tag, dieses Konto kommt an einem anderen Tag dran"


def ap_tagesdeckel(firmen, kandidaten, plaene, tag, tz, rnd):
    """REIN RECHNEND (testbar): Tagesdeckel je Firma (19.10.2026, Finn: „Es wurden richtig viele Accounts aufgeladen … vor allem bei
    Apex nicht alle Accounts in einem Tag machen, weil da etwas schiefgeht … 2 bis 3 Trades pro ID bei Apex"). regel.max_konten_tag =
    [von, bis] (oder eine Zahl): je ID × Firma bekommen an einem Tag höchstens so viele Konten einen Plan. Pläne, die den Tag schon
    belegen (laufend, heute geplant, heute beendet — _ap_plan_am_tag), zählen mit, damit Nachplan-Takt und Hand-Lauf den Deckel nicht
    aufstocken. Zahl und Konto-Auswahl sind seit AP1 (11.11.2026) FEST je ID × Firma × Tag (fest_wurf, ohne Speicher) — rnd wird nicht mehr benutzt
    (Signatur bleibt). Der Rest steht sichtbar in ausgelassen[]. Reihenfolge der behaltenen Konten bleibt die der Kandidatenliste. Ohne max_konten_tag
    (CFD-Firmen, Tradeify …): unverändert. → (kandidaten behalten, ausgelassen[])
    AP1 (Master 11.11.2026, Befund AD2; DB 14 Tage: ID-Tage mit 3 Apex-Konten 20× gegen 2 Konten 12×, 9× kam das dritte erst mit einer späteren Anlage):
    n wurde je Lauf neu gezogen (Seed aus SystemRandom), „Tagesdeckel“ ist kein fester Nachplan-Grund — ein späterer 5-min-Takt zog irgendwann 3 und
    legte ein drittes Konto an, aus „2 bis 3“ wurde praktisch immer 3. Jetzt ergeben Nachtlauf, Nachplanen, Knopf und Probelauf dieselbe Zahl und
    dieselben Konten."""
    # Schlüssel = ID × Regel (nicht Firmen-Schreibweise): „Apex" und „Apex Trader" einer ID teilen sich EINEN Deckel
    je, behalten_ids, raus = {}, set(), []
    for k in kandidaten:
        regel = ap_regel_finden(firmen, k["a"].get("firm")) or {}
        namen = tuple(sorted(_ap_norm(x) for x in (regel.get("namen") or [k["a"].get("firm")])))
        je.setdefault((str(k["a"].get("user_id")), namen), (regel, []))[1].append(k)
    for (uid, namen), (regel, liste) in je.items():
        sp = regel.get("max_konten_tag")
        if sp in (None, "", 0, False):
            behalten_ids.update(id(k) for k in liste)
            continue
        try:
            lo, hi = (int(sp[0]), int(sp[-1])) if isinstance(sp, (list, tuple)) else (int(sp), int(sp))
        except (TypeError, ValueError, IndexError):
            behalten_ids.update(id(k) for k in liste)
            continue
        if hi < lo:
            lo, hi = hi, lo
        n = min(hi, lo + int(fest_wurf(f"deckel|{uid}|{'+'.join(namen)}|{str(tag)[:10]}") * (hi - lo + 1))) if hi > lo else lo   # AP1: fest je ID × Firma × Tag
        belegt = sum(1 for p in plaene if str(p.get("user_id")) == uid and _ap_norm(p.get("master_firm")) in namen
                     and _ap_plan_am_tag(p, tag, tz))
        frei = max(0, n - belegt)
        misch = sorted(liste, key=lambda k: (fest_wurf(f"deckel|{k['a'].get('id')}|{str(tag)[:10]}"), str(k["a"].get("id"))))   # AP1: feste Reihenfolge je Tag
        behalten_ids.update(id(k) for k in misch[:frei])
        for k in misch[frei:]:
            raus.append(dict(k["zeile"], grund=AP_GRUND_TAGESDECKEL.format(n=n) + (f" ({belegt} heute schon belegt)" if belegt else "")))
    return [k for k in kandidaten if id(k) in behalten_ids], raus


def ap_nachplan_letzter(rows):
    """REIN RECHNEND: letzter Lauf aus auto_plan_lauf-Zeilen (tag,at,ergebnis; neueste zuerst) → ergebnis-Dict mit 'at' = Start des
    Laufs (steht im Ergebnis); fehlt es, die Zeit der Zeile (08.10.2026, für den Vergleich mit auto_plan_regeln.updated_at)."""
    erg = (rows[0].get("ergebnis") if rows else None) or {}
    if erg and isinstance(erg, dict) and not erg.get("at") and rows[0].get("at"):
        erg = dict(erg, at=rows[0].get("at"))
    return erg


AP_NACHPLAN_REST_RE = re.compile(r"nur noch (-?\d+) \$ bis zum Ziel")


def ap_nachplan_ziel_frei(letzter_erg, tag, schon=None):
    """REIN RECHNEND (testbar): Konto-IDs, deren „nur noch X $ bis zum Ziel"-Grund des letzten Laufs HEUTE einmal neu gerechnet wird — nur
    CFD-Phasen (typ phase1/phase2 in der Lauf-Zeile; ohne typ bleibt der Grund fest) mit Rest ≥ AP_REST_MIN_CFD. Anlass (Master 09.10.2026, Folge zu .1397): seit dem Klein-Trade wird aus so
    einem Rest ein Plan, der Grund stammte aber aus dem Lauf VOR dem Update und galt als fest → Chris/Moritz/Ina (Rest 36/56/62 $) wären
    erst morgen geplant worden. Unter AP_REST_MIN_CFD (seit 27.10.2026 1 $, vorher 10 $) bleibt er fest (Handarbeit), Futures unverändert. schon = heute bereits freigegebene IDs: jedes
    Konto nur EINMAL je Tag (kommt derselbe Grund wieder, z. B. „kein Punktwert", gilt er danach wieder als fest — kein 10-min-Kreisel)."""
    if not isinstance(letzter_erg, dict) or str(letzter_erg.get("tag") or "") != tag:
        return set()
    out = set()
    for z in letzter_erg.get("ausgelassen") or []:
        if not isinstance(z, dict) or str(z.get("typ") or "") not in ("phase1", "phase2") or not z.get("konto_id"):
            continue
        m = AP_NACHPLAN_REST_RE.search(str(z.get("grund") or ""))
        if m and int(m.group(1)) >= AP_REST_MIN_CFD and str(z.get("konto_id")) not in (schon or ()):
            out.add(str(z.get("konto_id")))
    return out


def ap_nachplan_neu_bis(zeiten):
    """REIN RECHNEND: (tz-Name, Minute des Tages) für die 16-Uhr-Regel neuer Konten — zeiten.neu_bis, sonst AP_NEU_BIS_STANDARD."""
    nb = (zeiten or {}).get("neu_bis")
    nb = nb if isinstance(nb, dict) else {}
