def fd_gruppen_schluessel(uid, daten):
    """REIN RECHNEND (testbar): Firmen-Abstand je Gruppe GENAU wie der DB-Trigger (prophos_gruppe_von, sql/2026-10-13_gruppen_planer.sql:
    kleinste gruppe_id aus id_gruppe_mitglied, ob mit Verwalter oder nicht) — sonst plant Python eine Zeit, die der Trigger beim Start
    verschiebt (Prüfung S4). Ohne Mitglieds-Zeile „ohne", ohne Gruppen-Daten ein Topf „ht" (wie vor dem 30.10.2026)."""
    if not daten:
        return "ht"
    g = sorted(str(m.get("gruppe_id")) for m in daten.get("mitglieder") or () if str(m.get("user_id")) == str(uid))
    return g[0] if g else "ohne"


def fd_plan_tag(jetzt, cme_fenster, ap_zeiten):
    """Planungstag der Funded-Planer (Apex/FTMO Futures fdp_planen, Funded CFD fcp_planen) → 'YYYY-MM-DD'. Vorfall 03.11.2026 (Finn ~02:30 Dubai: „heute ist der 3.
    schon … jetzt wurde quasi schon der nächste Tag geplant"): Nachtlauf 1105 um 21:30 UTC plante den 03.11., der Funded-Lauf 1119 um 22:11 UTC rechnete mit dem
    CME-Tag des Fensterbeginns (02:26 Dubai = noch 02.11.) und zählte die Trades vom 02.11. — „heute schon getradet" und Tagesdeckel je ID für Chris/Ina.
    Jetzt der spätere von CME-Tag des Fensters und dem Tag des Challenge-Nachtlaufs (ap_nacht_ziel, dieselbe Funktion wie der Nachtlauf): ab dessen Lauf-Zeitpunkt
    gilt der neue Tag. Die Tagesgrenze der Startzeiten (CME 03:00 Dubai im Winter, im_tag) bleibt. Lesefehler/Wochenende → CME-Tag wie bisher."""
    try:
        faellig, _n = ap_nacht_ziel(jetzt, ap_nacht_param(ap_zeiten))
        nacht = faellig[0].isoformat() if faellig else None
    except Exception as e:
        print(f"[funded-plan] ⚠️ Nachtlauf-Tag nicht rechenbar ({type(e).__name__}: {e}) — CME-Tag", flush=True)
        nacht = None
    tage = [t for t in (cme_fenster, nacht) if t]
    return max(tage) if tage else cme_fenster


def fd_fenster_basis(mitternacht, ab_min, von_min, plan_tag, tz):
    """REIN RECHNEND (testbar): Fenster-Basis zum Planungstag (Eingang 03.11.2026, Funded-CFD-Lauf 1124 um 02:26 Dubai: „kein freier Slot mehr im Fenster heute",
    das Fenster vom 02.11. war vorbei). Liegt der Planungstag (fd_plan_tag) in der Zone des Fensters noch in der Zukunft — z. B. Fenster in deutscher Zeit, Nachtlauf
    um 23:00 dt —, rechnen Startzeiten ab Mitternacht DIESES Tages und ab dem Fensterbeginn; sonst bleibt alles, wie es ist (Dubai: dort ist es schon der Tag)."""
    try:
        t = datetime.strptime(str(plan_tag)[:10], "%Y-%m-%d")
    except (TypeError, ValueError):
        return mitternacht, ab_min
    if mitternacht.date() < t.date():
        return datetime(t.year, t.month, t.day, tzinfo=tz), float(von_min)
    return mitternacht, ab_min


def fdp_je_groesse(regel, groesse):
    """Werte je Kontogröße aus der Firmen-Regel (ziel_gewinn, max_trade, kosten_eur, dd) oder None."""
    if not regel or not groesse:
        return None
    return (regel.get("je_groesse") or {}).get(str(int(groesse)))


def fdp_liq(groesse, dd, peak, balance, lock=100.0):
    """REIN RECHNEND (testbar): Liquidation des Funded-Kontos → (liq | None, text). Derselbe Konto-Boden wie Radar und Abhaken
    (liq_konto_boden, EOD-trailing): max(Größe, höchste belegte Balance) − DD, fest bei Größe + lock, sobald der Höchststand
    Größe + DD + lock erreicht. None = Balance liegt nicht über dem Boden (geblowt bzw. Datenzweifel)."""
    regel = {"maxdd_art": "eod_trailing", "maxdd_lock_ueber_groesse_usd": lock, "maxdd_usd": dd}
    boden, text, _dd, _art = liq_konto_boden(regel, {"max_drawdown": dd}, groesse, peak, balance)
    return boden, text


def fdp_stufe(stufen, balance):
    """REIN RECHNEND (testbar): (daily_loss, minis, nr) der Stufe nach dieser Balance (liq_stufe) — (None, None, None) ohne Stufen."""
    nr, st = liq_stufe(stufen, balance)
    if not st:
        return None, None, None
    return _wd_num(st.get("daily_loss_usd")), int(_wd_num(st.get("minis")) or 0) or None, nr


def fdp_tp(balance, start, ziel, max_trade, tol=FDP_BREAKEVEN_TOL_USD):
    """REIN RECHNEND (testbar): (tp | None, art). Mehr als FDP_BREAKEVEN_TOL_USD unter dem Start zurück auf Break-even ('break_even'), sonst
    min(max_trade, Ziel − Balance) ('normal'); Ziel erreicht → (None, 'ziel'). Anlass: Marc 99.988 $ hätte sonst TP 12,40 $ und Hedge 1,02 €."""
    if balance < start - tol:   # tol = konst.breakeven_tol (E2b-Nachtrag 05.11.2026), Rückfall FDP_BREAKEVEN_TOL_USD
        return round(start - balance, 2), "break_even"
    rest = ziel - balance
    if rest <= 0.005:
        return None, "ziel"
    return round(min(float(max_trade), rest), 2), "normal"


def fdp_sl(dll, balance, liq):
    """REIN RECHNEND (testbar): SL in $ = Daily Loss der Stufe, höchstens der Abstand zur Liquidation; ganze Dollar abgerundet."""
    if not dll or liq is None:
        return None
    sl = min(float(dll), balance - liq)
    return float(int(sl)) if sl > 0 else None


def fdp_kontrakte(verteilung, minis, rnd=None):
    """REIN RECHNEND (testbar): NQ-Kontrakte aus der Verteilung je Größe ({"2": 0.75, "3": 0.25}) — gewürfelt mit rnd, ohne rnd der
    wahrscheinlichste Wert (gleich wahrscheinlich: der kleinere); mindestens 1, höchstens die Minis der Stufe (Finn 27.10.2026)."""
    paare = sorted((int(k), float(w)) for k, w in (verteilung or {}).items() if _wd_num(w) and float(w) > 0 and int(k) > 0)
    if not paare:
        k = 1
    elif rnd is None:
        k = max(paare, key=lambda x: (x[1], -x[0]))[0]
    else:
        x, k = rnd.random() * sum(w for _k, w in paare), paare[-1][0]
        for kk, w in paare:
            if x < w:
                k = kk
                break
            x -= w
    return max(1, min(int(minis or k), k))


def fdp_hedge(offen, balance, liq, tp, sl, kt, ppl=FDP_NQ_PPL, sppl=FDP_SLAVE_PPL):
    """REIN RECHNEND (testbar): Fusion-Gegenhedge → dict | None. Verhältnis € je $ = offene Kosten ÷ (Balance − Liq); am Plan wie das
    Trade-Popup: Risiko Master = Balance − Liq, Risiko Slave = offene Kosten → Multiplikator = Lots ÷ Kontrakte (tpMultiplierAusRisiko),
    hedge_eur = Lots × 0,85 × TP-Punkte (tpWdHedgeEurAus). hedge_sl_eur/hedge_tp_eur = Hedge-Ergebnis am Master-SL/-TP."""
    dist = balance - liq if liq is not None else 0
    if not (offen and offen > 0 and dist > 0 and tp and tp > 0 and kt and kt > 0):
        return None
    v = offen / dist
    stop_pkt = dist / (ppl * kt)
    mult = offen / (sppl * stop_pkt) / kt
    lots = round(kt * mult, 2)
    if lots <= 0:
        return None
    return {"verhaeltnis": round(v, 5), "master_risk": round(dist, 2), "slave_risk": round(offen, 2), "multiplier": round(mult, 4),
            "hedge_faktor": round(mult, 3), "lots": lots, "hedge_eur": round(lots * sppl * (tp / (ppl * kt)), 2),
            "hedge_tp_eur": round(v * tp, 2), "hedge_sl_eur": round(v * (sl or 0), 2)}


def fdp_kosten_theorie(jg, start, balance, groesse, lock=100.0, max_schritte=60):
    """REIN RECHNEND (testbar; FH1 Variante B, Finn 10.11.2026): was es den Planer normalerweise kostet, das Konto vom Zyklus-Start bis zur Balance hochzupumpen.
    Start mit den Kontokosten (kosten_eur), Schritte wie fdp_tp (je höchstens max_trade, der letzte bis genau zur Balance), jeder Schritt gewinnt; der Fusion-Hedge
    verliert dabei offen ÷ (Balance − Liq) × TP (fdp_hedge: hedge_tp_eur). Die Liq zieht nach jedem Schritt EOD nach wie fdp_liq (Größe − DD bzw. Höchststand − DD,
    fest bei Größe + lock, sobald der Höchststand Größe + DD + lock erreicht) — das Nachziehen ändert den Abstand und damit den Satz des nächsten Schritts.
    → € (gerundet) | None (keine Daten: kosten_eur/dd/max_trade/Größe fehlen, Balance unter Start, Abstand ≤ 0)."""
    jg = jg or {}
    kosten, dd, mt = _wd_num(jg.get("kosten_eur")), _wd_num(jg.get("dd")), _wd_num(jg.get("max_trade"))
    g = float(groesse or 0)
    if not (kosten and kosten > 0 and dd and dd > 0 and mt and mt > 0 and g > 0) or balance is None or start is None:
        return None
    bal = peak = float(start)
    bis, offen = float(balance), float(kosten)
    if bis < bal - 0.005:
        return None
    for _ in range(max_schritte):
        if bal >= bis - 0.005:
            return round(offen, 2)
        liq, _txt = fdp_liq(g, dd, peak, bal, lock)
        if liq is None or bal - liq <= 0:
            return None
        tp = min(mt, bis - bal)
        offen += offen / (bal - liq) * tp
        bal += tp
        peak = max(peak, bal)
    return None


def fdp_offen(kosten, hedge_pls):
    """REIN RECHNEND (testbar): offene Kosten = Kontokosten − Summe der Hedge-Ergebnisse (Verlust negativ → erhöht, Gewinn senkt)."""
    return round(float(kosten or 0) - sum(float(x) for x in (hedge_pls or ()) if x is not None), 2)


def fdp_tage(plaene, ab=None):
    """REIN RECHNEND (testbar): Ergebnis je CME-Handelstag im Zyklus (beendete Trades, master_pl) → {tag: $}. Nur für die Anzeige
    „größter Tag x %" — keine Consistency-Wache (Finn 27.10.2026)."""
    out = {}
    for p in plaene or ():
        st = str(p.get("started_at") or "")
        pl = _wd_num(p.get("master_pl"))
        if not st or pl is None or p.get("status") != "completed" or (ab and st <= str(ab)):
            continue
        t = _cme_handelstag(st)
        if t:
            out[t] = round(out.get(t, 0.0) + pl, 2)
    return out


def fdp_zyklus(groesse, payouts, plaene):
    """REIN RECHNEND (testbar): aktueller Zyklus → {nr, ab, start}. Ohne Payout: Zyklus 1 ab Kontogröße. Mit Payout: ab dem jüngsten
    Payout, Start = Start-Balance des ersten Trades danach (None = noch keiner → der Aufrufer nimmt die aktuelle Balance)."""
    ps = sorted(str(p) for p in (payouts or ()) if p)
    if not ps:
        return {"nr": 1, "ab": None, "start": float(groesse)}
    ab = ps[-1]
    nach = sorted((p for p in plaene or () if str(p.get("started_at") or "") > ab and _wd_num(p.get("bal_start")) is not None),
                  key=lambda p: str(p.get("started_at")))
    return {"nr": len(ps) + 1, "ab": ab, "start": _wd_num(nach[0].get("bal_start")) if nach else None}


def fdp_vorschlag_neu(plan, r):
    """REIN RECHNEND (testbar): Felder, mit denen ein alter Break-even-Vorschlag nach der ±500-$-Regel neu gerechnet wird, sonst None. Nur unbestätigt, ohne Startzeit, nie gestartet; bestätigte Pläne fasst das nie an. r = fdp_konto_rechnen mit den Kontrakten des Plans.
    Stopp S9 02.11.2026: hand_werte_at reicht nicht, das Popup setzt es nicht. Darum muss der TP noch genau der Break-even dieser Balance sein, sonst hat jemand ihn geändert oder die Balance ist weiter. Würde r weniger Kontrakte
    nehmen (Minis der Stufe), bleibt der Plan auch: master_contracts wird hier nicht geschrieben, die Lots wären zu groß."""
    p, fp = plan or {}, (plan or {}).get("funded_plan")
    if (p.get("status") != "planned" or p.get("auto_bestaetigt_at") or p.get("start_um") or p.get("start_um_gestartet_at") or p.get("started_at") or p.get("hand_werte_at")
            or not isinstance(fp, dict) or fp.get("tp_art") != "break_even" or (r or {}).get("aktion") != "planen" or r.get("tp_art") != "normal"):
        return None
    tp, start, bal, kt = _wd_num(p.get("master_tp")), _wd_num(fp.get("start")), _wd_num(r.get("balance")), _wd_num(p.get("master_contracts"))
    if tp is None or start is None or bal is None or abs(tp - (start - bal)) >= 0.01 or kt is None or abs(kt - float(r.get("kontrakte") or 0)) > 1e-6:
        return None
    return {"master_tp": r["tp"], "master_sl": r["sl"], "master_risk": r["master_risk"], "slave_risk": r["slave_risk"], "multiplier": r["multiplier"], "hedge_faktor": r["hedge_faktor"], "hedge_eur": r["hedge_eur"]}


def fdp_vorschlag_basis_neu(plan, r, toleranz=1.0):
    """REIN RECHNEND (testbar; FH1b, Master 10.11.2026 — Finn wartete: Chris' Vorschlag von 01:31 stand nach FH1 weiter mit der alten Hedge-Basis 515 € / 2,79 Lot in
    „Zu bestätigen"): Hedge-Felder eines unbestätigten Vorschlags neu, wenn sich NUR die Hedge-Basis geändert hat (neue Regel wie FH1 B, neue Hedge-Ergebnisse).
    Guards wie fdp_vorschlag_neu (geplant, unbestätigt, ohne Startzeit/Claim, nie gestartet, keine Hand-Werte); TP, SL und Kontrakte des Plans = neue Rechnung
    (sonst hat jemand von Hand geändert oder die Balance ist weiter — dann nicht); die Basis am Plan (slave_risk) ist noch genau die vom Planer geschriebene
    (funded_plan.offen_eur — ein im Popup geänderter Hedge bleibt); neue Basis weicht ≥ toleranz € ab. → Felder | None. master_tp/sl/contracts bleiben."""
    p, fp = plan or {}, (plan or {}).get("funded_plan")
    if (p.get("status") != "planned" or p.get("auto_bestaetigt_at") or p.get("start_um") or p.get("start_um_gestartet_at") or p.get("started_at") or p.get("hand_werte_at")
            or not isinstance(fp, dict) or (r or {}).get("aktion") != "planen"):
        return None
    tp, sl, kt = _wd_num(p.get("master_tp")), _wd_num(p.get("master_sl")), _wd_num(p.get("master_contracts"))
    if tp is None or kt is None or abs(tp - float(r.get("tp") or 0)) >= 0.01 or abs(float(sl or 0) - float(r.get("sl") or 0)) >= 0.01 \
            or abs(kt - float(r.get("kontrakte") or 0)) > 1e-6:
        return None
    alt, gespeichert, neu = _wd_num(p.get("slave_risk")), _wd_num(fp.get("offen_eur")), _wd_num(r.get("slave_risk"))
    if alt is None or gespeichert is None or neu is None or abs(alt - gespeichert) >= 0.011 or abs(neu - alt) < toleranz:
        return None
    return {"master_risk": r["master_risk"], "slave_risk": r["slave_risk"], "multiplier": r["multiplier"], "hedge_faktor": r["hedge_faktor"], "hedge_eur": r["hedge_eur"]}


def fdp_notiz_basis(notes, r):
    """REIN RECHNEND (testbar): Ende der Planer-Notiz („· offene Kosten …“ / „· Konto im Plus …“ / „· Hedge-Basis …“) auf die neue Basis umschreiben, sonst None."""
    n = str(notes or "")
    if not re.search(r" · (offene Kosten |Konto im Plus |Hedge-Basis )", n):
        return None
    tail = (f"Hedge-Basis {_liq_de(r['offen_eur'])} € = Pump-Kosten bis Balance (B) · echt {_liq_de(r.get('offen_kosten_eur'))} €" if r.get("hedge_basis") == "pump_b" else
            f"Konto im Plus (offene Kosten {_liq_de(r.get('offen_kosten_eur'))} €) · Hedge-Basis {_liq_de(r['offen_eur'])} € = {r['hedge_quelle']}" if r.get("hedge_quelle") else
            f"offene Kosten {_liq_de(r['offen_eur'])} €")
    return re.sub(r" · (offene Kosten |Konto im Plus |Hedge-Basis ).*$", " · " + tail, n)


