def fdp_regeln_anzeige(reg, quelle="db"):
    """REIN RECHNEND (testbar): Einstellungen des Funded-Futures-Planers für den Reiter → dict. reg = Zeile funded_plan_regeln (None = Standard)."""
    r = reg or {"aktiv": False, "auto_bestaetigen": False, "firmen": FDP_FIRMEN_STANDARD, "zeiten": {}}
    firmen = []
    for f in r.get("firmen") or []:
        if not isinstance(f, dict):
            continue
        jg = f.get("je_groesse") if isinstance(f.get("je_groesse"), dict) else {}
        firmen.append({"name": f.get("name") or (f.get("namen") or ["?"])[0], "namen": list(f.get("namen") or []), "an": bool(f.get("an")),
                       "symbol": f.get("symbol"), "lock_usd": f.get("lock_usd"), "tp_modus": f.get("tp_modus") or "normal",
                       "consistency_pct": _wd_num(f.get("consistency_pct")),   # E2d: nur Anzeige (Kontoliste), der Planer prüft keine Consistency
                       "je_groesse": {str(k): dict(v) for k, v in jg.items() if isinstance(v, dict)}})
    return {"quelle": quelle if reg else "standard", "aktiv": bool(r.get("aktiv")), "auto_bestaetigen": r.get("auto_bestaetigen") is True,
            "updated_at": r.get("updated_at"), "zeiten": dict(FDP_ZEITEN_STANDARD, **(r.get("zeiten") or {})), "zeiten_db": dict(r.get("zeiten") or {}),
            "firmen": firmen, "fest": [{"key": k, "name": n, "wert": w, "einheit": e, "wo": wo, "grund": gr} for k, n, w, e, wo, gr in FDP_FEST], "fest_text": list(FDP_FEST_TEXT),
            # E2b-Nachtrag: Grenzen mit Rückfall (konst = gilt jetzt, konst_db = was in der Zeile steht, spalte = Spalte konst eingespielt) + eigenes Fenster
            "konst": fdp_konst(reg), "konst_db": dict((r.get("konst") or {}) if isinstance(r.get("konst"), dict) else {}), "konst_spalte": bool(reg) and "konst" in reg,
            "konst_info": [{"key": k, "name": t[0], "einheit": t[1], "text": t[2], "std": float(FDP_KONST[k][0]), "lo": FDP_KONST[k][1], "hi": FDP_KONST[k][2]} for k, t in FDP_KONST_TEXT.items()],
            "fenster_eigen": (r.get("zeiten") or {}).get("fenster_eigen") if fdp_fenster_eigen((r.get("zeiten") or {}).get("fenster_eigen")) else None}


def _fdp_zahl(v, lo, hi, ganz=False, nk=2):
    """Zahl in [lo, hi] (ganz: ohne Nachkomma, sonst auf nk Stellen) → float | None."""
    if isinstance(v, bool) or v is None or v == "":
        return None
    try:
        x = float(v)
    except (TypeError, ValueError):
        return None
    if x != x or x < lo or x > hi or (ganz and x != int(x)):
        return None
    return int(x) if ganz or x == int(x) else round(x, nk)


def fdp_regeln_aendern(reg, body):
    """REIN RECHNEND (testbar): Änderung aus POST /admin/funded-plan/regeln prüfen und in die Zeile mischen → (patch, None) | (None, fehler).
    body = {updated_at, schalter?: {aktiv?, auto_bestaetigen?}, zeiten?: {max_je_id_tag?, abstand_id_min?, vorlauf_min?},
    firma?: {name, an?, lock_usd?, je_groesse?: {"<Größe>": {<Feld>: Wert}}}}. Nur vorhandene Firmen, Größen und Schlüssel; Typ bleibt."""
    if not reg:
        return None, "funded_plan_regeln fehlt — SQL einspielen"
    b = body if isinstance(body, dict) else {}
    if str(b.get("updated_at") or "") != str(reg.get("updated_at") or ""):
        return None, "inzwischen geändert — neu laden, dann erneut speichern"
    bekannt = {"updated_at", "schalter", "zeiten", "firma", "konst"}
    if set(b) - bekannt:
        return None, "unbekannte Felder: " + ", ".join(sorted(set(b) - bekannt))
    patch = {}
    sch = b.get("schalter")
    if sch is not None:
        if not isinstance(sch, dict) or not sch or set(sch) - {"aktiv", "auto_bestaetigen"} or any(not isinstance(v, bool) for v in sch.values()):
            return None, "schalter: nur aktiv / auto_bestaetigen als true/false"
        patch.update(sch)
    zt = b.get("zeiten")
    if zt is not None:
        if not isinstance(zt, dict) or not zt:
            return None, "zeiten: leer"
        if "firma_abstand_min" in zt:
            return None, "firma_abstand_min ist fest (DB-Funktion prophos_firmen_abstand_funded_fenster) — hier nicht änderbar"
        neu_z = dict(reg.get("zeiten") or {})
        for k, v in zt.items():
            if k == "fenster_eigen":   # E2b-Nachtrag: eigenes Startfenster; null = zurück auf das Fenster des Challenge-Planers
                if v is None:
                    neu_z.pop("fenster_eigen", None)
                    continue
                if not isinstance(v, dict) or set(v) - {"von", "bis", "tz"} or not fdp_fenster_eigen(v):
                    return None, "zeiten.fenster_eigen: {von: HH:MM, bis: HH:MM, tz: Asia/Dubai | Europe/Berlin}, von < bis"
                neu_z["fenster_eigen"] = {"von": str(v["von"]), "bis": str(v["bis"]), "tz": str(v.get("tz") or "Asia/Dubai")}
                continue
            if k not in _FDP_ZEIT_FELDER:
                return None, f"zeiten.{k}: nicht änderbar"
            lo, hi, ganz = _FDP_ZEIT_FELDER[k]
            x = _fdp_zahl(v, lo, hi, ganz)
            if x is None:
                return None, f"zeiten.{k}: Zahl {lo}–{hi}{' (ganz)' if ganz else ''}"
            neu_z[k] = x
        patch["zeiten"] = neu_z
    ko = b.get("konst")
    if ko is not None:
        if "konst" not in reg:
            return None, "Spalte konst fehlt — sql/2026-11-05_fdp_einstellungen_db.sql einspielen"
        if not isinstance(ko, dict) or not ko:
            return None, "konst: leer"
        neu_k = dict(reg.get("konst") or {}) if isinstance(reg.get("konst"), dict) else {}
        for k, v in ko.items():
            if k not in FDP_KONST:
                return None, f"konst.{k}: nicht änderbar"
            lo, hi = FDP_KONST[k][1], FDP_KONST[k][2]
            x = _fdp_zahl(v, lo, hi)
            if x is None:
                return None, f"konst.{k}: Zahl {lo}–{hi}"
            neu_k[k] = x
        patch["konst"] = neu_k
    fa = b.get("firma")
    if fa is not None:
        if not isinstance(fa, dict) or not fa.get("name") or set(fa) - {"name", "an", "lock_usd", "je_groesse", "consistency_pct"} or len(fa) < 2:
            return None, "firma: {name, an | lock_usd | je_groesse | consistency_pct}"
        firmen = [dict(f) if isinstance(f, dict) else f for f in (reg.get("firmen") or [])]
        idx = [i for i, f in enumerate(firmen) if isinstance(f, dict) and (f.get("name") or (f.get("namen") or [""])[0]) == fa["name"]]
        if len(idx) != 1:
            return None, f"Firma „{fa['name']}“ nicht (eindeutig) in den Regeln"
        f = firmen[idx[0]]
        if "an" in fa:
            if not isinstance(fa["an"], bool):
                return None, "an: true/false"
            f["an"] = fa["an"]
        if "consistency_pct" in fa:   # E2d (Finn: „Tradeify manchmal 40, manchmal 50 — auswählen“): Anzeige-Parameter je Firma, null = keine; neuer Schlüssel ausdrücklich erlaubt
            if fa["consistency_pct"] is None:
                f.pop("consistency_pct", None)
            else:
                x = _fdp_zahl(fa["consistency_pct"], 10, 100)
                if x is None:
                    return None, "consistency_pct: Zahl 10–100 oder null"
                f["consistency_pct"] = x
        if "lock_usd" in fa:
            if "lock_usd" not in f:
                return None, "lock_usd: bei dieser Firma nicht hinterlegt"
            x = _fdp_zahl(fa["lock_usd"], 0, 1000)
            if x is None:
                return None, "lock_usd: Zahl 0–1000"
            f["lock_usd"] = x
        if "je_groesse" in fa:
            jg_alt = f.get("je_groesse") if isinstance(f.get("je_groesse"), dict) else {}
            if not isinstance(fa["je_groesse"], dict) or not fa["je_groesse"]:
                return None, "je_groesse: leer"
            jg = {k: dict(v) if isinstance(v, dict) else v for k, v in jg_alt.items()}
            for gr, werte in fa["je_groesse"].items():
                if str(gr) not in jg or not isinstance(jg[str(gr)], dict):
                    return None, f"Größe {gr}: nicht hinterlegt (neue Größen nur per SQL)"
                if not isinstance(werte, dict) or not werte:
                    return None, f"Größe {gr}: leer"
                z = jg[str(gr)]
                for k, v in werte.items():
                    if k not in z and k != "ziel_toleranz_pct":   # FE1b: Ziel-Toleranz darf neu dazukommen (Standard 0 = nicht hinterlegt)
                        return None, f"{gr}.{k}: bei dieser Größe nicht hinterlegt"
                    if k in _FDP_GR_BOOL:   # FF2
                        if not isinstance(v, bool):
                            return None, f"{gr}.{k}: true/false"
                        z[k] = v
                        continue
                    if k in _FDP_GR_ZEIT:   # FF2
                        m_z = re.fullmatch(r"(\d{2}):(\d{2})", str(v or ""))
                        if not m_z or int(m_z.group(1)) > 23 or int(m_z.group(2)) > 59:
                            return None, f"{gr}.{k}: Uhrzeit HH:MM"
                        z[k] = str(v)
                        continue
                    if k in _FDP_GR_KT:
                        if not isinstance(v, dict) or not v or not isinstance(z[k], dict):
                            return None, f"{gr}.{k}: {{Kontrakte: Anteil}}"
                        kt = {}
                        for kk, w in v.items():
                            n, ww = _fdp_zahl(kk, 1, 10, True), _fdp_zahl(w, 0, 1, nk=3)   # Anteile auf 3 Stellen wie das Frontend (Gegenprüfung)
                            if n is None or ww is None:
                                return None, f"{gr}.{k}: Kontrakte 1–10, Anteil 0–1"
                            if ww > 0:
                                kt[str(n)] = ww
                        if not kt or abs(sum(kt.values()) - 1) > 0.011:
                            return None, f"{gr}.{k}: Anteile müssen zusammen 100 % ergeben"
                        z[k] = kt
                        continue
                    if k not in _FDP_GR_FELDER:
                        return None, f"{gr}.{k}: nicht änderbar"
                    lo, hi = _FDP_GR_FELDER[k]
                    # E2h (Finn 05.11.2026: „bei Ziel immer von – bis"): Ziel-Gewinn darf von der Zahl zur Spanne werden (alte Zahl = von = bis)
                    if isinstance(z.get(k), (list, tuple)) or (k == "ziel_gewinn" and isinstance(v, (list, tuple))):
                        if not isinstance(v, (list, tuple)) or len(v) != 2:
                            return None, f"{gr}.{k}: Spanne [von, bis]"
                        a, e = _fdp_zahl(v[0], lo, hi), _fdp_zahl(v[1], lo, hi)
                        if a is None or e is None or a > e:
                            return None, f"{gr}.{k}: Spanne {lo}–{hi}, von ≤ bis"
                        z[k] = [a, e]
                    else:
                        x = _fdp_zahl(v, lo, hi)
                        if x is None:
                            return None, f"{gr}.{k}: Zahl {lo}–{hi}"
                        z[k] = x
            f["je_groesse"] = jg
        # FF2: Pump-Modell — Startfenster von < bis, und nur mit Fusion-Hedge je Größe einschalten (Lucid: Finn hat keinen Satz genannt)
        if f.get("tp_modus") == "pump2":
            for gr, z in (f.get("je_groesse") or {}).items():
                if isinstance(z, dict) and z.get("t1_von") and z.get("t1_bis") and str(z["t1_von"]) >= str(z["t1_bis"]):
                    return None, f"{gr}: Start ab muss vor Start bis liegen"
            if f.get("an") and any(isinstance(z, dict) and not ((_wd_num(z.get("hedge_eur")) or 0) > 0 and (_wd_num(z.get("hedge_auf_usd")) or 0) > 0)
                                   for z in (f.get("je_groesse") or {}).values()):
                return None, "Pump-Modell: Fusion-Hedge fehlt — erst eintragen, dann einschalten"
        firmen[idx[0]] = f
        patch["firmen"] = firmen
    if not patch:
        return None, "nichts zu ändern"
    return patch, None


# ── WINNING DAY JE FIRMA (E2b, 04.11.2026, Finn ~19:15 Dubai zum Foto der Einstellungen: „Vielleicht noch hinzufügen: Was ist ein Winning Day?“ — nach
# dem Big Trade (Ziel erreicht) geht das Konto auf Winning Days). NUR ANZEIGE, Quelle der Wahrheit bleibt Winning Days → Einstellungen bzw. der Code des Farmers:
#  - Mindestgewinn je Tag: wd_min_gewinn (WD_GOOD_DAY_MIN; je Konto überschreibbar mit goal_min_profit) — dieselbe Funktion, mit der der Farmer zählt
#  - WDs bis Payout: goal_target je Konto, Standard 5 (wd_konten_alle / Abhaken „or 5“)
#  - TP und Kontrakte je WD-Trade: wd_farmer_regeln.vorplan.regeln.fu / .kt (Winning Days → Einstellungen → Firmen); fehlt die Firma dort, der Standard des
#    Farmers (WD_FU_STANDARD = TP_VP_VORGABE.fu im Frontend; Lucid nimmt die Tradeify-Werte wie tpVpLucidWieTradeify)
#  - Besonderheiten aus dem Code: Apex-Recoverer (wd_farmer_regeln.zyklus_regel, sonst WD_ZYKLUS_VORGABE), Tradeify Zyklus im Plus (TRADEIFY_ZYKLUS_*)
WD_FU_STANDARD = {"tradeify": [270, 290], "lucid": [270, 290], "fnfutures": [270, 290], "apex": [370, 390], "apex100": [320, 340], "topstep": [220, 240], "sonst": [270, 290], "ftmofutures": [220, 240]}   # FT2: FTMO Futures „TP so 220 bis 240“


def fdp_wd_schluessel(name, groesse=None):
    """REIN RECHNEND (testbar): Firmen-Schlüssel des WD-Farmers wie tpVorplanFirmaKey im Frontend (fnfutures, apex/apex100 nach Größe, lucid, tradeify, topstep, sonst)."""
    f = str(name or "").lower()
    if "ftmo" in f and "futur" in f:
        return "ftmofutures"   # FT2 (11.11.2026): eigener Schlüssel wie tpVorplanFirmaKey — FTMO CFD bleibt „sonst“
    if "fundednext" in f and "futur" in f:
        return "fnfutures"
    if "apex" in f:
        return "apex100" if str(groesse or "") == "100000" else "apex"
    if "lucid" in f:
        return "lucid"
    if _ist_tradeify_cfd(name):
        return "sonst"
    return "tradeify" if "tradeify" in f else "topstep" if "topstep" in f else "sonst"


def fdp_wd_anzeige(firma, vorplan, zyklus_regel, bestaetigen=(), firmen_regeln=None):
    """REIN RECHNEND (testbar): „Was ist ein Winning Day“ für eine Firma der Funded-Futures-Regel → {groessen: [{groesse, min_usd, tp, tp_quelle, kt, instr}],
    ziel_std, bestaetigen, besonders: [Text], fehlt: bool}. Größen = die der Funded-Regel; ohne Größe ein Eintrag für die Firma. bestaetigen = wd_bestaetigen_firmen()
    (Farmer-WD dieser Firma starten erst nach ✓ unter Funded Planer → Winning Days)."""
    name = (firma or {}).get("name") or ""
    vp = vorplan if isinstance(vorplan, dict) else {}
    rg = vp.get("regeln") if isinstance(vp.get("regeln"), dict) else {}
    fu = rg.get("fu") if isinstance(rg.get("fu"), dict) else {}
    ktr = rg.get("kt") if isinstance(rg.get("kt"), dict) else {}
    rund = lambda x: int(float(x) + 0.5) if x is not None else None   # noqa: E731 — wie Math.round im Frontend (positiv)
    kt_std = max(1, rund(_wd_num(vp.get("kt")) or 1))
    instr = "NQ" if vp.get("instr") == "nq" else "MNQ"
    gr = sorted((str(g) for g in ((firma or {}).get("je_groesse") or {})), key=lambda x: float(x) if x.replace(".", "", 1).isdigit() else 0) or [None]
    zeilen = []
    for g in gr:
        key = fdp_wd_schluessel(name, g)
        tp = fu.get(key) if isinstance(fu.get(key), list) else (fu.get("tradeify") if key == "lucid" and isinstance(fu.get("tradeify"), list) else None)
        quelle = "wd-farmer" if tp else "standard"
        tp = tp or WD_FU_STANDARD.get(key)
        k = ktr.get(key) if isinstance(ktr.get(key), list) else (ktr.get("tradeify") if key == "lucid" and isinstance(ktr.get("tradeify"), list) else None)
        # wie wdKtSpanne (Gegenprüfung E2b): von = max(1, round(sp[0] || std)), bis = max(von, round(sp[1] || von)); keine Liste → [std, std]
        if k is not None:
            kv = max(1, rund(_wd_num(k[0] if len(k) > 0 else None) or kt_std))
            kt = [kv, max(kv, rund(_wd_num(k[1] if len(k) > 1 else None) or kv))]
        else:
            kt = [kt_std, kt_std]
        konto = {"firm": name, "name": f"{int(float(g)) // 1000}k" if g else ""}
        zeilen.append({"groesse": g, "schluessel": key, "min_usd": wd_min_gewinn(konto), "tp": [_wd_num(x) for x in tp] if tp else None, "tp_quelle": quelle,
                       "kt": kt, "instr": instr})
    f = str(name).lower()
    # Besonderheiten als PARAMETER {name, wert, info} (Nachtrag 3, Finn 05.11.2026: „Die Logik soll nicht da stehen, nur der Parameter“) — info steht im Reiter hinter ⓘ
    bes = []
    if "apex" in f and not isinstance(zyklus_regel, dict):
        # wie wd_zyklus_konto: ohne DB-Regel ist der Recoverer aus (Code keine_regel), nicht „an mit Vorgabe" (Gegenprüfung E2b)
        bes.append({"name": "Recoverer", "wert": "nicht eingerichtet", "info": "wd_farmer_regeln.zyklus_regel fehlt — nach einem Verlusttag laufen normale WD"})
    elif "apex" in f:
        zr = zyklus_regel
        st = sorted(((_wd_num(x.get("v")), _wd_num(x.get("ziel")), _wd_num(x.get("satz"))) for x in (zr.get("stuetz") or WD_ZYKLUS_VORGABE["stuetz"]) if isinstance(x, dict)),
                    key=lambda x: x[0] or 0)
        de = lambda v: f"{v:,.0f}".replace(",", ".")   # noqa: E731
        fi = zr.get("firmen") or WD_ZYKLUS_VORGABE["firmen"]
        gilt = [("100k" if z["schluessel"] == "apex100" else "150k") for z in zeilen if z["schluessel"] in fi]
        an = bool(zr.get("aktiv", True)) and bool(gilt)                  # wie wd_zyklus_konto: not r.get("aktiv", True) → aus, Schlüssel nicht in firmen → aus
        ab = int(_wd_num(zr.get("ab_zyklus")) or 2)
        bes.append({"name": "Recoverer", "wert": ("an" + (" (" + " · ".join(gilt) + ")" if len(gilt) < len(zeilen) else "") + f" · ab Zyklus {ab}") if an else "aus",
                    "info": f"nach einem Verlusttag im Payout-Zyklus WD-Ziel und Hedge linear nach dem Verlust, bis der Zyklus-Profit ≥ 2 × bester Tag ist · {WD_ZYKLUS_KT} {WD_ZYKLUS_INSTR.upper()}"})
        if an:   # eine Zeile je Stützpunkt (Verlust im Zyklus → WD-Ziel / Hedge), dazwischen linear
            bes += [{"name": f"bei −{de(v)} $ Verlust", "wert": f"{de(z)} $ / {de(sa)} €", "info": "Verlust im Zyklus → WD-Ziel $ / Hedge €, dazwischen linear"}
                    for v, z, sa in st if v and z and sa]
    if "tradeify" in f and not _ist_tradeify_cfd(name):
        _mn = wd_firmen_regel(firmen_regeln, "tradeify")["min_netto"]   # E4: Parameter aus Winning Days → Einstellungen (Standard 1 $ ab Zyklus 2)
        bes.append({"name": f"Payout ab Zyklus {_mn['ab_zyklus']}", "wert": (f"+{_mn['usd']:,.0f} $ im Zyklus".replace(",", ".") if _mn["an"] else "aus"),
                    "info": "Zyklus im Plus: Tradeify zahlt erst, wenn der Gewinn seit der letzten Anfrage mindestens so hoch ist (Winning Days → Einstellungen → Tradeify)"})
        bes.append({"name": "Ausgleichs-Trade", "wert": f"Fehlbetrag + {TRADEIFY_ZYKLUS_PUFFER[0]}–{TRADEIFY_ZYKLUS_PUFFER[1]} $" + (" · einzeln ✓" if TRADEIFY_AUSGLEICH_BESTAETIGEN else ""),
                    "info": "im Minus normale WD bis Ziel − 1, der letzte WD gleicht den Fehlbetrag aus"})
    if "lucid" in f:
        bes.append({"name": "Regeln", "wert": "wie Tradeify", "info": "1:1 die Tradeify-Regeln (Finn 23.10.2026) — WD-Werte von Tradeify, solange Lucid keine eigenen hat"})
        _mnl = wd_firmen_regel(firmen_regeln, "lucid")["min_netto"]   # LZ1 (Finn 10.11.2026): Zyklus im Plus auch bei Lucid, in jedem Zyklus
        bes.append({"name": f"Payout ab Zyklus {_mnl['ab_zyklus']}", "wert": (f"+{_mnl['usd']:,.0f} $ im Zyklus".replace(",", ".") if _mnl["an"] else "aus"),
                    "info": "Zyklus im Plus: Lucid zahlt nur aus, wenn der Net Profit seit der letzten Anfrage (im 1. Zyklus seit Kontostart) mindestens so hoch ist (Winning Days → Einstellungen → Lucid)"})
        bes.append({"name": "Ausgleichs-Trade", "wert": f"Fehlbetrag + {TRADEIFY_ZYKLUS_PUFFER[0]}–{TRADEIFY_ZYKLUS_PUFFER[1]} $" + (" · einzeln ✓" if TRADEIFY_AUSGLEICH_BESTAETIGEN else ""),
                    "info": "im Minus normale WD bis Ziel − 1, der letzte WD gleicht den Fehlbetrag aus (wie Tradeify)"})
    if "fundednext" in f and "futur" in f:
        bes.append({"name": "Regeln", "wert": "wie Tradeify", "info": "Finn 16.10.2026 — eigener Schlüssel im WD-Farmer"})
    best = any(str(k) and str(k) in f for k in (bestaetigen or ()))   # wie tpWdWartetAufBestaetigung / wd_bestaetigen_noetig: Teilstring im Firmennamen
    return {"groessen": zeilen, "ziel_std": 5, "bestaetigen": best, "besonders": bes, "fehlt": all(z["min_usd"] is None for z in zeilen)}


@app.route("/admin/funded-plan/regeln", methods=["POST", "OPTIONS"])
def admin_funded_plan_regeln():
    """POST → funded_plan_regeln ändern (E2, 04.11.2026). Nur Admin bzw. „Finn + Pascal“/„Pascal“ (admin_voll_uids) — die Regeln gelten für
    alle Gruppen. Prüfen und Mischen in fdp_regeln_aendern; Antwort mit den neuen Einstellungen (fdp_regeln_anzeige)."""
    if request.method == "OPTIONS":
        return "", 200
    _gs = _planer_schreib_gate()              # PLANER-RECHTE HT (30.10.2026)
    if _gs is not None:
        return _gs
    admin, uid, _sicht, err = _fdp_login()
    if err:
        return err
    body = request.get_json(silent=True) or {}
    if body.get("gruppe_id"):
        # UNT4: Abweichung eines Unternehmens (nur Firmen-Werte) — geprüft wie der Standard (fdp_regeln_aendern auf der wirksamen Regel)
        if set(body) - {"gruppe_id", "updated_at", "firma", "standard"}:
            return jsonify({"ok": False, "msg": "im Unternehmen sind nur Firmen-Werte änderbar (Schalter, Zeiten, Fenster, Grenzen gelten für alle)"}), 400
        reg = _fdp_regeln_laden()
        _a = lambda eff, b: fdp_regeln_aendern(dict(eff, updated_at=(reg or {}).get("updated_at")), dict(b, updated_at=(reg or {}).get("updated_at")))   # noqa: E731
        antw = _fd_unt_post("futures", reg, admin, uid, body, _a)
        if antw[0].is_json and (antw[0].get_json() or {}).get("ok"):
            _us = fd_unt_sicht("futures", _fdp_regeln_laden(), admin, uid)   # frisch: Name, Spalte, Auswahl wie im GET
            _d = antw[0].get_json()
            regeln = fdp_regeln_anzeige(_d.get("eff"), "db")   # wirksame Regel NACH dem Speichern (ein erneutes Lesen könnte den alten Stand liefern)
            regeln.update(abweichung=_d["abweichung"], darf=True, unternehmen_liste=fd_unt_auswahl(admin),
                          unternehmen={k: _us[k] for k in ("gruppe_id", "name", "spalte")} if _us else {"gruppe_id": str(body["gruppe_id"])})
            return jsonify(json.loads(json.dumps({"ok": True, "regeln": regeln}, default=str)))
        return antw
    try:
        voll = admin or str(uid) in {str(u) for u in (admin_voll_uids() or ())}
    except Exception:
        voll = admin
    if not voll:
        return jsonify({"ok": False, "msg": "Regeln des Funded-Planers ändern nur „Finn + Pascal“ und „Pascal“ — sie gelten für alle Gruppen"}), 403
    reg = _fdp_regeln_laden()
    patch, fehler = fdp_regeln_aendern(reg, request.get_json(silent=True) or {})
    if fehler:
        return jsonify({"ok": False, "msg": fehler}), (503 if not reg else 409 if fehler.startswith("inzwischen") else 400)
    patch["updated_at"] = datetime.now(timezone.utc).isoformat()
    neu = sb_update("funded_plan_regeln", {"id": "eq.1", "updated_at": f"eq.{reg.get('updated_at')}"}, patch)
    _fdp_reg_cache["at"] = 0.0     # KK1b: /konto-ziele liest danach frisch (auch bei 409 harmlos)
    if not neu:
        return jsonify({"ok": False, "msg": "inzwischen geändert — neu laden, dann erneut speichern"}), 409
    print(f"[funded-plan] Regeln geändert ({', '.join(k for k in patch if k != 'updated_at')}) von {str(uid or 'admin')[:8]}", flush=True)
    return jsonify({"ok": True, "regeln": fdp_regeln_anzeige(neu[0] if isinstance(neu, list) else _fdp_regeln_laden())})


# ══ FUNDED-CFD-PLANER (30.10.2026, Finn ~07:00 Dubai: „Ja, bauen"; Regeln diktiert 05:10–06:55, .claude/master/funded-cfd-planer-regeln.md).
