@app.route("/admin/funded-cfd-plan/waiting-zurueck", methods=["POST", "OPTIONS"])
def admin_funded_cfd_plan_waiting_zurueck():
    """POST {account_id} — WP3-Zusatz (10.11.2026, Master mit S3): seit WP3 stellt der Planer am Ziel ohne Schalter auf Waiting for Payout um; damit Finn
    ein falsch umgestelltes Konto (auch einer fremden ID) im Funded Planer → CFD zurücksetzen kann. Gate wie /einstellung: nur Admin, dazu die
    Schreib-Sicht der Gruppe (Zwei Unternehmen getrennt: HT nur HT-Konten). Nur account_type funded_cfd mit gesetztem waiting_payout_since → null.
    → {ok, merker, konto}. Setzt den Merker accounts.fcp_wartet_zurueck: der Planer stellt das Konto erst nach einer Balance-Änderung (nächster Trade)
    wieder automatisch um (fcp_merker_urteil)."""
    if request.method == "OPTIONS":
        return "", 200
    _gs = _planer_schreib_gate()              # PLANER-RECHTE HT (30.10.2026)
    if _gs is not None:
        return _gs
    admin, uid, _lese, sicht, err = _fcp_login()
    if err:
        return err
    if not admin:
        return jsonify({"ok": False, "msg": "Waiting for Payout zurücksetzen — nur Admin"}), 403
    body = request.get_json(silent=True) or {}
    aid = str(body.get("account_id") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}", aid):
        return jsonify({"ok": False, "msg": "account_id fehlt oder ungültig"}), 400
    try:
        a = (sb_select("accounts", {"select": "id,user_id,name,firm,account_type,waiting_payout_since", "id": f"eq.{aid}"}) or [None])[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Konto nicht lesbar ({type(e).__name__})"}), 502
    if not a:
        return jsonify({"ok": False, "msg": "Konto nicht gefunden"}), 404
    if sicht is not None and not admin_in_sicht(a.get("user_id"), sicht):
        return jsonify({"ok": False, "msg": "nur Konten der eigenen Gruppe"}), 403
    if a.get("account_type") != "funded_cfd":
        return jsonify({"ok": False, "msg": "nur Funded-CFD-Konten"}), 400
    if not a.get("waiting_payout_since"):
        return jsonify({"ok": False, "msg": "Konto steht nicht auf Waiting for Payout"}), 409
    # Merker (Master 10.11.2026): {at, von, balance None} — die Balance trägt der nächste Planer-Lauf aus SEINER Lesung ein (fcp_merker_urteil
    # „fuellen"), danach stellt er das Konto erst nach einer Balance-Änderung (nächster Trade) wieder automatisch um. Spalte fehlt → ohne Merker
    merker_neu = {"at": datetime.now(timezone.utc).isoformat(), "von": str(uid or ""), "balance": None}
    filt = {"id": f"eq.{aid}", "account_type": "eq.funded_cfd", "waiting_payout_since": "not.is.null"}
    mit_merker = True
    try:
        try:
            zeilen = sb_update("accounts", filt, {"waiting_payout_since": None, "fcp_wartet_zurueck": merker_neu})
        except requests.exceptions.HTTPError as e1:
            if "fcp_wartet_zurueck" not in str(getattr(getattr(e1, "response", None), "text", "") or e1):
                raise
            mit_merker = False
            zeilen = sb_update("accounts", filt, {"waiting_payout_since": None})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"{type(e).__name__}: {str(e)[:160]}"}), 502
    if not zeilen:
        return jsonify({"ok": False, "msg": "inzwischen geändert — neu laden"}), 409
    print(f"[funded-cfd] Waiting for Payout zurückgesetzt: {a.get('name')} (war seit {a.get('waiting_payout_since')}) durch Admin {str(uid)[:8]}", flush=True)
    return jsonify({"ok": True, "merker": mit_merker,
                    **({} if mit_merker else {"hinweis": "Spalte fcp_wartet_zurueck fehlt (sql/2026-11-10_fcp_wartet_zurueck.sql) — der Planer kann das Konto beim nächsten Lauf wieder umstellen"}),
                    "konto": {"id": aid, "user_id": a.get("user_id"), "name": a.get("name"), "firm": a.get("firm"),
                              "waiting_payout_since": None, "war_seit": a.get("waiting_payout_since")}})


@app.route("/admin/funded-cfd-plan/einstellung", methods=["POST", "OPTIONS"])
def admin_funded_cfd_plan_einstellung():
    """POST {news_regel: bool} — Kachel „News-Regel (rote USD-News)" im Funded Planer → CFD (S8 8427eda9). Der Schalter gilt für alle Gruppen
    (eine Zeile funded_cfd_plan_regeln) → nur Admin. /news/calendar liefert ihn nach ≤ 60 s als news_regel."""
    if request.method == "OPTIONS":
        return "", 200
    _gs = _planer_schreib_gate()              # PLANER-RECHTE HT (30.10.2026)
    if _gs is not None:
        return _gs
    admin, uid, _lese, _schreib, err = _fcp_login()
    if err:
        return err
    if not admin:
        return jsonify({"ok": False, "msg": "Die News-Regel gilt für alle Gruppen — nur Admin"}), 403
    body = request.get_json(silent=True) or {}
    if not isinstance(body.get("news_regel"), bool):
        return jsonify({"ok": False, "msg": "news_regel = true | false"}), 400
    try:
        zeilen = sb_update("funded_cfd_plan_regeln", {"id": "eq.1"}, {"news_regel": body["news_regel"], "updated_at": datetime.now(timezone.utc).isoformat()})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"{type(e).__name__}: {str(e)[:160]} — sql/2026-10-30_news_regel_schalter.sql eingespielt?"}), 502
    _news_regel["at"] = 0.0                  # /news/calendar liest sofort neu
    print(f"[funded-cfd] News-Regel {'AN' if body['news_regel'] else 'AUS'} durch Admin {str(uid)[:8]}", flush=True)
    return jsonify({"ok": True, "news_regel": body["news_regel"], "n": len(zeilen or [])})


@app.route("/admin/funded-cfd-plan/regel", methods=["POST", "OPTIONS"])
def admin_funded_cfd_plan_regel():
    """POST EINE Änderung der Regeln (fcp_regel_patch) — Einstellungen im Funded Planer → CFD (E1, 04.11.2026). Die Regeln gelten für alle
    Gruppen → nur Admin. Konfliktschutz: geschrieben wird nur, wenn updated_at noch dem gelesenen Stand entspricht (sonst 409, neu laden)."""
    if request.method == "OPTIONS":
        return "", 200
    _gs = _planer_schreib_gate()              # PLANER-RECHTE HT (30.10.2026)
    if _gs is not None:
        return _gs
    admin, uid, _lese, _schreib, err = _fcp_login()
    if err:
        return err
    body = request.get_json(silent=True) or {}
    if body.get("gruppe_id"):
        # UNT4: Abweichung eines Unternehmens (Firmen-Werte + Parameter) — geprüft wie der Standard (fcp_regel_patch auf der wirksamen Regel)
        if body.get("schalter") is not None or body.get("zeit") is not None:
            return jsonify({"ok": False, "msg": "im Unternehmen sind nur Firmen-Werte und Parameter änderbar (Schalter und Zeiten gelten für alle)"}), 400
        try:
            reg_c = _fcp_regeln_laden()
        except Exception as e:
            return jsonify({"ok": False, "msg": f"Regeln nicht lesbar ({type(e).__name__})"}), 502
        antw = _fd_unt_post("cfd", reg_c, admin, uid, body, fcp_regel_patch)
        if (antw[0].get_json() or {}).get("ok"):
            d = antw[0].get_json()
            return jsonify({"ok": True, "abweichung": d["abweichung"], "geaendert": ["funded_regeln"]})
        return antw
    if not admin:
        return jsonify({"ok": False, "msg": "Die Funded-CFD-Regeln gelten für alle Gruppen — nur Admin"}), 403
    try:
        try:   # E1b: Spalte parameter (sql/2026-11-05_fcp_einstellungen_db.sql) — fehlt sie noch, ohne sie lesen (Patch meldet es dann)
            zeile = (sb_select("funded_cfd_plan_regeln", {"select": "id,aktiv,auto_bestaetigen,ziel_auto_wartet,zeiten,firmen,parameter,updated_at", "id": "eq.1"}) or [None])[0]
        except Exception as e1:
            # nur bei fehlender Spalte ohne sie lesen — ein anderer Fehler (z. B. kurzer Ausfall) soll nicht „Spalte fehlt" melden (Fremd-Review E1b)
            _r1 = getattr(e1, "response", None)   # PostgREST: 400 „column funded_cfd_plan_regeln.parameter does not exist" (str(e1) trägt nur die URL)
            if getattr(_r1, "status_code", None) != 400 or "parameter" not in str(getattr(_r1, "text", "") or ""):
                raise
            zeile = (sb_select("funded_cfd_plan_regeln", {"select": "id,aktiv,auto_bestaetigen,ziel_auto_wartet,zeiten,firmen,updated_at", "id": "eq.1"}) or [None])[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Regeln nicht lesbar ({type(e).__name__})"}), 502
    if not zeile:
        return jsonify({"ok": False, "msg": "funded_cfd_plan_regeln fehlt — SQL einspielen"}), 503
    upd, fehler = fcp_regel_patch(zeile, body)
    if fehler:
        return jsonify({"ok": False, "msg": fehler}), 400
    jetzt = datetime.now(timezone.utc).isoformat()
    filt = {"id": "eq.1"}
    if zeile.get("updated_at"):
        filt["updated_at"] = f"eq.{zeile['updated_at']}"
    try:
        zeilen = sb_update("funded_cfd_plan_regeln", filt, dict(upd, updated_at=jetzt))
    except Exception as e:
        return jsonify({"ok": False, "msg": f"nicht gespeichert ({type(e).__name__}: {str(e)[:120]})"}), 502
    if not zeilen:
        return jsonify({"ok": False, "msg": "Regeln wurden inzwischen geändert — neu laden und noch einmal"}), 409
    print(f"[funded-cfd] Regel geändert durch Admin {str(uid)[:8]}: {json.dumps(body, ensure_ascii=False)[:200]}", flush=True)
    return jsonify({"ok": True, "geaendert": sorted(upd.keys()), "updated_at": jetzt})


@app.route("/admin/funded-cfd-plan/planen", methods=["POST", "OPTIONS"])
def admin_funded_cfd_plan_planen():
    """POST {tag: auto | heute | morgen} — „Jetzt planen" wie beim Funded-Planer (Vorschläge ohne Startzeit). Nur bei aktiv = true; legt für
    alle IDs der Regel an (jede Gruppe für sich), die Antwort zeigt nur die Sicht des Logins."""
    if request.method == "OPTIONS":
        return "", 200
    _gs = _planer_schreib_gate()              # PLANER-RECHTE HT (30.10.2026)
    if _gs is not None:
        return _gs
    admin, uid, sicht, schreib, err = _fcp_login()
    if err:
        return err
    if isinstance(schreib, str) or not schreib:
        return jsonify({"ok": False, "msg": "Jetzt planen nur im Admin-Reiter (alle IDs der Gruppe)"}), 403
    reg = _fcp_regeln_laden()
    if not reg:
        return jsonify({"ok": False, "msg": "funded_cfd_plan_regeln fehlt — SQL einspielen"}), 503
    if not reg.get("aktiv"):
        return jsonify({"ok": False, "msg": "Funded-CFD-Planer ist aus (funded_cfd_plan_regeln.aktiv)"}), 409
    body = request.get_json(silent=True) or {}
    bezug, wort = fdp_plan_jetzt(body.get("tag"), datetime.now(timezone.utc))
    try:
        erg = fcp_sicht(fcp_planen(trocken=False, jetzt=bezug, nur_ids=schreib), sicht)
    except Exception as e:
        print(f"[funded-cfd] ⚠️ Jetzt planen: {type(e).__name__}: {e}", flush=True)
        return jsonify({"ok": False, "msg": f"{type(e).__name__}: {e}"}), 500
    kurz = lambda z: {k: z.get(k) for k in ("konto", "konto_id", "user_id", "start", "start_um", "richtung", "tp", "sl", "lots", "hedge_lots", "grund")}   # noqa: E731
    print(f"[funded-cfd] Jetzt planen ({wort}) durch {'Admin' if admin else 'ID ' + str(uid)[:8]}: {len(erg.get('geplant') or [])} Vorschläge", flush=True)
    return jsonify({"ok": bool(erg.get("ok")), "tag": wort, "plan_tag": erg.get("tag"), "msg": erg.get("msg"),
                    "geplant": [kurz(z) for z in erg.get("geplant") or []], "ziel": [kurz(z) for z in erg.get("ziel") or []],
                    "ausgelassen": [kurz(z) for z in erg.get("ausgelassen") or []]})


def start_auto_planer():
    global _ap_started
    if _ap_started or not SUPABASE_SERVICE_KEY:
        return
    if (os.environ.get("PROPHOS_FRONTEND") or "").strip():
        return          # PC-Backend: kein Nachtlauf (nur Railway plant, sonst plant jeder PC)
    _ap_started = True
    _ap_info["started"] = True
    threading.Thread(target=ap_loop, daemon=True).start()
    threading.Thread(target=eh_schnell_loop, daemon=True).start()   # ECHO-HEDGE NIE STILL (30.10.2026): wartet, bis eh_tick einmal lief
    if not _fp["started"]:                    # Fremd-Positionen-Wache (08.10.2026) — eigener Takt, nur Railway wie der Planer
        _fp["started"] = True
        threading.Thread(target=fp_loop, daemon=True).start()
    if not _fb["started"]:                    # Fusion-Blindgänger-Wache (FW1, 10.11.2026) — eigener 10-s-Takt, nur Railway
        _fb["started"] = True
        threading.Thread(target=fb_loop, daemon=True).start()


def _ap_eingriff(aktion):
    """POST /admin/auto-plan/{bestaetigen {plan_ids} | zurueck {plan_id} | loeschen {plan_id}} (07.10.2026, Trade-Planer alle IDs).
    Gate (ap_eingriff_sicht, seit .1119 BESTÄTIGEN FÜR ALLE): Admin (ADMIN_EMAILS) und jeder Login im Planer (auto_plan_regeln.user_ids)
    alle IDs; admin_zugang „nur eigene" und jeder andere Login nur die eigenen (403 bei fremden Plänen). Guard-Bedingungen
    (ap_eingriff_filter) in derselben Anfrage; Antwort = die wirklich geänderten bzw. gelöschten Zeilen + alle:true/false (darf dieser
    Login fremde Pläne anfassen — das Frontend zeigt danach den ✓-Knopf bei allen Zeilen). Eigene Pläne schreibt das Frontend weiter
    selbst per supabase-js (RLS)."""
    if request.method == "OPTIONS":
        return "", 200
    _gs = _planer_schreib_gate()              # PLANER-RECHTE HT (30.10.2026)
    if _gs is not None:
        return _gs
    _mail, err = _planer_admin_auth()
    admin = err is None
    uid = str(request.environ.get("prophos.admin_uid") or "") if admin else None
    if not admin:
        if err[1] != 403:
            return err
        uid, err2 = _wd_login()
        if err2:
            return err2
    try:
        sicht_l, verwalter = admin_sicht_lesen(str(uid))   # Admin-Gruppen (08.10.2026): eingeschränkt + Gruppe des Verwalters
        nur, gruppe = sicht_l is not None, (sicht_l if verwalter else None)
        im_planer = False if admin else str(uid) in [str(u) for u in ((sb_select("auto_plan_regeln", {"select": "user_ids", "id": "eq.1"})
                                                                       or [{}])[0].get("user_ids") or [])]
    except Exception:
        return jsonify({"ok": False, "msg": "Anmeldung nicht prüfbar"}), 502
    body = request.get_json(silent=True) or {}
    sicht = ap_eingriff_sicht(admin, uid, im_planer, nur, ap_verwalter_sicht(gruppe, _ap_sicht_param()), gruppe)   # sicht:"admin" im Body = Admin-Reiter (08.10.2026), Verwalter fest (02.11.2026)
    ids = body.get("plan_ids") if isinstance(body.get("plan_ids"), list) else [body.get("plan_id")]
    params, upd, art = ap_eingriff_filter(aktion, ids, sicht)
    if params is None:
        return jsonify({"ok": False, "msg": art}), 400
    try:
        if sicht is not None:   # eine ID oder die Gruppe des Verwalters (Menge)
            fremd = [z for z in sb_select("trade_plans", {"select": "id,user_id", "id": params["id"]}) if not admin_in_sicht(z.get("user_id"), sicht)]
            if fremd:
                return jsonify({"ok": False, "msg": "nur eigene Pläne" if isinstance(sicht, str) else "nur Pläne der eigenen Gruppe"}), 403
        # JEDER NUR SEINE COMPANY (Finn 06.11.2026 zu HF2: „wenn ich als Admin-ID in HT acc bestätige, werden nur HT-acc bestätigt. Wenn Emin
        # bei sich acc bestätigt, nur bei sich. Jeder nur seine Company"): Bestätigen nimmt nur Pläne aus dem Unternehmen des Logins. Steht NACH dem
        # Sicht-Riegel (403 für fremde IDs/Gruppen bleibt wie vor HF2, selftest_emin_bestaetigen), greift also vor allem in der HT-Admin-Sicht
        # (unt_sicht_login: HT / Verwalter-Gruppe / ohne Unternehmen = nur er selbst; Gruppen nicht lesbar → nur die eigene ID, fail-closed)
        gehoert = unt_sicht_login(uid)
        if aktion == "bestaetigen":
            ids_ok = hf_ids_im_unternehmen(sb_select("trade_plans", {"select": "id,user_id", "id": params["id"]}) or [], gehoert)
            if not ids_ok:
                return jsonify({"ok": True, "aktion": aktion, "n": 0, "zeilen": [], "alle": sicht is None or not isinstance(sicht, str), "hedge_frei": 0,
                                "msg": "nichts bestätigt — Pläne gehören zu einem anderen Unternehmen"})
            params = dict(params, id=("eq." + ids_ok[0]) if len(ids_ok) == 1 else ("in.(" + ",".join(ids_ok) + ")"))
        if aktion == "bestaetigen":
            # BALANCE NICHT LIVE (08.10.2026, Finn: „nur bestätigen, wenn es perfekt ist"): Konto-Balance muss jünger sein als das Ende des
            # letzten Trades dieses Kontos (ap_balance_live) — sonst 400 mit Konto-Namen, nichts geändert. Lesefehler → 503, nicht
            # bestätigen (Slave 2, 08.10.2026: vorher ließ der Guard bei einem DB-Fehler durch)
            sperre = ap_bal_guard(lambda: _ap_bal_guard_laden(params["id"]))
            if sperre:
                return jsonify({"ok": False, "msg": sperre[1]}), sperre[0]
        zeilen = sb_delete("trade_plans", params) if art == "delete" else sb_update("trade_plans", params, upd)
        # Hedge-Freigabe beim ✓ (30.10.2026; HF2 06.11.2026): wer bestätigen darf, gibt damit auch frei — einzeln, „✓ alle", jede Sicht
        # (Admin, Verwalter, eigene ID). Vorher nur voller Admin mit sicht None; Finn: „einfach einmal ‚Bestätigen', fertig". Nur im eigenen
        # Unternehmen (Prüfer-Stopp S2 + Finn „Jeder nur seine Company")
        frei = _ap_hedge_mit_freigeben(zeilen, uid, gehoert) if aktion == "bestaetigen" else 0   # nur das eigene Unternehmen
        wer = "Admin" if sicht is None else ("ID " + sicht[:8]) if isinstance(sicht, str) else ("Verwalter " + str(uid)[:8])
        print(f"[auto-plan] {aktion}: {len(zeilen)} Zeile(n) durch {wer}" + (f", {frei} Hedge-Freigabe(n)" if frei else ""), flush=True)
        return jsonify({"ok": True, "aktion": aktion, "n": len(zeilen), "zeilen": zeilen, "alle": sicht is None or not isinstance(sicht, str),
                        "hedge_frei": frei})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"{type(e).__name__}: {e}"}), 502


