@app.route("/admin/auto-plan", methods=["GET", "POST", "OPTIONS"])
def admin_auto_plan():
    """GET: letzter Lauf (Admin: alle IDs, sonst nur die eigene). POST {trocken, tag}: jetzt planen — Admin oder eine ID,
    die selbst im Auto-Planer ist (Finn bestätigt in den Test-IDs, deren Login ist kein Admin).
    POST {trocken:true, ids:"alle"}: Probelauf über alle IDs mit planbaren Konten — nur Admin (ap_ids_modus, 07.10.2026)."""
    if request.method == "OPTIONS":
        return "", 200
    if request.method == "POST" and not ((request.get_json(silent=True) or {}).get("trocken") is True):
        _gs = _planer_schreib_gate()          # PLANER-RECHTE HT (30.10.2026)
        if _gs is not None:
            return _gs
    mail, err = _planer_admin_auth()
    uid = request.environ.get("prophos.admin_uid")
    admin = err is None
    if not admin:
        if err[1] != 403:
            return err
        uid, err2 = _wd_login()
        if err2:
            return err2
    reg = (sb_select("auto_plan_regeln", {"select": "aktiv,user_ids,zeiten,updated_at", "id": "eq.1"}) or [{}])[0]
    im_planer = str(uid) in [str(u) for u in (reg.get("user_ids") or [])]
    if not admin and not im_planer:
        # Admin-Reiter (08.10.2026): GET mit sicht=admin auch ohne Planer-Mitgliedschaft (ap_admin_reiter_ok); POST bleibt Planer-only.
        # Admin-Gruppen (08.10.2026): ein Verwalter liest hier seine Gruppe (ap_sicht_uid), „Jetzt planen" bleibt HT
        nur, gruppe = _ap_gruppe_lesen(uid)   # nicht lesbar → (True, None) → gesperrt
        # Verwalter ohne 403 (30.10.2026, wie _ap_zugang): GET auch ohne ?sicht=admin — dann nur die eigene ID (_ap_sicht_aus_anfrage unten)
        darf = request.method == "GET" and ap_admin_reiter_ok(False, False, nur, AP_SICHT_ADMIN,
                                                              verwalter=bool(gruppe) or bool(nur and ap_lese_gruppe(uid)))   # Mitglied liest (30.10.)
        if not darf:
            return jsonify({"ok": False, "msg": "Diese ID ist nicht im Auto-Planer"}), 403
    sicht = None if admin else str(uid)        # 06.10.2026: Nicht-Admin (Test-ID) sieht nur die eigenen Zeilen
    if request.method == "GET":
        sicht = _ap_sicht_aus_anfrage(admin, uid)   # seit 08.10.2026: Nicht-Admin alle IDs nur mit ?sicht=admin (Admin-Reiter), sonst eigene
        # GRUPPE WIE HT (30.10.2026): ein Verwalter (bzw. eine ID seiner Gruppe) sieht den letzten Lauf SEINER Gruppe (auto_plan_gruppe.
        # letzter_lauf, geschrieben von ap_gruppe_planen) — nie den HT-Lauf; HT-Logins lesen wie bisher auto_plan_lauf
        try:
            gr_lauf = None if admin else ap_gruppe_von_uid(uid)
        except Exception as e:      # Gruppen nicht lesbar → wie bisher HT-Lauf, nie HTTP 500 für jeden PC-Tab (Prüfung 30.10.2026)
            print(f"[auto-plan] ⚠️ Gruppe für den Lauf: {type(e).__name__}: {e}", flush=True)
            gr_lauf = None
        if gr_lauf:
            ll = gr_lauf.get("letzter_lauf") if isinstance(gr_lauf.get("letzter_lauf"), dict) else {}
            rows = [{"tag": ll.get("tag"), "quelle": ll.get("quelle"), "at": ll.get("at"), "ergebnis": ll}] if ll else []
        else:
            rows = sb_select("auto_plan_lauf", dict(AP_LAUF_NUR_CHALLENGE, select="tag,quelle,at,ergebnis", order="at.desc", limit="1"))
        erg = (rows[0].get("ergebnis") if rows else None) or {}
        if not gr_lauf and rows and rows[0].get("quelle") == "nachplanen" and isinstance(erg, dict) and "tw_pause_dazu" in globals():
            # TW2 (Prüfer SOLLTE 4): Nachplan-Lauf zeigt nur seine Konten — Pause-Tag-Zeilen des Haupt-Laufs desselben Tags dazu (Knopf „heute rein“ bleibt)
            try:
                _b = sb_select("auto_plan_lauf", dict(AP_LAUF_NUR_CHALLENGE, select="tag,ergebnis", tag=f"eq.{rows[0].get('tag')}", quelle="neq.nachplanen",
                                                      order="at.desc", limit="1"))
                if _b and isinstance(_b[0].get("ergebnis"), dict):
                    erg = tw_pause_dazu(dict(erg, tag=erg.get("tag") or rows[0].get("tag"), quelle_lauf="nachplanen"), dict(_b[0]["ergebnis"], tag=_b[0].get("tag")))
                    erg.pop("quelle_lauf", None)
            except Exception as e:
                print(f"[auto-plan] ⚠️ Pause-Zeilen zum Nachplan-Lauf: {type(e).__name__}: {e}", flush=True)
        try:
            erg = ap_ohne_archiv(erg, _ap_archiviert())   # seit dem Lauf archiviert → nicht mehr in Braucht dich (08.10.2026)
        except Exception as e:
            print(f"[auto-plan] ⚠️ Archiv-Filter: {type(e).__name__}: {e}", flush=True)
        if isinstance(erg, dict) and not erg.get("tag") and rows:
            erg = dict(erg, tag=rows[0].get("tag"))
        erg = ap_aus_ohne_plan_laden(erg)   # Konto hat inzwischen einen Plan für den Tag → nicht mehr in Braucht dich (09.10.2026)
        letzter = ap_sicht(erg, sicht) if sicht is not None else erg
        if not admin and _ap_gruppe_lesen(uid)[0]:
            letzter = ap_lauf_ohne_summen(letzter)   # Nachbesserung B (08.10.2026): Eingeschränkte bekommen keine HT-Summen
        # Seit dem Lauf gelesen (09.10.2026): „Balance fehlt"-Zeilen mit frischer Balance bekommen balance_gelesen_at — das Frontend nimmt sie
        # aus „Braucht dich" und zeigt „n Konten gelesen ✓ · beim nächsten Nachplanen". Eigener try: fällt es aus, bleibt der Lauf wie bisher.
        try:
            if isinstance(letzter, dict) and not letzter.get("at") and rows:
                letzter = dict(letzter, at=rows[0].get("at"))     # Laufzeit für den Vergleich (Zeit der Zeile, wenn das Ergebnis keine trägt)
            letzter = ap_lauf_gelesen_markieren(letzter)
        except Exception as e:
            print(f"[auto-plan] ⚠️ gelesen-Markierung: {type(e).__name__}: {e}", flush=True)
        # JSON-fest (09.10.2026, Hotfix): _ap_info ist Prozess-Speicher mehrerer Takte — ein set darin machte jeden GET zu HTTP 500
        info = json.loads(json.dumps({k: v for k, v in _ap_info.items() if k != "nachplan_ziel"},   # Merker gehört nicht in die Antwort
                                     default=lambda o: sorted(o) if isinstance(o, (set, frozenset)) else str(o)))
        # Balance von selbst (13.10.2026): heutige Aufträge je Konto, Übersprungene mit Grund — „Braucht dich" zeigt „Bot liest … n/3"
        info["balance_auto"] = json.loads(json.dumps({"tag": _ap_bal_auto.get("tag"), "at": _ap_bal_auto.get("at"), "fehler": _ap_bal_auto.get("fehler"),
                                                      "max_tag": AP_BAL_AUTO_MAX_TAG, "versuche": _ap_bal_auto.get("versuche"),
                                                      "gesendet": _ap_bal_auto.get("gesendet"), "uebersprungen": _ap_bal_auto.get("uebersprungen"),
                                                      # BALANCE SELBST 2 (16.10.2026): Braucht-dich-Text nur „liest von selbst", wo es stimmt
                                                      "aktiv": _ap_bal_auto.get("aktiv"), "ids": _ap_bal_auto.get("ids"), "kandidaten": _ap_bal_auto.get("kandidaten"),
                                                      "nicht": _ap_bal_auto.get("nicht"), "konten": _ap_bal_auto.get("konten"), "takt_s": AP_BAL_AUTO_TAKT_S},
                                                     default=str))
        # Von selbst bestätigen (15.10.2026): Schalter-Stand, heute Bestätigte, Wartende mit Grund — „Zu bestätigen" sagt „der Bot bestätigt"
        info["auto_bestaetigen"] = json.loads(json.dumps({"aktiv": bool(_ap_auto_best.get("aktiv")), "tag": _ap_auto_best.get("tag"),   # Stand des Takts (reg hier ohne regeln)
                                                          "umfang": _ap_auto_best.get("umfang"),   # A1 04.11.2026: "alle" | "cfd" (nur CFD-Challenges) | None
                                                          "at": _ap_auto_best.get("at"), "takt_s": AP_AUTO_BEST_TAKT_S, "fehler": _ap_auto_best.get("fehler"),
                                                          "bestaetigt": _ap_auto_best.get("bestaetigt"), "gewartet": _ap_auto_best.get("gewartet")},
                                                         default=str))
        try:
            nx, art = ap_nachplan_naechster(datetime.now(timezone.utc), _ap_info.get("nachplan_at"), reg.get("zeiten"), _ap_tz(AP_TZ_TAG))
            info.update(nachplan_naechster=nx.isoformat() if nx else None, nachplan_art=art, nachplan_takt_s=AP_NACHPLAN_TAKT_S,
                        nachplan_laeuft=_ap_nachplan_lock.locked())
        except Exception as e:
            print(f"[auto-plan] ⚠️ Countdown: {type(e).__name__}: {e}", flush=True)
        return jsonify({"ok": True, "admin": admin, "aktiv": bool(gr_lauf.get("aktiv")) if gr_lauf else bool(reg.get("aktiv")),
                        "ids": len(gr_lauf["ids"]) if gr_lauf else len(reg.get("user_ids") or []),
                        "im_planer": im_planer or admin, "letzter": letzter,
                        "sicht": "alle" if sicht is None else "eigene" if isinstance(sicht, str) else "gruppe", "info": info})
    body = request.get_json(silent=True) or {}
    if body.get("nachplanen"):
        # „JETZT NEU BERECHNEN" (Finn 09.10.2026): nur Admin (ADMIN_EMAILS, kein Verwalter) — dieselbe Strecke wie der 10-min-Takt
        # (_ap_nachplan_rechnen) für den Planungstag des letzten Nachtlaufs; bestehende Pläne bleiben (nur_konten). Läuft schon → 409.
        # seit 15.10.2026 auch für IDs im Planer (Finn bedient den Admin-Reiter auch aus Marcs/Chris' Login): dieselbe Hürde wie der
        # Admin-Reiter selbst (Option A) — geplant werden ohnehin nur Konten der user_ids
        if not (admin or im_planer):
            return jsonify({"ok": False, "msg": "Nachplanen nur für Admins oder IDs im Trade-Planer"}), 403
        if not reg.get("aktiv"):
            # Not-Aus gilt auch für den Knopf — der Takt prüft aktiv ebenfalls (Prüfer Slave 2, 09.10.2026)
            return jsonify({"ok": False, "msg": "Auto-Planer ist aus"}), 409
        tz = _ap_tz(AP_TZ_TAG)
        heute = datetime.now(timezone.utc).astimezone(tz).strftime("%Y-%m-%d")
        nr = sb_select("auto_plan_lauf", {"select": "tag", "ergebnis->>quelle": "eq.nacht", "order": "at.desc", "limit": "1"}) or []
        ptag = ap_nachplan_planungstag(heute, (nr[0] if nr else {}).get("tag"))
        if not ptag:
            letzt_n = (nr[0] if nr else {}).get("tag")
            return jsonify({"ok": False, "msg": (f"Kein Planungstag — der letzte Nachtlauf plante {letzt_n}, der Tag ist vorbei; "
                                                 "der nächste Nachtlauf plant den nächsten Handelstag") if letzt_n
                            else "Kein Planungstag — es gab noch keinen Nachtlauf; der nächste Nachtlauf plant"}), 409
        if not _ap_nachplan_lock.acquire(blocking=False):
            return jsonify({"ok": False, "msg": "läuft schon — Nachplanen rechnet gerade"}), 409
        try:
            erg, kand = _ap_nachplan_rechnen(ptag, datetime.now(timezone.utc), _ap_info, reg, tz)
        except Exception as e:
            return jsonify({"ok": False, "admin": admin, "msg": f"{type(e).__name__}: {e}"}), 502
        finally:
            _ap_nachplan_lock.release()
        erg = erg or {}
        print(f"[auto-plan] Jetzt neu berechnen (Knopf) {ptag}: {len(erg.get('geplant') or [])} geplant für {len(kand)} Konten", flush=True)
        return jsonify({"ok": True, "admin": admin, "tag": ptag, "kandidaten": len(kand), "geplant": len(erg.get("geplant") or []),
                        "ausgelassen": len(erg.get("ausgelassen") or []), "msg": erg.get("msg")})
    tag = str(body.get("tag") or "").strip() or None
    if tag and not re.match(r"^\d{4}-\d{2}-\d{2}$", tag):
        return jsonify({"ok": False, "msg": "tag = JJJJ-MM-TT"}), 400
    seed = body.get("seed")
    if seed not in (None, "") and not re.match(r"^\d{1,10}$", str(seed)):
        return jsonify({"ok": False, "msg": "seed = Ganzzahl"}), 400
    ids, fehler = ap_ids_modus(body, admin)         # PROBELAUF-ALLE-IDS (07.10.2026): ids="alle" nur Admin, nur trocken
    if fehler:
        return jsonify({"ok": False, "admin": admin, "msg": fehler[0]}), fehler[1]
    try:
        erg = ap_planen(tag, trocken=bool(body.get("trocken")), quelle="hand", seed=seed, sicht_uid=sicht,
                        fingerabdruck=str(body.get("fingerabdruck") or "").strip() or None, ids=ids)
        if not admin and _ap_gruppe_lesen(uid)[0]:
            erg = ap_lauf_ohne_summen(erg)           # Nachbesserung B (08.10.2026)
        return jsonify(dict(erg, admin=admin))
    except Exception as e:
        return jsonify({"ok": False, "admin": admin, "msg": f"{type(e).__name__}: {e}"}), 502


# ══ LIQUIDE MITTEL (09.10.2026, Slave-Terminal 4 — Auftrag Pascal über Finn, Vertrag .claude/master/auftraege/liquide-vertrag.md) ══
# Kunden-Töpfe aus Google Sheets: je Kunde ein Sheet „Transaktion, Betrag EUR, Datum", Zeile 2 Spalte B = Kontostand (Summenformel).
# Das Backend holt den CSV-Export ohne Key (Freigabe „Jeder mit dem Link"), rechnet wie lqParseSheet aus dem Kompass/Lifeplanner und
# schreibt je Sheet und Dubai-Tag eine Zeile in bank_staende. Fehler stehen als Text in `fehler`, nie stumm 0 (kontostand dann null).
# Tabellen nur über diese Routen (RLS ohne Policies, sql/2026-10-09_liquide_mittel.sql); Gate: Voll-Admin (Verwalter/eingeschränkt 403).
LQ_NICHT_FREI = "nicht freigegeben (Link-Freigabe „Jeder mit dem Link“ fehlt)"
LQ_TOLERANZ_EUR = 1.0           # Prüfung grün, wenn |Summe Buchungen − Kontostand| ≤ 1 € (Sheets runden auf ganze Euro)
LQ_TAKT_S = 6 * 3600            # Abruf im Backend alle 6 h (dazu der Knopf „↻ Abrufen")
LQ_ERSTER_ABRUF_S = 180         # nach dem Start einmal nach 3 min (der Stand ist dann ohne Knopfdruck da)
LQ_VERLAUF_TAGE = 120
_lq_lock = threading.Lock()
_lq_info = {"started": False, "letzter": None, "fehler": ""}


def lq_csv(text):
    """REIN RECHNEND: CSV (Google-Export) → Zeilen als Listen; Anführungszeichen, "" und Zeilenumbrüche in Zellen wie lqCsv."""
    import csv
    import io
    return [list(r) for r in csv.reader(io.StringIO(str(text or "")))]


def lq_num(s):
    """REIN RECHNEND: deutsche Zahl („1.234,56", „-235") → float, leer/unlesbar → None (wie lqNum: Punkte weg, Komma = Dezimal)."""
    s = str(s if s is not None else "").strip()
    if not s:
        return None
    try:
        f = float(s.replace(".", "").replace(",", "."))
    except ValueError:
        return None
    return f if f == f and f not in (float("inf"), float("-inf")) else None


def lq_datum(s):
    """REIN RECHNEND: „06.10.2026" / „24.9.2026" / „ 14.09.2026" → 'JJJJ-MM-TT', sonst None."""
    m = re.match(r"^\s*(\d{1,2})\.(\d{1,2})\.(\d{4})\s*$", str(s or ""))
    if not m:
        return None
    try:
        return datetime(int(m.group(3)), int(m.group(2)), int(m.group(1))).strftime("%Y-%m-%d")
    except ValueError:
        return None


def lq_parse_sheet(text):
    """REIN RECHNEND (Vertrag „Abruf/Parse"): CSV-Text eines Kunden-Sheets → {kontostand, einzahlungen, kaeufe, payouts, an_uns,
    letzte_buchung, diff, pruefung_ok, n, fehler}. Zeile 2 Spalte B = Kontostand, ab Zeile 3 Buchungen (Transaktion, Betrag EUR, Datum).
    Betrag > 0 ohne „Payout" = Einzahlung · > 0 mit „Payout" = Payout · < 0 mit „Abhebung"/„an uns" = an uns · sonst < 0 = Kauf/Reset.
    diff = Summe Buchungen − Kontostand, Prüfung grün bei |diff| ≤ LQ_TOLERANZ_EUR. Letzte Buchung = Datum der letzten Buchung in
    Sheet-Reihenfolge (wie lqParseSheet). HTML statt CSV (Google-Login) = nicht freigegeben. Bei Fehler kontostand None, nie 0."""
    leer = {"kontostand": None, "einzahlungen": None, "kaeufe": None, "payouts": None, "an_uns": None, "letzte_buchung": None,
            "diff": None, "pruefung_ok": False, "n": 0}
    t = str(text or "")
    if re.match(r"^\s*<", t) or re.search(r"<html|<!doctype", t[:2000], re.I):
        return dict(leer, fehler=LQ_NICHT_FREI)
    zeilen = lq_csv(t)
    if len(zeilen) < 2:
        return dict(leer, fehler="Sheet leer")
    roh_b2 = zeilen[1][1] if len(zeilen[1]) > 1 else ""
    bal = lq_num(roh_b2)
    if bal is None:
        return dict(leer, fehler=f"Zeile 2 Spalte B (Kontostand) nicht lesbar: {str(roh_b2).strip()[:40] or 'leer'}")
    ein = kauf = pay = uns = summe = 0.0
    n, letzte = 0, None
    for z in zeilen[2:]:
        betrag = lq_num(z[1] if len(z) > 1 else "")
        if betrag is None:
            continue
        text_z = str(z[0] if z else "")
        n += 1
        summe += betrag
        if betrag > 0:
            if re.search(r"payout", text_z, re.I):
                pay += betrag
            else:
                ein += betrag
        elif re.search(r"abhebung|an uns", text_z, re.I):
            uns += betrag
        else:
            kauf += betrag
        d = lq_datum(z[2] if len(z) > 2 else "")
        if d:
            letzte = d
    diff = round(summe - bal, 2)
    return {"kontostand": round(bal, 2), "einzahlungen": round(ein, 2), "kaeufe": round(kauf, 2), "payouts": round(pay, 2),
            "an_uns": round(uns, 2), "letzte_buchung": letzte, "diff": diff, "pruefung_ok": abs(diff) <= LQ_TOLERANZ_EUR, "n": n,
            "fehler": None}


def lq_sheet_id(link):
    """REIN RECHNEND: Sheet-ID aus einem Link (…/d/<ID>/…) oder die nackte ID; sonst None."""
    s = str(link or "").strip()
    m = re.search(r"/d/([A-Za-z0-9_-]{20,})", s)
    if m:
        return m.group(1)
    return s if re.fullmatch(r"[A-Za-z0-9_-]{20,}", s) else None


def _lq_holen(sheet_id):
    """CSV-Export eines Sheets holen und parsen → lq_parse_sheet-Ergebnis (mit fehler bei HTTP-/Netzfehler)."""
    url = f"https://docs.google.com/spreadsheets/d/{sheet_id}/export?format=csv"
    try:
        r = requests.get(url, timeout=(5, 20), allow_redirects=True)
    except requests.exceptions.RequestException as e:
        return dict(lq_parse_sheet(""), fehler=f"Abruf fehlgeschlagen: {type(e).__name__}")
    if r.status_code in (401, 403):
        return dict(lq_parse_sheet(""), fehler=LQ_NICHT_FREI)
    if r.status_code == 404:
        return dict(lq_parse_sheet(""), fehler="Sheet nicht gefunden (HTTP 404) — Link prüfen")
    if r.status_code != 200:
        return dict(lq_parse_sheet(""), fehler=f"HTTP {r.status_code}")
    if "text/html" in str(r.headers.get("content-type") or "").lower():
        return dict(lq_parse_sheet(""), fehler=LQ_NICHT_FREI)
    r.encoding = "utf-8"
    return lq_parse_sheet(r.text)


def _lq_tag():
    return datetime.now(timezone.utc).astimezone(_ap_tz("Asia/Dubai")).strftime("%Y-%m-%d")


def _lq_sheet_abrufen(r):
    """Ein Sheet holen und seine Zeile (Sheet + Dubai-Tag) in bank_staende schreiben (Upsert)."""
    erg = _lq_holen(r["sheet_id"])
    sb_upsert("bank_staende", {"person_uid": r.get("person_uid"), "sheet_id": r["sheet_id"], "day": _lq_tag(),
                               "kontostand": erg["kontostand"], "einzahlungen": erg["einzahlungen"], "kaeufe": erg["kaeufe"],
                               "payouts": erg["payouts"], "an_uns": erg["an_uns"], "letzte_buchung": erg["letzte_buchung"],
                               "diff": erg["diff"], "fehler": erg["fehler"], "geholt_at": datetime.now(timezone.utc).isoformat()})
    if erg["fehler"]:
        print(f"[liquide] ⚠️ Sheet {str(r['sheet_id'])[:6]}…: {erg['fehler']}", flush=True)


def _lq_abrufen(warten=True):
    """Alle aktiven Sheets jetzt holen (_lq_sheet_abrufen je Sheet). Ein Lauf auf einmal (_lq_lock). warten=False (Knopf „↻ Abrufen",
    Master 09.10.2026: die Railway-Threads sind knapp — ein Knopf-Abruf während des 6-h-Laufs hätte bis ~75 s am Lock gewartet):
    läuft schon einer → sofort None, der Aufrufer antwortet mit dem letzten Stand und abruf_laeuft. → Anzahl Sheets oder None"""
    if not _lq_lock.acquire(blocking=warten):
        return None
    try:
        rows = _sb_all("kunden_sheets", {"select": "id,person_uid,sheet_id,aktiv", "aktiv": "eq.true"})
        for r in rows:
            _lq_sheet_abrufen(r)
        _lq_info["letzter"] = datetime.now(timezone.utc).isoformat()
        return len(rows)
    finally:
        _lq_lock.release()


def _lq_fx():
    return fx_aus_zeilen(_sb_all("user_settings", {"select": "user_id,value", "key": "eq.fx_usd_eur"}), _fx_admin_uids())   # wie _admin_basis (03.11.2026 USD→EUR LIVE)


def lq_kunde_flags(nutzer, zeilen, admin_mails):
    """REIN RECHNEND: effektives Kunden-Flag je Person. nutzer = [(user_id, email)], zeilen = liq_personen. Fehlt die Zeile:
    Kunde = True, außer Admins (ADMIN_EMAILS: Finn, Pascal) = False."""
    gesetzt = {str(z.get("user_id")): bool(z.get("ist_kunde")) for z in zeilen or ()}
    return {uid: gesetzt.get(uid, str(mail or "").strip().lower() not in admin_mails) for uid, mail in nutzer}


def lq_antwort(sheets, staende, nutzer, personen, pending, fx, admin_mails, aus=frozenset()):
    """REIN RECHNEND: Antwort von GET /admin/liquide (Vertrag) aus den gelesenen Zeilen. staende = bank_staende (alle Tage, beliebige
    Reihenfolge); je Sheet gilt der jüngste Tag. summe_kunden_eur und verlauf_bank zählen nur aktive Sheets mit Kontostand.
    Ausgeblendete Personen (aus, ADMIN_EXCLUDE_EMAILS — Emin) kommen gar nicht erst vor: weder Sheet noch Summe, pending oder Flag."""
    sheets = [sh for sh in sheets or () if str(sh.get("person_uid")) not in aus]
    juengst = {}
    for s in staende or ():
        k = str(s.get("sheet_id"))
        if k not in juengst or str(s.get("day")) > str(juengst[k].get("day")):
            juengst[k] = s
    out_sheets, summe = [], 0.0
    for sh in sorted(sheets or (), key=lambda x: (str(x.get("person_name") or "").lower(), str(x.get("sheet_id")))):
        st = juengst.get(str(sh.get("sheet_id")))
        stand = None
        if st:
            d = st.get("diff")
            stand = {"day": st.get("day"), "kontostand": _wd_num(st.get("kontostand")) if st.get("kontostand") is not None else None,
                     "einzahlungen": _wd_num(st.get("einzahlungen")), "kaeufe": _wd_num(st.get("kaeufe")), "payouts": _wd_num(st.get("payouts")),
                     "an_uns": _wd_num(st.get("an_uns")), "letzte_buchung": st.get("letzte_buchung"),
                     "diff": float(d) if d is not None else None,
                     "pruefung_ok": (not st.get("fehler")) and d is not None and abs(float(d)) <= LQ_TOLERANZ_EUR,
                     "fehler": st.get("fehler"), "geholt_at": st.get("geholt_at")}
            if sh.get("aktiv") and stand["kontostand"] is not None:
                summe += float(stand["kontostand"])
        out_sheets.append({"id": sh.get("id"), "person_uid": sh.get("person_uid"), "person_name": sh.get("person_name"),
                           "sheet_id": sh.get("sheet_id"), "aktiv": bool(sh.get("aktiv")), "stand": stand})
    aktive = {str(sh.get("sheet_id")) for sh in sheets or () if sh.get("aktiv")}
    je_tag = {}
    for s in staende or ():
        if str(s.get("sheet_id")) in aktive and s.get("kontostand") is not None:
            je_tag[str(s.get("day"))] = je_tag.get(str(s.get("day")), 0.0) + float(s["kontostand"])
    verlauf = [{"day": d, "summe": round(v, 2)} for d, v in sorted(je_tag.items())]
    pend = []
    for p in pending or ():
        uid = str(p.get("user_id"))
        if uid in aus:
            continue
        try:
            betrag = float(p.get("amount") or 0)
        except (TypeError, ValueError):
            continue
        ccy = str(p.get("currency") or "EUR").upper()
        pend.append({"user_id": uid, "betrag_eur": round(betrag * (fx if ccy == "USD" else 1.0), 2), "betrag": round(betrag, 2),
                     "waehrung": ccy, "account_name": p.get("account_name") or "", "account_firm": p.get("account_firm") or "",
                     "liegt_bei": p.get("liegt_bei") or "", "requested_at": p.get("requested_at") or ""})
    pend.sort(key=lambda x: x["requested_at"])
    kunde = lq_kunde_flags([(u, m) for u, m in nutzer if u not in aus], personen, admin_mails)
    return {"ok": True, "sheets": out_sheets, "summe_kunden_eur": round(summe, 2), "verlauf_bank": verlauf, "kunde": kunde,
            "pending": pend, "fx_usd_eur": fx, "generated": datetime.now(timezone.utc).isoformat()}


def _lq_antwort_laden():
    seit = (datetime.now(timezone.utc).astimezone(_ap_tz("Asia/Dubai")).date().toordinal() - LQ_VERLAUF_TAGE)
    seit_iso = datetime.fromordinal(seit).strftime("%Y-%m-%d")
    sheets = _sb_all("kunden_sheets", {"select": "id,person_uid,person_name,sheet_id,aktiv", "order": "person_name.asc"})
    staende = _sb_all("bank_staende", {"select": "sheet_id,day,kontostand,einzahlungen,kaeufe,payouts,an_uns,letzte_buchung,diff,fehler,geholt_at",
                                       "day": f"gte.{seit_iso}", "order": "sheet_id.asc,day.asc"})
    # order PFLICHT (16.10.2026, gleicher Fund wie die Sperr-Matrix): _sb_all sortiert sonst nach id — bank_staende und liq_personen haben
    # keine id-Spalte, PostgREST antwortet 400 (mit order=id.asc gegen das echte PostgREST geprüft)
    personen = _sb_all("liq_personen", {"select": "user_id,ist_kunde", "order": "user_id.asc"})
    nutzer, aus = [], set()
    # UNT5 (05.11.2026): nur Personen aus dem Unternehmen des Logins (Liquide ist HT-Voll-Admins vorbehalten → HT) — vorher nur ADMIN_EXCLUDE
    # (Emin selbst), Emins Mitglieder standen mit Kunden-Flag, offenen Payouts und Sheets in HTs Liquide. Gruppen nicht lesbar → nur der Login.
    gehoert = unt_sicht_login(request.environ.get("prophos.admin_uid"))
    for u in (_auth_liste_anfrage().json() or {}).get("users", []):
        mail = str(u.get("email") or "").strip().lower()
        if mail in ADMIN_EXCLUDE_EMAILS or not gehoert(u.get("id")):
            aus.add(str(u.get("id")))
        nutzer.append((str(u.get("id")), mail))
    try:
        pending = _sb_all("pending_payouts", {"select": "user_id,amount,currency,liegt_bei,requested_at,account_name,account_firm",
                                              "status": "eq.pending"})
    except Exception as e:
        print(f"[liquide] ⚠️ pending_payouts: {type(e).__name__}: {e}", flush=True)   # Übersicht trotzdem, hörbar
        pending = []
    # UNT5 (Prüfung): zusätzlich direkt erlauben statt nur sperren — fällt die Nutzerliste aus (aus leer), bleibt Fremdes trotzdem draußen.
    # Sheets ohne person_uid pflegt HT selbst (wie bisher sichtbar).
    sheets = [sh for sh in sheets or () if not sh.get("person_uid") or gehoert(sh.get("person_uid"))]
    pending = [p for p in pending or () if gehoert(p.get("user_id"))]
    return lq_antwort(sheets, staende, nutzer, personen, pending, _lq_fx(), ADMIN_EMAILS, frozenset(aus))


def _lq_gate():
    """Gate wie /admin/overview + Rechnungen (_admin_auth: eingeloggt, ADMIN_EMAILS), dazu NUR Voll-Admins: ein eingeschränkter Login
    (Verwalter einer Gruppe, „nur eigene") bekommt 403 — Kundengeld ist HT-weit."""
    _mail, err = _admin_auth()
    if err:
        return err
    try:
        sicht, _verw = admin_sicht_lesen(request.environ.get("prophos.admin_uid"))
    except Exception:
        return jsonify({"error": "Admin-Zugang nicht prüfbar"}), 502
    if sicht is not None:
        return jsonify({"error": "Nur für Voll-Admins"}), 403
    return None


def _lq_json_antwort():
    try:
        # abruf_laeuft (Master 09.10.2026): ein Abruf (Takt oder Knopf) läuft gerade — das Frontend zeigt „Abruf läuft …"
        return jsonify(dict(_lq_antwort_laden(), abruf_laeuft=_lq_lock.locked()))
    except Exception as e:
        print(f"[liquide] ⚠️ Antwort: {type(e).__name__}: {e}", flush=True)
        return jsonify({"ok": False, "error": f"{type(e).__name__}: {e}"}), 502


