@app.route("/admin/liquide/sheet", methods=["POST", "OPTIONS"])
def admin_liquide_sheet():
    if request.method == "OPTIONS":
        return "", 200
    err = _lq_gate()
    if err:
        return err
    body = request.get_json(silent=True) or {}
